            public int opponent_rounds_won;
            public int player_points;
            public int opponent_points;
            public bool won;
            public bool is_ranked;
            public string ended_at;
            public string cards_display; // Comma-separated card names for display
            public string opp_cards_display; // Opponent's cards
            public string series_id; // For grouping matches into BO3 series
            public string series_score; // e.g. "2-0", "1-1"
            public float series_rating_change; // Elo change for completed series
            public int xp_gained; // XP earned for this match
            public int gold_gained; // Gold earned on this specific match (from XP crossings)
            public int series_gold_gained; // Gold earned from the series this match is part of (only set on the last-match-of-series row)
            // v1.25 average FPS. 0 = no data (row predates v1.25 OR opponent didn't have the mod).
            public int player_fps_avg;
            public int opponent_fps_avg;
            // v1.30 item 4 — per-game combat stats, viewer-relative (0 = no data:
            // row predates migration 111 or that side had no mod telemetry).
            public int player_bullets_fired, player_bullets_hit;
            public int player_blocks_activated, player_blocks_successful;
            public int player_keys_pressed;
            public float player_active_seconds;
            public int opp_bullets_fired, opp_bullets_hit;
            public int opp_blocks_activated, opp_blocks_successful;
            public int opp_keys_pressed;
            public float opp_active_seconds;
            // July 21 item 2 — viewer-relative fps timelines for the hover chart.
            public string player_fps_timeline, opp_fps_timeline;
            // July 22 item 3 — latency: averages for the row tag + timelines for the hover chart.
            public int player_ping_avg, opponent_ping_avg;
            public string player_ping_timeline, opp_ping_timeline;
            // July 22 item 1 — viewer-relative cumulative pair timelines
            // ("fired:hit,..." / "dmgTaken:blocksSucc,...") + per-point second
            // stamps (no orientation) for the new hover graphs.
            public string player_hit_timeline, opp_hit_timeline;
            public string player_block_timeline, opp_block_timeline;
            public string point_times;
            // Cumulative scoring timeline "myTotal:oppTotal,..." (viewer-relative).
            public string point_timeline;
            // Bug batch item 4 — total game length in seconds (0 = no data).
            public int duration_seconds;
            // Aug 6 item 4 — viewer-relative damage + death telemetry (server
            // migration 191). Server names verified against main.py:5208-5217
            // and schemas.py MatchHistoryEntry. NOTE the wire naming differs by
            // DIRECTION: the client UPLOADS "local_"/"opp_" prefixes and
            // DOWNLOADS "player_"/"opp_". Do not assume symmetry (#152).
            //
            // damage is `int | None` server-side: null on every row recorded
            // before the expanded-telemetry clients. RECORD_NONE = NOT RECORDED
            // (render a dash), 0 = a real game where this side dealt no damage
            // (#257). The timelines are CUMULATIVE ints; per-interval DPS needs
            // consecutive differences (see NativeUI.CumulativeToDps).
            // Initialised to RECORD_NONE, not left at C#'s 0: both current
            // parsers set them explicitly, but 0 is a MEANINGFUL value here, so
            // a future third construction site that forgets would otherwise
            // report "dealt no damage" instead of "not recorded".
            public int player_damage_dealt = RECORD_NONE, opp_damage_dealt = RECORD_NONE;
            public string player_damage_timeline, opp_damage_timeline;
            public int player_deaths = RECORD_NONE, player_deaths_boundary = RECORD_NONE, player_deaths_own_bullet = RECORD_NONE;
            public int opp_deaths = RECORD_NONE, opp_deaths_boundary = RECORD_NONE, opp_deaths_own_bullet = RECORD_NONE;
            // Aug 12 item 1 — end-of-game BUILD (the 22-field TabStatsOverlay
            // wire string), viewer-relative like every field above it. Server
            // sends JSON null for every row without one (pre-migration-216, a
            // client that predates capture, or a value its regex rejected), and
            // the parser leaves that as "" — so EMPTY means "no build to show".
            // Render it by handing the raw string to
            // TabStatsOverlay.DecodeBuildStats: an empty decode result means the
            // same thing, and positional labelling must never be re-derived here
            // (a version this client does not know decodes to nothing on
            // purpose).
            public string player_end_stats, opp_end_stats;
        }

