        // Cached data
        public static List<MatchHistoryEntry> CachedMatchHistory { get; private set; }
        public static Dictionary<string, AchievementData> CachedAchievements { get; private set; }

        /// <summary>Achievement keys already announced to the player this
        /// session. An achievement unlocks exactly once, so one toast per key
        /// is always correct — and this is the only thing that closes the
        /// client/server announce race. The cache pre-mark in UnlockAchievement
        /// stops the post-report refresh from re-toasting a key the client
        /// already announced, but not the reverse order: the refresh fires 3s
        /// after the report while an unlock POST can take longer than that to
        /// answer, so the refresh diff can toast the key as server-granted and
        /// the unlock callback then toasts the same key a second time. Both
        /// announce sites claim through here.</summary>
        private static readonly HashSet<string> _announcedAchievements =
            new HashSet<string>(StringComparer.Ordinal);

        // ── Initialization ────────────────────────────────────

        /// <summary>True when the TLS endpoint was unreachable this session and we
        /// fell back to the legacy plaintext one. Session-scoped on purpose — never
        /// persisted — so the client re-probes TLS every launch and self-heals the
        /// moment the network or trust store is fixed.</summary>
        public static bool UsingLegacyFallback { get; private set; }

        public static void Initialize(string url)
        {
            baseUrl = url.TrimEnd('/');
            Plugin.Log.LogInfo($"API client initialized: {baseUrl}");
            // The HTTPS migration rewrites the config to the TLS endpoint and
            // Config.Bind never revisits a written value, so a player for whom
            // :8444 does not work (port-filtering network, TLS-intercepting
            // proxy, stale root store) would be stuck there permanently — and
            // every channel that could tell them why, or ship them a fix, rides
            // this same baseUrl: DoCheckModVersion wraps its whole body in
            // `if (Success)` with no else, so LatestModVersion stays null, the
            // F5 Update button stays hidden, and the auto-updater never fires.
            // Probe first and fall back for the session if TLS can't connect.
            if (string.Equals(baseUrl, Plugin.DefaultApiUrl.TrimEnd('/'), StringComparison.OrdinalIgnoreCase))
                Plugin.Instance.StartCoroutine(ProbeEndpointThenStart());
            else
                CheckModVersion();
            // Start the tournament heartbeat loop. This runs forever and fires
            // ready-up heartbeats any time the player has an active tournament
            // match — regardless of which UI tab is open or whether the
            // competitive page is even visible. Needed because sync matches
            // happen in ROUNDS gameplay (outside the F5 menu), and without
            // this the player's ready_at would go stale during their match
            // and the server would auto-forfeit their NEXT match.
            Plugin.Instance.StartCoroutine(TournamentHeartbeatLoop());
            // v1.29: always-on presence ping (mod-clients-online counter).
            Plugin.Instance.StartCoroutine(PresenceLoop());
            // July 22: mint the Steam session ASAP. Enforced actions (toggle
            // ranked, match report, queue join) 401 without one, and the
            // presence loop's first tick is 15s out — too long a window. This
            // fast loop lands a session within ~2-5s of launch, then relaxes.
            Plugin.Instance.StartCoroutine(SteamAuthLoop());
            // Bug #65: replay match reports that failed in an earlier session.
            LoadOutbox();
            // Aug 7 item 1: startup alerts fetch — covers the launch-time
            // window before the presence loop's first tick (15s) and players
            // launching mid-outage whose presence pings may never succeed.
            FetchActiveAlerts();
        }

        // July 22: fast Steam-session establishment at startup (see Initialize).
        private static IEnumerator SteamAuthLoop()
        {
            // Authentication and durable-report recovery must keep moving on
            // paused result/menu screens where Time.timeScale can be zero.
            yield return new WaitForSecondsRealtime(2f);
            while (true)
            {
                try { SteamAuth.MaybeRefresh(); } catch { }
                yield return new WaitForSecondsRealtime(
                    SteamAuth.HasFreshToken ? 30f : 3f);
            }
        }

        // ── Match-report outbox (bug #65) ─────────────────────────────
        // A match report that exhausts its 3 immediate POST attempts is queued here
        // and re-sent every ~60s until it lands, the server permanently rejects it,
        // or the retry budget runs out. Stan lost a casual match to a transient DNS
        // outage ("Cannot resolve destination host" x3 over a few seconds) — the
        // outage outlived the whole retry window, and the report was dropped
        // forever. The queue persists to disk so a report that fails right before
        // quit is re-sent on next launch. Replays are dedup-safe server-side:
        // matches has UNIQUE (photon_room_id, player1_id, player2_id), team_matches
        // has the 5-column equivalent, and room ids are per-game suffixed — a
        // replay of a report that actually landed just errors out and is dropped.
        private class PendingReport { public string url; public string json; public int attempts; public float nextAt; }
        private static readonly List<PendingReport> _pendingReports = new List<PendingReport>();
        private static bool _outboxLoopStarted;
        private const int OUTBOX_MAX_ATTEMPTS = 20;
        private const float OUTBOX_RETRY_SECONDS = 60f;

        private static string OutboxPath
        {
            get { return Path.Combine(BepInEx.Paths.ConfigPath, "CompetitiveRounds.pending-reports.jsonl"); }
        }

        public static void EnqueueFailedReport(string url, string json)
        {
            try
            {
                if (string.IsNullOrEmpty(url) || string.IsNullOrEmpty(json)) return;
                // A lost response can reach more than one retry callback. Keep
                // one durable copy of an idempotent payload.
                foreach (var pending in _pendingReports)
                    if (pending.url == url && pending.json == json)
                        return;
                float initialDelay = IsSilentOutboxUrl(url) ? 120f : 30f;
                _pendingReports.Add(new PendingReport
                {
                    url = url,
                    json = json,
                    attempts = 0,
                    nextAt = Time.realtimeSinceStartup + initialDelay,
                });
                PersistOutbox();
                EnsureOutboxLoop();
                if (!IsSilentOutboxUrl(url))
                {
                    Plugin.Log.LogWarning($"[OUTBOX] report queued for retry ({_pendingReports.Count} pending)");
                    CompetitiveUI.ShowNotification("Couldn't record the match — retrying in the background", new Color(1f, 0.75f, 0.3f), 4f);
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[OUTBOX] enqueue failed: {ex.Message}"); }
        }

        private static bool IsSilentOutboxUrl(string url)
        {
            return !string.IsNullOrEmpty(url)
                && url.EndsWith("/api/v1/matches/macro-evidence", StringComparison.Ordinal);
        }

        private static void RemovePendingReport(string url, string json)
        {
            bool removed = false;
            for (int i = _pendingReports.Count - 1; i >= 0; i--)
            {
                var pending = _pendingReports[i];
                if (pending.url != url || pending.json != json) continue;
                _pendingReports.RemoveAt(i);
                removed = true;
            }
            if (removed) PersistOutbox();
        }

        private static void PersistOutbox()
        {
            try
            {
                var sb = new StringBuilder();
                foreach (var p in _pendingReports)
                    sb.Append(p.url).Append('\t').Append(p.json.Replace("\n", " ").Replace("\r", " ")).Append('\n');
                if (sb.Length == 0) { if (File.Exists(OutboxPath)) File.Delete(OutboxPath); }
                else File.WriteAllText(OutboxPath, sb.ToString());
            }
            catch { /* disk persistence is best-effort; in-memory queue still works */ }
        }

        private static void LoadOutbox()
        {
            try
            {
                if (!File.Exists(OutboxPath)) return;
                foreach (var line in File.ReadAllLines(OutboxPath))
                {
                    int tab = line.IndexOf('\t');
                    if (tab <= 0 || tab >= line.Length - 1) continue;
                    _pendingReports.Add(new PendingReport
                    {
                        url = line.Substring(0, tab),
                        json = line.Substring(tab + 1),
                        attempts = 0,
                        nextAt = Time.realtimeSinceStartup + 20f,
                    });
                }
                if (_pendingReports.Count > 0)
                {
                    Plugin.Log.LogInfo($"[OUTBOX] loaded {_pendingReports.Count} unsent report(s) from previous session");
                    EnsureOutboxLoop();
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[OUTBOX] load failed: {ex.Message}"); }
        }

        private static void EnsureOutboxLoop()
        {
            if (_outboxLoopStarted || Plugin.Instance == null) return;
            _outboxLoopStarted = true;
            Plugin.Instance.StartCoroutine(OutboxLoop());
        }

        private static IEnumerator OutboxLoop()
        {
            while (true)
            {
                yield return new WaitForSecondsRealtime(10f);
                if (_pendingReports.Count == 0) continue;
                float now = Time.realtimeSinceStartup;
                bool changed = false;
                for (int i = _pendingReports.Count - 1; i >= 0; i--)
                {
                    var p = _pendingReports[i];
                    if (p.nextAt > now) continue;
                    p.attempts++;
                    // Linear-ish backoff, capped at 4x the base interval.
                    p.nextAt = now + OUTBOX_RETRY_SECONDS * Math.Min(4, p.attempts);
                    bool done = false, ok = false; string resp = null;
                    yield return PostRequest(p.url, p.json, (s, r) => { done = true; ok = s; resp = r; });
                    while (!done) yield return null;
                    if (ok)
                    {
                        Plugin.Log.LogInfo($"[OUTBOX] queued report delivered on retry {p.attempts}");
                        if (!IsSilentOutboxUrl(p.url))
                            CompetitiveUI.ShowNotification("Match recorded", new Color(0.4f, 1f, 0.5f), 4f);
                        _pendingReports.RemoveAt(i);
                        changed = true;
                    }
                    else
                    {
                        // 4xx = the server understood and refused (bad signature, dup,
                        // validation) — retrying can never succeed. 5xx/transport keep
                        // retrying until the budget runs out.
                        // Macro evidence can legitimately race the elected
                        // reporter's match insert. Its 409 becomes retryable;
                        // exact room correlation remains valid after a restart.
                        bool retryableMacroResponse =
                            IsSilentOutboxUrl(p.url)
                            && resp != null
                            && (resp.Contains("401")
                                || resp.Contains("409")
                                || resp.Contains("429"));
                        // "Any 4xx is permanent" threw away three RECOVERABLE
                        // classes (found auditing the July 30 lost-game
                        // incidents). The rule was written for 403 bad-signature
                        // and duplicate-key, where retrying genuinely cannot
                        // help, but it also deleted:
                        //   429 — we were merely throttled; the game is fine and
                        //         the next attempt would have worked.
                        //   401 — the Steam session lapsed; SteamAuth.MaybeRefresh
                        //         mints a new ticket on its own 60s loop, so the
                        //         retry after it lands succeeds.
                        // Both are now retryable for EVERY outbox url, not just
                        // the silent macro-evidence ones. 409 stays permanent:
                        // the server state really has moved on, retrying cannot
                        // change it, and the server now quarantines that report
                        // for admin recovery instead of dropping it. The attempts
                        // cap still bounds anything that never succeeds.
                        bool retryableTransient =
                            resp != null
                            && (resp.Contains("HTTP 429") || resp.Contains("HTTP/1.1 429")
                                || resp.Contains("HTTP 401") || resp.Contains("HTTP/1.1 401"));
                        bool permanent =
                            !retryableMacroResponse
                            && !retryableTransient
                            && resp != null
                            && (resp.StartsWith("HTTP 4", StringComparison.Ordinal)
                                || resp.Contains("HTTP/1.1 4")
                                || resp.Contains("duplicate key"));
                        if (permanent || p.attempts >= OUTBOX_MAX_ATTEMPTS)
                        {
                            Plugin.Log.LogWarning($"[OUTBOX] dropping report after {p.attempts} attempt(s): {Trunc(resp ?? "(no response)", 160)}");
                            _pendingReports.RemoveAt(i);
                            changed = true;
                        }
                    }
                }
                if (changed || _pendingReports.Count > 0) PersistOutbox();
            }
        }

        private static string Trunc(string s, int n) => string.IsNullOrEmpty(s) || s.Length <= n ? s : s.Substring(0, n) + "..";

        // Per-match dispatch memo. Mirrors the per-tab one in NativeUI but
        // lives at plugin scope so the loop doesn't re-fire SetPendingRoom
        // every 20 seconds for the same match. Reset implicitly when the
        // match transitions out of "ready" (server stops returning it).
        private static readonly HashSet<string> _heartbeatDispatchedMatches = new HashSet<string>();
        // match_id -> unscaled time of the last auto-connect dispatch (drives the
        // 60s re-arm above).
        private static readonly Dictionary<string, float> _heartbeatDispatchTime = new Dictionary<string, float>();

        // Ticks since the heartbeat loop last refreshed the CURRENT-tournament
        // snapshot. The pre-start banner (item 3) needs scheduled_start_ts +
        // my_signup_id fresh even when the Tournaments tab has never been
        // opened this session — refresh it every 3rd tick (~60s).
        private static int _hbTournamentCurrentTick;

        private static IEnumerator TournamentHeartbeatLoop()
        {
            // Small initial delay so the mod finishes initializing before the
            // first call tries to resolve the local Steam ID.
            yield return new WaitForSeconds(10f);
            while (true)
            {
                yield return new WaitForSeconds(20f);
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") continue;
                // §2c identity fence (Codex mod-r1 F4): the broadcast service
                // account never heartbeats tournament readiness and never
                // auto-dispatches into a fighter room — a stale/misgranted
                // ready row would otherwise stage a room join that yanks the
                // seat out of its watched game and logs raw room+region.
                // Direct identity check (not the logging fence helper): this
                // fires every 20s and would spam the log. SetPendingRoom's
                // own discard is the structural backstop.
                if (BroadcastMode.IsBroadcastIdentity) continue;
                if (++_hbTournamentCurrentTick >= 3)
                {
                    _hbTournamentCurrentTick = 0;
                    try { FetchTournamentCurrent(sid); } catch { }
                }
                // Pull fresh active-match state. FetchMyActiveTournamentMatches
                // has its own 20s throttle so back-to-back calls are safe.
                FetchMyActiveTournamentMatches(sid);
                if (CachedMyActiveTournamentMatches == null) continue;
                // Heartbeat each tournament once per loop (dedupe by tournament_id
                // in case the player has multiple active matches somehow).
                var seen = new HashSet<string>();
                foreach (var m in CachedMyActiveTournamentMatches)
                {
                    if (string.IsNullOrEmpty(m.tournament_id) || seen.Contains(m.tournament_id)) continue;
                    seen.Add(m.tournament_id);
                    TournamentReady(m.tournament_id, sid);
                    yield return new WaitForSeconds(0.2f); // space the requests

                    // Tab-independent auto-connect dispatch. The Tournament
                    // tab's RefreshTournaments has the same logic, but it
                    // ONLY runs when the user is on tab 7 with the F5 menu
                    // open — meanwhile sync tournament matches need to
                    // start from in-game (F5 closed). Without this branch
                    // the auto-connect silently fails and the player
                    // forfeits the 5-min window.
                    bool isSyncReady = m.kind == "sync"
                        && m.status == "ready"
                        && m.my_ready
                        && m.opp_ready
                        && !string.IsNullOrEmpty(m.photon_room_name)
                        && !string.IsNullOrEmpty(m.match_id);
                    if (isSyncReady && !_heartbeatDispatchedMatches.Contains(m.match_id))
                    {
                        if (Plugin.PendingRankedRoom != m.photon_room_name)
                        {
                            _heartbeatDispatchedMatches.Add(m.match_id);
                            _heartbeatDispatchTime[m.match_id] = Time.unscaledTime;
                            Plugin.SetPendingRoom(m.photon_room_name, m.photon_region);
                            Plugin.Log.LogInfo($"[TOURNAMENT-HB] Dispatch from heartbeat loop: room={m.photon_room_name} region={m.photon_region ?? "default"} match={m.match_id}");
                        }
                    }
                    // Re-dispatch path (item 3 hardening): if we dispatched 60s+
                    // ago but STILL aren't in the match room (join failed, or the
                    // lonely-room watchdog bounced us back to the menu when the
                    // opponent was late), clear the memo so the block above fires
                    // again next tick. Without this, one failed join burned the
                    // match's only auto-connect for the whole session.
                    else if (isSyncReady && _heartbeatDispatchedMatches.Contains(m.match_id))
                    {
                        float at;
                        bool oldEnough = _heartbeatDispatchTime.TryGetValue(m.match_id, out at)
                            ? (Time.unscaledTime - at) > 60f : true;
                        bool inTargetRoom = false;
                        try
                        {
                            inTargetRoom = PhotonNetwork.InRoom
                                && PhotonNetwork.CurrentRoom != null
                                && PhotonNetwork.CurrentRoom.Name == m.photon_room_name;
                        }
                        catch { }
                        if (oldEnough && !inTargetRoom && Plugin.PendingRankedRoom != m.photon_room_name)
                        {
                            _heartbeatDispatchedMatches.Remove(m.match_id);
                            Plugin.Log.LogInfo($"[TOURNAMENT-HB] Not in match room 60s after dispatch — re-arming auto-connect for {m.match_id}");
                        }
                    }
                }
                // Drop any memo entries whose matches no longer appear —
                // lets a re-ready (e.g., player relaunched the game) fire
                // SetPendingRoom again.
                if (CachedMyActiveTournamentMatches.Count == 0)
                {
                    _heartbeatDispatchedMatches.Clear();
                }
                else
                {
                    var stillActive = new HashSet<string>();
                    foreach (var m in CachedMyActiveTournamentMatches)
                        if (!string.IsNullOrEmpty(m.match_id)) stillActive.Add(m.match_id);
                    _heartbeatDispatchedMatches.RemoveWhere(id => !stillActive.Contains(id));
                }
            }
        }

        /// <summary>Probe the TLS endpoint before committing to it for the session.
        /// Falls back to the legacy plaintext endpoint ONLY on a transport-level
        /// failure — never on an HTTP status, because any 4xx/5xx proves the port
        /// and the TLS handshake both worked and the problem is elsewhere.
        /// Deliberately does NOT write to config: this must re-evaluate every launch.
        /// DELETE THIS along with Plugin.LegacyApiUrl in the same release that drops
        /// the plaintext port-forward, or a broken TLS path is forgiven forever.</summary>
        private static IEnumerator ProbeEndpointThenStart()
        {
            const int attempts = 2;
            bool reachable = false;
            for (int i = 0; i < attempts && !reachable; i++)
            {
                using (var probe = UnityWebRequest.Get($"{baseUrl}/api/v1/mod-version"))
                {
                    probe.timeout = 8;
                    StampVersionHeader(probe);
                    yield return probe.SendWebRequest();
                    // "Reachable" must mean USABLE, not merely "something answered".
                    // An earlier version accepted anything that wasn't a
                    // ConnectionError, on the reasoning that an HTTP status proves
                    // the port and TLS handshake worked. True — but useless to the
                    // player: nginx up with the api container down returns 502, and
                    // a captive portal or TLS-intercepting middlebox returns an
                    // HTML 200. Both would pin the client to an endpoint it cannot
                    // actually use, and because every recovery channel rides this
                    // same baseUrl there would be no way back. Require a parseable
                    // mod-version payload instead.
                    string body = probe.result == UnityWebRequest.Result.Success
                        ? (probe.downloadHandler?.text ?? "") : "";
                    if (!string.IsNullOrEmpty(ExtractJsonString(body, "version")))
                        reachable = true;
                    else
                        Plugin.Log.LogWarning(
                            $"[API] TLS endpoint probe {i + 1}/{attempts} unusable: " +
                            $"result={probe.result} code={probe.responseCode} err={probe.error}");
                }
            }

            if (!reachable)
            {
                baseUrl = Plugin.LegacyApiUrl.TrimEnd('/');
                UsingLegacyFallback = true;
                Plugin.Log.LogWarning(
                    $"[API] {Plugin.DefaultApiUrl} unreachable — falling back to {baseUrl} for this session. " +
                    "Config is left untouched, so TLS is retried on next launch.");
                // Chat computes its wss:// URL once at RunLoop entry, so a socket
                // already looping on the dead TLS host has to be pointed at the
                // fallback explicitly — otherwise chat stays dark all session.
                try { ChatClient.Retarget(baseUrl); } catch (Exception ex) { Plugin.Log.LogWarning($"[API] chat retarget failed: {ex.Message}"); }
            }
            CheckModVersion();
        }

        public static void CheckModVersion()
        {
            Plugin.Instance.StartCoroutine(DoCheckModVersion());
        }

        private static IEnumerator DoCheckModVersion()
        {
            var req = UnityWebRequest.Get($"{baseUrl}/api/v1/mod-version");
            yield return req.SendWebRequest();
            if (req.result == UnityWebRequest.Result.Success)
            {
                string ver = ExtractJsonString(req.downloadHandler.text, "version");
                string minVer = ExtractJsonString(req.downloadHandler.text, "min_version");
                if (!string.IsNullOrEmpty(ver))
                {
                    LatestModVersion = ver;
                    if (ver != Plugin.ModVersion)
                        Plugin.Log.LogWarning($"[VERSION] Update available: v{Plugin.ModVersion} → v{ver}");
                    else
                        Plugin.Log.LogInfo($"[VERSION] Mod is up to date (v{ver})");
                }
                if (!string.IsNullOrEmpty(minVer))
                {
                    MinModVersion = minVer;
                    if (CompareVersion(Plugin.ModVersion, minVer) < 0)
                    {
                        ForceUpdateRequired = true;
                        Plugin.Log.LogWarning($"[VERSION] Mod is BELOW server minimum (v{Plugin.ModVersion} < v{minVer}) — update required");
                    }
                }
                // Auto-fire update on launch if behind. The Update method is no-op
                // when running the Thunderstore build (it surfaces a notification only).
                // NOT on the broadcast seat: that binary is installed by the build
                // pipeline (CopyToPlugins), and the updater's wait-for-exit swap
                // races the VM bot's ~20s stale-lease relaunch — the game quits
                // for the swap, the bot relaunches it before the copy window
                // opens, the still-old build re-arms the updater, and the seat
                // loops quit/relaunch (observed all night Aug 18 during the
                // v1.39.0 release window). The F5 Update button stays available.
                if (!string.IsNullOrEmpty(LatestModVersion) && CompareVersion(Plugin.ModVersion, LatestModVersion) < 0
                    && !IsUpdating && !UpdateReady
                    && !BroadcastMode.IsBroadcastIdentity)
                {
                    Plugin.Log.LogInfo("[VERSION] Auto-firing update on launch");
                    StartAutoUpdate();
                }
            }
        }

        /// <summary>Returns -1 / 0 / +1 by dotted-int component comparison. Treats parse failures as 0.</summary>
        private static int CompareVersion(string a, string b)
        {
            if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b)) return 0;
            var ap = a.Split('.'); var bp = b.Split('.');
            int n = Math.Max(ap.Length, bp.Length);
            for (int i = 0; i < n; i++)
            {
                int.TryParse(i < ap.Length ? ap[i] : "0", out int ai);
                int.TryParse(i < bp.Length ? bp[i] : "0", out int bi);
                if (ai != bi) return ai < bi ? -1 : 1;
            }
            return 0;
        }

        // ── Auto-Update ─────────────────────────────────────────

        public static bool IsUpdating { get; private set; } = false;
        public static bool UpdateReady { get; private set; } = false;
        private const string GITHUB_API_LATEST = "https://api.github.com/repos/SidNDeed/SidsCompetitiveRounds/releases/latest";

        public static void StartAutoUpdate()
        {
            if (IsUpdating || UpdateReady) return;
            IsUpdating = true;
            Plugin.Instance.StartCoroutine(DoAutoUpdate());
        }

        /* BUILD-GATE MARKERS. Do not translate these, do not reuse them, do not
         * delete them: they exist ONLY so a packaging script can prove which
         * variant a compiled DLL is, by scanning for a literal that can appear
         * for no other reason.
         *
         * This is the THIRD verification method for this gate. The first
         * scanned for a class name (learning #123) — type names live in the
         * UTF-8 #Strings heap, not the UTF-16 #US literal heap, so it matched
         * nothing in either build and passed vacuously. The second scanned the
         * auto-updater's user-facing notification text (learning #203) — which
         * worked until localization added BOTH of those strings to
         * I18nCatalogues and I18nSourceKeys as translation keys, so they are
         * now compiled unconditionally into EVERY build and can no longer tell
         * the variants apart. A marker that exists solely to be scanned cannot
         * be captured by a future feature the way user-visible text was. */
        internal const string BuildVariantMarker =
#if THUNDERSTORE
            "SCR_BUILD_VARIANT=THUNDERSTORE";
#else
            "SCR_BUILD_VARIANT=STANDALONE";
#endif

        private static IEnumerator DoAutoUpdate()
        {
#if THUNDERSTORE
            Plugin.Log.LogInfo("[UPDATE] Thunderstore build — auto-update disabled, use mod manager");
            CompetitiveUI.ShowNotification("Update available — update through your mod manager", Color.cyan, 6f);
            IsUpdating = false;
            NativeUI.MarkDirty();
            yield break;
#else
            CompetitiveUI.ShowNotification("Downloading update...", Color.cyan, 10f);
            NativeUI.MarkDirty();

            // Step 1: Get latest release info from GitHub
            var apiReq = UnityWebRequest.Get(GITHUB_API_LATEST);
            apiReq.SetRequestHeader("User-Agent", "CompetitiveRounds-AutoUpdate");
            apiReq.timeout = 15;
            yield return apiReq.SendWebRequest();

            if (apiReq.result != UnityWebRequest.Result.Success)
            {
                Plugin.Log.LogWarning($"[UPDATE] GitHub API failed: {apiReq.error}");
                CompetitiveUI.ShowNotification("Update failed — couldn't reach GitHub. Check your connection and try again.", new Color(1f, 0.4f, 0.4f), 5f);
                IsUpdating = false;
                yield break;
            }

            string json = apiReq.downloadHandler.text;

            // Step 2: Find the DLL asset URL
            string dllUrl = null;
            var matches = Regex.Matches(json, @"""browser_download_url""\s*:\s*""([^""]+\.dll)""");
            foreach (Match m in matches)
            {
                if (m.Groups[1].Value.IndexOf("CompetitiveRounds", StringComparison.OrdinalIgnoreCase) >= 0)
                {
                    dllUrl = m.Groups[1].Value;
                    break;
                }
            }
            if (dllUrl == null && matches.Count > 0)
                dllUrl = matches[0].Groups[1].Value;

            // Fallback: try zip
            if (dllUrl == null)
            {
                var zipMatches = Regex.Matches(json, @"""browser_download_url""\s*:\s*""([^""]+\.zip)""");
                if (zipMatches.Count > 0)
                {
                    // Can't easily unzip in Unity — fall back to opening browser
                    Plugin.Log.LogWarning("[UPDATE] No DLL asset found, only zip. Opening browser.");
                    CompetitiveUI.ShowNotification("This release only ships a zip — opening the releases page to update manually", Color.yellow, 5f);
                    Application.OpenURL("https://github.com/SidNDeed/SidsCompetitiveRounds/releases/latest");
                    IsUpdating = false;
                    yield break;
                }
                Plugin.Log.LogWarning("[UPDATE] No downloadable assets found in release");
                CompetitiveUI.ShowNotification("Update failed — that release has no download attached. Update manually from GitHub.", new Color(1f, 0.4f, 0.4f), 5f);
                IsUpdating = false;
                yield break;
            }

            Plugin.Log.LogInfo($"[UPDATE] Downloading: {dllUrl}");

            // Step 3: Download the DLL to temp
            string tempPath = Path.Combine(Path.GetTempPath(), "CompetitiveRounds_update.dll");
            var dlReq = UnityWebRequest.Get(dllUrl);
            dlReq.SetRequestHeader("User-Agent", "CompetitiveRounds-AutoUpdate");
            dlReq.timeout = 30;
            dlReq.downloadHandler = new DownloadHandlerFile(tempPath);
            yield return dlReq.SendWebRequest();

            if (dlReq.result != UnityWebRequest.Result.Success)
            {
                Plugin.Log.LogWarning($"[UPDATE] Download failed: {dlReq.error}");
                CompetitiveUI.ShowNotification("Update failed — the download didn't finish. Try again.", new Color(1f, 0.4f, 0.4f), 5f);
                IsUpdating = false;
                yield break;
            }

            Plugin.Log.LogInfo($"[UPDATE] Downloaded to: {tempPath}");

            // Step 4: Find where the current DLL lives
            string currentDll = "";
            try
            {
                currentDll = System.Reflection.Assembly.GetExecutingAssembly().Location;
            }
            catch { }

            if (string.IsNullOrEmpty(currentDll) || !File.Exists(currentDll))
            {
                // Fallback: use BepInEx.Paths.PluginPath (works for both vanilla and Thunderstore profiles)
                string bepPlugins = "";
                try { bepPlugins = BepInEx.Paths.PluginPath; } catch { }

                if (!string.IsNullOrEmpty(bepPlugins) && Directory.Exists(bepPlugins))
                {
                    // Search subdirectories first (e.g. plugins/CompetitiveRounds/ or plugins/SidNDeed-CompetitiveRounds/)
                    try
                    {
                        foreach (string dir in Directory.GetDirectories(bepPlugins))
                        {
                            string candidate = Path.Combine(dir, "CompetitiveRounds.dll");
                            if (File.Exists(candidate)) { currentDll = candidate; break; }
                        }
                    }
                    catch { }

                    // Also check plugins root
                    if (string.IsNullOrEmpty(currentDll) || !File.Exists(currentDll))
                    {
                        string root = Path.Combine(bepPlugins, "CompetitiveRounds.dll");
                        if (File.Exists(root)) currentDll = root;
                    }
                }

                // Last resort: vanilla hardcoded path
                if (string.IsNullOrEmpty(currentDll) || !File.Exists(currentDll))
                {
                    string vanillaPlugins = Path.Combine(Application.dataPath, "..", "BepInEx", "plugins");
                    string sub = Path.Combine(vanillaPlugins, "CompetitiveRounds", "CompetitiveRounds.dll");
                    string rootV = Path.Combine(vanillaPlugins, "CompetitiveRounds.dll");
                    if (File.Exists(sub)) currentDll = sub;
                    else if (File.Exists(rootV)) currentDll = rootV;
                }
            }

            Plugin.Log.LogInfo($"[UPDATE] Resolved DLL path: {currentDll}");

            if (string.IsNullOrEmpty(currentDll) || !File.Exists(currentDll))
            {
                Plugin.Log.LogWarning("[UPDATE] Could not locate current DLL");
                CompetitiveUI.ShowNotification("Update failed — couldn't find your installed mod file. Update manually from GitHub.", new Color(1f, 0.4f, 0.4f), 5f);
                IsUpdating = false;
                yield break;
            }

            // Step 5: Write batch script that waits for ROUNDS to exit, then swaps the file
            string batPath = Path.Combine(Path.GetTempPath(), "CompetitiveRounds_update.bat");
            string batContent =
                "@echo off\r\n" +
                "echo Waiting for ROUNDS to close...\r\n" +
                ":wait\r\n" +
                "tasklist /FI \"IMAGENAME eq Rounds.exe\" 2>NUL | find /I \"Rounds.exe\" >NUL\r\n" +
                "if %ERRORLEVEL%==0 (\r\n" +
                "    timeout /t 2 /nobreak >NUL\r\n" +
                "    goto wait\r\n" +
                ")\r\n" +
                "timeout /t 1 /nobreak >NUL\r\n" +
                $"copy /Y \"{tempPath}\" \"{currentDll}\"\r\n" +
                "if %ERRORLEVEL%==0 (\r\n" +
                "    echo Update complete!\r\n" +
                ") else (\r\n" +
                "    echo Update failed - could not copy file.\r\n" +
                "    pause\r\n" +
                "    exit /b 1\r\n" +
                ")\r\n" +
                $"del \"{tempPath}\"\r\n" +
                $"del \"%~f0\"\r\n";

            try
            {
                File.WriteAllText(batPath, batContent);
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[UPDATE] Failed to write batch script: {ex.Message}");
                CompetitiveUI.ShowNotification("Update failed — couldn't save the updater. Update manually from GitHub.", new Color(1f, 0.4f, 0.4f), 5f);
                IsUpdating = false;
                yield break;
            }

            // Step 6: Launch the batch script hidden
            try
            {
                var psi = new ProcessStartInfo
                {
                    FileName = batPath,
                    CreateNoWindow = true,
                    UseShellExecute = false,
                    WindowStyle = ProcessWindowStyle.Hidden,
                };
                Process.Start(psi);
                Plugin.Log.LogInfo("[UPDATE] Updater launched — will apply after ROUNDS closes");
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[UPDATE] Failed to launch updater: {ex.Message}");
                CompetitiveUI.ShowNotification("Update failed — couldn't start the updater. Update manually from GitHub.", new Color(1f, 0.4f, 0.4f), 5f);
                IsUpdating = false;
                yield break;
            }

            UpdateReady = true;
            IsUpdating = false;
            CompetitiveUI.ShowNotification("Update downloaded! Close ROUNDS to apply.", new Color(0.3f, 1f, 0.3f), 15f);
            NativeUI.MarkDirty();
#endif
        }

        // ── HMAC Match Signing ────────────────────────────────

        // Obfuscated key (XOR encoded — not plain string in DLL)
        private static readonly byte[] _hkE = {0xE2,0x60,0x7D,0x46,0xD1,0x1D,0xAE,0xD4,0xF3,0x33,0x3C,0x2F,0x47,0xED,0x9A,0x32,0xD7,0x6A,0x0B,0x18,0xA5,0x04,0xE3,0xEC,0xDC,0x50,0x22,0x18,0x15,0xA6,0xE7,0x2E,0xD8,0x46,0x03,0x33,0xA7,0x5A,0xD1,0xD1,0xFD,0x78,0x1C,0x3A,0x02,0x90,0xEF,0x2D};
        private static readonly byte[] _hkX = {0xB2,0x19,0x4F,0x77,0xE6,0x6F,0x96,0xB5,0xBA,0x0A,0x6A,0x5F,0x77,0xDF,0xAE,0x4B};

        private static byte[] GetHmacKeyBytes()
        {
            byte[] result = new byte[_hkE.Length];
            for (int i = 0; i < _hkE.Length; i++)
                result[i] = (byte)(_hkE[i] ^ _hkX[i % _hkX.Length]);
            return result;
        }

        private static string ComputeHmac(string p1SteamId, string p2SteamId,
            int p1Rounds, int p2Rounds, bool isRanked,
            string reporterSteamId, string roomId)
        {
            string message = $"{p1SteamId}:{p2SteamId}:{p1Rounds}:{p2Rounds}:" +
                             $"{(isRanked ? "true" : "false")}:{reporterSteamId}:{roomId ?? ""}";
            try
            {
                using (var hmac = new HMACSHA256(GetHmacKeyBytes()))
                {
                    byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(message));
                    var sb = new StringBuilder(hash.Length * 2);
                    foreach (byte b in hash) sb.Append(b.ToString("x2"));
                    return sb.ToString();
                }
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[HMAC] Computation failed: {ex.Message}");
                return "";
            }
        }

        private static string ComputeHmacHex(string message)
        {
            try
            {
                using (var hmac = new HMACSHA256(GetHmacKeyBytes()))
                {
                    byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(message));
                    var sb = new StringBuilder(hash.Length * 2);
                    foreach (byte b in hash) sb.Append(b.ToString("x2"));
                    return sb.ToString();
                }
            }
            catch { return ""; }
        }

        // Security A2: admin canonicals sign with the SEPARATE admin secret
        // from the local BepInEx config (never compiled into the DLL). Empty
        // secret -> empty signature -> clean server-side 403; the one-time log
        // line tells an admin why their admin menu suddenly stopped working.
        private static bool _adminSecretWarned = false;
        /// <summary>Codex r5/r6/r7 structural fix (learning #319): the ONE
        /// place every admin-signed request passes through. Signing arms this
        /// latch; the next request helper invocation consumes it and refuses
        /// the send on plaintext-to-public transport. This replaces guessing
        /// sensitivity from URL substrings and body tokens — three rounds of
        /// review each found another surface the guessing missed
        /// (/chat/moderate/*, bodies keyed on the TARGET steam_id, ...).
        /// Same-frame coupling is safe because every caller signs immediately
        /// before dispatching, on the single-threaded Unity main thread; a
        /// stale latch can only ever cause ONE extra refusal, never a leak
        /// (fail-closed), and it self-clears on the very next request.</summary>
        private static bool _nextRequestCarriesAdminCredential;
        private static string ComputeAdminHmacHex(string message)
        {
            _nextRequestCarriesAdminCredential = true;
            string secret = null;
            try { secret = Plugin.AdminHmacSecret?.Value; } catch { }
            if (string.IsNullOrWhiteSpace(secret))
            {
                // Only an ADMIN is missing anything here. The T-chat moderation
                // endpoints also accept a Steam session as proof (see the canonical
                // block further down), so a scoped moderator signs an empty string
                // by design and their actions are NOT rejected — telling them
                // otherwise describes a failure that isn't happening. Skipping
                // deliberately does not latch, so an admin whose status resolves
                // after their first signed call still gets the line once.
                if (!_adminSecretWarned && IsAdmin)
                {
                    _adminSecretWarned = true;
                    Plugin.Log.LogWarning(
                        "[ADMIN] AdminSecret is not set in the config — admin actions will be rejected by the server (security A2).");
                }
                return "";
            }
            try
            {
                using (var hmac = new HMACSHA256(Encoding.UTF8.GetBytes(secret.Trim())))
                {
                    byte[] hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(message));
                    var sb = new StringBuilder(hash.Length * 2);
                    foreach (byte b in hash) sb.Append(b.ToString("x2"));
                    return sb.ToString();
                }
            }
            catch { return ""; }
        }

        private static string ComputeSha256Hex(string value)
        {
            try
            {
                using (var sha = SHA256.Create())
                {
                    byte[] hash = sha.ComputeHash(Encoding.UTF8.GetBytes(value ?? ""));
                    var sb = new StringBuilder(hash.Length * 2);
                    foreach (byte b in hash) sb.Append(b.ToString("x2"));
                    return sb.ToString();
                }
            }
            catch { return ""; }
        }

        // ── Betting / Live series ────────────────────────────────
        [Serializable]
        public class ActiveSeriesEntry
        {
            public string series_id;
            public string p1_steam_id, p1_name;
            public int p1_rating, p1_wins;
            public float p1_odds;
            // Aug 9 bet audit find 8: AUTHORITATIVE per-side flags (server
            // computes them from the RAW multiplier its POST checks — never
            // re-derive from the rounded odds above). Default true so a
            // pre-1.39 server's response leaves the buttons as they were.
            public bool p1_bettable = true, p2_bettable = true;
            public string p2_steam_id, p2_name;
            public int p2_rating, p2_wins;
            public float p2_odds;
            public int live_p1_points, live_p2_points;
            public bool bets_locked;
            public string lock_reason;  // "game_in_progress" | "no_meaningful_odds" | null — the only values the server emits (the once-documented "tournament"/"private_room" never existed server-side)
            public bool is_private;
            public bool is_tournament;
            public string tournament_kind; // "sync" | "async" | null
            public string phase; // "pre_match" | "live"
        }

        public class MyBetEntry
        {
            public string series_id, bet_on_steam_id, bet_on_name, series_status, series_score;
            public int amount;
            public float odds_multiplier;
            // v1.30 (bug #53): settlement info so the UI can show what HAPPENED
            // to a bet — pending / won / lost / refunded. payout == amount is a
            // refund (learning #107); payout only meaningful when settled.
            public bool settled;
            public int payout;
            // Item 6 polish: the matchup's other player + when the bet was placed.
            public string vs_name;
            public string created_at;
            // v1.36: server's EXPLICIT outcome (open|won|lost|refunded) —
            // mode-aware, replaces the payout==amount inference (#244).
            public string state;
        }

        public static List<ActiveSeriesEntry> CachedActiveSeries { get; private set; }
        public static List<MyBetEntry> CachedMyBets { get; private set; } = new List<MyBetEntry>();

        public static void FetchActiveSeries()
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/series/active",
                (ok, resp) =>
                {
                    if (!ok) return;
                    var list = new List<ActiveSeriesEntry>();
                    try
                    {
                        var parts = resp.Split(new[] { "\"series_id\":" }, StringSplitOptions.None);
                        for (int i = 1; i < parts.Length; i++)
                        {
                            string chunk = "\"series_id\":" + parts[i];
                            var e = new ActiveSeriesEntry();
                            e.series_id    = ExtractJsonString(chunk, "series_id");
                            e.p1_steam_id  = ExtractJsonString(chunk, "p1_steam_id");
                            e.p1_name      = ExtractJsonString(chunk, "p1_name");
                            e.p1_rating    = ExtractJsonInt(chunk, "p1_rating");
                            e.p1_wins      = ExtractJsonInt(chunk, "p1_wins");
                            e.p1_odds      = ExtractJsonFloat(chunk, "p1_odds");
                            e.p2_steam_id  = ExtractJsonString(chunk, "p2_steam_id");
                            e.p2_name      = ExtractJsonString(chunk, "p2_name");
                            e.p2_rating    = ExtractJsonInt(chunk, "p2_rating");
                            e.p2_wins      = ExtractJsonInt(chunk, "p2_wins");
                            e.p2_odds      = ExtractJsonFloat(chunk, "p2_odds");
                            e.p1_bettable  = !(chunk.Contains("\"p1_bettable\":false") || chunk.Contains("\"p1_bettable\": false"));
                            e.p2_bettable  = !(chunk.Contains("\"p2_bettable\":false") || chunk.Contains("\"p2_bettable\": false"));
                            e.live_p1_points = ExtractJsonInt(chunk, "live_p1_points");
                            e.live_p2_points = ExtractJsonInt(chunk, "live_p2_points");
                            e.bets_locked   = chunk.Contains("\"bets_locked\":true") || chunk.Contains("\"bets_locked\": true");
                            e.lock_reason   = ExtractJsonString(chunk, "lock_reason");
                            e.is_private    = chunk.Contains("\"is_private\":true") || chunk.Contains("\"is_private\": true");
                            e.is_tournament = chunk.Contains("\"is_tournament\":true") || chunk.Contains("\"is_tournament\": true");
                            e.tournament_kind = ExtractJsonString(chunk, "tournament_kind");
                            e.phase           = ExtractJsonString(chunk, "phase");
                            if (!string.IsNullOrEmpty(e.series_id)) list.Add(e);
                        }
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[BET] active-series parse: {ex.Message}"); }
                    CachedActiveSeries = list;
                    NativeUI.MarkDirty();
                }
            ));
        }

        // Fetches the local player's recent bets so the live-series UI can replace the wager
        // buttons with "You bet 500g on PlayerName" once a bet is placed (server enforces one
        // bet per series per player; this is purely the visible feedback).
        /// <summary>A rating tier's floor + its LIVE Discord role colour.</summary>
        public class RankTierEntry
        {
            public float floor;
            public string name;
            public string color;   // "#RRGGBB"
        }

        /// <summary>Rank-tier colours for the rating-history graph's benchmark
        /// lines. Hardcoding them made the graph drift the moment a Discord
        /// rank role was recoloured; the client now reads the server's live
        /// values and keeps its compiled palette only as an offline fallback.
        /// Null until the first successful fetch.</summary>
        public static List<RankTierEntry> CachedRankTiers = null;
        private static bool _rankTiersInFlight;
        private static float _rankTiersAt = -99999f;
        // Server caches role colours for 5 minutes; re-ask a little slower than
        // that so a Discord recolour actually reaches a client that stays open
        // for hours. Without a TTL the cache was fetched once per process and
        // the advertised propagation never happened (Codex wave-5b finding 6).
        private const float RANK_TIERS_TTL = 420f;

        public static void FetchRankTiers()
        {
            if (_rankTiersInFlight) return;
            if (CachedRankTiers != null && Time.realtimeSinceStartup - _rankTiersAt < RANK_TIERS_TTL) return;
            _rankTiersAt = Time.realtimeSinceStartup;
            _rankTiersInFlight = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/rank-tiers",
                (ok, resp) =>
                {
                    _rankTiersInFlight = false;
                    if (!ok || string.IsNullOrEmpty(resp)) return;
                    try
                    {
                        var list = new List<RankTierEntry>();
                        int key = resp.IndexOf("\"tiers\":", StringComparison.Ordinal);
                        int open = key >= 0 ? resp.IndexOf('[', key) : -1;
                        // String-aware slicing even though every value here is
                        // server-generated — matching the house style costs
                        // nothing and this stops being true the day a tier name
                        // becomes configurable (#156).
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (open < 0 || close <= open) return;
                        foreach (var chunk in SliceTopLevelObjects(resp.Substring(open + 1, close - open - 1)))
                        {
                            var t = new RankTierEntry
                            {
                                floor = ExtractJsonInt(chunk, "floor"),
                                name = ExtractJsonString(chunk, "name"),
                                color = ExtractJsonString(chunk, "color"),
                            };
                            if (!string.IsNullOrEmpty(t.name)) list.Add(t);
                        }
                        if (list.Count > 0) { CachedRankTiers = list; NativeUI.MarkDirty(); }
                    }
                    catch (Exception ex)
                    { Plugin.Log.LogWarning($"[RANK-TIERS] parse failed: {ex.Message}"); }
                }));
        }

        /// <summary>One result from any mode for the Leaderboard tab's Recent
        /// Ranked Series panel. The server composes the winner side, score and
        /// labels, so the client never re-derives a winner — a DC forfeit whose
        /// stored score is tied cannot render backwards.</summary>
        public class MultimodeSeriesEntry
        {
            public string mode;            // "2v2" | "1v2" | "ffa"
            public string id, ended_at;
            public string left_label, right_label, score;
            public float left_rating_change, right_rating_change;
            public List<MultimodeBet> bets = new List<MultimodeBet>();
        }

        public class MultimodeBet
        {
            public string bettor_name, bettor_steam_id, bet_on_label;
            public int amount, payout;
            public float odds_multiplier;
            // Explicit state from the server, never inferred: `payout > amount`
            // renders a REFUND as a loss (#107).
            public string state;           // open | won | lost | refunded
        }

        public static List<MultimodeSeriesEntry> CachedRecentMultimode = null;
        private static bool _multimodeInFlight;

        public static void FetchRecentMultimodeSeries(int limit = 60)
        {
            if (_multimodeInFlight) return;
            _multimodeInFlight = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/series/recent-multimode?limit={limit}",
                (ok, resp) =>
                {
                    _multimodeInFlight = false;
                    if (!ok || string.IsNullOrEmpty(resp)) return;
                    try
                    {
                        var list = new List<MultimodeSeriesEntry>();
                        int key = resp.IndexOf("\"entries\":", StringComparison.Ordinal);
                        int open = key >= 0 ? resp.IndexOf('[', key) : -1;
                        // Every field here carries user-authored display names,
                        // so the slicing must be string-aware end to end (#156).
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (open < 0 || close <= open) return;
                        foreach (var chunk in SliceTopLevelObjects(resp.Substring(open + 1, close - open - 1)))
                        {
                            var e = new MultimodeSeriesEntry
                            {
                                mode = ExtractJsonString(chunk, "mode"),
                                id = ExtractJsonString(chunk, "id"),
                                ended_at = ExtractJsonString(chunk, "ended_at"),
                                left_label = ExtractJsonString(chunk, "left_label"),
                                right_label = ExtractJsonString(chunk, "right_label"),
                                score = ExtractJsonString(chunk, "score"),
                                left_rating_change = ExtractJsonFloat(chunk, "left_rating_change"),
                                right_rating_change = ExtractJsonFloat(chunk, "right_rating_change"),
                            };
                            int bk = chunk.IndexOf("\"bets\":", StringComparison.Ordinal);
                            int bo = bk >= 0 ? chunk.IndexOf('[', bk) : -1;
                            int bc = bo >= 0 ? FindMatchingBracketStringAware(chunk, bo) : -1;
                            if (bo >= 0 && bc > bo)
                            {
                                foreach (var bch in SliceTopLevelObjects(chunk.Substring(bo + 1, bc - bo - 1)))
                                {
                                    var b = new MultimodeBet
                                    {
                                        bettor_name = ExtractJsonString(bch, "bettor_name"),
                                        bettor_steam_id = ExtractJsonString(bch, "bettor_steam_id"),
                                        bet_on_label = ExtractJsonString(bch, "bet_on_label"),
                                        amount = ExtractJsonInt(bch, "amount"),
                                        payout = ExtractJsonInt(bch, "payout"),
                                        odds_multiplier = ExtractJsonFloat(bch, "odds_multiplier"),
                                        state = ExtractJsonString(bch, "state"),
                                    };
                                    if (!string.IsNullOrEmpty(b.bettor_name)) e.bets.Add(b);
                                }
                            }
                            if (!string.IsNullOrEmpty(e.mode)) list.Add(e);
                        }
                        CachedRecentMultimode = list;
                        Plugin.Log.LogInfo($"Recent multimode series loaded: {list.Count}");
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex)
                    { Plugin.Log.LogWarning($"[MULTIMODE] parse failed: {ex.Message}"); }
                }));
        }

        public static void FetchMyBets(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/bets?limit=50",
                (ok, resp) =>
                {
                    if (!ok) return;
                    var list = new List<MyBetEntry>();
                    try
                    {
                        var parts = resp.Split(new[] { "\"id\":" }, StringSplitOptions.None);
                        for (int i = 1; i < parts.Length; i++)
                        {
                            string chunk = parts[i];
                            var b = new MyBetEntry();
                            b.amount         = ExtractJsonInt(chunk, "amount");
                            b.odds_multiplier= ExtractJsonFloat(chunk, "odds_multiplier");
                            b.series_id      = ExtractJsonString(chunk, "series_id");
                            b.bet_on_steam_id= ExtractJsonString(chunk, "bet_on_steam_id");
                            b.bet_on_name    = ExtractJsonString(chunk, "bet_on_name");
                            b.series_status  = ExtractJsonString(chunk, "series_status");
                            b.series_score   = ExtractJsonString(chunk, "series_score");
                            // settled_at is an ISO string when settled, JSON null while
                            // pending — a non-empty extract means the bet resolved.
                            b.settled        = !string.IsNullOrEmpty(ExtractJsonString(chunk, "settled_at"));
                            b.payout         = ExtractJsonInt(chunk, "payout");
                            b.vs_name        = ExtractJsonString(chunk, "vs_name");
                            b.created_at     = ExtractJsonString(chunk, "created_at");
                            b.state          = ExtractJsonString(chunk, "state");
                            if (!string.IsNullOrEmpty(b.series_id)) list.Add(b);
                        }
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[BET] my-bets parse: {ex.Message}"); }
                    CachedMyBets = list;
                    NativeUI.MarkDirty();
                }
            ));
        }

        public static MyBetEntry GetMyBetForSeries(string seriesId)
        {
            if (string.IsNullOrEmpty(seriesId) || CachedMyBets == null) return null;
            foreach (var b in CachedMyBets) if (b.series_id == seriesId) return b;
            return null;
        }

        /// <summary>Report current game-1 point counts on a live ranked series. The server uses
        /// these to lock betting once 2+ points have been scored. Delivery is retried (bounded,
        /// newest-value-wins via the retry map) and a 409 refusal is terminal; nothing here ever
        /// blocks gameplay. HMAC over "live-points:{series}:{reporter}:{p1}:{p2}".</summary>
        public static void PostLivePoints(string seriesId, string reporterSteamId, int p1Points, int p2Points)
        {
            if (string.IsNullOrEmpty(seriesId) || string.IsNullOrEmpty(reporterSteamId)) return;
            string sig = ComputeHmacHex($"live-points:{seriesId}:{reporterSteamId}:{p1Points}:{p2Points}");
            string url = $"{baseUrl}/api/v1/series/{Escape(seriesId)}/live-points" +
                         $"?p1_points={p1Points}&p2_points={p2Points}" +
                         $"&reporter_steam_id={Escape(reporterSteamId)}&sig={sig}";
            // Aug 31 (review r1 find 4): 1v1 was the ONE live-points channel
            // doing a bare fire-and-forget — a transient failure was simply
            // lost while the sender's latch said "sent". Now on the shared
            // bounded-retry map like 2v2/FFA (newest score replaces a pending
            // one; the server's GREATEST makes any replay safe).
            SendLivePoints("1v1:" + seriesId, url,
                $"1v1 series={seriesId.Substring(0, Math.Min(8, seriesId.Length))} {p1Points}-{p2Points}",
                resp =>
                {
                    // Aug 9 bet audit r8 SELF-HEAL, carried onto the retry map:
                    // the server can hand a new game the PREVIOUS series' id
                    // (preflight reuse before the deciding report commits).
                    // Once it answers "Series is not active", drop the held id
                    // — GameStateWatcher's game-start re-arm recreates the
                    // right series at the next boundary. Reacting to the
                    // server's own verdict, never predicting the race (#327).
                    // Deliberately NO eager mid-game re-arm (r9) — see that
                    // review's phantom-0-0-series rationale.
                    if (resp != null && resp.IndexOf("not active", StringComparison.OrdinalIgnoreCase) >= 0
                        && string.Equals(ActiveRankedSeriesId, seriesId, StringComparison.Ordinal))
                    {
                        Plugin.Log.LogWarning("[LIVE-POINTS] held series is no longer active — clearing so the "
                                              + "preflight re-arms for the current game");
                        ActiveRankedSeriesId = null;
                    }
                    return null;   // no URL rewrite — the refusal hook is the side effect
                });
        }

        // Review HIGH: live-point delivery must survive one failed request —
        // the cutoff is the whole point of the channel, and FFA has a single
        // sender. Each key keeps only its LATEST score; a failure re-queues it
        // (bounded), and a newer score replaces a pending one rather than
        // queueing behind it. The server's writes are monotonic and
        // idempotent, so a resend is always safe.
        private class LivePointRetry
        {
            public string url; public int attempts; public string tag;
            // Aug 31 (bets recon mechanism #3): optional one-shot URL rewrite
            // consulted when the server REFUSES the write (409). FFA uses it
            // to re-derive a drifted game_number from the 409 body — without
            // it, one missed game report left every later live-points write
            // refused and the betting window open for the rest of the sitting.
            public Func<string, string> rewriteOnRefusal; public bool rewrote;
        }
        private static readonly Dictionary<string, LivePointRetry> livePointRetries =
            new Dictionary<string, LivePointRetry>();
        private const int LIVE_POINT_MAX_ATTEMPTS = 4;

        private static void SendLivePoints(string key, string url, string tag,
                                           Func<string, string> rewriteOnRefusal = null)
        {
            var entry = new LivePointRetry { url = url, attempts = 0, tag = tag, rewriteOnRefusal = rewriteOnRefusal };
            livePointRetries[key] = entry;   // newest score wins outright
            SendLivePointsOnce(key, entry);
        }

        private static void SendLivePointsOnce(string key, LivePointRetry entry)
        {
            entry.attempts++;
            Plugin.Instance.StartCoroutine(PostRequest(entry.url, "", (ok, resp) =>
            {
                LivePointRetry current;
                if (!livePointRetries.TryGetValue(key, out current) || current != entry)
                    return;   // a newer score superseded this one
                if (ok)
                {
                    livePointRetries.Remove(key);
                    Plugin.Log.LogInfo($"[LIVE-POINTS] {entry.tag} ok");
                    return;
                }
                // A 409 is the server saying the write does not apply (series
                // over, wrong game) — retrying the SAME request cannot help.
                // BOTH token forms, like the fenced-restart matcher above:
                // FormatRequestError emits "HTTP 409:" (the load-bearing
                // prefix), and "HTTP/1.1 409" covers any raw-status path.
                // Round-2 review blocker 1: the single "HTTP/1.1" form NEVER
                // matched the formatter's output, so the refusal branch and
                // the FFA rewrite below were unreachable (#434's exact class).
                bool permanent = resp != null
                    && (resp.IndexOf("HTTP 409", StringComparison.Ordinal) >= 0
                        || resp.IndexOf("HTTP/1.1 409", StringComparison.Ordinal) >= 0);
                // ...but a refusal the sender knows how to CORRECT gets one
                // rewritten resend (FFA game-number drift self-heal, Aug 31).
                if (permanent && entry.rewriteOnRefusal != null && !entry.rewrote)
                {
                    string nu = null;
                    try { nu = entry.rewriteOnRefusal(resp); } catch { }
                    if (!string.IsNullOrEmpty(nu))
                    {
                        entry.rewrote = true; entry.url = nu; entry.attempts = 0;
                        Plugin.Log.LogInfo($"[LIVE-POINTS] {entry.tag} refused — re-deriving and resending once");
                        SendLivePointsOnce(key, entry);
                        return;
                    }
                }
                if (permanent || entry.attempts >= LIVE_POINT_MAX_ATTEMPTS)
                {
                    livePointRetries.Remove(key);
                    Plugin.Log.LogWarning($"[LIVE-POINTS] {entry.tag} giving up after {entry.attempts} "
                                          + $"attempt(s){(permanent ? " (server refused)" : "")}");
                    return;
                }
                Plugin.Instance.StartCoroutine(RetryLivePointsAfter(key, entry, 2f * entry.attempts));
            }));
        }

        private static System.Collections.IEnumerator RetryLivePointsAfter(string key, LivePointRetry entry, float delay)
        {
            yield return new WaitForSeconds(delay);
            LivePointRetry current;
            if (livePointRetries.TryGetValue(key, out current) && current == entry)
                SendLivePointsOnce(key, entry);
        }

        /// <summary>2v2 game-1 points, so betting locks at 2 the way 1v1 does
        /// (Sid, Aug 9: the cutoff is 2 points, never a clock). t1/t2 are in
        /// team_series' own slot order. Delivery is retried like the 1v1
        /// channel (bounded, newest-value-wins); a persistently lost report
        /// costs cutoff precision until the 20s refresh, never gameplay.</summary>
        public static void PostTeamLivePoints(string seriesId, string reporterSteamId, int t1Points, int t2Points)
        {
            if (string.IsNullOrEmpty(seriesId) || string.IsNullOrEmpty(reporterSteamId)) return;
            string sig = ComputeHmacHex($"team-live-points:{seriesId}:{reporterSteamId}:{t1Points}:{t2Points}");
            string url = $"{baseUrl}/api/v1/team/series/{Escape(seriesId)}/live-points" +
                         $"?t1_points={t1Points}&t2_points={t2Points}" +
                         $"&reporter_steam_id={Escape(reporterSteamId)}&sig={sig}";
            SendLivePoints("2v2:" + seriesId, url,
                $"2v2 series={seriesId.Substring(0, Math.Min(8, seriesId.Length))} {t1Points}-{t2Points}");
        }

        /// <summary>Points scored ACROSS THE FIELD in the FFA game in progress
        /// (everyone's points added up), so betting closes on the same reading
        /// 1v1 and 2v2 use when they sum their two sides. The threshold is the
        /// server's (2 normally, 1 for a first-to-3 lobby). game_number keeps a
        /// finished game's total from locking the next one's window.</summary>
        public static void PostFfaLivePoints(string lobbyId, string reporterSteamId, int gameNumber, int totalPoints)
        {
            if (string.IsNullOrEmpty(lobbyId) || string.IsNullOrEmpty(reporterSteamId) || gameNumber < 1) return;
            string sig = ComputeHmacHex($"ffa-live-points:{lobbyId}:{reporterSteamId}:{gameNumber}:{totalPoints}");
            string url = $"{baseUrl}/api/v1/ffa/lobbies/{Escape(lobbyId)}/live-points" +
                         $"?game_number={gameNumber}&total_points={totalPoints}" +
                         $"&reporter_steam_id={Escape(reporterSteamId)}&sig={sig}";
            SendLivePoints("ffa:" + lobbyId, url,
                $"ffa lobby={lobbyId.Substring(0, Math.Min(8, lobbyId.Length))} g{gameNumber} total={totalPoints}",
                // Aug 31 self-heal: the server's wrong-game 409 names the game
                // it expects ("expected_game=N"); one re-signed resend with
                // that number closes the drifted-counter fail-open (a missed
                // game report otherwise left betting open all sitting). The
                // OBSERVATION is of the live game regardless of numbering, so
                // carrying totalPoints over is correct; older-server 409s
                // (no marker) still give up exactly as before.
                resp =>
                {
                    if (string.IsNullOrEmpty(resp)) return null;
                    int idx = resp.IndexOf("expected_game=", StringComparison.Ordinal);
                    if (idx < 0) return null;
                    int p = idx + 14, v = 0; bool any = false;
                    while (p < resp.Length && resp[p] >= '0' && resp[p] <= '9') { v = v * 10 + (resp[p] - '0'); p++; any = true; }
                    if (!any || v < 1 || v == gameNumber) return null;
                    string sig2 = ComputeHmacHex($"ffa-live-points:{lobbyId}:{reporterSteamId}:{v}:{totalPoints}");
                    return $"{baseUrl}/api/v1/ffa/lobbies/{Escape(lobbyId)}/live-points" +
                           $"?game_number={v}&total_points={totalPoints}" +
                           $"&reporter_steam_id={Escape(reporterSteamId)}&sig={sig2}";
                });
        }

        /// <summary>Place a bet. HMAC over "bet:{bettor}:{series_id}:{bet_on}:{amount}".</summary>
        public static void PlaceBet(string bettorSteamId, string seriesId, string betOnSteamId, int amount, Action<bool, string> callback)
        {
            // §2c identity fence: the broadcast service account never wagers.
            if (BroadcastMode.FenceBlocksFighterPath("bet-1v1")) { callback?.Invoke(false, "broadcast-fence"); return; }
            string sig = ComputeHmacHex($"bet:{bettorSteamId}:{seriesId}:{betOnSteamId}:{amount}");
            string url = $"{baseUrl}/api/v1/bets?steam_id={Escape(bettorSteamId)}&series_id={Escape(seriesId)}&bet_on_steam_id={Escape(betOnSteamId)}&amount={amount}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[BET] place {amount} on {betOnSteamId}: ok={ok} resp={resp}");
                callback?.Invoke(ok, resp);
                if (ok)
                {
                    FetchPlayerStats(bettorSteamId);
                    FetchActiveSeries();
                }
            }));
        }

        // ── 2v2 betting ──────────────────────────────────────────
        // Active 2v2 series, list-of-my-bets, and place-bet endpoints all
        // mirror the 1v1 shape — mostly used by the Live Series UI in the
        // Leaderboard tab. UI rendering for these is on the next pass.
        [Serializable]
        public class ActiveTeamSeriesEntry
        {
            public string series_id;
            public string t1a_steam, t1a_name, t1b_steam, t1b_name;
            public string t2a_steam, t2a_name, t2b_steam, t2b_name;
            public int t1_rating, t2_rating;          // team-average (used for odds context)
            public int t1a_rating, t1b_rating, t2a_rating, t2b_rating;  // per-player 2v2 ratings
            public int t1_wins, t2_wins;
            public float t1_odds, t2_odds;
            // Aug 9 bet audit find 8 — see the 1v1 twin.
            public bool t1_bettable = true, t2_bettable = true;
            public bool bets_locked;
            public string lock_reason;
            public string started_at;
            public string dc_grace_until;
            // Aug 8 (Sid): frozen body-colour team identity ("" = vanilla).
            public string t1_color_name, t1_color_hex, t2_color_name, t2_color_hex;
            // Codex r2 f8-adjacent: true = the server DECIDED the identity
            // (including a decided-vanilla ""); false = pre-feature row.
            public bool color_decided;
        }
        public static List<ActiveTeamSeriesEntry> CachedActiveTeamSeries { get; private set; } = new List<ActiveTeamSeriesEntry>();

        public static void FetchActiveTeamSeries()
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/series/active",
                (success, response) =>
                {
                    if (!success) return;
                    try { ParseActiveTeamSeries(response); }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[TEAM-BET] active parse: {ex.Message}"); }
                }));
        }

        private static void ParseActiveTeamSeries(string response)
        {
            var list = new List<ActiveTeamSeriesEntry>();
            // #156: fighter display names ride this payload — a name containing
            // ']' / '{' / '}' broke the old naive bracket/depth slicing and
            // blanked the Live 2v2 panel, the 2v2 tab strip AND the spectator
            // HUD series line. String-aware slicers only.
            int sStart = response.IndexOf("\"series\"");
            if (sStart < 0) { CachedActiveTeamSeries = list; return; }
            int arrStart = response.IndexOf('[', sStart);
            if (arrStart < 0) { CachedActiveTeamSeries = list; return; }
            int arrEnd = FindMatchingBracketStringAware(response, arrStart);
            if (arrEnd < 0) { CachedActiveTeamSeries = list; return; }
            foreach (string obj in SliceTopLevelObjects(response.Substring(arrStart, arrEnd - arrStart + 1)))
            {
                list.Add(new ActiveTeamSeriesEntry
                {
                    series_id = ExtractJsonString(obj, "series_id"),
                    t1a_steam = ExtractJsonString(obj, "t1a_steam"),
                    t1a_name  = ExtractJsonString(obj, "t1a_name"),
                    t1b_steam = ExtractJsonString(obj, "t1b_steam"),
                    t1b_name  = ExtractJsonString(obj, "t1b_name"),
                    t2a_steam = ExtractJsonString(obj, "t2a_steam"),
                    t2a_name  = ExtractJsonString(obj, "t2a_name"),
                    t2b_steam = ExtractJsonString(obj, "t2b_steam"),
                    t2b_name  = ExtractJsonString(obj, "t2b_name"),
                    t1_rating = ExtractJsonInt(obj, "t1_rating"),
                    t2_rating = ExtractJsonInt(obj, "t2_rating"),
                    t1a_rating = ExtractJsonInt(obj, "t1a_rating"),
                    t1b_rating = ExtractJsonInt(obj, "t1b_rating"),
                    t2a_rating = ExtractJsonInt(obj, "t2a_rating"),
                    t2b_rating = ExtractJsonInt(obj, "t2b_rating"),
                    t1_wins   = ExtractJsonInt(obj, "t1_wins"),
                    t2_wins   = ExtractJsonInt(obj, "t2_wins"),
                    t1_odds   = ExtractJsonFloat(obj, "t1_odds"),
                    t2_odds   = ExtractJsonFloat(obj, "t2_odds"),
                    t1_bettable = !obj.Contains("\"t1_bettable\":false") && !obj.Contains("\"t1_bettable\": false"),
                    t2_bettable = !obj.Contains("\"t2_bettable\":false") && !obj.Contains("\"t2_bettable\": false"),
                    bets_locked = ExtractJsonBool(obj, "bets_locked"),
                    lock_reason = ExtractJsonString(obj, "lock_reason"),
                    started_at = ExtractJsonString(obj, "started_at"),
                    dc_grace_until = ExtractJsonString(obj, "dc_grace_until"),
                    t1_color_name = ExtractJsonString(obj, "t1_color_name") ?? "",
                    t1_color_hex = ExtractJsonString(obj, "t1_color_hex") ?? "",
                    t2_color_name = ExtractJsonString(obj, "t2_color_name") ?? "",
                    t2_color_hex = ExtractJsonString(obj, "t2_color_hex") ?? "",
                    color_decided = ExtractJsonBool(obj, "color_decided"),
                });
            }
            CachedActiveTeamSeries = list;
        }

        public static void PlaceTeamBet(string bettorSteamId, string seriesId, int betOnTeam, int amount, Action<bool, string> callback)
        {
            // §2c identity fence: the broadcast service account never wagers.
            if (BroadcastMode.FenceBlocksFighterPath("bet-2v2")) { callback?.Invoke(false, "broadcast-fence"); return; }
            string sig = ComputeHmacHex($"team-bet:{bettorSteamId}:{seriesId}:{betOnTeam}:{amount}");
            string url = $"{baseUrl}/api/v1/team-bets?steam_id={Escape(bettorSteamId)}&team_series_id={Escape(seriesId)}&bet_on_team={betOnTeam}&amount={amount}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[TEAM-BET] place {amount} on team {betOnTeam}: ok={ok} resp={resp}");
                callback?.Invoke(ok, resp);
                if (ok)
                {
                    FetchPlayerStats(bettorSteamId);
                    FetchActiveTeamSeries();
                }
            }));
        }


        // ── Shop ─────────────────────────────────────────────────
        [Serializable]
        public class ShopItemData
        {
            public long id;
            public string sku;
            public string kind;
            public string name;
            public string description;
            public int price;
            public string rarity;
            public string preview_color;
            public bool owned;
            // Artist controls (v1.30): community items carry their creator +
            // optional stock cap so rows can render "by Nix — 3 of 10 left".
            public string artist_steam_id;
            public string artist_name;
            public int stock_limit;   // 0 = unlimited
            public int stock_sold;    // only populated when stock_limit > 0
            // Music: ISO release date ("" when the server omits/nulls it) so
            // album rows sort newest-first client-side. Flat scalar — rides
            // the manual parser with no slicer work.
            public string released_iso;
        }

        public static List<ShopItemData> CachedShopItems { get; private set; }
        public static List<ShopItemData> CachedInventory { get; private set; }

        // Music entitlement snapshot generation — stamped at request DISPATCH,
        // never at callback completion (music design R3). Completion-stamping
        // would hand whichever response arrives LAST the highest generation,
        // so a slow pre-revoke/pre-purchase response could overwrite fresher
        // data; dispatch order is the truth ApplyShopSnapshot's stale-compare
        // needs. Every shop-items fetch (startup warm fetch, tab open,
        // post-purchase refresh, consent-grant refetch) funnels through
        // FetchShopItems, so this is the single stamp site.
        private static int _shopSnapshotGen;
        /// <summary>Highest shop-snapshot generation DISPATCHED so far (not
        /// necessarily applied). Read-only hook so MusicEntitlements'
        /// consent-revoke invalidation can outrank generations that are
        /// still in flight — a threshold derived only from APPLIED
        /// generations cannot see them.</summary>
        internal static int ShopSnapshotGenHighWater => _shopSnapshotGen;

        // Consent/identity/cache EPOCH for the RAW shop + inventory caches
        // (impl review I10): advanced BEFORE the caches are cleared on a
        // consent revoke or a resolved-identity change, and captured at
        // request dispatch — a response whose dispatch epoch is stale lands
        // into the void instead of repopulating a cache the revoke/identity
        // change just emptied. MusicEntitlements has its own gates; this
        // epoch exists because the raw caches previously had none.
        private static int _shopCacheEpoch;
        // Newest COMMITTED generation per raw cache: a response commits only
        // when its dispatch generation is newer than the last committed one,
        // so a slow pre-purchase response can never repaint an owned album
        // as unowned after the post-purchase response landed (dispatch order
        // is the truth, completion order is not — R3).
        private static int _shopItemsCommittedGen;
        private static int _inventoryFetchGen;
        private static int _inventoryCommittedGen;

        /// <summary>Impl review I11 + r3 I10 (called by GameStateWatcher's
        /// identity-transition hook): the resolved local steam id CHANGED —
        /// or resolved for the FIRST time, which is equally an epoch edge (an
        /// anonymous pre-resolution response must not survive as the resolved
        /// user's view). Both raw caches may carry stale identity data. Epoch
        /// first, clears second (I10 ordering); the caller refetches for a
        /// valid new identity itself.</summary>
        internal static void OnLocalIdentityChanged()
        {
            _shopCacheEpoch++;
            CachedShopItems = null;
            CachedInventory = null;
            NativeUI.MarkDirty();
        }

        public static void FetchShopItems(string steamId = null)
        {
            string url = $"{baseUrl}/api/v1/shop/items";
            if (!string.IsNullOrEmpty(steamId)) url += $"?steam_id={Escape(steamId)}";
            int gen = ++_shopSnapshotGen;
            int epoch = _shopCacheEpoch;
            // Anonymous fetch => "" — ApplyShopSnapshot drops it (an
            // unauthenticated response must never touch entitlements).
            string entitlementSid = string.IsNullOrEmpty(steamId) ? "" : steamId;
            Plugin.Instance.StartCoroutine(GetRequest(url, (success, response) =>
            {
                if (!success) { Plugin.Log.LogWarning($"[SHOP] list failed: {response}"); return; }
                // I10: parse into a LOCAL first; the raw cache commits only
                // while consent, identity, epoch and dispatch generation are
                // ALL still current — a slow pre-revoke / pre-purchase /
                // pre-identity-change response must not repaint a cache a
                // newer event already cleared or refreshed.
                var items = ParseShopItems(response);
                string localNow = null;
                try { localNow = MatchTracker.LocalSteamId; } catch { }
                // [impl-r3 I10] an ANONYMOUS dispatch is identity-current only
                // while the local identity is STILL unresolved at landing — an
                // anonymous body landing after resolution would repaint the
                // resolved user's view with owned=false rows. (The first-
                // resolution epoch advance in GameStateWatcher also drops the
                // in-flight case; this closes the never-advanced-epoch path.)
                bool localResolved = !string.IsNullOrEmpty(localNow) && localNow != "unknown";
                bool identityCurrent = string.IsNullOrEmpty(entitlementSid)
                    ? !localResolved
                    : string.Equals(entitlementSid, localNow, StringComparison.Ordinal);
                if (Plugin.DataConsentGranted && epoch == _shopCacheEpoch
                    && gen > _shopItemsCommittedGen && identityCurrent)
                {
                    _shopItemsCommittedGen = gen;
                    CachedShopItems = items;
                    Plugin.Log.LogInfo($"[SHOP] loaded {items.Count} items");
                }
                else
                {
                    Plugin.Log.LogInfo($"[SHOP] stale shop snapshot dropped (gen {gen}, epoch {epoch}/{_shopCacheEpoch})");
                }
                // Entitlements ride the same snapshot but keep their OWN
                // identity + generation-floor gates, so they get the parsed
                // list whether or not the raw cache committed. Consent gate:
                // a revoke that lands while this response is in flight must
                // outrank it (G11) — GetRequest only checks consent at
                // dispatch, so the landing side re-checks here. Guarded so a
                // music-side throw can never break shop rendering.
                try
                {
                    if (Plugin.DataConsentGranted)
                        MusicEntitlements.ApplyShopSnapshot(entitlementSid, gen, items);
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[MUSIC] entitlement snapshot apply failed: {ex.Message}"); }
                NativeUI.MarkDirty();
            }));
        }

        public static void FetchInventory(string steamId)
        {
            if (string.IsNullOrEmpty(steamId)) return;
            int gen = ++_inventoryFetchGen;
            int epoch = _shopCacheEpoch;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/inventory",
                (success, response) =>
                {
                    if (!success) return;
                    // I10: same commit fence as FetchShopItems — the
                    // inventory cache must not repopulate after a consent
                    // revoke or identity change, and completion order must
                    // not beat dispatch order. Every caller passes the LOCAL
                    // player's id, so identity currency is an equality test.
                    string localNow = null;
                    try { localNow = MatchTracker.LocalSteamId; } catch { }
                    if (!Plugin.DataConsentGranted
                        || epoch != _shopCacheEpoch
                        || gen <= _inventoryCommittedGen
                        || !string.Equals(steamId, localNow, StringComparison.Ordinal)) return;
                    _inventoryCommittedGen = gen;
                    CachedInventory = ParseShopItems(response);
                    NativeUI.MarkDirty();
                }));
        }

        /// <summary>Purchase. HMAC over "buy:{steam_id}:{sku}" — FROZEN (#5
        /// class): expected_price deliberately rides OUTSIDE the canonical
        /// (music design v4 §1/R10 — it protects the honest buyer's PAINTED
        /// price against a racing artist edit, not against forgery; the
        /// session + HMAC keep authenticating the buyer).
        ///
        /// expectedPrice >= 0 appends &amp;expected_price= so the server can
        /// 409 on a live mismatch [M5]; the caller must pass the price the
        /// CLICKED row painted, never a cache re-read at click time [M6 —
        /// NativeUI's half]. -1 (default) omits the check entirely, so every
        /// pre-existing call site is byte-identical on the wire.
        ///
        /// A 409 whose body carries "price_changed" refetches the shop
        /// (repaint — without it every later click repeats the stale
        /// mismatch) and surfaces the literal sentinel "price_changed" to the
        /// callback so the UI can show its own Tr'd message [M7]. NEVER
        /// auto-retried at the new price — a fresh, informed click is the
        /// only path to a purchase.</summary>
        public static void PurchaseItem(string steamId, string sku, Action<bool, string> callback, int expectedPrice = -1)
        {
            Plugin.Log.LogInfo($"[SHOP] PurchaseItem ENTRY sku={sku} steamId={steamId} expectedPrice={expectedPrice}");
            try
            {
                string sig = ComputeHmacHex($"buy:{steamId}:{sku}");
                Plugin.Log.LogInfo($"[SHOP] sig computed ({sig?.Length ?? 0} chars)");
                string url = $"{baseUrl}/api/v1/shop/purchase?steam_id={steamId}&sku={sku}&sig={sig}";
                if (expectedPrice >= 0) url += $"&expected_price={expectedPrice}";
                Plugin.Log.LogInfo($"[SHOP] POST {url.Substring(0, Math.Min(url.Length, 100))}...");
                Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
                {
                    Plugin.Log.LogInfo($"[SHOP] purchase callback {sku}: ok={ok} resp={(resp != null && resp.Length > 120 ? resp.Substring(0, 120) + "..." : resp)}");
                    // [M7] price-mismatch 409: repaint BEFORE the user can
                    // click again. The raw body is already in the log line
                    // above; the callback gets a machine-readable sentinel
                    // (same pattern as "no-consent"/"outdated") — the UI owns
                    // the Tr'd player-facing message.
                    bool priceChanged = !ok && resp != null
                        && resp.StartsWith("HTTP 409", StringComparison.Ordinal)
                        && resp.IndexOf("price_changed", StringComparison.OrdinalIgnoreCase) >= 0;
                    if (priceChanged) FetchShopItems(steamId);
                    try { callback?.Invoke(ok, priceChanged ? "price_changed" : resp); } catch (Exception cex) { Plugin.Log.LogWarning($"[SHOP] callback threw: {cex.Message}"); }
                    if (ok)
                    {
                        FetchPlayerStats(steamId);
                        FetchShopItems(steamId);
                        FetchInventory(steamId);
                    }
                }));
                Plugin.Log.LogInfo("[SHOP] coroutine dispatched");
            }
            catch (Exception ex)
            {
                Plugin.Log.LogError($"[SHOP] PurchaseItem threw: {ex}");
                try { callback?.Invoke(false, ex.Message); } catch { }
            }
        }

        // ── Music ratings (music batch 2 §2; the fenced store is MusicRatings) ──

        /// <summary>GET /music/ratings — PUBLIC delayed aggregates. gen is
        /// MusicRatings' dispatch stamp; the store's floor/committed gates
        /// decide at landing whether the snapshot applies [M14]. Response
        /// contract (server sibling — grep both sides, #329):
        /// {"tracks":[{"sku","track_idx","avg","rating_count","rater_count"}...],
        ///  "albums":[{"sku","avg","rating_count","rater_count"}...]}.</summary>
        internal static void FetchMusicRatingAggregates(int gen)
        {
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/music/ratings", (ok, resp) =>
            {
                if (!ok) { Plugin.Log.LogInfo($"[MUSIC-RATE] aggregate fetch failed: {resp}"); return; }
                List<MusicRatings.TrackAggRow> tracks;
                List<MusicRatings.AlbumAggRow> albums;
                ParseMusicRatingAggregates(resp, out tracks, out albums);
                try { MusicRatings.ApplyAggregates(gen, tracks, albums); }
                catch (Exception ex) { Plugin.Log.LogWarning($"[MUSIC-RATE] aggregate apply failed: {ex.Message}"); }
            }));
        }

        /// <summary>GET /music/ratings/mine?steam_id= — the caller's PRIVATE
        /// rows, strict-session endpoint (M17/M21: separate from the public
        /// aggregates so an auth failure can never masquerade as own=[]; a
        /// failure here applies NOTHING). sessionAware so a stale token's
        /// 401 session_required re-mints instead of 401-looping until the
        /// ~23h expiry — and N17's replica-lag worry about that is REFUTED:
        /// the live edge allowlist routes only leaderboards/records/
        /// histories to the standby, every /music path hits the primary.
        /// Response contract:
        /// {"ratings":[{"sku","track_idx","stars","intent_rev"}...]}.</summary>
        internal static void FetchMusicRatingsOwn(string steamId, int gen)
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/music/ratings/mine?steam_id={Escape(steamId)}",
                (ok, resp) =>
                {
                    if (!ok) { Plugin.Log.LogInfo($"[MUSIC-RATE] own fetch failed: {resp}"); return; }
                    List<MusicRatings.OwnRow> rows;
                    if (!ParseMusicRatingsMine(resp, out rows))
                    {
                        // [N14]/[P6] malformed 200 — bad shell OR any bad
                        // element: NOT an authoritative empty, keep the prior
                        // own-rating state (this is the single rejection log).
                        Plugin.Log.LogWarning("[MUSIC-RATE] own fetch returned a malformed body — keeping prior state");
                        return;
                    }
                    try { MusicRatings.ApplyOwn(steamId, gen, rows); }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[MUSIC-RATE] own apply failed: {ex.Message}"); }
                }, detailedErrors: false, sessionAware: true));
        }

        /// <summary>POST /music/rate — stars ride the JSON BODY, never the
        /// query string (M21: rating values must stay out of URL logs). Rides
        /// PostRequest so HandleSessionReject runs. Deliberately NO transport
        /// retry (PostRequestWithRetry would resurrect superseded intents,
        /// the #166/M16 class) — MusicRatings owns the single-retry +
        /// latest-intent coalescing policy. stars 0 = clear.
        /// [N5] intent_rev is the per-(player,track) monotonic revision the
        /// server compares against its stored floor (reject-not-newer, so a
        /// delayed old request can never resurrect a superseded intent);
        /// op_id is the idempotency key (a duplicate landing twice must not
        /// re-arm the maturation delay). Server sibling reads exactly
        /// "intent_rev"/"op_id" (grep both sides, #329).</summary>
        internal static void PostMusicRating(string steamId, string sku, int trackIdx, int stars,
            int intentRev, string opId, Action<bool, string> callback)
        {
            string json = $"{{\"steam_id\":\"{Escape(steamId)}\",\"sku\":\"{Escape(sku)}\",\"track_idx\":{trackIdx},\"stars\":{stars},\"intent_rev\":{intentRev},\"op_id\":\"{Escape(opId ?? "")}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/music/rate", json, callback));
        }

        /// <summary>Slice the object array behind "prop": [...] . [#400] the
        /// first non-whitespace char after the colon must be '[' — a null (or
        /// absent) value must not let the scan consume the NEIGHBORING
        /// property's array. Returns empty on any shape mismatch.</summary>
        private static List<string> SliceNamedObjectArray(string json, string prop)
        {
            bool _;
            return SliceNamedObjectArray(json, prop, out _);
        }

        /// <summary>[N14] wellFormed reports whether the property EXISTS and
        /// its value is structurally an array. A missing / null / non-array
        /// value returns the same empty list either way, so a PRIVATE
        /// consumer must read wellFormed to tell "authoritative empty" from
        /// "malformed 200" — the two are indistinguishable by the list
        /// alone, and treating the latter as the former clears state.</summary>
        private static List<string> SliceNamedObjectArray(string json, string prop, out bool wellFormed)
        {
            wellFormed = false;
            var none = new List<string>();
            if (string.IsNullOrEmpty(json)) return none;
            int at = json.IndexOf("\"" + prop + "\":", StringComparison.Ordinal);
            if (at < 0) return none;
            int i = at + prop.Length + 3;
            while (i < json.Length && char.IsWhiteSpace(json[i])) i++;
            if (i >= json.Length || json[i] != '[') return none;
            int close = FindMatchingBracketStringAware(json, i);
            if (close < 0) return none;
            wellFormed = true;
            return SliceTopLevelObjects(json.Substring(i + 1, close - i - 1));
        }

        private static void ParseMusicRatingAggregates(string resp,
            out List<MusicRatings.TrackAggRow> tracks, out List<MusicRatings.AlbumAggRow> albums)
        {
            tracks = new List<MusicRatings.TrackAggRow>();
            albums = new List<MusicRatings.AlbumAggRow>();
            try
            {
                foreach (string obj in SliceNamedObjectArray(resp, "tracks"))
                {
                    string sku = ExtractJsonString(obj, "sku");
                    if (string.IsNullOrEmpty(sku)) continue;
                    int count = ExtractJsonInt(obj, "rating_count");
                    int raters = ExtractJsonInt(obj, "rater_count");
                    tracks.Add(new MusicRatings.TrackAggRow
                    {
                        sku = sku,
                        idx = ExtractJsonInt(obj, "track_idx"),
                        avg = ExtractJsonFloat(obj, "avg"),
                        count = count,
                        // Tolerate a server that omits rater_count [M20 carries
                        // both]; count is the honest lower-fidelity fallback.
                        raters = raters > 0 ? raters : count,
                    });
                }
                foreach (string obj in SliceNamedObjectArray(resp, "albums"))
                {
                    string sku = ExtractJsonString(obj, "sku");
                    if (string.IsNullOrEmpty(sku)) continue;
                    int count = ExtractJsonInt(obj, "rating_count");
                    int raters = ExtractJsonInt(obj, "rater_count");
                    albums.Add(new MusicRatings.AlbumAggRow
                    {
                        sku = sku,
                        avg = ExtractJsonFloat(obj, "avg"),
                        count = count,
                        raters = raters > 0 ? raters : count,
                    });
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[MUSIC-RATE] aggregate parse failed: {ex.Message}"); }
        }

        /// <summary>[N14]/[P6] Success/failure is DISTINCT from emptiness:
        /// returns false (rows left empty) when the 200 body is malformed.
        /// Only a true return may reach MusicRatings.ApplyOwn; a malformed
        /// success handed over would read as an authoritative "you have no
        /// ratings" and clear the user's confirmed stars.
        /// [P6] Strictness is PER ELEMENT, not just the array shell: every
        /// element must be an OBJECT carrying a nonempty sku (&lt;= 64 chars),
        /// int track_idx 0..63, int stars 0..5 (0 = pending clear) and int
        /// intent_rev &gt;= 1 (/mine is new in v1.40, so every server that can
        /// answer it stores a revision — no legacy-absent tolerance). ANY
        /// malformed element rejects the ENTIRE snapshot — the sibling
        /// parsers' skip-a-bad-row tolerance is wrong HERE because this list
        /// authorizes wholesale replacement of private state: a partially
        /// valid body (e.g. {"ratings":[42]} slicing to zero objects) must
        /// keep prior state, never apply as a clear. A genuinely empty array
        /// is true + zero rows (a cleared-everything state MUST still
        /// apply). The caller logs the rejection once.</summary>
        private static bool ParseMusicRatingsMine(string resp, out List<MusicRatings.OwnRow> rows)
        {
            rows = new List<MusicRatings.OwnRow>();
            try
            {
                List<string> objs;
                if (!SliceStrictNamedObjectArray(resp, "ratings", out objs)) return false;
                foreach (string obj in objs)
                {
                    // [Q4] Every required field must be a DIRECT member of the
                    // row object, present exactly once, holding a bare scalar
                    // of the right type. The old per-key IndexOf was
                    // depth-blind and delimiter-loose, so a nested substitute
                    // ({"row":{...}}) and a malformed literal ("stars":5 xyz)
                    // both validated — and either one reaches ApplyOwn, which
                    // REPLACES the player's whole confirmed rating state.
                    Dictionary<string, string> mem;
                    string sku;
                    int idx, stars, rev;
                    if (!TryTopLevelMembers(obj, out mem)
                        || !mem.ContainsKey("sku") || !TryStrictJsonString(mem["sku"], out sku)
                        || string.IsNullOrEmpty(sku) || sku.Length > 64
                        || !mem.ContainsKey("track_idx") || !TryStrictJsonInt(mem["track_idx"], out idx)
                        || idx < 0 || idx > 63
                        || !mem.ContainsKey("stars") || !TryStrictJsonInt(mem["stars"], out stars)
                        || stars < 0 || stars > 5
                        || !mem.ContainsKey("intent_rev") || !TryStrictJsonInt(mem["intent_rev"], out rev)
                        || rev < 1)
                    {
                        rows.Clear();
                        return false;
                    }
                    rows.Add(new MusicRatings.OwnRow { sku = sku, idx = idx, stars = stars, rev = rev });
                }
                return true;
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[MUSIC-RATE] own parse failed: {ex.Message}");
                rows.Clear();
                return false;
            }
        }

        /// <summary>[P6] Strict twin of SliceNamedObjectArray for snapshots
        /// that authorize wholesale state replacement: the named array's TOP
        /// LEVEL must hold nothing but comma-separated objects (whitespace
        /// tolerated; a trailing comma or any non-object element rejects).
        /// SliceNamedObjectArray harvests whatever balanced objects appear
        /// and silently ignores everything else, so {"ratings":[42]} reads
        /// as well-formed + zero rows there — here it is false. False also
        /// for an absent / null / non-array value, exactly like the tolerant
        /// helper's wellFormed out.</summary>
        private static bool SliceStrictNamedObjectArray(string json, string prop, out List<string> objs)
        {
            objs = new List<string>();
            if (string.IsNullOrEmpty(json)) return false;
            // [R4] ANCHOR THE ENVELOPE. The old IndexOf found the property at
            // ANY depth and validated nothing after the array, so
            // {"error":{"ratings":[]}} and {"ratings":[]}junk both read as a
            // valid EMPTY snapshot — and an empty snapshot authorizes clearing
            // the player's confirmed private ratings. The root must be one
            // object that parses completely, carrying the property as a DIRECT
            // member exactly once (TryTopLevelMembers rejects duplicates,
            // trailing commas, junk between members and trailing text), and
            // the array is then validated from that member's own span.
            Dictionary<string, string> root;
            if (!TryTopLevelMembers(json, out root)) return false;
            string arr;
            if (!root.TryGetValue(prop, out arr) || string.IsNullOrEmpty(arr)) return false;
            return SliceStrictObjectArraySpan(arr, out objs);
        }

        /// <summary>[R4] The array half of the strict slice, over a span that
        /// is already known to be ONE complete JSON value.</summary>
        private static bool SliceStrictObjectArraySpan(string json, out List<string> objs)
        {
            objs = new List<string>();
            int i = 0;
            while (i < json.Length && char.IsWhiteSpace(json[i])) i++;
            if (i >= json.Length || json[i] != '[') return false;
            int close = FindMatchingBracketStringAware(json, i);
            if (close < 0) return false;
            for (int t = close + 1; t < json.Length; t++)
                if (!char.IsWhiteSpace(json[t])) return false;   // junk after the array
            int p = i + 1;
            while (p < close)
            {
                while (p < close && char.IsWhiteSpace(json[p])) p++;
                if (p >= close) break;
                if (json[p] != '{') { objs.Clear(); return false; }
                int objClose = FindMatchingBraceStringAware(json, p);
                if (objClose < 0 || objClose >= close) { objs.Clear(); return false; }
                objs.Add(json.Substring(p, objClose - p + 1));
                p = objClose + 1;
                while (p < close && char.IsWhiteSpace(json[p])) p++;
                if (p >= close) break;                             // clean end after an object
                if (json[p] != ',') { objs.Clear(); return false; }
                p++;                                               // a comma must introduce another element...
                while (p < close && char.IsWhiteSpace(json[p])) p++;
                if (p >= close) { objs.Clear(); return false; }    // ...so a trailing comma rejects
            }
            return true;
        }

        /// <summary>[Q4] End index of the JSON string starting at
        /// <paramref name="openQuote"/> (the index of its closing quote), or
        /// -1. Escape-aware, matching the brace/bracket scanners.</summary>
        private static int FindJsonStringEnd(string s, int openQuote)
        {
            if (openQuote < 0 || openQuote >= s.Length || s[openQuote] != '"') return -1;
            for (int i = openQuote + 1; i < s.Length; i++)
            {
                if (s[i] == '\\') { i++; continue; }
                if (s[i] == '"') return i;
            }
            return -1;
        }

        /// <summary>[Q4] Depth-aware member map for ONE JSON object: every
        /// key at the object's TOP LEVEL mapped to its RAW value span, with
        /// duplicate keys, trailing commas, junk between members and any
        /// non-whitespace after the closing brace all rejected. The point is
        /// that a required field can only be satisfied by a DIRECT member —
        /// the old per-key IndexOf matched the same key nested arbitrarily
        /// deep, so a wrong-schema row passed validation and authorized a
        /// wholesale replacement of private state (r3 find Q4).</summary>
        private static bool TryTopLevelMembers(string obj, out Dictionary<string, string> members)
        {
            members = new Dictionary<string, string>(StringComparer.Ordinal);
            if (string.IsNullOrEmpty(obj)) return false;
            int i = 0;
            while (i < obj.Length && char.IsWhiteSpace(obj[i])) i++;
            if (i >= obj.Length || obj[i] != '{') return false;
            int end = FindMatchingBraceStringAware(obj, i);
            if (end < 0) return false;
            for (int t = end + 1; t < obj.Length; t++)
                if (!char.IsWhiteSpace(obj[t])) return false;   // trailing junk
            int p = i + 1;
            while (true)
            {
                while (p < end && char.IsWhiteSpace(obj[p])) p++;
                if (p >= end) return true;                       // clean finish
                if (obj[p] != '"') return false;                 // members are quoted keys
                int keyEnd = FindJsonStringEnd(obj, p);
                if (keyEnd < 0 || keyEnd >= end) return false;
                string key = obj.Substring(p + 1, keyEnd - p - 1);
                p = keyEnd + 1;
                while (p < end && char.IsWhiteSpace(obj[p])) p++;
                if (p >= end || obj[p] != ':') return false;
                p++;
                while (p < end && char.IsWhiteSpace(obj[p])) p++;
                if (p >= end) return false;
                int valStart = p, valEnd;
                char c = obj[p];
                if (c == '{' || c == '[')
                {
                    valEnd = (c == '{') ? FindMatchingBraceStringAware(obj, p)
                                        : FindMatchingBracketStringAware(obj, p);
                    if (valEnd < 0 || valEnd >= end) return false;
                }
                else if (c == '"')
                {
                    valEnd = FindJsonStringEnd(obj, p);
                    if (valEnd < 0 || valEnd >= end) return false;
                }
                else
                {
                    int q = p;
                    while (q < end && obj[q] != ',' && obj[q] != '}') q++;
                    valEnd = q - 1;
                    while (valEnd > p && char.IsWhiteSpace(obj[valEnd])) valEnd--;
                    if (valEnd < p) return false;
                }
                if (members.ContainsKey(key)) return false;      // duplicate member
                members[key] = obj.Substring(valStart, valEnd - valStart + 1);
                p = valEnd + 1;
                while (p < end && char.IsWhiteSpace(obj[p])) p++;
                if (p >= end) return true;
                if (obj[p] != ',') return false;                 // junk between members
                p++;
                while (p < end && char.IsWhiteSpace(obj[p])) p++;
                if (p >= end) return false;                      // trailing comma
            }
        }

        /// <summary>[Q4] A member's raw span must be a BARE JSON integer —
        /// the whole span, nothing else. Rejects null/string/float/exponent,
        /// digit-prefixed garbage, and the "5 xyz" shape the old
        /// whitespace-tolerant terminator accepted.
        ///
        /// ACCEPTED RESIDUAL (r4 R5, deliberate): this validates the value is
        /// an integer, not that it obeys JSON's integer GRAMMAR — "05" parses
        /// as 5. The same class covers escaped-but-semantically-duplicate keys
        /// (stored raw, so "stars" reads as an unrelated extra member and
        /// the real "stars" still governs), lone surrogate escapes in sku (a
        /// garbage sku matches no catalogue album and renders nothing), and
        /// unknown members whose spans are sliced but not syntax-checked.
        /// Every one of them requires OUR OWN server to emit malformed JSON —
        /// r4 confirmed no legitimate response is affected — and the worst
        /// outcome is a local own-ratings view that clears and self-heals on
        /// the next fetch. Tightening to full JSON grammar means a real
        /// tokenizer; that is the right fix if this parser ever consumes a
        /// third-party body, and unjustified while it consumes only ours.</summary>
        private static bool TryStrictJsonInt(string raw, out int val)
        {
            val = 0;
            if (string.IsNullOrEmpty(raw)) return false;
            int i = (raw[0] == '-') ? 1 : 0;
            if (i >= raw.Length) return false;
            for (int k = i; k < raw.Length; k++)
                if (raw[k] < '0' || raw[k] > '9') return false;  // ASCII only (#405)
            return int.TryParse(raw, System.Globalization.NumberStyles.Integer,
                System.Globalization.CultureInfo.InvariantCulture, out val);
        }

        /// <summary>[Q4] A member's raw span must be a quoted JSON string;
        /// returns it unescaped.</summary>
        private static bool TryStrictJsonString(string raw, out string val)
        {
            val = null;
            if (string.IsNullOrEmpty(raw) || raw.Length < 2
                || raw[0] != '"' || raw[raw.Length - 1] != '"') return false;
            if (FindJsonStringEnd(raw, 0) != raw.Length - 1) return false;   // must be ONE string
            var sb = new System.Text.StringBuilder(raw.Length);
            for (int i = 1; i < raw.Length - 1; i++)
            {
                char c = raw[i];
                if (c != '\\') { sb.Append(c); continue; }
                if (i + 1 >= raw.Length - 1) return false;
                char n = raw[++i];
                switch (n)
                {
                    case 'n': sb.Append('\n'); break;
                    case 'r': sb.Append('\r'); break;
                    case 't': sb.Append('\t'); break;
                    case 'b': sb.Append('\b'); break;
                    case 'f': sb.Append('\f'); break;
                    case '"': sb.Append('"'); break;
                    case '\\': sb.Append('\\'); break;
                    case '/': sb.Append('/'); break;
                    case 'u':
                        if (i + 4 >= raw.Length - 1) return false;
                        int code;
                        if (!int.TryParse(raw.Substring(i + 1, 4),
                                System.Globalization.NumberStyles.HexNumber,
                                System.Globalization.CultureInfo.InvariantCulture, out code)) return false;
                        sb.Append((char)code); i += 4; break;
                    default: return false;                        // invalid escape
                }
            }
            val = sb.ToString();
            return true;
        }

        /// <summary>Set / clear active title. HMAC over "title:{steam_id}:{item_id or 0}".</summary>
        public static void SetActiveTitle(string steamId, long itemId, Action<bool, string> callback = null)
        {
            string sig = ComputeHmacHex($"title:{steamId}:{itemId}");
            string url = $"{baseUrl}/api/v1/players/{steamId}/active-title?sig={sig}";
            if (itemId > 0) url += $"&item_id={itemId}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[SHOP] set title {itemId}: ok={ok} resp={resp}");
                callback?.Invoke(ok, resp);
                if (ok) FetchPlayerStats(steamId);
            }));
        }

        /// <summary>Set / clear active trail. HMAC over "trail:{steam_id}:{item_id or 0}".</summary>
        public static void SetActiveTrail(string steamId, long itemId, Action<bool, string> callback = null)
        {
            string sig = ComputeHmacHex($"trail:{steamId}:{itemId}");
            string url = $"{baseUrl}/api/v1/players/{steamId}/active-trail?sig={sig}";
