        private static List<ShopItemData> ParseShopItems(string response)
        {
            var list = new List<ShopItemData>();
            if (string.IsNullOrEmpty(response)) return list;
            // Split by item object boundary.
            var parts = response.Split(new[] { "{\"id\":" }, StringSplitOptions.None);
            for (int i = 1; i < parts.Length; i++)
            {
                string chunk = "{\"id\":" + parts[i];
                var it = new ShopItemData();
                it.id = ExtractJsonInt(chunk, "id");
                it.sku = ExtractJsonString(chunk, "sku");
                it.kind = ExtractJsonString(chunk, "kind");
                it.name = ExtractJsonString(chunk, "name");
                it.description = ExtractJsonString(chunk, "description");
                it.price = ExtractJsonInt(chunk, "price");
                it.rarity = ExtractJsonString(chunk, "rarity");
                it.preview_color = ExtractJsonString(chunk, "preview_color");
                it.owned = ExtractJsonBool(chunk, "owned");
                it.artist_steam_id = ExtractJsonString(chunk, "artist_steam_id");
                it.artist_name = ExtractJsonString(chunk, "artist_name");
                it.stock_limit = ExtractJsonInt(chunk, "stock_limit");
                it.stock_sold = ExtractJsonInt(chunk, "stock_sold");
                it.released_iso = ExtractJsonString(chunk, "released_iso");
                if (!string.IsNullOrEmpty(it.sku) || !string.IsNullOrEmpty(it.name))
                    list.Add(it);
            }
            return list;
        }


        /// <summary>Pulls recent chat scrollback so the log isn't empty on a fresh connect.
        /// Each entry dispatches through ChatClient.OnMessage to share the render path.</summary>
        /// <summary>Launch-time i18n pack overlay fetch (§2.2). The response
        /// is applied through I18n.ApplyPack (format gate first) and cached
        /// for offline launches only when it parsed cleanly.</summary>
        private static int _i18nPackGen;

        public static void FetchI18nPack()
        {
            // Locale captured HERE (wave-2 find 8): the callback must apply
            // and cache under the locale it FETCHED for — a slow response
            // arriving after a locale switch is dropped by ApplyPack's
            // expected-locale check, never installed under the new one.
            // The GENERATION guard (round-3 find N15) closes the ABA hole
            // locale equality can't: ES -> RU -> ES leaves two live ES
            // fetches, and the OLDER response finishing last would overwrite
            // the newer pack. Only the newest fetch may install.
            string loc = I18n.Locale;
            if (loc == I18n.LOCALE_EN || Plugin.Instance == null) return;
            int gen = ++_i18nPackGen;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/i18n/pack/{loc}",
                (success, response) =>
                {
                    if (gen != _i18nPackGen) return;   // superseded fetch
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try { if (I18n.ApplyPack(response, loc)) I18n.CachePack(response, loc); }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[I18N] pack fetch apply failed: {ex.Message}"); }
                }));
        }

        /// <summary>Portal handoff (§2.5): mint a short-TTL portal session and
        /// open the browser with the token in the URL FRAGMENT. Refused on a
        /// plaintext base URL — the token is a real credential.</summary>
        public static void OpenTranslatePortal()
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || Plugin.Instance == null) return;
            if (!baseUrl.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            {
                CompetitiveUI.ShowNotification("Can't open the portal - this install is on an insecure backup connection. Restart ROUNDS to retry the secure one.", Color.yellow, 6f);
                return;
            }
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/i18n/portal-session",
                $"{{\"steam_id\":\"{Escape(sid)}\"}}",
                (success, response) =>
                {
                    string token = success ? ExtractJsonString(response, "token") : null;
                    if (string.IsNullOrEmpty(token))
                    {
                        CompetitiveUI.ShowNotification("Portal session failed - are you signed in to Steam?", Color.yellow, 5f);
                        return;
                    }
                    Application.OpenURL($"{baseUrl}/translate#token={token}");
                }));
        }

        // R2-5: chat scrollback request generation. A refetch (reconnect,
        // language change) can race a slower earlier one; without a guard the
        // stale response repopulates the pane after the newer one. Bumped at
        // REQUEST time; each callback captures its value and drops itself when
        // superseded (mirrors ffaRecentRankedGen). Interlocked/Volatile rather
        // than a plain int because FetchRecentChat is also invoked from the
        // ChatClient WS thread (reconnect scrollback), not only the main
        // thread.
        private static int chatRecentGen;

        /// <summary>Chat scrollback for the FULL allowed channel set, always.
        /// There is no per-call channel override any more: the socket
        /// subscribes to every channel unconditionally
        /// (ChatClient.DerivedChannelSet is a constant), so history must
        /// match — a narrower fetch would just recreate the "All (merged)
        /// shows only global" bug on the history half. Filtering to one
        /// channel is a render-side decision, not a fetch-side one.
        /// `limit` is the TOTAL row budget; since Aug-3 the endpoint shares it
        /// FAIRLY across the requested channels (a ROW_NUMBER CTE ordered by
        /// rank first, so the channels interleave round-robin before the cut)
        /// instead of letting a busy global consume all of it. That fairness
        /// takes no client parameter — the server binds its per-channel window
        /// to `limit` itself, so a quiet es/ru never wastes its slice. The
        /// response is globally ordered by created_at, so ONE fetch is already
        /// chronologically merged across channels.</summary>
        public static void FetchRecentChat(int limit = 50)
        {
            // Values come from a closed set ("global"/"es"/"ru"), so no
            // URL-encoding concern.
            string chans = ChatClient.DerivedChannelSet();
            int gen = System.Threading.Interlocked.Increment(ref chatRecentGen);
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/chat/recent?limit={limit}&channels={chans}",
                (success, response) =>
                {
                    if (gen != System.Threading.Volatile.Read(ref chatRecentGen))
                    {
                        // A newer fetch owns the pane now — this response
                        // would repopulate it with a stale snapshot.
                        Plugin.Log.LogInfo("[CHAT] Scrollback response superseded - dropped");
                        return;
                    }
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try
                    {
                        // Response: {"messages":[{"source":..., ...}, ...]}.
                        // STRING-AWARE slicing (wave-2 find 13 / #156): names
                        // and messages are user-authored — a literal "} in a
                        // name truncated the old '"}'-scan mid-object. The
                        // existing string-aware helpers do the walk properly.
                        int mStart = response.IndexOf("\"messages\"", StringComparison.Ordinal);
                        int arrStart = mStart >= 0 ? response.IndexOf('[', mStart) : -1;
                        int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(response, arrStart) : -1;
                        int n = 0;
                        if (arrStart >= 0 && arrEnd > arrStart)
                        {
                            foreach (string obj in SliceTopLevelObjects(
                                response.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                            {
                                n++;
                                try { ChatClient.OnMessage?.Invoke(obj); } catch { }
                            }
                        }
                        Plugin.Log.LogInfo($"[CHAT] Scrollback loaded: {n} messages");
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[CHAT] Scrollback parse error: {ex.Message}"); }
                }
            ));
        }


        /// <summary>DELETE all data associated with this Steam ID on the server.
        /// Signature: HMAC of "delete:{steam_id}". Server verifies with the shared secret.</summary>
        public static void DeletePlayerData(string steamId, Action<bool, string> callback)
        {
            if (string.IsNullOrEmpty(steamId)) { callback(false, "no-steam-id"); return; }
            string sig = ComputeHmacHex($"delete:{steamId}");
            string url = $"{baseUrl}/api/v1/players/{steamId}/data?sig={sig}";
            Plugin.Instance.StartCoroutine(DoDelete(url, callback));
        }

        private static IEnumerator DoDelete(string url, Action<bool, string> callback)
        {
            using (var request = UnityWebRequest.Delete(url))
            {
                request.downloadHandler = new DownloadHandlerBuffer();
                string sentToken = SteamAuth.SessionToken;
                StampVersionHeader(request);
                request.timeout = 20;
                yield return request.SendWebRequest();
                bool success = request.result == UnityWebRequest.Result.Success;
                // Codex review find: the delete endpoint is now session-gated;
                // a 401 here must invalidate the stale token like every other
                // gated call so the next attempt re-mints instead of failing
                // with the same dead token until natural expiry.
                if (!success) HandleSessionReject(request, sentToken);
                callback(success, success ? (request.downloadHandler?.text ?? "") : request.error);
            }
        }

