                    FetchMySubmissions(steamId);
                }
                callback?.Invoke(ok, id, resp);
            }));
        }

        /// <summary>Admin: lazy per-submission frame fetch for the animated
        /// review preview (frames 2..N; frame 1 rides the list row).
        /// Codex r1 f11: PAGED — metadata first (frame numbers + byte sizes),
        /// then one frame per request SEQUENTIALLY, each on its own 20s GET
        /// timeout, appended to the cache as it lands. A 16-frame submission
        /// near the image cap is ~24 MB of base64; one response used to blow
        /// the fixed GET timeout on slow links and make it unreviewable.</summary>
        public static readonly Dictionary<int, List<string>> CachedCosmeticFrames =
            new Dictionary<int, List<string>>();
        public class CosmeticFrameProgressInfo
        {
            public int total;      // extra frames the server holds (2..N)
            public int fetched;    // how many have landed so far
            public bool done;      // sequence finished (possibly partial)
            public bool failed;    // a frame failed twice — partial result
        }
        public static readonly Dictionary<int, CosmeticFrameProgressInfo> CosmeticFrameProgress =
            new Dictionary<int, CosmeticFrameProgressInfo>();
        private static readonly HashSet<int> _cosmeticFramesRequested = new HashSet<int>();
        public static void FetchCosmeticFrames(string adminSteamId, int submissionId)
        {
            if (submissionId <= 0 || _cosmeticFramesRequested.Contains(submissionId)) return;
            _cosmeticFramesRequested.Add(submissionId);
            // One signature covers the whole submission — frame_no is a
            // sub-selector of the signed target, not new authority (server
            // contract note at admin_cosmetic_frames).
            string sig = ComputeAdminHmacHex($"admin:{adminSteamId}:cosmetic-frames:{submissionId}");
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/admin/cosmetic-frames?admin_steam_id={Escape(adminSteamId)}"
                + $"&submission_id={submissionId}&sig={sig}",
                (ok, resp) =>
                {
                    if (!ok) { _cosmeticFramesRequested.Remove(submissionId); return; }
                    try
                    {
                        var frameNos = new List<int>();
                        int arr = resp.IndexOf("\"frames\"", StringComparison.Ordinal);
                        int open = arr >= 0 ? resp.IndexOf('[', arr) : -1;
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (close > open)
                            foreach (var obj in SliceTopLevelObjects(resp.Substring(open, close - open + 1)))
                            {
                                int fn = ExtractJsonInt(obj, "frame_no");
                                if (fn >= 2) frameNos.Add(fn);
                            }
                        frameNos.Sort();
                        CachedCosmeticFrames[submissionId] = new List<string>();
                        CosmeticFrameProgress[submissionId] = new CosmeticFrameProgressInfo
                        { total = frameNos.Count, done = frameNos.Count == 0 };
                        if (frameNos.Count > 0)
                            Plugin.Instance.StartCoroutine(
                                FetchCosmeticFramesSequential(adminSteamId, submissionId, sig, frameNos));
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[COSMETIC] frames metadata parse: {ex.Message}"); }
                }));
        }

        private static IEnumerator FetchCosmeticFramesSequential(
            string adminSteamId, int submissionId, string sig, List<int> frameNos)
        {
            CosmeticFrameProgressInfo st;
            if (!CosmeticFrameProgress.TryGetValue(submissionId, out st)) yield break;
            foreach (int fn in frameNos)
            {
                bool got = false;
                for (int attempt = 0; attempt < 2 && !got; attempt++)
                {
                    bool ok = false; string body = null;
                    yield return GetRequest(
                        $"{baseUrl}/api/v1/admin/cosmetic-frames?admin_steam_id={Escape(adminSteamId)}"
                        + $"&submission_id={submissionId}&frame_no={fn}&sig={sig}",
                        (o, r) => { ok = o; body = r; });
                    if (ok && !string.IsNullOrEmpty(body))
                    {
                        string b64 = ExtractJsonString(body, "png_base64");
                        if (!string.IsNullOrEmpty(b64))
                        {
                            List<string> frames;
                            if (!CachedCosmeticFrames.TryGetValue(submissionId, out frames))
                                yield break;   // dropped (review closed a fetch-reset path)
                            frames.Add(b64);
                            st.fetched++;
                            got = true;
                            NativeUI.MarkDirty();
                        }
                    }
                }
                if (!got)
                {
                    // One retry spent — stop here and show what arrived (a
                    // contiguous prefix keeps the cycle coherent; skipping a
                    // MIDDLE frame would scramble the animation order).
                    Plugin.Log.LogWarning($"[COSMETIC] frame {fn} of submission {submissionId} failed twice — showing {st.fetched}/{st.total} extra frames");
                    st.failed = true;
                    break;
                }
            }
            st.done = true;
            NativeUI.MarkDirty();
        }

        private static CosmeticSubmission ParseCosmeticSubmissionObject(string chunk)
        {
            var s = new CosmeticSubmission();
            s.id = ExtractJsonInt(chunk, "id");
            s.name = ExtractJsonString(chunk, "name");
            s.slot = ExtractJsonString(chunk, "slot");
            s.status = ExtractJsonString(chunk, "status");
            s.frame_count = Math.Max(1, ExtractJsonInt(chunk, "frame_count"));
            s.anim_fps = ExtractJsonFloat(chunk, "anim_fps");
            s.review_note = ExtractJsonString(chunk, "review_note");
            s.shop_sku = ExtractJsonString(chunk, "shop_sku");
            s.artist_steam_id = ExtractJsonString(chunk, "artist_steam_id");
            s.artist_name = ExtractJsonString(chunk, "artist_name");
            s.render_scale = ExtractJsonFloat(chunk, "render_scale");
            if (s.render_scale <= 0f) s.render_scale = 1f;
            s.render_offset_x = ExtractJsonFloat(chunk, "render_offset_x");
            s.render_offset_y = ExtractJsonFloat(chunk, "render_offset_y");
            s.placement_revision = ExtractJsonInt(chunk, "placement_revision");
            if (s.placement_revision < 1) s.placement_revision = 1;
            s.placement_status = ExtractJsonString(chunk, "placement_status");
            s.placement_review_note = ExtractJsonString(chunk, "placement_review_note");
            s.review_kind = ExtractJsonString(chunk, "review_kind");
            s.approved_render_scale = ExtractJsonFloat(chunk, "approved_render_scale");
            s.approved_render_offset_x = ExtractJsonFloat(chunk, "approved_render_offset_x");
            s.approved_render_offset_y = ExtractJsonFloat(chunk, "approved_render_offset_y");
            s.approved_placement_revision = ExtractJsonInt(chunk, "approved_placement_revision");
            s.published_placement_revision = ExtractJsonInt(chunk, "published_placement_revision");
            s.created_at = ExtractJsonString(chunk, "created_at");
            s.png_base64 = ExtractJsonString(chunk, "png_base64");
            return s;
        }

        private static List<CosmeticSubmission> ParseCosmeticSubmissionArray(string json)
        {
            var list = new List<CosmeticSubmission>();
            if (string.IsNullOrEmpty(json)) return list;
            int key = json.IndexOf("\"submissions\":", StringComparison.Ordinal);
            int open = key >= 0 ? json.IndexOf('[', key) : -1;
            int close = open >= 0 ? FindMatchingBracketStringAware(json, open) : -1;
            if (open < 0 || close <= open) return list;
            foreach (var chunk in SliceTopLevelObjects(json.Substring(open + 1, close - open - 1)))
            {
                var s = ParseCosmeticSubmissionObject(chunk);
                if (s.id > 0) list.Add(s);
            }
            return list;
        }

        // [N1 client half] sessionAware: this is a PRIVATE per-artist read the
        // server now strict-session-gates (review notes, quota state), so a
        // stale token's 401 session_required must re-mint instead of
        // 401-looping until the ~23h expiry. N17's replica-lag worry is
        // REFUTED: /artist paths are never edge-routed to the standby (the
        // live allowlist routes only leaderboards/records/histories).
        public static void FetchMySubmissions(string steamId, Action<bool> callback = null)
        {
            string sig = ComputeHmacHex($"artist:{steamId}:my-submissions");
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/artist/my-submissions?steam_id={Escape(steamId)}&sig={sig}",
                (ok, resp) =>
                {
                    if (ok)
                    {
                        try
                        {
                            CachedMySubmissions = ParseCosmeticSubmissionArray(resp);
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[COSMETIC] my-subs parse: {ex.Message}"); }
                        NativeUI.MarkDirty();
                    }
                    callback?.Invoke(ok);
                }, sessionAware: true));
        }

        public static void FetchCosmeticSubmissionsAdmin(string adminSteamId, Action<bool, List<CosmeticSubmission>> callback)
        {
            string sig = ComputeAdminHmacHex($"admin:{adminSteamId}:cosmetic-subs:list");
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/admin/cosmetic-submissions?admin_steam_id={Escape(adminSteamId)}&sig={sig}",
                (ok, resp) =>
                {
                    var list = new List<CosmeticSubmission>();
