        {
            if (string.IsNullOrEmpty(adminSteamId) || string.IsNullOrEmpty(reportId) || string.IsNullOrEmpty(newStatus))
            { callback?.Invoke(false, "missing args"); return; }
            string sig = ComputeAdminHmacHex($"admin:{adminSteamId}:bug_reports_status:{reportId}");
            var sb = new System.Text.StringBuilder();
            sb.Append("{");
            sb.Append($"\"admin_steam_id\":\"{Escape(adminSteamId)}\"");
            sb.Append($",\"hmac_signature\":\"{sig}\"");
            sb.Append($",\"new_status\":\"{Escape(newStatus)}\"");
            if (!string.IsNullOrEmpty(comment))
                sb.Append($",\"comment\":\"{Escape(comment)}\"");
            sb.Append("}");
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/bug-reports/{reportId}/status", sb.ToString(),
                (ok, resp) => callback?.Invoke(ok, resp)));
        }

        // Manual JSON parsers (the existing pattern in this file: JsonUtility silently fails on nested arrays).
        private static List<FlaggedMatchEntry> ParseFlaggedMatches(string json)
        {
            var list = new List<FlaggedMatchEntry>();
            if (string.IsNullOrEmpty(json)) return list;
            // The array contains user-authored display names, so both its outer
            // boundary and object slicing must be string-aware (learning #156).
            int key = json.IndexOf("\"flags\":", StringComparison.Ordinal);
            int open = key >= 0 ? json.IndexOf('[', key) : -1;
            int close = open >= 0 ? FindMatchingBracketStringAware(json, open) : -1;
            if (open < 0 || close <= open) return list;
            foreach (var chunk in SliceTopLevelObjects(
                json.Substring(open + 1, close - open - 1)))
            {
                var e = new FlaggedMatchEntry();
                e.id = ExtractJsonString(chunk, "id");
                e.match_id = ExtractJsonString(chunk, "match_id");
                e.game_code = ExtractJsonString(chunk, "game_code");
                e.series_id = ExtractJsonString(chunk, "series_id");
                e.flag_reason = ExtractJsonString(chunk, "flag_reason");
                e.p1_name = ExtractJsonString(chunk, "p1_name");
                e.p2_name = ExtractJsonString(chunk, "p2_name");
                e.p1_steam_id = ExtractJsonString(chunk, "p1_steam_id");
                e.p2_steam_id = ExtractJsonString(chunk, "p2_steam_id");
                e.suspect_steam_text = ExtractJsonString(chunk, "suspect_steam_text");
                if (!string.IsNullOrEmpty(e.p1_steam_id)) e.player_steam_ids.Add(e.p1_steam_id);
                if (!string.IsNullOrEmpty(e.p2_steam_id)) e.player_steam_ids.Add(e.p2_steam_id);
                e.auto_invalidated = chunk.Contains("\"auto_invalidated\":true") || chunk.Contains("\"auto_invalidated\": true");
                e.match_invalidated = chunk.Contains("\"match_invalidated\":true") || chunk.Contains("\"match_invalidated\": true");
                e.is_ranked = chunk.Contains("\"is_ranked\":true") || chunk.Contains("\"is_ranked\": true");
                e.restoration_required = chunk.Contains("\"restoration_required\":true")
                    || chunk.Contains("\"restoration_required\": true");
                e.duration_seconds = ExtractJsonInt(chunk, "duration_seconds");
                e.discord_evidence_revision = ExtractJsonInt(
                    chunk, "discord_evidence_revision");
                e.duration_text = ExtractJsonString(chunk, "duration_text");
                e.review_action = ExtractJsonString(chunk, "review_action");
                e.match_invalidation_reason = ExtractJsonString(chunk, "match_invalidation_reason");
                e.created_at = ExtractJsonString(chunk, "created_at");
                e.score_summary = ExtractJsonString(chunk, "score_summary");
                e.cards_summary = ExtractJsonString(chunk, "cards_summary");
                e.point_progress = ExtractJsonString(chunk, "point_progress");
                e.evidence_summary = ExtractJsonString(chunk, "evidence_summary");
                e.telemetry_summary = ExtractJsonString(chunk, "telemetry_summary");
                e.connection_summary = ExtractJsonString(chunk, "connection_summary");
                e.match_context = ExtractJsonString(chunk, "match_context");
                if (!string.IsNullOrEmpty(e.id)) list.Add(e);
            }
            return list;
        }

        private static List<BannedUserEntry> ParseBannedUsers(string json)
        {
            var list = new List<BannedUserEntry>();
            if (string.IsNullOrEmpty(json)) return list;
            var parts = json.Split(new[] { "\"id\":\"" }, StringSplitOptions.None);
            for (int i = 1; i < parts.Length; i++)
            {
                var chunk = parts[i];
                int qend = chunk.IndexOf('"');
                if (qend < 0) continue;
                var e = new BannedUserEntry();
                e.id = chunk.Substring(0, qend);
                e.steam_id = ExtractJsonString(chunk, "steam_id");
                e.display_name = ExtractJsonString(chunk, "display_name");
                e.reason = ExtractJsonString(chunk, "reason");
                e.banned_by_steam_id = ExtractJsonString(chunk, "banned_by_steam_id");
                e.banned_at = ExtractJsonString(chunk, "banned_at");
                list.Add(e);
            }
            return list;
        }

        // ── Admin panel: roster, audit log, T-chat moderation (Aug 7) ─────────
        // Transport for the Admin tab's remaining surfaces. It lives here rather
        // than in NativeUI because ComputeAdminHmacHex, GetRequest/PostRequest and
        // baseUrl are private to this file — and baseUrl in particular holds the
        // session-scoped HTTPS fallback (#194), which a parallel transport would
        // silently miss for exactly the players whose endpoint probe failed.
        //
        // Canonicals are verified against the live handlers in main.py, not
        // transcribed: _admin_canonical is "admin:{admin}:{action}:{target}" and
        //   /admin/admins            -> action "admins_list",        target ""
        //   /admin/actions           -> action "admin_actions_list", target ""
        //   /chat/moderate/delete    -> action "chat_delete",        target "{message_id}"
        //   /chat/moderate/mute      -> action "chat_mute",          target "{steam}:{chan|all}"
        //   /chat/moderate/unmute    -> action "chat_unmute",        target "{steam}:{chan|all}"
        //   /chat/moderate/mutes     -> action "chat_mutes_list",    target ""
        //   /chat/moderate/mute-by-message -> action "chat_mute_msg",       target "{message_id}"
        //   /chat/moderate/bridge-unmute   -> action "chat_unmute_bridge",  target "{mute_id}"
        //   /chat/moderate/lockdown        -> action "chat_lockdown",       target "1"|"0"
        // A canonical that is one byte off is a silent 403 for every admin, so
        // any edit here needs re-reading the handler, not the comment.
        //
        // The three chat endpoints accept EITHER an admin HMAC (role "admin") or
        // a Steam session (role "moderator") — StampVersionHeader already carries
        // X-Session-Token, so signing unconditionally is correct: the server picks
        // the proof that matches the caller's role. Scope enforcement
        // (_chat_moderator_scope: a translation moderator is confined to their
        // languages) is deliberately NOT mirrored here; the refusal text is
        // surfaced verbatim instead.

        public class AdminUserEntry
        {
            public string steam_id, display_name, granted_by_steam_id, granted_by_name, granted_at, notes;
        }

        public class AdminActionEntry
        {
            public string id, admin_steam_id, admin_name, action, target_steam_id, target_name;
            public string target_match_id, target_series_id, created_at;
            // Raw JSONB blob, verbatim. Carries user-authored text (chat bodies,
            // ban reasons), so a renderer must treat it as hostile input.
            public string details;
        }

        public class ChatMuteEntry
        {
            public int id;
            // channel "" means EVERY channel — the server stores NULL for an
            // all-channels mute and the string readers below return "" for null.
            public string steam_id, display_name, channel, muted_by_steam_id, muted_by_name;
            public string reason, created_at, expires_at;
            public bool permanent;
        }

        /// <summary>Platform-identity mute (Twitch/YouTube/Discord chatter —
        /// chat-moderation design v3 S2). Server field is "mute_id", NOT "id",
        /// on purpose: it must never masquerade as a chat_mutes row (D1 F6),
        /// and the picker keys the two tables with distinct prefixes.</summary>
        public class BridgeMuteEntry
        {
            public int mute_id;
            public string platform, platform_user_id, platform_login, channel;
            public string display_name, muted_by, reason, created_at, expires_at;
            public bool permanent;
        }

        public static List<AdminUserEntry> CachedAdmins { get; private set; } = new List<AdminUserEntry>();
        public static List<AdminActionEntry> CachedAdminActions { get; private set; } = new List<AdminActionEntry>();
        public static int CachedAdminActionsTotal { get; private set; }
        public static List<ChatMuteEntry> CachedChatMutes { get; private set; } = new List<ChatMuteEntry>();
        public static List<BridgeMuteEntry> CachedBridgeMutes { get; private set; } = new List<BridgeMuteEntry>();
        // Last refusal text per surface, mirroring AdminQuarantineError: the fetch
        // callbacks are Action<bool>, so this is where a 403 explains itself.
        // Cleared on every success so a stale message can't outlive its cause.
        public static string AdminAdminsError { get; private set; } = "";
        public static string AdminActionsError { get; private set; } = "";
        public static string ChatMutesError { get; private set; } = "";
        // "Loaded" distinguishes an empty list from one that was never fetched —
        // without it the panel shows "no admins" before the first request lands.
        public static bool AdminAdminsLoaded { get; private set; }
        public static bool AdminActionsLoaded { get; private set; }
        public static bool ChatMutesLoaded { get; private set; }

        public static void FetchAdminAdmins(string adminSteamId, Action<bool> callback = null)
        {
            if (string.IsNullOrEmpty(adminSteamId)) { callback?.Invoke(false); return; }
            string sig = ComputeAdminHmacHex($"admin:{adminSteamId}:admins_list:");
            string url = $"{baseUrl}/api/v1/admin/admins"
                       + $"?admin_steam_id={UnityWebRequest.EscapeURL(adminSteamId)}"
                       + $"&hmac_signature={UnityWebRequest.EscapeURL(sig)}";
            Plugin.Instance.StartCoroutine(GetRequest(url, (ok, body) =>
            {
                if (!ok)
                {
                    AdminAdminsError = string.IsNullOrEmpty(body) ? "request failed" : body;
                    Plugin.Log.LogWarning($"[ADMIN] admins fetch failed: {Trunc120(body)}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(false);
                    return;
                }
                try
                {
                    CachedAdmins = ParseAdminUsers(body);
                    AdminAdminsLoaded = true;
                    AdminAdminsError = "";
                    Plugin.Log.LogInfo($"[ADMIN] admins: {CachedAdmins.Count}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(true);
                }
                catch (Exception ex)
                {
                    AdminAdminsError = "response parse failed";
                    Plugin.Log.LogWarning($"[ADMIN] admins parse: {ex.Message}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(false);
                }
            }, detailedErrors: true));
        }

        /// <summary>Page of the admin_actions audit log, newest first. `action` and
        /// `targetSteamId` are optional filters (empty = no filter). Bounds mirror
        /// the server's Query constraints so a slider overrun becomes a clamp
        /// rather than a 422 the admin has to decode.</summary>
        public static void FetchAdminActions(string adminSteamId, int limit, int offset,
            string action, string targetSteamId, Action<bool> callback = null)
        {
            if (string.IsNullOrEmpty(adminSteamId)) { callback?.Invoke(false); return; }
            limit = Mathf.Clamp(limit, 1, 200);
            offset = Mathf.Max(0, offset);
            action = ClampLen(action, 32);
            targetSteamId = ClampLen(targetSteamId, 20);
            string sig = ComputeAdminHmacHex($"admin:{adminSteamId}:admin_actions_list:");
            string url = $"{baseUrl}/api/v1/admin/actions"
                       + $"?admin_steam_id={UnityWebRequest.EscapeURL(adminSteamId)}"
                       + $"&hmac_signature={UnityWebRequest.EscapeURL(sig)}"
                       + $"&limit={limit}&offset={offset}"
                       + $"&action={UnityWebRequest.EscapeURL(action)}"
                       + $"&target_steam_id={UnityWebRequest.EscapeURL(targetSteamId)}";
            Plugin.Instance.StartCoroutine(GetRequest(url, (ok, body) =>
            {
                if (!ok)
                {
                    AdminActionsError = string.IsNullOrEmpty(body) ? "request failed" : body;
                    Plugin.Log.LogWarning($"[ADMIN] actions fetch failed: {Trunc120(body)}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(false);
                    return;
                }
                try
                {
                    CachedAdminActions = ParseAdminActions(body);
                    // `total` is a top-level sibling of the array; read it from the
                    // body AFTER the array has been sliced out of the way so a
                    // "total" key nested in someone's details blob can't win.
                    CachedAdminActionsTotal = ExtractJsonInt(StripArray(body, "actions"), "total");
                    AdminActionsLoaded = true;
                    AdminActionsError = "";
                    Plugin.Log.LogInfo($"[ADMIN] actions: {CachedAdminActions.Count} of {CachedAdminActionsTotal}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(true);
                }
                catch (Exception ex)
                {
                    AdminActionsError = "response parse failed";
                    Plugin.Log.LogWarning($"[ADMIN] actions parse: {ex.Message}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(false);
                }
            }, detailedErrors: true));
        }

        public static void FetchChatMutes(string steamId, Action<bool> callback = null)
        {
            if (string.IsNullOrEmpty(steamId)) { callback?.Invoke(false); return; }
            string sig = ComputeAdminHmacHex($"admin:{steamId}:chat_mutes_list:");
            string url = $"{baseUrl}/api/v1/chat/moderate/mutes"
                       + $"?steam_id={UnityWebRequest.EscapeURL(steamId)}"
                       + $"&hmac_signature={UnityWebRequest.EscapeURL(sig)}";
            Plugin.Instance.StartCoroutine(GetRequest(url, (ok, body) =>
            {
                if (!ok)
                {
                    ChatMutesError = string.IsNullOrEmpty(body) ? "request failed" : body;
                    Plugin.Log.LogWarning($"[CHAT-MOD] mutes fetch failed: {Trunc120(body)}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(false);
                    return;
                }
                try
                {
                    CachedChatMutes = ParseChatMutes(body);
                    CachedBridgeMutes = ParseBridgeMutes(body);
                    ChatMutesLoaded = true;
                    ChatMutesError = "";
                    Plugin.Log.LogInfo($"[CHAT-MOD] live mutes: {CachedChatMutes.Count} steam + {CachedBridgeMutes.Count} bridge");
                    NativeUI.MarkDirty();
                    callback?.Invoke(true);
                }
                catch (Exception ex)
                {
                    ChatMutesError = "response parse failed";
                    Plugin.Log.LogWarning($"[CHAT-MOD] mutes parse: {ex.Message}");
                    NativeUI.MarkDirty();
                    callback?.Invoke(false);
                }
            }, detailedErrors: true));
        }

        /// <summary>Soft-delete one T-chat message. Idempotent server-side (a second
        /// call re-broadcasts the retraction and returns already_deleted), so the
        /// caller never has to reason about a lost response.</summary>
        public static void AdminChatDelete(string steamId, int messageId, Action<bool, string> callback = null)
        {
            if (string.IsNullOrEmpty(steamId)) { callback?.Invoke(false, "missing steam id"); return; }
            // One invariant rendering feeds both the canonical and the body: the
            // server signs str(message_id), so the two must agree byte-for-byte,
            // and a locale-formatted number in the body would also be bad JSON.
            string mid = messageId.ToString(System.Globalization.CultureInfo.InvariantCulture);
            string sig = ComputeAdminHmacHex($"admin:{steamId}:chat_delete:{mid}");
            string body = $"{{\"steam_id\":\"{Escape(steamId)}\","
                        + $"\"message_id\":{mid},"
                        + $"\"hmac_signature\":\"{sig}\"}}";
            // Plain PostRequest, not PostRequestWithRetry: a moderation refusal is
            // a 403 the operator must see NOW, and the retry wrapper spends ~20s
            // re-sending a request the server has already judged (#252 — a 4xx
            // means "the server spoke", not "the transport may have dropped it").
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/chat/moderate/delete", body, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[CHAT-MOD] delete msg {mid}: ok={ok} resp={Trunc120(resp)}");
                callback?.Invoke(ok, resp);
            }));
        }

        /// <summary>Mute a steam_id. `channel` null/blank means EVERY channel, which
        /// the server allows only for admins; durationMinutes &lt;= 0 is permanent.
        /// `reason` is optional operator free text, stored on the mute row and in
        /// the admin audit log. It is last in the list so the existing call sites
        /// keep compiling.</summary>
        public static void AdminChatMute(string steamId, string targetSteamId, string channel,
            int durationMinutes, Action<bool, string> callback = null, string reason = "")
        {
            if (string.IsNullOrEmpty(steamId) || string.IsNullOrEmpty(targetSteamId))
            { callback?.Invoke(false, "missing steam id"); return; }
            string chan = NormalizeChatChannel(channel);
            // Clamp BEFORE escaping. The server stores `(reason or "")[:256]` in both
            // the mute row and the audit details, so anything past 256 is discarded
            // anyway — and cutting the ESCAPED form could slice a \uXXXX sequence in
            // half and hand the parser a malformed literal.
            string why = ClampLen(reason, 256);
            string sig = ComputeAdminHmacHex(
                $"admin:{steamId}:chat_mute:{targetSteamId}:{chan ?? "all"}");
            string body = "{"
                + $"\"steam_id\":\"{Escape(steamId)}\","
                + $"\"target_steam_id\":\"{Escape(targetSteamId)}\","
                + $"\"channel\":{(chan == null ? "null" : $"\"{Escape(chan)}\"")},"
                // Typed by a human, so JsonEscapeFull rather than Escape: one raw TAB
                // or console ESC byte makes FastAPI reject the whole request with a
                // 422 before validation ever runs (#100). Always a string and never
                // null — the server's field is a plain `str`, so null is a validation
                // error. Absent from the canonical
                // (`admin:{admin}:chat_mute:{target}:{channel|all}`), so no value here
                // can move the signature.
                + $"\"reason\":\"{JsonEscapeFull(why)}\","
                // Omitting a duration is how the server spells "permanent"; sending
                // 0 works too but null is the honest wire value for "no expiry".
                + $"\"duration_minutes\":{(durationMinutes > 0 ? durationMinutes.ToString(System.Globalization.CultureInfo.InvariantCulture) : "null")},"
                + $"\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/chat/moderate/mute", body, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[CHAT-MOD] mute {targetSteamId} in [{chan ?? "ALL"}] "
                                 + $"for {(durationMinutes > 0 ? durationMinutes + "m" : "ever")}: ok={ok} resp={Trunc120(resp)}");
                // Keep the mute list honest for the next panel open without making
                // the caller remember to refetch (mirrors AdminSetI18nGrant).
                if (ok) FetchChatMutes(steamId);
                callback?.Invoke(ok, resp);
            }));
        }

        /// <summary>Revoke mutes for a steam_id. `channel` null/blank clears every
        /// mute the CALLER is entitled to clear — all of them for an admin, only the
        /// moderator's own languages otherwise. The server decides that; we don't.</summary>
        public static void AdminChatUnmute(string steamId, string targetSteamId, string channel,
            Action<bool, string> callback = null)
        {
            if (string.IsNullOrEmpty(steamId) || string.IsNullOrEmpty(targetSteamId))
            { callback?.Invoke(false, "missing steam id"); return; }
            string chan = NormalizeChatChannel(channel);
            string sig = ComputeAdminHmacHex(
                $"admin:{steamId}:chat_unmute:{targetSteamId}:{chan ?? "all"}");
            string body = "{"
                + $"\"steam_id\":\"{Escape(steamId)}\","
                + $"\"target_steam_id\":\"{Escape(targetSteamId)}\","
                + $"\"channel\":{(chan == null ? "null" : $"\"{Escape(chan)}\"")},"
                + $"\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/chat/moderate/unmute", body, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[CHAT-MOD] unmute {targetSteamId} in [{chan ?? "their scope"}]: ok={ok} resp={Trunc120(resp)}");
                if (ok) FetchChatMutes(steamId);
                callback?.Invoke(ok, resp);
            }));
        }

        /// <summary>The unified mod verb (design v3 S6): mute the AUTHOR of one
        /// chat message on whatever platform it came from, purging their recent
        /// lines everywhere when `purge`. The server routes by the row's source
        /// and refuses unverifiable targets (an unverified in-game identity, a
        /// pre-263 bridged row) with a refusal this surfaces verbatim.</summary>
        public static void AdminChatMuteByMessage(string steamId, int messageId,
            int durationMinutes, string reason, bool purge, Action<bool, string> callback = null)
        {
            if (string.IsNullOrEmpty(steamId) || messageId <= 0)
            { callback?.Invoke(false, "missing target"); return; }
            string mid = messageId.ToString(System.Globalization.CultureInfo.InvariantCulture);
            string why = ClampLen(reason, 256);
            string sig = ComputeAdminHmacHex($"admin:{steamId}:chat_mute_msg:{mid}");
            string body = "{"
                + $"\"steam_id\":\"{Escape(steamId)}\","
                + $"\"message_id\":{mid},"
                + $"\"reason\":\"{JsonEscapeFull(why)}\","
                + $"\"purge\":{(purge ? "true" : "false")},"
                + $"\"duration_minutes\":{(durationMinutes > 0 ? durationMinutes.ToString(System.Globalization.CultureInfo.InvariantCulture) : "null")},"
                + $"\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/chat/moderate/mute-by-message", body, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[CHAT-MOD] mute-by-message #{mid}: ok={ok} resp={Trunc120(resp)}");
                if (ok) FetchChatMutes(steamId);
                callback?.Invoke(ok, resp);
            }));
        }

        /// <summary>Revoke one platform-identity (bridge) mute by its own row id.
        /// Distinct endpoint + canonical from the steam unmute — the two tables'
        /// ids are independent sequences and must never share a key (D1 F6).</summary>
        public static void AdminChatBridgeUnmute(string steamId, int muteId,
            Action<bool, string> callback = null)
        {
            if (string.IsNullOrEmpty(steamId) || muteId <= 0)
            { callback?.Invoke(false, "missing target"); return; }
            string mid = muteId.ToString(System.Globalization.CultureInfo.InvariantCulture);
            string sig = ComputeAdminHmacHex($"admin:{steamId}:chat_unmute_bridge:{mid}");
            string body = "{"
                + $"\"steam_id\":\"{Escape(steamId)}\","
                + $"\"mute_id\":{mid},"
                + $"\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/chat/moderate/bridge-unmute", body, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[CHAT-MOD] bridge unmute #{mid}: ok={ok} resp={Trunc120(resp)}");
                if (ok) FetchChatMutes(steamId);
                callback?.Invoke(ok, resp);
            }));
        }

        /// <summary>Whole-channel lockdown toggle (design v3 S7; admin only —
        /// the server enforces that, this just signs). The state lands back on
        /// every client through the WS lock frame, ChatClient.ChatLocked
        /// included, so there is nothing to set locally on success.</summary>
        public static void AdminChatLockdown(string steamId, bool locked,
            Action<bool, string> callback = null)
        {
            if (string.IsNullOrEmpty(steamId)) { callback?.Invoke(false, "missing steam id"); return; }
            string sig = ComputeAdminHmacHex($"admin:{steamId}:chat_lockdown:{(locked ? "1" : "0")}");
            string body = "{"
                + $"\"steam_id\":\"{Escape(steamId)}\","
                + $"\"locked\":{(locked ? "true" : "false")},"
                + $"\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/chat/moderate/lockdown", body, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[CHAT-MOD] lockdown={locked}: ok={ok} resp={Trunc120(resp)}");
                callback?.Invoke(ok, resp);
            }));
        }

        /// <summary>Byte-for-byte mirror of the server's own channel normalization
        /// (`(req.channel or "").lower().strip() or None`). The result feeds BOTH the
        /// HMAC canonical and the request body, so any divergence here is a 403 the
        /// admin cannot diagnose. Invariant casing on purpose — a Turkish locale
        /// would otherwise fold 'I' to a dotless 'ı' and break the signature (#47).</summary>
        private static string NormalizeChatChannel(string channel)
        {
            if (string.IsNullOrWhiteSpace(channel)) return null;
            return channel.Trim().ToLowerInvariant();
        }

        // Hard cut to a length limit. Distinct from Trunc(), which appends ".."
        // and would push a 32-char filter to 34 — straight past the server's
        // max_length and into a 422.
        private static string ClampLen(string s, int max) =>
            string.IsNullOrEmpty(s) ? "" : (s.Length > max ? s.Substring(0, max) : s);

        private static List<AdminUserEntry> ParseAdminUsers(string json)
        {
            var list = new List<AdminUserEntry>();
            if (string.IsNullOrEmpty(json)) return list;
            // display_name/notes are user-authored, so both the array boundary and
            // the entry slicing are string-aware (#156).
            if (!LocateArray(json, "admins", out int open, out int close)) return list;
            foreach (string chunk in SliceTopLevelObjects(json.Substring(open + 1, close - open - 1)))
            {
                var e = new AdminUserEntry
                {
                    steam_id = ExtractJsonString(chunk, "steam_id"),
                    display_name = ExtractJsonString(chunk, "display_name"),
                    granted_by_steam_id = ExtractJsonString(chunk, "granted_by_steam_id"),
                    granted_by_name = ExtractJsonString(chunk, "granted_by_name"),
                    granted_at = ExtractJsonString(chunk, "granted_at"),
                    notes = ExtractJsonString(chunk, "notes"),
                };
                if (!string.IsNullOrEmpty(e.steam_id)) list.Add(e);
            }
            return list;
        }

        private static List<AdminActionEntry> ParseAdminActions(string json)
        {
            var list = new List<AdminActionEntry>();
            if (string.IsNullOrEmpty(json)) return list;
            if (!LocateArray(json, "actions", out int open, out int close)) return list;
            foreach (string chunk in SliceTopLevelObjects(json.Substring(open + 1, close - open - 1)))
            {
                // `details` is a nested JSONB object whose keys collide with this
                // entry's own ("author_steam_id", "moderator_steam_id", "channel",
                // "reason"...). The scalar readers below are plain IndexOf lookups
                // with no notion of depth, so the blob has to come OUT of the chunk
                // before them — otherwise a details key wins whenever it appears
                // first, and the log renders another player's steam id as the target.
                string details = TakeNestedObject(chunk, "details", out string flat);
                var e = new AdminActionEntry
                {
                    id = ExtractJsonString(flat, "id"),
                    admin_steam_id = ExtractJsonString(flat, "admin_steam_id"),
                    admin_name = ExtractJsonString(flat, "admin_name"),
                    action = ExtractJsonString(flat, "action"),
                    target_steam_id = ExtractJsonString(flat, "target_steam_id"),
                    target_name = ExtractJsonString(flat, "target_name"),
                    target_match_id = ExtractJsonString(flat, "target_match_id"),
                    target_series_id = ExtractJsonString(flat, "target_series_id"),
                    created_at = ExtractJsonString(flat, "created_at"),
                    details = details,
                };
                if (!string.IsNullOrEmpty(e.id)) list.Add(e);
            }
            return list;
        }

        private static List<ChatMuteEntry> ParseChatMutes(string json)
        {
            var list = new List<ChatMuteEntry>();
            if (string.IsNullOrEmpty(json)) return list;
            if (!LocateArray(json, "mutes", out int open, out int close)) return list;
            foreach (string chunk in SliceTopLevelObjects(json.Substring(open + 1, close - open - 1)))
            {
                var e = new ChatMuteEntry
                {
                    id = ExtractJsonInt(chunk, "id"),
                    steam_id = ExtractJsonString(chunk, "steam_id"),
                    display_name = ExtractJsonString(chunk, "display_name"),
                    // Stays "" when the server sends null, which is precisely the
                    // all-channels mute — the reader can't match "channel":null.
                    channel = ExtractJsonString(chunk, "channel"),
                    muted_by_steam_id = ExtractJsonString(chunk, "muted_by_steam_id"),
                    muted_by_name = ExtractJsonString(chunk, "muted_by_name"),
                    reason = ExtractJsonString(chunk, "reason"),
                    created_at = ExtractJsonString(chunk, "created_at"),
                    expires_at = ExtractJsonString(chunk, "expires_at"),
                    permanent = ExtractJsonBool(chunk, "permanent"),
                };
                if (e.id > 0) list.Add(e);
            }
            return list;
        }

        /// <summary>Sibling of ParseChatMutes over the response's SEPARATE
        /// "bridge_mutes" array (design v3 Q4: a separate array is what keeps
        /// shipped parsers blind to these rows). Keyed on mute_id.</summary>
        private static List<BridgeMuteEntry> ParseBridgeMutes(string json)
        {
            var list = new List<BridgeMuteEntry>();
            if (string.IsNullOrEmpty(json)) return list;
            if (!LocateArray(json, "bridge_mutes", out int open, out int close)) return list;
            foreach (string chunk in SliceTopLevelObjects(json.Substring(open + 1, close - open - 1)))
            {
                var e = new BridgeMuteEntry
                {
                    mute_id = ExtractJsonInt(chunk, "mute_id"),
                    platform = ExtractJsonString(chunk, "platform"),
                    platform_user_id = ExtractJsonString(chunk, "platform_user_id"),
                    platform_login = ExtractJsonString(chunk, "platform_login"),
                    channel = ExtractJsonString(chunk, "channel"),
                    display_name = ExtractJsonString(chunk, "display_name"),
                    muted_by = ExtractJsonString(chunk, "muted_by"),
                    reason = ExtractJsonString(chunk, "reason"),
                    created_at = ExtractJsonString(chunk, "created_at"),
                    expires_at = ExtractJsonString(chunk, "expires_at"),
                    permanent = ExtractJsonBool(chunk, "permanent"),
                };
                if (e.mute_id > 0) list.Add(e);
            }
            return list;
        }

        /// <summary>Lift the object value of `key` out of `chunk`: returns it raw and
        /// writes the remainder — with the whole `"key":{...}` pair excised — to
        /// `rest`. That remainder is no longer valid JSON (it keeps a dangling
        /// comma), which is fine: every reader that consumes it is a substring
        /// lookup, not a parser. Returns "" (and `rest` unchanged) when the value is
        /// absent or null, so a NULL details column degrades to an empty blob.</summary>
        private static string TakeNestedObject(string chunk, string key, out string rest)
        {
            rest = chunk;
            if (string.IsNullOrEmpty(chunk)) return "";
            int k = FindKeyOutsideStrings(chunk, key);
            if (k < 0) return "";
            // Step past the `"key":` needle and demand a '{' right there rather than
            // scanning for the next one — with a null value that scan would happily
            // swallow an unrelated sibling object.
            int v = k + key.Length + 3;
            while (v < chunk.Length && (chunk[v] == ' ' || chunk[v] == '\t')) v++;
            if (v >= chunk.Length || chunk[v] != '{') return "";
            int close = FindMatchingBraceStringAware(chunk, v);
            if (close <= v) return "";
            rest = chunk.Remove(k, close - k + 1);
            return chunk.Substring(v, close - v + 1);
        }

        /// <summary>The body with `key`'s array removed, so a scalar reader can't be
        /// captured by a same-named key nested inside it.</summary>
        private static string StripArray(string json, string key)
        {
            if (string.IsNullOrEmpty(json)) return "";
            if (!LocateArray(json, key, out int open, out int close)) return json;
            return json.Remove(open, close - open + 1);
        }

        // ── Opponent ranked check ─────────────────────────────

        public static void CheckOpponentRanked(string steamId, Action<bool> callback)
        {
            if (string.IsNullOrEmpty(steamId) || steamId.StartsWith("photon_") || steamId == "unknown")
            {
                callback(false);
                return;
            }

            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/mod/check/{steamId}",
                (success, response) =>
                {
                    if (success)
                    {
                        try
                        {
                            var data = JsonUtility.FromJson<ModCheckResponse>(response);
                            // Item 4: matched against a mod-banned cheater → tell the
                            // player and leave the room. Treated as not-ranked so no
                            // series spins up around a ban-aborted match.
                            if (data.banned)
                            {
                                Plugin.Log.LogWarning($"[BAN] Opponent {steamId} is mod-banned ({data.ban_reason}) — leaving match");
                                CompetitiveUI.ShowNotification(
                                    "Your opponent is banned from the mod - leaving match.",
                                    new Color(1f, 0.3f, 0.3f), 8f);
                                try { if (Photon.Pun.PhotonNetwork.InRoom) Photon.Pun.PhotonNetwork.LeaveRoom(); }
                                catch (Exception ex) { Plugin.Log.LogWarning($"[BAN] LeaveRoom failed: {ex.Message}"); }
                                callback(false);
                                return;
                            }
                            bool isRanked = data.registered && data.ranked;
                            Plugin.Log.LogInfo($"Opponent ranked check: registered={data.registered}, ranked={data.ranked}");
                            callback(isRanked);
                        }
                        catch
                        {
                            callback(false);
                        }
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"Opponent rank check failed: {response}");
                        callback(false);
                    }
                }
            ));
        }

        // ── Match reporting ───────────────────────────────────

        public static void ReportMacroEvidence(
            string p1SteamId, string p2SteamId,
            int p1RoundsWon, int p2RoundsWon,
            string photonRoomId, DateTime matchStartedAt,
            int durationSeconds, bool sharedGameTokenUsed,
            string reporterSteamId,
            int suspectSeconds, int peakKps, int peakCps, int peakEps,
            string suspectTimeline)
        {
            if (suspectSeconds < 10 || string.IsNullOrEmpty(reporterSteamId)) return;
            string timeline = ClampTimeline(suspectTimeline, 1024);
            string roomHash = ComputeSha256Hex(photonRoomId ?? "");
            string startedAt = matchStartedAt.ToUniversalTime()
                .ToString(
                    "yyyy-MM-ddTHH:mm:ssZ",
                    System.Globalization.CultureInfo.InvariantCulture);
            string startedHash = ComputeSha256Hex(startedAt);
            string timelineHash = ComputeSha256Hex(timeline);
            string canonical =
                $"macro-evidence:{reporterSteamId}:{p1SteamId}:{p2SteamId}:"
                + $"{roomHash}:{startedHash}:{durationSeconds}:"
                + $"{(sharedGameTokenUsed ? 1 : 0)}:"
                + $"{p1RoundsWon}:{p2RoundsWon}:{suspectSeconds}:"
                + $"{peakKps}:{peakCps}:{peakEps}:{timelineHash}";
            string sig = ComputeHmacHex(canonical);
            string body =
                "{\"reporter_steam_id\":\"" + Escape(reporterSteamId) + "\""
                + ",\"p1_steam_id\":\"" + Escape(p1SteamId) + "\""
                + ",\"p2_steam_id\":\"" + Escape(p2SteamId) + "\""
                + ",\"p1_rounds_won\":" + p1RoundsWon
                + ",\"p2_rounds_won\":" + p2RoundsWon
                + ",\"photon_room_id\":\"" + Escape(photonRoomId) + "\""
                + ",\"match_started_at\":\"" + startedAt + "\""
                + ",\"duration_seconds\":" + durationSeconds
                + ",\"shared_game_token\":"
                + (sharedGameTokenUsed ? "true" : "false")
                + ",\"macro_suspect_seconds\":" + suspectSeconds
                + ",\"peak_keys_per_second\":" + peakKps
                + ",\"peak_clicks_per_second\":" + peakCps
                + ",\"peak_events_per_second\":" + peakEps
                + ",\"suspect_windows\":\"" + Escape(timeline) + "\""
                + ",\"hmac_signature\":\"" + sig + "\"}";
            string url = $"{baseUrl}/api/v1/matches/macro-evidence";
            // Persist before the first network yield so a quit, crash, or long
            // outage cannot erase the immutable evidence body.
            EnqueueFailedReport(url, body);
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                url, body,
                (ok, resp) =>
                {
                    if (ok)
                    {
                        RemovePendingReport(url, body);
                    }
                    else
                    {
                        Plugin.Log.LogWarning(
                            $"[INPUT] exact macro evidence was not attached: {Trunc120(resp)}");
                    }
                },
                maxRetries: 6, retryDelay: 2f));
        }

        public static void ReportMatch(
            string p1SteamId, string p1Name,
            string p2SteamId, string p2Name,
            int p1RoundsWon, int p2RoundsWon,
            int p1PointsTotal, int p2PointsTotal,
            List<MatchTracker.CardPickData> p1Cards,
            List<MatchTracker.CardPickData> p2Cards,
            List<MatchTracker.CardOfferData> p1Offers,
            List<MatchTracker.CardOfferData> p2Offers,
            string photonRoomId, string region,
            int durationSeconds, DateTime startedAt,
            string reporterSteamId, bool isRanked,
            // Anti-cheat: reporter's per-match input counts. Server flags reporter as
            // "inactive" if both are 0 across a non-trivial duration. NOT included in HMAC
            // (which is locked at exactly 7 fields) — these are advisory signals.
            int localShotsFired = 0, int localBlocksRaised = 0,
            // Hit% / Block% telemetry (v1.23). Same "advisory, not in HMAC" treatment — these
            // are stat counters on the reporter side that feed lifetime totals on the server.
            int localBulletsFired = 0, int localBulletsHit = 0,
            int localBlocksActivated = 0, int localBlocksSuccessful = 0,
            // v1.25 — average FPS this match. localAvgFps from our own counter, opponentAvgFps
            // sniffed from their Photon `cr_fps` custom property (0 = no data / no mod).
            int localAvgFps = 0, int opponentAvgFps = 0,
            // v1.29 — Compare-tab input-rate metrics (keys per active-combat second).
            int localKeysPressed = 0, float localActiveSeconds = 0f,
            // v1.29.1 (#50) — count of 1s windows whose combined gameplay key
            // and click rate was superhuman. Advisory, not in HMAC.
            int localMacroSuspectSeconds = 0,
            int localMacroPeakKps = 0, int localMacroPeakCps = 0,
            int localMacroPeakEps = 0, string localMacroTimeline = null,
            // Peer-carried copy of the non-reporting player's exact macro
            // evidence. Advisory and outside the immutable match HMAC.
            int oppMacroSuspectSeconds = 0,
            int oppMacroPeakKps = 0, int oppMacroPeakCps = 0,
            int oppMacroPeakEps = 0, string oppMacroTimeline = null,
            // v1.30 (item 4) — opponent's per-game combat stats (from their
            // cr_gstats Photon prop) + the cumulative scoring timeline
            // ("2:0,2:1,4:1,..." — rounds*2+points per event) for the history
            // hover graph. All advisory, not in HMAC.
            int oppBulletsFired = 0, int oppBulletsHit = 0,
            // #308 part 6. False => the peer's counters predate our counting
            // definition and are sent as null (unknown), never as 0 - a 0 here
            // is indistinguishable from "genuinely never fired" and would be
            // averaged into their career Hit% as a real observation.
            bool oppBulletStatsKnown = true,
            int oppBlocksActivated = 0, int oppBlocksSuccessful = 0,
            int oppKeysPressed = 0, float oppActiveSeconds = 0f,
            string pointTimeline = null,
            // July 21 item 2 — FPS/lag exploit telemetry. All advisory, not in
            // HMAC. Timelines are comma-int strings (own = 5s buckets, opp =
            // their 3s broadcast samples); freeze = main-thread stalls >0.5s
            // (focused resume = window-drag signature); recv gaps = our socket
            // silent >2s; opp hb gaps = their gstats heartbeat frozen >8s.
            string localFpsTimeline = null, string oppFpsTimeline = null,
            int localFreezeCount = 0, int localFreezeFocusedCount = 0,
            float localFreezeTotalSec = 0f,
            int localPingAvg = 0, int localPingMax = 0,
            int localRecvGapCount = 0, int localRecvGapMaxMs = 0,
            int oppHbGapCount = 0,
            int oppFreezeCount = 0, int oppFreezeFocusedCount = 0,
            int oppRecvGapCount = 0,
            // July 22 item 3 — latency timelines (own 3s samples; opp via
            // gstats field 12) + opp average for the history "Ping:" tag.
            string localPingTimeline = null, string oppPingTimeline = null,
            int oppPingAvg = 0,
            // July 22 item 1 — cumulative Hit%/Block% pair timelines
            // ("fired:hit,..." / "dmgTaken:blocksSucc,...", 3s cadence) +
            // per-point second stamps for the graph markers. Advisory.
            string localHitTimeline = null, string oppHitTimeline = null,
            string localBlockTimeline = null, string oppBlockTimeline = null,
            string pointTimes = null,
            // Aug 6 items 1+4 — expanded combat telemetry (advisory, not in
            // HMAC; the 7-field canonical is frozen). Damage timelines are
            // cumulative ints (own = 5s buckets, opp = their ~3s gstats
            // samples); deaths are the REPORTER's local observations of both
            // seats (every client simulates every death).
            float localDamageDealt = 0f, float oppDamageDealt = 0f,
            float localMaxSingleHit = 0f, float oppMaxSingleHit = 0f,
            float localMaxHealth = 0f, float oppMaxHealth = 0f,
            int localBestBounceKill = 0, int oppBestBounceKill = 0,
            string localDamageTimeline = null, string oppDamageTimeline = null,
            int localDeaths = 0, int localDeathsBoundary = 0, int localDeathsOwnBullet = 0,
            int oppDeaths = 0, int oppDeathsBoundary = 0, int oppDeathsOwnBullet = 0,
            // Aug 12 item 1 — each seat's end-of-game BUILD, as the 22-field
            // TabStatsOverlay wire string (TabStatsOverlay.CaptureBuildStats).
            // Positional by PLAYER SLOT, not viewer-relative: p1EndStats belongs
            // to p1SteamId. Null = not captured, which is a normal outcome and
            // simply omits the field. ADVISORY — rides outside the frozen
            // 7-field HMAC canonical below, which does not change for this.
            string p1EndStats = null, string p2EndStats = null)
        {
            if (RoomActors.LocalIsSpectator) return;   // spectator: never reports (design §3.5)
            // §2c identity fence: the broadcast account never reports, even if
            // some state bug ever leaves it looking like a fighter.
            if (BroadcastMode.FenceBlocksFighterPath("report-1v1")) return;
            var sb = new StringBuilder();
            sb.Append("{");
            sb.Append($"\"player1\":{{\"steam_id\":\"{Escape(p1SteamId)}\",\"display_name\":\"{Escape(p1Name)}\",\"cards\":[");
            AppendCards(sb, p1Cards);
            sb.Append("],\"card_offers\":[");
            AppendOffers(sb, p1Offers);
            sb.Append("]");
            AppendEndStats(sb, p1EndStats);
            sb.Append("},");
            sb.Append($"\"player2\":{{\"steam_id\":\"{Escape(p2SteamId)}\",\"display_name\":\"{Escape(p2Name)}\",\"cards\":[");
            AppendCards(sb, p2Cards);
            sb.Append("],\"card_offers\":[");
            AppendOffers(sb, p2Offers);
            sb.Append("]");
            AppendEndStats(sb, p2EndStats);
            sb.Append("},");
            sb.Append($"\"p1_rounds_won\":{p1RoundsWon},");
            sb.Append($"\"p2_rounds_won\":{p2RoundsWon},");
            sb.Append($"\"p1_points_total\":{p1PointsTotal},");
            sb.Append($"\"p2_points_total\":{p2PointsTotal},");
            sb.Append($"\"photon_room_id\":\"{Escape(photonRoomId)}\",");
            sb.Append($"\"game_version\":\"v{Application.version}\",");
            sb.Append($"\"region\":\"{Escape(region)}\",");
            sb.Append($"\"match_duration\":{durationSeconds},");
            sb.Append($"\"started_at\":\"{startedAt.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ", System.Globalization.CultureInfo.InvariantCulture)}\",");
            sb.Append($"\"is_ranked\":{(isRanked ? "true" : "false")},");
            sb.Append($"\"reported_by_steam_id\":\"{Escape(reporterSteamId)}\",");
            // Reporter's combat input counts for inactive-player anti-cheat. Server-side advisory.
            sb.Append($"\"local_shots_fired\":{localShotsFired},");
            sb.Append($"\"local_blocks_raised\":{localBlocksRaised},");
            // v1.23 Hit% / Block% per-match deltas; server aggregates into lifetime totals.
            sb.Append($"\"local_bullets_fired\":{localBulletsFired},");
            sb.Append($"\"local_bullets_hit\":{localBulletsHit},");
            sb.Append($"\"local_blocks_activated\":{localBlocksActivated},");
            sb.Append($"\"local_blocks_successful\":{localBlocksSuccessful},");
            sb.Append($"\"local_avg_fps\":{localAvgFps},");
            sb.Append($"\"opponent_avg_fps\":{opponentAvgFps},");
            // v1.29 input-rate metrics (advisory, not in HMAC). InvariantCulture so a
            // comma-decimal locale can't produce invalid JSON (learning #47 family).
            sb.Append($"\"local_keys_pressed\":{localKeysPressed},");
            sb.Append($"\"local_active_seconds\":{localActiveSeconds.ToString("F1", System.Globalization.CultureInfo.InvariantCulture)},");
            sb.Append($"\"local_macro_suspect_seconds\":{localMacroSuspectSeconds},");
            sb.Append($"\"local_macro_peak_kps\":{localMacroPeakKps},");
            sb.Append($"\"local_macro_peak_cps\":{localMacroPeakCps},");
            sb.Append($"\"local_macro_peak_eps\":{localMacroPeakEps},");
            sb.Append($"\"local_macro_timeline\":\"{Escape(ClampTimeline(localMacroTimeline, 1024))}\",");
            sb.Append($"\"opp_macro_suspect_seconds\":{oppMacroSuspectSeconds},");
            sb.Append($"\"opp_macro_peak_kps\":{oppMacroPeakKps},");
            sb.Append($"\"opp_macro_peak_cps\":{oppMacroPeakCps},");
            sb.Append($"\"opp_macro_peak_eps\":{oppMacroPeakEps},");
            sb.Append($"\"opp_macro_timeline\":\"{Escape(ClampTimeline(oppMacroTimeline, 1024))}\",");
            // v1.30 item 4 — opponent per-game stats + scoring timeline (advisory).
            // #308 part 6: `int | None` server-side with ge=0, so null is the
            // schema's own "unknown" and a negative sentinel would 422.
            sb.Append(oppBulletStatsKnown
                ? $"\"opp_bullets_fired\":{oppBulletsFired},"
                : "\"opp_bullets_fired\":null,");
            sb.Append(oppBulletStatsKnown
                ? $"\"opp_bullets_hit\":{oppBulletsHit},"
                : "\"opp_bullets_hit\":null,");
            sb.Append($"\"opp_blocks_activated\":{oppBlocksActivated},");
            sb.Append($"\"opp_blocks_successful\":{oppBlocksSuccessful},");
            sb.Append($"\"opp_keys_pressed\":{oppKeysPressed},");
            sb.Append($"\"opp_active_seconds\":{oppActiveSeconds.ToString("F1", System.Globalization.CultureInfo.InvariantCulture)},");
            sb.Append($"\"point_timeline\":\"{Escape(pointTimeline ?? "")}\",");
            // July 21 item 2 — FPS/lag telemetry (advisory, not in HMAC). Timelines
            // are self-generated digit/comma strings; clamp to the 512-char columns
            // COMMA-AWARE so the stored string never ends mid-number.
            string lft = ClampTimeline(localFpsTimeline);
            string oft = ClampTimeline(oppFpsTimeline);
            sb.Append($"\"local_fps_timeline\":\"{Escape(lft)}\",");
            sb.Append($"\"opp_fps_timeline\":\"{Escape(oft)}\",");
            sb.Append($"\"local_freeze_count\":{localFreezeCount},");
            sb.Append($"\"local_freeze_focused_count\":{localFreezeFocusedCount},");
            sb.Append($"\"local_freeze_total_sec\":{localFreezeTotalSec.ToString("F1", System.Globalization.CultureInfo.InvariantCulture)},");
            sb.Append($"\"local_ping_avg\":{localPingAvg},");
            sb.Append($"\"local_ping_max\":{localPingMax},");
            sb.Append($"\"local_recv_gap_count\":{localRecvGapCount},");
            sb.Append($"\"local_recv_gap_max_ms\":{localRecvGapMaxMs},");
            sb.Append($"\"opp_hb_gap_count\":{oppHbGapCount},");
            sb.Append($"\"opp_freeze_count\":{oppFreezeCount},");
            sb.Append($"\"opp_freeze_focused_count\":{oppFreezeFocusedCount},");
            sb.Append($"\"opp_recv_gap_count\":{oppRecvGapCount},");
            sb.Append($"\"local_ping_timeline\":\"{Escape(ClampTimeline(localPingTimeline))}\",");
            sb.Append($"\"opp_ping_timeline\":\"{Escape(ClampTimeline(oppPingTimeline))}\",");
            sb.Append($"\"opp_ping_avg\":{oppPingAvg},");
            // July 22 item 1 — hit/block pair timelines (1024-char columns) +
            // point-time stamps (512). Same digit/comma/colon-only wire shape.
            sb.Append($"\"local_hit_timeline\":\"{Escape(ClampTimeline(localHitTimeline, 1024))}\",");
            sb.Append($"\"opp_hit_timeline\":\"{Escape(ClampTimeline(oppHitTimeline, 1024))}\",");
            sb.Append($"\"local_block_timeline\":\"{Escape(ClampTimeline(localBlockTimeline, 1024))}\",");
            sb.Append($"\"opp_block_timeline\":\"{Escape(ClampTimeline(oppBlockTimeline, 1024))}\",");
            sb.Append($"\"point_times\":\"{Escape(ClampTimeline(pointTimes))}\",");
            // Aug 6 items 1+4 — expanded combat telemetry (advisory, not in HMAC).
            sb.Append($"\"local_damage_dealt\":{(int)localDamageDealt},");
            sb.Append($"\"opp_damage_dealt\":{(int)oppDamageDealt},");
            sb.Append($"\"local_max_single_hit\":{(int)localMaxSingleHit},");
            sb.Append($"\"opp_max_single_hit\":{(int)oppMaxSingleHit},");
            sb.Append($"\"local_max_health\":{(int)localMaxHealth},");
            sb.Append($"\"opp_max_health\":{(int)oppMaxHealth},");
            sb.Append($"\"local_best_bounce_kill\":{localBestBounceKill},");
            sb.Append($"\"opp_best_bounce_kill\":{oppBestBounceKill},");
            sb.Append($"\"local_damage_timeline\":\"{Escape(ClampTimeline(localDamageTimeline, 1024))}\",");
            sb.Append($"\"opp_damage_timeline\":\"{Escape(ClampTimeline(oppDamageTimeline, 1024))}\",");
            sb.Append($"\"local_deaths\":{localDeaths},");
            sb.Append($"\"local_deaths_boundary\":{localDeathsBoundary},");
            sb.Append($"\"local_deaths_own_bullet\":{localDeathsOwnBullet},");
            sb.Append($"\"opp_deaths\":{oppDeaths},");
            sb.Append($"\"opp_deaths_boundary\":{oppDeathsBoundary},");
            sb.Append($"\"opp_deaths_own_bullet\":{oppDeathsOwnBullet},");
            string sig = ComputeHmac(p1SteamId, p2SteamId, p1RoundsWon, p2RoundsWon, isRanked, reporterSteamId, photonRoomId);
            sb.Append($"\"hmac_signature\":\"{sig}\"");
            sb.Append("}");

            string json = sb.ToString();
            string matchType = isRanked ? "RANKED" : "CASUAL";
            Plugin.Log.LogInfo($"Reporting {matchType} match to API...");
            // r7 find 1: the game ended NOW, so BOTH the retirement and the
            // series-id clear happen HERE, synchronously — not in the report's
            // async callback. Applying them late let an old report's response
            // (up to 3 x 10s of retries) wipe an id the NEXT game had already
            // installed, and left a pre-boundary preflight response briefly
            // able to bind. Everything sent up to this instant belongs to the
            // game that just finished; anything sent after it survives.
            if (preflightGeneration > preflightRetiredThrough)
                preflightRetiredThrough = preflightGeneration;
            ActiveRankedSeriesId = null;

            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                $"{baseUrl}/api/v1/matches",
                json,
                (success, response) =>
                {
                    if (success)
                    {
                        Plugin.Log.LogInfo($"Match reported successfully: {response}");
                        RefreshAchievementsAfterReport();

                        // Parse XP from response
                        int xpGained = ExtractJsonInt(response, "xp_gained");
                        int newLevel = ExtractJsonInt(response, "level");
                        int totalXp = ExtractJsonInt(response, "total_xp");

                        // Track previous level for level-up detection
                        int prevLevel = CompetitiveUI.LastKnownLevel;

                        // Build XP notification with breakdown. July 20 item 6: parse the
                        // xp_bonuses array generically (same pattern as gold_bonuses below)
                        // instead of hardcoded Contains() checks — new server labels like
                        // "Master opp x2.5" display without a client release.
                        string xpLine = I18n.TrF("+{0} XP", xpGained);
                        var bonusParts = new List<string>();
                        int xpArrIdx = response.IndexOf("\"xp_bonuses\":");
                        if (xpArrIdx >= 0)
                        {
                            int xpOpen = response.IndexOf('[', xpArrIdx);
                            int xpClose = xpOpen >= 0 ? response.IndexOf(']', xpOpen) : -1;
                            if (xpOpen >= 0 && xpClose > xpOpen)
                            {
                                string xpBody = response.Substring(xpOpen + 1, xpClose - xpOpen - 1);
                                foreach (var seg in xpBody.Split(','))
                                {
                                    string s = seg.Trim().Trim('"').Trim();
                                    if (!string.IsNullOrEmpty(s)) bonusParts.Add(s);
                                }
                            }
                        }

                        if (bonusParts.Count > 0)
                            xpLine += "  [" + string.Join(", ", bonusParts.ToArray()) + "]";

                        CompetitiveUI.ShowNotification(xpLine, new Color(0.4f, 0.8f, 1f), 4f);

                        // Gold pop-up, queued after XP so they don't clobber each other.
                        int goldGained = ExtractJsonInt(response, "gold_gained");
                        if (goldGained > 0)
                        {
                            // Parse the gold_bonuses string array so labels like "XP +4" and
                            // "Series win +5" land in the notification with their actual numbers
                            // (old code was doing substring contains-matching and dropping the +N).
                            var parts = new List<string>();
                            int arrIdx = response.IndexOf("\"gold_bonuses\":");
                            if (arrIdx >= 0)
                            {
                                int open = response.IndexOf('[', arrIdx);
                                int close = open >= 0 ? response.IndexOf(']', open) : -1;
                                if (open >= 0 && close > open)
                                {
                                    string body = response.Substring(open + 1, close - open - 1);
                                    foreach (var seg in body.Split(','))
                                    {
                                        string s = seg.Trim().Trim('"').Trim();
                                        if (!string.IsNullOrEmpty(s)) parts.Add(s);
                                    }
                                }
                            }
                            string goldLine = I18n.TrF("+{0} gold", goldGained);
                            if (parts.Count > 0) goldLine += "  [" + string.Join(", ", parts.ToArray()) + "]";
                            CompetitiveUI.QueueNotification(goldLine, new Color(1f, 0.85f, 0.3f), 4f);
                        }

                        // Show level-up if we gained a level
                        if (newLevel > prevLevel && prevLevel >= 0)
                        {
                            CompetitiveUI.QueueNotification(I18n.TrF("LEVEL UP!  Level {0}", newLevel), new Color(1f, 0.85f, 0.3f), 4f);
                        }
                        CompetitiveUI.LastKnownLevel = newLevel;

                        FetchPlayerStats(MatchTracker.LocalSteamId);
                        FetchMatchHistory(MatchTracker.LocalSteamId);

                        // Series notifications and Glicko trigger
                        if (isRanked)
                        {
                            string seriesStatus = ExtractJsonString(response, "series_status");
                            string seriesScore = ExtractJsonString(response, "series_score");

                            // (live-points reporting for the finished game is
                            // irrelevant — bets are locked by series_wins > 0.
                            // ActiveRankedSeriesId was already cleared at the
                            // synchronous game boundary above; clearing it
                            // HERE would wipe an id the next game installed
                            // while this response was in flight — r7 find 1.)

                            if (seriesStatus == "active")
                            {
                                CompetitiveUI.QueueNotification(I18n.TrF("Series: {0}", seriesScore), new Color(1f, 0.85f, 0.3f), 3f);
                            }
                            else if (seriesStatus == "completed")
                            {
                                CompetitiveUI.QueueNotification(I18n.TrF("SERIES COMPLETE {0}!", seriesScore), new Color(0.3f, 1f, 0.3f), 4f);
                                // Increment the session series tally. The series winner is
                                // whoever won this final reported game (a BO_n first-to-N
                                // ends on the deciding game), so map reporter-perspective
                                // win to local-perspective win and bump the right counter.
                                try
                                {
                                    string mySid = MatchTracker.LocalSteamId;
                                    bool meIsP1 = !string.IsNullOrEmpty(mySid) && mySid == p1SteamId;
                                    bool meWon = meIsP1 ? (p1RoundsWon > p2RoundsWon) : (p2RoundsWon > p1RoundsWon);
                                    GameStateWatcher.IncrementSessionRankedSeries(meWon);
                                }
                                catch (Exception ex) { Plugin.Log.LogWarning($"[SESSION] series tally update failed: {ex.Message}"); }
                                // Regicide is now handled server-side after series completion
                                GameStateWatcher.pendingRegicideCheck = false;
                            }
                        }
                    }
                    else
                    {
                        Plugin.Log.LogError($"Failed to report match: {response}");
                        CompetitiveUI.ShowNotification("Couldn't record the match", Color.red);
                        // Bug #65: transient network/DNS outages outlive the 3 immediate
                        // attempts — queue for background retry instead of losing the game.
                        EnqueueFailedReport($"{baseUrl}/api/v1/matches", json);
                    }
                }
            ));
        }

        private static void AppendCards(StringBuilder sb, List<MatchTracker.CardPickData> cards)
        {
            for (int i = 0; i < cards.Count; i++)
            {
                if (i > 0) sb.Append(",");
                var c = cards[i];
                sb.Append("{");
                sb.Append($"\"card_name\":\"{Escape(c.CardName)}\",");
                sb.Append($"\"card_rarity\":\"{Escape(c.CardRarity ?? "Unknown")}\",");
                sb.Append($"\"pick_order\":{c.PickOrder},");
                sb.Append($"\"round_number\":{c.RoundNumber}");
                if (c.Rolled) sb.Append(",\"rolled\":true");
                sb.Append("}");
            }
        }

        private static void AppendOffers(StringBuilder sb, List<MatchTracker.CardOfferData> offers)
        {
            if (offers == null) return;
            for (int i = 0; i < offers.Count; i++)
            {
                if (i > 0) sb.Append(",");
                var o = offers[i];
                sb.Append("{");
                sb.Append($"\"card_name\":\"{Escape(o.CardName)}\",");
                sb.Append($"\"round_number\":{o.RoundNumber},");
                sb.Append($"\"was_picked\":{(o.WasPicked ? "true" : "false")}");
                sb.Append("}");
            }
        }

        /// <summary>Server bound on the end-of-game build string (schemas.py
        /// END_STATS_MAX_LEN / main.py _END_STATS_MAX_LEN, both 300).
        ///
        /// This one matters more than a normal advisory bound: Pydantic's
        /// max_length runs on the REQUEST MODEL, before _clean_end_stats ever
        /// sees the value, so an over-length build 422s the ENTIRE match report
        /// — the field is optional, the report is not.
        ///
        /// It is NOT reachable as the code stands, and this comment used to
        /// claim it was (Codex round-2 LOW, and the stale number is the whole
        /// reason the round-1 review raised a CRITICAL that did not exist).
        /// TabStatsOverlay.WIRE_FIELD_MAX is 12 — the widest field the server's
        /// anchored _END_STATS_RE accepts (sign + 7 integer digits + point + 3
        /// decimals) — so the capture side's structural worst case is
        /// 1 + 21 * (1 + 12) = 274 chars, and the two ends agree by
        /// construction rather than by coincidence.
        ///
        /// The check below therefore stays as a fail-closed guard on ONE
        /// specific future change: widening WIRE_FIELD_MAX (or adding wire
        /// fields) without widening the server's regex and column. Do not
        /// delete it because 274 < 300 today, and do not widen either side
        /// alone.</summary>
        private const int EndStatsMaxLen = 300;

        /// <summary>Append `,"end_stats":"…"` to a player object that already
        /// has at least one field written (every caller does — steam_id is
        /// always first), or append NOTHING.
        ///
        /// Omitted rather than sent empty when there is no capture: the server
        /// stores absent and null identically as "not recorded", and "" would be
        /// a third state meaning the same thing (#257).
        ///
        /// Over-length is ALSO dropped rather than truncated. The format is
        /// POSITIONAL, so a cut corrupts every field after it and produces
        /// confidently mislabelled history instead of no history — and sending
        /// it whole would take the whole report down with it (see the constant).
        /// This is the last point that knows the server's contract, so the guard
        /// belongs here and not in the capture code.</summary>
        private static void AppendEndStats(StringBuilder sb, string wire)
        {
            if (string.IsNullOrEmpty(wire)) return;
            if (wire.Length > EndStatsMaxLen)
            {
                Plugin.Log.LogWarning(
                    $"[TABSTATS] end_stats {wire.Length} chars > {EndStatsMaxLen} server bound - omitted from report");
                return;
            }
            sb.Append($",\"end_stats\":\"{Escape(wire)}\"");
        }

        // ── Data fetching ─────────────────────────────────────

        // limit 100 → 500 (v1.29): with 105 ranked players the top-100 fetch cut
        // the bottom of the board off. The tab already pages locally at 100/page.
        public static void FetchLeaderboard(int limit = 500, int minMatches = 1)
        {
            IsLoading = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/leaderboard?limit={limit}&min_matches={minMatches}",
                (success, response) =>
                {
                    IsLoading = false;
                    if (success)
                    {
                        try
                        {
                            // Manual parse — JsonUtility silently fails on this structure
                            var data = new LeaderboardData();
                            data.total_players = ExtractJsonInt(response, "total_players");

                            var entries = new List<LeaderboardEntry>();
                            var parts = response.Split(new[] { "\"rank\"" }, StringSplitOptions.None);

                            for (int i = 1; i < parts.Length; i++)
                            {
                                var chunk = parts[i];
                                var entry = new LeaderboardEntry();

                                // rank is right after the split point: :1,
                                try
                                {
                                    int colonIdx = chunk.IndexOf(':');
                                    if (colonIdx < 0) colonIdx = -1;
                                    int commaIdx = chunk.IndexOf(',', colonIdx + 1);
                                    if (colonIdx >= 0 && commaIdx > colonIdx)
                                    {
                                        string rankStr = chunk.Substring(colonIdx + 1, commaIdx - colonIdx - 1).Trim();
                                        entry.rank = int.Parse(rankStr);
                                    }
                                }
                                catch { entry.rank = i; }

                                entry.steam_id = ExtractJsonString(chunk, "steam_id");
                                entry.display_name = ExtractJsonString(chunk, "display_name");
                                entry.rating = ExtractJsonInt(chunk, "rating");
                                entry.rd = ExtractJsonInt(chunk, "rd");
                                entry.total_matches = ExtractJsonInt(chunk, "total_matches");
                                entry.wins = ExtractJsonInt(chunk, "wins");
                                entry.losses = ExtractJsonInt(chunk, "losses");

                                // Parse win_rate as float
                                try
                                {
                                    int wrIdx = chunk.IndexOf("\"win_rate\":");
                                    if (wrIdx >= 0)
                                    {
                                        wrIdx += "\"win_rate\":".Length;
                                        while (wrIdx < chunk.Length && chunk[wrIdx] == ' ') wrIdx++;
                                        int wrEnd = wrIdx;
                                        while (wrEnd < chunk.Length && (char.IsDigit(chunk[wrEnd]) || chunk[wrEnd] == '.' || chunk[wrEnd] == '-'))
                                            wrEnd++;
                                        if (wrEnd > wrIdx)
                                            entry.win_rate = float.Parse(chunk.Substring(wrIdx, wrEnd - wrIdx),
                                                System.Globalization.CultureInfo.InvariantCulture);
                                    }
                                }
                                catch { entry.win_rate = 0f; }

                                entry.level = ExtractJsonInt(chunk, "level");
                                entry.gold = ExtractJsonInt(chunk, "gold");
                                entry.title = ExtractJsonString(chunk, "title");
                                entry.title_color = ExtractJsonString(chunk, "title_color");
                                entry.rank_name = ExtractJsonString(chunk, "rank_name");
                                entry.rank_color = ExtractJsonString(chunk, "rank_color");

                                if (!string.IsNullOrEmpty(entry.steam_id))
                                    entries.Add(entry);
                            }

                            data.entries = entries.ToArray();
                            CachedLeaderboard = data;
                            Plugin.Log.LogInfo($"Leaderboard loaded: {CachedLeaderboard.entries?.Length ?? 0} entries");
                            // Repaint on every fresh fetch. NativeUI.Tick's auto dirty-flip
                            // only compares entry COUNT, so a same-size board with new
                            // ratings never re-rendered (part of the stale-leaderboard-tab
                            // report) — mark dirty explicitly.
                            NativeUI.MarkDirty();
                        }
                        catch (Exception ex)
                        {
                            Plugin.Log.LogError($"Failed to parse leaderboard: {ex.Message}");
                            LastError = "Failed to parse leaderboard data";
                        }
                    }
                    else
                    {
                        LastError = $"Failed to fetch leaderboard: {response}";
                        Plugin.Log.LogError(LastError);
                    }
                }
            ));
        }

        public static void FetchRecentSeries(int limit = 100)
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/series/recent?minutes=10080&limit={limit}",
                (success, response) =>
                {
                    if (success)
                    {
                        try
                        {
                            var list = new List<RecentSeriesEntry>();
                            var parts = response.Split(new[] { "\"series_id\"" }, StringSplitOptions.None);
                            for (int i = 1; i < parts.Length && list.Count < limit; i++)
                            {
                                var e = new RecentSeriesEntry();
                                e.winner_name = ExtractJsonString(parts[i], "winner_name");
                                e.p1_name = ExtractJsonString(parts[i], "p1_name");
                                e.p2_name = ExtractJsonString(parts[i], "p2_name");
                                e.p1_wins = ExtractJsonInt(parts[i], "p1_series_wins");
                                e.p2_wins = ExtractJsonInt(parts[i], "p2_series_wins");
                                e.winner_steam_id = ExtractJsonString(parts[i], "winner_steam_id");
                                e.p1_steam_id = ExtractJsonString(parts[i], "p1_steam_id");
                                e.p2_steam_id = ExtractJsonString(parts[i], "p2_steam_id");
                                // Parse rating changes as float
                                try{int rc1=parts[i].IndexOf("\"p1_rating_change\":");if(rc1>=0){rc1+="\"p1_rating_change\":".Length;int rc1e=rc1;while(rc1e<parts[i].Length&&(char.IsDigit(parts[i][rc1e])||parts[i][rc1e]=='.'||parts[i][rc1e]=='-'))rc1e++;if(rc1e>rc1)e.p1_rating_change=float.Parse(parts[i].Substring(rc1,rc1e-rc1),System.Globalization.CultureInfo.InvariantCulture);}}catch{}
                                try{int rc2=parts[i].IndexOf("\"p2_rating_change\":");if(rc2>=0){rc2+="\"p2_rating_change\":".Length;int rc2e=rc2;while(rc2e<parts[i].Length&&(char.IsDigit(parts[i][rc2e])||parts[i][rc2e]=='.'||parts[i][rc2e]=='-'))rc2e++;if(rc2e>rc2)e.p2_rating_change=float.Parse(parts[i].Substring(rc2,rc2e-rc2),System.Globalization.CultureInfo.InvariantCulture);}}catch{}
                                e.p1_rating = ExtractJsonInt(parts[i], "p1_rating");
                                e.p2_rating = ExtractJsonInt(parts[i], "p2_rating");
                                // Merge key for the multi-mode Recent panel: the
                                // server has always sent this, the client just
                                // never read it.
                                e.completed_at = ExtractJsonString(parts[i], "completed_at");
                                // Parse the bets array. Server inlines a 'bets' list into each series — each entry has
                                // bettor_name / amount / payout / bet_on_name / won. We isolate this series's bets chunk
                                // (from "bets" up to the next "series_id" boundary) so we don't accidentally pull bets
                                // from later series in the response.
                                int betsKey = parts[i].IndexOf("\"bets\":");
                                if (betsKey >= 0)
                                {
                                    int betsStart = parts[i].IndexOf('[', betsKey);
                                    // String-aware: a display name containing ']'
                                    // truncated the block and silently dropped
                                    // every bet after it (#156 family).
                                    int betsEnd = betsStart >= 0
                                        ? FindMatchingBracketStringAware(parts[i], betsStart) : -1;
                                    if (betsStart >= 0 && betsEnd > betsStart)
                                    {
                                        string betsBlock = parts[i].Substring(betsStart, betsEnd - betsStart + 1);
                                        var betChunks = betsBlock.Split(new[] { "\"bettor_name\":" }, StringSplitOptions.None);
                                        for (int bi = 1; bi < betChunks.Length; bi++)
                                        {
                                            string chunk = "\"bettor_name\":" + betChunks[bi];
                                            var b = new SeriesBetEntry();
                                            b.bettor_name = ExtractJsonString(chunk, "bettor_name");
                                            b.bettor_steam_id = ExtractJsonString(chunk, "bettor_steam_id");
                                            b.bet_on_name = ExtractJsonString(chunk, "bet_on_name");
                                            b.bet_on_steam_id = ExtractJsonString(chunk, "bet_on_steam_id");
                                            b.amount = ExtractJsonInt(chunk, "amount");
                                            b.payout = ExtractJsonInt(chunk, "payout");
                                            b.odds_multiplier = ExtractJsonFloat(chunk, "odds_multiplier");
                                            b.won = chunk.Contains("\"won\":true") || chunk.Contains("\"won\": true");
                                            if (!string.IsNullOrEmpty(b.bettor_name)) e.bets.Add(b);
                                        }
                                    }
                                }
                                if (!string.IsNullOrEmpty(e.p1_name)) list.Add(e);
                            }
                            CachedRecentSeries = list;
                            Plugin.Log.LogInfo($"Recent series loaded: {list.Count}");
                            NativeUI.MarkDirty();
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"Recent series parse error: {ex.Message}"); }
                    }
                }
            ));
        }

        // Signature of the last cosmetic set we pushed to Photon — publish only on change.
        private static string _lastPublishedCosmeticSig;

        private static string BuildCosmeticSig(PlayerStatsData s)
        {
            if (s == null) return "";
            try
            {
                return string.Join("|", new[]
                {
                    s.active_trail_sku ?? "", s.active_trail_color ?? "",
                    s.active_player_color_sku ?? "", s.active_player_color_hex ?? "",
                    s.active_player_effect_sku ?? "",
                    s.active_cursor_color_sku ?? "", s.active_cursor_color_hex ?? "",
                    s.active_title ?? "", s.active_title_color ?? "",
                    s.display_name ?? "",
                    s.active_nametag_skus != null ? string.Join(",", s.active_nametag_skus) : "",
                });
            }
            catch { return Guid.NewGuid().ToString(); } // never block a publish on a sig failure
        }

        /// <summary>Force the next stats refresh to republish cosmetics (used by the
        /// shop equip paths so a just-equipped item still pushes immediately).</summary>
        public static void InvalidateCosmeticSig() { _lastPublishedCosmeticSig = null; }

        public static void FetchPlayerStats(string steamId, bool force = false)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            if (!force && IsLoading) return; // Don't stack requests

            IsLoading = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}",
                (success, response) =>
                {
                    IsLoading = false;
                    if (success)
                    {
                        try
                        {
                            CachedPlayerStats = JsonUtility.FromJson<PlayerStatsData>(response);
                            // JsonUtility can't handle nested arrays / List<string>, so manually
                            // parse the fields it skipped — including active_nametag_skus which
                            // the Shop + NametagStyler both read.
                            ParseTopCards(CachedPlayerStats, response);
                            Plugin.Log.LogInfo($"Player stats loaded for {CachedPlayerStats.display_name}");
                            // Re-publish Photon cosmetic props when they CHANGED (v1.29,
                            // F5-lag fix). Every stats refresh used to fire 5 publishes —
                            // SetCustomProperties + NickName each broadcast to every
                            // client in the room, so opening the menu mid-match caused a
                            // visible network blip on the OPPONENT's side too. Photon
                            // player props persist for the room lifetime and the
                            // room-join hooks republish on entry, so identical
                            // re-publishes add nothing.
                            // Spectator: publishes NOTHING to the watched room
                            // (Codex r1 find 13 — a stats refresh mid-session
                            // was re-publishing cosmetic props).
                            string cosmeticSig = RoomActors.LocalIsSpectator
                                ? _lastPublishedCosmeticSig
                                : BuildCosmeticSig(CachedPlayerStats);
                            if (cosmeticSig != _lastPublishedCosmeticSig)
                            {
                                _lastPublishedCosmeticSig = cosmeticSig;
                                try { TrailCosmetic.PublishLocalProps(); } catch { }
                                try { PlayerColorCosmetic.PublishLocalProps(); } catch { }
                                try { PlayerEffectCosmetic.PublishLocalProps(); } catch { }
                                // Cursor color is local-only — re-apply the tinted hardware cursor.
                                try { CursorColorCosmetic.ApplyFromStats(); } catch { }
                                // Re-publish nametag styles into LocalPlayer.NickName too.
                                try { NametagStyler.PublishToPhoton(); } catch { }
                            }
                        }
                        catch (Exception ex)
                        {
                            Plugin.Log.LogError($"Failed to parse player stats: {ex.Message}");
                        }
                    }
                    else if (!response.Contains("404"))
                    {
                        Plugin.Log.LogError($"Failed to fetch player stats: {response}");
                    }
                }
            ));
        }


        /// <summary>
        /// Fetch stats for any player by Steam ID, with a callback.
        /// Used when clicking a player in the leaderboard.
        /// Does NOT overwrite CachedPlayerStats (that's the local player's).
        /// viewerSteamId (broadcast W7): overrides the viewer used for the
        /// server-side H2H — the spectator seat needs fighter-vs-fighter
        /// counts, not fighter-vs-broadcast-account. Null = local viewer
        /// (every pre-existing caller).
        /// </summary>
        public static void FetchPlayerStatsForView(string steamId, Action<PlayerStatsData> callback, string viewerSteamId = null)
        {
            if (string.IsNullOrEmpty(steamId))
            {
                callback(null);
                return;
            }

            // Pass the viewer so the server can compute head-to-head counts
            // (h2h_* wins = the VIEWER's wins over the subject — verified
            // against main.py's :vid FILTER). Falls back to no viewer
            // (no H2H) when the ID isn't resolved yet.
            string viewer = !string.IsNullOrEmpty(viewerSteamId) ? viewerSteamId : MatchTracker.LocalSteamId;
            string viewerQ = (!string.IsNullOrEmpty(viewer) && viewer != "unknown" && viewer != steamId)
                ? $"?viewer_steam_id={Escape(viewer)}"
                : "";
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}{viewerQ}",
                (success, response) =>
                {
                    if (success)
                    {
                        try
                        {
                            var data = JsonUtility.FromJson<PlayerStatsData>(response);
                            // Manually parse top_cards (JsonUtility can't handle nested arrays)
                            ParseTopCards(data, response);
                            callback(data);
                        }
                        catch
                        {
                            callback(null);
                        }
                    }
                    else
                    {
                        callback(null);
                    }
                }
            ));
        }

        // ── Head-to-head pair cache (broadcast W7 / spectator HUD) ─────────
        // Keyed by "min|max" of the two steam ids (ordinal), so either
        // argument order hits the same entry. The stored PlayerStatsData is
        // oriented h2h_* wins = the VIEWER param's wins over the subject
        // (main.py :vid FILTER); subjectId/viewerId ride in the tuple so a
        // renderer can re-orient to its own on-screen fighter order without
        // trusting data.steam_id round-trips.
        private const float H2H_CACHE_TTL = 300f;
        private const float H2H_REFETCH_FLOOR = 30f;
        private static readonly Dictionary<string, (float at, string subjectId, string viewerId, PlayerStatsData data)> _h2hCache
            = new Dictionary<string, (float, string, string, PlayerStatsData)>();
        // Last fetch ATTEMPT per pair (success or not) — the poll-side floor.
        // Separate from the cache so a failing pair can't hammer (#98 family:
        // the budget must not tick per render, only per attempt window).
        private static readonly Dictionary<string, float> _h2hAttemptAt = new Dictionary<string, float>();
        private static readonly HashSet<string> _h2hInFlight = new HashSet<string>();

        // Bug #272: pairs whose cached H2H is known to be out of date, with the
        // earliest realtime at which re-fetching them is worthwhile.
        //
        // Nothing used to invalidate _h2hCache at all, so the spectator's
        // "Overall Series" sat up to H2H_CACHE_TTL (300s) behind while the
        // "Session Series" beside it stepped instantly — Sid's "-1 behind",
        // every time, for five minutes. The fighters' own HUD does not have
        // this problem because OnSeriesCompletedVsOpponent bumps CachedOppLifetime
        // in place; a SPECTATOR is a third party to both fighters and never calls
        // it, so it needs its own signal (SpectatorViewState.RecordSessionSeries).
        //
        // The DELAY is the same lesson OnSeriesCompletedVsOpponent already
        // records: the deciding /matches report can still be in the retry outbox
        // when the spectator observes the score change, so an immediate refetch
        // reads the PRE-commit count and would cache the wrong value for another
        // full TTL — turning a 5-minute wrong into a 10-minute wrong. Waiting a
        // few seconds costs nothing because the stale value keeps rendering.
        private static readonly Dictionary<string, float> _h2hDirtyAfter = new Dictionary<string, float>();
        // 90s, matching OnSeriesCompletedVsOpponent's own window rather than the
        // 20s this first shipped with. Review find (HIGH): the deciding /matches
        // report can succeed on its THIRD attempt at ~34s, or later still out of
        // the retry outbox. Refetching at 20s reads the PRE-commit count and
        // re-stamps it with a fresh timestamp — leaving the spectator one behind
        // for another full 300s TTL, i.e. strictly worse than doing nothing.
        // Stale-for-90s beats wrong-for-390s, and the cached value keeps
        // rendering throughout either way.
        private const float H2H_DIRTY_DELAY = 90f;

        /// <summary>Mark a pair's cached head-to-head stale (bug #272). Does NOT
        /// drop the entry: the renderer keeps showing the old number until a
        /// fresh one lands, because a briefly-wrong value beats the segment
        /// blinking out — and the existing design rule here is "never a wrong
        /// number" only in the sense of never showing an UNFETCHED one.</summary>
        public static void MarkHeadToHeadStale(string a, string b)
        {
            if (string.IsNullOrEmpty(a) || a == "unknown"
                || string.IsNullOrEmpty(b) || b == "unknown" || a == b) return;
            _h2hDirtyAfter[H2HKeyFor(a, b)] = Time.realtimeSinceStartup + H2H_DIRTY_DELAY;
        }

        private static string H2HKeyFor(string a, string b)
            => string.CompareOrdinal(a, b) <= 0 ? a + "|" + b : b + "|" + a;

        /// <summary>Thin wrapper over FetchPlayerStatsForView(subject, cb,
        /// viewer) that fills the pair cache. cb receives null on any
        /// failure. Guards mirror the underlying fetch: both ids resolved,
        /// distinct.</summary>
        public static void FetchHeadToHead(string subjectSteamId, string viewerSteamId, Action<PlayerStatsData> cb)
        {
            if (string.IsNullOrEmpty(subjectSteamId) || subjectSteamId == "unknown"
                || string.IsNullOrEmpty(viewerSteamId) || viewerSteamId == "unknown"
                || subjectSteamId == viewerSteamId || Plugin.Instance == null)
            { cb?.Invoke(null); return; }
            string key = H2HKeyFor(subjectSteamId, viewerSteamId);
            // When this fetch STARTED, so its success callback can tell whether it
            // is entitled to clear the staleness mark (bug #272, review find 2).
            float fetchStartedAt = Time.realtimeSinceStartup;
            _h2hAttemptAt[key] = fetchStartedAt;
            if (!_h2hInFlight.Add(key)) { cb?.Invoke(null); return; }
            try
            {
                FetchPlayerStatsForView(subjectSteamId, data =>
                {
                    _h2hInFlight.Remove(key);
                    // Failures are NOT cached — the attempt stamp alone floors the
                    // retry, and a stale-but-good entry keeps rendering meanwhile.
                    if (data != null)
                    {
                        _h2hCache[key] = (Time.realtimeSinceStartup, subjectSteamId, viewerSteamId, data);
                        // Clear the staleness mark only when THIS fetch is
                        // entitled to. Success alone is not enough (review find
                        // 2): an entry can hit the ordinary 300s TTL and be
                        // refetched by the normal expiry path DURING the 90s
                        // settlement window, succeed, and return the PRE-commit
                        // count — then unconditionally dropping the mark would
                        // stamp that wrong value fresh and hold it for another
                        // full TTL. Same for a fetch already in flight when
                        // MarkHeadToHeadStale lands. A fetch may only clear a
                        // mark it started at or after.
                        if (!_h2hDirtyAfter.TryGetValue(key, out float dueAt) || fetchStartedAt >= dueAt)
                            _h2hDirtyAfter.Remove(key);
                    }
                    try { cb?.Invoke(data); } catch { }
                }, viewerSteamId);
            }
            catch
            {
                // A synchronous throw (coroutine host died between the guard
                // and the call) must not strand the in-flight latch — the
                // 30s floor still bounds the retry (#367: latch needs an owner).
                _h2hInFlight.Remove(key);
                try { cb?.Invoke(null); } catch { }
            }
        }

        /// <summary>Poll-cheap cache read for the spectator HUD: returns the
        /// pair's stats (oriented wins = the entry's VIEWER id — compare
        /// against data.steam_id / the stored ids to re-orient) or null when
        /// absent/stale. A null return self-arms: at most one background
        /// fetch per pair per 30s, single in-flight guard, so the HUD can
        /// call this every frame and converge without its own fetch logic.</summary>
        public static PlayerStatsData TryGetCachedHeadToHead(string a, string b)
        {
            if (string.IsNullOrEmpty(a) || a == "unknown"
                || string.IsNullOrEmpty(b) || b == "unknown" || a == b) return null;
            string key = H2HKeyFor(a, b);
            float now = Time.realtimeSinceStartup;
            if (_h2hCache.TryGetValue(key, out var e) && now - e.at < H2H_CACHE_TTL)
            {
                // Bug #272: a fresh-by-TTL entry can still be known-stale. Kick a
                // refresh off once the settle delay has passed, but KEEP RETURNING
                // the cached value — blanking the segment for a round trip would
                // be a worse regression than being one behind for a few seconds.
                if (_h2hDirtyAfter.TryGetValue(key, out float dirtyAfter) && now >= dirtyAfter
                    && !_h2hInFlight.Contains(key)
                    && (!_h2hAttemptAt.TryGetValue(key, out float lastTry) || now - lastTry >= H2H_REFETCH_FLOOR))
                {
                    // Do NOT clear the dirty mark here. Review find (MEDIUM):
                    // clearing on DISPATCH meant a fetch that timed out or errored
                    // took the only record of staleness with it, and the entry —
                    // still fresh by TTL — then served the old number for the
                    // remaining ~280s with nothing left to retry it. The mark is
                    // cleared in FetchHeadToHead's success path instead, and
                    // H2H_REFETCH_FLOOR bounds the retry rate meanwhile.
                    FetchHeadToHead(a, b, null);
                }
                return e.data;
            }
            if (!_h2hInFlight.Contains(key)
                && (!_h2hAttemptAt.TryGetValue(key, out float at) || now - at >= H2H_REFETCH_FLOOR))
                FetchHeadToHead(a, b, null);
            return null;
        }

        private static void ParseTopCards(PlayerStatsData data, string response)
        {
            data.top_card_names = new List<string>();
            data.top_card_picks = new List<int>();
            data.top_card_win_rates = new List<float>();
            data.recent_form = new List<string>();
            data.worst_card_names = new List<string>();
            data.worst_card_picks = new List<int>();
            data.worst_card_win_rates = new List<float>();
            data.region_names = new List<string>();
            data.region_matches = new List<int>();
            try
            {
                int tcStart = response.IndexOf("\"top_cards\"");
                if (tcStart >= 0)
                {
                    int arrStart = response.IndexOf("[", tcStart);
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    if (arrStart >= 0 && arrEnd >= 0)
                    {
                        string arr = response.Substring(arrStart, arrEnd - arrStart + 1);
                        if (arr != "[]")
                        {
                            var cardParts = arr.Split(new[] { "\"card_name\"" }, StringSplitOptions.None);
                            for (int i = 1; i < cardParts.Length && i <= 10; i++)
                            {
                                string name = ExtractJsonString(cardParts[i], "");
                                int picks = ExtractJsonInt(cardParts[i], "times_picked");
                                float wr = 0f;
                                try
                                {
                                    int wrIdx = cardParts[i].IndexOf("\"win_rate\":");
                                    if (wrIdx >= 0)
                                    {
                                        wrIdx += "\"win_rate\":".Length;
                                        while (wrIdx < cardParts[i].Length && cardParts[i][wrIdx] == ' ') wrIdx++;
                                        int wrEnd = wrIdx;
                                        while (wrEnd < cardParts[i].Length && (char.IsDigit(cardParts[i][wrEnd]) || cardParts[i][wrEnd] == '.' || cardParts[i][wrEnd] == '-')) wrEnd++;
                                        if (wrEnd > wrIdx)
                                            wr = float.Parse(cardParts[i].Substring(wrIdx, wrEnd - wrIdx), System.Globalization.CultureInfo.InvariantCulture);
                                    }
                                }
                                catch { }
                                if (!string.IsNullOrEmpty(name))
                                {
                                    data.top_card_names.Add(name);
                                    data.top_card_picks.Add(picks);
                                    data.top_card_win_rates.Add(wr);
                                }
                            }
                        }
                    }
                }
            }
            catch { }

            // Parse worst_cards (same shape as top_cards: card_name/times_picked/win_rate).
            try
            {
                int wcStart = response.IndexOf("\"worst_cards\"");
                if (wcStart >= 0)
                {
                    int arrStart = response.IndexOf("[", wcStart);
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    if (arrStart >= 0 && arrEnd >= 0)
                    {
                        string arr = response.Substring(arrStart, arrEnd - arrStart + 1);
                        if (arr != "[]")
                        {
                            var cardParts = arr.Split(new[] { "\"card_name\"" }, StringSplitOptions.None);
                            for (int i = 1; i < cardParts.Length && i <= 10; i++)
                            {
                                string name = ExtractJsonString(cardParts[i], "");
                                int picks = ExtractJsonInt(cardParts[i], "times_picked");
                                float wr = ExtractJsonFloat(cardParts[i], "win_rate");
                                if (!string.IsNullOrEmpty(name))
                                {
                                    data.worst_card_names.Add(name);
                                    data.worst_card_picks.Add(picks);
                                    data.worst_card_win_rates.Add(wr);
                                }
                            }
                        }
                    }
                }
            }
            catch { }

            // Parse region_breakdown ([{region, matches}]).
            try
            {
                int rbStart = response.IndexOf("\"region_breakdown\"");
                if (rbStart >= 0)
                {
                    int arrStart = response.IndexOf("[", rbStart);
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    if (arrStart >= 0 && arrEnd >= 0)
                    {
                        string arr = response.Substring(arrStart, arrEnd - arrStart + 1);
                        if (arr != "[]")
                        {
                            var parts = arr.Split(new[] { "\"region\"" }, StringSplitOptions.None);
                            for (int i = 1; i < parts.Length; i++)
                            {
                                string reg = ExtractJsonString(parts[i], "");
                                int matches = ExtractJsonInt(parts[i], "matches");
                                if (!string.IsNullOrEmpty(reg))
                                {
                                    data.region_names.Add(reg);
                                    data.region_matches.Add(matches);
                                }
                            }
                        }
                    }
                }
            }
            catch { }

            // Parse recent_form
            try
            {
                int rfStart = response.IndexOf("\"recent_form\"");
                if (rfStart >= 0)
                {
                    int arrStart = response.IndexOf("[", rfStart);
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    if (arrStart >= 0 && arrEnd >= 0)
                    {
                        string arr = response.Substring(arrStart, arrEnd - arrStart + 1);
                        if (arr != "[]")
                        {
                            var parts = arr.Split(new[] { "\"result\"" }, StringSplitOptions.None);
                            for (int i = 1; i < parts.Length; i++)
                            {
                                string result = ExtractJsonString(parts[i], "");
                                if (!string.IsNullOrEmpty(result))
                                    data.recent_form.Add(result);
                            }
                        }
                    }
                }
            }
            catch { }

            // Parse active_color_skus — flat string array of equipped map-color skus.
            data.active_color_skus = new List<string>();
            try
            {
                // String-aware property lookup, not a raw IndexOf: a player whose display
                // name is literally `active_color_skus` would otherwise be matched as the
                // property and shadow the real one (Codex r5 #7).
                int arrStart = FindJsonArrayStartStringAware(response, "active_color_skus");
                int csStart = arrStart;
                if (csStart >= 0)
                {
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    bool ownArray = arrStart >= 0;
                    if (ownArray && arrStart >= 0 && arrEnd >= 0 && arrEnd > arrStart)
                    {
                        data.active_color_skus_present = true;   // the server really answered
                        string arr = response.Substring(arrStart + 1, arrEnd - arrStart - 1);
                        int cursor = 0;
                        while (cursor < arr.Length)
                        {
                            int q1 = arr.IndexOf('"', cursor);
                            if (q1 < 0) break;
                            int q2 = arr.IndexOf('"', q1 + 1);
                            if (q2 < 0) break;
                            string sku = arr.Substring(q1 + 1, q2 - q1 - 1);
                            if (!string.IsNullOrEmpty(sku)) data.active_color_skus.Add(sku);
                            cursor = q2 + 1;
                        }
                    }
                }
            }
            catch { }

            // Parse active_nametag_skus — flat string array, one entry per active rich-text style.
            data.active_nametag_skus = new List<string>();
            try
            {
                int ntStart = response.IndexOf("\"active_nametag_skus\"");
                if (ntStart >= 0)
                {
                    int arrStart = response.IndexOf("[", ntStart);
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    if (arrStart >= 0 && arrEnd >= 0 && arrEnd > arrStart)
                    {
                        string arr = response.Substring(arrStart + 1, arrEnd - arrStart - 1);
                        int cursor = 0;
                        while (cursor < arr.Length)
                        {
                            int q1 = arr.IndexOf('"', cursor);
                            if (q1 < 0) break;
                            int q2 = arr.IndexOf('"', q1 + 1);
                            if (q2 < 0) break;
                            string sku = arr.Substring(q1 + 1, q2 - q1 - 1);
                            if (!string.IsNullOrEmpty(sku)) data.active_nametag_skus.Add(sku);
                            cursor = q2 + 1;
                        }
                    }
                }
            }
            catch { }

            // Parse recent_rating_history (rating + snapshot date per entry).
            data.rating_history = new List<float>();
            data.rating_history_times = new List<float>();
            ParseRatingSeries(response, "recent_rating_history", data.rating_history, data.rating_history_times);
            // Aug 7: the FFA rating series, same entry shape and therefore the
            // same parser. Every rated FFA game snapshots rating_after, so the
            // game rows ARE the history — there is no rating_history table for it.
            data.ffa_rating_history = new List<float>();
            data.ffa_rating_history_times = new List<float>();
            ParseRatingSeries(response, "ffa_rating_history", data.ffa_rating_history, data.ffa_rating_history_times);
            Plugin.Log.LogInfo($"[STATS] Parsed {data.rating_history.Count} 1v1 + {data.ffa_rating_history.Count} FFA rating history points for {data.display_name} (oldest→newest, 1500 baseline prepended)");

            /* Aug 6 item 1: re-read the three nullable career records. JsonUtility
             * has already written 0 for a JSON null, which would render as a real
             * "0 damage biggest hit" instead of "never recorded" (#257 / #2 — match
             * the client default to the server's intended semantics). RECORD_NONE
             * is the only value a render site may treat as "no data". */
            data.record_max_single_hit = ExtractNullableInt(response, "record_max_single_hit");
            data.record_max_health     = ExtractNullableInt(response, "record_max_health");
            data.record_bounce_kill    = ExtractNullableInt(response, "record_bounce_kill");
        }

        /// <summary>Parse one `[{"rating":…, <timestamp>:…}, …]` rating series into
        /// a parallel (rating, days-since-2020-01-01) pair, then prepend the 1500
        /// baseline point. ONE implementation for the 1v1 and FFA series on
        /// purpose: the compare graph indexes the two output lists in lockstep, so
        /// two hand-copied parsers drifting apart would render an off-by-one lie
        /// rather than an obviously missing point.</summary>
        private static void ParseRatingSeries(string response, string jsonKey,
                                              List<float> ratings, List<float> times)
        {
            try
            {
                int rhStart = response.IndexOf($"\"{jsonKey}\"");
                if (rhStart >= 0)
                {
                    int arrStart = response.IndexOf("[", rhStart);
                    int arrEnd = FindMatchingBracket(response, arrStart);
                    if (arrStart >= 0 && arrEnd >= 0)
                    {
                        string arr = response.Substring(arrStart, arrEnd - arrStart + 1);
                        if (arr != "[]")
                        {
                            var epoch = new DateTime(2020, 1, 1, 0, 0, 0, DateTimeKind.Utc);
                            float lastT = 0f;
                            var parts = arr.Split(new[] { "\"rating\"" }, StringSplitOptions.None);
                            for (int i = 1; i < parts.Length; i++)
                            {
                                // extract number after ":"
                                int colonIdx = parts[i].IndexOf(':');
                                if (colonIdx >= 0)
                                {
                                    int vStart = colonIdx + 1;
                                    while (vStart < parts[i].Length && parts[i][vStart] == ' ') vStart++;
                                    int vEnd = vStart;
                                    while (vEnd < parts[i].Length && (char.IsDigit(parts[i][vEnd]) || parts[i][vEnd] == '.' || parts[i][vEnd] == '-')) vEnd++;
                                    if (vEnd > vStart)
                                    {
                                        float val = float.Parse(parts[i].Substring(vStart, vEnd - vStart), System.Globalization.CultureInfo.InvariantCulture);
                                        ratings.Add(val);
                                        // Snapshot date → fractional days since 2020-01-01 (the
                                        // "Elo over time" x-axis). Missing/bad date → nudge past
                                        // the previous point so the lists stay parallel.
                                        float t = lastT + 0.01f;
                                        try
                                        {
                                            // The 1v1 entries key the timestamp "date"; the FFA
                                            // ones carry BOTH "recorded_at" (the contract name)
                                            // and "date". Try the contract name first so a future
                                            // server that drops the "date" alias still plots.
                                            string ds = ExtractJsonString(parts[i], "recorded_at");
                                            if (string.IsNullOrEmpty(ds)) ds = ExtractJsonString(parts[i], "date");
                                            if (!string.IsNullOrEmpty(ds))
                                            {
                                                var dt = DateTime.Parse(ds, System.Globalization.CultureInfo.InvariantCulture,
                                                    System.Globalization.DateTimeStyles.AdjustToUniversal | System.Globalization.DateTimeStyles.AssumeUniversal);
                                                t = (float)(dt - epoch).TotalDays;
                                            }
                                        }
                                        catch { }
                                        lastT = t;
                                        times.Add(t);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            catch { }
            // Server returns ASC (oldest → newest) since v1.26.8. Do NOT reverse —
            // the old reverse call was a v1.26.7-era hack that made the graph plot
            // right-to-left after the server switched ordering, AND made the "current
            // Elo" label read the OLDEST rating instead of the newest.
            //
            // Prepend 1500 as a synthetic first point so the graph starts at every
            // player's initial rating instead of wherever their first recorded series
            // happened to land. This matches user expectation ("shouldn't it start at
            // 1500 for everyone?") and turns the first slope into a meaningful "your
            // first series gain/loss from baseline" visualization. 1500 is the default
            // for the FFA ladder too (glicko_ratings_ffa.rating DEFAULT 1500), so the
            // same baseline is correct for both series.
            if (ratings.Count > 0 && ratings[0] != 1500f)
            {
                ratings.Insert(0, 1500f);
                // Keep the time axis parallel: baseline sits one day before the
                // first real snapshot.
                if (times.Count > 0)
                    times.Insert(0, times[0] - 1f);
            }
        }

        /// <summary>Read an `int | None` JSON field: the integer when present,
        /// <see cref="RECORD_NONE"/> when the key is absent or literally null.
        /// Deliberately NOT a JsonUtility field — JsonUtility collapses null to 0
        /// and the whole point here is telling those two apart.</summary>
        private static int ExtractNullableInt(string json, string key)
        {
            try
            {
                int k = json.IndexOf($"\"{key}\":", StringComparison.Ordinal);
                if (k < 0) return RECORD_NONE;
                int i = k + key.Length + 3;
                while (i < json.Length && json[i] == ' ') i++;
                if (i >= json.Length) return RECORD_NONE;
                if (json[i] == 'n') return RECORD_NONE;   // null
                int start = i;
                if (json[i] == '-') i++;
                while (i < json.Length && char.IsDigit(json[i])) i++;
                if (i <= start) return RECORD_NONE;
                return int.TryParse(json.Substring(start, i - start),
                    System.Globalization.NumberStyles.Integer,
                    System.Globalization.CultureInfo.InvariantCulture, out int v) ? v : RECORD_NONE;
            }
            catch { return RECORD_NONE; }
        }

        // ── Selected player achievements (for LB detail) ─────────

        public static Dictionary<string, AchievementData> SelectedPlayerAchievements { get; private set; }
        private static string selectedAchSteamId = "";

        public static void FetchAchievementsForView(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            if (steamId == selectedAchSteamId && SelectedPlayerAchievements != null) return; // already fetched
            selectedAchSteamId = steamId;
            SelectedPlayerAchievements = null;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/achievements/{steamId}",
                (success, response) =>
                {
                    if (success)
                    {
                        try
                        {
                            var dict = new Dictionary<string, AchievementData>();
                            var parts = response.Split(new[] { "\"achievement_key\"" }, StringSplitOptions.None);
                            for (int i = 1; i < parts.Length; i++)
                            {
                                string key = ExtractJsonString(parts[i], "");
                                if (string.IsNullOrEmpty(key)) continue;
                                bool unlocked = parts[i].Contains("\"unlocked\":true") || parts[i].Contains("\"unlocked\": true");
                                dict[key] = new AchievementData { achievement_key = key, unlocked = unlocked };
                            }
                            // Identity fence (design review, Aug 30): a late
                            // response for player A must not land after the
                            // selection moved to B — the cache is global and
                            // the detail panel renders it under B's name.
                            if (selectedAchSteamId != steamId) return;
                            SelectedPlayerAchievements = dict;
                            NativeUI.MarkDirty();
                        }
                        catch { }
                    }
                }
            ));
        }

        // ── Compare-tab achievement grid (v1.29) ─────────────────
        // Per-player unlocked-achievement sets for the "Achievement Grid"
        // compare metric, plus key→display-name captured from the same
        // response (so renamed achievements — Regicide → Sid Slayer — show
        // their server-side names without a client mapping).

        public static readonly Dictionary<string, Dictionary<string, AchievementData>> CompareAchievements =
            new Dictionary<string, Dictionary<string, AchievementData>>();
        public static readonly Dictionary<string, string> AchievementDisplayNames =
            new Dictionary<string, string>();
        private static readonly HashSet<string> _compareAchFetching = new HashSet<string>();

        public static void FetchAchievementsForCompare(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            if (CompareAchievements.ContainsKey(steamId) || _compareAchFetching.Contains(steamId)) return;
            _compareAchFetching.Add(steamId);
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/achievements/{steamId}",
                (success, response) =>
                {
                    _compareAchFetching.Remove(steamId);
                    if (!success) return;
                    try
                    {
                        var dict = new Dictionary<string, AchievementData>();
                        var parts = response.Split(new[] { "\"achievement_key\"" }, StringSplitOptions.None);
                        for (int i = 1; i < parts.Length; i++)
                        {
                            string key = ExtractJsonString(parts[i], "");
                            if (string.IsNullOrEmpty(key)) continue;
                            bool unlocked = parts[i].Contains("\"unlocked\":true") || parts[i].Contains("\"unlocked\": true");
                            dict[key] = new AchievementData { achievement_key = key, unlocked = unlocked };
                            string nm = ExtractJsonString(parts[i], "name");
                            if (!string.IsNullOrEmpty(nm)) AchievementDisplayNames[key] = nm;
                        }
                        CompareAchievements[steamId] = dict;
                        NativeUI.MarkDirty();
                    }
                    catch { }
                }
            ));
        }

        // ── Compare-tab stat boards (Aug 6 item 1) ───────────────
        /* Every endpoint below answers with PARALLEL PRIMITIVE ARRAYS rather than
         * an array of objects, because JsonUtility silently fails on nested arrays
         * (#25) and manual slicing over user-authored display names needs the
         * string-aware helpers anyway (#156). The parse for all of them is
         * therefore "pull N same-length arrays by key"; ArraysAligned() drops any
         * response whose arrays disagree in length rather than rendering a row
         * built from mismatched columns.
         *
         * Caching mirrors FetchAchievementsForCompare exactly: a public result
         * dictionary keyed by whatever identifies the request, plus a private
         * in-flight set so a metric that re-renders every frame can call the
         * fetch unconditionally without issuing duplicate requests. Nothing here
         * blocks; render sites read the cache and show a loading line on a miss. */

        public class RecordsBoardData
        {
            public List<string> names = new List<string>();
            public List<string> steamIds = new List<string>();
            public List<int> values = new List<int>();
            // Aug 17 match-derived enrichment. Each aligned with names when the
            // server sent it; EMPTY against an older server — render sites must
            // check Count == names.Count before indexing.
            public List<string> dates = new List<string>();
            public List<string> titles = new List<string>();
            public List<string> titleColors = new List<string>();
            public List<int> ratings = new List<int>();
            public List<string> cards = new List<string>();       // '|'-joined
            public List<string> names2 = new List<string>();      // opponent / p2
            public List<string> steamIds2 = new List<string>();   // opponent / p2 (highlighting)
            public List<string> cards2 = new List<string>();      // game boards only
            public List<int> ratings2 = new List<int>();          // game boards only
            public List<string> matchIds = new List<string>();    // Aug 18: admin record-removal target
            public List<int> durations = new List<int>();         // Aug 18: game details (Sid)
            public List<string> scores = new List<string>();      // holder-first, half-point convention
            // r1 finding 7: without a TTL, a client that cached a board before
            // an admin exclusion shows the removed row until process restart.
            public float fetchedAt;                               // Time.realtimeSinceStartup
        }
        public class CardTopPickersData
        {
            public string cardName;
            public List<string> names = new List<string>();
            public List<string> steamIds = new List<string>();
            public List<int> picks = new List<int>();
            public List<float> winRates = new List<float>();   // 0..1
        }
        public class RankedFriendsData
        {
            public List<string> names = new List<string>();
            public List<string> steamIds = new List<string>();
            public List<int> seriesCounts = new List<int>();
        }
        public class GoldSourcesData
        {
            public List<string> buckets = new List<string>();
            public List<int> amounts = new List<int>();
        }
        public class NemesisData
        {
            public List<string> names = new List<string>();
            public List<string> steamIds = new List<string>();
            // Aug 7: the endpoint was rescoped from ALL 1v1 matches (casual
            // included) to completed ranked 1v1 SERIES. The wire names are frozen
            // but these now count SERIES won / SERIES played — label them as such.
            public List<int> wins = new List<int>();
            public List<int> games = new List<int>();
            public List<float> winRates = new List<float>();   // 0..1
            // Which of the SELECTED players actually faced this opponent, as steam
            // ids. Index-aligned with the lists above; EMPTY when the server predates
            // the field, so render sites must tolerate a short/absent list rather
            // than assume one entry per row.
            public List<List<string>> facedBy = new List<List<string>>();
        }
