        /// <summary>Nemesis is asked over the WHOLE selected set at once, so the
        /// cache key is the joined id list. The server requires 2-12 numeric ids
        /// and 400s otherwise — refuse locally rather than burning a request, and
        /// key on the same string that is sent so a re-ordered selection is a
        /// genuinely different query rather than a false cache hit.</summary>
        public static string NemesisKeyFor(List<string> steamIds)
        {
            if (steamIds == null || steamIds.Count < 2 || steamIds.Count > 12) return null;
            var clean = new List<string>();
            foreach (var s in steamIds)
            {
                if (string.IsNullOrEmpty(s)) return null;
                foreach (char c in s) if (c < '0' || c > '9') return null;   // numeric ids only
                if (!clean.Contains(s)) clean.Add(s);
            }
            if (clean.Count < 2) return null;
            clean.Sort(StringComparer.Ordinal);
            return string.Join(",", clean.ToArray());
        }

        public static void FetchNemesis(string joinedKey)
        {
            if (string.IsNullOrEmpty(joinedKey) || NemesisBoards.ContainsKey(joinedKey)) return;
            FetchCompareBoard($"nemesis:{joinedKey}",
                $"{baseUrl}/api/v1/compare/nemesis?targets={UnityWebRequest.EscapeURL(joinedKey)}", resp =>
            {
                var d = new NemesisData
                {
                    names = JsonStringArrayByKey(resp, "display_names"),
                    steamIds = JsonStringArrayByKey(resp, "steam_ids"),
                    wins = JsonIntArrayByKey(resp, "wins"),
                    games = JsonIntArrayByKey(resp, "games"),
                    winRates = JsonFloatArrayByKey(resp, "win_rates"),
                    facedBy = JsonStringArrayOfArraysByKey(resp, "faced_by"),
                };
                if (!ArraysAligned(d.names.Count, d.steamIds.Count, d.wins.Count, d.games.Count, d.winRates.Count))
                    return false;
                // faced_by is deliberately OUTSIDE the alignment gate: it is
                // attribution garnish, and a server that predates it omits the key
                // entirely. Dropping the whole board over a missing optional field
                // would blank the panel for the entire pre-deploy window. Anything
                // that does not line up 1:1 is discarded instead.
                if (d.facedBy.Count != d.names.Count) d.facedBy.Clear();
                NemesisBoards[joinedKey] = d;
                return true;
            });
        }

        /// <summary>Per-player nemeses (`/compare/player-nemesis`). Same selection
        /// key as FetchNemesis — the board is asked over the whole selected set at
        /// once, so a re-ordered selection is the same query and a genuinely
        /// different selection is a different cache entry. Unlike the comparison
        /// board, a player's nemesis MAY be another selected player: "who beats me
        /// most" is a per-player question and excluding a co-selected rival would
        /// answer it wrongly, so the server does not filter them and neither do we.</summary>
        public static void FetchPlayerNemesis(string joinedKey)
        {
            if (string.IsNullOrEmpty(joinedKey) || PlayerNemesisBoards.ContainsKey(joinedKey)) return;
            FetchCompareBoard($"pnemesis:{joinedKey}",
                $"{baseUrl}/api/v1/compare/player-nemesis?targets={UnityWebRequest.EscapeURL(joinedKey)}", resp =>
            {
                var d = new PlayerNemesisData();
                // Every slice here crosses display_name, i.e. adversarial user text
                // — key location and bracket/brace matching are string-aware (#156).
                if (!LocateArray(resp, "players", out int pOpen, out int pClose)) return false;
                foreach (string pObj in SliceTopLevelObjects(resp.Substring(pOpen + 1, pClose - pOpen - 1)))
                {
                    // The nested nemesis objects repeat "steam_id"/"display_name",
                    // so read the player's OWN scalars from the text BEFORE the
                    // nemeses array — otherwise the FIRST nemesis shadows them.
                    int nKey = FindKeyOutsideStrings(pObj, "nemeses");
                    string head = nKey > 0 ? pObj.Substring(0, nKey) : pObj;
                    var g = new PlayerNemesisGroup
                    {
                        steamId = ExtractJsonString(head, "steam_id"),
                        name = ExtractJsonString(head, "display_name"),
                    };
                    if (string.IsNullOrEmpty(g.steamId)) continue;
                    if (LocateArray(pObj, "nemeses", out int nOpen, out int nClose))
                    {
                        foreach (string nObj in SliceTopLevelObjects(pObj.Substring(nOpen + 1, nClose - nOpen - 1)))
                        {
                            string nsid = ExtractJsonString(nObj, "steam_id");
                            if (string.IsNullOrEmpty(nsid)) continue;
                            g.nemeses.Add(new PlayerNemesisEntry
                            {
                                steamId = nsid,
                                name = ExtractJsonString(nObj, "display_name"),
                                seriesPlayed = ExtractJsonInt(nObj, "series_played"),
                                seriesLost = ExtractJsonInt(nObj, "series_lost"),
                                lossRate = ExtractJsonFloat(nObj, "loss_rate"),
                            });
                        }
                    }
                    // An empty nemeses list is a real answer (nobody has taken 3+
                    // series off them), so the group is kept either way.
                    d.players.Add(g);
                }
                // An empty players array (neither target known to the server) is
                // cached like every other board's empty result. Returning false
                // here would leave the key uncached and make the per-frame render
                // path re-request it forever.
                PlayerNemesisBoards[joinedKey] = d;
                return true;
            });
        }

        /// <summary>Card-name catalogue for the Cards sub-tab picker. `/cards` is
        /// the only server-side list of card names the client can enumerate —
        /// CardRarityLookup's dictionaries are populated from the live scene and
        /// expose no key accessor. min_picks=1 means a card nobody has ever picked
        /// is absent, which is correct here: there would be nothing to compare.</summary>
        public static void FetchCardCatalog()
        {
            if (CardCatalog != null) return;
            FetchCompareBoard("cardcatalog",
                $"{baseUrl}/api/v1/cards?limit=200&sort_by=times_picked&min_picks=1", resp =>
            {
                var list = ParseCardCatalogBody(resp);
                /* Aug 6 review find 9: an EMPTY catalogue must not be
                 * cached. The guard above is `CardCatalog != null`, so a 200
                 * returning [] would pin an empty list for the session and
                 * the Cards sub-tab picker would read "No matches." forever
                 * with no retry. Returning false leaves it null AND skips the
                 * success-cache in FetchCompareBoard, so the next open
                 * re-fetches. Matches what the other seven parsers do. */
                if (list.Count == 0) return false;
                CardCatalog = CollapseCardDuplicates(list);
                return true;
            });
        }

        /// <summary>Sept 1 — RANKED-only twin of the catalogue, for the Cards
        /// compare's ranked boards. Same shared parser/collapse (#330: one
        /// parse operation, not a second copy that drifts). A card only ever
        /// picked in casual is legitimately ABSENT here — render sites look
        /// selected cards up by name and treat a miss as zero.</summary>
        public static void FetchCardCatalogRanked()
        {
            if (CardCatalogRanked != null) return;
            FetchCompareBoard("cardcatalogranked",
                $"{baseUrl}/api/v1/cards?limit=200&sort_by=times_picked&min_picks=1&is_ranked=true", resp =>
            {
                var list = ParseCardCatalogBody(resp);
                if (list.Count == 0) return false;   // same empty-reject rule as above
                CardCatalogRanked = CollapseCardDuplicates(list);
                return true;
            });
        }

        /// <summary>One /cards body → entry list. Shared by the combined and
        /// ranked catalogue fetchers so the field list cannot drift (#330).
        /// String-aware slicing (#156): splitting the raw body on the literal
        /// "card_name" would let a stored card name containing that token
        /// split its own object in half — card names originate from reported
        /// match data and are not a closed set.</summary>
        private static List<CardCatalogEntry> ParseCardCatalogBody(string resp)
        {
            var list = new List<CardCatalogEntry>();
            int _cOpen = resp.IndexOf('[');
            int _cClose = _cOpen >= 0 ? FindMatchingBracketStringAware(resp, _cOpen) : -1;
            var parts = (_cOpen >= 0 && _cClose > _cOpen)
                ? SliceTopLevelObjects(resp.Substring(_cOpen + 1, _cClose - _cOpen - 1))
                : new List<string>();
            for (int i = 0; i < parts.Count; i++)
            {
                string nm = ExtractJsonString(parts[i], "card_name");
                if (string.IsNullOrEmpty(nm)) continue;
                list.Add(new CardCatalogEntry
                {
                    name = nm,
                    rarity = ExtractJsonString(parts[i], "card_rarity"),
                    times_picked = ExtractJsonInt(parts[i], "times_picked"),
                    times_offered = ExtractJsonInt(parts[i], "times_offered"),
                    win_rate = ExtractJsonFloat(parts[i], "win_rate"),
                    pass_rate = ExtractJsonFloat(parts[i], "pass_rate"),
                    sweeps_with_card = ExtractJsonInt(parts[i], "sweeps_with_card"),
                    stacked_builds = ExtractJsonInt(parts[i], "stacked_builds"),
                    unique_players = ExtractJsonInt(parts[i], "unique_players"),
                    wins_with_card = ExtractJsonInt(parts[i], "wins_with_card"),
                });
            }
            return list;
        }

        /// <summary>Aug 7 item 2 — collapse duplicate catalogue rows to ONE entry
        /// per canonical card name, keeping the row with the highest
        /// times_picked.
        ///
        /// Two independent sources of duplicates, and this closes both from the
        /// client side:
        ///  - the server groups /cards by (card_name, card_rarity), and
        ///    card_rarity is a PER-PICK SNAPSHOT written by whichever client
        ///    reported the match, so one card accumulates several stored
        ///    rarities and comes back as several rows with the SAME name (prod:
        ///    110 (name,rarity) groups over 88 distinct names = 22 dupe rows);
        ///  - GetCanonicalName folds ROUNDS' own name variants together
        ///    ("Leach" -> "Leech", "PoisonBullets" -> "Poison"), which a
        ///    name-only server GROUP BY still cannot merge.
        /// Rows that collapse together are AGGREGATED, not picked between
        /// (Codex Aug-7): sums for counts, weighted means for rates. The
        /// surviving entry keeps the DOMINANT RAW name, because that name is
        /// also the exact-match query key for /cards/top-pickers.
        ///
        /// The rarity note that used to live here is now stale: since the
        /// server groups /cards by card_name alone and elects the rarity by
        /// MODE, a minority-rarity row no longer exists to be picked.
        ///
        /// Belt and braces: it also fixes already-installed clients before the
        /// server-side GROUP BY change deploys. The key is lower-INVARIANT (#47
        /// family) so it can never fold two distinct cards together on a
        /// Turkish-locale client the way a culture-sensitive ToLower would.
        ///
        /// The rows are RE-SORTED after merging, not left in server order: the
        /// comment here used to claim "insertion order is preserved, so the
        /// server's sort survives", which stopped being true the moment merging
        /// started changing times_picked (Codex Aug-7).</summary>
        private static List<CardCatalogEntry> CollapseCardDuplicates(List<CardCatalogEntry> list)
        {
            try
            {
                /* Rewritten as BUCKET-then-AGGREGATE (Codex Aug-7 r3). The
                 * previous incremental merge folded each new row into a running
                 * survivor, and three separate findings all traced back to that
                 * shape: the running total had already overwritten the value the
                 * dominant-name test compared against, and a two-way
                 * same-name/different-name flag could not express "this raw
                 * spelling's offer row has already been counted once". Patching
                 * it a fourth time was the wrong move (#310) — collecting the
                 * bucket first and aggregating once makes each rule statable on
                 * its own. */
                var buckets = new Dictionary<string, List<CardCatalogEntry>>(StringComparer.Ordinal);
                var order = new List<string>();
                foreach (var e in list)
                {
                    if (e == null || string.IsNullOrEmpty(e.name)) continue;
                    string canon = e.name;
                    // GetCanonicalName reads the live CardInfo registry, which is
                    // empty until the first match — it then returns the input
                    // unchanged, so the key degrades to the raw name and the
                    // (name,rarity) dupes still collapse. Never throws, but the
                    // whole method is defensive anyway: a failure here must not
                    // cost the catalogue.
                    try { canon = CardRarityLookup.GetCanonicalName(e.name) ?? e.name; } catch { }
                    string key = canon.ToLowerInvariant();
                    List<CardCatalogEntry> b;
                    if (!buckets.TryGetValue(key, out b))
                    {
                        b = new List<CardCatalogEntry>(2);
                        buckets[key] = b;
                        order.Add(key);
                    }
                    b.Add(e);
                }

                var outp = new List<CardCatalogEntry>(buckets.Count);
                int dropped = 0;
                foreach (var key in order)
                {
                    var rows = buckets[key];
                    if (rows.Count == 1) { outp.Add(rows[0]); continue; }
                    dropped += rows.Count - 1;

                    /* PICKS always SUM. Every row is a distinct server GROUP BY
                     * bucket, so no pick is represented twice — true whether the
                     * server groups by (name, rarity) or by name alone. */
                    int totalPicks = 0, totalWins = 0;
                    float winAcc = 0f;
                    foreach (var r in rows)
                    {
                        totalPicks += r.times_picked;
                        totalWins += r.wins_with_card;   // main-body per-row aggregate: PICKS rule
                        winAcc += r.win_rate * r.times_picked;
                    }

                    /* OFFERS sum ONCE PER DISTINCT RAW NAME. The server LEFT
                     * JOINs the offer counts on card_name alone, so two rows
                     * sharing a raw name (an old server's two rarity rows) each
                     * repeat the SAME name-level total and must not be added
                     * twice; two rows with DIFFERENT raw names that canonicalise
                     * together (Leech + Leach, or Leech + LEECH on the current
                     * server) each carry their own offers and must be. Keying on
                     * the raw name states exactly that, which the old
                     * boolean could not: it asked "are these two rows' names
                     * equal" rather than "has this spelling been counted yet",
                     * so Leech/LEECH took a maximum instead of summing while an
                     * alternating old-server sequence could add one spelling
                     * more than once. */
                    var offersByRaw = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    var passByRaw = new Dictionary<string, float>(StringComparer.OrdinalIgnoreCase);
                    var picksByRaw = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    /* Aug 31: sweeps/stacks follow the OFFERS rule, for the same
                     * reason — the server computes both in name-keyed CTEs and
                     * LEFT JOINs them on card_name, so two rows sharing a raw
                     * name repeat the SAME name-level total (count once), while
                     * different spellings each carry their own (sum across). */
                    var sweepsByRaw = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    var stacksByRaw = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    /* Sept 1: unique_players follows the OFFERS rule too (a
                     * name-level server aggregate). Summing across SPELLINGS
                     * can double-count a player who picked both legacy
                     * spellings — accepted: display-only, and the alternative
                     * (max) undercounts every genuinely-merged pair. */
                    var uniqByRaw = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    foreach (var r in rows)
                    {
                        string raw = r.name ?? "";
                        int prevOffers;
                        if (!offersByRaw.TryGetValue(raw, out prevOffers) || r.times_offered > prevOffers)
                        {
                            offersByRaw[raw] = r.times_offered;
                            passByRaw[raw] = r.pass_rate;
                        }
                        int prevSw; if (!sweepsByRaw.TryGetValue(raw, out prevSw) || r.sweeps_with_card > prevSw) sweepsByRaw[raw] = r.sweeps_with_card;
                        int prevSt; if (!stacksByRaw.TryGetValue(raw, out prevSt) || r.stacked_builds > prevSt) stacksByRaw[raw] = r.stacked_builds;
                        int prevUq; if (!uniqByRaw.TryGetValue(raw, out prevUq) || r.unique_players > prevUq) uniqByRaw[raw] = r.unique_players;
                        int prevPicks;
                        picksByRaw.TryGetValue(raw, out prevPicks);
                        picksByRaw[raw] = prevPicks + r.times_picked;
                    }

                    int totalOffered = 0;
                    float passAcc = 0f;
                    foreach (var kv in offersByRaw)
                    {
                        totalOffered += kv.Value;
                        passAcc += passByRaw[kv.Key] * kv.Value;
                    }

                    /* The survivor keeps the DOMINANT RAW spelling — the one
                     * whose OWN rows account for the most picks, compared across
                     * per-spelling totals rather than against a running sum that
                     * has already absorbed the other spellings (that comparison
                     * is what made the first-seen name win regardless). The name
                     * is not canonicalised because it doubles as the exact-match
                     * query key for /cards/top-pickers; renaming Leach to Leech
                     * made that follow-up query return nothing.
                     *
                     * KNOWN, ACCEPTED: querying the dominant spelling returns
                     * only that spelling's pickers, and /cards/top-pickers also
                     * excludes invalidated/deleted history that /cards includes
                     * (Codex Aug-7 r3), so the panel can legitimately come back
                     * empty for a card the catalogue shows picks for. Both are
                     * display-only and neither can be fixed client-side; the
                     * real fix is canonicalising in /cards/top-pickers. */
                    var best = rows[0];
                    int bestPicks = -1;
                    foreach (var r in rows)
                    {
                        int own;
                        picksByRaw.TryGetValue(r.name ?? "", out own);
                        // Tie-break by name so the choice is stable across refreshes.
                        if (own > bestPicks ||
                            (own == bestPicks &&
                             string.Compare(r.name, best.name, StringComparison.OrdinalIgnoreCase) < 0))
                        {
                            bestPicks = own;
                            best = r;
                        }
                    }

                    best.times_picked = totalPicks;
                    best.wins_with_card = totalWins;
                    best.times_offered = totalOffered;
                    best.win_rate = totalPicks > 0 ? winAcc / totalPicks : best.win_rate;
                    best.pass_rate = totalOffered > 0 ? passAcc / totalOffered : best.pass_rate;
                    int swSum = 0, stSum = 0, uqSum = 0;
                    foreach (var kv in sweepsByRaw) swSum += kv.Value;
                    foreach (var kv in stacksByRaw) stSum += kv.Value;
                    foreach (var kv in uniqByRaw) uqSum += kv.Value;
                    best.sweeps_with_card = swSum;
                    best.stacked_builds = stSum;
                    best.unique_players = uqSum;
                    outp.Add(best);
                }

                if (dropped > 0)
                {
                    /* Aggregation changes the values the server sorted on —
                     * [Other=100, AliasA=60, AliasB=50] merges to
                     * [Other=100, AliasA=110] and would display the more-picked
                     * card second. Re-sort on the merged counts, matching the
                     * fixed catalogue request's times_picked DESC. Stable by
                     * name on a tie so the order is deterministic. */
                    outp.Sort((x, y) =>
                    {
                        int c = y.times_picked.CompareTo(x.times_picked);
                        return c != 0 ? c : string.Compare(x.name, y.name, StringComparison.OrdinalIgnoreCase);
                    });
                    Plugin.Log.LogInfo($"[CARDS] catalogue collapsed {list.Count} rows -> {outp.Count} ({dropped} duplicate)");
                }
                return outp.Count > 0 ? outp : list;
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[CARDS] collapse failed, using raw catalogue: {ex.Message}");
                return list;
            }
        }

        // ── Primitive-array readers keyed by field name ──────────
        /* The existing ParseJsonStringArray takes explicit open/close indices; the
         * responses above are flat objects of arrays, so these wrappers locate the
         * array for a key first. Bracket matching is the STRING-AWARE variant in
         * every case — display_names carries adversarial user text and a name like
         * ">:[" would otherwise derail the depth counter for the whole body
         * (#156). */

        private static bool LocateArray(string json, string key, out int open, out int close)
        {
            open = close = -1;
            /* Aug 6 review find 6: the bracket MATCHING below is string-aware,
             * but locating the key with a plain IndexOf was not — and every
             * one of these boards carries `display_names` straight from
             * players.display_name, i.e. adversarial user text (#156). A
             * player literally named  ", "values": [  serializes that exact
             * substring into the body, so IndexOf would find the fake key
             * BEFORE the real one and anchor the scan inside a string
             * literal. Best case the arrays mis-align and ArraysAligned drops
             * the board; worst case a crafted equal-length payload renders
             * fabricated names and values on a GLOBAL leaderboard.
             *
             * Fix: walk the body string-aware and only accept a key match that
             * begins OUTSIDE a string literal — i.e. at a real key position. */
            int k = FindKeyOutsideStrings(json, key);
            if (k < 0) return false;
            open = json.IndexOf('[', k);
            if (open < 0) return false;
            close = FindMatchingBracketStringAware(json, open);
            return close > open;
        }

        /// <summary>Index of `"key":` occurring as a REAL object key (not inside
        /// a string value), or -1. Mirrors the scanning discipline of
        /// FindMatchingBracketStringAware.</summary>
        private static int FindKeyOutsideStrings(string json, string key)
        {
            if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(key)) return -1;
            string needle = "\"" + key + "\":";
            bool inStr = false;
            for (int i = 0; i < json.Length; i++)
            {
                char c = json[i];
                if (inStr)
                {
                    if (c == '\\') { i++; continue; }
                    if (c == '"') inStr = false;
                    continue;
                }
                if (c == '"')
                {
                    // A key starts HERE, outside any string value. Test the
                    // needle at this position before entering the literal.
                    if (i + needle.Length <= json.Length
                        && string.CompareOrdinal(json, i, needle, 0, needle.Length) == 0)
                        return i;
                    inStr = true;
                }
            }
            return -1;
        }

        private static List<string> JsonStringArrayByKey(string json, string key)
        {
            return LocateArray(json, key, out int open, out int close)
                ? ParseJsonStringArray(json, open, close)
                : new List<string>();
        }

        /// <summary>Numbers inside a JSON array slice. Scans string-aware so a
        /// quoted element can never contribute its digits to the number list.</summary>
        private static List<float> JsonFloatArrayByKey(string json, string key)
        {
            var list = new List<float>();
            if (!LocateArray(json, key, out int open, out int close)) return list;
            var sb = new StringBuilder();
            bool inStr = false;
            for (int i = open + 1; i <= close; i++)
            {
                // At `close` the char is ']'; substitute a separator so the final
                // number is flushed by the same branch as every other element.
                char c = i < close ? json[i] : ',';
                if (inStr)
                {
                    if (c == '\\') i++;
                    else if (c == '"') inStr = false;
                    continue;
                }
                if (c == '"') { inStr = true; sb.Length = 0; continue; }
                if ((c >= '0' && c <= '9') || c == '.' || c == '-' || c == '+' || c == 'e' || c == 'E')
                {
                    sb.Append(c);
                    continue;
                }
                if (sb.Length > 0)
                {
                    if (float.TryParse(sb.ToString(), System.Globalization.NumberStyles.Float,
                                       System.Globalization.CultureInfo.InvariantCulture, out float v))
                        list.Add(v);
                    sb.Length = 0;
                }
            }
            return list;
        }

        /// <summary>Read a JSON array OF string arrays (`[["a","b"],["c"]]`) by key.
        /// The nemesis board's `faced_by` is nested rather than flat because it is
        /// index-aligned with the other parallel arrays and each row carries a
        /// SUBSET of the selected ids. Fully string-aware: the sibling
        /// display_names in the same body are adversarial user text, and a name
        /// like "&gt;:[" would otherwise derail the inner scan (#156).</summary>
        private static List<List<string>> JsonStringArrayOfArraysByKey(string json, string key)
        {
            var outer = new List<List<string>>();
            if (!LocateArray(json, key, out int open, out int close)) return outer;
            bool inStr = false;
            for (int i = open + 1; i < close; i++)
            {
                char c = json[i];
                if (inStr)
                {
                    if (c == '\\') i++;
                    else if (c == '"') inStr = false;
                    continue;
                }
                if (c == '"') { inStr = true; continue; }
                if (c != '[') continue;
                int innerClose = FindMatchingBracketStringAware(json, i);
                if (innerClose < 0 || innerClose > close) break;
                outer.Add(ParseJsonStringArray(json, i, innerClose));
                i = innerClose;   // the loop's i++ steps past the closing bracket
            }
            return outer;
        }

        private static List<int> JsonIntArrayByKey(string json, string key)
        {
            var src = JsonFloatArrayByKey(json, key);
            var list = new List<int>(src.Count);
            foreach (var f in src) list.Add(Mathf.RoundToInt(f));
            return list;
        }

        private static int FindMatchingBracket(string s, int openPos)
        {
            if (openPos < 0 || openPos >= s.Length) return -1;
            int depth = 0;
            for (int i = openPos; i < s.Length; i++)
            {
                if (s[i] == '[') depth++;
                else if (s[i] == ']') { depth--; if (depth == 0) return i; }
            }
            return -1;
        }

        // Brace-pair finder for {} — same semantics as FindMatchingBracket. Used
        // by the cards_by_player parser, which has to extract a nested JSON
        // object (not an array) keyed by steam_id.
        private static int FindMatchingBrace(string s, int openPos)
        {
            if (openPos < 0 || openPos >= s.Length) return -1;
            int depth = 0;
            for (int i = openPos; i < s.Length; i++)
            {
                if (s[i] == '{') depth++;
                else if (s[i] == '}') { depth--; if (depth == 0) return i; }
            }
            return -1;
        }

        // Per-player card-tier-list state. (filter, card_name) -> tier letter.
        // Loaded by FetchCardTiers when the user changes the Card Stats filter.
        public static void FetchCardTiers(string steamId, string filter, Action<Dictionary<string, string>> onLoaded)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") { onLoaded?.Invoke(new Dictionary<string, string>()); return; }
            string url = $"{baseUrl}/api/v1/players/{Escape(steamId)}/card-tiers?filter={Escape(filter)}";
            Plugin.Instance.StartCoroutine(GetRequest(url, (success, response) =>
            {
                var map = new Dictionary<string, string>();
                if (!success || string.IsNullOrEmpty(response)) { onLoaded?.Invoke(map); return; }
                try
                {
                    int o = response.IndexOf("\"tiers\"");
                    if (o < 0) { onLoaded?.Invoke(map); return; }
                    int oS = response.IndexOf('{', o);
                    int oE = FindMatchingBrace(response, oS);
                    if (oS < 0 || oE < 0) { onLoaded?.Invoke(map); return; }
                    string slice = response.Substring(oS + 1, oE - oS - 1);
                    int cur = 0;
                    while (cur < slice.Length)
                    {
                        int kS = slice.IndexOf('"', cur); if (kS < 0) break;
                        int kE = slice.IndexOf('"', kS + 1); if (kE < 0) break;
                        string card = slice.Substring(kS + 1, kE - kS - 1);
                        int colon = slice.IndexOf(':', kE); if (colon < 0) break;
                        int vS = slice.IndexOf('"', colon); if (vS < 0) break;
                        int vE = slice.IndexOf('"', vS + 1); if (vE < 0) break;
                        string val = slice.Substring(vS + 1, vE - vS - 1);
                        map[card.ToLower()] = val;
                        cur = vE + 1;
                    }
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[CARD-TIER] parse: {ex.Message}"); }
                onLoaded?.Invoke(map);
            }));
        }

        public static void SetCardTier(string steamId, string cardName, string filter, string tier)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            string sig = ComputeHmacHex($"card-tier:{steamId}:{cardName}:{filter}:{tier}");
            string url = $"{baseUrl}/api/v1/players/{Escape(steamId)}/card-tiers"
                       + $"?card_name={Escape(cardName)}&filter={Escape(filter)}&tier={Escape(tier)}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                if (!ok) Plugin.Log.LogWarning($"[CARD-TIER] set failed: {resp}");
            }));
        }

        public static void FetchCardStats(int limit = 30, string steamId = null, string sortBy = "times_picked", string isRanked = null)
        {
            IsLoading = true;
            string url = $"{baseUrl}/api/v1/cards?limit={limit}&sort_by={sortBy}&min_picks=1";
            if (!string.IsNullOrEmpty(steamId) && steamId != "unknown")
                url += $"&steam_id={steamId}";
            if (!string.IsNullOrEmpty(isRanked))
                url += $"&is_ranked={isRanked}";

            Plugin.Instance.StartCoroutine(GetRequest(
                url,
                (success, response) =>
                {
                    IsLoading = false;
                    if (success)
                    {
                        try
                        {
                            CachedCardStats = ParseCardStatsJson(response);
                            Plugin.Log.LogInfo(CachedCardStats.Count == 0
                                ? "Card stats: no data yet"
                                : $"Card stats loaded: {CachedCardStats.Count} cards");
                        }
                        catch (Exception ex)
                        {
                            CachedCardStats = new List<CardStatData>();
                            Plugin.Log.LogError($"Failed to parse card stats: {ex.Message}");
                        }
                    }
                    else
                    {
                        Plugin.Log.LogError($"Failed to fetch card stats: {response}");
                    }
                }
            ));
        }

        /// <summary>Parse a /cards JSON array. Extracted from FetchCardStats
        /// (broadcast W7) so the view fetch below shares the ONE parser
        /// (#279) — a field added here reaches both paths.</summary>
        private static List<CardStatData> ParseCardStatsJson(string response)
        {
            var entries = new List<CardStatData>();
            if (string.IsNullOrEmpty(response) || response.Trim() == "[]") return entries;

            // Manual parse — split by card_name entries
            var parts = response.Split(new[] { "\"card_name\"" }, StringSplitOptions.None);
            for (int i = 1; i < parts.Length; i++)
            {
                var chunk = parts[i];
                var entry = new CardStatData();
                entry.card_name = ExtractJsonString(chunk, "");
                entry.card_rarity = ExtractJsonString(chunk, "card_rarity");
                entry.times_picked = ExtractJsonInt(chunk, "times_picked");
                entry.wins_with_card = ExtractJsonInt(chunk, "wins_with_card");
                entry.times_offered = ExtractJsonInt(chunk, "times_offered");
                entry.pass_rate = ExtractJsonFloat(chunk, "pass_rate");

                // Parse win_rate as float
                try
                {
                    string wrStr = chunk;
                    int wrIdx = wrStr.IndexOf("\"win_rate\":");
                    if (wrIdx >= 0)
                    {
                        wrIdx += "\"win_rate\":".Length;
                        while (wrIdx < wrStr.Length && wrStr[wrIdx] == ' ') wrIdx++;
                        int wrEnd = wrIdx;
                        while (wrEnd < wrStr.Length && (char.IsDigit(wrStr[wrEnd]) || wrStr[wrEnd] == '.' || wrStr[wrEnd] == '-'))
                            wrEnd++;
                        if (wrEnd > wrIdx)
                            entry.win_rate = float.Parse(wrStr.Substring(wrIdx, wrEnd - wrIdx),
                                System.Globalization.CultureInfo.InvariantCulture);
                    }
                }
                catch { entry.win_rate = 0f; }

                if (!string.IsNullOrEmpty(entry.card_name))
                    entries.Add(entry);
            }
            return entries;
        }

        /// <summary>Broadcast W7: a fighter's top ranked cards for the report
        /// engine. Does NOT touch CachedCardStats (that's the Card Stats
        /// tab's, with its own limit/sort/filter). Callback gets null on
        /// transport/parse failure, a list (possibly empty) on a server
        /// answer — the report omits the panel on null, renders "no data"
        /// on empty.</summary>
        public static void FetchCardStatsForView(string steamId, Action<List<CardStatData>> cb)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown" || Plugin.Instance == null)
            { cb?.Invoke(null); return; }
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/cards?steam_id={UnityWebRequest.EscapeURL(steamId)}&is_ranked=true&sort_by=times_picked&order=desc&limit=8&min_picks=3",
                (success, response) =>
                {
                    if (!success) { try { cb?.Invoke(null); } catch { } return; }
                    List<CardStatData> list;
                    try { list = ParseCardStatsJson(response); }
                    catch (Exception ex)
                    {
                        Plugin.Log.LogWarning($"[BROADCAST] card stats parse: {ex.Message}");
                        list = null;
                    }
                    try { cb?.Invoke(list); } catch { }
                }
            ));
        }

        // limit=2000 is the server cap (see /players/{steam_id}/matches). Bumped
        // 500 → 2000 in v1.26.8 after Stan reported old matches "disappearing"
        // off the F5 history. 2000 covers ~6 months of heavy play for any user
        // and matches the server's enforcement ceiling.
        // ── Lazy history loading (v1.33, Sid's item 8) ─────────────────────
        // The full 2000-row fetch made My Stats slow to load. History now
        // arrives in HISTORY_CHUNK-row slices: the head chunk on menu open,
        // the next chunk when the pager nears the end of what's loaded.
        // /matches/summary supplies the FULL totals so the pager can still
        // show "page X of <whole history>".
        public const int HISTORY_CHUNK = 400;
        public static bool MatchHistoryLoadedAll;
        private static bool _historyFetchInFlight;
        public static int HistoryTotalMatches = -1;
        public static int HistoryTotalRankedGroups = -1;
        public static int HistoryTotalCasual = -1;

        public static void FetchMatchHistory(string steamId, int limit = HISTORY_CHUNK)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            if (_historyFetchInFlight) return;
            _historyFetchInFlight = true;
            FetchMatchSummary(steamId);
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/matches?limit={limit}",
                (success, response) =>
                {
                    if (!success) { _historyFetchInFlight = false; return; }
                    // v1.29 (F5 lag): parse SPREAD ACROSS FRAMES. The manual
                    // string-split parse of hundreds of KB used to run in one
                    // callback — a solid main-thread hitch on every menu open.
                    Plugin.Instance.StartCoroutine(ParseMatchHistoryChunked(response, append: false, requested: limit));
                }
            ));
        }

        /// <summary>Append the next HISTORY_CHUNK of older matches. No-op while a
        /// fetch is in flight or when the server has no more rows.</summary>
        public static void FetchMoreMatchHistory(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            if (_historyFetchInFlight || MatchHistoryLoadedAll) return;
            if (CachedMatchHistory == null) { FetchMatchHistory(steamId); return; }
            _historyFetchInFlight = true;
            int offset = CachedMatchHistory.Count;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/matches?limit={HISTORY_CHUNK}&offset={offset}",
                (success, response) =>
                {
                    if (!success) { _historyFetchInFlight = false; return; }
                    Plugin.Instance.StartCoroutine(ParseMatchHistoryChunked(response, append: true, requested: HISTORY_CHUNK));
                }
            ));
        }

        // ── Name-filtered history search (bug 263, Stan) ───────────────────
        // A SEPARATE cache, deliberately (recon risk 2): CachedMatchHistory
        // feeds other consumers (H2H seeding, session panels), so a filtered
        // fetch must never overwrite it — clearing the search would otherwise
        // force a full reload. The generation token retires in-flight
        // responses and parse coroutines when the query changes or clears
        // (#367b ownership-token shape / #232 stale-callback family).
        public static List<MatchHistoryEntry> MatchHistorySearch;   // null = no active search
        public static string MatchHistorySearchQuery = "";
        public static bool MatchHistorySearchLoadedAll;
        private static bool _searchFetchInFlight;
        private static int _searchFetchGen;

        public static void ClearMatchHistorySearch()
        {
            _searchFetchGen++;
            _searchFetchInFlight = false;
            MatchHistorySearch = null;
            MatchHistorySearchQuery = "";
            MatchHistorySearchLoadedAll = false;
        }

        /// <summary>Cap to at most 64 UTF-16 units WITHOUT trimming and without
        /// leaving a dangling high surrogate at the boundary (a lone surrogate
        /// throws in Uri.EscapeDataString — review r2). The search FIELD uses
        /// this so it can never hold a query longer than the server filter
        /// accepts: the visible text, the request and the cache identity then
        /// describe the same string, so stale/nonmatching rows can't render.</summary>
        public static string CapHistoryQueryUnits(string query)
        {
            string q = query ?? "";
            if (q.Length <= 64) return q;
            int cut = 64;
            if (char.IsHighSurrogate(q[cut - 1])) cut--;   // don't split a pair
            return q.Substring(0, cut);
        }

        /// <summary>Canonical history-search KEY = trimmed + unit-capped. The
        /// request URL, MatchHistorySearchQuery and the NativeUI cache-identity
        /// check all go through this ONE rule (review r2: incompatible length
        /// rules relabeled a stale cache). Because the field is already
        /// unit-capped, this only ever trims.</summary>
        public static string CanonicalizeHistoryQuery(string query)
        {
            return CapHistoryQueryUnits((query ?? "").Trim());
        }

        /// <summary>Fetch a name-filtered slice of the 1v1 history. append=false
        /// starts a new query (owns the cache from that moment); append=true
        /// pages the CURRENT query onward — the same lazy-chunk shape the
        /// unfiltered history uses.</summary>
        public static void FetchMatchHistorySearch(string steamId, string query, bool append)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            query = CanonicalizeHistoryQuery(query);
            if (query.Length == 0) { ClearMatchHistorySearch(); NativeUI.MarkDirty(); return; }
            if (append)
            {
                if (_searchFetchInFlight || MatchHistorySearchLoadedAll) return;
                if (!string.Equals(query, MatchHistorySearchQuery, StringComparison.Ordinal)) return;
            }
            else
            {
                _searchFetchGen++;
                MatchHistorySearchQuery = query;
                MatchHistorySearchLoadedAll = false;
                // Review r1 find 1: the OLD query's rows must never render
                // under the new label (and an append must never offset by
                // their count) — drop them now; the renderer falls back to
                // the instant client-side filter until fresh rows land.
                MatchHistorySearch = null;
            }
            int gen = _searchFetchGen;
            _searchFetchInFlight = true;
            int offset = append && MatchHistorySearch != null ? MatchHistorySearch.Count : 0;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/matches?limit={HISTORY_CHUNK}&offset={offset}&name_filter={Uri.EscapeDataString(query)}",
                (success, response) =>
                {
                    if (gen != _searchFetchGen) return;   // query changed/cleared mid-flight
                    if (!success) { _searchFetchInFlight = false; return; }
                    Plugin.Instance.StartCoroutine(ParseSearchHistoryChunked(response, gen, append));
                }
            ));
        }

        private static System.Collections.IEnumerator ParseSearchHistoryChunked(string response, int gen, bool append)
        {
            if (string.IsNullOrEmpty(response) || response.Trim() == "[]")
            {
                if (gen == _searchFetchGen)
                {
                    if (!append || MatchHistorySearch == null) MatchHistorySearch = new List<MatchHistoryEntry>();
                    MatchHistorySearchLoadedAll = true;
                    _searchFetchInFlight = false;
                    NativeUI.MarkDirty();
                }
                yield break;
            }
            List<string> slices = null;
            try { slices = SliceHistoryObjects(response); }
            catch (Exception ex)
            {
                if (gen == _searchFetchGen) _searchFetchInFlight = false;
                Plugin.Log.LogError($"Failed to parse history search: {ex.Message}");
                yield break;
            }
            var entries = new List<MatchHistoryEntry>(slices.Count);
            const int PER_FRAME = 80;
            for (int i = 0; i < slices.Count; i++)
            {
                try { entries.Add(ParseMatchHistoryChunkEntry(slices[i])); }
                catch { }
                if (i > 0 && i % PER_FRAME == 0)
                {
                    yield return null;
                    // Pump-id check after EVERY resume (#299): a stale parse
                    // must never land rows into a newer query's cache.
                    if (gen != _searchFetchGen) yield break;
                }
            }
            if (gen != _searchFetchGen) yield break;
            MatchHistorySearchLoadedAll = entries.Count < HISTORY_CHUNK;
            if (append && MatchHistorySearch != null)
            {
                var seen = new HashSet<string>();
                foreach (var m in MatchHistorySearch)
                    if (!string.IsNullOrEmpty(m.match_id)) seen.Add(m.match_id);
                foreach (var m in entries)
                    if (string.IsNullOrEmpty(m.match_id) || seen.Add(m.match_id))
                        MatchHistorySearch.Add(m);
            }
            else MatchHistorySearch = entries;
            _searchFetchInFlight = false;
            NativeUI.MarkDirty();
        }

        /// <summary>True ranked-game count for the LOCAL account, -1 until a
        /// summary response has carried it. wins/losses on PlayerStatsData
        /// include non-ranked play and series counters miss unfinished
        /// series (design review, Aug 30), so the first-timer hint keys on
        /// THIS field only. Bound to the local steam id at assignment.</summary>
        public static int LocalRankedMatches = -1;

        /// <summary>Full-history totals for the pager (flat scalars, manual extract).</summary>
        public static void FetchMatchSummary(string steamId)
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/matches/summary",
                (ok, resp) =>
                {
                    if (!ok || string.IsNullOrEmpty(resp)) return;
                    HistoryTotalMatches = ExtractJsonInt(resp, "total");
                    HistoryTotalRankedGroups = ExtractJsonInt(resp, "ranked_groups");
                    HistoryTotalCasual = ExtractJsonInt(resp, "casual_matches");
                    // Presence-checked (#400): an old server without the field
                    // must read as UNKNOWN, never as zero ranked games.
                    if (resp.IndexOf("\"ranked_matches\"", StringComparison.Ordinal) >= 0
                        && steamId == MatchTracker.LocalSteamId)
                        LocalRankedMatches = ExtractJsonInt(resp, "ranked_matches");
                    NativeUI.MarkDirty();
                }));
        }

        private static System.Collections.IEnumerator ParseMatchHistoryChunked(string response, bool append, int requested)
        {
            if (string.IsNullOrEmpty(response) || response.Trim() == "[]")
            {
                if (!append) CachedMatchHistory = new List<MatchHistoryEntry>();
                MatchHistoryLoadedAll = true;
                _historyFetchInFlight = false;
                yield break;
            }
            List<string> slices = null;
            try
            {
                slices = SliceHistoryObjects(response);
            }
            catch (Exception ex)
            {
                if (!append) CachedMatchHistory = new List<MatchHistoryEntry>();
                _historyFetchInFlight = false;
                Plugin.Log.LogError($"Failed to parse match history: {ex.Message}");
                yield break;
            }
            var entries = new List<MatchHistoryEntry>(slices.Count);
            const int PER_FRAME = 80;
            for (int i = 0; i < slices.Count; i++)
            {
                try
                {
                    entries.Add(ParseMatchHistoryChunkEntry(slices[i]));
                }
                catch { }
                if (i > 0 && i % PER_FRAME == 0) yield return null;
            }
            // Fewer rows than asked for = the server ran out of history.
            MatchHistoryLoadedAll = entries.Count < requested;
            if (append && CachedMatchHistory != null)
            {
                // Offset paging can duplicate a row if a new match landed between
                // chunks (everything shifts by one) — dedupe by match id.
                var seen = new HashSet<string>();
                foreach (var m in CachedMatchHistory)
                    if (!string.IsNullOrEmpty(m.match_id)) seen.Add(m.match_id);
                int added = 0;
                foreach (var m in entries)
                    if (string.IsNullOrEmpty(m.match_id) || seen.Add(m.match_id))
                    { CachedMatchHistory.Add(m); added++; }
                Plugin.Log.LogInfo($"Match history extended: +{added} (total {CachedMatchHistory.Count}, all={MatchHistoryLoadedAll})");
            }
            else
            {
                CachedMatchHistory = entries;
                Plugin.Log.LogInfo($"Match history loaded: {CachedMatchHistory.Count} matches (chunked parse, all={MatchHistoryLoadedAll})");
                // Review r1 find 3: a canonical reload (menu open, Refresh,
                // post-match) means the world changed — an ACTIVE search
                // cache is now stale and would miss new matches forever.
                // Refetch it against the same query; bounded to one refetch
                // per canonical reload.
                if (!string.IsNullOrEmpty(MatchHistorySearchQuery))
                {
                    try { FetchMatchHistorySearch(MatchTracker.LocalSteamId, MatchHistorySearchQuery, append: false); }
                    catch { }
                }
            }
            _historyFetchInFlight = false;
            NativeUI.MarkDirty();
        }

        // ── Opponent lifetime H2H (v1.33) ──────────────────────────────────
        // Session Info's "vs Name: XW-YL lifetime" used to scan the full local
        // history; with lazy loading the window may not reach old opponents, so
        // the counts now come from the server's H2H (whole matches table).
        // steam_id -> [my wins, my losses, my SERIES wins, my SERIES losses]
        // (series = completed ranked BO3s vs that opponent — feeds the in-match
        // "Total Series" HUD). Fetched once per opponent per session; a series
        // completing re-arms the fetch (OnSeriesCompletedVsOpponent).
        public static readonly Dictionary<string, int[]> CachedOppLifetime = new Dictionary<string, int[]>();
        private static readonly HashSet<string> _oppLifetimeRequested = new HashSet<string>();
        // Earliest Time.realtimeSinceStartup at which a re-fetch for this
        // opponent may fire. Two jobs (both review finds): (a) a FAILED fetch
        // must not be retried on the HUD's 0.25s cache cadence (4 req/s loop
        // while the server is down) — 10s backoff; (b) after a series-complete
        // bump, an immediate refetch could race the reporter's in-flight
        // /matches POST and overwrite the +1 with the server's PRE-commit
        // count — 20s quiet window before reconciling.
        private static readonly Dictionary<string, float> _oppLifetimeRefetchAfter = new Dictionary<string, float>();

        /// <summary>Called by GameStateWatcher the moment a ranked BO3 vs this
        /// opponent completes — from the local BO3-decision path (the one that
        /// actually runs on both clients) or, for DC/server-confirmed-only
        /// completions, from IncrementSessionRankedSeries; sessionSeriesCounted
        /// guarantees exactly one call per series. Bumps the cached H2H series
        /// tally instantly so the HUD's "Total Series" updates without a
        /// round-trip, and re-arms the fetch (after a quiet window) so a later
        /// FetchOpponentLifetime reconciles with the server's count.</summary>
        public static void OnSeriesCompletedVsOpponent(string oppSteamId, bool won)
        {
            if (string.IsNullOrEmpty(oppSteamId) || oppSteamId.StartsWith("photon_")) return;
            int[] v;
            if (CachedOppLifetime.TryGetValue(oppSteamId, out v) && v != null && v.Length >= 4)
            {
                if (won) v[2]++; else v[3]++;
            }
            // 90s, not 20 (Codex review find): the deciding /matches report can
            // sit in the retry outbox past 30s during an API blip — a refetch
            // inside that window reads the PRE-commit count and overwrites the
            // +1 bump for the rest of the session. Stale-for-90s beats
            // wrong-forever; the bump itself keeps the HUD correct meanwhile.
            _oppLifetimeRefetchAfter[oppSteamId] = Time.realtimeSinceStartup + 90f;
            _oppLifetimeRequested.Remove(oppSteamId);
        }

        public static void FetchOpponentLifetime(string oppSteamId)
        {
            string me = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(oppSteamId) || string.IsNullOrEmpty(me) || me == "unknown" || oppSteamId == me) return;
            float refetchAfter;
            if (_oppLifetimeRefetchAfter.TryGetValue(oppSteamId, out refetchAfter)
                && Time.realtimeSinceStartup < refetchAfter) return;
            if (!_oppLifetimeRequested.Add(oppSteamId)) return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{oppSteamId}?viewer_steam_id={me}",
                (ok, resp) =>
                {
                    if (!ok || string.IsNullOrEmpty(resp))
                    {
                        // Allow a retry later — but on a BACKOFF, not on the
                        // HUD's 0.25s cache cadence (review find: a failing
                        // fetch became a 4 req/s loop for the whole match).
                        _oppLifetimeRefetchAfter[oppSteamId] = Time.realtimeSinceStartup + 10f;
                        _oppLifetimeRequested.Remove(oppSteamId);
                        return;
                    }
                    // h2h_*_wins are the VIEWER's wins (main.py H2H orientation).
                    int w = ExtractJsonInt(resp, "h2h_ranked_wins") + ExtractJsonInt(resp, "h2h_casual_wins");
                    int l = ExtractJsonInt(resp, "h2h_ranked_losses") + ExtractJsonInt(resp, "h2h_casual_losses");
                    int sw = ExtractJsonInt(resp, "h2h_series_wins");
                    int sl = ExtractJsonInt(resp, "h2h_series_losses");
                    CachedOppLifetime[oppSteamId] = new[] { w, l, sw, sl };
                    NativeUI.MarkDirty();
                }));
        }

        /// <summary>Split a `[{..},{..}]` history response into per-match object
        /// slices, STRING-AWARE (learning #156): opponent display names are
        /// user-authored and can contain any bracket/brace/key-shaped text, so
        /// a plain split on "match_id" corrupts rows (and the count → the
        /// offset pager). Cheap linear scan; the expensive per-field parse
        /// stays frame-chunked in the callers.</summary>
        private static List<string> SliceHistoryObjects(string response)
        {
            int arrStart = response.IndexOf('[');
            if (arrStart < 0) return new List<string>();
            int arrEnd = FindMatchingBracketStringAware(response, arrStart);
            if (arrEnd < 0 || arrEnd <= arrStart) return new List<string>();
            return SliceTopLevelObjects(response.Substring(arrStart, arrEnd - arrStart + 1));
        }

        private static MatchHistoryEntry ParseMatchHistoryChunkEntry(string chunk)
        {
            var entry = new MatchHistoryEntry();
            // match_id read by KEY (bug: the old empty-key ':"' form read the
            // first ':"' in the chunk, which only worked because chunks were
            // Split on "match_id"; both parsers now feed full STRING-AWARE
            // object slices, so an opponent literally named "match_id" can no
            // longer split one row into two — learning #156).
            entry.match_id = ExtractJsonString(chunk, "match_id");
            entry.opponent_name = ExtractJsonString(chunk, "opponent_name");
            entry.opponent_steam_id = ExtractJsonString(chunk, "opponent_steam_id");
            entry.opponent_title = ExtractJsonString(chunk, "opponent_title");
            entry.opponent_title_color = ExtractJsonString(chunk, "opponent_title_color");
            entry.player_rounds_won = ExtractJsonInt(chunk, "player_rounds_won");
            entry.opponent_rounds_won = ExtractJsonInt(chunk, "opponent_rounds_won");
            entry.player_points = ExtractJsonInt(chunk, "player_points");
            entry.opponent_points = ExtractJsonInt(chunk, "opponent_points");
            entry.won = chunk.Contains("\"won\":true") || chunk.Contains("\"won\": true");
            entry.is_ranked = chunk.Contains("\"is_ranked\":true") || chunk.Contains("\"is_ranked\": true");
            entry.ended_at = ExtractJsonString(chunk, "ended_at");
            entry.cards_display = ExtractCardNames(chunk);
            entry.opp_cards_display = ExtractCardNames(chunk, "opponent_cards_picked");
            entry.series_id = ExtractJsonString(chunk, "series_id");
            entry.series_score = ExtractJsonString(chunk, "series_score");
            entry.series_rating_change = ExtractJsonFloat(chunk, "series_rating_change");
            entry.xp_gained = ExtractJsonInt(chunk, "xp_gained");
            entry.gold_gained = ExtractJsonInt(chunk, "gold_gained");
            entry.series_gold_gained = ExtractJsonInt(chunk, "series_gold_gained");
            entry.player_fps_avg = ExtractJsonInt(chunk, "player_fps_avg");
            entry.opponent_fps_avg = ExtractJsonInt(chunk, "opponent_fps_avg");
            entry.player_bullets_fired = ExtractJsonInt(chunk, "player_bullets_fired");
            entry.player_bullets_hit = ExtractJsonInt(chunk, "player_bullets_hit");
            entry.player_blocks_activated = ExtractJsonInt(chunk, "player_blocks_activated");
            entry.player_blocks_successful = ExtractJsonInt(chunk, "player_blocks_successful");
            entry.player_keys_pressed = ExtractJsonInt(chunk, "player_keys_pressed");
            entry.player_active_seconds = ExtractJsonFloat(chunk, "player_active_seconds");
            entry.opp_bullets_fired = ExtractJsonInt(chunk, "opp_bullets_fired");
            entry.opp_bullets_hit = ExtractJsonInt(chunk, "opp_bullets_hit");
            entry.opp_blocks_activated = ExtractJsonInt(chunk, "opp_blocks_activated");
            entry.opp_blocks_successful = ExtractJsonInt(chunk, "opp_blocks_successful");
            entry.opp_keys_pressed = ExtractJsonInt(chunk, "opp_keys_pressed");
            entry.opp_active_seconds = ExtractJsonFloat(chunk, "opp_active_seconds");
            entry.point_timeline = ExtractJsonString(chunk, "point_timeline");
            entry.player_fps_timeline = ExtractJsonString(chunk, "player_fps_timeline");
            entry.opp_fps_timeline = ExtractJsonString(chunk, "opp_fps_timeline");
            entry.player_ping_avg = ExtractJsonInt(chunk, "player_ping_avg");
            entry.opponent_ping_avg = ExtractJsonInt(chunk, "opponent_ping_avg");
            entry.player_ping_timeline = ExtractJsonString(chunk, "player_ping_timeline");
            entry.opp_ping_timeline = ExtractJsonString(chunk, "opp_ping_timeline");
            // July 22 item 1 — Hit%/Block% pair timelines + point-time stamps.
            entry.player_hit_timeline = ExtractJsonString(chunk, "player_hit_timeline");
            entry.opp_hit_timeline = ExtractJsonString(chunk, "opp_hit_timeline");
            entry.player_block_timeline = ExtractJsonString(chunk, "player_block_timeline");
            entry.opp_block_timeline = ExtractJsonString(chunk, "opp_block_timeline");
            entry.point_times = ExtractJsonString(chunk, "point_times");
            entry.duration_seconds = ExtractJsonInt(chunk, "duration_seconds");
            ParseDamageTelemetry(entry, chunk);
            ParseBuildStats(entry, chunk);
            return entry;
        }

        /// <summary>Aug 12 item 1 — the two end-of-game build strings off a
        /// /matches row. Its own helper for the reason spelled out on
        /// ParseDamageTelemetry: when a second /matches parser existed, a field
        /// wired into only one of them silently reported nothing on the other
        /// path (#279). The lean sibling is retired (broadcast W7) — every
        /// /matches parse now flows through ParseMatchHistoryChunkEntry; keep
        /// any future parser calling these helpers.
        ///
        /// ExtractJsonString is the right reader even though the column is
        /// nullable: it searches for `"key":"`, which a JSON null cannot match,
        /// so "not recorded" arrives as "" — the same value the renderer treats
        /// as "no build". There is no 0-vs-null ambiguity to preserve here (the
        /// reason the damage fields needed ExtractNullableInt), because an empty
        /// build string is not a meaningful reading of anything.</summary>
        private static void ParseBuildStats(MatchHistoryEntry entry, string chunk)
        {
            entry.player_end_stats = ExtractJsonString(chunk, "player_end_stats");
            entry.opp_end_stats = ExtractJsonString(chunk, "opp_end_stats");
        }

        /// <summary>Aug 6 item 4 — damage + death telemetry off a /matches row.
        /// A shared helper on purpose: when two /matches parsers existed, a field
        /// added to only one of them silently reported 0 on the other path
        /// (#279 — fix the sibling in the same pass). The lean parser is retired
        /// (broadcast W7); ParseMatchHistoryChunkEntry is the single caller —
        /// any future parser must call this too. ExtractNullableInt
        /// rather than ExtractJsonInt because the server sends JSON null for
        /// every row predating the telemetry clients, and "no data" must render
        /// as a dash, never as "0.0 dps" (#257).</summary>
        private static void ParseDamageTelemetry(MatchHistoryEntry entry, string chunk)
        {
            entry.player_damage_dealt = ExtractNullableInt(chunk, "player_damage_dealt");
            entry.opp_damage_dealt = ExtractNullableInt(chunk, "opp_damage_dealt");
            entry.player_damage_timeline = ExtractJsonString(chunk, "player_damage_timeline");
            entry.opp_damage_timeline = ExtractJsonString(chunk, "opp_damage_timeline");
            entry.player_deaths = ExtractNullableInt(chunk, "player_deaths");
            entry.player_deaths_boundary = ExtractNullableInt(chunk, "player_deaths_boundary");
            entry.player_deaths_own_bullet = ExtractNullableInt(chunk, "player_deaths_own_bullet");
            entry.opp_deaths = ExtractNullableInt(chunk, "opp_deaths");
            entry.opp_deaths_boundary = ExtractNullableInt(chunk, "opp_deaths_boundary");
            entry.opp_deaths_own_bullet = ExtractNullableInt(chunk, "opp_deaths_own_bullet");
        }

        /// <summary>Fetch ANY player's match history for the leaderboard detail view. Does NOT
        /// clobber CachedMatchHistory (that's the local player's). Used to render a clicked
        /// player's ranked history + head-to-head last series. Callback gets the parsed list.
        /// Broadcast W7: parses through the FULL ParseMatchHistoryChunkEntry (the lean
        /// ParseMatchHistoryJson sibling is retired — one parser, #279), chunked across
        /// frames like the local-history path, so entries carry every timeline + combat
        /// scalar the report engine's graph panels need.</summary>
        public static void FetchMatchHistoryForView(string steamId, Action<List<MatchHistoryEntry>> callback, int limit = 400)
        {
            // Legacy single-callback overload — delegates to the ok-carrying
            // variant with ok ignored (R1 f10 contract; NativeUI callers keep
            // their existing shape and semantics).
            FetchMatchHistoryForView(steamId, (list, ok) => { try { callback?.Invoke(list); } catch { } }, limit);
        }

        /// <summary>R1 f10: ok-carrying variant for the post-session report.
        /// transportOk=false means HTTP or parse failure — the consumer renders
        /// "(partial)" instead of claiming "0 games". (empty list, true) means a
        /// 200 with a genuinely empty history. The invalid-steamId guard reports
        /// false too: no successful read happened, so "confirmed empty" would be
        /// a lie. Result list is REPORT-PRIVATE (R1 f9) — never written to
        /// CachedMatchHistory or any other shared cache.</summary>
        public static void FetchMatchHistoryForView(string steamId, Action<List<MatchHistoryEntry>, bool> callback, int limit = 400)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") { callback?.Invoke(new List<MatchHistoryEntry>(), false); return; }
            // Server bound is Query(100, ge=1, le=2000) — out-of-range 422s
            // rather than clamping, so clamp here.
            if (limit < 1) limit = 1; else if (limit > 2000) limit = 2000;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{steamId}/matches?limit={limit}",
                (success, response) =>
                {
                    if (!success) { try { callback?.Invoke(new List<MatchHistoryEntry>(), false); } catch { } return; }
                    Plugin.Instance.StartCoroutine(ParseMatchHistoryForViewChunked(response, callback));
                }
            ));
        }

        /// <summary>View-path twin of ParseMatchHistoryChunked: same PER_FRAME
        /// budget, same entry parser, but hands the list to a callback instead
        /// of writing CachedMatchHistory (that's the local player's).
        /// Result ordering = server ordering (newest first), preserved.
        /// R1 f11: entry boundaries come from the string-aware top-level slicer,
        /// NEVER a token split on "match_id" — a display name ending in
        /// `"match_id` forges that needle across the escaped quote and the
        /// string terminator (#156), splitting one real game into two broken
        /// fragments. Since Aug 23 BOTH history parsers (local chunked and
        /// search) slice with SliceHistoryObjects and the shared entry parser
        /// reads match_id by KEY — there is no token-splitting path left.</summary>
        private static System.Collections.IEnumerator ParseMatchHistoryForViewChunked(string response, Action<List<MatchHistoryEntry>, bool> callback)
        {
            var entries = new List<MatchHistoryEntry>();
            // R2 f3: a SUCCESSFUL response with a null/blank/whitespace body is
            // a truncated/empty read, NOT a confirmed-empty history — report
            // ok=false so the consumer renders "(partial)" instead of a clean
            // "0 games". (empty, true) is reserved for a successfully parsed
            // empty array below.
            if (string.IsNullOrWhiteSpace(response))
            {
                Plugin.Log.LogWarning("[LBVIEW] match parse failed: blank body on a successful response");
                try { callback?.Invoke(entries, false); } catch { }
                yield break;
            }
            if (response.Trim() == "[]")
            {
                try { callback?.Invoke(entries, true); } catch { }
                yield break;
            }
            List<string> chunks = null;
            try
            {
                int open = response.IndexOf('[');
                int close = open >= 0 ? FindMatchingBracketStringAware(response, open) : -1;
                if (open >= 0 && close > open)
                    chunks = SliceTopLevelObjects(response.Substring(open + 1, close - open - 1));
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[LBVIEW] match parse failed: {ex.Message}");
            }
            if (chunks == null)
            {
                // Missing/unbalanced top-level array on a non-empty 200 is a
                // PARSE failure, not an empty history — report false (f10).
                Plugin.Log.LogWarning("[LBVIEW] match parse failed: top-level array not found");
                try { callback?.Invoke(entries, false); } catch { }
                yield break;
            }
            const int PER_FRAME = 80;
            for (int i = 0; i < chunks.Count; i++)
            {
                try
                {
                    var entry = ParseMatchHistoryChunkEntry(chunks[i]);
                    // The shared entry parser already reads match_id by KEY (Aug 23,
                    // review r2 H1); this re-read is redundant and kept only as a
                    // belt-and-braces guard for whole-object chunks.
                    entry.match_id = ExtractJsonString(chunks[i], "match_id");
                    entries.Add(entry);
                }
                catch { }
                if ((i + 1) % PER_FRAME == 0) yield return null;
            }
            try { callback?.Invoke(entries, true); } catch { }
        }

        private static string ExtractJsonString(string json, string key)
        {
            try
            {
                // When key is empty, we're reading the value right after a split point
                // Chunk starts with :"value",... so search for :"
                // When key is set, search for "key":"
                string search = string.IsNullOrEmpty(key) ? ":\"" : $"\"{key}\":\"";
                int start = json.IndexOf(search);
                if (start < 0) return "";
                start += search.Length;
                // Scan forward, skipping escaped chars. Without this, any value
                // containing a literal " (encoded as \" in JSON) truncates the
                // parse — bug reports with quoted log text were losing the rest
                // of the field + bleeding into adjacent fields.
                int i = start;
                var sb = new System.Text.StringBuilder();
                while (i < json.Length)
                {
                    char c = json[i];
                    if (c == '\\' && i + 1 < json.Length)
                    {
                        char nx = json[i + 1];
                        switch (nx)
                        {
                            case '"':  sb.Append('"');  i += 2; continue;
                            case '\\': sb.Append('\\'); i += 2; continue;
                            case '/':  sb.Append('/');  i += 2; continue;
                            case 'n':  sb.Append('\n'); i += 2; continue;
                            case 'r':  sb.Append('\r'); i += 2; continue;
                            case 't':  sb.Append('\t'); i += 2; continue;
                            case 'b':  sb.Append('\b'); i += 2; continue;
                            case 'f':  sb.Append('\f'); i += 2; continue;
                            case 'u':
                                if (i + 5 < json.Length)
                                {
                                    string hex = json.Substring(i + 2, 4);
                                    if (int.TryParse(hex, System.Globalization.NumberStyles.HexNumber,
                                                     System.Globalization.CultureInfo.InvariantCulture, out int code))
                                    {
                                        sb.Append((char)code);
                                        i += 6;
                                        continue;
                                    }
                                }
                                sb.Append(nx); i += 2; continue;
                            default: sb.Append(nx); i += 2; continue;
                        }
                    }
                    if (c == '"') break;
                    sb.Append(c);
                    i++;
                }
                return sb.ToString();
            }
            catch { return ""; }
        }

        // Public alias so CompetitiveUI can reuse the helper without exposing
        // every parser internal. Same semantics as ExtractJsonInt.
        public static string ExtractJsonStringPublic(string json, string key) => ExtractJsonString(json, key);
        public static int ExtractJsonIntPublic(string json, string key) => ExtractJsonInt(json, key);

        /// <summary>Reads a flat array of strings ("xp_bonuses":["a","b"]) into a list.
        /// Quote-aware, so a label containing a comma can't split into two entries —
        /// these labels are SERVER-generated, but the naive split-on-comma version of
        /// this parse already exists inline in the 1v1 path and is one comma away from
        /// being wrong (cf. #156: only server-generated, bracket-free values are safe
        /// for the naive slicers). Returns an empty list when the key is absent, so a
        /// server that doesn't send it yet degrades silently.</summary>
        private static List<string> ExtractJsonStringArray(string json, string key)
        {
            var outList = new List<string>();
            try
            {
                if (string.IsNullOrEmpty(json)) return outList;
                int at = json.IndexOf("\"" + key + "\":", StringComparison.Ordinal);
                if (at < 0) return outList;
                int open = json.IndexOf('[', at);
                if (open < 0) return outList;
                bool inStr = false, esc = false;
                var cur = new StringBuilder(32);
                for (int i = open + 1; i < json.Length; i++)
                {
                    char c = json[i];
                    if (inStr)
                    {
                        if (esc) { cur.Append(c); esc = false; continue; }
                        if (c == '\\') { esc = true; continue; }
                        if (c == '"')
                        {
                            inStr = false;
                            if (cur.Length > 0) outList.Add(cur.ToString());
                            cur.Length = 0;
                            continue;
                        }
                        cur.Append(c);
                        continue;
                    }
                    if (c == '"') { inStr = true; continue; }
                    if (c == ']') break;
                }
            }
            catch { }
            return outList;
        }
        public static float ExtractJsonFloatPublic(string json, string key) => ExtractJsonFloat(json, key);

        private static int ExtractJsonInt(string json, string key)
        {
            try
            {
                string search = $"\"{key}\":";
                int start = json.IndexOf(search);
                if (start < 0) return 0;
                start += search.Length;
                // Skip whitespace
                while (start < json.Length && (json[start] == ' ' || json[start] == '\t')) start++;
                int end = start;
                while (end < json.Length && (char.IsDigit(json[end]) || json[end] == '-')) end++;
                if (end == start) return 0;
                return int.Parse(json.Substring(start, end - start));
            }
            catch { return 0; }
        }

        private static float ExtractJsonFloat(string json, string key)
        {
            try
            {
                string search = $"\"{key}\":";
                int start = json.IndexOf(search);
                if (start < 0) return 0f;
                start += search.Length;
                while (start < json.Length && (json[start] == ' ' || json[start] == '\t')) start++;
                // Check for null
                if (start < json.Length && json[start] == 'n') return 0f;
                int end = start;
                while (end < json.Length && (char.IsDigit(json[end]) || json[end] == '.' || json[end] == '-')) end++;
                if (end == start) return 0f;
                return float.Parse(json.Substring(start, end - start),
                    System.Globalization.CultureInfo.InvariantCulture);
            }
            catch { return 0f; }
        }

        private static bool ExtractJsonBool(string json, string key)
        {
            try
            {
                string search = $"\"{key}\":";
                int start = json.IndexOf(search);
                if (start < 0) return false;
                start += search.Length;
                while (start < json.Length && (json[start] == ' ' || json[start] == '\t')) start++;
                return start < json.Length && json[start] == 't'; // "true" vs "false"
            }
            catch { return false; }
        }

        private static string ExtractCardNames(string chunk, string key = "cards_picked")
        {
            try
            {
                int cpStart = chunk.IndexOf("\"" + key + "\"");
                if (cpStart < 0) return "";

                int arrStart = chunk.IndexOf("[", cpStart);
                int arrEnd = chunk.IndexOf("]", arrStart);
                if (arrStart < 0 || arrEnd < 0) return "";

                string arr = chunk.Substring(arrStart, arrEnd - arrStart + 1);
                if (arr == "[]") return "";

                var names = new List<string>();
                var cardParts = arr.Split(new[] { "\"card_name\"" }, StringSplitOptions.None);
                for (int j = 1; j < cardParts.Length; j++)
                {
                    string name = ExtractJsonString(cardParts[j], "");
                    if (!string.IsNullOrEmpty(name) && name != "Unknown")
                        names.Add(name);
                }

                return names.Count > 0 ? string.Join(", ", names.ToArray()) : "";
            }
            catch { return ""; }
        }

        // TriggerGlickoRecalc was deleted (Aug 23) along with the server's
        // /glicko/recalculate endpoint: it had zero callers, a hardcoded "dev"
        // api key that could never authenticate, and the endpoint it targeted
        // would have double-applied every rated series and rated casual games.
        // Inline series-completion updates are the only 1v1 rating path.

        /// <summary>Read a resumed BO3 tally out of any server response carrying
        /// the {p1_steam_id, p2_steam_id, p1_wins, p2_wins} shape, resolved to
        /// MY perspective.
        ///
        /// Three responses emit that shape deliberately identically: the
        /// /series/preflight "exists" branch, /queue/ready's both_ready, and the
        /// queue poll's ready_join. Bug 200 was caused by only the FIRST of them
        /// carrying it — and the queue lock, by assigning ActiveRankedSeriesId,
        /// closes the IsNullOrEmpty gate that arms the preflight, so for game 1
        /// of every queue-issued series the preflight is unreachable and a
        /// resumed series rendered 0-0.
        ///
        /// Returns false for a fresh 0-0 series (nothing to adopt) and for an
        /// old server that omits the fields — absent participant ids must never
        /// be treated as "I am p2", which would invert an unrelated score.</summary>
        public static bool TryResolveResumedScore(string resp, string mySteamId,
                                                  out int myWins, out int oppWins)
        {
            myWins = 0; oppWins = 0;
            try
            {
                int p1w = (int)ExtractJsonFloat(resp, "p1_wins");
                int p2w = (int)ExtractJsonFloat(resp, "p2_wins");
                // An active BO3 can only be 0 or 1 on either side. A terminal
                // or negative payload is stale/malformed and must not become
                // the room's current-series phase.
                if (p1w < 0 || p2w < 0 || p1w >= 2 || p2w >= 2) return false;
                if (p1w <= 0 && p2w <= 0) return false;   // fresh series
                string sp1 = ExtractJsonString(resp, "p1_steam_id");
                string sp2 = ExtractJsonString(resp, "p2_steam_id");
                // Perspective is UNRESOLVABLE without both ids — bail rather
                // than guess (an old server sends neither).
                if (string.IsNullOrEmpty(sp1) || string.IsNullOrEmpty(sp2)
                    || string.IsNullOrEmpty(mySteamId)) return false;
                bool meIsP1 = sp1 == mySteamId;
                if (!meIsP1 && sp2 != mySteamId) return false;
                myWins = meIsP1 ? p1w : p2w;
                oppWins = meIsP1 ? p2w : p1w;
                return true;
            }
            catch { return false; }
        }

        /// <summary>THE single place a resumed score reaches the HUD and the
        /// player. Both the preflight path (already in the room) and the
        /// queue-lock path (via GameStateWatcher's stash, applied on room join)
        /// funnel through here so the toast can never drift between them.</summary>
        public static void ApplyResumedSeriesScore(int myWins, int oppWins,
                                                   int expectedRoomSeriesGeneration)
        {
            try
            {
                if (GameStateWatcher.AdoptSeriesScore(
                        myWins, oppWins, expectedRoomSeriesGeneration))
                {
                    CompetitiveUI.QueueNotification(
                        I18n.TrF("Resuming series at {0}-{1}",
                            GameStateWatcher.CurrentSeriesGamesWon,
                            GameStateWatcher.CurrentSeriesGamesLost),
                        new Color(1f, 0.85f, 0.3f), 4f);
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[SERIES] resumed-score apply failed: {ex.Message}"); }
        }

        /// <summary>Pre-create a ranked_series row on the server for a private-room
        /// match between two ranked-enabled mod users. Idempotent — server reuses
        /// any existing active series for the pair. Without this, private-room
        /// games don't appear in /series/active until the first match completes,
        /// so spectators can't see them in the Live Ranked Games panel.</summary>
        public static void SendSeriesPreflight(string mySteamId, string oppSteamId)
        {
            if (string.IsNullOrEmpty(mySteamId) || string.IsNullOrEmpty(oppSteamId)) return;
            // Server signs HMAC over the sorted-pair canonical so either side can
            // post the preflight without coordinating who's p1/p2.
            string a = string.Compare(mySteamId, oppSteamId, StringComparison.Ordinal) <= 0 ? mySteamId : oppSteamId;
            string b = a == mySteamId ? oppSteamId : mySteamId;
            string sig = ComputeHmacHex($"preflight:{a}:{b}");
            // Pass display names so first-time-seen players show as their
            // actual nickname in Live Ranked Games / Recent Series, not as
            // the bare Steam ID until their next /stats call.
            string myName = MatchTracker.LocalDisplayName ?? mySteamId;
            string oppName = GameStateWatcher.OpponentDisplayName ?? oppSteamId;
            // Room context → server decides is_private (queue/tournament rooms
            // keep the tight bet lock and no PRIVATE tag; code-join rooms get
            // the wider private window). #36.
            string roomName = "";
            try { roomName = Photon.Pun.PhotonNetwork.CurrentRoom?.Name ?? ""; } catch { }
            string preflightRoom = roomName;   // name half of the callback fence
            // r4 find 2: room name alone ALIASES successive series in one
            // room (a rematch reuses the Photon room), so a delayed response
            // could reinstall a completed series and send the NEW series'
            // live points to it. Every send takes a generation; only the
            // newest may bind.
            int myGen = ++preflightGeneration;
            // Tournament r2 find 2: the name also aliases successive
            // INCARNATIONS of one code room (leave CODE, rejoin CODE with a
            // different opponent) — the incarnation counter, bumped by both
            // Photon room callbacks, is what the name check cannot be.
            int myIncarnation = RoomIncarnation;
            int roomSeriesGeneration = GameStateWatcher.RoomSeriesGeneration;
            string url = $"{baseUrl}/api/v1/series/preflight?p1_steam_id={Escape(mySteamId)}&p2_steam_id={Escape(oppSteamId)}"
                       + $"&p1_name={Escape(myName)}&p2_name={Escape(oppName)}"
                       + $"&room_id={UnityEngine.Networking.UnityWebRequest.EscapeURL(roomName)}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                if (ok)
                {
                    // Aug 9 bet audit r3 find 3: this response describes the
                    // room the request was SENT from. If we have since left
                    // or changed rooms it must not bind anything — installing
                    // its series id here made Room B report its live points
                    // into Room A's series, and the teardown-only guard below
                    // was too late to stop that.
                    string roomNow = "";
                    try { roomNow = Photon.Pun.PhotonNetwork.CurrentRoom?.Name ?? ""; } catch { }
                    bool sameRoom = string.Equals(roomNow, preflightRoom, StringComparison.Ordinal);
                    if (myGen != preflightGeneration || myGen <= preflightRetiredThrough)
                    {
                        Plugin.Log.LogInfo($"[PREFLIGHT] response ignored — superseded (gen {myGen}, "
                                           + $"latest {preflightGeneration}, retired through {preflightRetiredThrough})");
                        return;
                    }
                    if (myIncarnation != RoomIncarnation)
                    {
                        // r2 find 2: same NAME, different room — a leave (or
                        // leave+rejoin) happened since this request was sent,
                        // so nothing it says may bind to the room we are in
                        // now. The name check below cannot catch this case.
                        Plugin.Log.LogInfo($"[PREFLIGHT] response ignored — room incarnation changed "
                                           + $"(sent in {myIncarnation}, now {RoomIncarnation})");
                        return;
                    }
                    // r3 find 2: PUN flips the client to Leaving SYNCHRONOUSLY
                    // inside LeaveRoom(), but CurrentRoom stays populated and
                    // OnLeftRoom (which bumps the incarnation) only fires on a
                    // later dispatch — so a coroutine resuming in that window
                    // passes BOTH fences above while the room is already dead.
                    // Nothing may bind unless the client is actually Joined.
                    bool joinedNow = false;
                    try
                    {
                        joinedNow = Photon.Pun.PhotonNetwork.InRoom
                                    && !Photon.Pun.PhotonNetwork.OfflineMode;
                    }
                    catch { }
                    if (!joinedNow)
                    {
                        Plugin.Log.LogInfo("[PREFLIGHT] response ignored — client is not in a joined room (leaving/left)");
                        return;
                    }
                    if (!sameRoom)
                    {
                        Plugin.Log.LogInfo("[PREFLIGHT] response ignored — room changed since the request "
                                           + $"(sent from '{preflightRoom}', now '{roomNow}')");
                        return;
                    }
                    string sid = ExtractJsonString(resp, "series_id");
                    if (!string.IsNullOrEmpty(sid))
                    {
                        // Aug 15 (bug 231): tournament banner context from the
                        // preflight's contract fields. The key-presence guard is
                        // LOAD-BEARING: an old server that lacks the field must
                        // not clear the sct- room-identity seed (absent = no
                        // change), while an explicit tournament:false from a
                        // new server correctly clears it for a non-tournament
                        // rematch series in the same room. The probe cannot
                        // false-match "tournament_label": (closing quote
                        // differs). Inherits this callback's generation +
                        // same-room fences above — those ARE the room binding
                        // that makes the flag safe to store.
                        //
                        // ORDER IS LOAD-BEARING (Aug 30 r2/r3): tournament
                        // context and its room-scoped provenance latch land
                        // BEFORE ActiveRankedSeriesId is published.
                        // EscLeaveRow requires BOTH the id and the latch — a
                        // staged id alone is not current-room proof (it can
                        // survive a failed queue join into a later room).
                        // The log sits after all state writes in its own try
                        // so a throwing listener cannot split them.
                        try
                        {
                            if (resp != null && resp.Contains("\"tournament\":"))
                            {
                                GameStateWatcher.SetTournamentContext(
                                    ExtractJsonBool(resp, "tournament"),
                                    ExtractJsonString(resp, "tournament_label"));
                                // Provenance latch (r3 finding 1): THIS room's
                                // preflight has now answered tournament-or-not.
                                GameStateWatcher.MarkTournamentContextResolved();
                            }
                        }
                        catch { }
                        ActiveRankedSeriesId = sid;
                        try { Plugin.Log.LogInfo($"[PREFLIGHT] series_id={sid} status={ExtractJsonString(resp, "status")}"); } catch { }
                        // Aug 9 (Sid): a rated ROOMCODE game must end every
                        // other search — the room-entry teardown deliberately
                        // ignores non-prefix rooms (bug #112: casual-while-
                        // searching is supported), so THIS is the first
                        // client-side moment the game is known rated. The
                        // server's preflight-time eviction covers old
                        // clients; this mirror gives the local UI immediate
                        // truth instead of a poll-time not_in_queue surprise.
                        try
                        {
                            // (the whole callback is already room-fenced above)
                            //
                            if (CurrentQueueState == QueueState.Searching)
                            {
                                Plugin.Log.LogInfo("[PREFLIGHT] rated room-code game confirmed — leaving the 1v1 search");
                                LeaveQueue(MatchTracker.LocalSteamId);
                            }
                            else if (CurrentQueueState == QueueState.Matched || CurrentQueueState == QueueState.ReadySent)
                            {
                                // Aug 9 bet audit r1 find 7: NOT DeclineMatch —
                                // decline puts both players back to
                                // 'searching', so the fighter in this rated
                                // room stays matchable (and a decline after a
                                // queue room was issued 409s, then the next
                                // poll's ready_join + LeavingForRanked yanks
                                // them OUT of the rated game). LeaveQueue
                                // deletes our row; the server's own eviction
                                // resets the innocent partner.
                                Plugin.Log.LogInfo("[PREFLIGHT] rated room-code game confirmed — leaving the pending 1v1 match");
                                LeaveQueue(MatchTracker.LocalSteamId);
                            }
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[PREFLIGHT] queue teardown failed: {ex.Message}"); }
                        // Resumed series (#33): adopt the server-side BO3 tally so
                        // the HUD doesn't restart at 0-0 after a DC + reconnect.
                        try
                        {
                            string status = ExtractJsonString(resp, "status");
                            if (status == "exists"
                                && TryResolveResumedScore(resp, mySteamId, out int myWins, out int oppWins))
                            {
                                // This path is already IN the room. The shared
                                // helper monotonic-merges any local game-over that
                                // beat this callback and generation-fences later
                                // BO3s. The queue-lock path stashes until join.
                                ApplyResumedSeriesScore(
                                    myWins, oppWins, roomSeriesGeneration);
                            }
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[PREFLIGHT] score adopt failed: {ex.Message}"); }
                    }
                    else
                    {
                        // v1.29 (#42): the server refuses a series when either player
                        // has ranked explicitly disabled. Downgrade the client's view
                        // of the match to casual so the HUD + report agree with the
                        // server (which also enforces this at match submit).
                        string status = ExtractJsonString(resp, "status");
                        if (status == "not_ranked")
                        {
                            Plugin.Log.LogInfo("[PREFLIGHT] server says not_ranked (a player has ranked disabled) — treating match as casual");
                            try { GameStateWatcher.DowngradeToCasual("opponent has ranked disabled"); } catch { }
                        }
                        else
                        {
                            Plugin.Log.LogInfo($"[PREFLIGHT] response: {resp}");
                        }
                    }
                }
                else
                {
                    Plugin.Log.LogWarning($"[PREFLIGHT] failed: {resp}");
                }
            }));
        }

        public static void ToggleRanked(string steamId, bool enabled, int attempt = 1,
                                       string displayName = null)
        {
            // The launch-time ranked sync is the FIRST server contact for a new
            // install and it auto-registers the player, so it must carry the
            // display name or the row is created under the raw Steam ID. Not
            // part of the signed canonical: the signature covers the ACTION
            // (who toggles what), and adding a mutable field to it would break
            // every older client's signature for no security gain — the server
            // treats the name as advisory and cleans it.
            // EscapeURL, not Escape(): Escape() is the JSON string escaper and
            // does nothing for URLs, while a display name can legitimately
            // contain &, #, + or spaces - which would truncate or inject query
            // parameters. Steam ids and UUIDs elsewhere are digit/hex-only, so
            // the distinction never bit before this field.
            // Resolve the name HERE rather than at the call sites. There are five
            // callers (startup init, the Steam-ready init, the 401 retry, the
            // consent grant, and the two F5 buttons) and only one of them was
            // passing a name — including the one that actually registers a
            // fresh install, so the raw-Steam-ID rows would have kept appearing.
            // Doing it at the single choke point makes every path correct and
            // keeps it correct when the sixth caller appears.
            string nm = displayName;
            if (string.IsNullOrEmpty(nm))
            {
                try { nm = MatchTracker.LocalDisplayName; } catch { nm = null; }
            }
            if (GameStateWatcher.IsPlaceholderName(nm, steamId)) nm = null;
            string nameQ = string.IsNullOrEmpty(nm)
                ? "" : $"&display_name={UnityEngine.Networking.UnityWebRequest.EscapeURL(nm)}"
                       + $"&name_sig={ComputeHmacHex($"toggle-ranked-name:{steamId}:{nm}")}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/mod/toggle-ranked/{steamId}?enabled={enabled.ToString().ToLower()}&sig={ComputeHmacHex($"toggle-ranked:{steamId}:{enabled.ToString().ToLower()}")}{nameQ}",
                "",
                (success, response) =>
                {
                    if (success)
                    {
                        Plugin.Log.LogInfo($"Ranked mode set to {enabled}");
                        CompetitiveUI.ShowNotification(
                            enabled ? "Ranked: ON" : "Ranked: OFF",
                            enabled ? Color.green : Color.yellow
                        );
                    }
                    else if ((response ?? "").Contains("401") && attempt < 3)
                    {
                        // July 22: the Steam session may still be minting in the
                        // startup window — HandleSessionReject already re-armed
                        // it; retry once it lands so the toggle isn't dropped.
                        Plugin.Log.LogWarning($"[RANKED] toggle got 401 (attempt {attempt}) — retrying after session establishes");
                        Plugin.Instance.StartCoroutine(RetryToggleRanked(steamId, enabled, attempt + 1));
                    }
                    else
                    {
                        Plugin.Log.LogError($"Failed to toggle ranked: {response}");
                    }
                }
            ));
        }

        private static IEnumerator RetryToggleRanked(string steamId, bool enabled, int attempt)
        {
            float t = 0f;
            while (t < 6f && !SteamAuth.HasFreshToken) { t += 0.5f; yield return new WaitForSeconds(0.5f); }
            yield return new WaitForSeconds(0.3f);
            ToggleRanked(steamId, enabled, attempt);
        }

        // ── Ranked Queue ──────────────────────────────────────

        public enum QueueState { Idle, Searching, Matched, ReadySent, Leaving }

        [Serializable]
        public class QueuePollData
        {
            public string status;        // searching, matched, ready_join, not_in_queue, expired
            public int wait_time;
            public int queue_size;
            public int elo_range;
            public string opponent_steam_id;
            public string opponent_name;
            public float opponent_rating;
            public bool opponent_ready;
            public string room_name;
            public string photon_region;
        }

        // Current queue state (mod-side)
        public static QueueState CurrentQueueState { get; private set; } = QueueState.Idle;
        // v1.22 — server returns this on /queue/ready when both players ready up. Used by
        // GameStateWatcher's poll to address the correct series when posting live point counts.
        // Cleared after the series's first match report (no longer needed; bets locked anyway).
        public static string ActiveRankedSeriesId;
        /// <summary>r4 find 2: monotonic id for preflight requests. Bumped on
        /// every send; a callback whose captured value is no longer the latest
        /// describes a superseded request and must bind nothing.</summary>
        private static int preflightGeneration;

        /// <summary>Responses whose captured generation is at or below this are
        /// stale: they belong to a request sent BEFORE the game boundary that
        /// set the watermark (r5 find 1 / r6 find 1).
        ///
        /// The watermark is captured SYNCHRONOUSLY when the match report is
        /// SENT — not in its async callback. A blind bump in the callback
        /// superseded the NEXT game's preflight whenever the report response
        /// was slow (up to 3 x 10s of retries), leaving that game with no
        /// series row and therefore no pre-game betting window.</summary>
        private static int preflightRetiredThrough;

        /// <summary>Room-INCARNATION counter (Codex tournament r2 find 2): a
        /// room NAME does not identify a room — code rooms are player-typed
        /// and reusable, so "leave rated room CODE, quickly rejoin CODE with
        /// a casual opponent" lets a delayed preflight response pass the
        /// name-equality fence and reinstall the OLD pairing's series id
        /// and tournament context into the new
        /// incarnation. Incremented by Plugin's Photon OnJoinedRoom AND
        /// OnLeftRoom callbacks (synchronous, cannot be missed the way the
        /// 10 Hz polled edges can); every preflight captures it at send and
        /// its callback refuses to bind across a bump.</summary>
        public static int RoomIncarnation;
        public static QueuePollData LastPollData { get; private set; }
        public static bool IsQueuePolling { get; private set; } = false;
        private static float queuePollTimer = 0f;
        private static float queuePollInterval = 3f;
        // Leaving-state safety timeout (learning #33): the leave callback always
        // fires (success, terminal failure, consent-block, or version-gate), but
        // if the coroutine host dies the join guards force-recover past this age
        // so a stuck Leaving state can never deadlock re-joining. Must exceed
        // the retry worst case (3 attempts × 10s timeout + 2 × 2s delay = 34s).
        private const float LEAVE_STUCK_TIMEOUT = 45f;
        private static float rankedLeavingSince = -999f;
        // F2 (Codex r3): ONE enrollment may be in flight per mode. A hosted
        // Join click and a public Search click could both be in flight at
        // once — the server refuses overwrites of live locked rows now, but
        // the client shouldn't fire the second enrollment at all. Shared
        // latch across the mode's entry points (public queue join, hosted
        // Create, hosted Join): set at send, cleared in each response
        // handler, 25s self-expiry so a lost response (dead coroutine host)
        // can never wedge it (#270c).
        private const float ENROLL_IN_FLIGHT_EXPIRY = 25f;
        private static float _teamEnrollInFlightAt = -999f;
        private static float _ovtEnrollInFlightAt = -999f;
        private static bool EnrollGateBegin(string mode)
        {
            float at = mode == "team" ? _teamEnrollInFlightAt : _ovtEnrollInFlightAt;
            if (Time.realtimeSinceStartup - at < ENROLL_IN_FLIGHT_EXPIRY)
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Still joining - one moment..."), new Color(1f, 0.6f, 0.2f), 4f);
                return false;
            }
            if (mode == "team") _teamEnrollInFlightAt = Time.realtimeSinceStartup;
            else _ovtEnrollInFlightAt = Time.realtimeSinceStartup;
            return true;
        }
        private static void EnrollGateEnd(string mode)
        {
            if (mode == "team") _teamEnrollInFlightAt = -999f;
            else _ovtEnrollInFlightAt = -999f;
        }
        // Lifecycle generation (Codex verify findings 2-4): bumped synchronously
        // on EVERY lifecycle edge (join send, leave start, stuck-recovery).
        // Every async queue callback captures the value at send time and applies
        // only if still current — otherwise a delayed join ack can restore
        // Searching after a leave, a delayed ready ack can post a dissolved
        // room as pending, and a 20s-old poll response from a PREVIOUS
        // lifecycle can auto-join a dead room after a rejoin. One counter per
        // queue; int overflow is a non-issue at click cadence.
        private static int queueGen = 0;

        /// <summary>Stuck-Leaving watchdog (Codex verify finding 1) — ticked
        /// from the persistent poll loop, NOT from the join buttons: the
        /// Leaving views hide those buttons, and the leave callback dies with
        /// its coroutine host (NetworkRestart destroys + respawns the plugin
        /// GO), which would otherwise leave the queue tab unusable until
        /// relaunch. Bumps the generation so a zombie leave callback that
        /// somehow fires later cannot touch the recovered state.</summary>
        public static void TickLeaveRecovery()
        {
            // A persisted escape intent outranks every other recovery path and
            // must run before them: they all try to reconcile a commitment the
            // player has explicitly revoked.
            TickEscapeRetry();
            float now = Time.realtimeSinceStartup;
            if (CurrentQueueState == QueueState.Leaving && now - rankedLeavingSince > LEAVE_STUCK_TIMEOUT)
            {
                queueGen++;
                CurrentQueueState = QueueState.Idle;
                Plugin.Log.LogWarning("[QUEUE] Leaving state stuck past timeout -- recovered to Idle");
                NativeUI.MarkDirty();
            }
            if (CurrentTeamQueueState == TeamQueueState.Leaving && now - teamLeavingSince > LEAVE_STUCK_TIMEOUT)
            {
                teamGen++;
                CurrentTeamQueueState = TeamQueueState.Idle;
                // F3 (Codex r3): the leave callback now owns clearing the
                // series belief (#249) — when it dies with its coroutine
                // host, this watchdog is the clear's durable home.
                ActiveTeamSeriesId = null;
                Plugin.Log.LogWarning("[TEAM-QUEUE] Leaving state stuck past timeout -- recovered to Idle");
                NativeUI.MarkDirty();
            }
            if (OvtQueueStatus == "leaving" && now - _ovtLeavingSince > LEAVE_STUCK_TIMEOUT)
            {
                ovtGen++;
                OvtQueueStatus = "";
                // F3: see the team branch above.
                ActiveOvt1v2SeriesId = null;
                Plugin.Log.LogWarning("[1v2] Leaving state stuck past timeout -- recovered");
                NativeUI.MarkDirty();
            }
            // FFA was the ONE mode with no stuck-Leaving recovery, and it is the
            // one that stranded four players: FfaLeaveQueue tears local state
            // down before its request is even sent, so a lost leave left the
            // client believing it was idle while the server still held a
            // ready_join row that blocked every queue in every mode.
            if (FfaQueueStatus == "leaving" && now - _ffaLeavingSince > LEAVE_STUCK_TIMEOUT)
            {
                ffaGen++;
                FfaQueueStatus = "";
                // Durable leave target (lobby impl round-2 find 2): the leave
                // callback that would have carried the belief may be dead
                // (NetworkRestart kills coroutine-hosted requests). Restore
                // the belief from the static so the poll-driven leave-intent
                // retry machinery owns the seat; without this, polling stayed
                // off while the server still held the row.
                if (_ffaLeaveIntent && string.IsNullOrEmpty(OpenFfaLobbyId)
                    && !string.IsNullOrEmpty(_ffaLeaveTargetLobby))
                    OpenFfaLobbyId = _ffaLeaveTargetLobby;
                Plugin.Log.LogWarning("[FFA] Leaving state stuck past timeout -- recovered"
                    + (_ffaLeaveIntent ? $" (leave retry re-armed for {OpenFfaLobbyId})" : ""));
                NativeUI.MarkDirty();
            }
            // Re-arm the poll when we hold a lobby but are NOT in a room.
            //
            // This is the root fix. The client disarms polling the instant a
            // lobby locks, which is why the server's sitting-over self-heal
            // ("every member polled within 90s") could never fire for a
            // dispersed lobby - it was dead code for exactly the population it
            // was written for. Resuming the poll while locked-but-roomless
            // makes that heal reachable with its intended meaning: everyone is
            // back at the menu, so the sitting really is over. It also gives the
            // client its own escape, because the poll is what discovers that the
            // lobby has been closed.
            //
            // Gated on OfflineMode so leaving Sandbox (which lingers InRoom at
            // the menu, #122) does not look like a live game.
            if ((!string.IsNullOrEmpty(ActiveFfaLobbyId) || !string.IsNullOrEmpty(OpenFfaLobbyId))
                && !IsFfaQueuePolling
                && FfaQueueStatus != "leaving")
            {
                bool inRoom = false;
                try { inRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode; } catch { }
                // Bug #132: an OPEN lobby seat may ride along a CASUAL game
                // (Sid's design — waiting in casual is allowed), and the poll
                // is the only way that member ever sees the host press Start.
                // Arm immediately: unlike the locked/roomless case there is no
                // "give up" signal to protect, the row simply stays 'lobby'.
                bool casualWithOpenSeat = false;
                try
                {
                    casualWithOpenSeat = inRoom
                        && !CompetitiveRoomDetect.IsCompetitiveRoom()
                        && !string.IsNullOrEmpty(OpenFfaLobbyId)
                        && string.IsNullOrEmpty(ActiveFfaLobbyId);
                }
                catch { }
                if (casualWithOpenSeat)
                {
                    Plugin.Log.LogInfo("[FFA-LOBBY] waiting in a casual game with an open lobby seat -- resuming poll to catch the host's Start");
                    IsFfaQueuePolling = true;
                    _ffaRoomlessSince = -1f;
                }
                else if (!inRoom)
                {
                    if (_ffaRoomlessSince < 0f) _ffaRoomlessSince = now;
                    // 20s of grace: the gap between the lock and actually being
                    // in the Photon room is legitimately roomless, and re-arming
                    // inside it would make the server think we had given up.
                    // OpenFfaLobbyId rides the same recovery: an open-lobby
                    // belief with a dead poll loop is always wrong — the poll
                    // is what discovers whether the membership still exists.
                    if (now - _ffaRoomlessSince > 20f)
                    {
                        Plugin.Log.LogInfo("[FFA] holding a lobby but not in a room -- resuming queue poll so the server can free us");
                        IsFfaQueuePolling = true;
                        _ffaRoomlessSince = -1f;
                    }
                }
                else _ffaRoomlessSince = -1f;
            }
            else _ffaRoomlessSince = -1f;
            // v1.37 host lobbies: the /lobby/state heartbeat MUST run from
            // this always-on loop — a member whose polls stop for ~75s is
            // lease-expired out of the lobby server-side, and a tab ticker
            // dies the moment the F5 menu closes (learning #50's class).
            TeamLobby.Tick();
            OvtLobby.Tick();
        }

        private static float _ffaRoomlessSince = -1f;

        // ── Escape hatch: "Leave all queues" (bug report #124) ──────────────
        //
        // The server side is a single DELETE of the player's queue lease, so
        // nothing else can roll it back. This side's job is to make sure the
        // request actually gets there, from a player whose client may be in
        // any state at all — including one that has just been relaunched.
        //
        // The intent is PERSISTED, not held in a static. Every previous
        // recovery mechanism here lived in a static that a relaunch cleared, a
        // coroutine that NetworkRestart killed, or a tab ticker that only ran
        // while the player was looking at the right screen. A player who quits
        // in frustration is exactly the one who needs this to survive.
        private const string ESCAPE_PREF = "cr_escape_pending";
        private static float _escapeRetryAt = -999f;

        public static bool EscapePending
        {
            get { try { return PlayerPrefs.GetInt(ESCAPE_PREF, 0) == 1; } catch { return false; } }
            private set
            {
                try { PlayerPrefs.SetInt(ESCAPE_PREF, value ? 1 : 0); PlayerPrefs.Save(); }
                catch { }
            }
        }

        /// <summary>Revoke every queue commitment, in every mode. Safe to call
        /// from any state; idempotent server-side.</summary>
        public static void EscapeAllQueues(Action<bool, string> done = null)
        {
            EscapePending = true;
            TearDownAllQueueBeliefs();
            SendEscapeRequest(done);
        }

        /// <summary>Drop every local belief about being queued. Runs BEFORE the
        /// request and again on success: the point of the button is that the
        /// client stops acting queued immediately, and re-running it on the ack
        /// catches anything a racing poll callback re-armed in between.</summary>
        private static void TearDownAllQueueBeliefs()
        {
            try
            {
                // Bump every lifecycle generation first — in-flight poll and
                // leave callbacks all check their gen and will now no-op
                // instead of resurrecting the state we are about to clear.
                queueGen++; teamGen++; ovtGen++; ffaGen++;

                CurrentQueueState = QueueState.Idle;
                IsQueuePolling = false;

                IsTeamQueuePolling = false;
                ActiveTeamSeriesId = null;
                // Bug 247: the escape hatch cleared the FFA slot but left the
                // 2v2/1v2 pending slots and the team queue STATE armed — both
                // are SpectateCommitmentBlocked predicates, so a mid-series
                // DC'd player who pressed "Leave All Queues" (the documented
                // remedy) still could not spectate: the client kept believing
                // it was in the 2v2. Mirror the not_in_queue handler's full
                // clear set.
                CurrentTeamQueueState = TeamQueueState.Idle;
                LastTeamPollData = null;
                try { Plugin.ClearPending2v2Slot(); } catch { }

                IsOvtQueuePolling = false;
                OvtQueueStatus = "";
                ActiveOvt1v2SeriesId = null;
                try { Plugin.ClearPendingOvtSlot(); } catch { }

                IsFfaQueuePolling = false;
                FfaQueueStatus = "";
                FfaQueueCount = 0; FfaGatherSecondsLeft = -1;
                ActiveFfaLobbyId = null; OpenFfaLobbyId = null;
                FfaLockedRoster = null; FfaMySlot = -1; FfaLobbyPlayerCount = 0;
                FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                _ffaLeaveIntent = false; _ffaLeaveTargetLobby = null; _ffaLeaveCause = "";
                _ffaJoinCountdownKey = null; _ffaJoinCountdownActiveToken = 0;
                _ffaRoomlessSince = -1f;

                // v1.37 host lobbies: open 2v2/1v2 seats are queue commitments
                // too — the escape lease-delete frees them server-side, and the
                // local beliefs must die with it.
                TeamLobby.TearDown();
                OvtLobby.TearDown();

                try { CompetitiveUI.CancelFfaStartCountdown(); } catch { }
                try { Plugin.ClearPendingFfaSlot(); } catch { }
                // Any pending competitive room join dies with the commitment —
                // otherwise QueueRoomJoiner still fires us into a room we just
                // told the server we are not part of.
                try
                {
                    string pend = Plugin.PendingRankedRoom ?? "";
                    if (pend.StartsWith("ranked_") || pend.StartsWith("team_")
                        || pend.StartsWith("ovt_") || pend.StartsWith("ffa_")
                        || pend.StartsWith("sct-"))
                        Plugin.ClearPendingRoom();
                }
                catch { }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[ESCAPE] teardown: {ex.Message}"); }
            NativeUI.MarkDirty();
        }

        private static void SendEscapeRequest(Action<bool, string> done)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown")
            {
                // Keep the intent: identity resolves a few seconds after
                // launch, and the retry in TickLeaveRecovery will pick it up.
                done?.Invoke(false, "identity not resolved yet");
                return;
            }
            _escapeRetryAt = Time.unscaledTime;
            string url = $"{baseUrl}/api/v1/queues/escape?steam_id={UnityWebRequest.EscapeURL(sid)}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(url, "", (ok, resp) =>
            {
                if (ok)
                {
                    EscapePending = false;
                    // Client review find 1: a RETRIED escape can succeed AFTER
                    // the player re-enrolled in a new queue/lobby — its
                    // unconditional teardown then nuked the NEW lifecycle
                    // (vanishing ready_join, stranded teammates). The eager
                    // teardown at click time already cleared everything and
                    // bumped the lifecycle gens, so gen-fenced stale callbacks
                    // CANNOT re-arm these — any armed state now is a genuine
                    // re-enrollment, which supersedes the old escape intent.
                    bool reEngaged = false;
                    try
                    {
                        // Verify round: the predicate must cover EVERY
                        // enrollment surface — hosted 2v2/1v2 lobby seats
                        // live in TeamLobby/OvtLobby (their enroll DISABLES
                        // the queue-polling flags), a 1v1 ready_join parks
                        // only PendingRankedRoom, and a join REQUEST in
                        // flight is visible via the queue action marker.
                        // Residual (documented): a lobby-join round-trip
                        // that sets no marker can still be invisible for
                        // one HTTP RTT — a >=15s-delayed escape landing in
                        // exactly that window is accepted as negligible.
                        string _pendRoom = Plugin.PendingRankedRoom ?? "";
                        reEngaged = IsQueuePolling || IsTeamQueuePolling
                            || IsOvtQueuePolling || IsFfaQueuePolling
                            || CurrentTeamQueueState != TeamQueueState.Idle
                            || !string.IsNullOrEmpty(ActiveFfaLobbyId)
                            || Plugin.Pending2v2Slot >= 0
                            || Plugin.PendingOvtSlot >= 0
                            || Plugin.PendingFfaSlot >= 0
                            || TeamLobby.Polling || OvtLobby.Polling
                            || !string.IsNullOrEmpty(TeamLobby.OpenLobbyId)
                            || !string.IsNullOrEmpty(OvtLobby.OpenLobbyId)
                            || Time.realtimeSinceStartup < queueRequestInFlightUntil
                            || _pendRoom.StartsWith("ranked_")
                            || _pendRoom.StartsWith("team_")
                            || _pendRoom.StartsWith("ovt_")
                            || _pendRoom.StartsWith("ffa_")
                            || _pendRoom.StartsWith("sct-");
                    }
                    catch { }
                    if (!reEngaged)
                    {
                        TearDownAllQueueBeliefs();
                        CompetitiveUI.ShowNotification("Left all queues", Color.green, 4f);
                    }
                    else
                        Plugin.Log.LogInfo("[ESCAPE] released server-side; local lifecycle re-armed since click - teardown skipped");
                    Plugin.Log.LogInfo($"[ESCAPE] released from all queues: {resp}");
                }
                else
                {
                    // Intent survives. Do NOT tell the player the server will
                    // sort it out — that exact promise, made by the FFA leave
                    // path while the server could not keep it, is what turned a
                    // bug into weeks of "it says it cleared me and it never
                    // does". We retry, and we say we are retrying.
                    Plugin.Log.LogWarning($"[ESCAPE] failed, will keep retrying: {resp}");
                    CompetitiveUI.ShowNotification("Couldn't reach the server - retrying in the background.",
                                                   new Color(1f, 0.6f, 0.2f), 5f);
                }
                done?.Invoke(ok, resp);
            }, maxRetries: 3, retryDelay: 2f));
        }

        /// <summary>Retry a pending escape from the always-on tick. Called from
        /// TickLeaveRecovery so it keeps running with the menu closed, mid-game,
        /// and across relaunches (the intent lives in PlayerPrefs).</summary>
        private static void TickEscapeRetry()
        {
            if (!EscapePending) return;
            // Client review find 1 companion: a successful re-enrollment
            // PROVES the server accepted the player — nothing is left to
            // escape, and firing the old intent later would tear down the
            // new lifecycle. An explicit join is the explicit opposite
            // intent (#252e's "later signals bend toward OUT" applies to
            // ambiguity, not to a server-accepted re-join).
            try
            {
                // Same enrollment-surface set as the success-callback guard
                // (verify round: hosted lobby seats + 1v1 ready_join were
                // missing here too, so the retry could fire a fresh escape
                // against a hosted seat).
                string _pendRoom = Plugin.PendingRankedRoom ?? "";
                if (IsQueuePolling || IsTeamQueuePolling || IsOvtQueuePolling
                    || IsFfaQueuePolling
                    || CurrentTeamQueueState != TeamQueueState.Idle
                    || !string.IsNullOrEmpty(ActiveFfaLobbyId)
                    || TeamLobby.Polling || OvtLobby.Polling
                    || !string.IsNullOrEmpty(TeamLobby.OpenLobbyId)
                    || !string.IsNullOrEmpty(OvtLobby.OpenLobbyId)
                    || _pendRoom.StartsWith("ranked_")
                    || _pendRoom.StartsWith("team_")
                    || _pendRoom.StartsWith("ovt_")
                    || _pendRoom.StartsWith("ffa_")
                    || _pendRoom.StartsWith("sct-"))
                {
                    EscapePending = false;
                    Plugin.Log.LogInfo("[ESCAPE] pending intent superseded by a successful re-enrollment - dropped");
                    return;
                }
            }
            catch { }
            if (Time.unscaledTime - _escapeRetryAt < 15f) return;
            SendEscapeRequest(null);
        }

        /// <summary>Photon's cached best-region code ("home" region) from
        /// PhotonNetwork.BestRegionSummaryInPreferences, or "" when absent.
        /// Summary format (RegionHandler.SummaryToCache, verified in the
        /// shipped decompile): "code;ping;available,codes" when a best region
        /// is cached, OR just the bare comma-separated available list when
        /// none is — hence both the semicolon guard (no ';' = no best region)
        /// and the comma guard (a comma in the first token means we grabbed
        /// the available-list, not a code).</summary>
        private static string HomeRegionFromPhotonCache()
        {
            try
            {
                string sum = PhotonNetwork.BestRegionSummaryInPreferences ?? "";
                int sc = sum.IndexOf(';');
                if (sc <= 0) return "";
                string code = sum.Substring(0, sc).Trim().ToLowerInvariant();
                if (code.Length == 0 || code.Length > 8 || code.Contains(",")) return "";
                return code;
            }
            catch { return ""; }
        }

        public static void JoinQueue(string steamId, string displayName, string region, bool rankedOnly)
        {
            if (SpectatorBlocksQueue()) return;
            NoteQueueRequestInFlight();   // r3: WATCH is blocked for the whole join round-trip   // design §3.1: leave the spectator seat first
            // A join landing while a leave retry is still in flight could get
            // its fresh row deleted by that retry — suppress until the leave
            // resolves (review finding), force-recover if stuck.
            if (CurrentQueueState == QueueState.Leaving)
            {
                if (Time.realtimeSinceStartup - rankedLeavingSince < LEAVE_STUCK_TIMEOUT)
                {
                    CompetitiveUI.ShowNotification("Still leaving the queue — try again in a moment.", new Color(1f, 0.6f, 0.2f));
                    return;
                }
                CurrentQueueState = QueueState.Idle;
            }
            // Use current Photon region if not specified
            if (string.IsNullOrEmpty(region))
            {
                try { region = PhotonNetwork.CloudRegion?.Replace("/*", "") ?? ""; } catch { region = ""; }
            }
            // Aug 15 item 5 (Jarvis/Nix, both-Asian pair on a US room): also
            // send Photon's cached BEST region — the player's HOME region from
            // the ping cache. CloudRegion above is a join-time snapshot that
            // casual region-churn (#82) or a not-connected menu state (#122)
            // makes wrong or empty, and the server's room-region pick trusted
            // it blindly (empty+empty fell through to "us"). Summary format is
            // "code;ping;available,codes" — or just the comma list when no
            // best region is cached (RegionHandler.SummaryToCache), hence the
            // semicolon and comma guards.
            string homeRegion = HomeRegionFromPhotonCache();
            string safeName = Escape(displayName ?? steamId);
            string json = $"{{\"steam_id\":\"{Escape(steamId)}\",\"display_name\":\"{safeName}\",\"region\":\"{Escape(region ?? "")}\",\"home_region\":\"{Escape(homeRegion)}\",\"ranked_only\":{(rankedOnly ? "true" : "false")}}}";

            int gen = ++queueGen;  // new lifecycle starts at SEND, not at the ack
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/queue/join",
                json,
                (success, response) =>
                {
                    if (gen != queueGen)
                    {
                        Plugin.Log.LogInfo("[QUEUE] stale join ack ignored (lifecycle moved on)");
                        return;
                    }
                    if (success)
                    {
                        CurrentQueueState = QueueState.Searching;
                        IsQueuePolling = true;
                        queuePollTimer = 0f;
                        Plugin.Log.LogInfo("[QUEUE] Joined ranked queue");
                        CompetitiveUI.ShowNotification("Searching for ranked match...", new Color(0.4f, 0.8f, 1f));
                        NativeUI.MarkDirty();
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[QUEUE] Failed to join queue: {response}");
                        CompetitiveUI.ShowNotification("Couldn't join the queue", new Color(1f, 0.4f, 0.4f));
                    }
                }
            ));
        }

        public static void LeaveQueue(string steamId)
        {
            if (CurrentQueueState == QueueState.Leaving) return; // leave already in flight
            if (CurrentQueueState == QueueState.Idle && !IsQueuePolling) return; // Already idle
            // Hold in Leaving (not Idle) until the server confirms: a 401/503
            // on the leave endpoint used to strand our row server-side while
            // the client showed Idle, ghost-locking other queuers until the
            // janitor sweep (review finding). The request is
            // idempotent, so retries are safe; Idle is finalized only in the
            // callback, which fires on every path.
            int gen = ++queueGen;
            CurrentQueueState = QueueState.Leaving;
            rankedLeavingSince = Time.realtimeSinceStartup;
            IsQueuePolling = false;
            LastPollData = null;
            NativeUI.MarkDirty();

            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                $"{baseUrl}/api/v1/queue/leave?steam_id={Escape(steamId)}",
                "",
                (success, response) =>
                {
                    if (gen != queueGen) return;  // watchdog recovered / new lifecycle
                    if (success)
                        Plugin.Log.LogInfo("[QUEUE] Left ranked queue");
                    else
                    {
                        // Can't fix the row from here — the queue janitor prunes
                        // non-polling rows, so surface it and release the UI.
                        Plugin.Log.LogWarning($"[QUEUE] Leave failed after retries: {response} — server will prune the stale row");
                        CompetitiveUI.ShowNotification("Couldn't confirm queue leave — the server will clear you shortly.", new Color(1f, 0.6f, 0.2f), 5f);
                    }
                    if (CurrentQueueState == QueueState.Leaving)
                        CurrentQueueState = QueueState.Idle;
                    NativeUI.MarkDirty();
                },
                maxRetries: 3, retryDelay: 2f
            ));
        }

        /// <summary>
        /// Decline a matched opponent. Blocks re-matching for 5 minutes.
        /// Both players are reset to searching (stay in queue).
        /// </summary>
        public static void DeclineMatch(string steamId)
        {
            var poll = LastPollData;
            string oppSteamId = poll?.opponent_steam_id ?? "";

            // Reset local state to Searching (stay in queue, keep polling)
            CurrentQueueState = QueueState.Searching;
            LastPollData = null;
            Plugin.ClearPendingRoom();
            NativeUI.MarkDirty();

            if (string.IsNullOrEmpty(oppSteamId))
            {
                // No opponent data — just leave queue as fallback (shares
                // LeaveQueue's Leaving-state + retry hardening)
                Plugin.Log.LogInfo("[QUEUE] Decline without opponent data — leaving queue as fallback");
                LeaveQueue(steamId);
                return;
            }

            string json = $"{{\"steam_id\":\"{Escape(steamId)}\",\"opponent_steam_id\":\"{Escape(oppSteamId)}\"}}";

            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/queue/decline",
                json,
                (success, response) =>
                {
                    if (success)
                        Plugin.Log.LogInfo($"[QUEUE] Declined match vs {oppSteamId}, searching for new opponent");
                    else
                        Plugin.Log.LogWarning($"[QUEUE] Decline failed: {response}");
                }
            ));
        }

        /// <summary>
        /// Signal ready for the current matched game. Server will generate
        /// a room when both players are ready.
        /// </summary>
        public static void ReadyUp(string steamId)
        {
            if (CurrentQueueState != QueueState.Matched) return;

            CurrentQueueState = QueueState.ReadySent;
            NativeUI.MarkDirty();
            Plugin.Log.LogInfo("[QUEUE] Ready Up sent");

            int gen = queueGen;  // captured, not bumped: ready is not a lifecycle edge
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                $"{baseUrl}/api/v1/queue/ready?steam_id={Escape(steamId)}",
                "",
                (success, response) =>
                {
                    // Codex verify finding 3: a delayed ready ack landing after a
                    // leave/rejoin must not post a dissolved room as pending or
                    // knock the state around. Same-lifecycle + still-ReadySent only.
                    if (gen != queueGen || CurrentQueueState != QueueState.ReadySent) return;
                    if (success)
                    {
                        // Check if both ready already (instant room)
                        string status = ExtractJsonString(response, "status");
                        if (status == "both_ready")
                        {
                            string room = ExtractJsonString(response, "room_name");
                            string region = ExtractJsonString(response, "photon_region");
                            // v1.22 — server now pre-creates the ranked_series and returns its id.
                            // Stash it so live-points reports during game 1 can address the right series.
                            ActiveRankedSeriesId = ExtractJsonString(response, "series_id");
                            // Bug 200: the server may have RESUMED an undecided BO3
                            // rather than creating a fresh one. Staging the tally
                            // here (not adopting) is required — the room-join reset
                            // runs after this and would zero it.
                            if (TryResolveResumedScore(response, MatchTracker.LocalSteamId,
                                                       out int _rmw, out int _row))
                                GameStateWatcher.StashResumedSeriesScore(room, _rmw, _row);
                            if (!string.IsNullOrEmpty(room))
                            {
                                IsQueuePolling = false;
                                CurrentQueueState = QueueState.Idle;
                                LastPollData = null;
                                Plugin.SetPendingRoom(room, region);
                                Plugin.Log.LogInfo($"[QUEUE] Both ready! Joining room: {room} (region: {region ?? "auto"}) series={ActiveRankedSeriesId}");
                                CompetitiveUI.ShowNotification("Both ready! Joining match...", Color.green, 5f);
                                // Refresh the Live Ranked Series list immediately so spectators
                                // (and the betting UI) see the new series the moment it's
                                // created, not on the 10s poll cycle. Gives spectators the full
                                // pre-game-1 window to place bets instead of missing half of it.
                                FetchActiveSeries();
                                NativeUI.MarkDirty();
                            }
                        }
                        else
                        {
                            // Echo the server response so if a "canceled despite both ready"
                            // report comes in again we can see if the server actually said
                            // "waiting" or something weirder like "not_matched" (which would
                            // indicate the matched state was already lost before the ready hit).
                            string detail = ExtractJsonString(response, "status") ?? "(no status)";
                            string msg = ExtractJsonString(response, "message") ?? "";
                            Plugin.Log.LogInfo($"[QUEUE] Waiting for opponent to ready up (server: {detail} — {msg})");
                        }
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[QUEUE] Ready failed after retries: {response}");
                        CompetitiveUI.ShowNotification("Ready-up failed — retrying search", new Color(1f, 0.6f, 0.2f), 5f);
                        CurrentQueueState = QueueState.Searching;
                        NativeUI.MarkDirty();
                    }
                },
                maxRetries: 3, retryDelay: 2f
            ));
        }

        /// <summary>
        /// Called from Update() when polling is active. Polls every 3 seconds.
        /// </summary>
        public static void UpdateQueuePoll(string steamId)
        {
            if (!IsQueuePolling) return;

            queuePollTimer += Time.deltaTime;
            if (queuePollTimer < queuePollInterval) return;
            queuePollTimer = 0f;

            int gen = queueGen;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/queue/poll/{steamId}",
                (success, response) =>
                {
                    // gen check (Codex verify finding 4): IsQueuePolling is a
                    // reusable boolean — a 20s-delayed response from a PREVIOUS
                    // lifecycle passes it after a leave+rejoin and could
                    // auto-join a dissolved room. The generation cannot be reused.
                    if (!success || !IsQueuePolling || gen != queueGen) return;

                    try
                    {
                        string status = ExtractJsonString(response, "status");

                        if (status == "ready_join")
                        {
                            // Both ready — room assigned, join it!
                            string room = ExtractJsonString(response, "room_name");
                            string region = ExtractJsonString(response, "photon_region");
                            // Adopt the pre-created series id (parity with the
                            // /queue/ready both_ready path). Without it the
                            // poll-discovered client never posted live points
                            // and the betting lock logic ran blind (#36).
                            string sid = ExtractJsonString(response, "series_id");
                            if (!string.IsNullOrEmpty(sid)) ActiveRankedSeriesId = sid;
                            // Bug 200: parity with the /queue/ready both_ready
                            // path — this poll branch hands over a series id the
                            // same way, so it must carry a resumed tally too.
                            if (TryResolveResumedScore(response, MatchTracker.LocalSteamId,
                                                       out int _pmw, out int _pow))
                                GameStateWatcher.StashResumedSeriesScore(room, _pmw, _pow);
                            IsQueuePolling = false;
                            CurrentQueueState = QueueState.Idle;
                            LastPollData = null;
                            Plugin.SetPendingRoom(room, region);
                            Plugin.Log.LogInfo($"[QUEUE] Both ready! Joining room: {room} (region: {region ?? "auto"}) series={ActiveRankedSeriesId ?? "(none)"}");
                            CompetitiveUI.ShowNotification("Both ready! Joining match...", Color.green, 5f);
                            NativeUI.MarkDirty();
                        }
                        else if (status == "matched")
                        {
                            bool oppReady = ExtractJsonBool(response, "opponent_ready");

                            if (CurrentQueueState == QueueState.Searching)
                            {
                                // New match found!
                                CurrentQueueState = QueueState.Matched;
                                Plugin.Log.LogInfo($"[QUEUE] MATCHED! vs {ExtractJsonString(response, "opponent_name")} ({ExtractJsonFloat(response, "opponent_rating"):F0})");
                                // Same template as NativeUI's match-found strip — ONE
                                // key for both sites. TagsMatch counts spec'd holes
                                // ({1:F0}) since the CountPlaceholder fix, so a
                                // translation dropping the rating fails validation.
                                CompetitiveUI.ShowNotification(
                                    I18n.TrF("MATCH FOUND!  vs {0} ({1:F0})", ExtractJsonString(response, "opponent_name"),
                                        ExtractJsonFloat(response, "opponent_rating")),
                                    Color.green, 8f
                                );
                                CompetitiveUI.PlayMatchFoundSound();
                                TaskbarFlash.Flash();
                            }

                            // Keep polling — update data (opponent_ready may change)
                            LastPollData = new QueuePollData
                            {
                                status = "matched",
                                wait_time = ExtractJsonInt(response, "wait_time"),
                                opponent_steam_id = ExtractJsonString(response, "opponent_steam_id"),
                                opponent_name = ExtractJsonString(response, "opponent_name"),
                                opponent_rating = ExtractJsonFloat(response, "opponent_rating"),
                                opponent_ready = oppReady,
                            };
                            NativeUI.MarkDirty();
                        }
                        else if (status == "searching")
                        {
                            if (CurrentQueueState == QueueState.Matched || CurrentQueueState == QueueState.ReadySent)
                            {
                                // Was matched but now searching — declined or timeout
                                Plugin.Log.LogInfo("[QUEUE] Match canceled — back to searching");
                                CompetitiveUI.ShowNotification("Match canceled — searching again...", Color.yellow, 5f);
                            }

                            CurrentQueueState = QueueState.Searching;
                            LastPollData = new QueuePollData
                            {
                                status = "searching",
                                wait_time = ExtractJsonInt(response, "wait_time"),
                                queue_size = ExtractJsonInt(response, "queue_size"),
                                elo_range = ExtractJsonInt(response, "elo_range"),
                            };
                            NativeUI.MarkDirty();
                        }
                        else if (status == "expired" || status == "not_in_queue")
                        {
                            CurrentQueueState = QueueState.Idle;
                            IsQueuePolling = false;
                            LastPollData = null;
                            CompetitiveUI.ShowNotification(status == "expired"
                                ? "Removed from queue after 30 minutes of searching - rejoin if you're still here!"
                                : "Stopped searching", Color.yellow, 7f);
                            NativeUI.MarkDirty();
                        }
                    }
                    catch (Exception ex)
                    {
                        Plugin.Log.LogWarning($"[QUEUE] Poll parse error: {ex.Message}");
                    }
                }
            ));
        }

        public static void ResetQueueState()
        {
            CurrentQueueState = QueueState.Idle;
            IsQueuePolling = false;
            LastPollData = null;
        }

        // ── Queue Count (lightweight, always-on when page open) ──

        public static int CachedQueueSearching { get; private set; } = 0;
        public static int CachedQueueTotal { get; private set; } = 0;
        // Mod clients online right now (v1.29). Fed by /queue/count while the
        // menu is open and by the always-on presence loop while it isn't.
        public static int CachedOnlineCount { get; private set; } = 0;
        private static float queueCountTimer = 0f;
        private static float queueCountInterval = 10f;

        public static void UpdateQueueCount()
        {
            queueCountTimer += Time.deltaTime;
            if (queueCountTimer < queueCountInterval) return;
            queueCountTimer = 0f;

            // steam_id makes this call count US toward the online figure.
            string sid = MatchTracker.LocalSteamId;
            string q = (!string.IsNullOrEmpty(sid) && sid != "unknown") ? $"?steam_id={Escape(sid)}" : "";
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/queue/count{q}",
                (success, response) =>
                {
                    if (success)
                    {
                        int s = ExtractJsonInt(response, "searching");
                        int t = ExtractJsonInt(response, "total");
                        int on = ExtractJsonInt(response, "online");
                        if (s != CachedQueueSearching || t != CachedQueueTotal || on != CachedOnlineCount)
                        {
                            CachedQueueSearching = s;
                            CachedQueueTotal = t;
                            CachedOnlineCount = on;
                            NativeUI.MarkDirty();
                        }
                    }
                }
            ));
        }

        public static void ResetQueueCountTimer() { queueCountTimer = queueCountInterval; }

        /// <summary>Always-on presence heartbeat (v1.29). Pings every 60s while the
        /// game runs — with or without the F5 menu — so the server can count mod
        /// clients online, and keeps CachedOnlineCount fresh for the queue tab.
        ///
        /// v1.30 hardening (bug #51):
        ///  1. Re-resolve the local Steam id each tick — IdentifyLocalPlayer only
        ///     ran at init + room joins, so a client that lost the startup
        ///     Steamworks race and sat in menus never pinged (its /queue/count
        ///     calls carried no steam_id either — observed live in the api log).
        ///  2. The web request is dispatched fire-and-forget instead of yielded:
        ///     one exception inside a yielded GetRequest would have killed this
        ///     loop for the whole session, silently zeroing the player from the
        ///     online count.</summary>
        // ════════════════════════════════════════════════════════════
        // HOME TAB DATA (v1.33) — online players, newest cosmetics,
        // latest GitHub release notes
        // ════════════════════════════════════════════════════════════

        public class OnlinePlayerEntry
        {
            public string name;
            public int rating;
            public int minutesAgo;
            public string title;
            public string titleColor;
            // The server has always sent steam_id (main.py presence rows);
            // the parse dropped it, which blocked driving Compare/leaderboard
            // views from this list (broadcast idle showcase, Aug 30).
            public string steamId;
        }

        public static List<OnlinePlayerEntry> CachedOnlinePlayers;
        public static List<OnlinePlayerEntry> CachedRecentPlayers;
        public static int CachedOnlineListCount;

        /// <summary>GET /presence/online — who's online + recently online, for the
        /// Home tab. Nested arrays -> manual parse (learning #25).</summary>
        public static void FetchOnlinePlayers()
        {
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/presence/online", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                try
                {
                    CachedOnlineListCount = ExtractJsonInt(resp, "online_count");
                    CachedOnlinePlayers = ParsePresenceList(resp, "\"online\"");
                    CachedRecentPlayers = ParsePresenceList(resp, "\"recent\"");
                    NativeUI.MarkDirty();
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[HOME] presence parse failed: {ex.Message}"); }
            }));
        }

        /// <summary>Find the ']' closing the '[' at openPos, tracking JSON string
        /// literals — brackets INSIDE values must not derail the count. The plain
        /// FindMatchingBracket is only safe when string values can't contain
        /// brackets; these arrays are mostly USER-CONTROLLED display names
        /// ("[TAG] Bob", ">:[") — learning #61 family.</summary>
        private static int FindMatchingBracketStringAware(string s, int openPos)
        {
            if (openPos < 0 || openPos >= s.Length) return -1;
            int depth = 0; bool inStr = false;
            for (int i = openPos; i < s.Length; i++)
            {
                char c = s[i];
                if (inStr)
                {
                    if (c == '\\') i++;
                    else if (c == '"') inStr = false;
                    continue;
                }
                if (c == '"') { inStr = true; continue; }
                if (c == '[') depth++;
                else if (c == ']') { depth--; if (depth == 0) return i; }
            }
            return -1;
        }

        // Curly twin of the above (learning #156: any slice over a region that
        // can carry user-authored strings must be string-aware).
        private static int FindMatchingBraceStringAware(string s, int openPos)
        {
            if (openPos < 0 || openPos >= s.Length) return -1;
            int depth = 0; bool inStr = false;
            for (int i = openPos; i < s.Length; i++)
            {
                char c = s[i];
                if (inStr)
                {
                    if (c == '\\') i++;
                    else if (c == '"') inStr = false;
                    continue;
                }
                if (c == '"') { inStr = true; continue; }
                if (c == '{') depth++;
                else if (c == '}') { depth--; if (depth == 0) return i; }
            }
            return -1;
        }

        private static List<OnlinePlayerEntry> ParsePresenceList(string json, string key)
        {
            var list = new List<OnlinePlayerEntry>();
            int k = json.IndexOf(key);
            if (k < 0) return list;
            int open = json.IndexOf('[', k);
            if (open < 0) return list;
            int close = FindMatchingBracketStringAware(json, open);
            if (close < 0) return list;
            // Entry boundaries via the string-aware object slicer (a display name
            // containing '{' or '}' must not split an entry).
            foreach (string chunk in SliceTopLevelObjects(json.Substring(open, close - open + 1)))
            {
                var e = new OnlinePlayerEntry
                {
                    name = ExtractJsonString(chunk, "display_name"),
                    rating = ExtractJsonInt(chunk, "rating"),
                    minutesAgo = ExtractJsonInt(chunk, "minutes_ago"),
                    title = ExtractJsonString(chunk, "title"),
                    titleColor = ExtractJsonString(chunk, "title_color"),
                    steamId = ExtractJsonString(chunk, "steam_id"),
                };
                if (!string.IsNullOrEmpty(e.name)) list.Add(e);
            }
            return list;
        }

        public class NewestCosmeticEntry
        {
            public string sku;
            public string kind;
            public string name;
            public string rarity;
            public int price;
            public string previewColor;
            public string artistName;
            public string added;   // "Jul 12" — the cosmetic-update day (batch)
            // F14: ISO date ("date_iso": YYYY-MM-DD) parsed when the server
            // sends it, so the render can honor the date-order setting via
            // DateFmt.Short(dateIso). Null on old servers — 'added' is the
            // preformatted fallback and stays untouched.
            public DateTime? dateIso;
            public bool onSale;    // false = artist hasn't opened sales yet ("coming soon")
        }

        public static List<NewestCosmeticEntry> CachedNewestCosmetics;

        /// <summary>GET /shop/newest — the most recently added shop items for the
        /// Home tab's "newest cosmetics" panel. batches=2 restricts the list to
        /// the last two cosmetic-update days (item 4).</summary>
        public static void FetchNewestCosmetics()
        {
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/shop/newest?limit=12&batches=2", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                try
                {
                    var list = new List<NewestCosmeticEntry>();
                    // String-aware slicing — item names/descriptions are free text.
                    int ik = resp.IndexOf("\"items\"");
                    int iopen = ik >= 0 ? resp.IndexOf('[', ik) : -1;
                    int iclose = iopen >= 0 ? FindMatchingBracketStringAware(resp, iopen) : -1;
                    if (iclose < 0) { Plugin.Log.LogWarning("[HOME] shop/newest: items array not found"); return; }
                    foreach (string chunk in SliceTopLevelObjects(resp.Substring(iopen, iclose - iopen + 1)))
                    {
                        var e = new NewestCosmeticEntry
                        {
                            sku = ExtractJsonString(chunk, "sku"),
                            kind = ExtractJsonString(chunk, "kind"),
                            name = ExtractJsonString(chunk, "name"),
                            rarity = ExtractJsonString(chunk, "rarity"),
                            price = ExtractJsonInt(chunk, "price"),
                            previewColor = ExtractJsonString(chunk, "preview_color"),
                            artistName = ExtractJsonString(chunk, "artist_name"),
                            added = ExtractJsonString(chunk, "added"),
                            // Absent key (old server) reads as false-ish; default
                            // to on-sale so pre-round-4 servers render unchanged.
                            onSale = !chunk.Contains("\"on_sale\":false"),
                        };
                        // F14: date_iso is additive — absent (old server) or
                        // unparseable leaves dateIso null and the preformatted
                        // 'added' string renders as before.
                        string iso = ExtractJsonString(chunk, "date_iso");
                        if (!string.IsNullOrEmpty(iso) &&
                            DateTime.TryParseExact(iso, "yyyy-MM-dd",
                                System.Globalization.CultureInfo.InvariantCulture,
                                System.Globalization.DateTimeStyles.None, out DateTime isoDt))
                            e.dateIso = isoDt;
                        if (!string.IsNullOrEmpty(e.sku)) list.Add(e);
                    }
                    CachedNewestCosmetics = list;
                    NativeUI.MarkDirty();
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[HOME] shop/newest parse failed: {ex.Message}"); }
            }));
        }

        public class ReleaseNoteEntry
        {
            public string tag;
            public string title;
            public string date;   // yyyy-MM-dd
            public string body;   // plain-ish text, truncated + ASCII-safe
        }

        public static List<ReleaseNoteEntry> CachedReleaseNotes;
        private static bool _releasesFetchInFlight;

        private const string GITHUB_API_RELEASES =
            "https://api.github.com/repos/SidNDeed/SidsCompetitiveRounds/releases?per_page=3";

        /// <summary>Fetch update notes for the Home tab (v1.33 rework, Sid's item 2):
        /// primary source is the server's mirror of the #scr-releases Discord
        /// channel (players see notes as they're POSTED), falling back to the
        /// GitHub releases list when the mirror is empty/unreachable (fresh
        /// deploy, bot down). Cached for the session.</summary>
        // Locale the cached notes were localized FOR. Codex review: without
        // this, switching language kept the previous language's notes for the
        // whole session, because the cache-populated early-return fires first.
        private static string _releaseNotesLocale = null;

        public static void FetchReleaseNotes(bool force = false)
        {
            if (_releasesFetchInFlight) return;
            string want = I18n.Locale;
            if (want == I18n.LOCALE_UNSET) want = "en";
            if (!force && CachedReleaseNotes != null && CachedReleaseNotes.Count > 0
                && _releaseNotesLocale == want) return;
            if (CachedReleaseNotes != null && _releaseNotesLocale != want)
            {
                // Language changed: the cached bodies are in the old language
                // and the English originals are gone, so refetch rather than
                // trying to un-translate them.
                CachedReleaseNotes = null;
            }
            _releasesFetchInFlight = true;
            /* Aug 7 item 6: PRIMARY is the server's own uncut store
             * (release_notes_i18n, English rows POSTed at ship time) — full
             * formatted bodies, locale-resolved server-side. The Discord
             * mirror became the fallback: its bodies arrive pre-truncated to
             * what one 2000-char Discord message carried (v1.37.0 lost 63% of
             * its notes that way). */
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/release-notes/full/{Escape(want)}", (fOk, fResp) =>
            {
                var full = fOk ? ParseFullReleaseNotes(fResp, want) : null;
                if (full != null && full.Count > 0)
                {
                    _releasesFetchInFlight = false;
                    CachedReleaseNotes = full;
                    _releaseNotesLocale = want;
                    Plugin.Log.LogInfo($"[HOME] release notes loaded: {full.Count} (server store, {want})");
                    NativeUI.MarkDirty();
                    return;
                }
                Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/releases/recent?limit=3", (ok, resp) =>
                {
                    var list = ok ? ParseReleasePosts(resp) : null;
                    if (list != null && list.Count > 0)
                    {
                        _releasesFetchInFlight = false;
                        CachedReleaseNotes = list;
                        Plugin.Log.LogInfo($"[HOME] release posts loaded: {list.Count} (channel mirror)");
                        NativeUI.MarkDirty();
                        // Codex review: the overlay used to run ONLY on the GitHub
                        // fallback, so on a healthy server (mirror populated — the
                        // normal case) translated notes were never requested.
                        MaybeLocalizeReleaseNotes();
                    }
                    else
                    {
                        Plugin.Log.LogInfo("[HOME] release mirror empty/unreachable - falling back to GitHub");
                        Plugin.Instance.StartCoroutine(DoFetchReleaseNotes());
                    }
                }));
            }));
        }

        /// <summary>Aug 7 item 6: parse /release-notes/full/{locale} — uncut
        /// bodies, formatted for TMP instead of stripped to a flat block.</summary>
        private static List<ReleaseNoteEntry> ParseFullReleaseNotes(string resp, string locale)
        {
            try
            {
                var list = new List<ReleaseNoteEntry>();
                if (string.IsNullOrEmpty(resp)) return list;
                int k = resp.IndexOf("\"releases\"", StringComparison.Ordinal);
                if (k < 0) return list;
                int open = resp.IndexOf('[', k);
                if (open < 0) return list;
                int close = FindMatchingBracketStringAware(resp, open);
                if (close < 0) return list;
                foreach (string chunk in SliceTopLevelObjects(resp.Substring(open, close - open + 1)))
                {
                    string body = ExtractJsonString(chunk, "body");
                    bool machine = ExtractJsonBool(chunk, "machine");
                    var e = new ReleaseNoteEntry
                    {
                        tag = ExtractJsonString(chunk, "tag"),
                        title = ExtractJsonString(chunk, "title"),
                        date = ExtractJsonString(chunk, "updated_at"),
                        body = locale == "en" ? MarkdownToTmp(body, unicode: false)
                                              : MarkdownToTmp(body, unicode: true),
                    };
                    if (machine && !string.IsNullOrEmpty(e.body))
                        e.body += "\n<color=#667788><i>" + I18n.Tr("Machine translation - corrections welcome in Discord.") + "</i></color>";
                    if (!string.IsNullOrEmpty(e.date) && e.date.Length >= 10) e.date = e.date.Substring(0, 10);
                    if (!string.IsNullOrEmpty(e.tag) && !string.IsNullOrEmpty(e.body)) list.Add(e);
                }
                return list;
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[HOME] full release notes parse failed: {ex.Message}");
                return null;
            }
        }

        private static List<ReleaseNoteEntry> ParseReleasePosts(string resp)
        {
            try
            {
                var list = new List<ReleaseNoteEntry>();
                if (string.IsNullOrEmpty(resp)) return list;
                int k = resp.IndexOf("\"posts\"");
                if (k < 0) return list;
                int open = resp.IndexOf('[', k);
                if (open < 0) return list;
                int close = FindMatchingBracketStringAware(resp, open);
                if (close < 0) return list;
                foreach (string chunk in SliceTopLevelObjects(resp.Substring(open, close - open + 1)))
                {
                    var e = new ReleaseNoteEntry
                    {
                        tag = ExtractJsonString(chunk, "author"),
                        title = "",
                        date = ExtractJsonString(chunk, "posted_at"),
                        body = CleanReleaseBody(ExtractJsonString(chunk, "content")),
                    };
                    if (!string.IsNullOrEmpty(e.date) && e.date.Length >= 10) e.date = e.date.Substring(0, 10);
                    if (!string.IsNullOrEmpty(e.body)) list.Add(e);
                }
                return list;
            }
            catch (Exception ex)
            {
                Plugin.Log.LogWarning($"[HOME] release posts parse failed: {ex.Message}");
                return null;
            }
        }

        private static IEnumerator DoFetchReleaseNotes()
        {
            var req = UnityEngine.Networking.UnityWebRequest.Get(GITHUB_API_RELEASES);
            req.SetRequestHeader("User-Agent", "CompetitiveRounds-HomeTab");
            req.timeout = 15;
            yield return req.SendWebRequest();
            _releasesFetchInFlight = false;
            if (req.result != UnityEngine.Networking.UnityWebRequest.Result.Success)
            {
                Plugin.Log.LogWarning($"[HOME] release notes fetch failed: {req.error}");
                yield break;
            }
            try
            {
                var list = new List<ReleaseNoteEntry>();
                foreach (string obj in SliceTopLevelObjects(req.downloadHandler.text))
                {
                    var e = new ReleaseNoteEntry
                    {
                        tag = ExtractGhString(obj, "tag_name"),
                        title = ExtractGhString(obj, "name"),
                        date = ExtractGhString(obj, "published_at"),
                        body = CleanReleaseBody(ExtractGhString(obj, "body")),
                    };
                    if (!string.IsNullOrEmpty(e.date) && e.date.Length >= 10) e.date = e.date.Substring(0, 10);
                    if (!string.IsNullOrEmpty(e.tag)) list.Add(e);
                    if (list.Count >= 3) break;
                }
                CachedReleaseNotes = list;
                Plugin.Log.LogInfo($"[HOME] release notes loaded: {list.Count}");
                NativeUI.MarkDirty();
                // Sid, Aug 3: show the notes in the player's language. GitHub
                // only has English, so the server holds an OVERLAY keyed by
                // release tag; anything without a translation keeps its
                // English text (never blank).
                MaybeLocalizeReleaseNotes();
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[HOME] release notes parse failed: {ex.Message}"); }
        }

        /// <summary>Start the locale overlay if one is needed. Called from BOTH
        /// cache paths (Discord mirror and GitHub fallback).</summary>
        private static void MaybeLocalizeReleaseNotes()
        {
            string loc = I18n.Locale;
            if (string.IsNullOrEmpty(loc) || loc == I18n.LOCALE_UNSET) loc = "en";
            _releaseNotesLocale = loc;
            if (loc == "en") return;
            Plugin.Instance.StartCoroutine(DoFetchReleaseNotesOverlay(loc));
        }

        /// <summary>Overlay the cached (English) release notes with server-held
        /// translations for the active locale. Per-TAG: an untranslated release
        /// keeps its English body rather than disappearing, and a failed fetch
        /// changes nothing at all.</summary>
        private static IEnumerator DoFetchReleaseNotesOverlay(string locale)
        {
            var req = UnityEngine.Networking.UnityWebRequest.Get(
                $"{baseUrl}/api/v1/release-notes/{Escape(locale)}");
            req.SetRequestHeader("X-Mod-Version", Plugin.ModVersion);
            req.timeout = 12;
            yield return req.SendWebRequest();
            if (req.result != UnityEngine.Networking.UnityWebRequest.Result.Success) yield break;
            // The player may have switched language while this was in flight;
            // applying it now would overwrite the new locale's notes with the
            // old one's (Codex review).
            if (_releaseNotesLocale != locale) yield break;
            try
            {
                string resp = req.downloadHandler.text;
                int open = resp.IndexOf("\"notes\":");
                if (open < 0) yield break;
                int close = FindMatchingBracketStringAware(resp, open + "\"notes\":".Length);
                if (close < 0) yield break;
                int s = open + "\"notes\":".Length;
                int applied = 0;
                foreach (string obj in SliceTopLevelObjects(resp.Substring(s + 1, close - s - 1)))
                {
                    string tag = ExtractJsonString(obj, "tag");
                    string body = ExtractJsonString(obj, "body");
                    if (string.IsNullOrEmpty(tag) || string.IsNullOrEmpty(body)) continue;
                    string title = ExtractJsonString(obj, "title");
                    bool machine = ExtractJsonBool(obj, "machine");
                    foreach (var e in CachedReleaseNotes)
                    {
                        // Codex review: the Discord-mirror path stores the POST
                        // AUTHOR in `tag`, so an exact tag compare matched
                        // nothing on the normal path. Accept an exact match
                        // (GitHub path) OR the release tag appearing in the
                        // entry's title/body (mirror path).
                        bool hit = e.tag == tag
                                   || (!string.IsNullOrEmpty(e.title) && e.title.Contains(tag))
                                   || (!string.IsNullOrEmpty(e.body) && e.body.Contains(tag));
                        if (!hit) continue;
                        // Sanitize BEFORE it reaches TMP (Codex review): a
                        // translated body is Markdown that can carry '<'/'>'
                        // and would otherwise open or close a rich-text tag in
                        // the Home panel.
                        string clean = CleanReleaseBodyUnicode(body);
                        e.body = machine
                            ? clean + "\n\n<color=#888><i>"
                                    + I18n.Tr("Machine translation - the English notes are on GitHub.")
                                    + "</i></color>"
                            : clean;
                        if (!string.IsNullOrEmpty(title)) e.title = title;
                        applied++;
                    }
                }
                if (applied > 0) { Plugin.Log.LogInfo($"[HOME] release notes localized: {applied}"); NativeUI.MarkDirty(); }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[HOME] release-note overlay failed: {ex.Message}"); }
        }

        /// <summary>Split a top-level JSON array into its object slices. Unlike
        /// FindMatchingBrace this is STRING-AWARE — GitHub release bodies are
        /// markdown that can legally contain braces.</summary>
        private static List<string> SliceTopLevelObjects(string json)
        {
            var outp = new List<string>();
            if (string.IsNullOrEmpty(json)) return outp;
            int depth = 0, objStart = -1;
            bool inStr = false;
            for (int i = 0; i < json.Length; i++)
            {
                char c = json[i];
                if (inStr)
                {
                    if (c == '\\') i++;           // skip escaped char
                    else if (c == '"') inStr = false;
                    continue;
                }
                if (c == '"') { inStr = true; continue; }
                if (c == '{')
                {
                    if (depth == 0) objStart = i;
                    depth++;
                }
                else if (c == '}')
                {
                    depth--;
                    if (depth == 0 && objStart >= 0)
                    {
                        outp.Add(json.Substring(objStart, i - objStart + 1));
                        objStart = -1;
                    }
                }
            }
            return outp;
        }

        /// <summary>GitHub-style string field extractor: tolerates the pretty-printed
        /// `"key": "value"` spacing (ExtractJsonString expects the API's compact
        /// form) and unescapes the value.</summary>
        private static string ExtractGhString(string json, string key)
        {
            try
            {
                int k = json.IndexOf($"\"{key}\"");
                if (k < 0) return "";
                int c = json.IndexOf(':', k + key.Length + 2);
                if (c < 0) return "";
                int p = c + 1;
                while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
                if (p >= json.Length || json[p] != '"')
                    return "";  // null or non-string value
                // Reuse the escape-aware scanner by handing it a compact slice.
                return ExtractJsonString("\"" + key + "\":" + json.Substring(p), key);
            }
            catch { return ""; }
        }

        /// <summary>Markdown release body -> TMP-safe plain text: strip heading/bold
        /// markers, drop angle brackets (would parse as rich-text tags), map common
        /// unicode to ASCII (Gravity font, learning #47), truncate.</summary>
        /// <summary>Same Markdown/TMP cleanup as CleanReleaseBody, WITHOUT the
        /// ASCII-only pass — that pass would erase Spanish accents and delete
        /// Cyrillic outright. Still neutralises '&lt;'/'&gt;' so a translated body
        /// can never open or close a TMP tag in the Home panel (Codex review:
        /// the localized body previously reached TMP raw).</summary>
        private static string CleanReleaseBodyUnicode(string body)
        {
            if (string.IsNullOrEmpty(body)) return "";
            string nl = "\n";
            string t = body.Replace("\r\n", nl).Replace("\r", nl);
            // Same ordering rule as CleanReleaseBody above (r2 find 16):
            // unwrap while the Markdown structure is still present.
            t = NativeUI.UnwrapHardBreaks(t);
            t = t.Replace("**", "").Replace("__", "").Replace("`", "");
            t = t.Replace("<", "[").Replace(">", "]");
            var sb = new System.Text.StringBuilder(t.Length);
            foreach (string rawLine in t.Split('\n'))
            {
                string line = rawLine.TrimEnd();
                string trimmed = line.TrimStart();
                if (trimmed.StartsWith("#")) line = trimmed.TrimStart('#', ' ');
                sb.Append(line).Append('\n');
            }
            t = sb.ToString();
            // Control characters only — every printable non-ASCII glyph is kept
            // and the runtime font fallback renders it (UnicodeFallback).
            var keep = new System.Text.StringBuilder(t.Length);
            foreach (char ch in t)
                if (ch == '\n' || ch >= 32) keep.Append(ch);
            t = keep.ToString();
            while (t.Contains("\n\n\n")) t = t.Replace("\n\n\n", "\n\n");
            t = t.Trim();
            // Aug 7 item 6: 2500 -> 9000. The es/ru bodies run ~6k and this
            // cap was cutting them mid-list; the panel scrolls.
            if (t.Length > 9000) t = t.Substring(0, 9000).TrimEnd() + " ...";
            return t;
        }

        /// <summary>Aug 7 item 6: Markdown -> TMP rich text for the Home tab's
        /// uncut release notes. Order is load-bearing: neutralize SOURCE angle
        /// brackets FIRST, then insert our tags — a changelog line containing
        /// "&lt;b&gt;" must render as text, never inject markup (same class as
        /// the overlay sanitizer). ASCII variant maps typography to ASCII and
        /// drops other non-ASCII (Gravity coverage, #47); Unicode variant
        /// keeps accents/Cyrillic for the runtime fallback font.</summary>
        internal static string MarkdownToTmp(string body, bool unicode)
        {
            if (string.IsNullOrEmpty(body)) return "";
            string t = body.Replace("\r\n", "\n").Replace("\r", "\n");
            t = NativeUI.UnwrapHardBreaks(t);
            t = t.Replace("<", "(").Replace(">", ")");
            if (!unicode)
            {
                t = t.Replace("—", "-").Replace("–", "-").Replace("×", "x")
                     .Replace("•", "-").Replace("→", "->").Replace("·", "-")
                     .Replace("‘", "'").Replace("’", "'")
                     .Replace("“", "\"").Replace("”", "\"");
            }
            var sb = new StringBuilder(t.Length + 256);
            foreach (string rawLine in t.Split('\n'))
            {
                string line = rawLine.TrimEnd();
                string trimmed = line.TrimStart();
                if (trimmed.StartsWith("#", StringComparison.Ordinal))
                {
                    string h = trimmed.TrimStart('#').Trim();
                    sb.Append("<size=+3><color=#FFD94D><b>").Append(InlineMdToTmp(h))
                      .Append("</b></color></size>\n");
                    continue;
                }
                bool bullet = (trimmed.StartsWith("- ", StringComparison.Ordinal)
                            || trimmed.StartsWith("* ", StringComparison.Ordinal)
                            || trimmed.StartsWith("+ ", StringComparison.Ordinal))
                            && !trimmed.StartsWith("**", StringComparison.Ordinal);
                if (bullet)
                {
                    int indent = line.Length - trimmed.Length;
                    sb.Append(indent >= 2 ? "      " : "  ")
                      .Append("<color=#FFD94D>-</color> ")
                      .Append(InlineMdToTmp(trimmed.Substring(2))).Append('\n');
                    continue;
                }
                sb.Append(InlineMdToTmp(line)).Append('\n');
            }
            string outp = sb.ToString();
            var filtered = new StringBuilder(outp.Length);
            foreach (char ch in outp)
            {
                if (ch == '\n') { filtered.Append(ch); continue; }
                if (ch < 32) continue;
                if (!unicode && ch >= 127) continue;
                filtered.Append(ch);
            }
            outp = filtered.ToString();
            while (outp.Contains("\n\n\n")) outp = outp.Replace("\n\n\n", "\n\n");
            outp = outp.Trim();
            // 9000 cap: real changelogs run 5-6k; the panel scrolls.
            if (outp.Length > 9000) outp = outp.Substring(0, 9000).TrimEnd() + " ...";
            return outp;
        }

        /// <summary>Inline markdown: **bold**, __underline__, `code` (light
        /// blue). Runs AFTER angle-bracket neutralization, so our own tags are
        /// the only markup in the string. Markers inside a code span are
        /// LITERAL (identifiers like __init__ or cr_ffa_cfg must not toggle
        /// styling); single * / _ are left alone for the same reason.
        /// Unbalanced markers are closed at end of line — the global Truncate
        /// default plus TMP both misbehave on dangling tags (#292).</summary>
        private static string InlineMdToTmp(string line)
        {
            if (string.IsNullOrEmpty(line)) return line ?? "";
            var sb = new StringBuilder(line.Length + 24);
            bool bold = false, under = false, code = false, ital = false;
            for (int i = 0; i < line.Length; i++)
            {
                char c = line[i];
                if (c == '`')
                { sb.Append(code ? "</color>" : "<color=#AAD4FF>"); code = !code; continue; }
                if (!code && c == '*' && i + 1 < line.Length && line[i + 1] == '*')
                { sb.Append(bold ? "</b>" : "<b>"); bold = !bold; i++; continue; }
                // Aug 8 (Sid, item 6): ITALICS were the one requested style the
                // formatter never had — a single '*' fell through as a literal
                // asterisk. Checked AFTER the '**' branch so bold still wins,
                // and only when the asterisk is adjacent to a non-space (so
                // "3 * 4" and a lone trailing '*' stay literal rather than
                // opening a span that swallows the rest of the line).
                if (!code && c == '*'
                    && (ital ? (i > 0 && line[i - 1] != ' ')
                             : (i + 1 < line.Length && line[i + 1] != ' ')))
                { sb.Append(ital ? "</i>" : "<i>"); ital = !ital; continue; }
                if (!code && c == '_' && i + 1 < line.Length && line[i + 1] == '_')
                { sb.Append(under ? "</u>" : "<u>"); under = !under; i++; continue; }
                sb.Append(c);
            }
            if (code) sb.Append("</color>");
            if (bold) sb.Append("</b>");
            if (under) sb.Append("</u>");
            if (ital) sb.Append("</i>");
            return sb.ToString();
        }

        private static string CleanReleaseBody(string body)
        {
            if (string.IsNullOrEmpty(body)) return "";
            string t = body.Replace("\r\n", "\n").Replace("\r", "\n");
            /* Bug #160 / Codex Aug-4 r2 find 16: unwrap the author's hard
             * line breaks HERE, while the Markdown is still intact. The
             * cleanup below strips '#' heading markers and backticks, and
             * once those are gone a heading reads as ordinary prose — the
             * unwrapper would happily join it into the paragraph beneath
             * it. Structure has to be read before it is erased. */
            t = NativeUI.UnwrapHardBreaks(t);
            t = t.Replace("**", "").Replace("__", "").Replace("`", "");
            t = t.Replace("<", "[").Replace(">", "]");
            t = t.Replace("—", "-").Replace("–", "-").Replace("×", "x")
                 .Replace("•", "-").Replace("→", "->").Replace("·", "-")
                 .Replace("‘", "'").Replace("’", "'")
                 .Replace("“", "\"").Replace("”", "\"");
            var sb = new System.Text.StringBuilder(t.Length);
            foreach (string rawLine in t.Split('\n'))
            {
                string line = rawLine.TrimEnd();
                string trimmed = line.TrimStart();
                if (trimmed.StartsWith("###")) line = trimmed.TrimStart('#', ' ');
                else if (trimmed.StartsWith("##")) line = trimmed.TrimStart('#', ' ');
                else if (trimmed.StartsWith("#")) line = trimmed.TrimStart('#', ' ');
                sb.Append(line).Append('\n');
            }
            t = sb.ToString();
            // ASCII-only (unsupported glyphs render as squares in ROUNDS' font).
            var ascii = new System.Text.StringBuilder(t.Length);
            foreach (char ch in t)
                if (ch == '\n' || (ch >= 32 && ch < 127)) ascii.Append(ch);
            t = ascii.ToString();
            while (t.Contains("\n\n\n")) t = t.Replace("\n\n\n", "\n\n");
            t = t.Trim();
            /* Aug 7 item 6: 2500 -> 9000 — the GitHub fallback body for a real
             * release runs ~5-6k and the old cap cut it mid-list ("... ").
             * The panel scrolls; length costs nothing. */
            if (t.Length > 9000) t = t.Substring(0, 9000).TrimEnd() + " ...";
            return t;
        }

        public static IEnumerator PresenceLoop()
        {
            yield return new WaitForSeconds(15f);
            // Codex batch find 3: with a flat 60s cadence, a game that starts
            // just after a tick has NO in_match evidence for up to a minute —
            // exactly the window in which a leave used to dissolve live game 1.
            // The loop now wakes every 5s and sends early whenever the match
            // group EDGE changes (battle started / group changed); steady state
            // stays one ping per 60s.
            string lastInMatchSent = null;
            float lastPingAt = -999f;
            while (true)
            {
                // July 21 item 4: keep a fresh Steam session (mints a web-API
                // ticket when the current one nears expiry; 60s self-backoff).
                try { SteamAuth.MaybeRefresh(); } catch { }
                try
                {
                    GameStateWatcher.EnsureIdentityResolved();
                    string sid = MatchTracker.LocalSteamId;
                    if (!string.IsNullOrEmpty(sid) && sid != "unknown")
                    {
                        string inMatch = GetPresenceMatchGroupId();
                        bool due = Time.realtimeSinceStartup - lastPingAt >= 60f;
                        bool edge = !string.IsNullOrEmpty(inMatch) && inMatch != lastInMatchSent;
                        if (due || edge)
                        {
                            lastPingAt = Time.realtimeSinceStartup;
                            string sentInMatch = inMatch;
                            string matchQuery = string.IsNullOrEmpty(inMatch)
                                ? ""
                                : $"&in_match={UnityWebRequest.EscapeURL(inMatch)}";
                            Plugin.Instance.StartCoroutine(GetRequest(
                                $"{baseUrl}/api/v1/presence/ping"
                                + $"?steam_id={UnityWebRequest.EscapeURL(sid)}"
                                + matchQuery,
                                (success, response) =>
                                {
                                    // Codex round-3 residual 3: the edge marker
                                    // advances only when the ping actually
                                    // LANDED — a transport-failed edge retries
                                    // on the next 5s tick instead of silently
                                    // leaving game 1 unprotected for 60s.
                                    if (success)
                                    {
                                        lastInMatchSent = sentInMatch;
                                        int on = ExtractJsonInt(response, "online");
                                        if (on != CachedOnlineCount)
                                        {
                                            CachedOnlineCount = on;
                                            NativeUI.MarkDirty();
                                        }
                                        // Aug 7 item 1: alerts revision rides the
                                        // ping; refetch only on a change-edge.
                                        int arev = ExtractJsonInt(response, "alerts_rev");
                                        if (arev > 0 && arev != LastAlertsRev)
                                            FetchActiveAlerts();
                                    }
                                }));
                        }
                    }
                }
                catch (Exception ex)
                {
                    Plugin.Log.LogWarning($"[PRESENCE] tick failed: {ex.Message}");
                }
                yield return new WaitForSeconds(5f);
            }
        }

        private static string GetPresenceMatchGroupId()
        {
            try
            {
                // A spectator is not IN a match — an in_match claim from a
                // spectator would veto queue-lifecycle cleanup for a group it
                // is not part of (design §3.5, #281's evidence discipline).
                if (RoomActors.LocalIsSpectator) return null;
                if (!CompetitiveRoomDetect.IsCompetitiveRoom()
                    || PhotonNetwork.CurrentRoom == null)
                    return null;
                // Codex batch find 2: room OCCUPANCY is not gameplay. During
                // assembly (3 of 4 joined, game never starts) an in_match claim
                // would veto the very cancel that frees the group. Claim only
                // while a battle is actually ongoing; the server's 210s TTL
                // bridges pick phases, round transitions and the rematch flow,
                // all far shorter than that.
                try
                {
                    if (GameManager.instance == null || !GameManager.instance.battleOngoing)
                        return null;
                }
                catch { return null; }

                string room = PhotonNetwork.CurrentRoom.Name ?? "";
                if (room.StartsWith("ffa_", StringComparison.Ordinal))
                    return string.IsNullOrEmpty(ActiveFfaLobbyId) ? null : ActiveFfaLobbyId;
                if (room.StartsWith("ovt_", StringComparison.Ordinal))
                    return string.IsNullOrEmpty(ActiveOvt1v2SeriesId) ? null : ActiveOvt1v2SeriesId;

                var props = PhotonNetwork.CurrentRoom.CustomProperties;
                bool isTeamRoom = room.StartsWith("team_", StringComparison.Ordinal)
                    || (props != null && props.ContainsKey("cr_ff"));
                if (isTeamRoom)
                    return string.IsNullOrEmpty(ActiveTeamSeriesId) ? null : ActiveTeamSeriesId;
            }
            catch { }
            return null;
        }

        // ── Aug 7 item 1: standing admin alerts ─────────────────────
        public class AlertEntry
        {
            public int id;
            public string category, admin_name, created_at, expires_at, message;
            // Codex r1 f16: parsed expiry (UTC). MaxValue = never expires
            // (empty/unparseable expires_at) so comparisons stay branch-free.
            public DateTime expiresUtc = DateTime.MaxValue;
        }
        public static List<AlertEntry> CachedAlerts = new List<AlertEntry>();
        public static int LastAlertsRev;
        private static bool alertsFetchInFlight;
        private const string PP_SEEN_ALERTS = "CR_SeenAlertIds";

        private static DateTime ParseAlertExpiry(string iso)
        {
            if (string.IsNullOrEmpty(iso)) return DateTime.MaxValue;
            try
            {
                if (DateTime.TryParse(iso, System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.AssumeUniversal | System.Globalization.DateTimeStyles.AdjustToUniversal,
                    out DateTime dt))
                    return dt;
            }
            catch { }
            return DateTime.MaxValue;
        }

        /// <summary>Codex r1 f16: drop CachedAlerts entries whose expiry has
        /// passed. Purely local (no server call); returns true when anything
        /// was removed so the caller can MarkDirty and clear the banner.</summary>
        public static bool PruneExpiredAlerts()
        {
            var list = CachedAlerts;
            if (list == null || list.Count == 0) return false;
            int removed = list.RemoveAll(a => a != null && a.expiresUtc <= DateTime.UtcNow);
            return removed > 0;
        }

        public static void FetchActiveAlerts()
        {
            if (alertsFetchInFlight || Plugin.Instance == null) return;
            alertsFetchInFlight = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/alerts/active",
                (ok, resp) =>
                {
                    alertsFetchInFlight = false;
                    if (!ok) return;
                    try
                    {
                        int rev = ExtractJsonInt(resp, "rev");
                        if (rev > 0) LastAlertsRev = rev;
                        var list = new List<AlertEntry>();
                        int arr = resp.IndexOf("\"alerts\"", StringComparison.Ordinal);
                        int open = arr >= 0 ? resp.IndexOf('[', arr) : -1;
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (close > open)
                        {
                            // message is admin-authored free text — string-aware
                            // slicing only (#156).
                            foreach (var raw in SliceTopLevelObjects(resp.Substring(open, close - open + 1)))
                            {
                                var a = new AlertEntry
                                {
                                    id = ExtractJsonInt(raw, "id"),
                                    category = ExtractJsonString(raw, "category") ?? "info",
                                    admin_name = ExtractJsonString(raw, "admin_name") ?? "Admin",
                                    created_at = ExtractJsonString(raw, "created_at") ?? "",
                                    expires_at = ExtractJsonString(raw, "expires_at") ?? "",
                                    message = ExtractJsonString(raw, "message") ?? "",
                                };
                                a.expiresUtc = ParseAlertExpiry(a.expires_at);
                                // Codex r1 f16: an already-expired alert never
                                // enters the cache (nor the announce pass).
                                if (a.expiresUtc <= DateTime.UtcNow) continue;
                                if (a.id > 0 && !string.IsNullOrEmpty(a.message)) list.Add(a);
                            }
                        }
                        CachedAlerts = list;
                        AnnounceUnseenAlerts(list);
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[ALERTS] parse: {ex.Message}"); }
                }));
        }

        /// <summary>One toast per alert id per install (PlayerPrefs seen-set,
        /// pruned to live ids + a small tail so it cannot grow forever). This
        /// is what makes "coming online" players see a standing notice once
        /// without being re-toasted every session.</summary>
        private static void AnnounceUnseenAlerts(List<AlertEntry> live)
        {
            try
            {
                var seen = new HashSet<int>();
                foreach (var tok in (PlayerPrefs.GetString(PP_SEEN_ALERTS, "") ?? "").Split(','))
                    if (int.TryParse(tok, out int v)) seen.Add(v);
                bool changed = false;
                foreach (var a in live)
                {
                    if (seen.Contains(a.id)) continue;
                    seen.Add(a.id); changed = true;
                    Color c = a.category == "outage" ? new Color(0.95f, 0.35f, 0.30f)
                            : a.category == "issue" ? new Color(1f, 0.72f, 0.30f)
                            : a.category == "update" ? new Color(0.45f, 0.85f, 1f)
                            : new Color(0.75f, 0.80f, 0.90f);
                    // Neutralize rich-text tags in user-authored fields before
                    // they touch a richText IMGUI style (mirror NativeUI.Escape).
                    string msg = (a.message ?? "").Replace("<", "(").Replace(">", ")");
                    string who = (a.admin_name ?? "Admin").Replace("<", "(").Replace(">", ")");
                    CompetitiveUI.QueueNotification(
                        I18n.TrF("[SERVER NOTICE] {0}: {1}", who, msg), c, 9f);
                    if (a.category == "outage") { try { TaskbarFlash.Flash(); } catch { } }
                }
                if (changed)
                {
                    // Prune: keep only ids that are still live plus the newest
                    // 50 — a revoked alert's id can drop out safely (a revoked
                    // alert is never re-announced because it never returns).
                    var keep = new List<int>();
                    foreach (var a in live) keep.Add(a.id);
                    foreach (var s in seen) { if (!keep.Contains(s)) keep.Add(s); if (keep.Count >= 50) break; }
                    PlayerPrefs.SetString(PP_SEEN_ALERTS, string.Join(",", keep.ConvertAll(i => i.ToString()).ToArray()));
                    PlayerPrefs.Save();
                }
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[ALERTS] announce: {ex.Message}"); }
        }

        // Admin side — mirrors AdminBan's shape. The create canonical binds
        // category + sha256(message)[:16] so a captured signature cannot be
        // replayed with a different payload (server computes the identical
        // UTF-8 lowercase-hex prefix).
        public static void AdminCreateAlert(string category, string message, int expiresMinutes, Action<bool, string> cb = null)
        {
            string admin = MatchTracker.LocalSteamId;
            string msg = (message ?? "").Trim();
            string sig = ComputeAdminHmacHex($"admin:{admin}:alert_create:{category}:{ComputeSha256Hex(msg).Substring(0, 16)}");
            string json = $"{{\"admin_steam_id\":\"{Escape(admin)}\",\"category\":\"{Escape(category)}\",\"message\":\"{JsonEscapeFull(msg)}\",\"expires_minutes\":{(expiresMinutes > 0 ? expiresMinutes.ToString() : "null")},\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry($"{baseUrl}/api/v1/admin/alerts", json, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[ALERTS] create ok={ok} resp={(resp != null && resp.Length > 200 ? resp.Substring(0, 200) : resp)}");
                if (ok) FetchActiveAlerts();
                cb?.Invoke(ok, resp);
            }));
        }

        public static void AdminRevokeAlert(int alertId, Action<bool, string> cb = null)
        {
            string admin = MatchTracker.LocalSteamId;
            string sig = ComputeAdminHmacHex($"admin:{admin}:alert_revoke:{alertId}");
            string json = $"{{\"admin_steam_id\":\"{Escape(admin)}\",\"alert_id\":{alertId},\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry($"{baseUrl}/api/v1/admin/alerts/revoke", json, (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[ALERTS] revoke {alertId} ok={ok}");
                if (ok) FetchActiveAlerts();
                cb?.Invoke(ok, resp);
            }));
        }

        public static List<AlertEntry> CachedAdminAlerts = new List<AlertEntry>();
        public static void FetchAdminAlerts(Action onDone = null)
        {
            string admin = MatchTracker.LocalSteamId;
            string sig = ComputeAdminHmacHex($"admin:{admin}:alerts_list:");
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/admin/alerts/list?admin_steam_id={Escape(admin)}&sig={sig}",
                (ok, resp) =>
                {
                    if (!ok) return;
                    try
                    {
                        var list = new List<AlertEntry>();
                        int arr = resp.IndexOf("\"alerts\"", StringComparison.Ordinal);
                        int open = arr >= 0 ? resp.IndexOf('[', arr) : -1;
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (close > open)
                        {
                            foreach (var raw in SliceTopLevelObjects(resp.Substring(open, close - open + 1)))
                            {
                                list.Add(new AlertEntry
                                {
                                    id = ExtractJsonInt(raw, "id"),
                                    category = (ExtractJsonBool(raw, "revoked") ? "revoked " : "")
                                               + (ExtractJsonString(raw, "category") ?? "info"),
                                    admin_name = ExtractJsonString(raw, "admin_name") ?? "Admin",
                                    created_at = ExtractJsonString(raw, "created_at") ?? "",
                                    expires_at = ExtractJsonString(raw, "expires_at") ?? "",
                                    message = ExtractJsonString(raw, "message") ?? "",
                                });
                            }
                        }
                        CachedAdminAlerts = list;
                        NativeUI.MarkDirty();
                        onDone?.Invoke();
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[ALERTS] admin list parse: {ex.Message}"); }
                }));
        }

        // ════════════════════════════════════════════════════════════
        // 2v2 RANKED (Phase 2 — client side)
        // ════════════════════════════════════════════════════════════

        public enum TeamQueueState { Idle, Searching, Matched, ReadySent, Leaving }

        [Serializable]
        public class TeamQueueMember
        {
            public string steam_id;
            public string display_name;
            public int rating;
            public string region;
            public int team_assigned; // 1, 2, or 0 if unassigned
            // Server-side balancer flag: true when the queuer's 2v2 sample is
            // too small to trust (completed_series < TEAM_TRUST_2V2_RATING_AFTER)
            // and the matchmaker is using their 1v1 rating instead. Surfaced in
            // the queue UI so users can verify the fallback fired when expected.
            public bool using_fallback_rating;
            public int balance_rating;     // the rating the balancer actually uses (2v2 or 1v1 fallback)
            public int completed_series;   // 2v2 series count at queue join time
            public bool ready;             // per-slot ready flag for the lock-in prompt
        }

        [Serializable]
        public class TeamQueuePollData
        {
            public string status;
            public int queue_count;
            public int elo_range;
            public string series_id;
            public int team_assigned;
            public List<TeamQueueMember> teammates = new List<TeamQueueMember>();
            public List<TeamQueueMember> opponents = new List<TeamQueueMember>();
            public string room_name;
            public string room_region;
            public int match_age_seconds;
            public bool my_ready;          // the polling player's own ready flag
        }

        [Serializable]
        public class TeamQueueListEntry
        {
            public string steam_id;
            public string display_name;
            public int rating;
            public int balance_rating;
            public bool using_fallback_rating;
            public int completed_series;
            public string region;
            public string status;
            public int team_assigned;
            public string series_id;
            public int wait_seconds;
            public bool manual_pick_enabled;
            public int preferred_team;
            public string queue_type;  // "auto" or "manual" — empty defaults to auto
        }
        public static List<TeamQueueListEntry> CachedTeamQueueList { get; private set; } = new List<TeamQueueListEntry>();
        // Pre-bucketed views for the F5 panel — saves the renderer from re-filtering every frame.
        public static List<TeamQueueListEntry> CachedTeamQueueAuto { get; private set; } = new List<TeamQueueListEntry>();
        public static List<TeamQueueListEntry> CachedTeamQueueManual { get; private set; } = new List<TeamQueueListEntry>();
        private static float teamQueueListTimer = 0f;
        // Tight 2s polling so the panel reflects new queuers within ~2s of them
        // joining. User reported: "In Queue doesn't seem to update with new
        // players when someone joins until i back out and rejoin the queue".
        private const float TEAM_QUEUE_LIST_INTERVAL = 2f;

        public static TeamQueueState CurrentTeamQueueState { get; private set; } = TeamQueueState.Idle;
        private static float teamLeavingSince = -999f;
        private static int teamGen = 0;  // lifecycle generation — see queueGen
        public static TeamQueuePollData LastTeamPollData { get; private set; }
        // Aug 8 (Sid): frozen body-colour team identity for the ACTIVE 2v2
        // series, published for the in-game tinting pass (another writer).
        // Empty string = vanilla / not stamped. Set by the series-state poll;
        // cleared by the ActiveTeamSeriesId setter below, which is the single
        // chokepoint every series-context change (leave, expiry, escape,
        // completion teardown) already flows through.
        public static string SeriesTeam1ColorName = "", SeriesTeam1ColorHex = "";
        public static string SeriesTeam2ColorName = "", SeriesTeam2ColorHex = "";
        // Codex r2 f8-adjacent: true once the server has DECIDED the identity
        // for the active series — a decided-vanilla answer ('' hexes) must
        // still freeze the live local fallback, so the bool is carried
        // separately from the hex emptiness.
        public static bool SeriesColorDecided;
        private static string activeTeamSeriesId;
        public static string ActiveTeamSeriesId
        {
            get => activeTeamSeriesId;
            set
            {
                if (!string.Equals(value, activeTeamSeriesId, StringComparison.Ordinal))
                {
                    SeriesTeam1ColorName = ""; SeriesTeam1ColorHex = "";
                    SeriesTeam2ColorName = ""; SeriesTeam2ColorHex = "";
                    SeriesColorDecided = false;
                    // Codex r2 f8: the series-state cache is SCOPED to the
                    // series it described. Without this reset a failed FIRST
                    // poll of a NEW series left stale "active/4"-style values
                    // standing, and the assembly loop (Plugin.cs — requires
                    // LastSeriesStateForId == current id) could terminate on
                    // the PREVIOUS series' answer.
                    LastSeriesStateForId = null;
                    LastSeriesStateStatus = null;
                    LastSeriesStateReason = null;
                    LastSeriesStateConfirmations = 0;
                    LastSeriesDcGraceSeconds = 0;
                    LastSeriesDcTeamRemaining = 0;
                    LastSeriesT1Wins = 0;
                    LastSeriesT2Wins = 0;
                }
                activeTeamSeriesId = value;
            }
        }
        public static bool IsTeamQueuePolling { get; private set; } = false;
        public static int CachedTeamQueueSearching { get; private set; } = 0;
        private static float teamQueuePollTimer = 0f;
        private static float teamQueueCountTimer = 0f;
        private const float TEAM_QUEUE_POLL_INTERVAL = 3f;
        private const float TEAM_QUEUE_COUNT_INTERVAL = 10f;

        // Tracks which queue (auto / manual) the local player joined. Read by
        // the F5 tab to render the team-pick controls only inside the manual
        // queue and to highlight the active "Search Random" / "Find Custom"
        // button.
        public static string CurrentTeamQueueType { get; private set; } = "auto";

        public static void JoinTeamQueue(string steamId, string displayName, string region, string queueType = "auto")
        {
            if (SpectatorBlocksQueue()) return;
            NoteQueueRequestInFlight();   // r3: WATCH is blocked for the whole join round-trip   // design §3.1
            // v1.37 host lobbies: a queue join from a held open seat would
            // clobber the seat's row server-side. Leave first, explicitly.
            if (!string.IsNullOrEmpty(TeamLobby.OpenLobbyId))
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Leave your 2v2 lobby first."), new Color(1f, 0.7f, 0.3f), 5f);
                return;
            }
            // Codex r2 f3: an unresolved leave (lobby or converted-seat) must
            // fully land before a NEW queue row exists for it to race.
            if (HostLobbyClient.HasPendingLeave("team"))
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Finishing your previous leave first..."), new Color(1f, 0.6f, 0.2f), 4f);
                return;
            }
            // Suppress joining while a leave retry is in flight (same rationale
            // as JoinQueue); force-recover past the safety timeout.
            if (CurrentTeamQueueState == TeamQueueState.Leaving)
            {
                if (Time.realtimeSinceStartup - teamLeavingSince < LEAVE_STUCK_TIMEOUT)
                {
                    CompetitiveUI.ShowNotification("Still leaving the 2v2 queue — try again in a moment.", new Color(1f, 0.6f, 0.2f));
                    return;
                }
                CurrentTeamQueueState = TeamQueueState.Idle;
            }
            if (string.IsNullOrEmpty(region))
            {
                try { region = PhotonNetwork.CloudRegion?.Replace("/*", "") ?? ""; } catch { region = ""; }
            }
            // F2 (Codex r3): last gate before the send — one enrollment in
            // flight per mode, shared with the hosted Create/Join paths.
            if (!EnrollGateBegin("team")) return;
            string qt = (queueType == "manual") ? "manual" : "auto";
            string safeName = Escape(displayName ?? steamId);
            string json = $"{{\"steam_id\":\"{Escape(steamId)}\",\"display_name\":\"{safeName}\",\"region\":\"{Escape(region ?? "")}\",\"queue_type\":\"{qt}\"}}";
            int gen = ++teamGen;
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/team/queue/join", json,
                (success, response) =>
                {
                    // F2: release the latch BEFORE the gen check — a stale ack
                    // must still free the mode for the next enrollment.
                    EnrollGateEnd("team");
                    if (gen != teamGen)
                    {
                        Plugin.Log.LogInfo("[TEAM-QUEUE] stale join ack ignored (lifecycle moved on)");
                        return;
                    }
                    if (success)
                    {
                        CurrentTeamQueueState = TeamQueueState.Searching;
                        CurrentTeamQueueType = qt;
                        IsTeamQueuePolling = true;
                        teamQueuePollTimer = 0f;
                        Plugin.Log.LogInfo($"[TEAM-QUEUE] Joined 2v2 {qt} queue");
                        string msg = qt == "manual" ? "Searching for custom 2v2 lobby..." : "Searching for 2v2 match...";
                        CompetitiveUI.ShowNotification(msg, new Color(0.4f, 0.8f, 1f));
                        NativeUI.MarkDirty();
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[TEAM-QUEUE] Join failed: {response}");
                        CompetitiveUI.ShowNotification("Couldn't join the 2v2 queue", new Color(1f, 0.4f, 0.4f));
                    }
                }
            ));
        }

        public static void LeaveTeamQueue(string steamId)
        {
            if (CurrentTeamQueueState == TeamQueueState.Leaving) return; // leave already in flight
            if (CurrentTeamQueueState == TeamQueueState.Idle && !IsTeamQueuePolling) return;
            // Leaving until the server confirms — a failed leave (401/503
            // queue_contended) with local state already Idle strands our row
            // and can ghost-lock the other three (review finding).
            // Idempotent request; Idle finalized only in the callback.
            //
            // F3 (Codex r3): capture the series incarnation BEFORE any local
            // clear — this legacy public path used to null ActiveTeamSeriesId
            // first and then build an UNFENCED leave URL, so a delayed retry
            // could tear down a NEWER enrollment (HostLobbyClient's
            // DirectQueueLeave already fences). The id clears in the RESPONSE
            // handler (#249), never before the request; the stuck-Leaving
            // watchdog in TickLeaveRecovery clears it if the callback dies.
            string fenceSeriesId = ActiveTeamSeriesId;
            int gen = ++teamGen;
            CurrentTeamQueueState = TeamQueueState.Leaving;
            teamLeavingSince = Time.realtimeSinceStartup;
            // Eager poll disarm stays: it is what prevents a fresh poll from
            // re-adopting the match while the leave is in flight.
            IsTeamQueuePolling = false;
            LastTeamPollData = null;
            Plugin.ClearPending2v2Slot();
            NativeUI.MarkDirty();
            string leaveUrl = $"{baseUrl}/api/v1/team/queue/leave?steam_id={Escape(steamId)}";
            if (!string.IsNullOrEmpty(fenceSeriesId))
                leaveUrl += $"&expected_series_id={UnityWebRequest.EscapeURL(fenceSeriesId)}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                leaveUrl, "",
                (success, response) =>
                {
                    if (gen != teamGen) return;  // watchdog recovered / new lifecycle
                    if (success)
                    {
                        // {"stale":true} = the row's CURRENT series differs from
                        // the fenced incarnation — that incarnation is gone,
                        // which is exactly what this leave wanted.
                        if (ExtractJsonBool(response ?? "", "stale"))
                            Plugin.Log.LogInfo("[TEAM-QUEUE] fenced leave hit a newer incarnation — old seat already gone");
                        else
                            Plugin.Log.LogInfo("[TEAM-QUEUE] Left 2v2 queue");
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[TEAM-QUEUE] Leave failed after retries: {response} — server will prune the stale row");
                        CompetitiveUI.ShowNotification("Couldn't confirm 2v2 queue leave — the server will clear you shortly.", new Color(1f, 0.6f, 0.2f), 5f);
                    }
                    // F3/#249: the series belief clears on the RESPONSE, both
                    // outcomes — failure keeps today's best-effort semantics
                    // (the server prunes the row) while the fence above kept
                    // the request honest about WHICH incarnation it targeted.
                    if (string.Equals(ActiveTeamSeriesId, fenceSeriesId, StringComparison.Ordinal))
                        ActiveTeamSeriesId = null;
                    if (CurrentTeamQueueState == TeamQueueState.Leaving)
                        CurrentTeamQueueState = TeamQueueState.Idle;
                    NativeUI.MarkDirty();
                },
                maxRetries: 3, retryDelay: 2f
            ));
        }

        public static void ReadyUpTeam(string steamId)
        {
            if (CurrentTeamQueueState != TeamQueueState.Matched) return;
            CurrentTeamQueueState = TeamQueueState.ReadySent;
            NativeUI.MarkDirty();
            Plugin.Log.LogInfo("[TEAM-QUEUE] Ready Up sent");
            int gen = teamGen;  // captured, not bumped: ready is not a lifecycle edge
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                $"{baseUrl}/api/v1/team/queue/ready?steam_id={Escape(steamId)}", "",
                (success, response) =>
                {
                    // Same-lifecycle + still-ReadySent only (Codex verify
                    // finding 3): a delayed failure ack after a leave must not
                    // restore Matched with polling off.
                    if (gen != teamGen || CurrentTeamQueueState != TeamQueueState.ReadySent) return;
                    if (!success)
                    {
                        Plugin.Log.LogWarning($"[TEAM-QUEUE] Ready failed after retries: {response}");
                        CompetitiveUI.ShowNotification("Ready-up failed — retrying search", new Color(1f, 0.6f, 0.2f), 5f);
                        CurrentTeamQueueState = TeamQueueState.Matched;
                        NativeUI.MarkDirty();
                    }
                },
                maxRetries: 3, retryDelay: 2f
            ));
        }

        public static void UpdateTeamQueuePoll(string steamId)
        {
            if (!IsTeamQueuePolling) return;
            teamQueuePollTimer += Time.deltaTime;
            if (teamQueuePollTimer < TEAM_QUEUE_POLL_INTERVAL) return;
            teamQueuePollTimer = 0f;
            int gen = teamGen;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/queue/poll/{steamId}",
                (success, response) =>
                {
                    // gen check: see UpdateQueuePoll (Codex verify finding 4).
                    if (!success || !IsTeamQueuePolling || gen != teamGen) return;
                    try { ParseTeamQueuePoll(response); }
                    catch (Exception ex) { Plugin.Log.LogError($"[TEAM-QUEUE] poll parse: {ex.Message}"); }
                }
            ));
        }

        // Polled by the F5 2v2 tab to render the "who's in queue" panel.
        // Throttled at 5s to keep request volume low.
        public static void UpdateTeamQueueList(bool force = false)
        {
            teamQueueListTimer += Time.deltaTime;
            if (!force && teamQueueListTimer < TEAM_QUEUE_LIST_INTERVAL) return;
            teamQueueListTimer = 0f;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/queue/list",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try { ParseTeamQueueList(response); NativeUI.MarkDirty(); }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[TEAM-QUEUE-LIST] parse: {ex.Message}"); }
                }
            ));
        }

        private static void ParseTeamQueueList(string response)
        {
            var list = new List<TeamQueueListEntry>();
            int qStart = response.IndexOf("\"queuers\"");
            if (qStart < 0) { CachedTeamQueueList = list; return; }
            int arrStart = response.IndexOf('[', qStart);
            int arrEnd = FindMatchingBracket(response, arrStart);
            if (arrStart < 0 || arrEnd < 0) { CachedTeamQueueList = list; return; }
            string slice = response.Substring(arrStart + 1, arrEnd - arrStart - 1);
            int oIdx = 0;
            while (oIdx < slice.Length)
            {
                int objStart = slice.IndexOf('{', oIdx);
                if (objStart < 0) break;
                int oDepth = 1, j = objStart + 1;
                while (j < slice.Length && oDepth > 0)
                {
                    if (slice[j] == '{') oDepth++;
                    else if (slice[j] == '}') oDepth--;
                    j++;
                }
                if (oDepth != 0) break;
                string obj = slice.Substring(objStart, j - objStart);
                string qt = ExtractJsonString(obj, "queue_type");
                if (string.IsNullOrEmpty(qt)) qt = "auto";
                list.Add(new TeamQueueListEntry
                {
                    steam_id = ExtractJsonString(obj, "steam_id"),
                    display_name = ExtractJsonString(obj, "display_name"),
                    rating = ExtractJsonInt(obj, "rating"),
                    balance_rating = ExtractJsonInt(obj, "balance_rating"),
                    using_fallback_rating = ExtractJsonBool(obj, "using_fallback_rating"),
                    completed_series = ExtractJsonInt(obj, "completed_series"),
                    region = ExtractJsonString(obj, "region"),
                    status = ExtractJsonString(obj, "status"),
                    team_assigned = ExtractJsonInt(obj, "team_assigned"),
                    series_id = ExtractJsonString(obj, "series_id"),
                    wait_seconds = ExtractJsonInt(obj, "wait_seconds"),
                    manual_pick_enabled = ExtractJsonBool(obj, "manual_pick_enabled"),
                    preferred_team = ExtractJsonInt(obj, "preferred_team"),
                    queue_type = qt,
                });
                oIdx = j;
            }
            CachedTeamQueueList = list;
            var autoB = new List<TeamQueueListEntry>();
            var manB = new List<TeamQueueListEntry>();
            foreach (var e in list)
            {
                if (e.queue_type == "manual") manB.Add(e); else autoB.Add(e);
            }
            CachedTeamQueueAuto = autoB;
            CachedTeamQueueManual = manB;
        }

        // Toggle the local player's manual_pick_enabled flag in the team queue.
        // When 3 of the 4 queuers have it enabled, the matchmaker honors
        // each player's preferred_team (otherwise it auto-balances by elo).
        public static void ToggleTeamManualPick(string steamId, bool enabled)
        {
            if (string.IsNullOrEmpty(steamId)) return;
            string url = $"{baseUrl}/api/v1/team/queue/manual-pick-toggle?steam_id={UnityWebRequest.EscapeURL(steamId)}&enabled={(enabled ? "true" : "false")}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                if (ok) Plugin.Log.LogInfo($"[2v2-MANUAL] toggle={enabled} ok: {resp}");
                else Plugin.Log.LogWarning($"[2v2-MANUAL] toggle failed: {resp}");
                UpdateTeamQueueList(force: true);
            }));
        }

        public static void SetTeamPreferredTeam(string steamId, int team)
        {
            if (string.IsNullOrEmpty(steamId)) return;
            string url = $"{baseUrl}/api/v1/team/queue/preferred-team?steam_id={UnityWebRequest.EscapeURL(steamId)}&team={team}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                if (ok) Plugin.Log.LogInfo($"[2v2-MANUAL] team={team} ok: {resp}");
                else Plugin.Log.LogWarning($"[2v2-MANUAL] team set failed: {resp}");
                UpdateTeamQueueList(force: true);
            }));
        }

        private static void ParseTeamQueuePoll(string response)
        {
            string status = ExtractJsonString(response, "status");
            var data = new TeamQueuePollData
            {
                status = status,
                queue_count = ExtractJsonInt(response, "queue_count"),
                elo_range = ExtractJsonInt(response, "elo_range"),
                series_id = ExtractJsonString(response, "series_id"),
                team_assigned = ExtractJsonInt(response, "team_assigned"),
                room_name = ExtractJsonString(response, "room_name"),
                room_region = ExtractJsonString(response, "room_region"),
                match_age_seconds = ExtractJsonInt(response, "match_age_seconds"),
                my_ready = ExtractJsonBool(response, "my_ready"),
            };
            data.teammates = ExtractTeamMemberList(response, "teammates");
            data.opponents = ExtractTeamMemberList(response, "opponents");
            LastTeamPollData = data;

            if (status == "ready_join")
            {
                if (!string.IsNullOrEmpty(data.room_name))
                {
                    IsTeamQueuePolling = false;
                    CurrentTeamQueueState = TeamQueueState.Idle;
                    ActiveTeamSeriesId = data.series_id;
                    // Compute MY slot in the 4-player lineup: team_assigned (1 or 2)
                    // determines team-half, and steam-id sort within team determines
                    // which of the 2 within-team slots is mine. Server's lock-time
                    // canonicalization sorts the same way, so all 4 clients agree.
                    int slot = ComputeMy2v2Slot(MatchTracker.LocalSteamId, data.team_assigned, data.teammates);
                    Plugin.SetPending2v2Slot(slot);
                    // Pre-populate Photon LocalPlayer custom properties NOW, before the
                    // room is even joined. When we join the team_ room these props ride
                    // along with the Photon Player record sent to all room members, so
                    // remote clients reading Owner.CustomProperties[p_id]/[t_id] inside
                    // Player.Start always see the correct slot — no race against
                    // PhotonNetwork.Instantiate's broadcast order.
                    try
                    {
                        var prejoin = new ExitGames.Client.Photon.Hashtable();
                        prejoin["p_id"] = slot;
                        prejoin["t_id"] = slot / 2;
                        // Publish our Steam ID under "u_id" so peers can resolve
                        // actor → Steam ID at match-end time. Vanilla
                        // PlayerAssigner.CreatePlayer normally calls AssignUserID
                        // which writes this — our 2v2 CreatePlayer override skips
                        // it (intentionally, to avoid pulling in extra ROUNDS
                        // identity machinery). Without u_id, ResolvePhotonSteamId
                        // falls back to "photon_<actor>", TryReportTeamMatch
                        // aborts with "couldn't resolve Steam ID for actor X",
                        // and the match silently routes to the 1v1 casual path.
                        // That's why every 2v2 was logging in the My Stats tab
                        // instead of the 2v2 tab.
                        string mySid = MatchTracker.LocalSteamId;
                        if (!string.IsNullOrEmpty(mySid) && mySid != "unknown")
                            prejoin["u_id"] = mySid;
                        if (PhotonNetwork.LocalPlayer != null)
                            PhotonNetwork.LocalPlayer.SetCustomProperties(prejoin);
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[2v2] pre-join SetCustomProperties: {ex.Message}"); }

                    // Publish styled NickName + cosmetic props BEFORE the Photon
                    // room join completes, so when remote clients receive the
                    // join broadcast for our actor, our NickName is already the
                    // styled version. Otherwise they cache the unstyled persona
                    // name when they first see our actor and the in-game
                    // nametag label never picks up the styling — user reported:
                    // "Sid didn't show up with all the name stylizing on
                    // anyone's screen in the first game" (then it appeared in
                    // game 2 because the periodic stats-reload publish
                    // eventually re-broadcast the styled NickName). The
                    // PublishToPhoton at room-join (GameStateWatcher) is
                    // post-join — too late for the initial spawn read.
                    try { NametagStyler.PublishToPhoton(); } catch (Exception ex) { Plugin.Log.LogWarning($"[2v2] pre-join nametag publish: {ex.Message}"); }
                    try { PlayerColorCosmetic.PublishLocalProps(); } catch (Exception ex) { Plugin.Log.LogWarning($"[2v2] pre-join pcolor publish: {ex.Message}"); }
                    try { TrailCosmetic.PublishLocalProps(); } catch (Exception ex) { Plugin.Log.LogWarning($"[2v2] pre-join trail publish: {ex.Message}"); }

                    Plugin.SetPendingRoom(data.room_name, data.room_region);
                    Plugin.Log.LogInfo($"[TEAM-QUEUE] All ready! Room: {data.room_name} (region: {data.room_region ?? "auto"}) series={data.series_id} my_slot={slot}");
                    CompetitiveUI.ShowNotification("4/4 ready! Joining 2v2...", Color.green, 5f);
                    // Auto-close the F5 panel so testers don't sit on the queue screen
                    // while the Photon room is loading. Otherwise they have to manually
                    // close before they can see ROUNDS' character-select / game scene.
                    try { if (NativeUI.IsOpen) NativeUI.Close(); } catch { }
                    NativeUI.MarkDirty();
                }
            }
            else if (status == "matched")
            {
                if (CurrentTeamQueueState != TeamQueueState.ReadySent)
                    CurrentTeamQueueState = TeamQueueState.Matched;
                ActiveTeamSeriesId = data.series_id;
                NativeUI.MarkDirty();
            }
            else if (status == "searching")
            {
                if (CurrentTeamQueueState != TeamQueueState.Searching)
                {
                    // Was matched, got bumped back (someone left)
                    CurrentTeamQueueState = TeamQueueState.Searching;
                    ActiveTeamSeriesId = null;
                    Plugin.ClearPending2v2Slot();
                    CompetitiveUI.ShowNotification("Match canceled — searching again...", new Color(1f, 0.6f, 0.2f), 5f);
                }
                NativeUI.MarkDirty();
            }
            else if (status == "lobby")
            {
                // v1.37 host lobbies: a still-armed queue poll whose searching
                // row was CONVERTED by a lobby enroll. The /team/lobby/state
                // heartbeat owns this state — disarm the queue machinery and
                // adopt the seat.
                IsTeamQueuePolling = false;
                CurrentTeamQueueState = TeamQueueState.Idle;
                TeamLobby.AdoptSeatFromQueuePoll(ExtractJsonString(response, "series_id"));
                NativeUI.MarkDirty();
            }
            else if (status == "lobby_closed")
            {
                IsTeamQueuePolling = false;
                CurrentTeamQueueState = TeamQueueState.Idle;
                TeamLobby.HandleSeatExpired();
                NativeUI.MarkDirty();
            }
            else if (status == "expired" || status == "not_in_queue")
            {
                IsTeamQueuePolling = false;
                CurrentTeamQueueState = TeamQueueState.Idle;
                LastTeamPollData = null;
                ActiveTeamSeriesId = null;
                Plugin.ClearPending2v2Slot();
                // 30-min server cap (July 28): tell the player WHY the queue
                // ended — silently flipping to Idle looked like a mystery bug.
                if (status == "expired")
                    CompetitiveUI.ShowNotification(
                        "Removed from 2v2 queue after 30 minutes of searching - rejoin if you're still here!",
                        Color.yellow, 7f);
                NativeUI.MarkDirty();
            }
        }

        /// <summary>Compute the local player's 0-3 slot in the 4-player ROUNDS
        /// lineup. Team 1 → slots 0,1; team 2 → slots 2,3. Within each team,
        /// the 2 slots are assigned by steam-id ordinal sort — same canonical
        /// rule the server uses at lock time, so all 4 clients independently
        /// arrive at consistent unique slots without any extra coordination.</summary>
        public static int ComputeMy2v2Slot(string mySteamId, int teamAssigned, List<TeamQueueMember> teammates)
        {
            int teamBase = (teamAssigned == 2) ? 2 : 0;
            // Find my one teammate (same team_assigned). If we can't, fall
            // back to slot 0 within team — better than collision.
            string mateSteamId = null;
            if (teammates != null)
            {
                foreach (var t in teammates)
                {
                    if (t == null) continue;
                    if (t.team_assigned == teamAssigned && t.steam_id != mySteamId)
                    {
                        mateSteamId = t.steam_id;
                        break;
                    }
                }
            }
            if (string.IsNullOrEmpty(mateSteamId)) return teamBase;
            // Within-team sort by steam_id ordinal. Lower = slot 0; higher = slot 1.
            int withinTeam = string.Compare(mySteamId, mateSteamId, StringComparison.Ordinal) <= 0 ? 0 : 1;
            return teamBase + withinTeam;
        }

        /// <summary>Manual TeamQueueMember[] parser. Photon JsonUtility chokes on
        /// nested arrays so we hand-extract the slice for `key`. Format:
        /// `"key":[{...},{...}]`. Returns empty list on missing/malformed.</summary>
        private static List<TeamQueueMember> ExtractTeamMemberList(string json, string key)
        {
            var list = new List<TeamQueueMember>();
            try
            {
                // String-AWARE slicing (#156, lobby-redesign design review find
                // 12): these arrays carry display names, and a name containing
                // ']' or '}' broke the naive depth counters this used — which
                // truncated the READY ROSTER for 2v2/1v2/FFA locks, not just a
                // cosmetic list.
                int kIdx = json.IndexOf("\"" + key + "\"");
                int arrStart = kIdx >= 0 ? json.IndexOf('[', kIdx) : -1;
                int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(json, arrStart) : -1;
                if (arrStart < 0 || arrEnd <= arrStart) return list;
                foreach (string obj in SliceTopLevelObjects(json.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                {
                    list.Add(new TeamQueueMember
                    {
                        steam_id = ExtractJsonString(obj, "steam_id"),
                        display_name = ExtractJsonString(obj, "display_name"),
                        rating = ExtractJsonInt(obj, "rating"),
                        region = ExtractJsonString(obj, "region"),
                        team_assigned = ExtractJsonInt(obj, "team_assigned"),
                        using_fallback_rating = ExtractJsonBool(obj, "using_fallback_rating"),
                        balance_rating = ExtractJsonInt(obj, "balance_rating"),
                        completed_series = ExtractJsonInt(obj, "completed_series"),
                        ready = ExtractJsonBool(obj, "ready"),
                    });
                }
            }
            catch { }
            return list;
        }

        public static void UpdateTeamQueueCount()
        {
            teamQueueCountTimer += Time.deltaTime;
            if (teamQueueCountTimer < TEAM_QUEUE_COUNT_INTERVAL) return;
            teamQueueCountTimer = 0f;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/queue/count",
                (success, response) =>
                {
                    if (success)
                    {
                        int s = ExtractJsonInt(response, "searching");
                        if (s != CachedTeamQueueSearching)
                        {
                            CachedTeamQueueSearching = s;
                            NativeUI.MarkDirty();
                        }
                    }
                }
            ));
        }

        /// <summary>Tracks the most recent series-state poll response so the
        /// dispatcher coroutine can react. Set by PollTeamSeriesState.</summary>
        public static string LastSeriesStateStatus = null;
        public static string LastSeriesStateReason = null;
        public static int LastSeriesStateConfirmations = 0;
        public static int LastSeriesDcGraceSeconds = 0;
        public static int LastSeriesDcTeamRemaining = 0;
        public static int LastSeriesT1Wins = 0;
        public static int LastSeriesT2Wins = 0;
        // Codex r2 f8: WHICH series the LastSeriesState* fields describe. Set
        // ONLY in PollTeamSeriesState's success callback (to the id that
        // response was for) and reset by the ActiveTeamSeriesId setter, so a
        // consumer can require ForId == current before trusting the cache.
        public static string LastSeriesStateForId = null;
        // Throttled background poll of the team-series state — 2s while we
        // have an active or paused series, off otherwise.
        private static float teamSeriesStateTimer = 0f;
        private const float TEAM_SERIES_STATE_INTERVAL = 2f;
        public static void UpdateTeamSeriesStatePoll(bool force)
        {
            string sid = ActiveTeamSeriesId;
            if (string.IsNullOrEmpty(sid)) return;
            teamSeriesStateTimer += Time.deltaTime;
            if (!force && teamSeriesStateTimer < TEAM_SERIES_STATE_INTERVAL) return;
            teamSeriesStateTimer = 0f;
            PollTeamSeriesState(sid, (status, reason, conf) =>
            {
                // PollTeamSeriesState already populates LastSeriesStateStatus etc.
                // We just need to extract the DC fields, which it doesn't currently
                // parse — the response JSON has them, but the in-helper parse uses
                // a fixed callback signature. Refresh in a separate parse below.
            });
        }

        /// <summary>POST /team/series/continuation. Called by the reporter (lowest Steam
        /// ID) at game start when still in a cr_ff room with 4 players but no active team
        /// series — i.e. the previous BO3 completed and they kept playing. Opens a fresh
        /// active series for the same four + room so games 4+ record as ranked (closes the
        /// recording gap). Sets ActiveTeamSeriesId on success. Idempotent server-side.</summary>
        public static void RequestContinuationSeries(
            string reporterSteam, string roomId, string region,
            string t1a, string t1b, string t2a, string t2b, Action<bool> callback = null)
        {
            string canonical = $"team-continuation:{t1a}:{t1b}:{t2a}:{t2b}:{roomId}:{reporterSteam}";
            string sig = ComputeHmacHex(canonical);
            string body = $"{{\"reporter_steam_id\":\"{Escape(reporterSteam)}\",\"room_id\":\"{Escape(roomId)}\"," +
                          $"\"region\":\"{Escape(region ?? "")}\",\"t1a_steam\":\"{Escape(t1a)}\",\"t1b_steam\":\"{Escape(t1b)}\"," +
                          $"\"t2a_steam\":\"{Escape(t2a)}\",\"t2b_steam\":\"{Escape(t2b)}\",\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry($"{baseUrl}/api/v1/team/series/continuation", body, (ok, resp) =>
            {
                if (ok && !string.IsNullOrEmpty(resp))
                {
                    string sid = ExtractJsonString(resp, "series_id");
                    if (!string.IsNullOrEmpty(sid))
                    {
                        ActiveTeamSeriesId = sid;
                        Plugin.Log.LogInfo($"[2v2-CONTINUATION] active series set to {sid} ({ExtractJsonString(resp, "status")})");
                        // Codex r2 f6: BOTH continuation branches ("created" and
                        // the idempotent "existing") now carry the frozen colour
                        // stamp, and the reporter is the ONLY seat that sees this
                        // response — adopt it into the statics and publish the
                        // room property so every seat/spectator renders the same
                        // identity without waiting for their own state poll.
                        // Guarded to the id just adopted (the setter above wiped
                        // the previous series' colours if the id changed).
                        if (sid == ActiveTeamSeriesId)
                        {
                            SeriesTeam1ColorName = ExtractJsonString(resp, "t1_color_name") ?? "";
                            SeriesTeam1ColorHex = ExtractJsonString(resp, "t1_color_hex") ?? "";
                            SeriesTeam2ColorName = ExtractJsonString(resp, "t2_color_name") ?? "";
                            SeriesTeam2ColorHex = ExtractJsonString(resp, "t2_color_hex") ?? "";
                            SeriesColorDecided = ExtractJsonBool(resp, "color_decided");
                            TeamColorIdentity.PublishSeriesStamp(sid,
                                SeriesTeam1ColorName, SeriesTeam1ColorHex,
                                SeriesTeam2ColorName, SeriesTeam2ColorHex, SeriesColorDecided);
                        }
                    }
                }
                else Plugin.Log.LogWarning($"[2v2-CONTINUATION] request failed: {resp}");
                callback?.Invoke(ok);
            }));
        }

        /// <summary>POST /team/series/{id}/report-dc. Called from
        /// Cr2v2DiagCallbacks.OnPlayerLeftRoom when the lowest-Steam-ID remaining
        /// client detects a mid-series DC. Server applies the 2v2 DC rule (any
        /// match abandoned with >=2 total points → non-DC team wins) and starts
        /// the 5-min sticky-team requeue grace window.</summary>
        public static void ReportTeamSeriesDc(
            string seriesId, string reporterSteamId, string dcPlayerSteamId,
            int t1PointsTotal, int t2PointsTotal)
        {
            // §2c identity fence: the broadcast service account never reports.
            if (BroadcastMode.FenceBlocksFighterPath("report-2v2-dc")) return;
            if (string.IsNullOrEmpty(seriesId) || string.IsNullOrEmpty(reporterSteamId) || string.IsNullOrEmpty(dcPlayerSteamId)) return;
            string sig = ComputeHmacHex($"{reporterSteamId}:{seriesId}:{dcPlayerSteamId}:dc");
            // Bug 245 companion: name the room this DC was OBSERVED in (raw,
            // unsuffixed). The server ignores a report whose room no longer
            // matches the series' CURRENT room — a requeue-resume re-issues
            // the room, so a deferred report about the abandoned old room
            // must not lead-forfeit the resumed sitting mid-play. Unsigned
            // hint by design (the DC canonical is frozen); empty when the
            // room is already gone, which keeps legacy behavior.
            string dcRoom = "";
            try { dcRoom = PhotonNetwork.InRoom ? (PhotonNetwork.CurrentRoom?.Name ?? "") : ""; } catch { }
            string url = $"{baseUrl}/api/v1/team/series/{seriesId}/report-dc" +
                         $"?reporter_steam_id={UnityWebRequest.EscapeURL(reporterSteamId)}" +
                         $"&dc_player_steam_id={UnityWebRequest.EscapeURL(dcPlayerSteamId)}" +
                         $"&t1_points_total={t1PointsTotal}" +
                         $"&t2_points_total={t2PointsTotal}" +
                         $"&photon_room_id={UnityWebRequest.EscapeURL(dcRoom)}" +
                         $"&hmac_sig={UnityWebRequest.EscapeURL(sig)}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                if (ok) Plugin.Log.LogInfo($"[2v2-DC] report accepted: {resp}");
                else Plugin.Log.LogWarning($"[2v2-DC] report failed: {resp}");
            }));
        }

        /// <summary>POST /team/series/{id}/spawn-confirm. Called from the auto-spawn
        /// coroutine when CreatePlayer override successfully creates the local
        /// Player in a cr_ff room. Idempotent server-side.</summary>
        public static void SendTeamSpawnConfirm(string seriesId, string steamId)
        {
            if (string.IsNullOrEmpty(seriesId) || string.IsNullOrEmpty(steamId)) return;
            string sig = ComputeHmacHex($"{steamId}:{seriesId}:spawn");
            string url = $"{baseUrl}/api/v1/team/series/{seriesId}/spawn-confirm" +
                         $"?steam_id={UnityWebRequest.EscapeURL(steamId)}" +
                         $"&hmac_sig={UnityWebRequest.EscapeURL(sig)}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                if (ok) Plugin.Log.LogInfo($"[2v2] spawn-confirm OK: {resp}");
                else Plugin.Log.LogWarning($"[2v2] spawn-confirm failed: {resp}");
            }));
        }

        /// <summary>GET /team/series/{id}/state. Polled during the first 20s
        /// after ready_join to detect server-side assembly cancel.</summary>
        public static void PollTeamSeriesState(string seriesId, Action<string, string, int> onResponse)
        {
            if (string.IsNullOrEmpty(seriesId)) return;
            string url = $"{baseUrl}/api/v1/team/series/{seriesId}/state";
            Plugin.Instance.StartCoroutine(GetRequest(url, (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                string status = ExtractJsonString(resp, "status") ?? "";
                string reason = ExtractJsonString(resp, "reason") ?? "";
                int conf = ExtractJsonInt(resp, "confirmations");
                LastSeriesStateStatus = status;
                LastSeriesStateReason = reason;
                LastSeriesStateConfirmations = conf;
                LastSeriesDcGraceSeconds = ExtractJsonInt(resp, "dc_grace_seconds_remaining");
                LastSeriesDcTeamRemaining = ExtractJsonInt(resp, "dc_team_remaining");
                LastSeriesT1Wins = ExtractJsonInt(resp, "t1_series_wins");
                LastSeriesT2Wins = ExtractJsonInt(resp, "t2_series_wins");
                // Codex r2 f8: stamp WHICH series this answer described — the
                // ONLY writer of this field. A late callback for a previous
                // series overwrites the cache above, but ForId then names that
                // previous series, so the assembly loop's ForId==current check
                // rejects it.
                LastSeriesStateForId = seriesId;
                // Aug 8 (Sid): the frozen team-colour stamp rides this poll
                // (empty = vanilla / pre-migration). Publish only while the
                // response still describes the ACTIVE series — a late callback
                // for a previous series must not repaint the new one's stamp.
                if (seriesId == ActiveTeamSeriesId)
                {
                    SeriesTeam1ColorName = ExtractJsonString(resp, "t1_color_name") ?? "";
                    SeriesTeam1ColorHex = ExtractJsonString(resp, "t1_color_hex") ?? "";
                    SeriesTeam2ColorName = ExtractJsonString(resp, "t2_color_name") ?? "";
                    SeriesTeam2ColorHex = ExtractJsonString(resp, "t2_color_hex") ?? "";
                    // Codex r2 f8-adjacent/f6: carry the decided bool with the
                    // colours, and re-publish the room stamp from the poll —
                    // idempotent (PublishSeriesStamp skips identical values
                    // and no-ops on undecided-and-empty), and this is the one
                    // fetch every fighter seat runs, so it reaches rooms the
                    // continuation response (reporter-only) cannot.
                    SeriesColorDecided = ExtractJsonBool(resp, "color_decided");
                    TeamColorIdentity.PublishSeriesStamp(seriesId,
                        SeriesTeam1ColorName, SeriesTeam1ColorHex,
                        SeriesTeam2ColorName, SeriesTeam2ColorHex, SeriesColorDecided);
                }
                onResponse?.Invoke(status, reason, conf);
            }));
        }

        /// <summary>Submit a 2v2 match. Reporter is the lowest Steam ID across
        /// all 4 participants. Builds the 11-field HMAC over
        /// t1a:t1b:t2a:t2b:t1r:t2r:is_ranked:reporter:room_id:winner_team:series_id.</summary>
        /// <summary>Per-slot 2v2 telemetry blob (July 22 item 7). Null slot =
        /// that player's data never reached the reporter (old client).</summary>
        public class TeamTelemetry
        {
            public string fpsTimeline, pingTimeline, hitTimeline, blockTimeline;
            // Aug 7: cumulative damage-dealt CSV, for the DPS hover graph. Must be
            // sampled on the SAME grid as fpsTimeline (the 3s / cap-128 series) —
            // the graph plots its derivative beside the fps chart and a different
            // cadence puts the two on different x-axes. Null/empty = not recorded,
            // which the server stores as NULL so the row draws no graph (#257).
            // NOTE: the FFA report path does NOT read this — FFA carries its own
            // per-entry damage_dealt_timeline; only the 2v2 blob uses it.
            public string damageTimeline;
            public int pingAvg;
            public int bulletsFired, bulletsHit, blocksActivated, blocksSuccessful, keysPressed;
            /// <summary>False when the PEER that produced bulletsFired/bulletsHit
            /// predates the #308 counting fix, so those two numbers mean something
            /// different from what this build means by them.
            ///
            /// Defaults TRUE because every other producer of this struct is the
            /// LOCAL client, whose counters are by definition current-era. Only the
            /// peer-harvest path can set it false.
            ///
            /// When false the two counters and the hit TIMELINE are all sent as
            /// JSON null. Sending 0 instead was the first attempt and it is worse
            /// than sending nothing: the server stores a real zero, which reads as
            /// "fired no shots" rather than "not recorded" (#257's distinction),
            /// and the derived curve would sit beside it still drawn from the old
            /// era's numbers.</summary>
            public bool bulletStatsKnown = true;
            public float activeSeconds;
        }

        private static void AppendTeamTelemetry(StringBuilder sb, string slot, TeamTelemetry t)
        {
            if (t == null) return;
            sb.Append($"\"{slot}_telemetry\":{{");
            sb.Append($"\"fps_timeline\":\"{Escape(ClampTimeline(t.fpsTimeline))}\",");
            sb.Append($"\"ping_timeline\":\"{Escape(ClampTimeline(t.pingTimeline))}\",");
            sb.Append($"\"ping_avg\":{Math.Max(0, Math.Min(30000, t.pingAvg))},");
            sb.Append($"\"hit_timeline\":\"{Escape(ClampTimeline(t.hitTimeline, 1024))}\",");
            sb.Append($"\"block_timeline\":\"{Escape(ClampTimeline(t.blockTimeline, 1024))}\",");
            // Mirrors team_match_telemetry.damage_dealt_timeline (migration 201).
            // An empty string is stored as NULL server-side, so an old/unwired
            // caller costs nothing beyond two bytes on the wire.
            sb.Append($"\"damage_dealt_timeline\":\"{Escape(ClampTimeline(t.damageTimeline, 1024))}\",");
            // null, not 0, when the peer predates the epoch: the server column is `int | None` so "not recorded" survives the wire, and a real 0 would read as "fired no shots".
            sb.Append(t.bulletStatsKnown
                ? $"\"bullets_fired\":{Math.Max(0, t.bulletsFired)},"
                : "\"bullets_fired\":null,");
            // null, not 0, when the peer predates the epoch: the server column is `int | None` so "not recorded" survives the wire, and a real 0 would read as "fired no shots".
            sb.Append(t.bulletStatsKnown
                ? $"\"bullets_hit\":{Math.Max(0, t.bulletsHit)},"
                : "\"bullets_hit\":null,");
            sb.Append($"\"blocks_activated\":{Math.Max(0, t.blocksActivated)},");
            sb.Append($"\"blocks_successful\":{Math.Max(0, t.blocksSuccessful)},");
            sb.Append($"\"keys_pressed\":{Math.Max(0, t.keysPressed)},");
            sb.Append($"\"active_seconds\":{Math.Max(0f, t.activeSeconds).ToString("F1", System.Globalization.CultureInfo.InvariantCulture)}");
            sb.Append("},");
        }

        public static void ReportTeamMatch(
            string seriesId,
            string t1aSteam, string t1aName, List<MatchTracker.CardPickData> t1aCards,
            string t1bSteam, string t1bName, List<MatchTracker.CardPickData> t1bCards,
            string t2aSteam, string t2aName, List<MatchTracker.CardPickData> t2aCards,
            string t2bSteam, string t2bName, List<MatchTracker.CardPickData> t2bCards,
            int t1Rounds, int t2Rounds, int t1Points, int t2Points,
            string photonRoomId, string region, int durationSeconds, DateTime startedAt,
            string reporterSteamId, bool isRanked, int winnerTeam,
            int t1aFps, int t1bFps, int t2aFps, int t2bFps,
            // July 22 item 7 — per-slot telemetry (timelines + counters), same
            // slot ordering as the fps args. Null-safe: absent slots omitted.
            TeamTelemetry t1aTele = null, TeamTelemetry t1bTele = null,
            TeamTelemetry t2aTele = null, TeamTelemetry t2bTele = null,
            // Aug 12 item 1 — per-slot end-of-game BUILD wire strings, same slot
            // ordering as the fps/telemetry args above. Null = not captured
            // (field omitted). ADVISORY: outside the frozen 11-field canonical.
            string t1aEndStats = null, string t1bEndStats = null,
            string t2aEndStats = null, string t2bEndStats = null)
        {
            if (RoomActors.LocalIsSpectator) return;   // spectator: never reports (design §3.5)
            // §2c identity fence: the broadcast account never reports.
            if (BroadcastMode.FenceBlocksFighterPath("report-2v2")) return;
            var sb = new StringBuilder();
            sb.Append("{");
            sb.Append($"\"series_id\":\"{Escape(seriesId)}\",");
            void appendPlayer(string field, string sid, string name, List<MatchTracker.CardPickData> cards, string endStats)
            {
                sb.Append($"\"{field}\":{{\"steam_id\":\"{Escape(sid)}\",\"display_name\":\"{Escape(name)}\",\"cards\":[");
                AppendCards(sb, cards);
                sb.Append("],\"card_offers\":[]");
                AppendEndStats(sb, endStats);
                sb.Append("},");
            }
            appendPlayer("t1a", t1aSteam, t1aName, t1aCards, t1aEndStats);
            appendPlayer("t1b", t1bSteam, t1bName, t1bCards, t1bEndStats);
            appendPlayer("t2a", t2aSteam, t2aName, t2aCards, t2aEndStats);
            appendPlayer("t2b", t2bSteam, t2bName, t2bCards, t2bEndStats);
            sb.Append($"\"t1_rounds_won\":{t1Rounds},");
            sb.Append($"\"t2_rounds_won\":{t2Rounds},");
            sb.Append($"\"t1_points_total\":{t1Points},");
            sb.Append($"\"t2_points_total\":{t2Points},");
            sb.Append($"\"winner_team\":{winnerTeam},");
            sb.Append($"\"photon_room_id\":\"{Escape(photonRoomId)}\",");
            sb.Append($"\"game_version\":\"v{Application.version}\",");
            sb.Append($"\"region\":\"{Escape(region)}\",");
            sb.Append($"\"match_duration\":{durationSeconds},");
            sb.Append($"\"started_at\":\"{startedAt.ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ", System.Globalization.CultureInfo.InvariantCulture)}\",");
            sb.Append($"\"is_ranked\":{(isRanked ? "true" : "false")},");
            sb.Append($"\"reported_by_steam_id\":\"{Escape(reporterSteamId)}\",");
            sb.Append($"\"t1a_fps\":{t1aFps},\"t1b_fps\":{t1bFps},\"t2a_fps\":{t2aFps},\"t2b_fps\":{t2bFps},");
            // July 22 item 7 — per-slot telemetry objects (advisory, NOT in the
            // 11-field HMAC below; that canonical must never change).
            AppendTeamTelemetry(sb, "t1a", t1aTele);
            AppendTeamTelemetry(sb, "t1b", t1bTele);
            AppendTeamTelemetry(sb, "t2a", t2aTele);
            AppendTeamTelemetry(sb, "t2b", t2bTele);

            string canonical =
                $"{t1aSteam}:{t1bSteam}:{t2aSteam}:{t2bSteam}:" +
                $"{t1Rounds}:{t2Rounds}:" +
                $"{(isRanked ? "true" : "false")}:{reporterSteamId}:" +
                $"{photonRoomId ?? ""}:{winnerTeam}:{seriesId}";
            string sig = ComputeHmacHex(canonical);
            sb.Append($"\"hmac_signature\":\"{sig}\"");
            sb.Append("}");

            string json = sb.ToString();
            Plugin.Log.LogInfo($"Reporting 2v2 match (series={seriesId}, winner=T{winnerTeam}, {t1Rounds}-{t2Rounds})...");
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                $"{baseUrl}/api/v1/team/matches", json,
                (success, response) =>
                {
                    if (success)
                    {
                        Plugin.Log.LogInfo($"2v2 match reported: {response}");
                        RefreshAchievementsAfterReport();
                        string sStatus = ExtractJsonString(response, "series_status");
                        string sScore = ExtractJsonString(response, "series_score");
                        if (sStatus == "completed")
                        {
                            CompetitiveUI.ShowNotification(I18n.TrF("Series complete: {0}", sScore), Color.green, 6f);
                            // Tally the series result into the Session Info panel
                            // (2v2 row). series_score is from the reporter's team
                            // perspective, e.g. "2-1" if the reporter's team won.
                            try
                            {
                                bool seriesWon = false;
                                if (!string.IsNullOrEmpty(sScore))
                                {
                                    var sp = sScore.Split('-');
                                    if (sp.Length == 2 && int.TryParse(sp[0], out int sw) && int.TryParse(sp[1], out int sl))
                                        seriesWon = sw > sl;
                                }
                                // The reporter is the lowest-Steam-ID participant.
                                // For OTHER team members the report still lands but
                                // the local report-callback only fires on the
                                // reporter's client. Fan out via team-stats refresh
                                // below which all 4 will pick up.
                                GameStateWatcher.RecordSessionTeamSeries(seriesWon);
                            }
                            catch (Exception ex) { Plugin.Log.LogWarning($"[2v2] session tally failed: {ex.Message}"); }
                            ActiveTeamSeriesId = null;
                            Plugin.ClearPending2v2Slot();
                        }
                        else if (!string.IsNullOrEmpty(sScore))
                        {
                            CompetitiveUI.ShowNotification(I18n.TrF("Series: {0}", sScore), new Color(0.6f, 0.8f, 1f), 4f);
                        }
                        // Mid-series rebalance — DORMANT compatibility scaffolding:
                        // since Aug 23 the server is proposal-only (it logs the
                        // swap it would have made and always sends null here),
                        // because this client half — the actual TeamID + spawn +
                        // body-color mutation — never shipped. Parser kept so an
                        // eventual server re-enable degrades to today's toast.
                        try
                        {
                            int rIdx = response.IndexOf("\"rebalance_assignments\":");
                            if (rIdx >= 0)
                            {
                                int oStart = response.IndexOf('{', rIdx);
                                int oEnd = oStart >= 0 ? FindMatchingBrace(response, oStart) : -1;
                                if (oStart > 0 && oEnd > oStart)
                                {
                                    string slice = response.Substring(oStart + 1, oEnd - oStart - 1);
                                    if (!string.IsNullOrEmpty(slice.Trim()))
                                    {
                                        Plugin.Log.LogInfo($"[2v2-REBALANCE] server says swap teams next match: {slice}");
                                        CompetitiveUI.ShowNotification("Teams will rebalance next match!", new Color(1f, 0.8f, 0.4f), 5f);
                                    }
                                }
                            }
                        }
                        catch (Exception rex) { Plugin.Log.LogWarning($"[2v2-REBALANCE] parse: {rex.Message}"); }
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"2v2 match report failed: {response}");
                        // Bug #65 family: don't lose the game to a transient outage.
                        // team_matches' 5-column unique constraint makes replays safe.
                        EnqueueFailedReport($"{baseUrl}/api/v1/team/matches", json);
                    }
                },
                maxRetries: 3, retryDelay: 2f
            ));
        }

        public static void ResetTeamQueue()
        {
            CurrentTeamQueueState = TeamQueueState.Idle;
            IsTeamQueuePolling = false;
            LastTeamPollData = null;
        }

