        public static List<TeamSeriesPagedEntry> CachedTeamSeriesPaged { get; private set; } = new List<TeamSeriesPagedEntry>();
        public static int CachedTeamSeriesTotal { get; private set; } = 0;
        public static int CachedTeamSeriesPage { get; private set; } = 0;
        public static int CachedTeamSeriesPageSize { get; private set; } = 3;
        public static int CachedTeamSeriesTotalPages { get; private set; } = 0;

        public static void FetchAllSeriesPaged(int page = 0, int pageSize = 3)
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/all-series-paged?page={page}&page_size={pageSize}",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try { ParseAllSeriesPaged(response, page, pageSize); NativeUI.MarkDirty(); }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[TEAM-SERIES-PAGED] parse: {ex.Message}"); }
                }
            ));
        }

        private static void ParseAllSeriesPaged(string response, int reqPage, int reqPageSize)
        {
            var list = ParseTeamSeriesPagedList(response, out bool shapeOk);
            if (!shapeOk) { CachedTeamSeriesPaged = list; return; }
            CachedTeamSeriesPaged = list;
            CachedTeamSeriesTotal = ExtractJsonInt(response, "total");
            CachedTeamSeriesPage = reqPage;
            CachedTeamSeriesPageSize = reqPageSize;
            CachedTeamSeriesTotalPages = ExtractJsonInt(response, "total_pages");
        }

        /// <summary>Shared rich-series list parser for /team/all-series-paged
        /// responses — used by the F5 cache path above AND the report-private
        /// fetch (R1 f12 reconciliation). shapeOk=false means the "series"
        /// array was absent/unbalanced (a shape failure, not "empty").</summary>
        private static List<TeamSeriesPagedEntry> ParseTeamSeriesPagedList(string response, out bool shapeOk)
        {
            // R1 f13 (#156): every enclosing array/object here wraps regions
            // carrying user-authored display names and card strings — a name
            // like "A]" or "}x" derails a plain depth counter, truncating the
            // series list or yielding hybrid entries. String-aware slicing
            // throughout; fields extracted are unchanged.
            var list = new List<TeamSeriesPagedEntry>();
            shapeOk = false;
            int arrStart = FindJsonArrayStartStringAware(response, "series");
            int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(response, arrStart) : -1;
            if (arrStart < 0 || arrEnd < 0) return list;
            shapeOk = true;
            string slice = response.Substring(arrStart + 1, arrEnd - arrStart - 1);
            foreach (string obj in SliceTopLevelObjects(slice))
            {
                var e = new TeamSeriesPagedEntry
                {
                    series_id = ExtractJsonString(obj, "series_id"),
                    completed_at = ExtractJsonString(obj, "completed_at"),
                    winner_team = ExtractJsonInt(obj, "winner_team"),
                    t1_series_wins = ExtractJsonInt(obj, "t1_series_wins"),
                    t2_series_wins = ExtractJsonInt(obj, "t2_series_wins"),
                    t1_color_name = ExtractJsonString(obj, "t1_color_name") ?? "",
                    t1_color_hex = ExtractJsonString(obj, "t1_color_hex") ?? "",
                    t2_color_name = ExtractJsonString(obj, "t2_color_name") ?? "",
                    t2_color_hex = ExtractJsonString(obj, "t2_color_hex") ?? "",
                    color_decided = ExtractJsonBool(obj, "color_decided"),
                    t1a = ParseSeriesSlot(obj, "t1a"),
                    t1b = ParseSeriesSlot(obj, "t1b"),
                    t2a = ParseSeriesSlot(obj, "t2a"),
                    t2b = ParseSeriesSlot(obj, "t2b"),
                    matches = ParseSeriesMatches(obj),
                };
                list.Add(e);
            }
            return list;
        }

        private static TeamSeriesSlot ParseSeriesSlot(string seriesObj, string slotKey)
        {
            // Find "<slotKey>": { ... }  inside the series object. The key
            // needle `"t1a":` cannot be forged inside a string literal (its
            // interior quote would have to be escaped), but the slot object
            // BODY carries names/titles, so the brace match must be
            // string-aware (R1 f13, #156).
            int kIdx = seriesObj.IndexOf($"\"{slotKey}\":");
            if (kIdx < 0) return new TeamSeriesSlot();
            int oStart = seriesObj.IndexOf('{', kIdx);
            int oEnd = oStart >= 0 ? FindMatchingBraceStringAware(seriesObj, oStart) : -1;
            if (oStart < 0 || oEnd < 0) return new TeamSeriesSlot();
            string s = seriesObj.Substring(oStart, oEnd - oStart + 1);
            return new TeamSeriesSlot
            {
                steam_id = ExtractJsonString(s, "steam_id"),
                name = ExtractJsonString(s, "name"),
                title = ExtractJsonString(s, "title"),
                title_color = ExtractJsonString(s, "title_color"),
                rating = (int)ExtractJsonFloat(s, "rating"),
                rating_change = ExtractJsonFloat(s, "rating_change"),
                gold_earned = ExtractJsonInt(s, "gold_earned"),
                xp_earned = ExtractJsonInt(s, "xp_earned"),
            };
        }

        private static List<TeamSeriesMatch> ParseSeriesMatches(string seriesObj)
        {
            var list = new List<TeamSeriesMatch>();
            // R1 f13 (#156): match objects carry card names + telemetry keyed by
            // players, so the array and object boundaries must be string-aware.
            int mIdx = seriesObj.IndexOf("\"matches\":");
            if (mIdx < 0) return list;
            int aStart = seriesObj.IndexOf('[', mIdx);
            int aEnd = aStart >= 0 ? FindMatchingBracketStringAware(seriesObj, aStart) : -1;
            if (aStart < 0 || aEnd < 0) return list;
            string slice = seriesObj.Substring(aStart + 1, aEnd - aStart - 1);
            foreach (string m in SliceTopLevelObjects(slice))
            {
                var entry = new TeamSeriesMatch
                {
                    match_id = ExtractJsonString(m, "match_id"),
                    ended_at = ExtractJsonString(m, "ended_at"),
                    t1_rounds_won = ExtractJsonInt(m, "t1_rounds_won"),
                    t2_rounds_won = ExtractJsonInt(m, "t2_rounds_won"),
                    t1_points_total = ExtractJsonInt(m, "t1_points_total"),
                    t2_points_total = ExtractJsonInt(m, "t2_points_total"),
                    duration_seconds = ExtractJsonInt(m, "duration_seconds"),
                };
                // July 22 item 7: fps_by_player {sid: int} — string-aware slice
                // (sits beside user-authored card names; learning #156).
                int fIdx = m.IndexOf("\"fps_by_player\":");
                if (fIdx >= 0)
                {
                    int fS = m.IndexOf('{', fIdx);
                    int fE = fS >= 0 ? FindMatchingBraceStringAware(m, fS) : -1;
                    if (fS >= 0 && fE > fS)
                    {
                        string fb = m.Substring(fS + 1, fE - fS - 1);
                        int fc = 0;
                        while (fc < fb.Length)
                        {
                            int kS = fb.IndexOf('"', fc);
                            if (kS < 0) break;
                            int kE = fb.IndexOf('"', kS + 1);
                            if (kE < 0) break;
                            string sid = fb.Substring(kS + 1, kE - kS - 1);
                            int col = fb.IndexOf(':', kE);
                            if (col < 0) break;
                            int vEnd = col + 1;
                            while (vEnd < fb.Length && (char.IsDigit(fb[vEnd]) || fb[vEnd] == ' ')) vEnd++;
                            int fv;
                            if (int.TryParse(fb.Substring(col + 1, vEnd - col - 1).Trim(), out fv))
                                entry.fps_by_player[sid] = fv;
                            fc = vEnd + 1;
                        }
                    }
                }
                // telemetry_by_player {sid: {fields...}}
                int tIdx = m.IndexOf("\"telemetry_by_player\":");
                if (tIdx >= 0)
                {
                    int tS = m.IndexOf('{', tIdx);
                    int tE = tS >= 0 ? FindMatchingBraceStringAware(m, tS) : -1;
                    if (tS >= 0 && tE > tS)
                    {
                        string tb = m.Substring(tS + 1, tE - tS - 1);
                        int tc = 0;
                        while (tc < tb.Length)
                        {
                            int kS = tb.IndexOf('"', tc);
                            if (kS < 0) break;
                            int kE = tb.IndexOf('"', kS + 1);
                            if (kE < 0) break;
                            string sid = tb.Substring(kS + 1, kE - kS - 1);
                            int oS = tb.IndexOf('{', kE);
                            if (oS < 0) break;
                            int oE = FindMatchingBraceStringAware(tb, oS);
                            if (oE < 0) break;
                            string ob = tb.Substring(oS, oE - oS + 1);
                            entry.telemetry_by_player[sid] = new TeamPlayerTele
                            {
                                fps_timeline = ExtractJsonString(ob, "fps_timeline"),
                                ping_timeline = ExtractJsonString(ob, "ping_timeline"),
                                hit_timeline = ExtractJsonString(ob, "hit_timeline"),
                                block_timeline = ExtractJsonString(ob, "block_timeline"),
                                damage_dealt_timeline = ExtractJsonString(ob, "damage_dealt_timeline"),
                                ping_avg = ExtractJsonInt(ob, "ping_avg"),
                                bullets_fired = ExtractJsonInt(ob, "bullets_fired"),
                                bullets_hit = ExtractJsonInt(ob, "bullets_hit"),
                                blocks_activated = ExtractJsonInt(ob, "blocks_activated"),
                                blocks_successful = ExtractJsonInt(ob, "blocks_successful"),
                            };
                            tc = oE + 1;
                        }
                    }
                }
                // cards_by_player parser (same shape as TeamMatchHistoryEntry).
                // R1 f13: string-aware braces — the map's values are card-name
                // arrays, i.e. exactly the region a plain counter dies in.
                int cIdx = m.IndexOf("\"cards_by_player\":");
                if (cIdx >= 0)
                {
                    int cbStart = m.IndexOf('{', cIdx);
                    int cbEnd = cbStart >= 0 ? FindMatchingBraceStringAware(m, cbStart) : -1;
                    if (cbStart >= 0 && cbEnd > cbStart)
                    {
                        string cbSlice = m.Substring(cbStart + 1, cbEnd - cbStart - 1);
                        int cursor = 0;
                        while (cursor < cbSlice.Length)
                        {
                            int kS = cbSlice.IndexOf('"', cursor);
                            if (kS < 0) break;
                            int kE = cbSlice.IndexOf('"', kS + 1);
                            if (kE < 0) break;
                            string sid = cbSlice.Substring(kS + 1, kE - kS - 1);
                            int aS2 = cbSlice.IndexOf('[', kE);
                            int aE2 = aS2 >= 0 ? FindMatchingBracketStringAware(cbSlice, aS2) : -1;
                            if (aS2 < 0 || aE2 < 0) break;
                            string aSlice = cbSlice.Substring(aS2 + 1, aE2 - aS2 - 1);
                            // Cards are bare strings here (the new endpoint flattens them).
                            var cards = new List<string>();
                            int sCur = 0;
                            while (sCur < aSlice.Length)
                            {
                                int qs = aSlice.IndexOf('"', sCur);
                                if (qs < 0) break;
                                int qe = aSlice.IndexOf('"', qs + 1);
                                if (qe < 0) break;
                                cards.Add(aSlice.Substring(qs + 1, qe - qs - 1));
                                sCur = qe + 1;
                            }
                            entry.cards_by_player[sid] = cards;
                            cursor = aE2 + 1;
                        }
                    }
                }
                // Aug 12 item 1 — end_stats_by_player {sid: "1|…"}. Reuses the
                // shared string-aware reader rather than a fourth hand-rolled
                // loop: this object sits in the same blob as user-authored card
                // names, so a plain depth counter is not safe here (#156).
                entry.end_stats_by_player = ParseSteamStringMap(m, "end_stats_by_player");
                list.Add(entry);
            }
            return list;
        }

        public class TeamMatchHistoryEntry
        {
            public string match_id, series_id, ended_at;
            public bool won;
            public int my_team;
            public string t1a_steam_id, t1a_name, t1b_steam_id, t1b_name;
            public string t2a_steam_id, t2a_name, t2b_steam_id, t2b_name;
            public int t1_rounds_won, t2_rounds_won;
            public int t1_points_total, t2_points_total;
            public string series_score;
            public float series_rating_change;
            // FPS keyed by Steam ID; absent = no data
            public Dictionary<string, int> fps_by_player = new Dictionary<string, int>();
            // Card names picked, keyed by Steam ID. Drives the per-match cards
            // section in the F5 2v2 history UI ("Sid+Sid2 took: Shields Up,
            // Big Bullet  vs  Sid3+Sid4 took: Dazzle, Cold Bullets").
            public Dictionary<string, List<string>> cards_by_player = new Dictionary<string, List<string>>();
        }
