        [Serializable]
        public class TeamStatsData
        {
            public string steam_id, display_name;
            public float rating, rating_deviation, peak_rating;
            public int completed_series, series_wins, series_losses;
            public float series_win_rate;
            public int match_wins, match_losses, current_streak;
        }
        public static TeamStatsData CachedTeamStats { get; private set; }

        public static void FetchTeamStats(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/players/{steamId}/team-stats",
                (success, response) =>
                {
                    if (!success) return;
                    try
                    {
                        var d = new TeamStatsData
                        {
                            steam_id = ExtractJsonString(response, "steam_id"),
                            display_name = ExtractJsonString(response, "display_name"),
                            rating = ExtractJsonFloat(response, "rating"),
                            rating_deviation = ExtractJsonFloat(response, "rating_deviation"),
                            peak_rating = ExtractJsonFloat(response, "peak_rating"),
                            completed_series = ExtractJsonInt(response, "completed_series"),
                            series_wins = ExtractJsonInt(response, "series_wins"),
                            series_losses = ExtractJsonInt(response, "series_losses"),
                            series_win_rate = ExtractJsonFloat(response, "series_win_rate"),
                            match_wins = ExtractJsonInt(response, "match_wins"),
                            match_losses = ExtractJsonInt(response, "match_losses"),
                            current_streak = ExtractJsonInt(response, "current_streak"),
                        };
                        CachedTeamStats = d;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex) { Plugin.Log.LogError($"[TEAM-STATS] parse: {ex.Message}"); }
                }
            ));
        }

        public static void FetchTeamMatchHistory(string steamId, int limit = 50)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/players/{steamId}/team-matches?limit={limit}",
                (success, response) =>
                {
                    if (!success) return;
                    try
                    {
                        var entries = new List<TeamMatchHistoryEntry>();
                        if (string.IsNullOrEmpty(response) || response.Trim() == "[]")
                        {
                            CachedTeamMatchHistory = entries;
                            NativeUI.MarkDirty();
                            return;
                        }
                        // #156: each match object carries four display names, so
                        // the old '"match_id"' token split + naive brace/bracket
                        // matchers broke on a name containing '{' '[' or '"'.
                        // String-aware slice over the top-level array instead.
                        int tArr = response.IndexOf('[');
                        int tEnd = tArr >= 0 ? FindMatchingBracketStringAware(response, tArr) : -1;
                        if (tEnd < 0) { CachedTeamMatchHistory = entries; NativeUI.MarkDirty(); return; }
                        foreach (var chunk in SliceTopLevelObjects(response.Substring(tArr, tEnd - tArr + 1)))
                        {
                            var e = new TeamMatchHistoryEntry
                            {
                                match_id = ExtractJsonString(chunk, "match_id"),
                                series_id = ExtractJsonString(chunk, "series_id"),
                                ended_at = ExtractJsonString(chunk, "ended_at"),
                                won = chunk.Contains("\"won\":true"),
                                my_team = ExtractJsonInt(chunk, "my_team"),
                                t1a_steam_id = ExtractJsonString(chunk, "t1a_steam_id"),
                                t1a_name = ExtractJsonString(chunk, "t1a_name"),
                                t1b_steam_id = ExtractJsonString(chunk, "t1b_steam_id"),
                                t1b_name = ExtractJsonString(chunk, "t1b_name"),
                                t2a_steam_id = ExtractJsonString(chunk, "t2a_steam_id"),
                                t2a_name = ExtractJsonString(chunk, "t2a_name"),
                                t2b_steam_id = ExtractJsonString(chunk, "t2b_steam_id"),
                                t2b_name = ExtractJsonString(chunk, "t2b_name"),
                                t1_rounds_won = ExtractJsonInt(chunk, "t1_rounds_won"),
                                t2_rounds_won = ExtractJsonInt(chunk, "t2_rounds_won"),
                                t1_points_total = ExtractJsonInt(chunk, "t1_points_total"),
                                t2_points_total = ExtractJsonInt(chunk, "t2_points_total"),
                                series_score = ExtractJsonString(chunk, "series_score"),
                                series_rating_change = ExtractJsonFloat(chunk, "series_rating_change"),
                            };
                            // Parse cards_by_player: dict keyed by steam_id, value
                            // is a list of card-objects each with a card_name.
                            try
                            {
                                int cStart = chunk.IndexOf("\"cards_by_player\"");
                                if (cStart >= 0)
                                {
                                    int oStart = chunk.IndexOf('{', cStart);
                                    int oEnd = FindMatchingBraceStringAware(chunk, oStart);
                                    if (oStart >= 0 && oEnd > oStart)
                                    {
                                        string slice = chunk.Substring(oStart + 1, oEnd - oStart - 1);
                                        int cursor = 0;
                                        while (cursor < slice.Length)
                                        {
                                            // Keys are server-generated steam ids
                                            // (digits) — the plain quote scan is
                                            // safe for the KEY, but the value
                                            // arrays get string-aware slicing.
                                            int kS = slice.IndexOf('"', cursor);
                                            if (kS < 0) break;
                                            int kE = slice.IndexOf('"', kS + 1);
                                            if (kE < 0) break;
                                            string sid = slice.Substring(kS + 1, kE - kS - 1);
                                            int aS = slice.IndexOf('[', kE);
                                            int aE = aS >= 0 ? FindMatchingBracketStringAware(slice, aS) : -1;
                                            if (aS < 0 || aE < 0) break;
                                            var cardList = new List<string>();
                                            foreach (var objStr in SliceTopLevelObjects(slice.Substring(aS, aE - aS + 1)))
                                            {
                                                string cn = ExtractJsonString(objStr, "card_name");
                                                if (!string.IsNullOrEmpty(cn)) cardList.Add(cn);
                                            }
                                            e.cards_by_player[sid] = cardList;
                                            cursor = aE + 1;
                                        }
                                    }
                                }
                            }
                            catch { }
                            entries.Add(e);
                        }
                        CachedTeamMatchHistory = entries;
                        Plugin.Log.LogInfo($"[TEAM-HIST] loaded {entries.Count} 2v2 matches");
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex)
                    {
                        Plugin.Log.LogError($"[TEAM-HIST] parse: {ex.Message}");
                    }
                }
            ));
        }

        public static void FetchTeamLeaderboard(int limit = 200, string sortBy = "rating")
        {
            CachedTeamLeaderboardSort = sortBy;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/team/leaderboard?limit={limit}&sort_by={sortBy}",
                (success, response) =>
                {
                    if (!success) return;
                    try
                    {
                        var entries = new List<TeamLeaderboardEntry>();
                        var parts = response.Split(new[] { "\"rank\":" }, StringSplitOptions.None);
                        for (int i = 1; i < parts.Length; i++)
                        {
                            var chunk = parts[i];
                            int rankVal = 0; try { int comma = chunk.IndexOf(','); rankVal = int.Parse(chunk.Substring(0, comma)); } catch { }
                            entries.Add(new TeamLeaderboardEntry
                            {
                                rank = rankVal,
                                steam_id = ExtractJsonString(chunk, "steam_id"),
                                display_name = ExtractJsonString(chunk, "display_name"),
                                rating = ExtractJsonInt(chunk, "rating"),
                                rd = ExtractJsonInt(chunk, "rd"),
                                // Safe beside "rating" — see the FFA board's
                                // note: the reader matches the QUOTED key.
                                peak_rating = ExtractJsonInt(chunk, "peak_rating"),
                                completed_series = ExtractJsonInt(chunk, "completed_series"),
                                series_wins = ExtractJsonInt(chunk, "series_wins"),
                                series_losses = ExtractJsonInt(chunk, "series_losses"),
                                win_rate = ExtractJsonFloat(chunk, "win_rate"),
                                level = ExtractJsonInt(chunk, "level"),
                                title = ExtractJsonString(chunk, "title"),
                                title_color = ExtractJsonString(chunk, "title_color"),
                                avg_teammate_elo = ExtractJsonInt(chunk, "avg_teammate_elo"),
                                team_gold_earned = ExtractJsonInt(chunk, "team_gold_earned"),
                                team_xp_earned = ExtractJsonInt(chunk, "team_xp_earned"),
                            });
                        }
                        CachedTeamLeaderboard = entries;
                        CachedTeamLeaderboardTotal = ExtractJsonInt(response, "total_players");
                        NativeUI.MarkDirty();
                        Plugin.Log.LogInfo($"[TEAM-LB] Loaded {entries.Count} 2v2 ranked players");
                    }
                    catch (Exception ex)
                    {
                        Plugin.Log.LogError($"[TEAM-LB] parse error: {ex.Message}");
                    }
                }
            ));
        }

        // ══ 1v2 (solo vs duo) — queue + leaderboard + report ══════════════
        // Server is UNSCORED at launch; the client mirrors that with an
        // "Unranked (beta)" banner. Queue is a consent lobby (no Elo band).
        public class OvtLeaderboardEntry
        {
            public int rank; public string steam_id, display_name;
            public int games_played, wins, losses, solo_games, duo_games, level;
            // July 22 item 3: W/L split by role (as solo vs as duo half).
            public int solo_wins, solo_losses, duo_wins, duo_losses;
            public float win_rate;
            // Split-board pass: server-resolved title + newest ovt_match time
            // (iso string, "" when the server omits it / sends null).
            public string title, title_color, last_played;
        }
        public static List<OvtLeaderboardEntry> CachedOvtLeaderboard = null;
        public static int CachedOvtLeaderboardTotal = 0;
        // role=solo / role=duo boards — the server re-scopes games/wins/losses/
        // win_rate to the role; the combined cache above stays untouched so
        // legacy consumers keep working.
        public static List<OvtLeaderboardEntry> CachedOvtLeaderboardSolo = null;
        public static List<OvtLeaderboardEntry> CachedOvtLeaderboardDuo = null;

        // Live queue state (drives the 1v2 tab + auto room-join).
        public static string OvtQueueStatus = "";        // ""/searching/ready_join/leaving
        public static int OvtQueueCount = 0;
        public static string ActiveOvt1v2SeriesId = null;
        public static int OvtMySide = 0;                 // 1 solo, 2 duo
        public static bool OvtSoloExtraPick = false;
        public static bool IsOvtQueuePolling = false;
        private static float _ovtLastPollAt = -999f;
        // Locked lineup (set at ready_join) — the tab renders "Solo vs A + B".
        public static string OvtLockedSoloName = null;
        public static List<TeamQueueMember> OvtLockedDuo = null;

        // Who's-in-the-lobby snapshot from /ovt/queue/list (2v2-parity panel).
        public class OvtQueueListEntry
        {
            public string steam_id, display_name, status, region;
            public int rating_1v1, rating_2v2, preferred_side, side_assigned, wait_seconds;
            public bool solo_extra_pick;
        }
        public static List<OvtQueueListEntry> CachedOvtQueueList = null;
        private static float _ovtListLastAt = -999f;

        // Last-used join preferences — lets the not_in_queue auto-rejoin (a
        // server prune after an API gap, e.g. a backend redeploy) restore the
        // exact queue entry the player asked for.
        private static int _ovtLastPreferredSide = 0;
        private static bool _ovtLastSoloExtraPick = false;
        // TRUE only after a successful /ovt/queue/join this session — gates
        // the not_in_queue auto-rejoin so polling armed by the v1.37 lobby
        // handoff can never conscript the player into the consent queue.
        private static bool _ovtConsentQueueJoined = false;
        private static float _ovtLastAutoRejoinAt = -999f;
        private static float _ovtLeavingSince = -999f;
        private static int ovtGen = 0;  // lifecycle generation — see queueGen

        public static void OvtJoinQueue(int preferredSide, bool soloExtraPick)
        {
            if (SpectatorBlocksQueue()) return;
            NoteQueueRequestInFlight();   // r3: WATCH is blocked for the whole join round-trip   // design §3.1
            // No loop-breaker reset on join — see FfaJoinQueue's comment
            // (Codex sitting-over review find 2).
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            // v1.37 host lobbies: a queue join from a held open seat would
            // clobber the seat's row server-side. Leave first, explicitly.
            if (!string.IsNullOrEmpty(OvtLobby.OpenLobbyId))
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Leave your custom 1v2 lobby first."), new Color(1f, 0.7f, 0.3f), 5f);
                return;
            }
            // Codex r2 f3: an unresolved leave (lobby or converted-seat) must
            // fully land before a NEW queue row exists for it to race.
            if (HostLobbyClient.HasPendingLeave("ovt"))
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Finishing your previous leave first..."), new Color(1f, 0.6f, 0.2f), 4f);
                return;
            }
            // Suppress joining while a leave retry is in flight (same rationale
            // as JoinQueue); force-recover past the safety timeout.
            if (OvtQueueStatus == "leaving")
            {
                if (Time.realtimeSinceStartup - _ovtLeavingSince < LEAVE_STUCK_TIMEOUT)
                {
                    CompetitiveUI.ShowNotification("Still leaving the 1v2 queue — try again in a moment.", new Color(1f, 0.6f, 0.2f));
                    return;
                }
                OvtQueueStatus = "";
            }
            // The 1v2 queue has NO ready-up consent step (joining IS consent,
            // learning #127) — so unlike 1v1/2v2, a lock fires whenever a 3rd
            // player shows up, possibly hours later. Queueing from inside a
            // live game would let that lock yank the player out mid-match
            // (DC against them + a free win for their opponent). Block it.
            // OfflineMode is exempt: PhotonNetwork.InRoom lingers true at the
            // menu after Sandbox (learning #122).
            bool inOnlineRoom = false;
            try { inOnlineRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode; } catch { }
            if (inOnlineRoom)
            {
                CompetitiveUI.ShowNotification("Finish or leave your current game before joining the 1v2 queue.", new Color(1f, 0.7f, 0.3f), 5f);
                return;
            }
            _ovtLastPreferredSide = preferredSide;
            _ovtLastSoloExtraPick = soloExtraPick;
            string name = Escape(MatchTracker.LocalDisplayName ?? "Player");
            // Region rides along like 2v2's JoinTeamQueue — without it the
            // server pins every 1v2 room to "us" even for an all-EU trio.
            string region = "";
            try { region = PhotonNetwork.CloudRegion?.Replace("/*", "") ?? ""; } catch { region = ""; }
            // F2 (Codex r3): last gate before the send — one enrollment in
            // flight per mode, shared with the hosted Create/Join paths.
            if (!EnrollGateBegin("ovt")) return;
            string body = $"{{\"steam_id\":\"{sid}\",\"display_name\":\"{name}\",\"region\":\"{Escape(region)}\"," +
                          $"\"preferred_side\":{preferredSide},\"solo_extra_pick\":{(soloExtraPick ? "true" : "false")}}}";
            int gen = ++ovtGen;
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ovt/queue/join", body, (ok, resp) =>
            {
                // F2: release the latch BEFORE the gen check — a stale ack
                // must still free the mode for the next enrollment.
                EnrollGateEnd("ovt");
                if (gen != ovtGen) { Plugin.Log.LogInfo("[1v2] stale join ack ignored (lifecycle moved on)"); return; }
                if (ok)
                {
                    // The not_in_queue auto-rejoin may only restore a consent
                    // queue the player actually ENTERED this session — polling
                    // armed by the v1.37 lobby handoff must never conscript
                    // them into the queue on a bare not_in_queue (#238).
                    _ovtConsentQueueJoined = true;
                    IsOvtQueuePolling = true; OvtQueueStatus = "searching"; UpdateOvtQueueList(force: true); NativeUI.MarkDirty();
                }
                else Plugin.Log.LogWarning($"[1v2] join failed: {resp}");
            }));
        }

        public static void OvtLeaveQueue(string cause = "")
        {
            string sid = MatchTracker.LocalSteamId;
            if (OvtQueueStatus == "leaving") return; // leave already in flight
            // F3 (Codex r3): capture the series incarnation BEFORE any local
            // clear — this legacy public path used to null ActiveOvt1v2SeriesId
            // first and then build an UNFENCED leave URL, so a delayed retry
            // could tear down a NEWER enrollment (HostLobbyClient's
            // DirectQueueLeave already fences). The id clears in the RESPONSE
            // handler (#249); the stuck-Leaving watchdog in TickLeaveRecovery
            // clears it if the callback dies with its coroutine host.
            string fenceSeriesId = ActiveOvt1v2SeriesId;
            // Eager disarm stays: polling/lineup/pending-slot are the "stop
            // acting on it" half and must not survive into the leave window
            // (a lingering pending slot would still auto-join the ovt room).
            IsOvtQueuePolling = false; OvtQueueCount = 0;
            OvtLockedSoloName = null; OvtLockedDuo = null;
            Plugin.ClearPendingOvtSlot();
            if (string.IsNullOrEmpty(sid) || sid == "unknown")
            {
                // No request can be sent — nothing to fence; local-only reset.
                ActiveOvt1v2SeriesId = null;
                OvtQueueStatus = "";
                return;
            }
            // "leaving" holds until the server confirms — a failed leave with
            // local state already cleared strands our row (and any husk lock)
            // server-side, ghost-locking the other two until the 75s janitor
            // (review finding). Idempotent request; "" finalized only
            // in the callback.
            int gen = ++ovtGen;
            OvtQueueStatus = "leaving";
            _ovtLeavingSince = Time.realtimeSinceStartup;
            NativeUI.MarkDirty();
            string leaveUrl = $"{baseUrl}/api/v1/ovt/queue/leave?steam_id={UnityWebRequest.EscapeURL(sid)}"
                + (string.IsNullOrEmpty(cause) ? "" : $"&cause={UnityWebRequest.EscapeURL(cause)}");
            if (!string.IsNullOrEmpty(fenceSeriesId))
                leaveUrl += $"&expected_series_id={UnityWebRequest.EscapeURL(fenceSeriesId)}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                leaveUrl, "",
                (ok, resp) =>
                {
                    if (gen != ovtGen) return;  // watchdog recovered / new lifecycle
                    if (ok)
                    {
                        // {"stale":true} = the row carries a NEWER series than
                        // the fenced one — that incarnation is already gone.
                        if (ExtractJsonBool(resp ?? "", "stale"))
                            Plugin.Log.LogInfo("[1v2] fenced leave hit a newer incarnation — old seat already gone");
                        else
                            Plugin.Log.LogInfo("[1v2] Left 1v2 queue");
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[1v2] Leave failed after retries: {resp} — server will prune the stale row");
                        CompetitiveUI.ShowNotification("Couldn't confirm 1v2 queue leave — the server will clear you shortly.", new Color(1f, 0.6f, 0.2f), 5f);
                    }
                    // F3/#249: series belief clears on the RESPONSE, both
                    // outcomes — guarded so a NEWER series adopted mid-leave
                    // is never wiped by this older leave's ack.
                    if (string.Equals(ActiveOvt1v2SeriesId, fenceSeriesId, StringComparison.Ordinal))
                        ActiveOvt1v2SeriesId = null;
                    if (OvtQueueStatus == "leaving") OvtQueueStatus = "";
                    UpdateOvtQueueList(force: true);
                    NativeUI.MarkDirty();
                },
                maxRetries: 3, retryDelay: 2f));
        }

        /// <summary>Throttled queue poll. Ticked from BOTH the plugin-level
        /// poll loop (so ready_join lands with the F5 menu closed) and the 1v2
        /// tab ticker — timestamp throttle keeps the double call site at one
        /// request per 2s. On ready_join: computes our slot, publishes the
        /// pre-join Photon props, and joins the ovt_ room via the same
        /// SetPendingRoom path 2v2 uses.</summary>
        public static void UpdateOvtQueuePoll(bool force)
        {
            if (!IsOvtQueuePolling) return;
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            if (!force && Time.unscaledTime - _ovtLastPollAt < 2f) return;
            _ovtLastPollAt = Time.unscaledTime;
            int gen = ovtGen;
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ovt/queue/poll/{sid}", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                if (!IsOvtQueuePolling) return;   // left/locked while the request was in flight
                if (gen != ovtGen) return;        // stale lifecycle (Codex verify finding 4)
                string status = ExtractJsonString(resp, "status") ?? "";
                OvtQueueStatus = status;
                OvtQueueCount = ExtractJsonInt(resp, "queue_count");
                if (status == "ready_join")
                {
                    // Consent guard: with no ready-up step, a lock can land
                    // while the player is mid-game in another mode (queued,
                    // then went to play something — the join guard blocks
                    // queueing FROM a room, but a room can be entered after
                    // queueing). Auto-joining would force-leave that live
                    // game and record a DC against them. Decline instead:
                    // leaving the queue dissolves the lock server-side so the
                    // other two go back to searching immediately.
                    bool busyInRoom = false;
                    try { busyInRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode; } catch { }
                    if (busyInRoom)
                    {
                        Plugin.Log.LogWarning("[1v2] ready_join landed while in another room — declining (leaving 1v2 queue)");
                        OvtLeaveQueue();
                        CompetitiveUI.ShowNotification("1v2 match found, but you're in a game — removed from the 1v2 queue.", new Color(1f, 0.7f, 0.3f), 7f);
                        NativeUI.MarkDirty();
                        return;
                    }
                    IsOvtQueuePolling = false;
                    ActiveOvt1v2SeriesId = ExtractJsonString(resp, "series_id");
                    OvtMySide = ExtractJsonInt(resp, "side_assigned");
                    OvtSoloExtraPick = ExtractJsonBool(resp, "solo_extra_pick");
                    string room = ExtractJsonString(resp, "room_name");
                    string region = ExtractJsonString(resp, "room_region");

                    // Lineup: "solo" is a single object, "duo" an ordered pair
                    // (the server's duo_a/duo_b columns — identical payload on
                    // all three clients, so slot agreement needs no sorting).
                    string soloName = null;
                    try
                    {
                        int sIdx = resp.IndexOf("\"solo\":");
                        int oStart = sIdx >= 0 ? resp.IndexOf('{', sIdx) : -1;
                        int oEnd = oStart >= 0 ? FindMatchingBrace(resp, oStart) : -1;
                        if (oStart >= 0 && oEnd > oStart)
                            soloName = ExtractJsonString(resp.Substring(oStart, oEnd - oStart + 1), "display_name");
                    }
                    catch { }
                    var duo = ExtractTeamMemberList(resp, "duo");
                    OvtLockedSoloName = soloName;
                    OvtLockedDuo = duo;

                    if (!string.IsNullOrEmpty(room))
                    {
                        // Loop-breaker — same contract as the FFA handler
                        // (July 28 trapped-lobby incident; the bug #85 "keeps
                        // putting me back in the same match" class): 3 fires
                        // of the same dead room, then leave and free the trio.
                        string ovtFireKey = (ActiveOvt1v2SeriesId ?? "") + "|" + room;
                        if (ovtFireKey == _ovtLastReadyFireKey) _ovtReadyFireCount++;
                        else { _ovtLastReadyFireKey = ovtFireKey; _ovtReadyFireCount = 1; }
                        if (_ovtReadyFireCount > 3)
                        {
                            Plugin.Log.LogWarning($"[1v2] ready_join re-fired {_ovtReadyFireCount}x for '{room}' — giving up and leaving the 1v2 queue");
                            CompetitiveUI.ShowNotification("Couldn't join the 1v2 match — left the queue. Please requeue.", Color.yellow, 8f);
                            OvtLeaveQueue();
                            NativeUI.MarkDirty();
                            return;
                        }
                        // Slot 0 = solo (team 0); slots 1/2 = duo (team 1) in
                        // payload order. Read by the CreatePlayer override so
                        // the 3 players land on the forced 1-vs-2 split instead
                        // of vanilla's join-order teams.
                        int slot = 0;
                        if (OvtMySide != 1)
                        {
                            if (duo.Count >= 1 && duo[0].steam_id == sid) slot = 1;
                            else if (duo.Count >= 2 && duo[1].steam_id == sid) slot = 2;
                            else
                            {
                                slot = 1;
                                Plugin.Log.LogWarning($"[1v2] my steam id not found in duo payload — defaulting slot 1 (duo={duo.Count})");
                            }
                        }
                        Plugin.SetPendingOvtSlot(slot);

                        // Pre-join Photon props — identical rationale to the
                        // 2v2 ready_join path: remote clients must have
                        // p_id/t_id/u_id BEFORE our Instantiate broadcast, and
                        // the styled NickName + cosmetics before our actor-join
                        // lands, or their first read caches the wrong values.
                        try
                        {
                            var prejoin = new ExitGames.Client.Photon.Hashtable();
                            prejoin["p_id"] = slot;
                            prejoin["t_id"] = slot == 0 ? 0 : 1;
                            prejoin["u_id"] = sid;
                            if (PhotonNetwork.LocalPlayer != null)
                                PhotonNetwork.LocalPlayer.SetCustomProperties(prejoin);
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[1v2] pre-join SetCustomProperties: {ex.Message}"); }
                        try { NametagStyler.PublishToPhoton(); } catch (Exception ex) { Plugin.Log.LogWarning($"[1v2] pre-join nametag publish: {ex.Message}"); }
                        try { PlayerColorCosmetic.PublishLocalProps(); } catch (Exception ex) { Plugin.Log.LogWarning($"[1v2] pre-join pcolor publish: {ex.Message}"); }
                        try { TrailCosmetic.PublishLocalProps(); } catch (Exception ex) { Plugin.Log.LogWarning($"[1v2] pre-join trail publish: {ex.Message}"); }

                        Plugin.SetPendingRoom(room, region);
                        Plugin.Log.LogInfo($"[1v2] All ready! Room: {room} (region: {region ?? "auto"}) series={ActiveOvt1v2SeriesId} side={OvtMySide} slot={slot}");
                        CompetitiveUI.ShowNotification(OvtMySide == 1
                            ? "3/3 ready! Joining 1v2 — you are the SOLO..."
                            : "3/3 ready! Joining 1v2 — you are on the DUO...", Color.green, 5f);
                        try { if (NativeUI.IsOpen) NativeUI.Close(); } catch { }
                    }
                }
                else if (status == "lobby")
                {
                    // v1.37 host lobbies: a still-armed queue poll whose
                    // searching row was CONVERTED by a lobby enroll — the
                    // /ovt/lobby/state heartbeat owns this state.
                    IsOvtQueuePolling = false; OvtQueueStatus = "";
                    OvtLobby.AdoptSeatFromQueuePoll(ExtractJsonString(resp, "lobby_id"));
                }
                else if (status == "lobby_closed")
                {
                    IsOvtQueuePolling = false; OvtQueueStatus = "";
                    OvtLobby.HandleSeatExpired();
                }
                else if (status == "not_in_queue" || status == "expired")
                {
                    IsOvtQueuePolling = false; OvtQueueStatus = "";
                    OvtLockedSoloName = null; OvtLockedDuo = null;
                    Plugin.ClearPendingOvtSlot();
                    // 30-min server cap (July 28) — explicit reason, and no
                    // auto-rejoin for this status (that would defeat the cap).
                    if (status == "expired")
                        CompetitiveUI.ShowNotification(
                            "Removed from 1v2 queue after 30 minutes of searching - rejoin if you're still here!",
                            Color.yellow, 7f);
                    // We believed we were searching but the server dropped our
                    // row — the ghost-prune fires on every queuer after any
                    // >75s API gap (backend redeploy, network blip). Silently
                    // flipping to "Not in queue." strands the player (they
                    // think they're queued; the menu may even be closed).
                    // Auto-rejoin once per minute with the same preferences;
                    // a voluntary Leave can't reach here (it stops polling
                    // and the in-flight guard drops late responses).
                    // Online-room gate (Codex post-release finds 1 + C): the
                    // server now EVICTS other-mode searching rows when a match
                    // locks — rejoining from inside a game would recreate the
                    // ghost the eviction just removed. OFFLINE sandbox rooms
                    // linger at the menu (learning #122) and stay eligible for
                    // the normal ghost-prune recovery.
                    if (status == "not_in_queue"
                        && _ovtConsentQueueJoined
                        && (!PhotonNetwork.InRoom || PhotonNetwork.OfflineMode)
                        && Time.unscaledTime - _ovtLastAutoRejoinAt > 60f)
                    {
                        _ovtLastAutoRejoinAt = Time.unscaledTime;
                        Plugin.Log.LogWarning("[1v2] queue row vanished server-side while searching — auto-rejoining");
                        OvtJoinQueue(_ovtLastPreferredSide, _ovtLastSoloExtraPick);
                    }
                }
                NativeUI.MarkDirty();
            }));
        }

        /// <summary>GET /ovt/queue/list — who's in the 1v2 lobby, with the
        /// context ratings (1v1 + 2v2 elo), side preference, wait time and
        /// status. Same 2s-throttle ticker pattern as the 2v2 panel
        /// (learning #62).</summary>
        public static void UpdateOvtQueueList(bool force = false)
        {
            if (!force && Time.unscaledTime - _ovtListLastAt < 2f) return;
            _ovtListLastAt = Time.unscaledTime;
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ovt/queue/list", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                try
                {
                    var list = new List<OvtQueueListEntry>();
                    int qStart = resp.IndexOf("\"queuers\"");
                    int arrStart = qStart >= 0 ? resp.IndexOf('[', qStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracket(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        string slice = resp.Substring(arrStart + 1, arrEnd - arrStart - 1);
                        int oIdx = 0;
                        while (oIdx < slice.Length)
                        {
                            int objStart = slice.IndexOf('{', oIdx);
                            if (objStart < 0) break;
                            int objEnd = FindMatchingBrace(slice, objStart);
                            if (objEnd < 0) break;
                            string obj = slice.Substring(objStart, objEnd - objStart + 1);
                            list.Add(new OvtQueueListEntry
                            {
                                steam_id = ExtractJsonString(obj, "steam_id"),
                                display_name = ExtractJsonString(obj, "display_name"),
                                rating_1v1 = ExtractJsonInt(obj, "rating_1v1"),
                                rating_2v2 = ExtractJsonInt(obj, "rating_2v2"),
                                preferred_side = ExtractJsonInt(obj, "preferred_side"),
                                solo_extra_pick = ExtractJsonBool(obj, "solo_extra_pick"),
                                status = ExtractJsonString(obj, "status"),
                                side_assigned = ExtractJsonInt(obj, "side_assigned"),
                                wait_seconds = ExtractJsonInt(obj, "wait_seconds"),
                                region = ExtractJsonString(obj, "region"),
                            });
                            oIdx = objEnd + 1;
                        }
                    }
                    CachedOvtQueueList = list;
                    NativeUI.MarkDirty();
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[1v2-QUEUE-LIST] parse: {ex.Message}"); }
            }));
        }

        /// <summary>POST /ovt/series/continuation — open a fresh 1v2 series when the
        /// three keep playing past a completed BO3 (recording-gap fix, learning #70).
        /// Reuses the 2v2 continuation request shape: t1a=solo, t1b=duo_a, t2a=duo_b,
        /// t2b unused. Reporter is the lowest Steam ID (caller ensures). Sets
        /// ActiveOvt1v2SeriesId on success.</summary>
        public static void RequestOvtContinuationSeries(
            string reporterSteam, string roomId, string region,
            string soloSteam, string duoASteam, string duoBSteam, Action<bool> callback = null)
        {
            // Canonical MUST match the server (ovt_series_continuation): 5 fields.
            string canonical = $"ovt-continuation:{soloSteam}:{duoASteam}:{duoBSteam}:{roomId}:{reporterSteam}";
            string sig = ComputeHmacHex(canonical);
            // Server reads t1a/t1b/t2a (t2b ignored) — send duoB in t2b too, harmless.
            string body = $"{{\"reporter_steam_id\":\"{Escape(reporterSteam)}\",\"room_id\":\"{Escape(roomId)}\"," +
                          $"\"region\":\"{Escape(region ?? "")}\",\"t1a_steam\":\"{Escape(soloSteam)}\",\"t1b_steam\":\"{Escape(duoASteam)}\"," +
                          $"\"t2a_steam\":\"{Escape(duoBSteam)}\",\"t2b_steam\":\"{Escape(duoBSteam)}\",\"hmac_signature\":\"{sig}\"}}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry($"{baseUrl}/api/v1/ovt/series/continuation", body, (ok, resp) =>
            {
                if (ok && !string.IsNullOrEmpty(resp))
                {
                    string sidNew = ExtractJsonString(resp, "series_id");
                    if (!string.IsNullOrEmpty(sidNew)) { ActiveOvt1v2SeriesId = sidNew; Plugin.Log.LogInfo($"[1v2-CONTINUATION] active series set to {sidNew} ({ExtractJsonString(resp, "status")})"); }
                }
                else Plugin.Log.LogWarning($"[1v2-CONTINUATION] request failed: {resp}");
                callback?.Invoke(ok);
            }, maxRetries: 2, retryDelay: 2f));
        }

        /// <summary>GET /ovt/leaderboard. role: combined|solo|duo — combined fills
        /// the legacy CachedOvtLeaderboard, solo/duo fill the split activity-board
        /// caches the 1v2 tab renders. The server re-scopes games/wins/losses/
        /// win_rate to the role (note: 1v2 win_rate is 0-100, unlike FFA's 0-1).</summary>
        public static void FetchOvtLeaderboard(int limit = 200, string role = "combined")
        {
            string roleQ = (role == "solo" || role == "duo") ? role : "combined";
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ovt/leaderboard?limit={limit}&role={roleQ}", (ok, resp) =>
            {
                if (!ok) return;
                try
                {
                    var entries = new List<OvtLeaderboardEntry>();
                    // String-aware slicing (learning #156) — the old "rank": split
                    // parser would break on a display name containing that literal.
                    int eStart = resp.IndexOf("\"entries\"");
                    int arrStart = eStart >= 0 ? resp.IndexOf('[', eStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        foreach (string chunk in SliceTopLevelObjects(
                            resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                        {
                            entries.Add(new OvtLeaderboardEntry
                            {
                                rank = ExtractJsonInt(chunk, "rank"),
                                steam_id = ExtractJsonString(chunk, "steam_id"),
                                display_name = ExtractJsonString(chunk, "display_name"),
                                games_played = ExtractJsonInt(chunk, "games_played"),
                                wins = ExtractJsonInt(chunk, "wins"),
                                losses = ExtractJsonInt(chunk, "losses"),
                                win_rate = ExtractJsonFloat(chunk, "win_rate"),
                                solo_games = ExtractJsonInt(chunk, "solo_games"),
                                duo_games = ExtractJsonInt(chunk, "duo_games"),
                                solo_wins = ExtractJsonInt(chunk, "solo_wins"),
                                solo_losses = ExtractJsonInt(chunk, "solo_losses"),
                                duo_wins = ExtractJsonInt(chunk, "duo_wins"),
                                duo_losses = ExtractJsonInt(chunk, "duo_losses"),
                                level = ExtractJsonInt(chunk, "level"),
                                title = ExtractJsonString(chunk, "title"),
                                title_color = ExtractJsonString(chunk, "title_color"),
                                last_played = ExtractJsonString(chunk, "last_played"),
                            });
                        }
                    }
                    if (roleQ == "solo") CachedOvtLeaderboardSolo = entries;
                    else if (roleQ == "duo") CachedOvtLeaderboardDuo = entries;
                    else
                    {
                        CachedOvtLeaderboard = entries;
                        CachedOvtLeaderboardTotal = ExtractJsonInt(resp, "total_players");
                    }
                    NativeUI.MarkDirty();
                    Plugin.Log.LogInfo($"[1v2-LB] loaded {entries.Count} players (role={roleQ})");
                }
                catch (Exception ex) { Plugin.Log.LogError($"[1v2-LB] parse: {ex.Message}"); }
            }));
        }

        /// <summary>Report a finished 1v2 game to /ovt/matches. 10-field HMAC
        /// canonical (see schemas.py OvtMatchReport). solo = side 1, duo = side 2.
        /// Reporter is the lowest Steam ID across the three (caller ensures).</summary>
        public static void ReportOvtMatch(
            string seriesId, string room, string region, int durationSeconds,
            string soloSteam, string soloName, List<MatchTracker.CardPickData> soloCards,
            string duoASteam, string duoAName, List<MatchTracker.CardPickData> duoACards,
            string duoBSteam, string duoBName, List<MatchTracker.CardPickData> duoBCards,
            int soloRounds, int duoRounds, int soloPoints, int duoPoints,
            string reporterSteam, int soloFps, int duoAFps, int duoBFps,
            // Aug 7 — cumulative damage-dealt CSVs per seat, for the DPS graph.
            // Same 3s grid as the fps timelines these sit beside. Optional so a
            // caller that has no sample for a seat simply omits it (the server
            // stores an empty string as NULL, i.e. "not recorded", not zero).
            string soloDamageTimeline = null,
            string duoADamageTimeline = null,
            string duoBDamageTimeline = null,
            // Aug 12 item 1 — per-seat end-of-game BUILD wire strings. Null =
            // not captured (field omitted). ADVISORY: rides outside the frozen
            // 10-field canonical below.
            string soloEndStats = null,
            string duoAEndStats = null,
            string duoBEndStats = null)
        {
            if (RoomActors.LocalIsSpectator) return;   // spectator: never reports (design §3.5)
            // §2c identity fence: the broadcast account never reports.
            if (BroadcastMode.FenceBlocksFighterPath("report-1v2")) return;
            int winnerSide = soloRounds > duoRounds ? 1 : 2;
            bool isRanked = false;  // unscored at launch
            var sb = new StringBuilder();
            sb.Append("{");
            sb.Append($"\"series_id\":\"{Escape(seriesId)}\",");
            void appendPlayer(string key, string steam, string nm, List<MatchTracker.CardPickData> cards, string endStats)
            {
                sb.Append($"\"{key}\":{{\"steam_id\":\"{Escape(steam)}\",\"display_name\":\"{Escape(nm)}\",\"cards\":[");
                AppendCards(sb, cards ?? new List<MatchTracker.CardPickData>());
                sb.Append("]");
                AppendEndStats(sb, endStats);
                sb.Append("},");
            }
            appendPlayer("solo", soloSteam, soloName, soloCards, soloEndStats);
            appendPlayer("duo_a", duoASteam, duoAName, duoACards, duoAEndStats);
            appendPlayer("duo_b", duoBSteam, duoBName, duoBCards, duoBEndStats);
            sb.Append($"\"solo_rounds_won\":{soloRounds},\"duo_rounds_won\":{duoRounds},");
            sb.Append($"\"solo_points_total\":{soloPoints},\"duo_points_total\":{duoPoints},");
            sb.Append($"\"winner_side\":{winnerSide},");
            sb.Append($"\"photon_room_id\":\"{Escape(room)}\",\"game_version\":\"v{Application.version}\",");
            sb.Append($"\"region\":\"{Escape(region)}\",\"match_duration\":{durationSeconds},");
            sb.Append($"\"is_ranked\":{(isRanked ? "true" : "false")},");
            sb.Append($"\"reported_by_steam_id\":\"{Escape(reporterSteam)}\",");
            sb.Append($"\"solo_fps\":{soloFps},\"duo_a_fps\":{duoAFps},\"duo_b_fps\":{duoBFps},");
            // Mirrors ovt_matches.<seat>_damage_timeline (migration 201). Flat on
            // the report, not a telemetry blob — 1v2 has no telemetry table. These
            // ride OUTSIDE the 10-field HMAC canonical below, which is frozen.
            sb.Append($"\"solo_damage_timeline\":\"{Escape(ClampTimeline(soloDamageTimeline, 1024))}\",");
            sb.Append($"\"duo_a_damage_timeline\":\"{Escape(ClampTimeline(duoADamageTimeline, 1024))}\",");
            sb.Append($"\"duo_b_damage_timeline\":\"{Escape(ClampTimeline(duoBDamageTimeline, 1024))}\",");
            string canonical = $"{soloSteam}:{duoASteam}:{duoBSteam}:{soloRounds}:{duoRounds}:" +
                               $"{(isRanked ? "true" : "false")}:{reporterSteam}:{room ?? ""}:{winnerSide}:{seriesId}";
            sb.Append($"\"hmac_signature\":\"{ComputeHmacHex(canonical)}\"");
            sb.Append("}");
            string json = sb.ToString();
            Plugin.Log.LogInfo($"[1v2-REPORT] submitting series={seriesId} winner=side{winnerSide} {soloRounds}-{duoRounds}");
            Plugin.Instance.StartCoroutine(PostRequestWithRetry($"{baseUrl}/api/v1/ovt/matches", json, (ok, resp) =>
            {
                if (ok)
                {
                    Plugin.Log.LogInfo($"[1v2] match reported: {resp}");
                    RefreshAchievementsAfterReport();
                    string sStatus = ExtractJsonString(resp, "series_status");
                    string sScore = ExtractJsonString(resp, "series_score");
                    if (sStatus == "completed") { CompetitiveUI.ShowNotification(I18n.TrF("1v2 series complete: {0}", sScore), Color.green, 6f); ActiveOvt1v2SeriesId = null; Plugin.ClearPendingOvtSlot(); }
                    else if (!string.IsNullOrEmpty(sScore)) CompetitiveUI.ShowNotification(I18n.TrF("1v2 series: {0}", sScore), new Color(0.6f, 0.8f, 1f), 4f);
                    // Bug #129: 1v2 always PAID xp+gold, but nothing anywhere ever
                    // showed it — which is exactly why it read as "1v2 doesn't give
                    // XP/gold". Queue (not Show) so it follows the score toast
                    // instead of replacing it. Bonus labels are read generically so
                    // a future server-side factor renders with no client release.
                    int gXp = ExtractJsonInt(resp, "xp_gained");
                    int gGold = ExtractJsonInt(resp, "gold_gained");
                    if (gXp > 0 || gGold > 0)
                    {
                        string gLine = I18n.TrF("+{0} XP", gXp) + (gGold > 0 ? "  <color=#FFD94D>" + I18n.TrF("+{0}g", gGold) + "</color>" : "");
                        string bon = string.Join(", ", ExtractJsonStringArray(resp, "xp_bonuses").ToArray());
                        if (!string.IsNullOrEmpty(bon)) gLine += $"  ({bon})";
                        CompetitiveUI.QueueNotification(gLine, new Color(0.75f, 0.9f, 0.6f), 5f);
                    }
                }
                else
                {
                    Plugin.Log.LogWarning($"[1v2] report failed: {resp}");
                    EnqueueFailedReport($"{baseUrl}/api/v1/ovt/matches", json);  // bug #65 outbox
                }
            }, maxRetries: 3, retryDelay: 2f));
        }

        // ── 1v2 recent games feed (GET /ovt/recent) ──────────────────────────
        // Field names parse the codex-task-1v2-server.md contract byte-for-byte
        // (learning #152). Every array/object slice over regions carrying user
        // display names is string-aware (learning #156).

        public class OvtRecentMatch
        {
            public string match_id, ended_at;
            public int winner_side, solo_rounds, duo_rounds, solo_points, duo_points, duration_seconds;
            public Dictionary<string, int> fps_by_steam = new Dictionary<string, int>();
            public Dictionary<string, List<string>> cards_by_steam = new Dictionary<string, List<string>>();
            // Aug 7. Cumulative damage CSV per seat, for the DPS hover graph. The
            // server OMITS a seat whose timeline is null, so an absent key means
            // "not recorded" — register no graph rather than an empty one (#257).
            public Dictionary<string, string> damage_timeline_by_steam = new Dictionary<string, string>();
            // Aug 12 item 1 — steam_id -> end-of-game BUILD wire string. Same
            // omit-when-absent rule as the map above: a seat with no build is
            // simply not a key, so render no build panel rather than an empty
            // one (#257).
            public Dictionary<string, string> end_stats_by_steam = new Dictionary<string, string>();
        }
        public class OvtRecentSeries
        {
            public string series_id, status, created_at, completed_at;
            public int winner_side, solo_wins, duo_wins;
            public bool solo_extra_pick;
            public string solo_steam, solo_name, duo_a_steam, duo_a_name, duo_b_steam, duo_b_name;
            public Dictionary<string, int> gold_by_steam = new Dictionary<string, int>();
            public Dictionary<string, int> xp_by_steam = new Dictionary<string, int>();
            public List<OvtRecentMatch> matches = new List<OvtRecentMatch>();
        }
        public static List<OvtRecentSeries> CachedOvtRecent = null;
        public static int CachedOvtRecentTotal = 0;
        public static int CachedOvtRecentPages = 0;

        /// <summary>Parse a {"7656...": 123, ...} object. The object is LOCATED
        /// with the string-aware brace matcher (sibling fields carry user names);
        /// INSIDE it the keys are numeric steam ids and the values plain ints,
        /// so simple quote/number scans are safe. Search includes the closing
        /// quote + colon so an escaped key literal inside a name can't match.</summary>
        private static Dictionary<string, int> ParseSteamIntMap(string json, string key)
        {
            var d = new Dictionary<string, int>();
            int k = json.IndexOf($"\"{key}\":");
            if (k < 0) return d;
            int open = json.IndexOf('{', k);
            if (open < 0) return d;
            int close = FindMatchingBraceStringAware(json, open);
            if (close < 0) return d;
            int i = open + 1;
            while (i < close)
            {
                int q1 = json.IndexOf('"', i); if (q1 < 0 || q1 >= close) break;
                int q2 = json.IndexOf('"', q1 + 1); if (q2 < 0 || q2 >= close) break;
                string sid = json.Substring(q1 + 1, q2 - q1 - 1);
                int colon = json.IndexOf(':', q2); if (colon < 0 || colon >= close) break;
                int e = colon + 1;
                while (e < close && json[e] == ' ') e++;
                int st = e;
                while (e < close && (char.IsDigit(json[e]) || json[e] == '-')) e++;
                int val = 0;
                if (e > st) int.TryParse(json.Substring(st, e - st), out val);
                if (!string.IsNullOrEmpty(sid)) d[sid] = val;
                i = e + 1;
            }
            return d;
        }

        /// <summary>Parse a {"7656...": "0,0,55,...", ...} object. Keys are numeric
        /// steam ids; the VALUES originate from a client-submitted report field, so
        /// they are read escape-aware rather than scanned for a bare closing quote.
        /// A key the server omitted simply never lands in the map.</summary>
        private static Dictionary<string, string> ParseSteamStringMap(string json, string key)
        {
            var d = new Dictionary<string, string>();
            int k = json.IndexOf($"\"{key}\":");
            if (k < 0) return d;
            int open = json.IndexOf('{', k);
            if (open < 0) return d;
            int close = FindMatchingBraceStringAware(json, open);
            if (close < 0) return d;
            int i = open + 1;
            while (i < close)
            {
                int q1 = json.IndexOf('"', i); if (q1 < 0 || q1 >= close) break;
                int q2 = json.IndexOf('"', q1 + 1); if (q2 < 0 || q2 >= close) break;
                string sid = json.Substring(q1 + 1, q2 - q1 - 1);
                int colon = json.IndexOf(':', q2); if (colon < 0 || colon >= close) break;
                // The value MUST be the next non-space token. Today the server
                // omits a seat whose timeline is null, but scanning ahead for the
                // next quote would silently pair this key with the NEXT entry's
                // value if it ever emits `"765":null` instead — so bail out of the
                // whole map rather than record a mis-attributed timeline.
                int vq = colon + 1;
                while (vq < close && (json[vq] == ' ' || json[vq] == '\t')) vq++;
                if (vq >= close || json[vq] != '"') break;
                // Escape-aware value scan (same translation table as
                // ParseJsonStringArray): a bare IndexOf('"') would stop inside an
                // escaped quote and leave the cursor mid-value for the next entry.
                var sb = new StringBuilder();
                int e = vq + 1;
                while (e < close)
                {
                    char c = json[e];
                    if (c == '\\' && e + 1 < close)
                    {
                        char nx = json[e + 1];
                        sb.Append(nx == 'n' ? '\n' : nx == 't' ? '\t' : nx == 'r' ? '\r' : nx);
                        e += 2;
                        continue;
                    }
                    if (c == '"') break;
                    sb.Append(c);
                    e++;
                }
                if (!string.IsNullOrEmpty(sid)) d[sid] = sb.ToString();
                i = e + 1;
            }
            return d;
        }

        /// <summary>Read the quoted strings of a JSON string array spanning
        /// s[open..close] ('[' and ']'). Values are card names — treat as
        /// arbitrary text: escape-aware, never comma-split.</summary>
        private static List<string> ParseJsonStringArray(string s, int open, int close)
        {
            var list = new List<string>();
            var sb = new StringBuilder();
            bool inStr = false;
            for (int i = open + 1; i < close; i++)
            {
                char c = s[i];
                if (!inStr) { if (c == '"') { inStr = true; sb.Length = 0; } continue; }
                if (c == '\\' && i + 1 < close)
                {
                    i++;
                    char nx = s[i];
                    sb.Append(nx == 'n' ? '\n' : nx == 't' ? '\t' : nx == 'r' ? '\r' : nx);
                    continue;
                }
                if (c == '"') { inStr = false; list.Add(sb.ToString()); continue; }
                sb.Append(c);
            }
            return list;
        }

        /// <summary>Parse {"7656...": ["Card A", ...], ...}. Keys numeric steam
        /// ids; VALUES are card-name string arrays — sliced string-aware.</summary>
        private static Dictionary<string, List<string>> ParseSteamCardsMap(string json, string key)
        {
            var d = new Dictionary<string, List<string>>();
            int k = json.IndexOf($"\"{key}\":");
            if (k < 0) return d;
            int open = json.IndexOf('{', k);
            if (open < 0) return d;
            int close = FindMatchingBraceStringAware(json, open);
            if (close < 0) return d;
            int i = open + 1;
            while (i < close)
            {
                int q1 = json.IndexOf('"', i); if (q1 < 0 || q1 >= close) break;
                int q2 = json.IndexOf('"', q1 + 1); if (q2 < 0 || q2 >= close) break;
                string sid = json.Substring(q1 + 1, q2 - q1 - 1);
                int arrOpen = json.IndexOf('[', q2); if (arrOpen < 0 || arrOpen >= close) break;
                int arrClose = FindMatchingBracketStringAware(json, arrOpen);
                if (arrClose < 0 || arrClose > close) break;
                if (!string.IsNullOrEmpty(sid)) d[sid] = ParseJsonStringArray(json, arrOpen, arrClose);
                i = arrClose + 1;
            }
            return d;
        }

        /// <summary>GET /ovt/recent — paged recent 1v2 series with nested matches
        /// (the tab's "Recent 1v2 Games" panel). Anyone can browse.</summary>
        public static void FetchOvtRecent(int page = 0, int pageSize = 5)
        {
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ovt/recent?page={page}&page_size={pageSize}", (ok, resp) =>
            {
                if (!ok) return;
                try
                {
                    var seriesList = new List<OvtRecentSeries>();
                    int sStart = resp.IndexOf("\"series\"");
                    int arrStart = sStart >= 0 ? resp.IndexOf('[', sStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        foreach (string sObj in SliceTopLevelObjects(
                            resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                        {
                            // Series-level scalars are read from the text BEFORE the
                            // matches array — winner_side exists at BOTH levels and
                            // the contract places matches last, so this guarantees
                            // the series value can't be shadowed by game 1's.
                            int mKey = sObj.IndexOf("\"matches\":");
                            string head = mKey >= 0 ? sObj.Substring(0, mKey) : sObj;
                            var s = new OvtRecentSeries
                            {
                                series_id = ExtractJsonString(head, "series_id"),
                                status = ExtractJsonString(head, "status"),
                                winner_side = ExtractJsonInt(head, "winner_side"),
                                created_at = ExtractJsonString(head, "created_at"),
                                completed_at = ExtractJsonString(head, "completed_at"),
                                solo_wins = ExtractJsonInt(head, "solo_wins"),
                                duo_wins = ExtractJsonInt(head, "duo_wins"),
                                solo_extra_pick = ExtractJsonBool(head, "solo_extra_pick"),
                                gold_by_steam = ParseSteamIntMap(head, "gold_by_steam"),
                                xp_by_steam = ParseSteamIntMap(head, "xp_by_steam"),
                            };
                            // solo: {"steam_id":..,"display_name":..}
                            int soloK = head.IndexOf("\"solo\":");
                            int soloOpen = soloK >= 0 ? head.IndexOf('{', soloK) : -1;
                            int soloClose = soloOpen >= 0 ? FindMatchingBraceStringAware(head, soloOpen) : -1;
                            if (soloOpen >= 0 && soloClose > soloOpen)
                            {
                                string so = head.Substring(soloOpen, soloClose - soloOpen + 1);
                                s.solo_steam = ExtractJsonString(so, "steam_id");
                                s.solo_name = ExtractJsonString(so, "display_name");
                            }
                            // duo: [ {..}, {..} ]
                            int duoK = head.IndexOf("\"duo\":");
                            int duoOpen = duoK >= 0 ? head.IndexOf('[', duoK) : -1;
                            int duoClose = duoOpen >= 0 ? FindMatchingBracketStringAware(head, duoOpen) : -1;
                            if (duoOpen >= 0 && duoClose > duoOpen)
                            {
                                var duo = SliceTopLevelObjects(head.Substring(duoOpen + 1, duoClose - duoOpen - 1));
                                if (duo.Count > 0)
                                {
                                    s.duo_a_steam = ExtractJsonString(duo[0], "steam_id");
                                    s.duo_a_name = ExtractJsonString(duo[0], "display_name");
                                }
                                if (duo.Count > 1)
                                {
                                    s.duo_b_steam = ExtractJsonString(duo[1], "steam_id");
                                    s.duo_b_name = ExtractJsonString(duo[1], "display_name");
                                }
                            }
                            // matches: [ {..}, .. ]
                            int mArr = mKey >= 0 ? sObj.IndexOf('[', mKey) : -1;
                            int mEnd = mArr >= 0 ? FindMatchingBracketStringAware(sObj, mArr) : -1;
                            if (mArr >= 0 && mEnd > mArr)
                            {
                                foreach (string mObj in SliceTopLevelObjects(
                                    sObj.Substring(mArr + 1, mEnd - mArr - 1)))
                                {
                                    s.matches.Add(new OvtRecentMatch
                                    {
                                        match_id = ExtractJsonString(mObj, "match_id"),
                                        ended_at = ExtractJsonString(mObj, "ended_at"),
                                        winner_side = ExtractJsonInt(mObj, "winner_side"),
                                        solo_rounds = ExtractJsonInt(mObj, "solo_rounds"),
                                        duo_rounds = ExtractJsonInt(mObj, "duo_rounds"),
                                        solo_points = ExtractJsonInt(mObj, "solo_points"),
                                        duo_points = ExtractJsonInt(mObj, "duo_points"),
                                        duration_seconds = ExtractJsonInt(mObj, "duration_seconds"),
                                        fps_by_steam = ParseSteamIntMap(mObj, "fps_by_steam"),
                                        cards_by_steam = ParseSteamCardsMap(mObj, "cards_by_steam"),
                                        damage_timeline_by_steam = ParseSteamStringMap(mObj, "damage_timeline_by_steam"),
                                        // Aug 12 item 1 — end-of-game builds.
                                        end_stats_by_steam = ParseSteamStringMap(mObj, "end_stats_by_steam"),
                                    });
                                }
                            }
                            seriesList.Add(s);
                        }
                    }
                    CachedOvtRecent = seriesList;
                    CachedOvtRecentTotal = ExtractJsonInt(resp, "total");
                    CachedOvtRecentPages = ExtractJsonInt(resp, "total_pages");
                    NativeUI.MarkDirty();
                    Plugin.Log.LogInfo($"[1v2-RECENT] loaded {seriesList.Count} series (page {page})");
                }
                catch (Exception ex) { Plugin.Log.LogError($"[1v2-RECENT] parse: {ex.Message}"); }
            }));
        }

