        private static float _ffaLobbyRejoinAt = -999f;
        private static bool _ffaLobbyActionInFlight = false;
        private static float _ffaLobbyActionAt = -999f;
        // Generation for the in-flight bit (round-2 find: a STALE callback
        // clearing the global bit could release a newer action's guard and
        // let two actions overlap). A callback only clears the bit if no
        // newer action started; the watchdog releases at 30s — ABOVE the 20s
        // POST timeout, so a live request can never overlap its successor.
        private static int _ffaLobbyActionGen = 0;

        private static void FfaLobbyActionBegin()
        {
            _ffaLobbyActionInFlight = true;
            _ffaLobbyActionAt = Time.realtimeSinceStartup;
            _ffaLobbyActionGen++;
        }

        private static void FfaLobbyActionEnd(int actionGen)
        {
            if (actionGen == _ffaLobbyActionGen) _ffaLobbyActionInFlight = false;
        }
        // Explicit-leave intent (impl review find 2): once the player asked to
        // leave, every later signal bends toward OUT — a 'lobby' poll retries
        // the leave instead of re-adopting the seat, a not_in_queue means the
        // leave landed (never the rejoin recovery), and a ready_join that
        // raced the start is left, not joined. Cleared by leave ack or a
        // fresh create/join intent.
        private static bool _ffaLeaveIntent = false;
        private static float _ffaLeaveRetryAt = -999f;
        // Durable leave target (round-2 find 2): the id the leave was aimed
        // at must survive the callback being killed (NetworkRestart right
        // after FfaLeaveQueue) so the stuck-leave watchdog can restore the
        // belief and re-arm the poll-driven retry.
        private static string _ffaLeaveTargetLobby = null;
        // Durable leave CAUSE (round-10 find 1): the in_room_exit attestation
        // must survive the same coroutine-death/retry boundary the target
        // does — a cause-free retry would let the server reclassify a known
        // in-room departure as failed assembly. Cleared with intent/target.
        private static string _ffaLeaveCause = "";
        // Ambiguity window after a transport-failed enroll: keep polling so a
        // late-committing create/join surfaces instead of hiding a seat.
        private static float _ffaAmbiguousPollUntil = -999f;

        /// <summary>Server-sent error detail, or the fallback when the server
        /// never spoke (ExtractJsonString returns "" — `??` alone can't tell
        /// a transport failure from a spoken 4xx; impl review find 8).</summary>
        private static string DetailOr(string resp, string fallback)
        {
            string d = ExtractJsonString(resp ?? "", "detail");
            return string.IsNullOrEmpty(d) ? fallback : d;
        }

        public class FfaQueueListEntry
        {
            public string steam_id, display_name, status, region;
            public int rating, rating_1v1, slot, wait_seconds;
        }
        public static List<FfaQueueListEntry> CachedFfaQueueList = null;
        private static float _ffaListLastAt = -999f;
        private static float _ffaLastAutoRejoinAt = -999f;
        // July 28 trapped-lobby loop-breaker: the same dead room re-firing
        // ready_join forever (server wedge, join failure, any loop shape) —
        // after 3 fires for one lobby+room, leave the queue instead of
        // re-attempting. Reset on a fresh join intent. Mirrored for 1v2.
        private static string _ffaLastReadyFireKey = null;
        private static int _ffaReadyFireCount = 0;
        private static string _ovtLastReadyFireKey = null;
        private static int _ovtReadyFireCount = 0;
        private static float _ffaLeavingSince = -999f;
        private static int ffaGen = 0;  // lifecycle generation — see queueGen

        public static void FfaJoinQueue()
        {
            if (SpectatorBlocksQueue()) return;
            NoteQueueRequestInFlight();   // r3: WATCH is blocked for the whole join round-trip   // design §3.1
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            // NO loop-breaker reset here (Codex sitting-over review find 2):
            // the wedge loop travels THROUGH this method (auto-rejoin -> join
            // -> poll -> dead ready_join), so resetting on join made the
            // counter unable to ever exceed 1. A genuinely new assembly gets
            // a new lobby UUID and therefore a new fire key on its own; the
            // counter only survives across retries of the SAME dead room.
            if (FfaQueueStatus == "leaving")
            {
                if (Time.realtimeSinceStartup - _ffaLeavingSince < LEAVE_STUCK_TIMEOUT)
                {
                    CompetitiveUI.ShowNotification("Still leaving the FFA queue — try again in a moment.", new Color(1f, 0.6f, 0.2f));
                    return;
                }
                FfaQueueStatus = "";
            }
            // No ready-up step (consent-at-join, #127) — never queue from
            // inside a live online room or a later lock would yank the player
            // out mid-match (#150). OfflineMode lingers InRoom at menu (#122).
            bool inOnlineRoom = false;
            try { inOnlineRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode; } catch { }
            if (inOnlineRoom)
            {
                CompetitiveUI.ShowNotification("Finish or leave your current game before joining the FFA queue.", new Color(1f, 0.7f, 0.3f), 5f);
                return;
            }
            string name = Escape(MatchTracker.LocalDisplayName ?? "Player");
            string region = "";
            try { region = PhotonNetwork.CloudRegion?.Replace("/*", "") ?? ""; } catch { region = ""; }
            string body = $"{{\"steam_id\":\"{sid}\",\"display_name\":\"{name}\",\"region\":\"{Escape(region)}\"}}";
            int gen = ++ffaGen;
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ffa/queue/join", body, (ok, resp) =>
            {
                if (gen != ffaGen) { Plugin.Log.LogInfo("[FFA] stale join ack ignored (lifecycle moved on)"); return; }
                if (ok) { IsFfaQueuePolling = true; FfaQueueStatus = "searching"; UpdateFfaQueueList(force: true); NativeUI.MarkDirty(); }
                else Plugin.Log.LogWarning($"[FFA] join failed: {resp}");
            }));
        }

        // ── Open host-lobby actions (July 29 redesign) ─────────────────────

        private static bool FfaLobbyActionPreflight(out string sid)
        {
            sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return false;
            // Watchdog release (impl review adjacent find): a lost callback
            // must not wedge the buttons forever. 30s > the 20s POST timeout,
            // so a still-live request can never overlap its successor.
            if (_ffaLobbyActionInFlight && Time.realtimeSinceStartup - _ffaLobbyActionAt > 30f)
                _ffaLobbyActionInFlight = false;
            if (_ffaLobbyActionInFlight) return false;
            if (FfaQueueStatus == "leaving")
            {
                CompetitiveUI.ShowNotification("Still leaving — try again in a moment.", new Color(1f, 0.6f, 0.2f));
                return false;
            }
            // Codex round-3 regression 5: a locked membership (start countdown
            // pending or lobby fired) must gate the browser buttons — a Join
            // click bumps the queue generation, which silently invalidates the
            // live delayed join even when the server rejects the new join.
            if (!string.IsNullOrEmpty(ActiveFfaLobbyId))
            {
                CompetitiveUI.ShowNotification("Your FFA is already starting — leave it first if you meant to switch.", new Color(1f, 0.7f, 0.3f), 5f);
                return false;
            }
            // Consent-at-join (#127/#150), narrowed for bug #132: taking an
            // OPEN lobby seat while in a CASUAL game is allowed — waiting in
            // casual is the whole point of Sid's design; the Start countdown
            // pulls the member out when the lobby actually fires. Competitive
            // rooms still refuse. OfflineMode lingers InRoom (#122).
            bool inCompetitiveRoom = false;
            try
            {
                inCompetitiveRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode
                    && CompetitiveRoomDetect.IsCompetitiveRoom();
            }
            catch { }
            if (inCompetitiveRoom)
            {
                CompetitiveUI.ShowNotification("Finish or leave your current game first.", new Color(1f, 0.7f, 0.3f), 5f);
                return false;
            }
            return true;
        }

        private static string FfaLobbyBody(string sid, string lobbyId = null, string password = null)
        {
            string name = Escape(MatchTracker.LocalDisplayName ?? "Player");
            string region = "";
            try { region = PhotonNetwork.CloudRegion?.Replace("/*", "") ?? ""; } catch { region = ""; }
            string lob = lobbyId == null ? "" : $",\"lobby_id\":\"{Escape(lobbyId)}\"";
            // v1.37 private lobbies: password rides create AND join; the server
            // ignores it on public lobbies, so a stale value is harmless.
            string pw = string.IsNullOrEmpty(password) ? "" : $",\"password\":\"{Escape(password)}\"";
            return $"{{\"steam_id\":\"{sid}\",\"display_name\":\"{name}\",\"region\":\"{Escape(region)}\"{lob}{pw}}}";
        }

        // Remembered for recovery rejoins (the ghost-prune same-lobby rejoin
        // must re-send a private lobby's password or it 403s). Memory-only.
        private static string _ffaLastLobbyPassword = null;

        /// <summary>Shared post-enroll handling: adopt the membership, or —
        /// when the server may have committed without us hearing (transport
        /// failure) — let the SERVER state win via an immediate poll probe
        /// (impl review find 4: a lost create/join ack must not leave a
        /// hidden seat the host can lock).</summary>
        private static void FfaEnrollResult(bool ok, string resp, string intendedLobbyId, bool wasRecovery)
        {
            if (ok)
            {
                string lid = ExtractJsonString(resp, "lobby_id");
                OpenFfaLobbyId = string.IsNullOrEmpty(lid) ? intendedLobbyId : lid;
                // Per-lobby mirror validity (round-2 find 13): the Cfg*
                // mirrors otherwise hold the PREVIOUS lobby's values until
                // the first membership poll returns — the Info popup would
                // show 10/3 from the lobby just left. Take the enroll
                // response's config when present (the server echoes the row);
                // fall back to defaults, which the poll corrects in ~2s.
                int ecT = ExtractJsonInt(resp, "score_target");
                int ecP = ExtractJsonInt(resp, "initial_picks");
                int ecC = ExtractJsonInt(resp, "card_cap");
                FfaLobbyCfgTarget = ecT > 0 ? ecT : 5;
                int ecCand = ExtractJsonInt(resp, "card_candidates");
                FfaLobbyCfgCand = ecCand > 0 ? ecCand : 5;
                FfaLobbyCfgPicks = ecP > 0 ? ecP : 1;
                FfaLobbyCfgCap = ecC > 0 ? ecC : 5;
                FfaLobbyCfgSame = ExtractJsonBool(resp, "same_card_rule");
                FfaLobbyCfgSudden = ExtractJsonBool(resp, "sudden_death");
                FfaLobbyCfgRanked = !resp.Contains("\"lobby_ranked\":false");
                _ffaLeaveIntent = false;
                IsFfaQueuePolling = true; FfaQueueStatus = "lobby";
                Plugin.Log.LogInfo($"[FFA-LOBBY] enrolled in lobby {OpenFfaLobbyId} (recovery={wasRecovery})");
                // Level-triggered room exclusion (impl review find 3), now
                // competitive-only (bug #132 — a casual game may carry an open
                // seat): if a COMPETITIVE game finished connecting while the
                // enroll was in flight, we hold a seat we cannot sit in.
                bool inCompRoom = false;
                try
                {
                    inCompRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode
                        && CompetitiveRoomDetect.IsCompetitiveRoom();
                }
                catch { }
                if (inCompRoom)
                {
                    Plugin.Log.LogWarning("[FFA-LOBBY] enrolled while inside a competitive room — leaving the lobby");
                    FfaLeaveQueue();
                    return;
                }
            }
            else
            {
                // "The server judged this" = any 4xx (FormatRequestError now
                // carries the body, so detail parses out of it too). 5xx and
                // transport failures stay AMBIGUOUS — the request may have
                // committed (round-2 find 4).
                bool serverSpoke = resp != null && resp.StartsWith("HTTP 4", StringComparison.Ordinal);
                Plugin.Log.LogWarning($"[FFA-LOBBY] enroll failed (recovery={wasRecovery}, serverSpoke={serverSpoke}): {resp}");
                // v1.37 private lobbies: the two password 403 details are exact
                // API contract (main.py LOBBY_PW_*_DETAIL) — map them to a
                // readable prompt instead of toasting the raw token.
                string pwDetail = serverSpoke ? (ExtractJsonString(resp ?? "", "detail") ?? "") : "";
                // Aug 8 (Sid): KICKED IS TERMINAL. Every FFA join funnels here
                // — user clicks AND the ghost-prune same-lobby rejoin — and a
                // kicked client that retried would fight the kick forever.
                // Clear belief AND leave-intent, never retry, never reprompt.
                if (pwDetail == "kicked_from_lobby")
                {
                    OpenFfaLobbyId = null; FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                    FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                    IsFfaQueuePolling = false;
                    _ffaAmbiguousPollUntil = -999f;
                    _ffaLeaveIntent = false; _ffaLeaveTargetLobby = null; _ffaLeaveCause = "";
                    if (FfaQueueStatus == "lobby") FfaQueueStatus = "";
                    CompetitiveUI.ShowNotification(I18n.Tr("The host removed you from this lobby."), new Color(1f, 0.7f, 0.3f), 7f);
                    FetchFfaLobbies(force: true);
                    NativeUI.MarkDirty();
                    return;
                }
                if (pwDetail == "password_required" || pwDetail == "password_incorrect")
                {
                    bool pwWrong = pwDetail == "password_incorrect";
                    if (wasRecovery)
                    {
                        // A background recovery rejoin has no user mid-flow —
                        // never pop a modal from it. The seat is already gone
                        // server-side, so dropping the belief leaves nothing
                        // behind; tell the player the way back in.
                        OpenFfaLobbyId = null; FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                        FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                        IsFfaQueuePolling = false;
                        if (FfaQueueStatus == "lobby") FfaQueueStatus = "";
                        CompetitiveUI.ShowNotification(I18n.Tr("Couldn't rejoin your private FFA lobby — join it again from the browser."), new Color(1f, 0.75f, 0.4f), 7f);
                    }
                    else
                    {
                        CompetitiveUI.ShowNotification(pwWrong
                            ? I18n.Tr("Wrong password — try again.")
                            : I18n.Tr("That FFA lobby is private — enter its password."), new Color(1f, 0.7f, 0.3f), 5f);
                        string relobby = intendedLobbyId;   // captured — the modal outlives this callback
                        if (!string.IsNullOrEmpty(relobby))
                            CompetitiveUI.OpenArtistInput(I18n.Tr("Private FFA lobby"),
                                pwWrong ? I18n.Tr("Wrong password - try again") : I18n.Tr("Password"), "",
                                pw => FfaJoinLobby(relobby, pw));
                    }
                    FetchFfaLobbies(force: true);
                    NativeUI.MarkDirty();
                    return;
                }
                if (wasRecovery && serverSpoke)
                {
                    // The server judged our old membership: it's gone.
                    OpenFfaLobbyId = null; FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                    FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                    IsFfaQueuePolling = false;
                    if (FfaQueueStatus == "lobby") FfaQueueStatus = "";
                    CompetitiveUI.ShowNotification("Your FFA lobby closed.", new Color(1f, 0.75f, 0.4f), 6f);
                }
                else if (!serverSpoke)
                {
                    // Transport failure — the request may have COMMITTED
                    // (possibly AFTER this callback: a timed-out handler can
                    // still be queued behind a lock server-side, round-2
                    // plausible find). Adopt the intended belief when we know
                    // it (join), and keep polling through a 90s ambiguity
                    // window so a late commit surfaces instead of becoming a
                    // hidden seat.
                    if (!string.IsNullOrEmpty(intendedLobbyId))
                        OpenFfaLobbyId = intendedLobbyId;
                    _ffaAmbiguousPollUntil = Time.unscaledTime + 90f;
                    IsFfaQueuePolling = true;
                    UpdateFfaQueuePoll(force: true);
                }
                else
                    CompetitiveUI.ShowNotification(DetailOr(resp, "Couldn't join that lobby."), new Color(1f, 0.6f, 0.2f), 5f);
            }
            FetchFfaLobbies(force: true);
            NativeUI.MarkDirty();
        }

        public static void FfaCreateLobby(string password = null)
        {
            if (SpectatorBlocksQueue()) return;   // r4: the one enrollment POST that lacked the guard
            NoteQueueRequestInFlight();
            if (password != null && password.Length > 64)
            {
                // Server 400s over 64 (LOBBY_PASSWORD_MAX_LEN) — say it plainly.
                CompetitiveUI.ShowNotification(I18n.Tr("Password must be 64 characters or fewer."), new Color(1f, 0.6f, 0.2f), 5f);
                return;
            }
            if (!FfaLobbyActionPreflight(out string sid)) return;
            _ffaLeaveIntent = false;
            _ffaLastLobbyPassword = password;
            int gen = ++ffaGen;
            FfaLobbyActionBegin(); int actionGen = _ffaLobbyActionGen;
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ffa/lobby/create", FfaLobbyBody(sid, null, password), (ok, resp) =>
            {
                FfaLobbyActionEnd(actionGen);
                if (gen != ffaGen) return;
                if (ok) FfaLobbyIsHost = true;
                FfaEnrollResult(ok, resp, null, wasRecovery: false);
            }));
        }

        public static void FfaJoinLobby(string lobbyId, string password = null)
        {
            if (SpectatorBlocksQueue()) return;
            NoteQueueRequestInFlight();   // r3: WATCH is blocked for the whole join round-trip   // design §3.1
            if (string.IsNullOrEmpty(lobbyId)) return;
            if (password != null && password.Length > 64)
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Password must be 64 characters or fewer."), new Color(1f, 0.6f, 0.2f), 5f);
                return;
            }
            if (!FfaLobbyActionPreflight(out string sid)) return;
            bool wasRecovery = OpenFfaLobbyId == lobbyId;
            if (!wasRecovery) _ffaLeaveIntent = false;
            _ffaLastLobbyPassword = password;
            int gen = ++ffaGen;
            FfaLobbyActionBegin(); int actionGen = _ffaLobbyActionGen;
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ffa/lobby/join", FfaLobbyBody(sid, lobbyId, password), (ok, resp) =>
            {
                FfaLobbyActionEnd(actionGen);
                if (gen != ffaGen) return;
                FfaEnrollResult(ok, resp, lobbyId, wasRecovery);
            }));
        }

        public static void FfaStartLobby()
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            // Same watchdog discipline as create/join (round-2 find: Start
            // neither stamped nor released, so one lost callback blocked
            // every later Start for the membership).
            if (_ffaLobbyActionInFlight && Time.realtimeSinceStartup - _ffaLobbyActionAt > 30f)
                _ffaLobbyActionInFlight = false;
            if (_ffaLobbyActionInFlight) return;
            int gen = ffaGen;   // NOT ++: starting must not orphan the poll lifecycle
            FfaLobbyActionBegin(); int actionGen = _ffaLobbyActionGen;
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ffa/lobby/start",
                $"{{\"steam_id\":\"{sid}\"}}", (ok, resp) =>
            {
                FfaLobbyActionEnd(actionGen);
                if (gen != ffaGen) return;
                if (!ok)
                {
                    Plugin.Log.LogWarning($"[FFA-LOBBY] start failed: {resp}");
                    CompetitiveUI.ShowNotification(DetailOr(resp, "Couldn't start the game."),
                        new Color(1f, 0.6f, 0.2f), 5f);
                    NativeUI.MarkDirty();
                    return;
                }
                // The response IS the ready_join payload — the very next poll
                // would deliver the same thing; hand it to the poll handler's
                // logic by just letting the 2s poll pick it up (keeps ONE
                // room-join code path). Nothing to do here but log.
                Plugin.Log.LogInfo("[FFA-LOBBY] start accepted — lock lands via the poll");
            }));
        }

        /// <summary>Host changes one lobby setting. Sends ONLY the changed
        /// field; the server validates + clamps and returns the effective
        /// values, which we adopt immediately so the panel reflects reality
        /// (§7d clamp-up contract) without waiting for the next poll.</summary>
        public static void FfaSetLobbySetting(string field, int intValue, bool boolValue = false, bool isBool = false)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            if (_ffaLobbyActionInFlight && Time.realtimeSinceStartup - _ffaLobbyActionAt > 30f)
                _ffaLobbyActionInFlight = false;
            if (_ffaLobbyActionInFlight) return;
            int gen = ffaGen;
            FfaLobbyActionBegin(); int actionGen = _ffaLobbyActionGen;
            string val = isBool ? (boolValue ? "true" : "false") : intValue.ToString();
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ffa/lobby/settings",
                $"{{\"steam_id\":\"{sid}\",\"{field}\":{val}}}", (ok, resp) =>
            {
                FfaLobbyActionEnd(actionGen);
                if (gen != ffaGen) return;
                if (!ok)
                {
                    Plugin.Log.LogWarning($"[FFA-LOBBY] settings change failed: {resp}");
                    CompetitiveUI.ShowNotification(DetailOr(resp, "Couldn't change that setting."),
                        new Color(1f, 0.6f, 0.2f), 5f);
                    NativeUI.MarkDirty();
                    return;
                }
                int t = ExtractJsonInt(resp, "score_target"); if (t > 0) FfaLobbyCfgTarget = t;
                int cd = ExtractJsonInt(resp, "card_candidates"); if (cd > 0) FfaLobbyCfgCand = cd;
                int p = ExtractJsonInt(resp, "initial_picks"); if (p > 0) FfaLobbyCfgPicks = p;
                int c = ExtractJsonInt(resp, "card_cap"); if (c > 0) FfaLobbyCfgCap = c;
                FfaLobbyCfgSame = ExtractJsonBool(resp, "same_card_rule");
                FfaLobbyCfgSudden = ExtractJsonBool(resp, "sudden_death");
                FfaLobbyCfgRanked = !resp.Contains("\"lobby_ranked\":false");
                // A real change arms the 60s server gate — mirror it now; the
                // next poll re-syncs the authoritative remainder.
                if (resp.Contains("\"changed\":[") && !resp.Contains("\"changed\":[]"))
                {
                    FfaLobbySettingsLockSeconds = 60;
                    _ffaLobbyLockAnchorAt = Time.unscaledTime;
                }
                NativeUI.MarkDirty();
            }));
        }

        public static void FetchFfaLobbies(bool force = false)
        {
            if (!force && Time.unscaledTime - _ffaLobbiesLastAt < 3f) return;
            _ffaLobbiesLastAt = Time.unscaledTime;
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ffa/lobbies?steam_id={Escape(MatchTracker.LocalSteamId)}", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp))
                {
                    // Old server / outage: show "unavailable", never eternal
                    // "Loading..." (impl review find 8).
                    FfaLobbiesUnavailable = true;
                    if (CachedFfaLobbies == null) CachedFfaLobbies = new List<FfaOpenLobbyEntry>();
                    NativeUI.MarkDirty();
                    return;
                }
                FfaLobbiesUnavailable = false;
                try
                {
                    var list = new List<FfaOpenLobbyEntry>();
                    int aStart = resp.IndexOf("\"lobbies\"");
                    int arrStart = aStart >= 0 ? resp.IndexOf('[', aStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        foreach (string obj in SliceTopLevelObjects(resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                        {
                            var e = new FfaOpenLobbyEntry
                            {
                                lobby_id = ExtractJsonString(obj, "lobby_id"),
                                host_name = ExtractJsonString(obj, "host_name") ?? "?",
                                player_count = ExtractJsonInt(obj, "player_count"),
                                max_players = Math.Max(1, ExtractJsonInt(obj, "max_players")),
                                age_seconds = ExtractJsonInt(obj, "age_seconds"),
                                has_password = ExtractJsonBool(obj, "has_password"),
                                members = ParseBrowserMembers(obj),
                                bets_open = ExtractJsonBool(obj, "bets_open"),
                                bet_targets = ParseBetTargets(obj),
                                my_bet_amount = ExtractJsonInt(obj, "my_bet_amount"),
                                my_bet_targets = ExtractJsonString(obj, "my_bet_targets") ?? "",
                            };
                            if (!string.IsNullOrEmpty(e.lobby_id)) list.Add(e);
                        }
                    }
                    CachedFfaLobbies = list;
                    NativeUI.MarkDirty();
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[FFA-LOBBY] browser parse: {ex.Message}"); }
            }));
        }

        /// <summary>One-shot membership discovery (design review find 6): a
        /// relaunched client whose server row still exists must find it. Runs
        /// on FFA-tab open; harmless when nothing is held (the poll returns
        /// not_in_queue with no lobby belief -> polling just stops).</summary>
        private static bool _ffaProbed = false;
        public static void FfaProbeServerState()
        {
            if (_ffaProbed || IsFfaQueuePolling) { _ffaProbed = true; return; }
            _ffaProbed = true;
            IsFfaQueuePolling = true;
            UpdateFfaQueuePoll(force: true);
        }

        /// <summary>cause (round-9 gate): "in_room_exit" when fired by the
        /// room-exit hook (the leaver was demonstrably IN the ffa_ room, so
        /// the server must never classify it as failed assembly); anything
        /// else / empty = pre-room (menu leave, decline, watchdog).</summary>
        public static void FfaLeaveQueue(string cause = "")
        {
            string sid = MatchTracker.LocalSteamId;
            // Durable-cause bookkeeping (round-10 finds 1+3): a tagged call
            // records/upgrades the stored cause even when a leave is already
            // in flight (the room-exit hook fires AFTER a teardown's own
            // leave and used to be discarded whole); an untagged call
            // inherits it so every retry path re-sends the attestation.
            if (cause == "in_room_exit") _ffaLeaveCause = cause;
            if (FfaQueueStatus == "leaving") return;
            if (string.IsNullOrEmpty(cause)) cause = _ffaLeaveCause;
            else _ffaLeaveCause = cause;
            // Capture the expected target BEFORE any clears (impl review find
            // 2: the old order captured after clearing ActiveFfaLobbyId, so a
            // locked-lobby leave carried no expected id and no recovery
            // anchor). Explicit leave = standing intent: every later signal
            // bends toward OUT until an ack or an authoritative not_in_queue.
            string expectedLobby = !string.IsNullOrEmpty(OpenFfaLobbyId) ? OpenFfaLobbyId : ActiveFfaLobbyId;
            _ffaLeaveIntent = true;
            if (!string.IsNullOrEmpty(expectedLobby)) _ffaLeaveTargetLobby = expectedLobby;
            // Bug #132 fencing: a leave abandons any pending start countdown.
            _ffaJoinCountdownKey = null;
            _ffaJoinCountdownActiveToken = 0;
            CompetitiveUI.CancelFfaStartCountdown();
            IsFfaQueuePolling = false; FfaQueueCount = 0; FfaGatherSecondsLeft = -1;
            FfaLockedRoster = null;
            ActiveFfaLobbyId = null;
            FfaMySlot = -1; FfaLobbyPlayerCount = 0;
            FfaLobbyIsHost = false; FfaLobbyCanStart = false;
            FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
            Plugin.ClearPendingFfaSlot();
            // A pending ffa_ room join must die with the membership (impl
            // review find 5: QueueRoomJoiner could still fire its captured
            // JoinOrCreateRoom after a successful leave).
            try { if ((Plugin.PendingRankedRoom ?? "").StartsWith("ffa_")) Plugin.ClearPendingRoom(); } catch { }
            if (string.IsNullOrEmpty(sid) || sid == "unknown") { FfaQueueStatus = ""; OpenFfaLobbyId = null; _ffaLeaveIntent = false; return; }
            int gen = ++ffaGen;
            FfaQueueStatus = "leaving";
            _ffaLeavingSince = Time.realtimeSinceStartup;
            NativeUI.MarkDirty();
            string url = $"{baseUrl}/api/v1/ffa/queue/leave?steam_id={UnityWebRequest.EscapeURL(sid)}";
            if (!string.IsNullOrEmpty(expectedLobby))
                url += $"&expected_lobby_id={UnityWebRequest.EscapeURL(expectedLobby)}";
            if (!string.IsNullOrEmpty(cause))
                url += $"&cause={UnityWebRequest.EscapeURL(cause)}";
            Plugin.Instance.StartCoroutine(PostRequestWithRetry(url, "",
                (ok, resp) =>
                {
                    if (gen != ffaGen) return;
                    if (ok)
                    {
                        OpenFfaLobbyId = null;
                        _ffaLeaveIntent = false;
                        _ffaLeaveTargetLobby = null;
                        _ffaLeaveCause = "";
                        Plugin.Log.LogInfo("[FFA] Left FFA queue/lobby");
                    }
                    else
                    {
                        // Keep the belief AND the intent: the poll re-arm lets
                        // the server state win — a surviving seat triggers a
                        // leave RETRY (intent), a dead row clears us silently.
                        Plugin.Log.LogWarning($"[FFA] Leave failed after retries: {resp} — re-arming the poll to recover");
                        OpenFfaLobbyId = OpenFfaLobbyId ?? expectedLobby;
                        IsFfaQueuePolling = !string.IsNullOrEmpty(OpenFfaLobbyId);
                        CompetitiveUI.ShowNotification("Couldn't confirm FFA leave — the server will clear you shortly.", new Color(1f, 0.6f, 0.2f), 5f);
                    }
                    if (FfaQueueStatus == "leaving") FfaQueueStatus = "";
                    UpdateFfaQueueList(force: true);
                    FetchFfaLobbies(force: true);
                    NativeUI.MarkDirty();
                },
                maxRetries: 3, retryDelay: 2f));
        }

        /// <summary>Throttled FFA queue poll — ticked from the plugin-level
        /// always-on loop AND the FFA tab ticker (2s throttle shared). On
        /// ready_join: records lobby/slot, publishes pre-join props, joins
        /// the ffa_ room via SetPendingRoom.</summary>
        public static void UpdateFfaQueuePoll(bool force)
        {
            if (!IsFfaQueuePolling) return;
            // Ambiguity-window expiry must not depend on a SUCCESSFUL poll
            // response (round-3 find E1): with the server unreachable, a
            // belief-less ambiguity poll would otherwise dispatch forever.
            // Fires only when a window was actually armed; the one-shot probe
            // and all belief-carrying polling are untouched.
            if (_ffaAmbiguousPollUntil > 0f
                && Time.unscaledTime > _ffaAmbiguousPollUntil
                && string.IsNullOrEmpty(OpenFfaLobbyId)
                && string.IsNullOrEmpty(ActiveFfaLobbyId)
                && !_ffaLeaveIntent)
            {
                _ffaAmbiguousPollUntil = -999f;
                IsFfaQueuePolling = false;
                if (FfaQueueStatus != "leaving") FfaQueueStatus = "";
                Plugin.Log.LogInfo("[FFA-LOBBY] ambiguity window lapsed with no resolution — stopping the probe poll");
                NativeUI.MarkDirty();
                return;
            }
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            if (!force && Time.unscaledTime - _ffaLastPollAt < 2f) return;
            _ffaLastPollAt = Time.unscaledTime;
            int gen = ffaGen;
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ffa/queue/poll/{sid}", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                if (!IsFfaQueuePolling) return;
                if (gen != ffaGen) return;
                string status = ExtractJsonString(resp, "status") ?? "";
                FfaQueueStatus = status;
                FfaQueueCount = ExtractJsonInt(resp, "queue_count");
                if (status == "searching")
                {
                    int gsl = -1;
                    try { gsl = resp.Contains("\"gather_seconds_left\"") ? ExtractJsonInt(resp, "gather_seconds_left") : -1; } catch { }
                    FfaGatherSecondsLeft = gsl;
                    // A NEW client never wants a legacy searching row (impl
                    // review finds 5+7): it appears when a dissolved active
                    // lobby reset us, or when the probe found a pre-update
                    // remnant. Clear every belief and delete the row — the
                    // auto-gather is retired in this client.
                    bool hadBelief = !string.IsNullOrEmpty(OpenFfaLobbyId)
                                     || !string.IsNullOrEmpty(ActiveFfaLobbyId)
                                     || Plugin.PendingFfaSlot >= 0;
                    OpenFfaLobbyId = null; ActiveFfaLobbyId = null;
                    FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                    FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                    FfaMySlot = -1; FfaLobbyPlayerCount = 0;
                    FfaLockedRoster = null;
                    Plugin.ClearPendingFfaSlot();
                    if (hadBelief)
                        CompetitiveUI.ShowNotification("Your FFA lobby closed.", new Color(1f, 0.75f, 0.4f), 6f);
                    Plugin.Log.LogInfo($"[FFA-LOBBY] legacy searching row detected (belief={hadBelief}) — leaving it");
                    FfaLeaveQueue();
                    NativeUI.MarkDirty();
                    return;
                }
                if (status == "lobby")
                {
                    // A LOCK outranks a lobby-status response (Codex round-3
                    // regression 2): a delayed pre-Start poll response landing
                    // after ready_join would otherwise repopulate
                    // OpenFfaLobbyId — and the room-entry hook then reads that
                    // stale open seat as foreign and dissolves our own live
                    // lobby the moment we enter its ffa_ room.
                    if (!string.IsNullOrEmpty(ActiveFfaLobbyId)) return;
                    // Leave intent outranks membership (impl review find 2):
                    // the seat still existing means the leave never landed —
                    // retry it instead of re-adopting.
                    if (_ffaLeaveIntent)
                    {
                        if (Time.unscaledTime - _ffaLeaveRetryAt > 10f)
                        {
                            _ffaLeaveRetryAt = Time.unscaledTime;
                            Plugin.Log.LogWarning("[FFA-LOBBY] leave intent pending but seat still exists — retrying leave");
                            FfaLeaveQueue();
                        }
                        return;
                    }
                    // Level-triggered room exclusion (impl review find 3),
                    // narrowed for bug #132 (Snail + Sid's design): an OPEN
                    // lobby seat is a waiting-room ticket, and waiting in a
                    // CASUAL game is explicitly allowed — the seat only
                    // becomes incompatible with a room when that room is
                    // competitive (ranked/2v2/1v2/ffa/tournament), where a
                    // lock firing mid-match would yank the player (#150).
                    // The gate re-fires every poll — no missed edges.
                    bool inCompetitiveRoomNow = false;
                    try
                    {
                        inCompetitiveRoomNow = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode
                            && CompetitiveRoomDetect.IsCompetitiveRoom();
                    }
                    catch { }
                    if (inCompetitiveRoomNow)
                    {
                        Plugin.Log.LogWarning("[FFA-LOBBY] in a competitive room while holding a lobby seat — leaving the lobby");
                        FfaLeaveQueue();
                        return;
                    }
                    // Open host-lobby membership (July 29 redesign).
                    _ffaAmbiguousPollUntil = -999f;   // resolved — the seat exists
                    OpenFfaLobbyId = ExtractJsonString(resp, "lobby_id") ?? OpenFfaLobbyId;
                    FfaLobbyIsHost = ExtractJsonBool(resp, "is_host");
                    FfaLobbyCanStart = ExtractJsonBool(resp, "can_start");
                    FfaLobbyMemberCount = ExtractJsonInt(resp, "player_count");
                    int minP = ExtractJsonInt(resp, "min_players"); if (minP > 0) FfaLobbyMinPlayers = minP;
                    int maxP = ExtractJsonInt(resp, "max_players"); if (maxP > 0) FfaLobbyMaxPlayers = maxP;
                    // v1.36 lobby config + settings-lock (flat scalars, #73;
                    // absent on an old server -> zeros keep the defaults).
                    int cfgT = ExtractJsonInt(resp, "score_target"); if (cfgT > 0) FfaLobbyCfgTarget = cfgT;
                    int cfgCand = ExtractJsonInt(resp, "card_candidates"); if (cfgCand > 0) FfaLobbyCfgCand = cfgCand;
                    int cfgP = ExtractJsonInt(resp, "initial_picks"); if (cfgP > 0) FfaLobbyCfgPicks = cfgP;
                    int cfgC = ExtractJsonInt(resp, "card_cap"); if (cfgC > 0) FfaLobbyCfgCap = cfgC;
                    FfaLobbyCfgSame = ExtractJsonBool(resp, "same_card_rule");
                FfaLobbyCfgSudden = ExtractJsonBool(resp, "sudden_death");
                    FfaLobbyCfgRanked = !resp.Contains("\"lobby_ranked\":false");
                    FfaLobbySettingsLockSeconds = Math.Max(0, ExtractJsonInt(resp, "settings_lock_seconds"));
                    _ffaLobbyLockAnchorAt = Time.unscaledTime;
                    try
                    {
                        var members = new List<FfaLobbyMemberEntry>();
                        int mStart = resp.IndexOf("\"members\"");
                        int arrStart = mStart >= 0 ? resp.IndexOf('[', mStart) : -1;
                        int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                        if (arrStart >= 0 && arrEnd > arrStart)
                        {
                            foreach (string obj in SliceTopLevelObjects(resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                            {
                                members.Add(new FfaLobbyMemberEntry
                                {
                                    steam_id = ExtractJsonString(obj, "steam_id"),
                                    display_name = ExtractJsonString(obj, "display_name") ?? "?",
                                    rating = ExtractJsonInt(obj, "rating"),
                                    rating_1v1 = ExtractJsonInt(obj, "rating_1v1"),
                                    wait_seconds = ExtractJsonInt(obj, "wait_seconds"),
                                    is_host = ExtractJsonBool(obj, "is_host"),
                                });
                            }
                        }
                        FfaLobbyMembers = members;
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[FFA-LOBBY] member parse: {ex.Message}"); }
                }
                else if (status == "lobby_closed")
                {
                    // Authoritative terminal: the lobby we sat in is gone
                    // (disband, janitor, or we were pruned at start).
                    Plugin.Log.LogInfo($"[FFA-LOBBY] lobby closed server-side (was {OpenFfaLobbyId})");
                    _ffaJoinCountdownKey = null;
                    _ffaJoinCountdownActiveToken = 0;
                    CompetitiveUI.CancelFfaStartCountdown();
                    OpenFfaLobbyId = null; FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                    FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                    IsFfaQueuePolling = false; FfaQueueStatus = "";
                    CompetitiveUI.ShowNotification("Your FFA lobby closed.", new Color(1f, 0.75f, 0.4f), 6f);
                    FetchFfaLobbies(force: true);
                }
                if (status == "ready_join")
                {
                    // Leave intent outranks a racing Start (impl review find
                    // 2): the player asked OUT before the lock landed —
                    // leaving now uses the legacy ready_join dissolution.
                    if (_ffaLeaveIntent)
                    {
                        Plugin.Log.LogWarning("[FFA-LOBBY] ready_join landed after a leave request — leaving instead of joining");
                        FfaLeaveQueue();
                        NativeUI.MarkDirty();
                        return;
                    }
                    // Countdown re-fire suppression (Codex batch find 6):
                    // polling now stays ON through the 5s start countdown so a
                    // REMOTE dissolution can still reach us — which means this
                    // branch re-enters every ~2s while the countdown runs.
                    // Same lobby+room with a live countdown is not a new
                    // event: skip before the busy checks (or the casual-room
                    // leave would re-fire) and without touching the
                    // loop-breaker counter.
                    string cdLobby = ExtractJsonString(resp, "lobby_id") ?? "";
                    string cdRoom = ExtractJsonString(resp, "room_name") ?? "";
                    if (_ffaJoinCountdownKey != null
                        && _ffaJoinCountdownKey == cdLobby + "|" + cdRoom
                        && _ffaJoinCountdownActiveToken != 0
                        && Time.realtimeSinceStartup - _ffaJoinCountdownArmedAt < 12f)
                    {
                        return;
                    }
                    // Mid-game rejoin refusal (Codex round-4 find F1): a
                    // ready_join carrying game_in_progress means a battle is
                    // LIVE among the other members while WE are at the menu —
                    // i.e. we are the crashed/relaunched seat. A reset client
                    // cannot reconstruct the missed deck/phase state (its
                    // roster spot is already frozen as departed for
                    // reporting, #227), so joining now only desyncs the room.
                    // The gate excludes a client already IN that room (the
                    // post-ready_join cancel-detector polls through game 1's
                    // start — that client must not tear itself down).
                    {
                        bool inThatRoom = false;
                        try
                        {
                            inThatRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode
                                && PhotonNetwork.CurrentRoom?.Name == cdRoom;
                        }
                        catch { }
                        if (!inThatRoom && resp.Contains("\"game_in_progress\":true"))
                        {
                            Plugin.Log.LogWarning("[FFA] ready_join for a lobby whose game is LIVE — refusing rejoin (relaunched seat)");
                            FfaLeaveQueue();
                            CompetitiveUI.ShowNotification("Your FFA match continued without you - you've been removed from it.", new Color(1f, 0.7f, 0.3f), 8f);
                            NativeUI.MarkDirty();
                            return;
                        }
                        // STARTUP-UNKNOWN (round-5 gate find): the server just
                        // restarted and cannot yet say whether a game is live.
                        // Neither join NOR leave — wait; the next poll (2-3s)
                        // re-asks, and the server's window resolves within
                        // ~210s worst case. Acting on unknown was what made
                        // an API restart dissolve every fresh FFA.
                        if (!inThatRoom && resp.Contains("\"game_in_progress\":null"))
                        {
                            Plugin.Log.LogInfo("[FFA] ready_join with game_in_progress UNKNOWN (server just restarted) — waiting for the next poll");
                            return;
                        }
                    }
                    // Consent guard: decline a lock that lands mid-COMPETITIVE-game
                    // (#150). A CASUAL room is different since bug #132: waiting
                    // in casual with an open lobby seat is allowed, and the
                    // host pressing Start is the consent — kick out of the
                    // casual game immediately (Sid's design), then the 5s
                    // countdown below runs before the FFA room join.
                    bool busyInRoom = false, busyCasual = false;
                    try
                    {
                        busyInRoom = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode;
                        busyCasual = busyInRoom && !CompetitiveRoomDetect.IsCompetitiveRoom();
                    }
                    catch { }
                    if (busyInRoom && !busyCasual)
                    {
                        Plugin.Log.LogWarning("[FFA] ready_join landed while in a competitive room — declining (leaving FFA queue)");
                        FfaLeaveQueue();
                        CompetitiveUI.ShowNotification("FFA match found, but you're in a game — removed from the FFA queue.", new Color(1f, 0.7f, 0.3f), 7f);
                        NativeUI.MarkDirty();
                        return;
                    }
                    if (busyCasual)
                    {
                        Plugin.Log.LogInfo("[FFA] host started the FFA while we're in a casual game — leaving it now (#132)");
                        try
                        {
                            // Deliberate exit: never a DC loss on the casual tally.
                            GameStateWatcher.LeavingForRanked = true;
                            PhotonNetwork.LeaveRoom();
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[FFA] casual-room leave: {ex.Message}"); }
                    }
                    // NOTE: polling deliberately stays ON here (Codex batch
                    // find 6) — it is the only channel that can tell us the
                    // lobby was cancelled by ANOTHER member's leave during the
                    // countdown. DelayedFfaRoomJoin turns it off at fire time.
                    ActiveFfaLobbyId = ExtractJsonString(resp, "lobby_id");
                    // The open-lobby membership just became a LOCKED lobby —
                    // clear the open belief or the room-join teardown would
                    // "leave" our own game the moment we enter the ffa_ room.
                    OpenFfaLobbyId = null;
                    FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                    FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                    FfaMySlot = ExtractJsonInt(resp, "slot");
                    FfaLobbyPlayerCount = ExtractJsonInt(resp, "player_count");
                    string room = ExtractJsonString(resp, "room_name");
                    string region = ExtractJsonString(resp, "room_region");
                    var roster = ExtractTeamMemberList(resp, "players");
                    FfaLockedRoster = roster;
                    // v1.36 frozen lobby config — flat scalars (#73), from the
                    // server's row (the authority). Absent fields (old server)
                    // extract as 0/false and the setter's clamps keep defaults.
                    try
                    {
                        int cfgTarget = ExtractJsonInt(resp, "score_target");
                        int cfgCand = ExtractJsonInt(resp, "card_candidates");
                        int cfgPicks = ExtractJsonInt(resp, "initial_picks");
                        int cfgCap = ExtractJsonInt(resp, "card_cap");
                        bool cfgSame = ExtractJsonBool(resp, "same_card_rule");
                        bool cfgRanked = !resp.Contains("\"lobby_ranked\":false");
                        // Aug 6 item 10: sudden death. Absent/false from an
                        // older server (or a roster the server collapsed for
                        // capability) reads as FALSE, which is the only safe
                        // direction — a client that armed the rule while its
                        // peers had not would suppress damage they applied.
                        bool cfgSudden = ExtractJsonBool(resp, "sudden_death");
                        if (cfgTarget > 0)
                            FfaMode.SetPendingConfig(cfgTarget, cfgCand > 0 ? cfgCand : 5,
                                cfgPicks > 0 ? cfgPicks : 1, cfgCap > 0 ? cfgCap : 5,
                                cfgSame, cfgRanked, cfgSudden);
                    }
                    catch (Exception cfgEx) { Plugin.Log.LogWarning($"[FFA] config parse: {cfgEx.Message}"); }

                    if (!string.IsNullOrEmpty(room))
                    {
                        // Loop-breaker (July 28 trapped-lobby incident): if
                        // this exact lobby+room keeps re-firing (dead room,
                        // wedged server row, failed joins re-arming the
                        // poll), stop after 3 attempts and LEAVE — the leave
                        // endpoint dissolves/closes the lobby server-side,
                        // freeing the whole group. The menu also stops being
                        // slammed shut by the auto-close below.
                        string fireKey = (ActiveFfaLobbyId ?? "") + "|" + room;
                        if (fireKey == _ffaLastReadyFireKey) _ffaReadyFireCount++;
                        else { _ffaLastReadyFireKey = fireKey; _ffaReadyFireCount = 1; }
                        if (_ffaReadyFireCount > 3)
                        {
                            Plugin.Log.LogWarning($"[FFA] ready_join re-fired {_ffaReadyFireCount}x for '{room}' — giving up and leaving the FFA queue");
                            CompetitiveUI.ShowNotification("Couldn't join the FFA match — left the queue. Please requeue.", Color.yellow, 8f);
                            FfaLeaveQueue();
                            NativeUI.MarkDirty();
                            return;
                        }
                        Plugin.SetPendingFfaSlot(FfaMySlot, FfaLobbyPlayerCount);
                        try
                        {
                            var prejoin = new ExitGames.Client.Photon.Hashtable();
                            prejoin["p_id"] = FfaMySlot;
                            prejoin["t_id"] = FfaMySlot;   // FFA: every player own team
                            prejoin["u_id"] = sid;
                            // Capability advert (rope-scale fix): the map-object
                            // rescale keys off the MASTER's copy of this prop —
                            // pre-join so it rides the Player record and can
                            // never race a peer's map load (#79 pattern).
                            prejoin[FfaMapScale.ScaleCapabilityProp] = 1;
                            // Config/same-card feature level (v1.36): the
                            // same-card engine runs only when EVERY room member
                            // advertises this (#273 all-players rule).
                            prejoin[FfaCardSequence.CapabilityProp] = FfaCardSequence.FeatureLevel;
                            if (PhotonNetwork.LocalPlayer != null)
                                PhotonNetwork.LocalPlayer.SetCustomProperties(prejoin);
                        }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[FFA] pre-join SetCustomProperties: {ex.Message}"); }
                        try { NametagStyler.PublishToPhoton(); } catch (Exception ex) { Plugin.Log.LogWarning($"[FFA] pre-join nametag publish: {ex.Message}"); }
                        try { PlayerColorCosmetic.PublishLocalProps(); } catch (Exception ex) { Plugin.Log.LogWarning($"[FFA] pre-join pcolor publish: {ex.Message}"); }
                        try { TrailCosmetic.PublishLocalProps(); } catch (Exception ex) { Plugin.Log.LogWarning($"[FFA] pre-join trail publish: {ex.Message}"); }

                        // Bug #132 (Sid's design): a 5-second on-screen countdown
                        // between the host's Start and the actual room join, so
                        // nobody — especially a member just yanked out of a
                        // casual game — is teleported with zero warning. The
                        // deferred join re-checks generation, leave intent AND
                        // lobby identity so a Leave clicked during the countdown
                        // or a remote dissolution observed by the (still-live)
                        // poll wins over the join (#252e / Codex find 6).
                        _ffaJoinCountdownKey = (ActiveFfaLobbyId ?? "") + "|" + room;
                        int cdToken = ++_ffaJoinCountdownToken;
                        _ffaJoinCountdownActiveToken = cdToken;
                        _ffaJoinCountdownArmedAt = Time.realtimeSinceStartup;
                        CompetitiveUI.ShowFfaStartCountdown(5f);
                        Plugin.Log.LogInfo($"[FFA] Lobby locked! Room: {room} (region: {region ?? "auto"}) lobby={ActiveFfaLobbyId} slot={FfaMySlot} players={FfaLobbyPlayerCount} — joining in 5s");
                        CompetitiveUI.ShowNotification(I18n.TrF("{0}-player FFA starting in 5 seconds!", FfaLobbyPlayerCount), Color.green, 5f);
                        try { if (NativeUI.IsOpen) NativeUI.Close(); } catch { }
                        Plugin.Instance.StartCoroutine(DelayedFfaRoomJoin(room, region, gen, ActiveFfaLobbyId, cdToken, 5f));
                    }
                }
                else if (status == "not_in_queue" || status == "expired")
                {
                    IsFfaQueuePolling = false; FfaQueueStatus = "";
                    FfaLockedRoster = null;
                    // Full teardown (impl review find 5): a dead row means NO
                    // live commitment — stale lock state here caused repeated
                    // roomless-poll recovery loops and a QueueRoomJoiner that
                    // could still fire into a canceled Photon room.
                    _ffaJoinCountdownKey = null;
                    _ffaJoinCountdownActiveToken = 0;
                    CompetitiveUI.CancelFfaStartCountdown();
                    ActiveFfaLobbyId = null;
                    FfaMySlot = -1; FfaLobbyPlayerCount = 0;
                    FfaLobbyIsHost = false; FfaLobbyCanStart = false;
                    FfaLobbyMembers = null; FfaLobbyMemberCount = 0;
                    Plugin.ClearPendingFfaSlot();
                    try { if ((Plugin.PendingRankedRoom ?? "").StartsWith("ffa_")) Plugin.ClearPendingRoom(); } catch { }
                    // 30-min server cap (July 28) — explicit reason, and no
                    // auto-rejoin for this status (that would defeat the cap).
                    if (status == "expired")
                        CompetitiveUI.ShowNotification(
                            "Removed from FFA queue after 30 minutes of searching - rejoin if you're still here!",
                            Color.yellow, 7f);
                    // A pending explicit leave reaching not_in_queue means the
                    // leave LANDED (its ack was just lost) — clear the belief
                    // silently; re-enrolling an explicit leaver is the one
                    // thing recovery must never do (impl review find 2).
                    if (_ffaLeaveIntent)
                    {
                        _ffaLeaveIntent = false;
                        _ffaLeaveTargetLobby = null;
                        _ffaLeaveCause = "";
                        OpenFfaLobbyId = null;
                        NativeUI.MarkDirty();
                        return;
                    }
                    // Ambiguity window after a transport-failed CREATE (no id
                    // to re-join): the enroll may still commit behind a lock
                    // server-side — keep polling so it surfaces as 'lobby'
                    // instead of becoming a hidden seat (round-2 plausible
                    // find). Joins carry a belief and use the rejoin path.
                    // 'expired' is TERMINAL and kills the window instead of
                    // re-arming it (round-3 find E2 — the 30-min cap must
                    // never turn into another 90s of polling).
                    if (status == "expired")
                        _ffaAmbiguousPollUntil = -999f;
                    if (status == "not_in_queue"
                        && string.IsNullOrEmpty(OpenFfaLobbyId)
                        && Time.unscaledTime < _ffaAmbiguousPollUntil)
                    {
                        IsFfaQueuePolling = true;
                        NativeUI.MarkDirty();
                        return;
                    }
                    // Ghost-prune recovery, lobby edition (design review finds
                    // 6+9): if we BELIEVE we're in an open lobby, attempt ONE
                    // same-lobby rejoin (idempotent server-side); the join's
                    // failure path converts a truly-gone lobby into the
                    // explicit closed toast. Never auto-CREATE, and never the
                    // legacy gather queue — that mechanism is retired in this
                    // client. Room gate matches the bug-#132 rule (Codex batch
                    // find 13): a CASUAL room may carry an open seat, so it
                    // must also be allowed to RECOVER one — the old
                    // any-room gate left a pruned seat looping unrecoverable
                    // for as long as the casual game lasted. Competitive rooms
                    // still block (#122/#150).
                    if (status == "not_in_queue"
                        && !string.IsNullOrEmpty(OpenFfaLobbyId)
                        && (!PhotonNetwork.InRoom || PhotonNetwork.OfflineMode
                            || !CompetitiveRoomDetect.IsCompetitiveRoom())
                        && Time.unscaledTime - _ffaLobbyRejoinAt > 60f)
                    {
                        _ffaLobbyRejoinAt = Time.unscaledTime;
                        Plugin.Log.LogWarning("[FFA-LOBBY] membership row vanished server-side — attempting same-lobby rejoin");
                        // Re-send the remembered password: a private lobby's
                        // recovery rejoin 403s without it (v1.37).
                        FfaJoinLobby(OpenFfaLobbyId, _ffaLastLobbyPassword);
                    }
                }
                NativeUI.MarkDirty();
            }));
        }

        // Suppression key for countdown-window ready_join re-fires (the poll
        // stays live through the countdown; Codex batch find 6). Ownership is
        // TOKEN-scoped (round-3 regressions 4/8): a superseded coroutine must
        // never clear a newer countdown's key/banner, and suppression keys off
        // the pending token — not the UI clock — so a deadline expiring a
        // frame before the coroutine wakes cannot admit a duplicate fire.
        private static string _ffaJoinCountdownKey;
        private static int _ffaJoinCountdownToken;        // monotonic issue counter
        private static int _ffaJoinCountdownActiveToken;  // 0 = none pending
        // Round-4 find 9: suppression must SELF-EXPIRE. The delayed-join
        // coroutine can die with its host (a NetworkRestart tears coroutine
        // hosts down) leaving the active token set forever — and a suppressed
        // ready_join returns BEFORE the loop-breaker counter, so nothing else
        // recovers. 12s > countdown (5s) + wake jitter, so a HEALTHY pending
        // countdown is never deduplicated away; a dead one lapses and the next
        // poll re-arms a fresh countdown (counting toward the loop-breaker).
        private static float _ffaJoinCountdownArmedAt = -999f;

        /// <summary>Bug #132: the FFA room join runs after the 5s start
        /// countdown. Hosted on Plugin.Instance — NOTE the coroutine itself
        /// can still die mid-wait (a NetworkRestart tears down in-flight
        /// coroutines, #252e); the suppression TTL above is what recovers
        /// from a dead pending countdown. Aborts
        /// when: a newer countdown superseded this one, the queue generation
        /// moved, an explicit leave was requested, the lobby belief changed
        /// (a remote dissolution observed by the still-running poll nulls
        /// ActiveFfaLobbyId — Codex find 6), a DIFFERENT mode armed the shared
        /// pending-room slot, or we are already sitting in a competitive room
        /// another flow joined (find 14 — never yank the player out of it).
        /// Every abort clears the countdown banner (find 15).
        ///
        /// ACCEPTED residual (round-3 find 6): a remote dissolution landing
        /// after our last ~2s poll observation but before the fire can still
        /// send us into the dead Photon room. That window was the ENTIRE
        /// pre-countdown behaviour (the join used to fire instantly with zero
        /// re-checks), so the countdown strictly narrowed it; the lonely-room
        /// watchdog recovers the tail.</summary>
        private static IEnumerator DelayedFfaRoomJoin(string room, string region, int gen,
                                                      string lobbyId, int myToken, float delay)
        {
            yield return new WaitForSecondsRealtime(delay);
            if (_ffaJoinCountdownActiveToken != myToken)
                yield break;   // superseded — the newer owner controls key/banner
            _ffaJoinCountdownActiveToken = 0;
            _ffaJoinCountdownKey = null;
            string pendingNow = null;
            try { pendingNow = Plugin.PendingRankedRoom; } catch { }
            bool foreignPending = !string.IsNullOrEmpty(pendingNow) && pendingNow != room;
            bool inCompetitiveRoomNow = false;
            try
            {
                inCompetitiveRoomNow = PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode
                    && CompetitiveRoomDetect.IsCompetitiveRoom();
            }
            catch { }
            if (gen != ffaGen || _ffaLeaveIntent
                || string.IsNullOrEmpty(ActiveFfaLobbyId) || ActiveFfaLobbyId != lobbyId
                || foreignPending || inCompetitiveRoomNow)
            {
                CompetitiveUI.CancelFfaStartCountdown();
                Plugin.Log.LogInfo("[FFA] start countdown aborted ("
                    + (foreignPending ? $"another join owns the room slot: {pendingNow}"
                        : inCompetitiveRoomNow ? "already in a competitive room"
                        : "leave requested, lobby gone, or queue lifecycle moved on")
                    + ")");
                yield break;
            }
            IsFfaQueuePolling = false;
            Plugin.SetPendingRoom(room, region);
        }

        // ── 2v2 / 1v2 host lobbies (v1.37 private-lobby client half) ───────
        // One generalized client mirroring the server's _LOBBY_MODE_CFG engine
        // and the FFA lobby machinery's shapes: leave-intent set BEFORE any
        // request with response-driven state clearing (#249), ambiguity
        // windows for transport-failed enrolls, level-triggered competitive-
        // room exclusion (#132 pattern), and the stuck-leave watchdog.
        //
        // HEARTBEAT CONTRACT: GET /{mode}/lobby/state is the server-side
        // lease-renewing heartbeat — a member whose polls stop for ~75s is
        // expired from the lobby (main.py _lobby_state_impl). Tick() is
        // driven from TickLeaveRecovery (the always-on Plugin.Update loop),
        // NOT from a tab ticker, so the seat survives a closed F5 menu
        // (learning #50's class).
        //
        // HANDOFF CONTRACT: after the host's Start, members' queue rows flip
        // to 'matched' (2v2) / 'ready_join' (1v2) and /lobby/state returns
        // not_in_lobby — indistinguishable from a disband. A confirmed member
        // seeing not_in_lobby therefore probes the mode's own /queue/poll and
        // resolves: matched/ready_join = STARTED (hand the flow to the normal
        // queue machinery, which owns ready-up / room issuance / reports);
        // 'searching' = the server reset our dead-lobby seat to a searching
        // queue row — leave it (never keep a queue the player didn't ask for,
        // #238); 'lobby' = transient disagreement, resume the state poll;
        // 'not_in_queue' = row gone — one same-lobby rejoin attempt (FFA
        // ghost-prune pattern), then declare the lobby closed;
        // 'lobby_closed' = seat lease expired server-side.
        public class HostLobbyMemberEntry
        {
            public string steam_id, display_name;
            public int rating, rating_1v1, wait_seconds, preferred_team, preferred_side;
            public bool is_host, solo_extra_pick;
        }
        public class HostLobbyOpenEntry
        {
            public string lobby_id, host_name;
            public int player_count, max_players, age_seconds;
            public bool has_password;
            public List<LobbyBrowserMember> members;   // Aug 8: who's inside (null on old server)
            // Aug 9: lobby-phase betting (2v2 only — the server never opens
            // bets on 1v2, and the browser gates on the mode as well).
            public bool bets_open;
            public List<LobbyBetTarget> bet_targets;
            public int my_bet_amount;
            public string my_bet_targets;
        }

        public sealed class HostLobbyClient
        {
            private readonly string mode;    // "team" | "ovt" — URL segment
            private readonly string label;   // "2v2" | "1v2" — user-facing + log tag
            private bool IsTeam => mode == "team";

            // Belief state (OpenLobbyId kept until a leave is ACKED or the
            // server authoritatively closes it — FFA design-review find 6).
            public string OpenLobbyId;
            public bool IsHost, CanStart, HasPassword;
            public int MemberCount, MaxPlayers;
            public List<HostLobbyMemberEntry> Members;
            public string Status = "";        // "" | "lobby" | "leaving"
            public bool Polling;              // the 2s /lobby/state heartbeat armed

            // Browser (with the FfaLobbiesUnavailable degradation, recon risk 6).
            public List<HostLobbyOpenEntry> CachedLobbies;
            public bool LobbiesUnavailable;

            private int gen;                  // lifecycle generation — see queueGen
            private bool leaveIntent;         // explicit leave = standing intent (#252e)
            private string leaveTarget;       // durable leave target (FFA round-2 find 2)
            private bool confirmedMember;     // enroll-ok or a state-poll 'lobby' seen
            private float leavingSince = -999f, lastPollAt = -999f, lobbiesLastAt = -999f;
            private float ambiguousUntil = -999f, rejoinAt = -999f, leaveRetryAt = -999f;
            private float handoffUntil = -999f, handoffProbeAt = -999f;
            private bool actionInFlight; private float actionAt = -999f; private int actionGen;
            private bool probed;
            // Codex r1 f5: a Start that converts the seat mid-leave re-targets
            // the standing leave intent at the LOCKED group. Lives on this
            // process-wide singleton, never in a callback closure (#252e), so
            // a NetworkRestart-killed request cannot lose it; Tick() retries.
            private bool queueLeaveIntent;
            private bool queueLeaveInFlight;
            private float queueLeaveAt = -999f, queueLeaveRetryAt = -999f;
            private int queueLeaveAttempts;
            // Codex r2 f3: the series INCARNATION the standing queue-leave is
            // aimed at, recorded when the intent is created (from the
            // "started" response / resolve answer that named it) and sent as
            // expected_series_id on every attempt — a delayed retry must
            // never tear down a NEWER enrollment. Null = legacy unfenced
            // (the searching-row dissolution path, which has no series).
            private string queueLeaveSeriesId;
            // Codex r2 f4/f6: seated preference PATCHes are a GENERATION-
            // tokened single-flight queue. One request in flight; the user's
            // latest desired value per field coalesces in prefsPending and
            // goes out when the ack lands; a response only clears in-flight
            // state when its generation matches the newest request. While
            // ANYTHING here is unacked, PrefsInFlight suppresses hydration
            // and the host's Start button.
            // F5 (Codex r3): each queued write also carries the lobby
            // INCARNATION the seat belonged to when it was QUEUED — sent as
            // expected_lobby_id so the server no-ops (409 not_in_open_lobby)
            // when the seat moved lobbies between enqueue and send.
            private sealed class PendingPref
            {
                public string FieldJson;
                public string LobbyId;   // captured at ENQUEUE, never at send
            }
            private bool prefsInFlight; private float prefsAt = -999f;
            private int prefsGen;
            private readonly Dictionary<string, PendingPref> prefsPending = new Dictionary<string, PendingPref>();
            private float prefsPumpRetryAt = -999f;
            // Codex r2 f5-residual: the caller's CURRENT structured
            // preferences — updated on every local selection (the static
            // wrappers) AND every prefs ack echo. Recovery rejoins build
            // their enrollment body from THESE, never from a join-time
            // extras snapshot that a later prefs change made stale.
            private int curPreferredTeam;              // team: 0 any / 1 / 2
            private int curPreferredSide;              // ovt: 0 any / 1 solo / 2 duo
            private bool curSoloExtraPick;
            // Remembered for recovery rejoins: a same-lobby rejoin of a
            // PRIVATE lobby must re-send the password or it 403s (a supplied
            // password on a public lobby is ignored server-side, so a stale
            // value is harmless).
            private string lastPassword;

            public HostLobbyClient(string mode, string label, int defaultPlayers)
            { this.mode = mode; this.label = label; MaxPlayers = defaultPlayers; }

            private void ActionBegin()
            { actionInFlight = true; actionAt = Time.realtimeSinceStartup; actionGen++; }
            private void ActionEnd(int aGen)
            { if (aGen == actionGen) actionInFlight = false; }

            private static bool InCompetitiveRoomNow()
            {
                try
                {
                    return PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode
                        && CompetitiveRoomDetect.IsCompetitiveRoom();
                }
                catch { return false; }
            }

            private bool ActionPreflight(out string sid)
            {
                sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") return false;
                // Watchdog release: 30s > the 20s POST timeout, so a live
                // request can never overlap its successor (FFA pattern).
                if (actionInFlight && Time.realtimeSinceStartup - actionAt > 30f)
                    actionInFlight = false;
                if (actionInFlight) return false;
                if (Status == "leaving")
                {
                    CompetitiveUI.ShowNotification(I18n.Tr("Still leaving — try again in a moment."), new Color(1f, 0.6f, 0.2f));
                    return false;
                }
                // A live locked group in this mode outranks lobby actions
                // (mirror of FFA's Codex round-3 regression 5 gate).
                bool lockedElsewhere = IsTeam
                    ? (!string.IsNullOrEmpty(ActiveTeamSeriesId)
                       || CurrentTeamQueueState == TeamQueueState.Matched
                       || CurrentTeamQueueState == TeamQueueState.ReadySent)
                    : (!string.IsNullOrEmpty(ActiveOvt1v2SeriesId) || Plugin.PendingOvtSlot >= 0);
                if (lockedElsewhere)
                {
                    CompetitiveUI.ShowNotification(I18n.TrF("You're in a live {0} game — finish or leave it first.", label), new Color(1f, 0.7f, 0.3f), 5f);
                    return false;
                }
                // Open seats may ride a CASUAL game (#132); competitive rooms refuse.
                if (InCompetitiveRoomNow())
                {
                    CompetitiveUI.ShowNotification(I18n.Tr("Finish or leave your current game first."), new Color(1f, 0.7f, 0.3f), 5f);
                    return false;
                }
                return true;
            }

            private string EnrollBody(string sid, string lobbyId, string password, string extras)
            {
                string name = Escape(MatchTracker.LocalDisplayName ?? "Player");
                string region = "";
                try { region = PhotonNetwork.CloudRegion?.Replace("/*", "") ?? ""; } catch { region = ""; }
                string lob = lobbyId == null ? "" : $",\"lobby_id\":\"{Escape(lobbyId)}\"";
                string pw = string.IsNullOrEmpty(password) ? "" : $",\"password\":\"{Escape(password)}\"";
                return $"{{\"steam_id\":\"{sid}\",\"display_name\":\"{name}\",\"region\":\"{Escape(region)}\"{lob}{pw}{extras ?? ""}}}";
            }

            private static bool PasswordTooLong(string password)
            {
                // Server 400s over 64 chars (LOBBY_PASSWORD_MAX_LEN) — catch it
                // client-side with a readable message instead.
                if (password == null || password.Length <= 64) return false;
                CompetitiveUI.ShowNotification(I18n.Tr("Password must be 64 characters or fewer."), new Color(1f, 0.6f, 0.2f), 5f);
                return true;
            }

            /// <summary>Codex r2 f3: true (with toast) while a leave intent
            /// for this mode is still unresolved — create/join/queue-join
            /// entry points must wait for it, or the retrying teardown and
            /// the fresh enrollment race each other.</summary>
            public bool BlocksOnPendingLeave()
            {
                if (!leaveIntent && !queueLeaveIntent && Status != "leaving") return false;
                CompetitiveUI.ShowNotification(I18n.Tr("Finishing your previous leave first..."), new Color(1f, 0.6f, 0.2f), 4f);
                return true;
            }

            /// <summary>Codex r2 f3: static probe for the mode's PUBLIC queue
            /// joins (JoinTeamQueue / OvtJoinQueue live outside this class).</summary>
            public static bool HasPendingLeave(string mode)
            {
                HostLobbyClient c = mode == "team" ? TeamLobby : mode == "ovt" ? OvtLobby : null;
                return c != null && (c.leaveIntent || c.queueLeaveIntent || c.Status == "leaving");
            }

            /// <summary>Codex r2 f5-residual: record the local selection as
            /// structured values. The static wrappers call these on every
            /// create/join/prefs click; the prefs ack echo also folds in.</summary>
            public void SetLocalTeamPref(int preferredTeam)
            { curPreferredTeam = (preferredTeam == 1 || preferredTeam == 2) ? preferredTeam : 0; }
            public void SetLocalOvtSide(int side)
            { curPreferredSide = (side == 1 || side == 2) ? side : 0; }
            public void SetLocalOvtExtraPick(bool extraPick)
            { curSoloExtraPick = extraPick; }
            /// <summary>F6 (Codex r3): the LOCAL desired value — the last
            /// value the user selected (kept server-true by the ack echo and
            /// idle hydration). The ovt extra-pick toggle derives its next
            /// value from THIS while a prefs write is unacked: the server
            /// member row is stale in that window, so ON-then-OFF before the
            /// first ack used to send ON twice.</summary>
            public bool LocalDesiredExtraPick => curSoloExtraPick;
            /// <summary>Recovery-rejoin enrollment extras, built from the
            /// CURRENT structured preferences — never a join-time snapshot
            /// (Codex r2 f5-residual: the snapshot replayed stale values
            /// over any prefs change made while seated).</summary>
            private string CurrentExtras()
                => IsTeam ? TeamLobbyExtras(curPreferredTeam)
                          : OvtLobbyExtras(curPreferredSide, curSoloExtraPick);

            public void Create(string password, string extras)
            {
                if (SpectatorBlocksQueue()) return;
                NoteQueueRequestInFlight();
                if (PasswordTooLong(password)) return;
                if (BlocksOnPendingLeave()) return;
                if (!ActionPreflight(out string sid)) return;
                // F2 (Codex r3): one enrollment in flight per mode, shared
                // with the public queue join.
                if (!EnrollGateBegin(mode)) return;
                leaveIntent = false;
                lastPassword = password;
                int g = ++gen;
                ActionBegin(); int aGen = actionGen;
                Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/{mode}/lobby/create",
                    EnrollBody(sid, null, password, extras), (ok, resp) =>
                {
                    EnrollGateEnd(mode);   // F2: before the gen check — a stale ack still frees the mode
                    ActionEnd(aGen);
                    if (g != gen) return;
                    if (ok) IsHost = true;
                    EnrollResult(ok, resp, null, wasRecovery: false);
                }));
            }

            public void Join(string lobbyId, string password, string extras)
            {
                if (SpectatorBlocksQueue()) return;
                NoteQueueRequestInFlight();
                if (string.IsNullOrEmpty(lobbyId)) return;
                if (PasswordTooLong(password)) return;
                if (BlocksOnPendingLeave()) return;
                if (!ActionPreflight(out string sid)) return;
                // F2 (Codex r3): one enrollment in flight per mode, shared
                // with the public queue join. Recovery rejoins ride the same
                // latch — they are enrollments too, and their 60s throttle
                // makes a collision with a user click rare.
                if (!EnrollGateBegin(mode)) return;
                bool wasRecovery = OpenLobbyId == lobbyId;
                if (!wasRecovery) { leaveIntent = false; confirmedMember = false; }
                lastPassword = password;
                int g = ++gen;
                ActionBegin(); int aGen = actionGen;
                Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/{mode}/lobby/join",
                    EnrollBody(sid, lobbyId, password, extras), (ok, resp) =>
                {
                    EnrollGateEnd(mode);   // F2: before the gen check — a stale ack still frees the mode
                    ActionEnd(aGen);
                    if (g != gen) return;
                    EnrollResult(ok, resp, lobbyId, wasRecovery);
                }));
            }

            /// <summary>Shared post-enroll handling — direct port of
            /// FfaEnrollResult, plus the password 403 contract mapping
            /// ("password_required"/"password_incorrect" are exact API
            /// tokens, main.py LOBBY_PW_*_DETAIL).</summary>
            private void EnrollResult(bool ok, string resp, string intendedLobbyId, bool wasRecovery)
            {
                if (ok)
                {
                    string lid = ExtractJsonString(resp, "lobby_id");
                    string prevLobbyId = OpenLobbyId;
                    OpenLobbyId = string.IsNullOrEmpty(lid) ? intendedLobbyId : lid;
                    // F5 (Codex r3): adopting a DIFFERENT lobby id is a
                    // membership change — queued pref writes were bound to the
                    // previous seat; drop them (and stale-ify any in-flight
                    // ack) instead of landing them on the new lobby.
                    if (!string.IsNullOrEmpty(prevLobbyId)
                        && !string.Equals(prevLobbyId, OpenLobbyId, StringComparison.Ordinal)
                        && (prefsPending.Count > 0 || prefsInFlight))
                    {
                        prefsPending.Clear();
                        prefsInFlight = false;
                        prefsGen++;
                        Plugin.Log.LogInfo($"[{label}-LOBBY] dropped queued pref writes on lobby change ({prevLobbyId} -> {OpenLobbyId})");
                    }
                    HasPassword = ExtractJsonBool(resp, "has_password") || !string.IsNullOrEmpty(lastPassword);
                    int mx = ExtractJsonInt(resp, "max_players"); if (mx > 0) MaxPlayers = mx;
                    int pc = ExtractJsonInt(resp, "player_count"); if (pc > 0) MemberCount = pc;
                    leaveIntent = false; leaveTarget = null;
                    confirmedMember = true;
                    ambiguousUntil = -999f; handoffUntil = -999f;
                    Status = "lobby"; Polling = true; lastPollAt = -999f;
                    // The seat CONVERTED any searching row in this mode — a
                    // still-armed queue poll would now see 'lobby' forever, so
                    // the state heartbeat takes over cleanly here.
                    if (IsTeam)
                    {
                        IsTeamQueuePolling = false;
                        if (CurrentTeamQueueState == TeamQueueState.Searching)
                            CurrentTeamQueueState = TeamQueueState.Idle;
                    }
                    else
                    {
                        IsOvtQueuePolling = false;
                        if (OvtQueueStatus == "searching") OvtQueueStatus = "";
                    }
                    Plugin.Log.LogInfo($"[{label}-LOBBY] enrolled in lobby {OpenLobbyId} (recovery={wasRecovery})");
                    // Level-triggered room exclusion: a COMPETITIVE game that
                    // finished connecting while the enroll was in flight means
                    // we hold a seat we cannot sit in (#150).
                    if (InCompetitiveRoomNow())
                    {
                        Plugin.Log.LogWarning($"[{label}-LOBBY] enrolled while inside a competitive room — leaving the lobby");
                        LeaveLobby();
                        return;
                    }
                }
                else
                {
                    bool serverSpoke = resp != null && resp.StartsWith("HTTP 4", StringComparison.Ordinal);
                    Plugin.Log.LogWarning($"[{label}-LOBBY] enroll failed (recovery={wasRecovery}, serverSpoke={serverSpoke}): {resp}");
                    string detail = serverSpoke ? (ExtractJsonString(resp ?? "", "detail") ?? "") : "";
                    // Aug 8 (Sid): KICKED IS TERMINAL. Every join path funnels
                    // through here — user clicks, the ghost-prune same-lobby
                    // rejoin, the handoff's not_in_queue recovery — and a
                    // kicked client that retried would fight the kick forever.
                    // Clear belief AND intent, never retry, never reprompt.
                    if (detail == "kicked_from_lobby")
                    {
                        ClearMembershipSilent();
                        leaveIntent = false; leaveTarget = null;
                        CompetitiveUI.ShowNotification(I18n.Tr("The host removed you from this lobby."), new Color(1f, 0.7f, 0.3f), 7f);
                        FetchLobbies(force: true);
                        NativeUI.MarkDirty();
                        return;
                    }
                    if (detail == "password_required" || detail == "password_incorrect")
                    {
                        bool wrong = detail == "password_incorrect";
                        if (wasRecovery)
                        {
                            // A background recovery rejoin has no user mid-flow —
                            // never pop a modal from it. The seat is already gone
                            // server-side, so dropping the belief leaves nothing
                            // behind; tell the player the way back in.
                            ClearMembershipSilent();
                            CompetitiveUI.ShowNotification(I18n.TrF("Couldn't rejoin your private {0} lobby — join it again from the browser.", label), new Color(1f, 0.75f, 0.4f), 7f);
                        }
                        else
                        {
                            CompetitiveUI.ShowNotification(wrong
                                ? I18n.Tr("Wrong password — try again.")
                                : I18n.TrF("That {0} lobby is private — enter its password.", label), new Color(1f, 0.7f, 0.3f), 5f);
                            string relobby = intendedLobbyId; string reextras = CurrentExtras();
                            if (!string.IsNullOrEmpty(relobby))
                                CompetitiveUI.OpenArtistInput(I18n.TrF("Private {0} lobby", label),
                                    wrong ? I18n.Tr("Wrong password - try again") : I18n.Tr("Password"), "",
                                    pw => Join(relobby, pw, reextras));
                        }
                        FetchLobbies(force: true);
                        NativeUI.MarkDirty();
                        return;
                    }
                    if (wasRecovery && serverSpoke)
                    {
                        // The server judged our old membership: it's gone.
                        ClearMembershipSilent();
                        leaveIntent = false; leaveTarget = null;
                        CompetitiveUI.ShowNotification(I18n.TrF("Your {0} lobby closed.", label), new Color(1f, 0.75f, 0.4f), 6f);
                    }
                    else if (!serverSpoke)
                    {
                        // Transport failure — the request may have COMMITTED.
                        // Adopt the intended belief when we know it (join) and
                        // keep polling through a 90s ambiguity window so a late
                        // commit surfaces instead of becoming a hidden seat.
                        if (!string.IsNullOrEmpty(intendedLobbyId))
                            OpenLobbyId = intendedLobbyId;
                        ambiguousUntil = Time.unscaledTime + 90f;
                        Polling = true; lastPollAt = -999f;
                    }
                    else
                        CompetitiveUI.ShowNotification(DetailOr(resp, I18n.Tr("Couldn't join that lobby.")), new Color(1f, 0.6f, 0.2f), 5f);
                }
                FetchLobbies(force: true);
                NativeUI.MarkDirty();
            }

            /// <summary>Drop every membership belief WITHOUT touching leave
            /// intent (callers decide that). Local-only — no request.</summary>
            private void ClearMembershipSilent()
            {
                OpenLobbyId = null;
                IsHost = false; CanStart = false; HasPassword = false;
                Members = null; MemberCount = 0;
                Polling = false; confirmedMember = false;
                ambiguousUntil = -999f; handoffUntil = -999f;
                if (Status == "lobby") Status = "";
                // F5 (Codex r3): a teardown is a membership change — queued
                // pref writes were bound to the dead seat and can never land;
                // the gen bump makes any in-flight ack stale so it can't fold
                // echoes from the dead lobby into the fresh state.
                prefsPending.Clear();
                prefsInFlight = false;
                prefsGen++;
            }

            public void StartLobby()
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
                // Codex r2 f4/f6 gate: a Start racing the host's own unacked
                // prefs write would freeze a value the host JUST changed (the
                // ovt extra-pick race). The button renders dimmed
                // "(saving...)" while this is true — this is its no-op half.
                if (PrefsInFlight) return;
                if (actionInFlight && Time.realtimeSinceStartup - actionAt > 30f)
                    actionInFlight = false;
                if (actionInFlight) return;
                int g = gen;   // NOT ++: starting must not orphan the poll lifecycle
                ActionBegin(); int aGen = actionGen;
                Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/{mode}/lobby/start",
                    $"{{\"steam_id\":\"{sid}\"}}", (ok, resp) =>
                {
                    ActionEnd(aGen);
                    if (g != gen) return;
                    if (!ok)
                    {
                        Plugin.Log.LogWarning($"[{label}-LOBBY] start failed: {resp}");
                        CompetitiveUI.ShowNotification(DetailOr(resp, I18n.Tr("Couldn't start the game.")), new Color(1f, 0.6f, 0.2f), 5f);
                        NativeUI.MarkDirty();
                        return;
                    }
                    // The rows are locked now; the state poll would discover
                    // not_in_lobby within ~2s anyway — begin the handoff
                    // immediately so the host's ready-up (2v2) / room join
                    // (1v2) engages without the extra round-trip.
                    Plugin.Log.LogInfo($"[{label}-LOBBY] start accepted — handing off to the queue flow");
                    BeginHandoff();
                    NativeUI.MarkDirty();
                }));
            }

            /// <summary>Leave the OPEN lobby seat. Explicit leave = standing
            /// intent (#252e): belief and intent survive until the server acks
            /// or authoritatively resolves; state clears in the RESPONSE
            /// handler, never before the request (#249).</summary>
            public void LeaveLobby()
            {
                string sid = MatchTracker.LocalSteamId;
                if (Status == "leaving") return;
                string expected = OpenLobbyId;
                leaveIntent = true;
                if (!string.IsNullOrEmpty(expected)) leaveTarget = expected;
                if (string.IsNullOrEmpty(sid) || sid == "unknown")
                { Status = ""; OpenLobbyId = null; leaveIntent = false; return; }
                int g = ++gen;
                Status = "leaving";
                leavingSince = Time.realtimeSinceStartup;
                handoffUntil = -999f;
                NativeUI.MarkDirty();
                string url = $"{baseUrl}/api/v1/{mode}/lobby/leave?steam_id={UnityWebRequest.EscapeURL(sid)}";
                if (!string.IsNullOrEmpty(expected))
                    url += $"&expected_lobby_id={UnityWebRequest.EscapeURL(expected)}";
                Plugin.Instance.StartCoroutine(PostRequestWithRetry(url, "", (ok, resp) =>
                {
                    if (g != gen) return;
                    if (ok)
                    {
                        // Codex r1 f5: HTTP 200 "started" = Start converted the
                        // seat while the leave was in flight. The leave INTENT
                        // stands and now targets the locked group — route it
                        // through the mode's /queue/leave (which owns
                        // locked-group dissolution) and clear it only on THAT
                        // call's ack, never here.
                        if ((ExtractJsonString(resp ?? "", "status") ?? "") == "started")
                        {
                            Plugin.Log.LogWarning($"[{label}-LOBBY] leave raced a Start (server said started) — leaving via the {label} queue");
                            ClearMembershipSilent();
                            // Codex r2 f3: the "started" answer names the series
                            // the seat converted into — record it as the fence.
                            DirectQueueLeave(ExtractJsonString(resp ?? "", "series_id"));
                        }
                        else
                        {
                            ClearMembershipSilent();
                            leaveIntent = false; leaveTarget = null;
                            Plugin.Log.LogInfo($"[{label}-LOBBY] left lobby");
                        }
                    }
                    else
                    {
                        // 409 "Not in an open lobby" = the row is LOCKED (a
                        // Start raced this leave on an old-contract answer).
                        // The player asked OUT — honor it through the mode's
                        // queue leave via the UNCONDITIONAL direct request
                        // (Codex r1 f5: LeaveTeamQueue no-ops when locally
                        // Idle, which is exactly this client's state).
                        bool lockedRace = resp != null
                            && resp.StartsWith("HTTP 4", StringComparison.Ordinal)
                            && resp.Contains("Not in an open lobby");
                        if (lockedRace)
                        {
                            Plugin.Log.LogWarning($"[{label}-LOBBY] leave raced a Start — leaving via the {label} queue instead");
                            ClearMembershipSilent();
                            DirectQueueLeave();
                        }
                        else
                        {
                            // Keep the belief AND the intent: the state poll
                            // re-arm lets the server state win — a surviving
                            // seat triggers a leave RETRY, a dead row clears
                            // us silently.
                            Plugin.Log.LogWarning($"[{label}-LOBBY] leave failed after retries: {resp} — re-arming the poll to recover");
                            OpenLobbyId = OpenLobbyId ?? expected;
                            Polling = !string.IsNullOrEmpty(OpenLobbyId);
                            CompetitiveUI.ShowNotification(I18n.TrF("Couldn't confirm the {0} lobby leave — retrying in the background.", label), new Color(1f, 0.6f, 0.2f), 5f);
                        }
                    }
                    if (Status == "leaving") Status = "";
                    FetchLobbies(force: true);
                    NativeUI.MarkDirty();
                }, maxRetries: 3, retryDelay: 2f));
            }

            /// <summary>Codex r1 f5: the leave intent survived a Start
            /// conversion (or a legacy dissolution reset the row) — tear the
            /// QUEUE-side row down with a direct POST to the mode's
            /// /queue/leave. Deliberately independent of the mode's local
            /// polling/Idle state: LeaveTeamQueue early-returns on
            /// (Idle && !polling), which is exactly the state a lobby client
            /// is in when Start lands under it, so this must not ride it.
            /// Intent clears ONLY on the ack; a transport failure retries from
            /// Tick(). The mode's local queue state is disarmed here (not in
            /// the callback) because this client never adopted the started
            /// match — there is no belief to preserve, only one to prevent.</summary>
            /// <summary>Codex r2 f3: `fenceSeriesId` names the series
            /// INCARNATION this leave is aimed at (from the "started"
            /// response / resolve answer). Recorded into the intent when the
            /// intent is created — or refreshed by a newer authoritative
            /// answer — and sent as expected_series_id on every attempt so a
            /// delayed retry can never tear down a NEWER enrollment. Null
            /// from a caller that knows no series (searching-row dissolution)
            /// keeps the legacy unfenced behaviour; the parameterless Tick
            /// retry keeps whatever the intent recorded.</summary>
            private void DirectQueueLeave(string fenceSeriesId = null)
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
                if (!string.IsNullOrEmpty(fenceSeriesId)) queueLeaveSeriesId = fenceSeriesId;
                else if (!queueLeaveIntent) queueLeaveSeriesId = null;   // fresh unfenced intent
                if (!queueLeaveIntent) queueLeaveAttempts = 0;   // fresh intent = fresh budget
                queueLeaveIntent = true;
                if (queueLeaveInFlight && Time.realtimeSinceStartup - queueLeaveAt > 30f)
                    queueLeaveInFlight = false;
                if (queueLeaveInFlight) return;
                if (queueLeaveAttempts >= 10)
                {
                    // Give up locally — the server's lease expiry frees the row
                    // within minutes regardless (#276's failure direction).
                    Plugin.Log.LogWarning($"[{label}-LOBBY] queue-leave retry budget exhausted — leaving cleanup to the server lease expiry");
                    queueLeaveIntent = false; queueLeaveSeriesId = null;
                    leaveIntent = false; leaveTarget = null;
                    return;
                }
                queueLeaveAttempts++;
                queueLeaveInFlight = true; queueLeaveAt = Time.realtimeSinceStartup;
                // Disarm the mode's queue machinery so a racing poll callback
                // can't adopt the match this leave is dissolving. Gen bumps
                // invalidate in-flight callbacks (they all check their gen).
                if (IsTeam)
                {
                    teamGen++;
                    IsTeamQueuePolling = false;
                    LastTeamPollData = null;
                    ActiveTeamSeriesId = null;
                    Plugin.ClearPending2v2Slot();
                    if (CurrentTeamQueueState != TeamQueueState.Idle)
                        CurrentTeamQueueState = TeamQueueState.Idle;
                }
                else
                {
                    ovtGen++;
                    IsOvtQueuePolling = false;
                    ActiveOvt1v2SeriesId = null;
                    Plugin.ClearPendingOvtSlot();
                    if (OvtQueueStatus != "leaving") OvtQueueStatus = "";
                }
                int g = gen;
                string leaveUrl = $"{baseUrl}/api/v1/{mode}/queue/leave?steam_id={UnityWebRequest.EscapeURL(sid)}";
                // Codex r2 f3: fence every attempt to the recorded incarnation.
                if (!string.IsNullOrEmpty(queueLeaveSeriesId))
                    leaveUrl += $"&expected_series_id={UnityWebRequest.EscapeURL(queueLeaveSeriesId)}";
                Plugin.Instance.StartCoroutine(PostRequestWithRetry(leaveUrl, "",
                    (ok, resp) =>
                {
                    queueLeaveInFlight = false;
                    if (g != gen) return;   // TearDown/escape took over
                    if (ok)
                    {
                        // Codex r2 f3: {"stale":true} = the row's CURRENT series
                        // differs from the fenced incarnation — that incarnation
                        // is gone, which is exactly what this leave wanted.
                        // TERMINAL ack either way; only the log differs.
                        if (ExtractJsonBool(resp ?? "", "stale"))
                            Plugin.Log.LogInfo($"[{label}-LOBBY] queue-leave fence hit a newer incarnation — old seat already gone, intent satisfied");
                        else
                            Plugin.Log.LogInfo($"[{label}-LOBBY] queue-leave for the converted seat acked");
                        queueLeaveIntent = false; queueLeaveAttempts = 0;
                        queueLeaveSeriesId = null;
                        leaveIntent = false; leaveTarget = null;
                    }
                    else
                    {
                        // Keep BOTH intents; Tick retries (the resolve probe's
                        // not_in_queue answer also clears them authoritatively).
                        queueLeaveRetryAt = Time.realtimeSinceStartup + 15f;
                        Plugin.Log.LogWarning($"[{label}-LOBBY] queue-leave for the converted seat failed: {resp} — will retry");
                    }
                    NativeUI.MarkDirty();
                }, maxRetries: 3, retryDelay: 2f));
            }

            /// <summary>Always-on upkeep, driven from TickLeaveRecovery so the
            /// heartbeat never depends on a tab being open. No-op unless armed.</summary>
            public void Tick()
            {
                try
                {
                    float now = Time.realtimeSinceStartup;
                    // Stuck-leave watchdog (FFA pattern: the callback that
                    // carried the belief may be dead — NetworkRestart kills
                    // coroutine-hosted requests).
                    if (Status == "leaving" && now - leavingSince > LEAVE_STUCK_TIMEOUT)
                    {
                        gen++;
                        Status = "";
                        if (leaveIntent && string.IsNullOrEmpty(OpenLobbyId) && !string.IsNullOrEmpty(leaveTarget))
                            OpenLobbyId = leaveTarget;
                        Polling = !string.IsNullOrEmpty(OpenLobbyId);
                        Plugin.Log.LogWarning($"[{label}-LOBBY] Leaving state stuck past timeout — recovered"
                            + (leaveIntent ? $" (leave retry re-armed for {OpenLobbyId})" : ""));
                        NativeUI.MarkDirty();
                    }
                    // Codex r1 f5: a standing queue-leave intent (Start
                    // converted the seat mid-leave) retries here — the request
                    // coroutine may have died with its host (#249).
                    if (queueLeaveIntent && !queueLeaveInFlight
                        && Time.realtimeSinceStartup >= queueLeaveRetryAt)
                        DirectQueueLeave();
                    // Codex r2 f4: a queued prefs write whose request failed
                    // (or whose coroutine host died) drains here after the
                    // backoff; PumpPrefs itself enforces single-flight.
                    if (prefsPending.Count > 0
                        && !(prefsInFlight && Time.realtimeSinceStartup - prefsAt < 25f)
                        && Time.realtimeSinceStartup >= prefsPumpRetryAt)
                        PumpPrefs();
                    // Handoff window: the state poll pauses; the READ-ONLY
                    // /lobby/resolve probe settles start-vs-closed (r1 f1).
                    if (handoffUntil > 0f)
                    {
                        if (Time.unscaledTime > handoffUntil)
                        {
                            // Unresolved (server unreachable) — fall back to
                            // the state poll; a still-dead membership simply
                            // re-enters the handoff on its next answer.
                            handoffUntil = -999f;
                            Polling = !string.IsNullOrEmpty(OpenLobbyId);
                        }
                        else if (Time.unscaledTime >= handoffProbeAt)
                        {
                            handoffProbeAt = Time.unscaledTime + 3f;
                            SendHandoffProbe();
                        }
                        return;
                    }
                    if (actionInFlight && now - actionAt > 30f) actionInFlight = false;
                    // Level-triggered re-arm: a held belief with a dead poll
                    // loop is always wrong — the poll is both the seat's lease
                    // heartbeat and the only channel that discovers closure.
                    if (!Polling && !string.IsNullOrEmpty(OpenLobbyId)
                        && Status != "leaving" && !actionInFlight)
                        Polling = true;
                    if (!Polling) return;
                    // Ambiguity-window expiry must not depend on a SUCCESSFUL
                    // poll response (FFA round-3 find E1 mirror).
                    if (ambiguousUntil > 0f && Time.unscaledTime > ambiguousUntil
                        && string.IsNullOrEmpty(OpenLobbyId) && !leaveIntent)
                    {
                        ambiguousUntil = -999f;
                        Polling = false;
                        if (Status != "leaving") Status = "";
                        Plugin.Log.LogInfo($"[{label}-LOBBY] ambiguity window lapsed with no resolution — stopping the probe poll");
                        NativeUI.MarkDirty();
                        return;
                    }
                    string sid = MatchTracker.LocalSteamId;
                    if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
                    if (Time.unscaledTime - lastPollAt < 2f) return;
                    lastPollAt = Time.unscaledTime;
                    int g = gen;
                    Plugin.Instance.StartCoroutine(GetRequest(
                        $"{baseUrl}/api/v1/{mode}/lobby/state?steam_id={UnityWebRequest.EscapeURL(sid)}", (ok, resp) =>
                    {
                        if (!ok || string.IsNullOrEmpty(resp)) return;
                        if (!Polling || g != gen) return;
                        HandleState(resp);
                    }));
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[{label}-LOBBY] tick: {ex.Message}"); }
            }

            private void HandleState(string resp)
            {
                string status = ExtractJsonString(resp, "status") ?? "";
                if (status == "lobby")
                {
                    // Leave intent outranks membership: the seat still existing
                    // means the leave never landed — retry it instead of
                    // re-adopting (FFA impl review find 2).
                    if (leaveIntent)
                    {
                        if (Time.unscaledTime - leaveRetryAt > 10f)
                        {
                            leaveRetryAt = Time.unscaledTime;
                            Plugin.Log.LogWarning($"[{label}-LOBBY] leave intent pending but seat still exists — retrying leave");
                            LeaveLobby();
                        }
                        return;
                    }
                    // Room-entry teardown, level-triggered every poll: an open
                    // seat may ride a CASUAL game (#132), but a competitive
                    // room means a Start could yank us out mid-match (#150).
                    if (InCompetitiveRoomNow())
                    {
                        Plugin.Log.LogWarning($"[{label}-LOBBY] in a competitive room while holding a lobby seat — leaving the lobby");
                        LeaveLobby();
                        return;
                    }
                    ambiguousUntil = -999f;
                    confirmedMember = true;
                    OpenLobbyId = ExtractJsonString(resp, "lobby_id") ?? OpenLobbyId;
                    IsHost = ExtractJsonBool(resp, "is_host");
                    CanStart = ExtractJsonBool(resp, "can_start");
                    HasPassword = ExtractJsonBool(resp, "has_password");
                    MemberCount = ExtractJsonInt(resp, "player_count");
                    int mx = ExtractJsonInt(resp, "max_players"); if (mx > 0) MaxPlayers = mx;
                    Status = "lobby";
                    try
                    {
                        var members = new List<HostLobbyMemberEntry>();
                        int mStart = resp.IndexOf("\"members\"");
                        int arrStart = mStart >= 0 ? resp.IndexOf('[', mStart) : -1;
                        int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                        if (arrStart >= 0 && arrEnd > arrStart)
                        {
                            foreach (string obj in SliceTopLevelObjects(resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                            {
                                members.Add(new HostLobbyMemberEntry
                                {
                                    steam_id = ExtractJsonString(obj, "steam_id"),
                                    display_name = ExtractJsonString(obj, "display_name") ?? "?",
                                    rating = ExtractJsonInt(obj, "rating"),
                                    rating_1v1 = ExtractJsonInt(obj, "rating_1v1"),
                                    wait_seconds = ExtractJsonInt(obj, "wait_seconds"),
                                    preferred_team = ExtractJsonInt(obj, "preferred_team"),
                                    preferred_side = ExtractJsonInt(obj, "preferred_side"),
                                    solo_extra_pick = ExtractJsonBool(obj, "solo_extra_pick"),
                                    is_host = ExtractJsonBool(obj, "is_host"),
                                });
                            }
                        }
                        Members = members;
                        // Codex r2 f5-residual: keep the structured current
                        // prefs server-true from the freshest poll — this is
                        // what makes a RELAUNCHED client's recovery rejoin
                        // carry its real stored prefs even though no local
                        // selection happened this session. An unacked local
                        // write outranks the poll (it may predate the PATCH).
                        if (!PrefsInFlight)
                        {
                            string mySid = MatchTracker.LocalSteamId;
                            foreach (var m in members)
                            {
                                if (m == null || m.steam_id != mySid) continue;
                                if (IsTeam)
                                    curPreferredTeam = (m.preferred_team == 1 || m.preferred_team == 2) ? m.preferred_team : 0;
                                else
                                {
                                    curPreferredSide = (m.preferred_side == 1 || m.preferred_side == 2) ? m.preferred_side : 0;
                                    curSoloExtraPick = m.solo_extra_pick;
                                }
                                break;
                            }
                        }
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[{label}-LOBBY] member parse: {ex.Message}"); }
                    NativeUI.MarkDirty();
                    return;
                }
                if (status == "not_in_lobby")
                {
                    if (leaveIntent)
                    {
                        // Either the leave LANDED (ack lost) or a Start
                        // CONVERTED the seat — the state endpoint cannot tell
                        // them apart (a matched row is not_in_lobby here).
                        // Codex r1 f5: only the read-only resolve may clear a
                        // standing leave intent; its not_in_queue answer clears
                        // silently, its matched answer routes the intent
                        // through the mode's queue leave.
                        BeginHandoff();
                        return;
                    }
                    if (string.IsNullOrEmpty(OpenLobbyId))
                    {
                        // No belief: one-shot probe found nothing, or an
                        // ambiguity window is still open (keep polling until
                        // it lapses in Tick).
                        if (ambiguousUntil <= 0f || Time.unscaledTime >= ambiguousUntil)
                        {
                            Polling = false;
                            if (Status != "leaving") Status = "";
                        }
                        NativeUI.MarkDirty();
                        return;
                    }
                    if (!confirmedMember)
                    {
                        // Ambiguous enroll (transport-failed join): a same-lobby
                        // rejoin is idempotent server-side and resolves the
                        // belief either way (FFA ghost-prune pattern).
                        if (Time.unscaledTime - rejoinAt > 60f)
                        {
                            rejoinAt = Time.unscaledTime;
                            Plugin.Log.LogWarning($"[{label}-LOBBY] unconfirmed membership not found server-side — attempting same-lobby rejoin");
                            Join(OpenLobbyId, lastPassword, CurrentExtras());
                        }
                        return;
                    }
                    // Confirmed member + not_in_lobby: Start and disband are
                    // indistinguishable HERE — resolve via the queue poll.
                    BeginHandoff();
                    return;
                }
                // Unknown status: ignore (old server / new field).
            }

            private void BeginHandoff()
            {
                Polling = false;
                handoffUntil = Time.unscaledTime + 25f;
                handoffProbeAt = Time.unscaledTime;   // first probe on the next Tick
                Plugin.Log.LogInfo($"[{label}-LOBBY] membership left the lobby state — resolving start-vs-closed via /{mode}/lobby/resolve");
            }

            /// <summary>Codex r1 prefs contract: a 409 not_in_open_lobby from
            /// the prefs PATCH means the seat is gone or the lobby started —
            /// never retry the PATCH; the read-only resolve decides which.</summary>
            public void ResolveStaleSeat()
            {
                if (handoffUntil > 0f) return;   // already resolving
                if (string.IsNullOrEmpty(OpenLobbyId) && Status != "lobby") return;
                BeginHandoff();
            }

            private void SendHandoffProbe()
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
                int g = gen;
                // Codex r1 f1: READ-ONLY resolve. The old probe was the mode's
                // MUTATING /queue/poll — against a 'searching' row it could
                // LOCK this client into a public match it never consented to,
                // and it read ANY matched row as "our lobby started".
                Plugin.Instance.StartCoroutine(GetRequest(
                    $"{baseUrl}/api/v1/{mode}/lobby/resolve?steam_id={UnityWebRequest.EscapeURL(sid)}", (ok, resp) =>
                {
                    if (g != gen || handoffUntil <= 0f) return;
                    if (!ok || string.IsNullOrEmpty(resp)) return;   // retried at the next probe tick
                    HandleResolveProbe(ExtractJsonString(resp, "status") ?? "", resp, sid);
                }));
            }

            private void HandleResolveProbe(string status, string resp, string sid)
            {
                if (status == "lobby")
                {
                    // Row still says lobby. Only lobby_status 'open' keeps the
                    // membership; anything else (active/canceled/gone) means a
                    // seat orphaned from its lobby — treat as disbanded.
                    string lstat = ExtractJsonString(resp, "lobby_status") ?? "";
                    handoffUntil = -999f;
                    if (lstat == "open")
                    {
                        // The state read was transient. Back to the state poll,
                        // whose 'lobby' branch also owns leave-intent retries.
                        Polling = true; lastPollAt = -999f;
                        return;
                    }
                    bool told = leaveIntent;
                    ClearMembershipSilent();
                    leaveIntent = false; leaveTarget = null;
                    if (!told)
                        CompetitiveUI.ShowNotification(I18n.TrF("Your {0} lobby closed.", label), new Color(1f, 0.75f, 0.4f), 6f);
                    NativeUI.MarkDirty();
                    return;
                }
                handoffUntil = -999f;
                if (status == "matched" || status == "ready" || status == "ready_join")
                {
                    // The host STARTED the lobby and the seat is a locked group.
                    if (leaveIntent)
                    {
                        // Codex r1 f5: the player asked OUT before the Start
                        // won — the intent stands and its teardown belongs to
                        // the mode's /queue/leave.
                        Plugin.Log.LogInfo($"[{label}-LOBBY] resolve found a started group under a standing leave intent — leaving via the {label} queue");
                        ClearMembershipSilent();
                        // Codex r2 f3: the resolve answer names the started
                        // series — record it as the fence.
                        DirectQueueLeave(ExtractJsonString(resp, "series_id"));
                        NativeUI.MarkDirty();
                        return;
                    }
                    // Adopt the handoff only while a remembered seat awaited
                    // this start (TearDown / kick already dropped the belief
                    // for every other path — this is the belt).
                    if (string.IsNullOrEmpty(OpenLobbyId))
                    {
                        Polling = false;
                        NativeUI.MarkDirty();
                        return;
                    }
                    Plugin.Log.LogInfo($"[{label}-LOBBY] lobby started — handing off to the {label} queue flow (status={status})");
                    ClearMembershipSilent();
                    string seriesId = ExtractJsonString(resp, "series_id") ?? "";
                    if (IsTeam)
                    {
                        IsTeamQueuePolling = true;
                        CurrentTeamQueueType = "manual";
                        if (!string.IsNullOrEmpty(seriesId)) ActiveTeamSeriesId = seriesId;
                        if (CurrentTeamQueueState != TeamQueueState.ReadySent)
                            CurrentTeamQueueState = TeamQueueState.Matched;
                        // The resolve answer carries no teammates payload, so
                        // the ready_join room join (slot compute needs it) is
                        // the real queue poll's job — fire its next tick now.
                        teamQueuePollTimer = TEAM_QUEUE_POLL_INTERVAL;
                        if (status == "matched")
                        {
                            // Lobby members can be idle for minutes — unlike a
                            // fresh queuer they need the full match-found blast
                            // or the 90s ready window burns silently.
                            CompetitiveUI.ShowNotification(I18n.Tr("Your 2v2 lobby is starting — Ready Up in the 2v2 tab (F5)!"), Color.green, 8f);
                            try { CompetitiveUI.PlayMatchFoundSound(); } catch { }
                            try { TaskbarFlash.Flash(); } catch { }
                        }
                    }
                    else
                    {
                        // The existing ovt poll owns ready_join (slot compute,
                        // pre-join props, auto room join — resolve's bare
                        // room_name/room_region can't place the duo slots) —
                        // re-arm it and let its next fetch carry the payload.
                        IsOvtQueuePolling = true;
                        _ovtLastPollAt = -999f;
                        UpdateOvtQueuePoll(force: true);
                    }
                    NativeUI.MarkDirty();
                    return;
                }
                if (status == "searching")
                {
                    // Legacy dissolution reset the seat to a PUBLIC searching
                    // row. The player never consented to public matchmaking
                    // from a hosted lobby (#238) — leave it unconditionally
                    // (DirectQueueLeave carries its own retry intent) and say
                    // why. NEVER adopt a searching row.
                    Plugin.Log.LogInfo($"[{label}-LOBBY] lobby closed server-side — leaving the reset queue row");
                    bool told = leaveIntent;
                    ClearMembershipSilent();
                    DirectQueueLeave();
                    if (!told)
                        CompetitiveUI.ShowNotification(I18n.TrF("Your {0} lobby closed.", label), new Color(1f, 0.75f, 0.4f), 6f);
                    NativeUI.MarkDirty();
                    return;
                }
                if (status == "not_in_queue")
                {
                    // Authoritative: the row is gone. Every standing leave
                    // intent is satisfied (Codex r1 f5's "authoritative
                    // resolve answer" — the only non-ack way intents clear).
                    if (leaveIntent || queueLeaveIntent)
                    {
                        ClearMembershipSilent();
                        leaveIntent = false; leaveTarget = null;
                        queueLeaveIntent = false; queueLeaveAttempts = 0;
                        queueLeaveSeriesId = null;
                        NativeUI.MarkDirty();
                        return;
                    }
                    // Could be a lease hiccup that expired the seat while the
                    // lobby lives on — a same-lobby rejoin recovers it; a truly
                    // dead lobby turns that join into the 4xx "closed" path.
                    if (!string.IsNullOrEmpty(OpenLobbyId)
                        && Time.unscaledTime - rejoinAt > 60f)
                    {
                        rejoinAt = Time.unscaledTime;
                        Plugin.Log.LogWarning($"[{label}-LOBBY] membership row vanished server-side — attempting same-lobby rejoin");
                        Join(OpenLobbyId, lastPassword, CurrentExtras());
                        return;
                    }
                    ClearMembershipSilent();
                    CompetitiveUI.ShowNotification(I18n.TrF("Your {0} lobby closed.", label), new Color(1f, 0.75f, 0.4f), 6f);
                    NativeUI.MarkDirty();
                    return;
                }
                // Unknown — resume the state poll and let it re-resolve.
                Polling = !string.IsNullOrEmpty(OpenLobbyId);
            }

            /// <summary>Aug 8 (Sid): host kicks a member. Refusal tokens are
            /// exact API contract (not_host / target_not_in_lobby /
            /// target_is_admin / cannot_kick_yourself). Success refreshes the
            /// member list on the next state poll tick.</summary>
            public void Kick(string targetSteamId)
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown" || string.IsNullOrEmpty(targetSteamId)) return;
                if (actionInFlight && Time.realtimeSinceStartup - actionAt > 30f)
                    actionInFlight = false;
                if (actionInFlight) return;
                int g = gen;   // NOT ++: kicking must not orphan the poll lifecycle
                ActionBegin(); int aGen = actionGen;
                string body = $"{{\"steam_id\":\"{Escape(sid)}\",\"target_steam_id\":\"{Escape(targetSteamId)}\"}}";
                Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/{mode}/lobby/kick", body, (ok, resp) =>
                {
                    ActionEnd(aGen);
                    if (g != gen) return;
                    if (ok)
                    {
                        Plugin.Log.LogInfo($"[{label}-LOBBY] kicked {targetSteamId}");
                        CompetitiveUI.ShowNotification(I18n.Tr("Player removed from the lobby."), new Color(1f, 0.75f, 0.4f), 4f);
                        lastPollAt = -999f;   // pull the shrunken member list now
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[{label}-LOBBY] kick failed: {resp}");
                        CompetitiveUI.ShowNotification(
                            KickRefusalText(resp) ?? DetailOr(resp, I18n.Tr("Couldn't kick that player.")),
                            new Color(1f, 0.6f, 0.2f), 5f);
                    }
                    NativeUI.MarkDirty();
                }));
            }

            /// <summary>True while ANY preference write is unacked (in flight
            /// OR queued) — the hydration pass must not overwrite the
            /// just-clicked local value with a state poll that predates it
            /// (Codex r1 f4), and the host's Start button dims/no-ops so a
            /// Start can't freeze a value the host just changed (r2 f4/f6).</summary>
            public bool PrefsInFlight
                => (prefsInFlight && Time.realtimeSinceStartup - prefsAt < 25f)
                   || prefsPending.Count > 0;

            /// <summary>The field name a wrapper fragment PATCHes — the
            /// coalescing key. fieldJson is code-authored (leading-comma
            /// `,"name":value`), never user input.</summary>
            private static string PrefFieldKey(string fieldJson)
            {
                int q1 = fieldJson.IndexOf('"');
                int q2 = q1 >= 0 ? fieldJson.IndexOf('"', q1 + 1) : -1;
                return q2 > q1 ? fieldJson.Substring(q1 + 1, q2 - q1 - 1) : fieldJson;
            }

            /// <summary>Codex r1 f4/f6/f7 + r2 f4: seated preference PATCH —
            /// ONE changed field per request (a whole-row resend overwrites
            /// the sibling setting with a stale local copy, and the old full
            /// lobby-JOIN resend raced Start). r2 f4: writes are SERIALIZED —
            /// the click coalesces into prefsPending (latest value per field
            /// wins) and PumpPrefs keeps exactly one request in flight. 409
            /// not_in_open_lobby is terminal: resolve, don't retry.</summary>
            public void SendPrefs(string fieldJson)
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
                if (string.IsNullOrEmpty(OpenLobbyId)) return;   // seated-only surface
                // F5 (Codex r3): bind the write to the lobby the seat belongs
                // to NOW (enqueue time) — a later rejoin into a different
                // lobby must not inherit this write.
                prefsPending[PrefFieldKey(fieldJson)] = new PendingPref { FieldJson = fieldJson, LobbyId = OpenLobbyId };
                PumpPrefs();
            }

            /// <summary>Single-flight sender. Reached from SendPrefs, from
            /// each ack (to drain the queue), and from Tick (retry after a
            /// transport failure / a died coroutine host).</summary>
            private void PumpPrefs()
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown"
                    || string.IsNullOrEmpty(OpenLobbyId))
                {
                    // Seat gone — a seated-only write has nothing to land on.
                    prefsPending.Clear();
                    prefsInFlight = false;
                    return;
                }
                if (prefsInFlight && Time.realtimeSinceStartup - prefsAt < 25f) return;
                // F5 (Codex r3): a queued write is bound to the lobby the seat
                // belonged to at ENQUEUE. A membership change (rejoin adopted
                // a NEW lobby) makes it moot — drop it here rather than land
                // it on the new lobby (the server's expected_lobby_id fence
                // below is the authoritative backstop).
                if (prefsPending.Count > 0)
                {
                    List<string> moot = null;
                    foreach (var kv in prefsPending)
                        if (!string.Equals(kv.Value.LobbyId, OpenLobbyId, StringComparison.Ordinal))
                            (moot ?? (moot = new List<string>())).Add(kv.Key);
                    if (moot != null)
                    {
                        foreach (var k in moot) prefsPending.Remove(k);
                        Plugin.Log.LogInfo($"[{label}-LOBBY] dropped {moot.Count} queued pref write(s) bound to a previous lobby");
                    }
                }
                if (prefsPending.Count == 0) { prefsInFlight = false; return; }
                string key = null;
                foreach (var k in prefsPending.Keys) { key = k; break; }
                PendingPref pend = prefsPending[key];
                string fieldJson = pend.FieldJson;
                prefsInFlight = true; prefsAt = Time.realtimeSinceStartup;
                // r2 f4: generation token — a response may only clear the
                // in-flight state when it belongs to the NEWEST request (a
                // watchdog-expired request's late answer must not release a
                // successor's single-flight slot).
                int pg = ++prefsGen;
                int g = gen;
                // F5: the fence rides the request body — server no-ops with
                // 409 not_in_open_lobby when the seat moved lobbies.
                Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/{mode}/lobby/prefs",
                    $"{{\"steam_id\":\"{Escape(sid)}\",\"expected_lobby_id\":\"{Escape(pend.LobbyId)}\"{fieldJson}}}", (ok, resp) =>
                {
                    if (g != gen) return;
                    if (pg != prefsGen) return;   // stale generation — newest request owns the state
                    prefsInFlight = false;
                    if (ok)
                    {
                        // Acked: drop the pending entry unless the user changed
                        // the field again mid-flight (the newer value then goes
                        // out on the drain pump below).
                        PendingPref cur;
                        if (prefsPending.TryGetValue(key, out cur) && cur.FieldJson == fieldJson)
                            prefsPending.Remove(key);
                        // Fold the echoed STORED values into our cached member
                        // row so the hydration pass can't briefly revert the
                        // control from a state poll that predates the PATCH —
                        // and into the structured current prefs the recovery
                        // rejoin body is built from (r2 f5-residual).
                        try
                        {
                            // Codex r4 f4: NEVER fold an echoed field over a
                            // NEWER pending write — the server echoes EVERY
                            // field it stores, so an older ack (or a sibling
                            // field's ack) used to overwrite the value the
                            // user selected mid-flight, and the next toggle
                            // then derived from the wrong base. The acked
                            // entry was already removed above, so anything
                            // still in prefsPending IS newer — its field's
                            // cur* value is the user's desire, not the echo.
                            bool ptPend = prefsPending.ContainsKey("preferred_team");
                            bool psPend = prefsPending.ContainsKey("preferred_side");
                            bool sepPend = prefsPending.ContainsKey("solo_extra_pick");
                            int ptEcho = IsTeam ? ExtractJsonInt(resp, "preferred_team") : 0;
                            int psEcho = IsTeam ? 0 : ExtractJsonInt(resp, "preferred_side");
                            bool sepEcho = !IsTeam && ExtractJsonBool(resp, "solo_extra_pick");
                            if (IsTeam)
                            {
                                if (!ptPend)
                                    curPreferredTeam = (ptEcho == 1 || ptEcho == 2) ? ptEcho : 0;
                            }
                            else
                            {
                                if (!psPend)
                                    curPreferredSide = (psEcho == 1 || psEcho == 2) ? psEcho : 0;
                                if (!sepPend)
                                    curSoloExtraPick = sepEcho;
                            }
                            if (Members != null)
                                foreach (var m in Members)
                                {
                                    if (m == null || m.steam_id != sid) continue;
                                    if (IsTeam)
                                    {
                                        if (!ptPend) m.preferred_team = curPreferredTeam;
                                    }
                                    else
                                    {
                                        if (!psPend) m.preferred_side = curPreferredSide;
                                        if (!sepPend) m.solo_extra_pick = curSoloExtraPick;
                                    }
                                    break;
                                }
                        }
                        catch { }
                        // Pull the member list now so every seat's claim tags
                        // update within a tick, then drain any queued field.
                        lastPollAt = -999f;
                        PumpPrefs();
                        NativeUI.MarkDirty();
                        return;
                    }
                    if (resp != null && resp.Contains("not_in_open_lobby"))
                    {
                        // Terminal: the seat is gone or the lobby started —
                        // nothing queued can ever land.
                        prefsPending.Clear();
                        Plugin.Log.LogWarning($"[{label}-LOBBY] prefs refused — seat gone or lobby started; resolving");
                        ResolveStaleSeat();
                    }
                    else
                    {
                        // Transport/5xx: keep the desired value queued; Tick
                        // retries after a short backoff.
                        prefsPumpRetryAt = Time.realtimeSinceStartup + 5f;
                        Plugin.Log.LogWarning($"[{label}-LOBBY] prefs update failed: {resp} — will retry");
                    }
                    NativeUI.MarkDirty();
                }));
            }

            /// <summary>Adopt a seat discovered by the MODE's queue poll (a
            /// still-armed queue poll seeing 'lobby' after an enroll converted
            /// its searching row). The state heartbeat owns it from here.</summary>
            public void AdoptSeatFromQueuePoll(string lobbyId)
            {
                if (Status == "leaving") return;   // a leave in flight outranks adoption
                if (!string.IsNullOrEmpty(lobbyId)) OpenLobbyId = OpenLobbyId ?? lobbyId;
                if (string.IsNullOrEmpty(OpenLobbyId)) return;
                confirmedMember = true;
                Status = "lobby";
                Polling = true; lastPollAt = -999f;
            }

            /// <summary>The MODE's queue poll reported our open seat lease-
            /// expired ('lobby_closed').</summary>
            public void HandleSeatExpired()
            {
                if (string.IsNullOrEmpty(OpenLobbyId) && Status != "lobby") return;
                ClearMembershipSilent();
                leaveIntent = false; leaveTarget = null;
                CompetitiveUI.ShowNotification(I18n.TrF("Your {0} lobby seat expired — join or create a new one.", label), new Color(1f, 0.75f, 0.4f), 6f);
            }

            /// <summary>One-shot membership discovery on tab open (FFA design
            /// review find 6): a relaunched client whose server row survived
            /// must find it before its seat lease expires. Harmless when
            /// nothing is held (not_in_lobby with no belief stops the poll).</summary>
            public void ProbeServerState()
            {
                if (probed || Polling) { probed = true; return; }
                probed = true;
                Polling = true; lastPollAt = -999f;
            }

            public void FetchLobbies(bool force = false)
            {
                if (!force && Time.unscaledTime - lobbiesLastAt < 3f) return;
                lobbiesLastAt = Time.unscaledTime;
                Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/{mode}/lobbies?steam_id={Escape(MatchTracker.LocalSteamId)}", (ok, resp) =>
                {
                    if (!ok || string.IsNullOrEmpty(resp))
                    {
                        // Old server / outage: show "unavailable", never an
                        // eternal "Loading..." (recon risk 6).
                        LobbiesUnavailable = true;
                        if (CachedLobbies == null) CachedLobbies = new List<HostLobbyOpenEntry>();
                        NativeUI.MarkDirty();
                        return;
                    }
                    LobbiesUnavailable = false;
                    try
                    {
                        var list = new List<HostLobbyOpenEntry>();
                        int aStart = resp.IndexOf("\"lobbies\"");
                        int arrStart = aStart >= 0 ? resp.IndexOf('[', aStart) : -1;
                        int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                        if (arrStart >= 0 && arrEnd > arrStart)
                        {
                            foreach (string obj in SliceTopLevelObjects(resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                            {
                                var e = new HostLobbyOpenEntry
                                {
                                    lobby_id = ExtractJsonString(obj, "lobby_id"),
                                    host_name = ExtractJsonString(obj, "host_name") ?? "?",
                                    player_count = ExtractJsonInt(obj, "player_count"),
                                    max_players = Math.Max(1, ExtractJsonInt(obj, "max_players")),
                                    age_seconds = ExtractJsonInt(obj, "age_seconds"),
                                    has_password = ExtractJsonBool(obj, "has_password"),
                                    members = ParseBrowserMembers(obj),
                                    bets_open = ExtractJsonBool(obj, "bets_open"),
                                    bet_targets = ParseBetTargets(obj),
                                    my_bet_amount = ExtractJsonInt(obj, "my_bet_amount"),
                                    my_bet_targets = ExtractJsonString(obj, "my_bet_targets") ?? "",
                                };
                                if (!string.IsNullOrEmpty(e.lobby_id)) list.Add(e);
                            }
                        }
                        CachedLobbies = list;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[{label}-LOBBY] browser parse: {ex.Message}"); }
                }));
            }

            /// <summary>Escape-hatch teardown — every local belief dies, no
            /// requests (the escape endpoint owns the server side).</summary>
            public void TearDown()
            {
                gen++;
                ClearMembershipSilent();
                Status = "";
                leaveIntent = false; leaveTarget = null;
                queueLeaveIntent = false; queueLeaveInFlight = false; queueLeaveAttempts = 0;
                queueLeaveSeriesId = null;
                prefsInFlight = false;
                prefsPending.Clear();
                actionInFlight = false;
            }
        }

        public static readonly HostLobbyClient TeamLobby = new HostLobbyClient("team", "2v2", 4);
        public static readonly HostLobbyClient OvtLobby = new HostLobbyClient("ovt", "1v2", 3);

        // Mode-specific enroll wrappers: the server's _LobbyCreateReq carries
        // preferred_team (2v2) / preferred_side + solo_extra_pick (1v2 — the
        // server ORs solo_extra_pick across members at Start, main.py comment
        // at _LobbyCreateReq; omitting it would make that OR always false).
        // Codex r2 f5-residual: every wrapper records the LOCAL SELECTION as
        // structured values first — the recovery-rejoin body is rebuilt from
        // those (never a join-time extras snapshot), and the prefs ack echo
        // keeps them server-true.
        public static void TeamLobbyCreate(int preferredTeam, string password = null)
        { TeamLobby.SetLocalTeamPref(preferredTeam); TeamLobby.Create(password, TeamLobbyExtras(preferredTeam)); }
        public static void TeamLobbyJoin(string lobbyId, int preferredTeam, string password = null)
        { TeamLobby.SetLocalTeamPref(preferredTeam); TeamLobby.Join(lobbyId, password, TeamLobbyExtras(preferredTeam)); }
        private static string TeamLobbyExtras(int preferredTeam)
            => (preferredTeam == 1 || preferredTeam == 2) ? $",\"preferred_team\":{preferredTeam}" : "";
        public static void OvtLobbyCreate(int preferredSide, bool soloExtraPick, string password = null)
        {
            OvtLobby.SetLocalOvtSide(preferredSide); OvtLobby.SetLocalOvtExtraPick(soloExtraPick);
            OvtLobby.Create(password, OvtLobbyExtras(preferredSide, soloExtraPick));
        }
        public static void OvtLobbyJoin(string lobbyId, int preferredSide, bool soloExtraPick, string password = null)
        {
            OvtLobby.SetLocalOvtSide(preferredSide); OvtLobby.SetLocalOvtExtraPick(soloExtraPick);
            OvtLobby.Join(lobbyId, password, OvtLobbyExtras(preferredSide, soloExtraPick));
        }
        // Codex r1 f4/f6/f7: seated preference changes are single-field
        // PATCHes on /lobby/prefs — never a whole lobby-JOIN resend (which
        // raced Start and resent stale sibling fields). 0 is an explicit
        // "Any"/clear and IS sent (f7 — the stale claim used to stand).
        public static void TeamLobbyPrefs(int preferredTeam)
        {
            TeamLobby.SetLocalTeamPref(preferredTeam);
            TeamLobby.SendPrefs($",\"preferred_team\":{((preferredTeam == 1 || preferredTeam == 2) ? preferredTeam : 0)}");
        }
        public static void OvtLobbyPrefsSide(int preferredSide)
        {
            OvtLobby.SetLocalOvtSide(preferredSide);
            OvtLobby.SendPrefs($",\"preferred_side\":{((preferredSide == 1 || preferredSide == 2) ? preferredSide : 0)}");
        }
        public static void OvtLobbyPrefsExtraPick(bool soloExtraPick)
        {
            OvtLobby.SetLocalOvtExtraPick(soloExtraPick);
            OvtLobby.SendPrefs($",\"solo_extra_pick\":{(soloExtraPick ? "true" : "false")}");
        }
        private static string OvtLobbyExtras(int preferredSide, bool soloExtraPick)
            => $",\"preferred_side\":{((preferredSide == 1 || preferredSide == 2) ? preferredSide : 0)},\"solo_extra_pick\":{(soloExtraPick ? "true" : "false")}";

        /// <summary>Aug 8 (Sid): kick refusal detail -> readable toast, or
        /// null for an unrecognized detail (caller falls back to DetailOr).
        /// Tokens are exact API contract.</summary>
        private static string KickRefusalText(string resp)
        {
            switch (ExtractJsonString(resp ?? "", "detail") ?? "")
            {
                case "not_host": return I18n.Tr("Only the host can kick players.");
                case "target_not_in_lobby": return I18n.Tr("They already left the lobby.");
                case "target_is_admin": return I18n.Tr("Admins can't be kicked.");
                case "cannot_kick_yourself": return I18n.Tr("You can't kick yourself.");
                default: return null;
            }
        }

        /// <summary>Aug 8 (Sid): browser member lines — WHO is inside each
        /// open lobby before joining. name/title are user-authored, so the
        /// slicing is string-aware (#156) and the renderer sanitizes.</summary>
        public class LobbyBrowserMember
        {
            public string name, title, title_color;
            public int rating;
            public bool established;   // 2v2/FFA: mode glicko vs 1v1 fallback
        }

        private static List<LobbyBrowserMember> ParseBrowserMembers(string lobbyObj)
        {
            try
            {
                // Review find 10: locate the KEY string-aware. A raw IndexOf
                // can land inside a user-authored display name that happens to
                // contain the token, and with bet_targets now emitted before
                // members that mis-hit would slice the wrong array (#156).
                int arrStart = FindJsonArrayStartStringAware(lobbyObj, "members");
                if (arrStart < 0) return null;   // old server — renderer degrades to one line
                int arrEnd = FindMatchingBracketStringAware(lobbyObj, arrStart);
                if (arrStart < 0 || arrEnd <= arrStart) return null;
                var list = new List<LobbyBrowserMember>();
                foreach (string m in SliceTopLevelObjects(lobbyObj.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                {
                    list.Add(new LobbyBrowserMember
                    {
                        name = ExtractJsonString(m, "name") ?? "?",
                        title = ExtractJsonString(m, "title") ?? "",
                        title_color = ExtractJsonString(m, "title_color") ?? "",
                        rating = ExtractJsonInt(m, "rating"),
                        established = ExtractJsonBool(m, "established"),
                    });
                }
                return list;
            }
            catch { return null; }
        }

        /// <summary>Aug 9 (Sid): one bettable target in a lobby-phase bet. The
        /// roster isn't final while a lobby is open, so these are the CURRENT
        /// members and a bet on someone who ends up not playing is refunded —
        /// the picker says so before the amount is entered.</summary>
        public class LobbyBetTarget
        {
            public string id, name;
        }

        /// <summary>Read an id that the server may serialize as a JSON number
        /// OR a quoted string. ExtractJsonInt is not usable here: a 17-digit
        /// steam id overflows int, and its int.Parse throw is swallowed into a
        /// silent 0 — which would post a bet against player "0".</summary>
        private static string ExtractJsonIdToken(string json, string key)
        {
            try
            {
                string quoted = ExtractJsonString(json, key);
                if (!string.IsNullOrEmpty(quoted)) return quoted;
                string search = $"\"{key}\":";
                int start = json.IndexOf(search, StringComparison.Ordinal);
                if (start < 0) return "";
                start += search.Length;
                while (start < json.Length && (json[start] == ' ' || json[start] == '\t')) start++;
                int end = start;
                while (end < json.Length && char.IsDigit(json[end])) end++;
                return end > start ? json.Substring(start, end - start) : "";
            }
            catch { return ""; }
        }

        /// <summary>Aug 9 (Sid): the lobby browser's "bet_targets" array. Names
        /// are user-authored, so the array slicing is string-aware (#156) —
        /// a display name containing '[' or '}' must not truncate the list.
        /// Returns null when the key is absent (old server), which the browser
        /// treats as "betting not available for this lobby".</summary>
        private static List<LobbyBetTarget> ParseBetTargets(string lobbyObj)
        {
            try
            {
                int arrStart = FindJsonArrayStartStringAware(lobbyObj, "bet_targets");
                if (arrStart < 0) return null;
                int arrEnd = FindMatchingBracketStringAware(lobbyObj, arrStart);
                if (arrEnd <= arrStart) return null;
                var list = new List<LobbyBetTarget>();
                foreach (string t in SliceTopLevelObjects(lobbyObj.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                {
                    string id = ExtractJsonIdToken(t, "id");
                    if (string.IsNullOrEmpty(id)) continue;
                    list.Add(new LobbyBetTarget
                    {
                        id = id,
                        name = ExtractJsonString(t, "name") ?? "",
                    });
                }
                return list;
            }
            catch { return null; }
        }

        /// <summary>Aug 9 (Sid): place a bet on a lobby that hasn't started
        /// yet. No odds are quoted at placement — the roster is not final, so
        /// the server prices the bet when the lobby locks and refunds it when
        /// the exact person/pair bet on isn't in the game that runs.
        /// mode is "team" or "ffa"; targetSteams is one steam id for ffa and
        /// the pair's two ids SORTED and joined with ':' for team.</summary>
        public static void PlaceLobbyBet(string bettorSteamId, string mode, string lobbyId,
            string targetSteams, int amount, Action<bool, string> callback)
        {
            // §2c identity fence: the broadcast service account never wagers.
            if (BroadcastMode.FenceBlocksFighterPath("bet-lobby")) { callback?.Invoke(false, "broadcast-fence"); return; }
            string sig = ComputeHmacHex($"lobby-bet:{bettorSteamId}:{mode}:{lobbyId}:{targetSteams}:{amount}");
            string url = $"{baseUrl}/api/v1/lobby-bets?steam_id={Escape(bettorSteamId)}" +
                         $"&mode={Escape(mode)}&lobby_id={Escape(lobbyId)}" +
                         $"&target_steams={Escape(targetSteams)}&amount={amount}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[LOBBY-BET] place {amount} on {mode} {targetSteams} (lobby {lobbyId}): ok={ok} resp={resp}");
                callback?.Invoke(ok, resp);
                if (ok)
                {
                    FetchPlayerStats(bettorSteamId);
                    RefreshLobbyBrowserFor(mode);
                }
            }));
        }

        /// <summary>Aug 9 (Sid): withdraw the caller's still-open lobby-phase
        /// bet. One bet per lobby, so the lobby identifies it — no bet id.</summary>
        public static void CancelLobbyBet(string bettorSteamId, string mode, string lobbyId,
            Action<bool, string> callback)
        {
            string sig = ComputeHmacHex($"lobby-bet-cancel:{bettorSteamId}:{mode}:{lobbyId}");
            string url = $"{baseUrl}/api/v1/lobby-bets/cancel?steam_id={Escape(bettorSteamId)}" +
                         $"&mode={Escape(mode)}&lobby_id={Escape(lobbyId)}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[LOBBY-BET] cancel {mode} lobby {lobbyId}: ok={ok} resp={resp}");
                callback?.Invoke(ok, resp);
                if (ok)
                {
                    FetchPlayerStats(bettorSteamId);
                    RefreshLobbyBrowserFor(mode);
                }
            }));
        }

        /// <summary>Re-pull the browser the bet was placed from so the row's
        /// bet state (and any server-side my_bet echo) refreshes immediately
        /// instead of on the next 3s throttle window.</summary>
        private static void RefreshLobbyBrowserFor(string mode)
        {
            if (mode == "ffa") FetchFfaLobbies(force: true);
            else if (mode == "team") TeamLobby.FetchLobbies(force: true);
        }

        /// <summary>Aug 8 (Sid): FFA host kicks a member — same contract as
        /// the team/ovt kicks (HostLobbyClient.Kick).</summary>
        public static void FfaKickFromLobby(string targetSteamId)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || string.IsNullOrEmpty(targetSteamId)) return;
            if (_ffaLobbyActionInFlight && Time.realtimeSinceStartup - _ffaLobbyActionAt > 30f)
                _ffaLobbyActionInFlight = false;
            if (_ffaLobbyActionInFlight) return;
            int gen = ffaGen;   // NOT ++: kicking must not orphan the poll lifecycle
            FfaLobbyActionBegin(); int actionGen = _ffaLobbyActionGen;
            string body = $"{{\"steam_id\":\"{Escape(sid)}\",\"target_steam_id\":\"{Escape(targetSteamId)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest($"{baseUrl}/api/v1/ffa/lobby/kick", body, (ok, resp) =>
            {
                FfaLobbyActionEnd(actionGen);
                if (gen != ffaGen) return;
                if (ok)
                {
                    Plugin.Log.LogInfo($"[FFA-LOBBY] kicked {targetSteamId}");
                    CompetitiveUI.ShowNotification(I18n.Tr("Player removed from the lobby."), new Color(1f, 0.75f, 0.4f), 4f);
                    UpdateFfaQueuePoll(force: true);   // pull the shrunken member list now
                }
                else
                {
                    Plugin.Log.LogWarning($"[FFA-LOBBY] kick failed: {resp}");
                    CompetitiveUI.ShowNotification(
                        KickRefusalText(resp) ?? DetailOr(resp, I18n.Tr("Couldn't kick that player.")),
                        new Color(1f, 0.6f, 0.2f), 5f);
                }
                NativeUI.MarkDirty();
            }));
        }

        public static void UpdateFfaQueueList(bool force = false)
        {
            if (!force && Time.unscaledTime - _ffaListLastAt < 2f) return;
            _ffaListLastAt = Time.unscaledTime;
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ffa/queue/list", (ok, resp) =>
            {
                if (!ok || string.IsNullOrEmpty(resp)) return;
                try
                {
                    var list = new List<FfaQueueListEntry>();
                    int qStart = resp.IndexOf("\"queuers\"");
                    int arrStart = qStart >= 0 ? resp.IndexOf('[', qStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        foreach (string obj in SliceTopLevelObjects(
                            resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                        {
                            list.Add(new FfaQueueListEntry
                            {
                                steam_id = ExtractJsonString(obj, "steam_id"),
                                display_name = ExtractJsonString(obj, "display_name"),
                                rating = ExtractJsonInt(obj, "rating"),
                                rating_1v1 = ExtractJsonInt(obj, "rating_1v1"),
                                status = ExtractJsonString(obj, "status"),
                                slot = ExtractJsonInt(obj, "slot"),
                                wait_seconds = ExtractJsonInt(obj, "wait_seconds"),
                                region = ExtractJsonString(obj, "region"),
                            });
                        }
                    }
                    CachedFfaQueueList = list;
                    NativeUI.MarkDirty();
                }
                catch (Exception ex) { Plugin.Log.LogWarning($"[FFA-QUEUE-LIST] parse: {ex.Message}"); }
            }));
        }

        public static void FetchFfaLeaderboard(int limit = 200, string sortBy = "rating")
        {
            Plugin.Instance.StartCoroutine(GetRequest($"{baseUrl}/api/v1/ffa/leaderboard?limit={limit}&sort_by={UnityWebRequest.EscapeURL(sortBy)}", (ok, resp) =>
            {
                if (!ok) return;
                try
                {
                    var entries = new List<FfaLeaderboardEntry>();
                    int eStart = resp.IndexOf("\"entries\"");
                    int arrStart = eStart >= 0 ? resp.IndexOf('[', eStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        foreach (string chunk in SliceTopLevelObjects(
                            resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                        {
                            entries.Add(new FfaLeaderboardEntry
                            {
                                rank = ExtractJsonInt(chunk, "rank"),
                                steam_id = ExtractJsonString(chunk, "steam_id"),
                                display_name = ExtractJsonString(chunk, "display_name"),
                                rating = ExtractJsonInt(chunk, "rating"),
                                rd = ExtractJsonInt(chunk, "rd"),
                                // Safe beside "rating": the reader searches for
                                // the quoted key, and "peak_rating" cannot match
                                // "\"rating\":" (the char before is '_').
                                peak_rating = ExtractJsonInt(chunk, "peak_rating"),
                                games_played = ExtractJsonInt(chunk, "games_played"),
                                wins = ExtractJsonInt(chunk, "wins"),
                                top3 = ExtractJsonInt(chunk, "top3"),
                                avg_placement = ExtractJsonFloat(chunk, "avg_placement"),
                                win_rate = ExtractJsonFloat(chunk, "win_rate"),
                                level = ExtractJsonInt(chunk, "level"),
                                title = ExtractJsonString(chunk, "title"),
                                title_color = ExtractJsonString(chunk, "title_color"),
                                ffa_gold_earned = ExtractJsonInt(chunk, "ffa_gold_earned"),
                                ffa_xp_earned = ExtractJsonInt(chunk, "ffa_xp_earned"),
                            });
                        }
                    }
                    CachedFfaLeaderboard = entries;
                    CachedFfaLeaderboardTotal = ExtractJsonInt(resp, "total_players");
                    NativeUI.MarkDirty();
                    Plugin.Log.LogInfo($"[FFA-LB] loaded {entries.Count} players");
                }
                catch (Exception ex) { Plugin.Log.LogError($"[FFA-LB] parse: {ex.Message}"); }
            }));
        }

        // F8: per-mode request generations. Paged fetches can complete out of
        // order (a slow page-1 response landing after a fast page-2 one would
        // clobber the newer page's caches). Bumped at REQUEST time; each
        // callback captures its own value and only the newest may write.
        // Coroutine callbacks run on the main thread, so plain ints suffice.
        private static int ffaRecentRankedGen;
        private static int ffaRecentCasualGen;

        public static void FetchFfaRecent(int page = 0, int pageSize = 5, bool ranked = true)
        {
            // ranked=true (the default, and every pre-existing caller) hits the
            // endpoint exactly as before and writes the ranked caches; false
            // asks the server's validated bool param for casual rows and writes
            // the CachedFfaRecentCasual* mirror instead. Same parser both ways —
            // it already handles null rating_change + is_ranked per row.
            string url = $"{baseUrl}/api/v1/ffa/recent?page={page}&page_size={pageSize}";
            if (!ranked) url += "&ranked=false";
            int gen = ranked ? ++ffaRecentRankedGen : ++ffaRecentCasualGen;
            Plugin.Instance.StartCoroutine(GetRequest(url, (ok, resp) =>
            {
                if (!ok) return;
                try
                {
                    var matches = ParseFfaRecentList(resp, out _);
                    // F8: superseded response — a newer request for this mode
                    // was issued after ours; its data must win. Drop ours.
                    if (gen != (ranked ? ffaRecentRankedGen : ffaRecentCasualGen))
                    {
                        Plugin.Log.LogInfo($"[FFA-RECENT] stale {(ranked ? "ranked" : "casual")} page {page} response dropped (superseded)");
                        return;
                    }
                    if (ranked)
                    {
                        CachedFfaRecent = matches;
                        CachedFfaRecentTotal = ExtractJsonInt(resp, "total");
                        CachedFfaRecentPages = ExtractJsonInt(resp, "total_pages");
                    }
                    else
                    {
                        CachedFfaRecentCasual = matches;
                        CachedFfaRecentCasualTotal = ExtractJsonInt(resp, "total");
                        CachedFfaRecentCasualPages = ExtractJsonInt(resp, "total_pages");
                    }
                    NativeUI.MarkDirty();
                    Plugin.Log.LogInfo($"[FFA-RECENT] loaded {matches.Count} {(ranked ? "ranked" : "casual")} matches (page {page})");
                }
                catch (Exception ex) { Plugin.Log.LogError($"[FFA-RECENT] parse: {ex.Message}"); }
            }));
        }

        /// <summary>Shared rich-match list parser for /ffa/recent responses —
        /// used by the F5 cache path above AND the report-private fetch (R1
        /// f15 reconciliation). shapeOk=false means the "matches" array was
        /// absent/unbalanced (a shape failure, not "empty").</summary>
        private static List<FfaRecentMatch> ParseFfaRecentList(string resp, out bool shapeOk)
        {
                    var matches = new List<FfaRecentMatch>();
                    shapeOk = false;
                    int mStart = resp.IndexOf("\"matches\"");
                    int arrStart = mStart >= 0 ? resp.IndexOf('[', mStart) : -1;
                    int arrEnd = arrStart >= 0 ? FindMatchingBracketStringAware(resp, arrStart) : -1;
                    if (arrStart >= 0 && arrEnd > arrStart)
                    {
                        shapeOk = true;
                        foreach (string mObj in SliceTopLevelObjects(
                            resp.Substring(arrStart + 1, arrEnd - arrStart - 1)))
                        {
                            var m = new FfaRecentMatch
                            {
                                match_id = ExtractJsonString(mObj, "match_id"),
                                photon_room_id = ExtractJsonString(mObj, "photon_room_id"),
                                ended_at = ExtractJsonString(mObj, "ended_at"),
                                started_at = ExtractJsonString(mObj, "started_at"),
                                winner_steam_id = ExtractJsonString(mObj, "winner_steam_id"),
                                player_count = ExtractJsonInt(mObj, "player_count"),
                                duration_seconds = ExtractJsonInt(mObj, "duration_seconds"),
                                is_ranked = ExtractJsonBool(mObj, "is_ranked"),
                                timeline = ExtractJsonString(mObj, "timeline"),
                            };
                            // "settings" is a nested OBJECT and is null for
                            // pre-config matches, so slice it explicitly
                            // rather than reading fields off the whole match
                            // blob (which would also match a player's keys).
                            int sIdx = mObj.IndexOf("\"settings\"");
                            int sOpen = sIdx >= 0 ? mObj.IndexOf('{', sIdx) : -1;
                            // A null settings value has no '{' before the next
                            // key, so bound the search to this match object.
                            if (sOpen >= 0)
                            {
                                int sClose = FindMatchingBraceStringAware(mObj, sOpen);
                                if (sClose > sOpen)
                                {
                                    string so = mObj.Substring(sOpen, sClose - sOpen + 1);
                                    m.score_target = ExtractJsonInt(so, "score_target");
                                    m.card_cap = ExtractJsonInt(so, "card_cap");
                                    m.initial_picks = ExtractJsonInt(so, "initial_picks");
                                    m.card_candidates = ExtractJsonInt(so, "card_candidates");
                                    m.same_card_rule = ExtractJsonBool(so, "same_card_rule");
                                    m.has_settings = m.score_target > 0;
                                }
                            }
                            int pStart = mObj.IndexOf("\"players\"");
                            int pArr = pStart >= 0 ? mObj.IndexOf('[', pStart) : -1;
                            int pEnd = pArr >= 0 ? FindMatchingBracketStringAware(mObj, pArr) : -1;
                            if (pArr >= 0 && pEnd > pArr)
                            {
                                foreach (string pObj in SliceTopLevelObjects(
                                    mObj.Substring(pArr + 1, pEnd - pArr - 1)))
                                {
                                    var rp = new FfaRecentPlayer
                                    {
                                        steam_id = ExtractJsonString(pObj, "steam_id"),
                                        display_name = ExtractJsonString(pObj, "display_name"),
                                        title = ExtractJsonString(pObj, "title"),
                                        title_color = ExtractJsonString(pObj, "title_color"),
                                        slot = ExtractJsonInt(pObj, "slot"),
                                        placement = ExtractJsonInt(pObj, "placement"),
                                        rounds_won = ExtractJsonInt(pObj, "rounds_won"),
                                        points_total = ExtractJsonInt(pObj, "points_total"),
                                        kills = ExtractJsonInt(pObj, "kills"),
                                        fps_avg = ExtractJsonInt(pObj, "fps_avg"),
                                        ping_avg = ExtractJsonInt(pObj, "ping_avg"),
                                        bullets_fired = ExtractJsonInt(pObj, "bullets_fired"),
                                        bullets_hit = ExtractJsonInt(pObj, "bullets_hit"),
                                        blocks_activated = ExtractJsonInt(pObj, "blocks_activated"),
                                        blocks_successful = ExtractJsonInt(pObj, "blocks_successful"),
                                        fps_timeline = ExtractJsonString(pObj, "fps_timeline"),
                                        ping_timeline = ExtractJsonString(pObj, "ping_timeline"),
                                        hit_timeline = ExtractJsonString(pObj, "hit_timeline"),
                                        block_timeline = ExtractJsonString(pObj, "block_timeline"),
                                        // Aug 6 item 4 — nullable reader (#257): null
                                        // => RECORD_NONE ("not recorded"), which the
                                        // DPS tag renders as a dash, not "0.0".
                                        damage_dealt = ExtractNullableInt(pObj, "damage_dealt"),
                                        damage_timeline = ExtractJsonString(pObj, "damage_dealt_timeline"),
                                        // Aug 12 item 1 — end-of-game build.
                                        // "" for every pre-migration-216 row.
                                        end_stats = ExtractJsonString(pObj, "end_stats"),
                                        xp_gained = ExtractJsonInt(pObj, "xp_gained"),
                                        gold_gained = ExtractJsonInt(pObj, "gold_gained"),
                                        left_early = ExtractJsonBool(pObj, "left_early"),
                                        absent = ExtractJsonBool(pObj, "absent"),
                                        color_name = ExtractJsonString(pObj, "color_name") ?? "",
                                        color_hex = ExtractJsonString(pObj, "color_hex") ?? "",
                                    };
                                    try
                                    {
                                        // rating_change may be null (unranked rows)
                                        int rcKey = pObj.IndexOf("\"rating_change\"", StringComparison.Ordinal);
                                        int rcColon = rcKey >= 0 ? pObj.IndexOf(':', rcKey + 15) : -1;
                                        int rcValue = rcColon + 1;
                                        while (rcValue > 0 && rcValue < pObj.Length &&
                                               (pObj[rcValue] == ' ' || pObj[rcValue] == '\t'))
                                            rcValue++;
                                        if (rcColon >= 0 && rcValue < pObj.Length && pObj[rcValue] != 'n')
                                        {
                                            rp.rating_change = ExtractJsonFloat(pObj, "rating_change");
                                            rp.has_rating_change = true;
                                        }
                                    }
                                    catch { }
                                    int cStart = pObj.IndexOf("\"cards\"");
                                    int cArr = cStart >= 0 ? pObj.IndexOf('[', cStart) : -1;
                                    int cEnd = cArr >= 0 ? FindMatchingBracketStringAware(pObj, cArr) : -1;
                                    if (cArr >= 0 && cEnd > cArr)
                                    {
                                        // Card names are user-authored mod data and
                                        // may contain commas or braces. Slice the
                                        // object array string-aware; never comma-split.
                                        foreach (string cObj in SliceTopLevelObjects(
                                            pObj.Substring(cArr + 1, cEnd - cArr - 1)))
                                        {
                                            rp.cards.Add(new FfaRecentCard
                                            {
                                                name = ExtractJsonString(cObj, "n"),
                                                rolled = ExtractJsonBool(cObj, "r"),
                                            });
                                        }
                                    }
                                    m.players.Add(rp);
                                }
                            }
                            matches.Add(m);
                        }
                    }
                    return matches;
        }

        private static bool TryExtractNullableJsonFloat(string json, string key, out float value)
        {
            value = 0f;
            if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(key)) return false;
            int keyAt = json.IndexOf("\"" + key + "\"", StringComparison.Ordinal);
            int colon = keyAt >= 0 ? json.IndexOf(':', keyAt + key.Length + 2) : -1;
            int pos = colon + 1;
            while (pos > 0 && pos < json.Length && (json[pos] == ' ' || json[pos] == '\t')) pos++;
            if (colon < 0 || pos >= json.Length || json[pos] == 'n') return false;
            value = ExtractJsonFloat(json, key);
            return true;
        }

        private static int FindJsonArrayStartStringAware(string json, string key)
        {
            if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(key)) return -1;
            for (int i = 0; i < json.Length; i++)
            {
                if (json[i] != '"') continue;
                int start = i + 1;
                int end = start;
                while (end < json.Length)
                {
                    if (json[end] == '\\') { end += 2; continue; }
                    if (json[end] == '"') break;
                    end++;
                }
                if (end >= json.Length) return -1;
                bool matches = end - start == key.Length
                    && string.CompareOrdinal(json, start, key, 0, key.Length) == 0;
                int pos = end + 1;
                while (pos < json.Length && char.IsWhiteSpace(json[pos])) pos++;
                if (matches && pos < json.Length && json[pos] == ':')
                {
                    pos++;
                    while (pos < json.Length && char.IsWhiteSpace(json[pos])) pos++;
                    if (pos < json.Length && json[pos] == '[') return pos;
                }
                i = end;
            }
            return -1;
        }

        private static List<string> ExtractStringListStringAware(string json, string key)
        {
            var values = new List<string>();
            if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(key)) return values;
            int open = FindJsonArrayStartStringAware(json, key);
            int close = open >= 0 ? FindMatchingBracketStringAware(json, open) : -1;
            if (open < 0 || close <= open) return values;
            int pos = open + 1;
            while (pos < close)
            {
                while (pos < close && json[pos] != '"') pos++;
                if (pos >= close) break;
                int quote = pos++;
                bool escaped = false;
                while (pos < close)
                {
                    char c = json[pos];
                    if (escaped) escaped = false;
                    else if (c == '\\') escaped = true;
                    else if (c == '"') break;
                    pos++;
                }
                if (pos >= close) break;
                string token = json.Substring(quote, pos - quote + 1);
                values.Add(ExtractJsonString(":" + token, ""));
                pos++;
            }
            return values;
        }

        public static void FetchPlayerModeHistories(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            FetchPlayerTeamHistory(steamId);
            FetchPlayerOvtHistory(steamId);
            FetchPlayerFfaHistory(steamId);
        }

        private static void FetchPlayerTeamHistory(string steamId)
        {
            if (CachedPlayerTeamHistory.ContainsKey(steamId) || !_playerTeamHistoryInFlight.Add(steamId)) return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/{Escape(steamId)}/team-history?limit=10",
                (ok, resp) =>
                {
                    _playerTeamHistoryInFlight.Remove(steamId);
                    if (!ok || string.IsNullOrEmpty(resp)) return;
                    try
                    {
                        var list = new List<PlayerTeamHistoryEntry>();
                        int open = FindJsonArrayStartStringAware(resp, "series");
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (open >= 0 && close > open)
                        {
                            foreach (string obj in SliceTopLevelObjects(resp.Substring(open + 1, close - open - 1)))
                            {
                                var entry = new PlayerTeamHistoryEntry
                                {
                                    series_id = ExtractJsonString(obj, "series_id"),
                                    won = ExtractJsonBool(obj, "won"),
                                    score = ExtractJsonString(obj, "score"),
                                    mate = ExtractJsonString(obj, "mate"),
                                    completed_at = ExtractJsonString(obj, "completed_at"),
                                    opponents = ExtractStringListStringAware(obj, "opponents"),
                                };
                                entry.has_rating_change = TryExtractNullableJsonFloat(
                                    obj, "rating_change", out entry.rating_change);
                                list.Add(entry);
                            }
                        }
                        CachedPlayerTeamHistory[steamId] = list;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[LB-MODE-HIST] 2v2 parse: {ex.Message}"); }
                }));
        }

