        // ── Report-private mode-history variants (R1 f9/f10/f12/f15) ────────
        // Twins of FetchPlayerTeamHistory / FetchPlayerFfaHistory for the
        // post-session report: SAME endpoint, SAME entry type, SAME parse —
        // but the result list is handed to the callback and NEVER written to
        // CachedPlayerTeamHistory/CachedPlayerFfaHistory (shared-cache reads
        // race the F5 tab, R1 f9), and no NativeUI.MarkDirty. transportOk
        // semantics per f10: false = HTTP or parse failure; (empty, true) = a
        // 200 whose history is genuinely empty.

        /// <summary>Report-private RICH 2v2 series for one participant —
        /// /team/all-series-paged?participant_steam_id= (server filter added
        /// Aug 19 for R1 f12: the global page hides a sitting behind newer
        /// unrelated series, and /team-history is too thin for the report's
        /// slots/telemetry/cards). Same TeamSeriesPagedEntry shape the F5
        /// 2v2 tab renders, parsed into a PRIVATE list — no shared cache,
        /// no MarkDirty (R1 f9).
        /// R2 f4: PAGINATED. One page of 20 can hide a watched sitting behind
        /// newer unrelated series, so pages are fetched SEQUENTIALLY and
        /// accumulated until (a) the server's total_pages is exhausted,
        /// (b) the oldest completed_at on a page is already OLDER than
        /// noOlderThanUtc (server orders newest-first, so nothing beyond that
        /// page can still be in the report window), or (c) a 5-page safety
        /// cap. ok=true ONLY when every fetched page was transport+shape ok
        /// AND the loop ended by (a) or (b); ending by the cap or any failed
        /// page reports the ACCUMULATED rows with ok=false so the consumer
        /// labels the section partial rather than printing an exact count.
        /// Null noOlderThanUtc = only (a)/(c) apply. (empty, true) = genuinely
        /// no series for that player.
        /// R3 f4: /team/all-series-paged is a MUTABLE LIMIT/OFFSET query with
        /// no id tie-breaker, so a series committing (or being invalidated)
        /// between two page requests shifts the window and can silently DROP a
        /// boundary row while every page still looks well-formed. ok=true is a
        /// completeness CLAIM, so it is withheld on any anomaly the loop can
        /// detect: a cross-page duplicate id (proves the window shifted), an
        /// empty page the server's own metadata says should have rows, or
        /// total_pages drifting between pages. Rows are still returned (the
        /// consumer renders them as a labeled floor). KEYSET pagination
        /// ordered by (completed_at, id) is the real fix — recorded as a
        /// follow-up, deliberately NOT attempted here.</summary>
        public static void FetchTeamHistoryForView(string steamId, DateTime? noOlderThanUtc, Action<List<TeamSeriesPagedEntry>, bool> callback)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") { callback?.Invoke(new List<TeamSeriesPagedEntry>(), false); return; }
            const int PAGE_SIZE = 20;   // server page_size le=20
            const int MAX_PAGES = 5;    // safety cap (c) — hitting it = ok=false
            var acc = new List<TeamSeriesPagedEntry>();
            // A series completing mid-pagination shifts every later page by
            // one, so a row can straddle a page boundary and arrive twice —
            // dedupe by series_id or the report double-counts it.
            var seen = new HashSet<string>();
            // R3 f4: a detected shift only ever DOWNGRADES the completeness
            // claim; it never drops rows and never aborts the run early (a
            // longer floor is strictly better for the report).
            bool windowShifted = false;
            int prevTotalPages = 0;     // 0 = unknown/absent, never compared against
            Action<int> fetchPage = null;
            fetchPage = page =>
            {
                Plugin.Instance.StartCoroutine(GetRequest(
                    $"{baseUrl}/api/v1/team/all-series-paged?page={page}&page_size={PAGE_SIZE}&participant_steam_id={Escape(steamId)}",
                    (ok, resp) =>
                    {
                        bool shapeOk = false;
                        List<TeamSeriesPagedEntry> rows = null;
                        // Blank/whitespace body on a 200 is a failed read, not
                        // an empty page (R2 f3's rule, applied here too).
                        if (ok && !string.IsNullOrWhiteSpace(resp))
                        {
                            try { rows = ParseTeamSeriesPagedList(resp, out shapeOk); }
                            catch (Exception ex) { Plugin.Log.LogWarning($"[REPORT-HIST] 2v2 parse (page {page}): {ex.Message}"); shapeOk = false; }
                        }
                        if (!shapeOk || rows == null)
                        {
                            // Mid-run transport/shape failure: hand back what
                            // we have, marked partial — never a clean count.
                            try { callback?.Invoke(acc, false); } catch { }
                            return;
                        }
                        int dupes = 0;
                        for (int i = 0; i < rows.Count; i++)
                        {
                            string k = rows[i].series_id ?? "";
                            if (k.Length == 0 || seen.Add(k)) acc.Add(rows[i]);
                            else dupes++;
                        }
                        int totalPages = ExtractJsonInt(resp, "total_pages");
                        // R3 f4 anomaly 1: a row we already have arriving again
                        // proves the OFFSET window moved between requests — the
                        // same shift that can drop a DIFFERENT row entirely.
                        if (dupes > 0)
                        {
                            windowShifted = true;
                            Plugin.Log.LogWarning($"[REPORT-HIST] 2v2 page {page}: {dupes} duplicate series_id(s) — window shifted, completeness withheld");
                        }
                        // R3 f4 anomaly 2: total_pages drifting mid-run means
                        // rows were added or removed under us. (R3's minimal fix
                        // says "metadata drift"; the fix delta names GROWTH.
                        // Either direction invalidates the offsets, and a
                        // shrink is the DELETION case that skips a boundary row
                        // without ever producing a duplicate, so both count.)
                        if (page > 0 && prevTotalPages > 0 && totalPages != prevTotalPages)
                        {
                            windowShifted = true;
                            Plugin.Log.LogWarning($"[REPORT-HIST] 2v2 page {page}: total_pages {prevTotalPages} -> {totalPages} mid-run — completeness withheld");
                        }
                        // R3 f4 anomaly 3 — THIS TEST RUNS BEFORE THE EXHAUSTION
                        // TEST ON PURPOSE. An empty page whose own (or the
                        // previous page's) metadata claims pages exist is a
                        // window shift, and the (a) test below would otherwise
                        // certify it as a clean end: total_pages=1 with a page
                        // that came back empty satisfies (page+1) >= totalPages
                        // and used to return ok=true with zero rows.
                        // total_pages is 0 ONLY when the server counted zero
                        // rows (main.py: `if total else 0`), so the genuinely
                        // empty history still reports (empty, true), and the
                        // absent-metadata fallback still treats a short/empty
                        // page as the end.
                        if (rows.Count == 0 && (totalPages > 0 || prevTotalPages > 0))
                        {
                            Plugin.Log.LogWarning($"[REPORT-HIST] 2v2 page {page} empty while total_pages={totalPages} (prev {prevTotalPages}) — reporting partial");
                            try { callback?.Invoke(acc, false); } catch { }
                            return;
                        }
                        prevTotalPages = totalPages;
                        // (a) exhausted: trust total_pages when present; a
                        // missing/zero total_pages (ExtractJsonInt's absent-key
                        // 0) falls back to "a short page proves the end".
                        bool exhausted = totalPages > 0 ? (page + 1) >= totalPages : rows.Count < PAGE_SIZE;
                        if (exhausted) { try { callback?.Invoke(acc, !windowShifted); } catch { } return; }
                        // (b) cutoff crossed: oldest stamp on THIS page already
                        // predates the window — later pages are older still.
                        if (noOlderThanUtc.HasValue)
                        {
                            DateTime? oldest = OldestTeamStampUtc(rows);
                            if (oldest.HasValue && oldest.Value < noOlderThanUtc.Value)
                            { try { callback?.Invoke(acc, !windowShifted); } catch { } return; }
                        }
                        if (page + 1 >= MAX_PAGES)
                        {
                            // (c) safety cap: rows are real but the run is
                            // provably incomplete — partial by contract.
                            Plugin.Log.LogWarning($"[REPORT-HIST] 2v2 pagination hit the {MAX_PAGES}-page safety cap — reporting partial");
                            try { callback?.Invoke(acc, false); } catch { }
                            return;
                        }
                        fetchPage(page + 1);
                    }));
            };
            fetchPage(0);
        }

        /// <summary>Oldest parseable completed_at across one page of 2v2
        /// series (UTC). Null when no row on the page carries a parseable
        /// stamp — the (b) cutoff rule then simply can't fire for that page.</summary>
        private static DateTime? OldestTeamStampUtc(List<TeamSeriesPagedEntry> rows)
        {
            DateTime? oldest = null;
            for (int i = 0; i < rows.Count; i++)
            {
                if (rows[i] == null) continue;
                if (TryParseServerUtc(rows[i].completed_at, out DateTime t)
                    && (!oldest.HasValue || t < oldest.Value)) oldest = t;
            }
            return oldest;
        }

        /// <summary>Oldest parseable ended_at across one page of FFA matches
        /// (UTC). Same contract as OldestTeamStampUtc.</summary>
        private static DateTime? OldestFfaStampUtc(List<FfaRecentMatch> rows)
        {
            DateTime? oldest = null;
            for (int i = 0; i < rows.Count; i++)
            {
                if (rows[i] == null) continue;
                if (TryParseServerUtc(rows[i].ended_at, out DateTime t)
                    && (!oldest.HasValue || t < oldest.Value)) oldest = t;
            }
            return oldest;
        }

        /// <summary>Server-UTC ISO stamp parse — the same style every other
        /// ISO read in this file uses (InvariantCulture, AssumeUniversal +
        /// AdjustToUniversal; e.g. ParseAlertExpiry), and byte-identical to
        /// PostSessionReport.TryParseUtc so the fetch cutoff and the report's
        /// window math can never disagree about one stamp.</summary>
        private static bool TryParseServerUtc(string iso, out DateTime dt)
        {
            dt = default(DateTime);
            if (string.IsNullOrEmpty(iso)) return false;
            try
            {
                return DateTime.TryParse(iso, System.Globalization.CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.AssumeUniversal | System.Globalization.DateTimeStyles.AdjustToUniversal,
                    out dt);
            }
            catch { return false; }
        }

        /// <summary>Report-private RICH FFA matches for one participant —
        /// /ffa/recent?participant_steam_id= (server filter added Aug 19 for
        /// R1 f15; the cap there rose to 30). Ranked and casual are separate
        /// server feeds (§6), and a watched FFA lobby can be either, so BOTH
        /// are fetched and merged newest-first into one PRIVATE list of the
        /// same FfaRecentMatch shape the F5 FFA tab renders — no shared
        /// cache, no MarkDirty (R1 f9).
        /// R2 f5: each leg PAGINATES (page_size=30) under the same rules as
        /// the 2v2 fetch — stop on (a) total_pages exhausted, (b) the page's
        /// oldest ended_at predating noOlderThanUtc, or (c) a 3-page safety
        /// cap; a leg is ok only when every page was transport+shape ok and
        /// it ended by (a)/(b). Null noOlderThanUtc = only (a)/(c).
        /// R2 f6: the two legs launch CONCURRENTLY (serial legs could each
        /// satisfy the 20s request timeout yet jointly blow the report's 30s
        /// deadline); a shared join fires the combined callback EXACTLY once
        /// after both settle. ok=false when EITHER leg failed so the report
        /// labels itself partial rather than asserting a clean zero (f10).</summary>
        public static void FetchFfaHistoryForView(string steamId, DateTime? noOlderThanUtc, Action<List<FfaRecentMatch>, bool> callback)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") { callback?.Invoke(new List<FfaRecentMatch>(), false); return; }
            // Join state shared by the two leg completions. Coroutine
            // callbacks run on the main thread (see the F8 generation note
            // above), so plain captured locals suffice — the fired flag
            // guards against a double-settle logic bug, not a data race.
            var rankedList = new List<FfaRecentMatch>();
            var casualList = new List<FfaRecentMatch>();
            bool rankedOk = false, casualOk = false;
            int settledLegs = 0;
            bool fired = false;
            Action settle = () =>
            {
                if (fired || settledLegs < 2) return;
                fired = true;
                var merged = new List<FfaRecentMatch>(rankedList.Count + casualList.Count);
                merged.AddRange(rankedList);
                merged.AddRange(casualList);
                // Newest first across both feeds; ended_at is server ISO
                // 8601 so ordinal string compare orders correctly.
                try { merged.Sort((a, b) => string.CompareOrdinal(b.ended_at ?? "", a.ended_at ?? "")); } catch { }
                try { callback?.Invoke(merged, rankedOk && casualOk); } catch { }
            };
            FfaHistoryForViewLeg(steamId, true, noOlderThanUtc, rankedList,
                ok => { rankedOk = ok; settledLegs++; settle(); });
            FfaHistoryForViewLeg(steamId, false, noOlderThanUtc, casualList,
                ok => { casualOk = ok; settledLegs++; settle(); });
        }

        /// <summary>One ranked-or-casual /ffa/recent pagination leg for
        /// FetchFfaHistoryForView. Appends into the caller-owned acc list
        /// (main-thread callbacks — no concurrent mutation) and reports leg
        /// success per the (a)/(b)/(c) contract documented on the caller.
        /// legDone is invoked exactly once per leg.
        /// R3 f4: /ffa/recent is the same MUTABLE LIMIT/OFFSET shape as
        /// /team/all-series-paged, so this leg runs the identical window-shift
        /// detector (duplicate id / metadata drift / metadata-contradicting
        /// empty page, the last checked BEFORE the exhaustion test) and
        /// withholds the leg's ok on any of them. Keyset pagination ordered by
        /// (ended_at, id) is the real fix — follow-up, not attempted here.</summary>
        private static void FfaHistoryForViewLeg(string steamId, bool ranked, DateTime? noOlderThanUtc,
            List<FfaRecentMatch> acc, Action<bool> legDone)
        {
            const int PAGE_SIZE = 30;   // server page_size le=30
            const int MAX_PAGES = 3;    // safety cap (c) — hitting it = leg ok=false
            string legName = ranked ? "ranked" : "casual";
            // Page-shift dupe guard (a match reported mid-pagination shifts
            // later pages) — same rule as the 2v2 fetch, keyed by match_id.
            var seen = new HashSet<string>();
            bool windowShifted = false;  // R3 f4 — downgrades ok, never drops rows
            int prevTotalPages = 0;      // 0 = unknown/absent, never compared against
            Action<int> fetchPage = null;
            fetchPage = page =>
            {
                // ranked=true is the endpoint default (matches every
                // pre-existing caller); only the casual leg passes the param.
                string url = $"{baseUrl}/api/v1/ffa/recent?page={page}&page_size={PAGE_SIZE}&participant_steam_id={Escape(steamId)}";
                if (!ranked) url += "&ranked=false";
                Plugin.Instance.StartCoroutine(GetRequest(url, (ok, resp) =>
                {
                    bool shapeOk = false;
                    List<FfaRecentMatch> rows = null;
                    // Blank/whitespace body on a 200 is a failed read, not an
                    // empty page (R2 f3's rule, applied here too).
                    if (ok && !string.IsNullOrWhiteSpace(resp))
                    {
                        try { rows = ParseFfaRecentList(resp, out shapeOk); }
                        catch (Exception ex) { Plugin.Log.LogWarning($"[REPORT-HIST] FFA {legName} parse (page {page}): {ex.Message}"); shapeOk = false; }
                    }
                    if (!shapeOk || rows == null) { legDone(false); return; }
                    int dupes = 0;
                    for (int i = 0; i < rows.Count; i++)
                    {
                        string k = rows[i].match_id ?? "";
                        if (k.Length == 0 || seen.Add(k)) acc.Add(rows[i]);
                        else dupes++;
                    }
                    int totalPages = ExtractJsonInt(resp, "total_pages");
                    // R3 f4 anomaly 1 — a re-served row proves the window moved.
                    if (dupes > 0)
                    {
                        windowShifted = true;
                        Plugin.Log.LogWarning($"[REPORT-HIST] FFA {legName} page {page}: {dupes} duplicate match_id(s) — window shifted, completeness withheld");
                    }
                    // R3 f4 anomaly 2 — metadata drift in EITHER direction (see
                    // the 2v2 leg's note: a shrink is the deletion case that
                    // skips a boundary row without producing a duplicate).
                    if (page > 0 && prevTotalPages > 0 && totalPages != prevTotalPages)
                    {
                        windowShifted = true;
                        Plugin.Log.LogWarning($"[REPORT-HIST] FFA {legName} page {page}: total_pages {prevTotalPages} -> {totalPages} mid-run — completeness withheld");
                    }
                    // R3 f4 anomaly 3 — BEFORE the exhaustion test (an empty
                    // page that satisfies (page+1) >= totalPages used to be
                    // certified complete). total_pages is 0 only when the
                    // server counted zero rows, so a genuinely empty feed still
                    // settles the leg ok.
                    if (rows.Count == 0 && (totalPages > 0 || prevTotalPages > 0))
                    {
                        Plugin.Log.LogWarning($"[REPORT-HIST] FFA {legName} page {page} empty while total_pages={totalPages} (prev {prevTotalPages}) — reporting partial");
                        legDone(false);
                        return;
                    }
                    prevTotalPages = totalPages;
                    // (a) exhausted — same total_pages/short-page fallback as
                    // the 2v2 fetch.
                    bool exhausted = totalPages > 0 ? (page + 1) >= totalPages : rows.Count < PAGE_SIZE;
                    if (exhausted) { legDone(!windowShifted); return; }
                    // (b) cutoff crossed: oldest ended_at on THIS page already
                    // predates the window — later pages are older still.
                    if (noOlderThanUtc.HasValue)
                    {
                        DateTime? oldest = OldestFfaStampUtc(rows);
                        if (oldest.HasValue && oldest.Value < noOlderThanUtc.Value) { legDone(!windowShifted); return; }
                    }
                    if (page + 1 >= MAX_PAGES)
                    {
                        // (c) safety cap: provably incomplete — partial.
                        Plugin.Log.LogWarning($"[REPORT-HIST] FFA {legName} pagination hit the {MAX_PAGES}-page safety cap — reporting partial");
                        legDone(false);
                        return;
                    }
                    fetchPage(page + 1);
                }));
            };
            fetchPage(0);
        }

        public static void FetchFfaBettable(string steamId)
        {
            if (_ffaBettableInFlight || string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            _ffaBettableInFlight = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/ffa/bettable?steam_id={Escape(steamId)}",
                (ok, resp) =>
                {
                    _ffaBettableInFlight = false;
                    if (!ok || string.IsNullOrEmpty(resp)) return;
                    try
                    {
                        var lobbies = new List<FfaBettableLobby>();
                        int open = FindJsonArrayStartStringAware(resp, "lobbies");
                        int close = open >= 0 ? FindMatchingBracketStringAware(resp, open) : -1;
                        if (open >= 0 && close > open)
                        {
                            foreach (string obj in SliceTopLevelObjects(resp.Substring(open + 1, close - open - 1)))
                            {
                                var lobby = new FfaBettableLobby
                                {
                                    lobby_id = ExtractJsonString(obj, "lobby_id"),
                                    player_count = ExtractJsonInt(obj, "player_count"),
                                    game_number = ExtractJsonInt(obj, "game_number"),
                                    is_member = ExtractJsonBool(obj, "is_member"),
                                    already_bet = ExtractJsonBool(obj, "already_bet"),
                                    bets_open = ExtractJsonBool(obj, "bets_open"),
                                };
                                int playersOpen = FindJsonArrayStartStringAware(obj, "players");
                                int playersClose = playersOpen >= 0
                                    ? FindMatchingBracketStringAware(obj, playersOpen) : -1;
                                if (playersOpen >= 0 && playersClose > playersOpen)
                                {
                                    foreach (string pObj in SliceTopLevelObjects(
                                        obj.Substring(playersOpen + 1, playersClose - playersOpen - 1)))
                                    {
                                        lobby.players.Add(new FfaBettablePlayer
                                        {
                                            steam_id = ExtractJsonString(pObj, "steam_id"),
                                            display_name = ExtractJsonString(pObj, "display_name"),
                                            rating = ExtractJsonInt(pObj, "rating"),
                                            odds_multiplier = ExtractJsonFloat(pObj, "odds_multiplier"),
                                            bettable = ExtractJsonBool(pObj, "bettable"),
                                        });
                                    }
                                }
                                lobbies.Add(lobby);
                            }
                        }
                        CachedFfaBettable = lobbies;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception ex) { Plugin.Log.LogWarning($"[FFA-BET] bettable parse: {ex.Message}"); }
                }));
        }

        public static void PlaceFfaBet(string bettorSteamId, string lobbyId,
            string betOnSteamId, int amount, int gameNumber, Action<bool, string> callback)
        {
            // §2c identity fence: the broadcast service account never wagers.
            if (BroadcastMode.FenceBlocksFighterPath("bet-ffa")) { callback?.Invoke(false, "broadcast-fence"); return; }
            // game_number is INSIDE the signature (server review find 2) so a
            // lost-response retry can never be replayed onto a later game.
            string sig = ComputeHmacHex($"ffa-bet:{bettorSteamId}:{lobbyId}:{betOnSteamId}:{amount}:{gameNumber}");
            string url = $"{baseUrl}/api/v1/ffa/bets?steam_id={Escape(bettorSteamId)}" +
                         $"&lobby_id={Escape(lobbyId)}&bet_on_steam_id={Escape(betOnSteamId)}" +
                         $"&amount={amount}&game_number={gameNumber}&sig={sig}";
            Plugin.Instance.StartCoroutine(PostRequest(url, "", (ok, resp) =>
            {
                Plugin.Log.LogInfo($"[FFA-BET] place {amount} on {betOnSteamId}: ok={ok} resp={resp}");
                callback?.Invoke(ok, resp);
                if (ok)
                {
                    FetchPlayerStats(bettorSteamId);
                    FetchFfaBettable(bettorSteamId);
                }
            }));
        }

        /// <summary>One participant's payload for an FFA match report.</summary>
        public class FfaReportPlayer
        {
            public string steamId, displayName;
            public int slot, rounds, points, kills, fps;
            public bool leftEarly;
            public bool absent;   // left in an EARLIER game of the sitting
            // Points the whole field had scored when this leaver left; drives
            // the server's early-leave grace. -1 = not applicable/not known
            // (a present player, or a ghost whose leave was an earlier game),
            // which omits the field so the server keeps pre-grace behaviour.
            public int gamePointsAtLeave = -1;
            public List<MatchTracker.CardPickData> cards;
            public TeamTelemetry telemetry;
            // Bugs #127/#130. Cumulative CSV ints on the 3s telemetry cadence,
            // plus the per-match total. Ride OUTSIDE the ffa: HMAC canonical
            // like the timelines do (kills, by contrast, IS signed since the
            // v2 canonical); old servers ignore them.
            public int damageDealt;
            public string killTimeline, damageTimeline;
            // Aug 12 item 1 — this seat's end-of-game BUILD wire string
            // (TabStatsOverlay.CaptureBuildStats). Null = not captured, which
            // omits the field. ADVISORY: outside the ffa: HMAC canonical, unlike
            // kills — do not add it to the canonical without a lockstep server
            // release, and do not add it at all (labels never cross the wire, so
            // there is nothing here worth signing).
            public string endStats;
        }

        /// <summary>Deterministic cross-language steam-id ordering used by the
        /// FFA HMAC canonical + slot assignment: (length, ordinal) — equals
        /// numeric order for canonical numeric ids; the server implements the
        /// identical comparison (main.py _ffa_sort_key).</summary>
        public static int FfaCompareSteamIds(string a, string b)
        {
            int la = (a ?? "").Length, lb = (b ?? "").Length;
            if (la != lb) return la.CompareTo(lb);
            return string.CompareOrdinal(a ?? "", b ?? "");
        }

        /// <summary>Report a finished FFA game to /ffa/matches. Variable-length
        /// domain-separated HMAC canonical (see schemas.py FfaMatchReport).</summary>
        public static void ReportFfaMatch(
            string lobbyId, string room, string region, int durationSeconds,
            List<FfaReportPlayer> players, string winnerSteam, string reporterSteam,
            string timeline = null)
        {
            if (RoomActors.LocalIsSpectator) return;   // spectator: never reports (design §3.5)
            // §2c identity fence: the broadcast account never reports.
            if (BroadcastMode.FenceBlocksFighterPath("report-ffa")) return;
            if (players == null || players.Count < 2)
            {
                Plugin.Log.LogWarning("[FFA-REPORT] not enough players to report");
                return;
            }
            // Clamp kills to the shared SATURATION bound (0..2000) BEFORE
            // building either the JSON body or the HMAC canonical — kills is
            // signed now, so body and canonical must carry the identical
            // value, and an out-of-bounds value would 422 the entire report.
            // Saturation is part of the ordering RULE (FfaMode.KillsRankFor
            // uses the same bound): full-wipe battles make raw kills
            // structurally unbounded, so above 2000 kills deliberately
            // compare EQUAL on every surface — client ordering, signed
            // report, and server placement all agree by definition.
            foreach (var p in players)
                p.kills = Math.Max(0, Math.Min(FfaMode.KillsCompareCap, p.kills));
            // §6 casual path: the lobby's ranked flag (from the frozen server
            // row via the poll payload) replaces the old hardcoded literal.
            // The server's ranked AUTHORITY is its own lobby row exclusively;
            // this signed claim is only compared against it as skew evidence
            // (a mismatch is logged server-side, never honored).
            bool isRanked = FfaMode.LobbyRanked;
            var sb = new StringBuilder();
            sb.Append("{");
            sb.Append($"\"lobby_id\":\"{Escape(lobbyId)}\",");
            sb.Append("\"players\":[");
            for (int i = 0; i < players.Count; i++)
            {
                var p = players[i];
                if (i > 0) sb.Append(",");
                sb.Append("{");
                sb.Append($"\"steam_id\":\"{Escape(p.steamId)}\",\"display_name\":\"{Escape(p.displayName ?? "Player")}\",");
                // kills is the SECOND placement tie-break (rounds, points,
                // kills — Sid approved 2026-08-03) and is now SIGNED: the v2
                // ffa: canonical carries it per player. The ffa: canonical is
                // the domain-tagged VARIABLE-length form (#213) — it may
                // evolve, but only in client/server lockstep; the server
                // accepts v1 (3-field) and v2 (4-field) for one release.
                sb.Append($"\"slot\":{p.slot},\"rounds_won\":{p.rounds}," +
                          $"\"points_total\":{p.points},\"kills\":{Math.Max(0, p.kills)}," +
                          $"\"left_early\":{(p.leftEarly ? "true" : "false")}," +
                          $"\"absent\":{(p.absent ? "true" : "false")},");
                sb.Append($"\"fps\":{Math.Max(0, p.fps)},");
                // Early-leave grace input (2026-08-20). Outside the frozen HMAC
                // canonical, like absent/damage_dealt — the server refutes it
                // against the SIGNED tally rather than trusting the number.
                // Omitted when negative so an old server, a present player and
                // a carried ghost all read identically to before.
                if (p.leftEarly && p.gamePointsAtLeave >= 0)
                    sb.Append($"\"game_points_at_leave\":{p.gamePointsAtLeave},");
                // Damage dealt + kill/damage timelines (#127/#130). Outside the
                // frozen HMAC canonical; omitted entirely when empty so an FFA
                // game with no data doesn't ship empty strings.
                sb.Append($"\"damage_dealt\":{Math.Max(0, p.damageDealt)},");
                if (!string.IsNullOrEmpty(p.killTimeline))
                    sb.Append($"\"kill_timeline\":\"{Escape(ClampTimeline(p.killTimeline, 512))}\",");
                if (!string.IsNullOrEmpty(p.damageTimeline))
                    sb.Append($"\"damage_dealt_timeline\":\"{Escape(ClampTimeline(p.damageTimeline, 1024))}\",");
                sb.Append("\"cards\":[");
                AppendCards(sb, p.cards ?? new List<MatchTracker.CardPickData>());
                sb.Append("]");
                // §10 offer baseline: the reporter attaches ITS OWN offered
                // candidates only (other seats' offers are unknowable client-
                // side when the same-card rule is off). Outside the canonical.
                if (p.steamId == reporterSteam && FfaMode.LocalOffers.Count > 0)
                {
                    sb.Append(",\"card_offers\":[");
                    int oc = 0;
                    foreach (var off in FfaMode.LocalOffers)
                    {
                        if (off == null || string.IsNullOrEmpty(off.CardName)) continue;
                        // 512 covers the structural max (~450 offers in a
                        // 10-player first-to-10 — Codex find 9; matches the
                        // server's truncation bound).
                        if (oc >= 512) break;
                        if (oc++ > 0) sb.Append(",");
                        sb.Append($"{{\"card_name\":\"{Escape(off.CardName)}\",\"round_number\":{Math.Max(1, off.Round)},\"was_picked\":{(off.Picked ? "true" : "false")}}}");
                    }
                    sb.Append("]");
                }
                if (p.telemetry != null)
                {
                    var t = p.telemetry;
                    sb.Append(",\"telemetry\":{");
                    sb.Append($"\"fps_timeline\":\"{Escape(ClampTimeline(t.fpsTimeline))}\",");
                    sb.Append($"\"ping_timeline\":\"{Escape(ClampTimeline(t.pingTimeline))}\",");
                    sb.Append($"\"ping_avg\":{Math.Max(0, Math.Min(30000, t.pingAvg))},");
                    sb.Append($"\"hit_timeline\":\"{Escape(ClampTimeline(t.hitTimeline, 1024))}\",");
                    sb.Append($"\"block_timeline\":\"{Escape(ClampTimeline(t.blockTimeline, 1024))}\",");
                    // null, not 0, when the peer predates the epoch: the server column is `int | None` so "not recorded" survives the wire, and a real 0 would read as "fired no shots".
                    sb.Append(t.bulletStatsKnown
                        ? $"\"bullets_fired\":{Math.Max(0, t.bulletsFired)},"
                        : "\"bullets_fired\":null,");
                    // null, not 0, when the peer predates the epoch: the server column is `int | None` so "not recorded" survives the wire, and a real 0 would read as "fired no shots".
                    sb.Append(t.bulletStatsKnown
                        ? $"\"bullets_hit\":{Math.Max(0, t.bulletsHit)},"
                        : "\"bullets_hit\":null,");
                    sb.Append($"\"blocks_activated\":{Math.Max(0, t.blocksActivated)},");
                    sb.Append($"\"blocks_successful\":{Math.Max(0, t.blocksSuccessful)},");
                    sb.Append($"\"keys_pressed\":{Math.Max(0, t.keysPressed)},");
                    sb.Append($"\"active_seconds\":{Math.Max(0f, t.activeSeconds).ToString("F1", System.Globalization.CultureInfo.InvariantCulture)}");
                    sb.Append("}");
                }
                // Aug 12 item 1 — end-of-game build. Last field of the entry so
                // it cannot land inside the telemetry object above; the entry
                // always has earlier fields, so the leading comma is safe.
                AppendEndStats(sb, p.endStats);
                sb.Append("}");
            }
            sb.Append("],");
            sb.Append($"\"winner_steam_id\":\"{Escape(winnerSteam)}\",");
            sb.Append($"\"photon_room_id\":\"{Escape(room)}\",\"game_version\":\"v{Application.version}\",");
            sb.Append($"\"region\":\"{Escape(region)}\",\"match_duration\":{durationSeconds},");
            sb.Append($"\"is_ranked\":{(isRanked ? "true" : "false")},");
            sb.Append($"\"reported_by_steam_id\":\"{Escape(reporterSteam)}\",");
            // Score-progression timeline (outside the frozen canonical).
            if (!string.IsNullOrEmpty(timeline))
                sb.Append($"\"timeline\":\"{Escape(timeline.Length > 1900 ? timeline.Substring(0, 1900) : timeline)}\",");
            // Canonical (v2): ffa:{lobby}:{room}:{reporter}:{is_ranked}:{winner}:{n}
            // then per player sorted by (len, ordinal): :{steam}:{rounds}:{points}:{kills}
            // kills MUST be the same clamped value the JSON body carries, or
            // the server's recomputation from the received fields won't match.
            var sorted = new List<FfaReportPlayer>(players);
            sorted.Sort((a, b) => FfaCompareSteamIds(a.steamId, b.steamId));
            var canon = new StringBuilder();
            canon.Append($"ffa:{lobbyId}:{room ?? ""}:{reporterSteam}:{(isRanked ? "true" : "false")}:{winnerSteam}:{players.Count}");
            foreach (var p in sorted)
                canon.Append($":{p.steamId}:{p.rounds}:{p.points}:{Math.Max(0, p.kills)}");
            sb.Append($"\"hmac_signature\":\"{ComputeHmacHex(canon.ToString())}\"");
            sb.Append("}");
            string json = sb.ToString();
            Plugin.Log.LogInfo($"[FFA-REPORT] submitting lobby={lobbyId} n={players.Count} winner={winnerSteam}");
            Plugin.Instance.StartCoroutine(PostRequestWithRetry($"{baseUrl}/api/v1/ffa/matches", json, (ok, resp) =>
            {
                if (ok)
                {
                    Plugin.Log.LogInfo($"[FFA] match reported: {resp}");
                    RefreshAchievementsAfterReport();
                    int myPlace = ExtractJsonInt(resp, "placement");
                    int xp = ExtractJsonInt(resp, "xp_gained");
                    if (myPlace > 0)
                        CompetitiveUI.ShowNotification(
                            myPlace == 1 ? I18n.TrF("FFA VICTORY! +{0}xp", xp) : I18n.TrF("FFA: placed #{0} (+{1}xp)", myPlace, xp),
                            myPlace == 1 ? Color.green : new Color(0.6f, 0.8f, 1f), 6f);
                }
                else
                {
                    Plugin.Log.LogWarning($"[FFA] report failed: {resp}");
                    EnqueueFailedReport($"{baseUrl}/api/v1/ffa/matches", json);
                }
            }, maxRetries: 3, retryDelay: 2f));
        }

        // ── Player Blocks (permanent, from leaderboard) ──────────

        public static HashSet<string> BlockedSteamIds { get; private set; } = new HashSet<string>();
        private static bool blocksLoaded = false;

        public static void FetchBlockedPlayers(string steamId)
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/players/blocks/{steamId}",
                (success, response) =>
                {
                    if (success)
                    {
                        BlockedSteamIds.Clear();
                        // Parse JSON array of steam IDs
                        int arrStart = response.IndexOf("[");
                        int arrEnd = response.IndexOf("]");
                        if (arrStart >= 0 && arrEnd > arrStart)
                        {
                            string arr = response.Substring(arrStart + 1, arrEnd - arrStart - 1);
                            if (!string.IsNullOrEmpty(arr))
                            {
                                foreach (string part in arr.Split(','))
                                {
                                    string sid = part.Trim().Trim('"');
                                    if (!string.IsNullOrEmpty(sid))
                                        BlockedSteamIds.Add(sid);
                                }
                            }
                        }
                        blocksLoaded = true;
                        NativeUI.MarkDirty();
                        Plugin.Log.LogInfo($"[BLOCKS] Loaded {BlockedSteamIds.Count} blocked players");
                    }
                }
            ));
        }

        public static bool IsPlayerBlocked(string steamId)
        {
            return BlockedSteamIds.Contains(steamId);
        }

        // ── Disconnect Reporting (leave % tracking) ─────────

        public static void ReportDisconnect(string reporterSteamId, string disconnectedSteamId)
        {
            // §2c identity fence: the broadcast service account never reports.
            if (BroadcastMode.FenceBlocksFighterPath("report-dc")) return;
            if (string.IsNullOrEmpty(reporterSteamId) || string.IsNullOrEmpty(disconnectedSteamId)) return;
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/report-disconnect?reporter_steam_id={Escape(reporterSteamId)}&disconnected_steam_id={Escape(disconnectedSteamId)}",
                "",
                (success, response) =>
                {
                    if (success)
                        Plugin.Log.LogInfo($"[DC] Reported disconnect by {disconnectedSteamId}: {response}");
                    else
                        Plugin.Log.LogWarning($"[DC] Failed to report disconnect: {response}");
                }
            ));
        }

        /// <summary>Aug 6 item 1 — casual rage-quit report. The surviving
        /// client reports a mid-game leave in a CASUAL 1v1 (any midgame
        /// leave, including 4-0 — Sid's rule). Server dedups per
        /// (room, leaver) and rate-limits per reporter.
        ///
        /// Since Aug 12 (item 12) this is ALSO the numerator of the reporter's
        /// own "opponents quit on me" rate, and the server now creates the
        /// leaver's row rather than 404-ing a first-encounter vanilla quitter.
        /// <paramref name="leaverDisplayName"/> is what stops that brand-new row
        /// showing a raw account id forever: pass the opponent's resolved
        /// nickname, never a placeholder — the server accepts any non-blank
        /// value that is not the steam id itself, so "Opponent" WOULD be stored
        /// as somebody's name.
        ///
        /// <paramref name="gameRoomId"/> (Aug 13) is the PER-GAME identity of
        /// the game being abandoned — see the parameter's own note below for
        /// why it is deliberately not the whole report id.</summary>
        public static void ReportCasualDc(string reporterSteamId, string leaverSteamId, string roomId,
                                          string leaverDisplayName = null, string gameRoomId = null)
        {
            // §2c identity fence: the broadcast service account never reports.
            if (BroadcastMode.FenceBlocksFighterPath("report-casual-dc")) return;
            if (string.IsNullOrEmpty(reporterSteamId) || string.IsNullOrEmpty(leaverSteamId)
                || string.IsNullOrEmpty(roomId)) return;
            /* Optional and advisory, so it must never cost us the report. The
             * server declares it Query(max_length=64) and FastAPI rejects the
             * whole request at 422 on overflow, so trim rather than risk that;
             * a trailing lone high surrogate (a split emoji) is dropped so the
             * UTF-8 encoding stays well-formed. Blank is omitted entirely —
             * the server would only fall back to the id anyway. */
            string nameQ = "";
            string nm = (leaverDisplayName ?? "").Trim();
            if (nm.Length > 64) nm = nm.Substring(0, 64);
            if (nm.Length > 0 && char.IsHighSurrogate(nm[nm.Length - 1])) nm = nm.Substring(0, nm.Length - 1);
            if (nm.Length > 0) nameQ = $"&leaver_display_name={UnityWebRequest.EscapeURL(nm)}";
            /* PER-GAME ID (Aug 13, closes the residual documented in main.py's
             * rage-quit block). `room_id` is the RAW Photon room name, and one
             * room hosts a whole sitting — production has rooms with 7 recorded
             * matches — so "some match exists in this room" cannot answer "was
             * the game they abandoned recorded?". The server currently
             * approximates that with an `m.ended_at >= e.created_at` ordering
             * test, which mis-handles the between-games leave.
             *
             * WHAT THIS VALUE IS, precisely: the STABLE prefix of the report id
             * the match report for this same game would carry —
             * GameStateWatcher.BuildReportRoomId() is "{room}_{token}_r{rounds}"
             * and this is "{room}_{token}", i.e. the same string with the score
             * suffix removed.
             *
             * THE SUFFIX MUST BE REMOVED, it is not a simplification. A leave at
             * 4-0 advances the awarded side to the terminal score BEFORE the
             * report is filed (#179), so the match row's suffix is "_r5" while
             * anything captured at leave time reads "_r4" — an equality test on
             * the full id would then be a constant miss, which is exactly the
             * failure the server already hit once (0 of 25 events matched by
             * equality). The server must PREFIX-match this, the same way it
             * already prefix-matches the room.
             *
             * WHEN THE TWO STRINGS PROVABLY AGREE, stated exactly rather than
             * as "they match":
             *   - the abandoned game itself: the survivor files both the DC
             *     event and the DC-decided report, so one client, one token,
             *     identical either way — including the local start-time
             *     fallback, which matters because this stat mostly measures
             *     VANILLA opponents, who never negotiate a shared token at all;
             *   - a between-games leave where the previous game's report came
             *     from a MODDED opponent: agrees iff both clients negotiated
             *     the shared per-game token (#174/#177). Against a modded peer
             *     on a pre-token build the two fall back to their own local
             *     start times and can differ.
             * That last case degrades to exactly today's behaviour — no
             * matching row means the event counts as an abandoned game, which
             * is what the ordering heuristic already concludes — so the id can
             * only make the number better or leave it unchanged, never worse.
             *
             * Optional and advisory: omitted entirely when the caller has no
             * value, and the server keeps its ordering heuristic for old
             * clients.
             *
             * Over-length is DROPPED, never truncated — the opposite of the
             * display name above. A truncated prefix is not a worse id, it is a
             * BROADER one: it would match every match in the room and silently
             * exclude a genuinely abandoned game from the denominator. Dropping
             * falls back to the server's existing heuristic, which is merely
             * imprecise. 96 chars is room (server cap 64) + '_' + a 6-digit
             * token with slack, so a legitimate value can never hit it; the
             * bound exists because FastAPI 422s the ENTIRE request on a Query
             * max_length overflow and this must never cost the report. */
            string gameQ = "";
            string gid = (gameRoomId ?? "").Trim();
            if (gid.Length > 96) gid = "";
            if (gid.Length > 0) gameQ = $"&game_room_id={UnityWebRequest.EscapeURL(gid)}";
            Plugin.Instance.StartCoroutine(PostRequest(
                /* EscapeURL, never Escape() — the latter is the JSON string
                 * escaper and does nothing useful in a query string (review
                 * find 10). Harmless for numeric steam ids, wrong by
                 * construction. */
                $"{baseUrl}/api/v1/matches/casual-dc?reporter_steam_id={UnityWebRequest.EscapeURL(reporterSteamId)}&leaver_steam_id={UnityWebRequest.EscapeURL(leaverSteamId)}&room_id={UnityWebRequest.EscapeURL(roomId)}{nameQ}{gameQ}",
                "",
                (success, response) =>
                {
                    if (success)
                        Plugin.Log.LogInfo($"[DC] Casual rage-quit recorded for {leaverSteamId}: {response}");
                    else
                        Plugin.Log.LogWarning($"[DC] Casual rage-quit report failed: {response}");
                }
            ));
        }

        public static void BlockPlayer(string mySteamId, string targetSteamId, Action<bool> callback = null)
        {
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/players/block?steam_id={Escape(mySteamId)}&target_steam_id={Escape(targetSteamId)}&sig={ComputeHmacHex($"block:{mySteamId}:{targetSteamId}")}",
                "",
                (success, response) =>
                {
                    if (success)
                    {
                        BlockedSteamIds.Add(targetSteamId);
                        Plugin.Log.LogInfo($"[BLOCKS] Blocked {targetSteamId}");
                        NativeUI.MarkDirty();
                    }
                    callback?.Invoke(success);
                }
            ));
        }

        public static void UnblockPlayer(string mySteamId, string targetSteamId, Action<bool> callback = null)
        {
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/players/unblock?steam_id={Escape(mySteamId)}&target_steam_id={Escape(targetSteamId)}&sig={ComputeHmacHex($"unblock:{mySteamId}:{targetSteamId}")}",
                "",
                (success, response) =>
                {
                    if (success)
                    {
                        BlockedSteamIds.Remove(targetSteamId);
                        Plugin.Log.LogInfo($"[BLOCKS] Unblocked {targetSteamId}");
                        NativeUI.MarkDirty();
                    }
                    callback?.Invoke(success);
                }
            ));
        }

        // ── HTTP helpers ──────────────────────────────────────

        // Column-cap clamp for the timeline CSVs. F8 (Codex r3 finding 8):
        // the old head-truncation kept the OLDEST prefix — 127 four-digit
        // pairs ≈ 1272 chars against the 1024 cap, so the newest ~25 samples
        // (including the FINAL TOTALS) were silently dropped from any long
        // game. DECIMATE-TO-FIT instead: drop every other INTERIOR sample
        // (the first and the LAST always survive) until the joined CSV fits.
        // The "v2|" dialect marker is preserved. Name/signature unchanged so
        // no call site moves.
        private static string ClampTimeline(string t, int max = 512)
        {
            t = t ?? "";
            if (t.Length <= max) return t;
            string prefix = "";
            if (t.StartsWith("v2|", StringComparison.Ordinal)) { prefix = "v2|"; t = t.Substring(3); }
            int budget = max - prefix.Length;
            var parts = t.Split(',');
            string joined = t;
            while (joined.Length > budget && parts.Length > 2)
            {
                var kept = new List<string>(parts.Length / 2 + 2) { parts[0] };
                for (int i = 2; i + 1 < parts.Length; i += 2) kept.Add(parts[i]);
                kept.Add(parts[parts.Length - 1]);
                parts = kept.ToArray();
                joined = string.Join(",", parts);
            }
            // Degenerate backstop (a single oversize sample / two-sample
            // floor still over budget): the cap is a hard server contract,
            // so hard-cut at the last full sample rather than exceed it.
            if (joined.Length > budget)
            {
                int cut = joined.LastIndexOf(',', Math.Min(budget, joined.Length) - 1);
                joined = cut > 0 ? joined.Substring(0, cut) : joined.Substring(0, Math.Max(0, budget));
            }
            return prefix + joined;
        }

        // July 21 review fix ([9]): 401 session_required recovery. Without this
        // a server-side-invalidated session (key flip, table wipe) blocked every
        // enforced write for up to ~23h — InvalidateSession was dead code. The
        // token compare guards the race where a slow in-flight request's 401
        // lands after a newer session was already minted.
        private static void HandleSessionReject(UnityWebRequest req, string sentToken)
        {
            try
            {
                if (req.responseCode != 401) return;
                string body = null;
                try { body = req.downloadHandler?.text; } catch { }
                if (body == null || !body.Contains("session_required")) return;
                SteamAuth.InvalidateSessionIf(sentToken);
                Plugin.Log.LogWarning("[STEAM-AUTH] server rejected session (401) — re-minting on next heartbeat");
            }
            catch { }
        }

        // F1 (Codex r3): authenticated REST must never ride plaintext HTTP to a
        // PUBLIC host — the TLS-probe fallback can retarget baseUrl to
        // Plugin.LegacyApiUrl (http://), and after that an on-path observer
        // would capture the 24h bearer off every request. The PRIVATE/loopback
        // carve-out is load-bearing: Sid's own dev config deliberately
        // overrides BaseUrl to http://192.168.72.90:8443 and must keep working.
        private static bool CredentialedTransportAllowed(string url)
        {
            if (string.IsNullOrEmpty(url)) return false;
            if (url.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) return true;
            if (!url.StartsWith("http://", StringComparison.OrdinalIgnoreCase)) return false;
            // Codex r4 f2: the first cut was a textual PREFIX test on a
            // hand-sliced host — "192.168.evil.example" and
            // "192.168.1.1@evil.example" both passed it. Parse properly,
            // refuse userinfo outright, and accept plaintext only for exact
            // localhost or a REAL IPv4 in the private/loopback ranges.
            try
            {
                Uri uri;
                if (!Uri.TryCreate(url, UriKind.Absolute, out uri)) return false;
                if (!string.IsNullOrEmpty(uri.UserInfo)) return false;
                string host = uri.Host;
                if (string.Equals(host, "localhost", StringComparison.OrdinalIgnoreCase)) return true;
                System.Net.IPAddress ip;
                if (!System.Net.IPAddress.TryParse(host, out ip)) return false;
                if (ip.AddressFamily != System.Net.Sockets.AddressFamily.InterNetwork) return false;
                byte[] b = ip.GetAddressBytes();
                return (b[0] == 192 && b[1] == 168)
                    || b[0] == 10
                    || b[0] == 127;
            }
            catch { return false; }
        }
        private static bool _loggedTokenWithheld;     // once-per-session log (F1)
        private static bool _insecureAuthNotified;    // once-per-session toast (F1)

        // Stamp every outbound API call with the mod's own version so the server
        // can reject (426) any client that drops below the configured floor.
        // July 21 item 4: also stamps the Steam session token when one is held —
        // the server binds it to our steam_id (spoof prevention). Absent token
        // is always allowed client-side; the server's enforcement mode decides.
        private static void StampVersionHeader(UnityWebRequest req)
        {
            try { req.SetRequestHeader("X-Mod-Version", Plugin.ModVersion ?? "0.0.0"); } catch { }
            try
            {
                if (!string.IsNullOrEmpty(SteamAuth.SessionToken))
                {
                    // F1: withhold the bearer on plaintext-to-public transport.
                    // The request still goes out anonymously — reads keep
                    // working; session-gated endpoints 401 and their features
                    // degrade, which is the accepted design.
                    if (CredentialedTransportAllowed(req.url))
                        req.SetRequestHeader("X-Session-Token", SteamAuth.SessionToken);
                    else if (!_loggedTokenWithheld)
                    {
                        _loggedTokenWithheld = true;
                        Plugin.Log.LogWarning("[STEAM-AUTH] plaintext public endpoint — X-Session-Token withheld (session-gated features degrade this session)");
                    }
                }
            }
            catch { }
        }

        /// <summary>July 21 item 4: exchange a Steam web-API auth ticket for a
        /// server session token. Called from SteamAuth's ticket callback.</summary>
        public static void PostSteamAuth(string ticketHex)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || Plugin.Instance == null) return;
            // F1 (Codex r3): never exchange a Steam ticket over plaintext to a
            // PUBLIC host — the returned 24h bearer would be capturable in
            // transit. SteamAuth keeps minting tickets on a 4s backoff while
            // no session lands, so the log + toast are once-per-session.
            if (!CredentialedTransportAllowed(baseUrl))
            {
                if (!_insecureAuthNotified)
                {
                    _insecureAuthNotified = true;
                    Plugin.Log.LogWarning($"[STEAM-AUTH] refusing ticket exchange over plaintext public endpoint {baseUrl} — signed-in features disabled this session");
                    try
                    {
                        CompetitiveUI.ShowNotification(I18n.Tr("Secure connection unavailable - signed-in features are disabled this session."), new Color(1f, 0.6f, 0.2f), 8f);
                    }
                    catch { }
                }
                return;
            }
            string json = $"{{\"steam_id\":\"{Escape(sid)}\",\"ticket_hex\":\"{Escape(ticketHex)}\",\"mod_version\":\"{Escape(Plugin.ModVersion ?? "0.0.0")}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/auth/steam",
                json,
                (success, response) =>
                {
                    if (!success)
                    {
                        Plugin.Log.LogWarning($"[STEAM-AUTH] session exchange failed: {response}");
                        return;
                    }
                    string token = ExtractJsonString(response, "session_token");
                    int expiresIn = ExtractJsonInt(response, "expires_in");
                    if (!string.IsNullOrEmpty(token)) SteamAuth.SetSession(token, expiresIn > 0 ? expiresIn : 86400);
                    else Plugin.Log.LogWarning("[STEAM-AUTH] session response had no token");
                }
            ));
        }

        // Paths that MUST work before consent is granted (version probe so we can auto-update
        // out-of-date clients regardless of consent state).
        private static bool IsConsentBypassed(string url)
        {
            if (string.IsNullOrEmpty(url)) return false;
            return url.Contains("/api/v1/mod-version");
        }

        // Short-circuit any data-carrying request when consent hasn't been granted.
        // Returns true if the caller should skip the request entirely.
        private static bool ConsentBlocksRequest(string url)
        {
            if (Plugin.DataConsentGranted) return false;
            if (IsConsentBypassed(url)) return false;
            return true;
        }

        /// <summary>Hook from the consent modal — kick the initial data fetches the moment
        /// the user grants consent (otherwise they'd wait for the next poll cycle).
        /// On revoke, drop the local cache AND turn off ranked mode so the mod runs
        /// completely offline — no API traffic, no ranked queue, no ongoing tracking.</summary>
        public static void OnConsentChanged()
        {
            if (Plugin.DataConsentGranted)
            {
                // Heal the consent trap (bug #47): if ranked was auto-disabled by a
                // previous revoke/decline (not by the user clicking Disable), restore
                // it now and re-sync the server. Otherwise the flag stayed false
                // forever, the startup sync kept pushing false, and every game vs
                // this player silently recorded casual.
                if (Plugin.RankedDisabledByConsent != null && Plugin.RankedDisabledByConsent.Value)
                {
                    Plugin.RankedDisabledByConsent.Value = false;
                    if (Plugin.RankedEnabled != null && !Plugin.RankedEnabled.Value)
                    {
                        Plugin.RankedEnabled.Value = true;
                        Plugin.Log.LogInfo("[CONSENT] Ranked mode restored on consent grant (was auto-disabled by revoke)");
                    }
                }
                string id = MatchTracker.LocalSteamId;
                if (!string.IsNullOrEmpty(id) && id != "unknown")
                {
                    ToggleRanked(id, Plugin.RankedEnabled != null && Plugin.RankedEnabled.Value);
                    FetchPlayerStats(id);
                    FetchMatchHistory(id);
                    FetchAchievements(id);
                    // Music [F16]: the startup warm fetch was consent-blocked
                    // (or its snapshot was revoke-invalidated), so entitlements
                    // need an authenticated snapshot NOW, not at the next
                    // shop-tab open.
                    FetchShopItems(id);
                }
                FetchLeaderboard();
                FetchRecentSeries();
                ChatClient.Connect();
            }
            else
            {
                // I10: epoch BEFORE the clears — an in-flight shop/inventory
                // response captured the old epoch at dispatch, so it can
                // never commit over the caches this revoke empties below.
                _shopCacheEpoch++;
                CachedLeaderboard = null;
                CachedPlayerStats = null;
                CachedCardStats = null;
                CachedMatchHistory = null;
                CachedRecentSeries = null;
                CachedRecentMultimode = null;
                CachedAchievements = null;
                CachedShopItems = null;
                CachedInventory = null;
                // Music [G11]: revoke outranks every in-flight shop response —
                // the store advances its generation past the dispatch high
                // water, clears, and fires Changed (engine stops custom
                // playback + reconciles to vanilla). Guarded so a music-side
                // throw can never abort the ranked-off flip below.
                try { MusicEntitlements.OnConsentRevoked(); } catch { }
                // Music ratings [M14]: same revoke semantics — floor advance
                // outranks in-flight fetches AND writes, own intent cleared.
                try { MusicRatings.OnConsentRevoked(); } catch { }
                CachedActiveSeries = null;
                ChatClient.Disconnect();
                // Flip ranked off — if the user is in queue, server rejects further polls (410)
                // and the queue entry expires via the cleanup cron. No more match reports will
                // leave the client because every helper short-circuits on !DataConsentGranted.
                // Mark WHY it flipped so a later consent grant can restore it — a plain flip
                // persisted as if the user chose Disable and never healed (bug #47).
                if (Plugin.RankedEnabled != null && Plugin.RankedEnabled.Value)
                {
                    Plugin.RankedEnabled.Value = false;
                    if (Plugin.RankedDisabledByConsent != null)
                        Plugin.RankedDisabledByConsent.Value = true;
                    Plugin.Log.LogInfo("[CONSENT] Ranked mode disabled due to revoke");
                }
            }
            NativeUI.MarkDirty();
        }

        // Detect server-side version-gate rejection. UnityWebRequest treats 4xx as
        // ProtocolError, so we look at responseCode rather than result.
        private static bool HandleVersionGate(UnityWebRequest req)
        {
            if (req.responseCode == 426)
            {
                if (!ForceUpdateRequired)
                    Plugin.Log.LogWarning("[VERSION] Server returned 426 — mod is below required version, gating UI");
                ForceUpdateRequired = true;
                return true;
            }
            return false;
        }

        // Heartbeat — track the most recent ATTEMPT and the most recent SUCCESS, separately.
        // Banner only shows when:  attempt within last 10s  AND  success was >5s before that attempt.
        // This prevents false-positives during quiet periods (no API calls = no info either way).
        public static float LastApiSuccessAt = -999f;
        public static float LastApiAttemptAt = -999f;
        public static bool LastResponseWasMaintenance = false;
        private static void NoteAttempt() { LastApiAttemptAt = Time.unscaledTime; }
        private static void NoteResult(bool success, long httpCode)
        {
            if (success) { LastApiSuccessAt = Time.unscaledTime; LastResponseWasMaintenance = false; }
            else if (httpCode == 503) { LastResponseWasMaintenance = true; }
        }
        /// <summary>True when we've recently TRIED to talk to the API and the most recent attempt
        /// hasn't succeeded — distinct from "haven't tried in a while".</summary>
        public static bool ApiLooksDown
        {
            get
            {
                if (LastApiAttemptAt < 0f) return false;
                float now = Time.unscaledTime;
                if (now - LastApiAttemptAt > 15f) return false;        // no recent attempts → don't claim down
                return (now - LastApiSuccessAt) > 10f;                  // attempts happening but no recent success
            }
        }

        /// <param name="detailedErrors">Report failures through FormatRequestError
        /// (status + response body) instead of Unity's bare status text. Opt-in
        /// because the default shape is what ~100 existing callers log; the
        /// admin reads need it because every refusal on those endpoints is a
        /// FastAPI {"detail": ...} that has to reach the operator verbatim —
        /// "HTTP/1.1 403 Forbidden" cannot tell a moderator that their grant
        /// does not cover a channel.</param>
        /// <summary>Codex r4 f1: refuse SENSITIVE payloads on plaintext-to-
        /// public transport. The r3 gate covered only the session bearer;
        /// admin-HMAC requests (signed with each admin's REAL per-config
        /// secret) and lobby passwords were still dispatched. Scope is
        /// deliberate: match-report HMACs are deterrent-tier (the secret
        /// ships in every DLL, #188 family), so blocking them would break
        /// core reporting for fallback users while protecting nothing.</summary>
        private static bool _loggedSensitiveBlocked;
        private static bool SensitiveTransportBlocked(string url, string json,
            Action<bool, string> callback)
        {
            // CONSUME the admin-credential latch on every request, whatever
            // the transport — leaving it armed would make the NEXT unrelated
            // request inherit it (learning #319's structural gate).
            bool adminSigned = _nextRequestCarriesAdminCredential;
            _nextRequestCarriesAdminCredential = false;
            try
            {
                if (CredentialedTransportAllowed(url)) return false;
                // Codex r5 f1/f2: admin-HMAC traffic is identified by the
                // admin_steam_id credential it carries, not by a path prefix
                // (/bug-reports/* and /chat/moderate/* are admin surfaces
                // too, while player bug SUBMISSION must keep working on the
                // fallback). The password match is the KEY TOKEN "password":
                // — a value can never contain that raw sequence because
                // in-string quotes are escaped, so a player literally named
                // password no longer poisons their own match reports.
                // Codex r6 f1/f2: /chat/moderate/* is an admin surface whose
                // bodies carry a plain "steam_id" (the TARGET), so the
                // credential match alone missed it — and the credential token
                // is COLON-anchored, because a player literally named
                // admin_steam_id would otherwise block their own match
                // reports (a value can't contain the raw key sequence; its
                // quotes arrive escaped).
                // adminSigned is the STRUCTURAL half and covers every
                // admin-HMAC surface by construction. The URL/body matches
                // stay as defence-in-depth for the non-signed sensitive
                // payloads (lobby passwords) and as a belt-and-braces net if
                // a future admin path ever bypasses ComputeAdminHmacHex.
                bool sensitive =
                    adminSigned
                    || url.IndexOf("/admin/", StringComparison.OrdinalIgnoreCase) >= 0
                    || url.IndexOf("/chat/moderate/", StringComparison.OrdinalIgnoreCase) >= 0
                    || url.IndexOf("admin_steam_id=", StringComparison.OrdinalIgnoreCase) >= 0
                    || (json != null
                        && (json.IndexOf("\"admin_steam_id\":", StringComparison.Ordinal) >= 0
                            || json.IndexOf("\"password\":", StringComparison.Ordinal) >= 0));
                if (!sensitive) return false;
                if (!_loggedSensitiveBlocked)
                {
                    _loggedSensitiveBlocked = true;
                    Plugin.Log.LogWarning("[API] plaintext public endpoint — admin/password requests are refused this session");
                }
            }
            catch { return false; }
            callback(false, "insecure-transport");
            return true;
        }

        /// <param name="sessionAware">Run HandleSessionReject on the response
        /// (M21 — GETs historically stamped the token but never consumed a
        /// 401 session_required, so a server-invalidated session 401-looped
        /// private GET reads until the ~23h expiry). Opt-in: only private
        /// per-identity reads need it — music ratings /mine, and the artist
        /// private reads (my-submissions, cosmetic-preview; N1) — while the
        /// ~100 public-read callers keep their exact current behavior.</param>
        private static IEnumerator GetRequest(string url, Action<bool, string> callback,
            bool detailedErrors = false, bool sessionAware = false)
        {
            if (ConsentBlocksRequest(url)) { callback(false, "no-consent"); yield break; }
            if (SensitiveTransportBlocked(url, null, callback)) yield break;
            NoteAttempt();
            using (var request = UnityWebRequest.Get(url))
            {
                StampVersionHeader(request);
                // Capture the token this request rides out with (same pattern
                // as PostRequest): the compare inside HandleSessionReject
                // guards the race where a slow 401 lands after a newer
                // session was already minted.
                string _sentTok = sessionAware ? SteamAuth.SessionToken : null;
                request.timeout = 20;
                yield return request.SendWebRequest();

                if (HandleVersionGate(request)) { callback(false, "outdated"); yield break; }
                if (sessionAware) HandleSessionReject(request, _sentTok);
                bool success = request.result == UnityWebRequest.Result.Success;
                NoteResult(success, request.responseCode);
                callback(success, success
                    ? request.downloadHandler.text
                    : (detailedErrors ? FormatRequestError(request) : request.error));
            }
        }

        private static IEnumerator PostRequest(string url, string json, Action<bool, string> callback)
        {
            if (ConsentBlocksRequest(url)) { callback(false, "no-consent"); yield break; }
            if (SensitiveTransportBlocked(url, json, callback)) yield break;
            NoteAttempt();
            using (var request = new UnityWebRequest(url, "POST"))
            {
                if (!string.IsNullOrEmpty(json))
                {
                    byte[] bodyRaw = Encoding.UTF8.GetBytes(json);
                    request.uploadHandler = new UploadHandlerRaw(bodyRaw);
                }
                request.downloadHandler = new DownloadHandlerBuffer();
                request.SetRequestHeader("Content-Type", "application/json");
                StampVersionHeader(request);
                string _sentTok = SteamAuth.SessionToken;
                request.timeout = 20;

                yield return request.SendWebRequest();

                if (HandleVersionGate(request)) { callback(false, "outdated"); yield break; }
                HandleSessionReject(request, _sentTok);
                bool success = request.result == UnityWebRequest.Result.Success;
                NoteResult(success, request.responseCode);
                callback(
                    success,
                    success
                        ? request.downloadHandler.text
                        : FormatRequestError(request));
            }
        }

        private static string FormatRequestError(UnityWebRequest request)
        {
            if (request == null) return "request failed";
            // Carry the RESPONSE BODY, not just Unity's status text (lobby
            // impl review round 2 find 4): FastAPI's {"detail": ...} is how a
            // 4xx explains itself, and discarding it made "the server judged
            // this" indistinguishable from a transport timeout. The
            // "HTTP <code>:" prefix is load-bearing — the report outbox
            // pattern-matches it for permanence.
            string body = "";
            try { body = request.downloadHandler?.text ?? ""; } catch { }
            if (body.Length > 300) body = body.Substring(0, 300);
            return request.responseCode > 0
                ? $"HTTP {request.responseCode}: {(string.IsNullOrEmpty(body) ? request.error : body)}"
                : request.error;
        }

        /// <summary>POST with automatic retry on failure (DNS hiccups, timeouts).</summary>
        private static IEnumerator PostRequestWithRetry(string url, string json, Action<bool, string> callback, int maxRetries = 3, float retryDelay = 2f)
        {
            if (ConsentBlocksRequest(url)) { callback(false, "no-consent"); yield break; }
            if (SensitiveTransportBlocked(url, json, callback)) yield break;
            for (int attempt = 1; attempt <= maxRetries; attempt++)
            {
                NoteAttempt();
                using (var request = new UnityWebRequest(url, "POST"))
                {
                    if (!string.IsNullOrEmpty(json))
                    {
                        byte[] bodyRaw = Encoding.UTF8.GetBytes(json);
                        request.uploadHandler = new UploadHandlerRaw(bodyRaw);
                    }
                    request.downloadHandler = new DownloadHandlerBuffer();
                    request.SetRequestHeader("Content-Type", "application/json");
                    StampVersionHeader(request);
                    string _sentTok = SteamAuth.SessionToken;
                    request.timeout = 10;

                    yield return request.SendWebRequest();

                    if (HandleVersionGate(request)) { callback(false, "outdated"); yield break; }
                    HandleSessionReject(request, _sentTok);

                    bool success = request.result == UnityWebRequest.Result.Success;
                    NoteResult(success, request.responseCode);
                    if (success)
                    {
                        callback(true, request.downloadHandler.text);
                        yield break;
                    }

                    Plugin.Log.LogWarning($"[HTTP] POST attempt {attempt}/{maxRetries} failed: {request.error}");

                    if (attempt < maxRetries)
                        // Network recovery must keep moving while ROUNDS pauses
                        // or slows game time on result/menu screens.
                        yield return new WaitForSecondsRealtime(retryDelay);
                    else
                        callback(false, FormatRequestError(request));
                }
            }
        }

        // ── Discord Linking ──────────────────────────────────────

        public static void GenerateLinkCode(string steamId)
        {
            // Bug #274: this broadcast CLIENT does not generate link codes.
            // Its Home tab is on a 24/7 stream, and this call's success path
            // paints the 6-char code into a 15s cyan toast, an unmasked log
            // line, and the Home panel — three readable copies on camera. The
            // code is a BEARER credential: the bot binds whoever types
            // "!link <code>" with no proof of ownership, so anyone reading it
            // off the stream inside its 10-minute life takes the account's
            // Discord link. Owner's call (Aug 24): stop this seat generating
            // codes rather than masking the UI.
            //
            // SCOPE, stated honestly: this is a CLIENT gate and therefore only
            // stops US from minting a code (learning #159 — a client-side gate
            // is a rendering suggestion, not a gate). The server's
            // POST /players/link-code takes a bare steam_id and has NO
            // authentication, so anyone can still mint a code for any account
            // and bind their own Discord to it. That hole is real, affects all
            // players rather than just this seat, and needs a server fix; it is
            // reported separately and is NOT closed here.
            if (BroadcastMode.IsBroadcastIdentity)
            {
                Plugin.Log.LogInfo("[LINK] broadcast identity — link-code generation suppressed on this client (bug #274)");
                try
                {
                    CompetitiveUI.ShowNotification(
                        I18n.Tr("Link codes are disabled on the broadcast seat."),
                        new Color(1f, 0.8f, 0.4f), 5f);
                }
                catch { }
                return;
            }
            // Strict-session endpoint as of 2026-08-25 (the mint is now gated on
            // a verified Steam session, because the code it returns is a bearer
            // credential — see the server side). Pre-filter rather than firing a
            // request we know will 401, and SAY SO: the pre-existing failure text
            // is a flat red "Couldn't get a link code", which for the dominant
            // real case — the first seconds after launch, before SteamAuth has
            // minted — reads as broken when it is merely early.
            if (string.IsNullOrEmpty(SteamAuth.SessionToken))
            {
                Plugin.Log.LogInfo("[LINK] no Steam session yet — link-code request suppressed");
                try
                {
                    CompetitiveUI.ShowNotification(
                        I18n.Tr("Steam sign-in still pending - try again in a moment."),
                        new Color(1f, 0.8f, 0.4f), 5f);
                }
                catch { }
                return;
            }
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/players/link-code?steam_id={Escape(steamId)}",
                "",
                (success, response) =>
                {
                    if (success)
                    {
                        string code = ExtractJsonString(response, "code");
                        if (!string.IsNullOrEmpty(code))
                        {
                            Plugin.Log.LogInfo($"[LINK] Generated link code: {code}");
                            CompetitiveUI.ShowNotification(I18n.TrF("Link code: {0}", code), Color.cyan, 15f);
                            NativeUI.SetLinkCode(code);
                        }
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[LINK] Failed to generate code: {response}");
                        CompetitiveUI.ShowNotification("Couldn't get a link code", new Color(1f, 0.4f, 0.4f));
                    }
                }
            ));
        }

        // ── LFP Discord ping (July 21 item 8) ─────────────────────
        // All outcomes are HTTP 200 + a status field (the transport surfaces
        // only request.error on non-2xx, so a 429-style design would lose the
        // remaining-time info). Message uses JsonEscapeFull — user-typed text
        // can carry control chars (learning #100).
        public static void SendLfpPing(string steamId, string message, int expiresMinutes, string modes = "1v1")
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            // modes is client-constructed from fixed constants ("1v1,ffa"), so
            // plain Escape is enough; the server re-validates against its own
            // allowlist anyway.
            string json = $"{{\"steam_id\":\"{Escape(steamId)}\",\"message\":\"{JsonEscapeFull(message ?? "")}\",\"expires_minutes\":{expiresMinutes},\"modes\":\"{Escape(modes ?? "1v1")}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/lfp-ping",
                json,
                (success, response) =>
                {
                    if (!success)
                    {
                        CompetitiveUI.ShowNotification("RLFP ping failed - server unreachable. Try again shortly.", new Color(1f, 0.5f, 0.4f), 6f);
                        return;
                    }
                    string status = ExtractJsonString(response, "status");
                    switch (status)
                    {
                        case "queued":
                            NativeUI.LfpArmCooldown(ExtractJsonInt(response, "cooldown_seconds"));
                            CompetitiveUI.ShowNotification("Posted to Discord - good luck!", new Color(0.5f, 1f, 0.6f), 6f);
                            break;
                        case "cooldown":
                            int left = ExtractJsonInt(response, "seconds_left");
                            NativeUI.LfpArmCooldown(left);
                            CompetitiveUI.ShowNotification(I18n.TrF("RLFP ping available in {0}m {1}s (1 per hour).", left / 60, left % 60), new Color(1f, 0.8f, 0.3f), 6f);
                            break;
                        case "not_linked":
                            CompetitiveUI.ShowNotification("Link your Discord account first (Home tab) to use RLFP pings.", new Color(1f, 0.8f, 0.3f), 7f);
                            break;
                        case "ranked_disabled":
                            CompetitiveUI.ShowNotification("Enable Ranked first - the RLFP ping is for ranked matches.", new Color(1f, 0.8f, 0.3f), 6f);
                            break;
                        default:
                            CompetitiveUI.ShowNotification(I18n.TrF("RLFP ping failed: {0}", status), new Color(1f, 0.5f, 0.4f), 6f);
                            break;
                    }
                }
            ));
        }

        // ── Achievements ──────────────────────────────────────────

        // July 21 item 7: click an achievement row → who earned it, sorted by
        // current 1v1 elo. Display names are ADVERSARIAL input (learning #156)
        // — sliced with the string-aware helpers, never naive Split.
        public class AchEarnerData
        {
            public string display_name;
            public int rating;          // -1 = unrated
            public string unlocked_at;
            // July 22: the earner's displayed title (server-resolved, same as leaderboard).
            public string title, title_color;
        }
        public static string EarnersKey { get; private set; }
        public static List<AchEarnerData> CachedEarners { get; private set; }
        // July 22 item 4: full earner count from the server (the list itself is
        // capped at 500 rows) so the header can't under-report.
        public static int CachedEarnersTotal { get; private set; }
        private static bool _earnersInFlight;
        // Review fix [7]: last-write-wins intent — a click during an in-flight
        // fetch records the WANTED key; the callback re-fires for it, so the
        // panel can't stick on "loading" over a stale list.
        private static string _earnersWantedKey;

        public static void FetchAchievementEarners(string achievementKey)
        {
            if (string.IsNullOrEmpty(achievementKey)) return;
            _earnersWantedKey = achievementKey;
            if (_earnersInFlight) return;
            _earnersInFlight = true;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/achievements/{achievementKey}/earners",
                (success, response) =>
                {
                    _earnersInFlight = false;
                    if (!success)
                    {
                        Plugin.Log.LogWarning($"[ACH] earners fetch failed: {response}");
                        if (_earnersWantedKey != null && _earnersWantedKey != achievementKey)
                            FetchAchievementEarners(_earnersWantedKey);   // superseded — serve the newer click
                        return;
                    }
                    try
                    {
                        var list = new List<AchEarnerData>();
                        int arrIdx = response.IndexOf("\"earners\":");
                        if (arrIdx >= 0)
                        {
                            int open = response.IndexOf('[', arrIdx);
                            int close = open >= 0 ? FindMatchingBracketStringAware(response, open) : -1;
                            if (open >= 0 && close > open)
                            {
                                foreach (var chunk in SliceTopLevelObjects(response.Substring(open + 1, close - open - 1)))
                                {
                                    var e = new AchEarnerData
                                    {
                                        display_name = ExtractJsonString(chunk, "display_name"),
                                        unlocked_at = ExtractJsonString(chunk, "unlocked_at"),
                                        rating = chunk.Contains("\"rating\":null") ? -1 : ExtractJsonInt(chunk, "rating"),
                                        title = ExtractJsonString(chunk, "title"),
                                        title_color = ExtractJsonString(chunk, "title_color"),
                                    };
                                    if (!string.IsNullOrEmpty(e.display_name)) list.Add(e);
                                }
                            }
                        }
                        EarnersKey = achievementKey;
                        CachedEarners = list;
                        CachedEarnersTotal = ExtractJsonInt(response, "total");
                        NativeUI.MarkDirty();
                        Plugin.Log.LogInfo($"[ACH] earners loaded for {achievementKey}: {list.Count} (total={CachedEarnersTotal})");
                        if (_earnersWantedKey != null && _earnersWantedKey != achievementKey)
                            FetchAchievementEarners(_earnersWantedKey);   // superseded — serve the newer click
                    }
                    catch (Exception ex)
                    {
                        Plugin.Log.LogWarning($"[ACH] earners parse error: {ex.Message}");
                    }
                }
            ));
        }


        /// <summary>Refresh the achievement list a few seconds after a match
        /// report lands, so the diff in FetchAchievements can announce anything
        /// the SERVER granted during submit_match.
        ///
        /// Without this the whole server-granted notification path is inert
        /// (Codex cold review, blocker 2): nothing else calls FetchAchievements
        /// on a match boundary — the only callers are the startup/consent path,
        /// opening the F5 Achievements tab, a manual refresh, and the
        /// client-side unlock callback. A player who never opens F5 would still
        /// never be told about silent_drill, clutch, lumberjack, the sweeps,
        /// the slayers or a rank threshold.
        ///
        /// Delayed, because the grants are written INSIDE the submit_match
        /// transaction: fetching in the response callback can race the commit
        /// on a slow write and read the pre-grant snapshot, which would then be
        /// cached as the new baseline and suppress the toast for good.</summary>
        public static void RefreshAchievementsAfterReport()
        {
            try
            {
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
                if (Plugin.Instance == null) return;
                Plugin.Instance.StartCoroutine(RefreshAchievementsAfterReportCo(sid));
            }
            catch { }
        }

        private static System.Collections.IEnumerator RefreshAchievementsAfterReportCo(string steamId)
        {
            yield return new WaitForSecondsRealtime(3f);
            FetchAchievements(steamId);
        }

        public static void FetchAchievements(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/achievements/{steamId}",
                (success, response) =>
                {
                    if (success)
                    {
                        try
                        {
                            var dict = new Dictionary<string, AchievementData>();
                            // Manual parse — array of {achievement_key, unlocked, unlocked_at}
                            var parts = response.Split(new[] { "\"achievement_key\"" }, StringSplitOptions.None);
                            for (int i = 1; i < parts.Length; i++)
                            {
                                string key = ExtractJsonString(parts[i], "");
                                if (string.IsNullOrEmpty(key)) continue;
                                bool unlocked = parts[i].Contains("\"unlocked\":true") || parts[i].Contains("\"unlocked\": true");
                                string unlockedAt = ExtractJsonString(parts[i], "unlocked_at");
                                dict[key] = new AchievementData
                                {
                                    achievement_key = key,
                                    unlocked = unlocked,
                                    unlocked_at = unlockedAt,
                                    global_pct = ExtractJsonFloat(parts[i], "global_pct"),
                                    gold = ExtractJsonInt(parts[i], "gold")
                                };
                            }
                            // Bug 201/209 family: SERVER-detected achievements
                            // (silent_drill, clutch, lumberjack, collector, the
                            // 5-0 sweeps, slayers, rank thresholds...) are
                            // granted inline during submit_match and never pass
                            // through UnlockAchievement, which is the ONLY site
                            // in the whole plugin that raises the unlock toast.
                            // They therefore landed completely silently, every
                            // time, since they shipped — Stan filed exactly
                            // that ("got the achievement, no popup, but it
                            // shows as completed"). Diffing the refreshed list
                            // against the previous cache is the only mechanism
                            // that can ever notify for them.
                            //
                            // PRIME SILENTLY on the first fetch of a session:
                            // with no prior cache every already-earned
                            // achievement reads as a fresh unlock, so a returning
                            // player would be buried under ~35 toasts at launch.
                            bool prime = CachedAchievements == null || CachedAchievements.Count == 0;
                            var freshlyUnlocked = new List<string>();
                            if (!prime)
                            {
                                foreach (var kv in dict)
                                {
                                    if (!kv.Value.unlocked) continue;
                                    if (CachedAchievements.TryGetValue(kv.Key, out var was) && was.unlocked) continue;
                                    freshlyUnlocked.Add(kv.Key);
                                }
                            }
                            CachedAchievements = dict;
                            NativeUI.MarkDirty();
                            Plugin.Log.LogInfo($"[ACH] Loaded {dict.Count} achievements"
                                + (prime ? " (primed, no toasts)" : ""));
                            foreach (var key in freshlyUnlocked)
                            {
                                try
                                {
                                    // One announcement per key per session, no
                                    // matter which site sees it first.
                                    if (!_announcedAchievements.Add(key)) continue;
                                    // Same display/translation path as the
                                    // client-side unlock toast so the two are
                                    // indistinguishable to the player.
                                    bool hasDef = AchievementDefs.TryGetValue(key, out var def);
                                    string dispName = hasDef ? I18n.Tr(def[0]) : key;
                                    string req = hasDef ? I18n.Tr(def[1]) : null;
                                    string toast = I18n.TrF("Achievement Unlocked: {0}!", dispName)
                                                 + (string.IsNullOrEmpty(req) ? "" : $"\n{req}");
                                    // Queued, not latest-wins: a match can grant
                                    // several server-side achievements at once
                                    // and ShowNotification would leave only the
                                    // last one visible.
                                    CompetitiveUI.QueueNotification(toast, new Color(1f, 0.85f, 0.3f), 8f);
                                    Plugin.Log.LogInfo($"[ACH] Unlocked (server-granted): {key}");
                                }
                                catch { }
                            }
                        }
                        catch (Exception ex)
                        {
                            Plugin.Log.LogWarning($"[ACH] Parse error: {ex.Message}");
                        }
                    }
                }
            ));
        }

        public static void UnlockAchievement(string steamId, string achievementKey, string matchId = null)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            string achSig = ComputeHmacHex($"achievement:{steamId}:{achievementKey}");
            string json = $"{{\"steam_id\":\"{Escape(steamId)}\",\"achievement_key\":\"{Escape(achievementKey)}\",\"hmac_signature\":\"{Escape(achSig)}\"";
            if (!string.IsNullOrEmpty(matchId))
                json += $",\"match_id\":\"{Escape(matchId)}\"";
            json += "}";

            Plugin.Instance.StartCoroutine(PostRequestWithRetry(
                $"{baseUrl}/api/v1/achievements/unlock",
                json,
                (success, response) =>
                {
                    if (success)
                    {
                        string status = ExtractJsonString(response, "status");
                        string name = ExtractJsonString(response, "name");
                        if (status == "unlocked" && !string.IsNullOrEmpty(name))
                        {
                            // Headline prefers the client def's display name so it can
                            // translate; the server-sent name is the fallback for
                            // achievements shipped server-first that this build's
                            // AchievementDefs doesn't know yet.
                            bool hasDef = AchievementDefs.TryGetValue(achievementKey, out var def);
                            string dispName = hasDef ? I18n.Tr(def[0]) : name;
                            string req = hasDef ? I18n.Tr(def[1]) : null;
                            string toast = I18n.TrF("Achievement Unlocked: {0}!", dispName) + (string.IsNullOrEmpty(req) ? "" : $"\n{req}");
                            // Claim the announcement (see _announcedAchievements):
                            // a slow unlock response can land AFTER the refresh
                            // already toasted this key as server-granted.
                            if (_announcedAchievements.Add(achievementKey))
                            {
                                CompetitiveUI.ShowNotification(toast, new Color(1f, 0.85f, 0.3f), 8f);
                                Plugin.Log.LogInfo($"[ACH] Unlocked: {achievementKey} ({name})");
                            }
                            else
                            {
                                Plugin.Log.LogInfo($"[ACH] Unlocked: {achievementKey} ({name}) — already announced this session");
                            }
                            // Mark it unlocked in the cache BEFORE the refresh
                            // below. The refresh diffs against this cache and
                            // toasts anything that flipped — without this the
                            // key we just announced flips false->true there too
                            // and every client-detected unlock toasts TWICE
                            // (Codex cold review, blocker 3). Updating the
                            // cache is also simply true: the server has
                            // confirmed the unlock.
                            try
                            {
                                if (CachedAchievements == null)
                                    CachedAchievements = new Dictionary<string, AchievementData>();
                                CachedAchievements.TryGetValue(achievementKey, out var prevAch);
                                CachedAchievements[achievementKey] = new AchievementData
                                {
                                    achievement_key = achievementKey,
                                    unlocked = true,
                                    unlocked_at = prevAch != null ? prevAch.unlocked_at : "",
                                    global_pct = prevAch != null ? prevAch.global_pct : 0f,
                                    gold = prevAch != null ? prevAch.gold : 0
                                };
                            }
                            catch { }
                        }
                        else
                        {
                            Plugin.Log.LogInfo($"[ACH] {achievementKey}: {status}");
                        }
                        // Refresh cached achievements
                        FetchAchievements(steamId);
                    }
                    else
                    {
                        Plugin.Log.LogWarning($"[ACH] Unlock failed for {achievementKey}: {response}");
                    }
                }
            ));
        }

        private static string Escape(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            return s.Replace("\\", "\\\\")
                    .Replace("\"", "\\\"")
                    .Replace("\n", "\\n")
                    .Replace("\r", "\\r");
        }

        // Full JSON string escaping — every control char < 0x20 gets \uXXXX'd.
        // Escape() above only covers \ " \n \r, which is fine for our own clean
        // strings but NOT for log files: a raw TAB, NUL, or console ESC byte in
        // a log embedded as a JSON literal makes the server's (strict) JSON
        // parser reject the whole request with 422 BEFORE validation runs —
        // that's why one player's log attach failed on every submit (#31) while
        // the no-log retry succeeded. Use this for any payload that carries
        // text we didn't author (logs, user-typed descriptions).
        private static string JsonEscapeFull(string s)
        {
            if (string.IsNullOrEmpty(s)) return "";
            var sb = new System.Text.StringBuilder(s.Length + 64);
            foreach (char c in s)
            {
                switch (c)
                {
                    case '\\': sb.Append("\\\\"); break;
                    case '"':  sb.Append("\\\""); break;
                    case '\n': sb.Append("\\n"); break;
                    case '\r': sb.Append("\\r"); break;
                    case '\t': sb.Append("\\t"); break;
                    default:
                        if (c < 0x20 || c == 0x7F) sb.Append($"\\u{(int)c:x4}");
                        else sb.Append(c);
                        break;
                }
            }
            return sb.ToString();
        }

        // ── Bug reports ──────────────────────────────────────────────────────
        // POST /api/v1/bug-reports. Server gzips + persists the log blob to
        // disk; we just pass plain text up. Caps log payload at ~3.5MB to
        // stay under the server's 4MB validator and FastAPI's body limit.
        public const int BUG_REPORT_LOG_CAP_CHARS = 3_500_000;
        public static void SubmitBugReport(string steamId, string displayName, string description,
                                           string reproSteps, string severity, string category,
                                           string logText, Action<bool, string> done)
        {
            if (string.IsNullOrEmpty(steamId))
            {
                done?.Invoke(false, "steam_id missing");
                return;
            }
            if (logText != null && logText.Length > BUG_REPORT_LOG_CAP_CHARS)
                logText = logText.Substring(logText.Length - BUG_REPORT_LOG_CAP_CHARS); // tail-most window
            // JsonEscapeFull everywhere — logs (and even typed descriptions) can
            // carry raw control bytes that strict JSON parsers reject (#31).
            var sb = new System.Text.StringBuilder();
            sb.Append("{");
            sb.Append($"\"steam_id\":\"{JsonEscapeFull(steamId)}\"");
            sb.Append($",\"display_name\":\"{JsonEscapeFull(displayName ?? "")}\"");
            sb.Append($",\"mod_version\":\"{JsonEscapeFull(Plugin.ModVersion)}\"");
            sb.Append($",\"game_version\":\"{JsonEscapeFull(UnityEngine.Application.version ?? "")}\"");
            sb.Append($",\"severity\":\"{JsonEscapeFull(severity ?? "medium")}\"");
            sb.Append($",\"category\":\"{JsonEscapeFull(category ?? "other")}\"");
            sb.Append($",\"description\":\"{JsonEscapeFull(description ?? "")}\"");
            if (!string.IsNullOrEmpty(reproSteps))
                sb.Append($",\"repro_steps\":\"{JsonEscapeFull(reproSteps)}\"");
            if (!string.IsNullOrEmpty(logText))
                sb.Append($",\"log_text\":\"{JsonEscapeFull(logText)}\"");
            sb.Append("}");
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/bug-reports", sb.ToString(),
                (ok, response) =>
                {
                    if (ok) Plugin.Log.LogInfo($"[BUG-REPORT] submitted ok: {response}");
                    else Plugin.Log.LogWarning($"[BUG-REPORT] submit failed: {response}");
                    done?.Invoke(ok, response);
                }
            ));
        }

        // Reads the tail of a log file (BepInEx LogOutput.log or Unity output_log.txt)
        // with sane caps so we don't blow out memory on a multi-MB log.
        public static string ReadLogTail(string path, int maxChars = BUG_REPORT_LOG_CAP_CHARS)
        {
            try
            {
                if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path)) return "";
                // FileShare.ReadWrite — BepInEx + Unity keep these handles open.
                using (var fs = new System.IO.FileStream(path, System.IO.FileMode.Open,
                                                        System.IO.FileAccess.Read,
                                                        System.IO.FileShare.ReadWrite))
                using (var sr = new System.IO.StreamReader(fs))
                {
                    string all = sr.ReadToEnd();
                    if (all.Length <= maxChars) return all;
                    return all.Substring(all.Length - maxChars);
                }
            }
            catch (Exception ex)
            {
                return $"[log read error: {ex.Message}]";
            }
        }


        // ── Tournaments ──────────────────────────────────────────────────────
        //
        // Raw-JSON caching + field-level extraction for the Tournaments tab. We
        // avoid JsonUtility-with-nested-arrays per the codebase convention (see
        // CLAUDE.md learnings 25). Top-level flat fields are parsed into
        // TournamentSnapshot; signups/matches/time_slots stay as raw JSON and
        // are sliced into per-row strings that the UI re-parses lazily.

        public static string CachedTournamentJson;
        public static TournamentSnapshot CachedTournament;
        private static float _tournamentRefreshAt;

        [Serializable]
        public class TournamentSnapshot
        {
            public string tournament_id;
            public string status;            // voting | locked | running | completed | null
            public string kind;              // sync | async
            public string default_start_ts;
            public string scheduled_start_ts;
            public string lock_at;
            public string started_at;
            public string ended_at;
            public int min_players;
            public int max_players;
            // Prizes scale with confirmed player count (July 17 round 2):
            // server-computed, live during voting, locked snapshot after.
            public int prize_players;
            public int prize_gold_1, prize_gold_2, prize_gold_3;
            public int prize_xp_1, prize_xp_2, prize_xp_3;
            public string my_signup_id;
            public bool my_ready;
            public float my_penalty_pct;
            public bool my_discord_linked;
            public int force_vote_count;
            public string photon_region;         // tournament's canonical Photon region (null until lock)
            public string[] my_votes;            // ISO datetimes
            public string[] time_slot_options;   // ISO datetimes
            public TimeVoteTally[] time_slot_tallies;
            public TournamentSignupRow[] signups;
            public TournamentMatchRow[] matches;
        }

        [Serializable]
        public class TimeVoteTally
        {
            public string slot_ts;
            public int votes;
        }

        [Serializable]
        public class TournamentSignupRow
        {
            public string signup_id;
            public string steam_id;
            public string display_name;
            public bool is_speculative;
            public int seed;        // 0 until lock
            public float penalty_at_signup;
            public bool ready;
            public bool forfeited;
            public int placed_rank; // 0 if not placed
            public string progress_label;  // "WB R2" / "LB R3" / "eliminated WB R2" / "CHAMPION"
            // Aug 17 bracket-clarity batch: locked elo (live rating pre-lock),
            // 0 = never rated; resolved title (dynamic skus pre-resolved
            // server-side, #111) for the signups list.
            public int rating;
            public string title;
            public string title_color;
        }

        [Serializable]
        public class TournamentMatchRow
        {
            public string match_id;
            public int round;
            public string bracket_side;   // W | TP | L | GF | GF_RESET
            public int slot_idx;
            public string p1_signup_id;
            public string p2_signup_id;
            public string p1_display_name;
            public string p2_display_name;
            public bool is_bye;
            public string status;         // pending | ready | forfeit | completed | bye_auto
            public string series_id;
            public string winner_signup_id;
            public int p1_series_wins;
            public int p2_series_wins;
            public string deadline_at;    // async 7-day match deadline (null for sync)
            // UUIDs of the matches whose winners (or losers, per
            // prereq_roles) feed into this match's p1/p2 slots. Empty for
            // round-1 WB matches. Used by the visual bracket renderer to
            // draw connector lines between cells.
            public string[] prereq_match_ids;
            // Server-issued Photon room name. Set when the match
            // transitions to 'ready'. Replaces client-side derivation
            // ("sct-" + match_id[:12]) so both clients always converge
            // on the same room. Falls back to null for older matches
            // that pre-date the column.
            public string photon_room_name;
            // PER-MATCH Photon region, resolved server-side at bracket
            // activation from both players' ping/region history. Null on
            // matches created before the column existed, and on every async
            // match (async coordinates its own lobby and pins nothing) — the
            // consumer falls back to the tournament-wide value. A bracket
            // re-pairs every round, so one region provably cannot serve every
            // pair: an EU/EU final under a us-locked tournament is a permanent
            // ~110ms tax on a match whose right answer is obvious.
            public string photon_region;
        }

        // Tracks which kind (sync | async) the client is currently viewing. Set
        // by the UI's sub-tab; defaults to sync so existing callers keep the
        // Phase 1 behavior.
        public static string TournamentKind = "sync";

        // Monotonic per-request generation for /tournaments/current: a response
        // is applied only if no NEWER request has been issued since (r2 review:
        // the kind fence alone still let two SAME-kind responses land out of
        // order, oldest-wins). Single-writer (main thread), so a plain int.
        private static int _tournamentFetchGen;
        public static void FetchTournamentCurrent(string steamId, bool force = false)
        {
            if (!force && Time.unscaledTime < _tournamentRefreshAt) return;
            _tournamentRefreshAt = Time.unscaledTime + 5f;   // throttle
            int myGen = ++_tournamentFetchGen;
            string kindParam = string.IsNullOrEmpty(TournamentKind) ? "sync" : TournamentKind;
            string q = string.IsNullOrEmpty(steamId) || steamId == "unknown"
                ? $"?kind={kindParam}"
                : $"?steam_id={Escape(steamId)}&kind={kindParam}";
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/tournaments/current{q}",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    // Generation fence first (r2 review): drop any response a
                    // NEWER request has superseded — covers same-kind
                    // reordering, which the kind fence below cannot see.
                    if (myGen != _tournamentFetchGen) return;
                    // Kind fence (Aug 30 review LOW): a slower response for the
                    // PREVIOUSLY selected kind must not overwrite the cache after
                    // a sub-tab switch (manual or tab-entry auto-select) — the
                    // stale snapshot would hide the My Match panel until the next
                    // poll. Same identity-fence shape as SelectedPlayerAchievements.
                    // Kept as belt over the generation fence for any future
                    // TournamentKind write site that forgets to refetch.
                    if (!string.Equals(kindParam,
                            string.IsNullOrEmpty(TournamentKind) ? "sync" : TournamentKind,
                            StringComparison.Ordinal)) return;
                    try
                    {
                        CachedTournamentJson = response;
                        CachedTournament = ParseTournament(response);
                        NativeUI.MarkDirty();
                    }
                    catch (Exception e)
                    {
                        Plugin.Log.LogWarning($"[TOURNAMENT] parse failed: {e.Message}");
                    }
                }
            ));
        }

        private static TournamentSnapshot ParseTournament(string json)
        {
            var t = new TournamentSnapshot();
            t.tournament_id = ExtractString(json, "tournament_id");
            t.status = ExtractString(json, "status");
            t.kind = ExtractString(json, "kind");
            t.default_start_ts = ExtractString(json, "default_start_ts");
            t.scheduled_start_ts = ExtractString(json, "scheduled_start_ts");
            t.lock_at = ExtractString(json, "lock_at");
            t.started_at = ExtractString(json, "started_at");
            t.ended_at = ExtractString(json, "ended_at");
            t.min_players = ExtractInt(json, "min_players", 8);
            t.max_players = ExtractInt(json, "max_players", 16);
            t.prize_players = ExtractInt(json, "prize_players", 0);
            t.prize_gold_1 = ExtractInt(json, "prize_gold_1", 0);
            t.prize_gold_2 = ExtractInt(json, "prize_gold_2", 0);
            t.prize_gold_3 = ExtractInt(json, "prize_gold_3", 0);
            t.prize_xp_1 = ExtractInt(json, "prize_xp_1", 0);
            t.prize_xp_2 = ExtractInt(json, "prize_xp_2", 0);
            t.prize_xp_3 = ExtractInt(json, "prize_xp_3", 0);
            t.my_signup_id = ExtractString(json, "my_signup_id");
            t.my_ready = ExtractBool(json, "my_ready");
            t.my_penalty_pct = ExtractFloat(json, "my_penalty_pct");
            t.my_discord_linked = ExtractBool(json, "my_discord_linked");
            t.force_vote_count = ExtractInt(json, "force_vote_count", 0);
            t.photon_region = ExtractString(json, "photon_region");
            t.my_votes = ExtractStringArray(json, "my_votes");
            t.time_slot_options = ExtractStringArray(json, "time_slot_options");
            t.time_slot_tallies = ExtractObjectArray(json, "time_slot_tallies",
                raw => new TimeVoteTally
                {
                    slot_ts = ExtractString(raw, "slot_ts"),
                    votes = ExtractInt(raw, "votes", 0),
                });
            t.signups = ExtractObjectArray(json, "signups", raw => new TournamentSignupRow
            {
                signup_id = ExtractString(raw, "signup_id"),
                steam_id = ExtractString(raw, "steam_id"),
                display_name = ExtractString(raw, "display_name"),
                is_speculative = ExtractBool(raw, "is_speculative"),
                seed = ExtractInt(raw, "seed", 0),
                penalty_at_signup = ExtractFloat(raw, "penalty_at_signup"),
                ready = ExtractBool(raw, "ready"),
                forfeited = ExtractBool(raw, "forfeited"),
                placed_rank = ExtractInt(raw, "placed_rank", 0),
                progress_label = ExtractString(raw, "progress_label"),
                rating = ExtractInt(raw, "rating", 0),
                title = ExtractString(raw, "title"),
                title_color = ExtractString(raw, "title_color"),
            });
            t.matches = ExtractObjectArray(json, "matches", raw => new TournamentMatchRow
            {
                match_id = ExtractString(raw, "match_id"),
                round = ExtractInt(raw, "round", 0),
                bracket_side = ExtractString(raw, "bracket_side"),
                slot_idx = ExtractInt(raw, "slot_idx", 0),
                p1_signup_id = ExtractString(raw, "p1_signup_id"),
                p2_signup_id = ExtractString(raw, "p2_signup_id"),
                p1_display_name = ExtractString(raw, "p1_display_name"),
                p2_display_name = ExtractString(raw, "p2_display_name"),
                is_bye = ExtractBool(raw, "is_bye"),
                status = ExtractString(raw, "status"),
                series_id = ExtractString(raw, "series_id"),
                winner_signup_id = ExtractString(raw, "winner_signup_id"),
                p1_series_wins = ExtractInt(raw, "p1_series_wins", 0),
                p2_series_wins = ExtractInt(raw, "p2_series_wins", 0),
                deadline_at = ExtractString(raw, "deadline_at"),
                prereq_match_ids = ExtractStringArray(raw, "prereq_match_ids"),
                photon_room_name = ExtractString(raw, "photon_room_name"),
                photon_region = ExtractString(raw, "photon_region"),
            });
            return t;
        }

        // Small, forgiving JSON extractors. NOT a full parser — they handle the
        // shapes we control (API response) and ignore the rest.

        /// <summary>Index of the COLON after a genuine `"key":` occurrence, or
        /// -1. String-aware (#156 one level down — Aug 17 review F3/F8): a
        /// plain IndexOf finds the key text inside a user-authored STRING
        /// VALUE (display names are adversarial), which let a player named
        /// "placed_rank" forge their row's later numeric fields. A string
        /// token is a KEY exactly when the next non-whitespace character
        /// after its closing quote is ':' — a string VALUE is always followed
        /// by ',' '}' or ']' in valid JSON, never ':'.</summary>
        private static int FindKeyColon(string json, string key)
        {
            if (string.IsNullOrEmpty(json) || string.IsNullOrEmpty(key)) return -1;
            bool inStr = false, esc = false;
            int tokStart = -1;
            for (int i = 0; i < json.Length; i++)
            {
                char ch = json[i];
                if (inStr)
                {
                    if (esc) { esc = false; continue; }
                    if (ch == '\\') { esc = true; continue; }
                    if (ch != '"') continue;
                    inStr = false;
                    int len = i - tokStart;
                    // Escaped content never CompareOrdinal-matches our plain
                    // ASCII keys — a name crafted to escape into a key shape
                    // therefore fails the compare rather than forging.
                    if (len == key.Length && string.CompareOrdinal(json, tokStart, key, 0, len) == 0)
                    {
                        int p = i + 1;
                        while (p < json.Length && (json[p] == ' ' || json[p] == '\t' || json[p] == '\r' || json[p] == '\n')) p++;
                        if (p < json.Length && json[p] == ':') return p;
                    }
                    continue;
                }
                if (ch == '"') { inStr = true; tokStart = i + 1; }
            }
            return -1;
        }

        private static string ExtractString(string json, string key)
        {
            if (string.IsNullOrEmpty(json)) return null;
            int c = FindKeyColon(json, key);
            if (c < 0) return null;
            int p = c + 1;
            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
            if (p >= json.Length) return null;
            if (json[p] == 'n' && json.Length >= p + 4 && json.Substring(p, 4) == "null") return null;
            if (json[p] != '"') return null;
            int start = p + 1;
            var sb = new System.Text.StringBuilder();
            for (int k = start; k < json.Length; k++)
            {
                char ch = json[k];
                if (ch == '\\' && k + 1 < json.Length) { sb.Append(json[k + 1]); k++; continue; }
                if (ch == '"') break;
                sb.Append(ch);
            }
            return sb.ToString();
        }

        private static int ExtractInt(string json, string key, int def)
        {
            if (string.IsNullOrEmpty(json)) return def;
            int c = FindKeyColon(json, key);
            if (c < 0) return def;
            int p = c + 1;
            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
            if (p >= json.Length) return def;
            int e = p;
            while (e < json.Length && (char.IsDigit(json[e]) || json[e] == '-')) e++;
            if (e == p) return def;
            int v; return int.TryParse(json.Substring(p, e - p), out v) ? v : def;
        }

        private static float ExtractFloat(string json, string key)
        {
            if (string.IsNullOrEmpty(json)) return 0f;
            int c = FindKeyColon(json, key);
            if (c < 0) return 0f;
            int p = c + 1;
            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
            if (p >= json.Length) return 0f;
            int e = p;
            while (e < json.Length && (char.IsDigit(json[e]) || json[e] == '-' || json[e] == '.' || json[e] == 'e' || json[e] == 'E' || json[e] == '+')) e++;
            if (e == p) return 0f;
            float v; return float.TryParse(json.Substring(p, e - p), System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out v) ? v : 0f;
        }

        private static bool ExtractBool(string json, string key)
        {
            if (string.IsNullOrEmpty(json)) return false;
            int c = FindKeyColon(json, key);
            if (c < 0) return false;
            int p = c + 1;
            while (p < json.Length && (json[p] == ' ' || json[p] == '\t')) p++;
            return p + 4 <= json.Length && json.Substring(p, 4) == "true";
        }

        private static string[] ExtractStringArray(string json, string key)
        {
            if (string.IsNullOrEmpty(json)) return Array.Empty<string>();
            int c0 = FindKeyColon(json, key);
            if (c0 < 0) return Array.Empty<string>();
            int b = json.IndexOf('[', c0);
            if (b < 0) return Array.Empty<string>();
            int e = json.IndexOf(']', b);
            if (e < 0) return Array.Empty<string>();
            string inner = json.Substring(b + 1, e - b - 1);
            var list = new List<string>();
            int p = 0;
            while (p < inner.Length)
            {
                int q = inner.IndexOf('"', p);
                if (q < 0) break;
                int q2 = inner.IndexOf('"', q + 1);
                if (q2 < 0) break;
                list.Add(inner.Substring(q + 1, q2 - q - 1));
                p = q2 + 1;
            }
            return list.ToArray();
        }

        private static T[] ExtractObjectArray<T>(string json, string key, Func<string, T> parse)
        {
            if (string.IsNullOrEmpty(json)) return Array.Empty<T>();
            // Key anchor via FindKeyColon (review F8): a signup literally named
            // "time_slot_tallies" used to redirect this to the wrong array.
            int c0 = FindKeyColon(json, key);
            if (c0 < 0) return Array.Empty<T>();
            int b = json.IndexOf('[', c0);
            if (b < 0) return Array.Empty<T>();
            // Scan forward, tracking brace depth, collect { ... } segments at
            // depth 1. STRING-AWARE (#156): display names are user-authored and
            // may contain braces/brackets — a naive depth counter here silently
            // corrupted the whole array for every client whenever one signup
            // name carried a '{' or '}'.
            var list = new List<T>();
            int depth = 0;
            int objStart = -1;
            bool inStr = false, esc = false;
            for (int k = b; k < json.Length; k++)
            {
                char ch = json[k];
                if (inStr)
                {
                    if (esc) { esc = false; continue; }
                    if (ch == '\\') { esc = true; continue; }
                    if (ch == '"') inStr = false;
                    continue;
                }
                if (ch == '"') { inStr = true; continue; }
                if (ch == '[') { depth++; continue; }
                if (ch == ']') { depth--; if (depth == 0) break; continue; }
                if (ch == '{')
                {
                    if (objStart < 0) objStart = k;
                    depth++;
                    continue;
                }
                if (ch == '}')
                {
                    depth--;
                    if (depth == 1 && objStart >= 0)
                    {
                        list.Add(parse(json.Substring(objStart, k - objStart + 1)));
                        objStart = -1;
                    }
                }
            }
            return list.ToArray();
        }

        /// <summary>True for a string that could be a Photon region code:
        /// lowercase alphanumeric, 2-8 chars. Deliberately NOT an allowlist of
        /// today's 17 codes — a new Photon datacentre must not be silently
        /// dropped — but tight enough that the failure this guards against
        /// (see BestKnownPhotonRegion) cannot get through.</summary>
        private static bool IsPlausibleRegionCode(string s)
        {
            if (string.IsNullOrEmpty(s) || s.Length < 2 || s.Length > 8) return false;
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))) return false;
            }
            return true;
        }

        /// <summary>The best Photon region code we can name for THIS client
        /// right now, or "" when there is genuinely nothing to report.
        ///
        /// PhotonNetwork.CloudRegion returns NetworkingClient.CloudRegion, which
        /// is populated only while CONNECTED — so a player signing up for a
        /// tournament from the main menu reports "". That is not an edge case:
        /// 24 of the 25 signups ever recorded in production carry no region, and
        /// because the lock picks the MODE of the non-empty values, the single
        /// legacy outlier decided an entire tournament's region on its own.
        ///
        /// PUN caches its own best-region verdict across launches in PlayerPrefs
        /// (PhotonNetwork.BestRegionSummaryInPreferences, key
        /// "PUNCloudBestRegion"), and that survives disconnection — which is
        /// exactly the question a menu-time signup needs answered.
        ///
        /// PARSING IS NOT "take field 0". RegionHandler.SummaryToCache emits two
        /// different shapes:
        ///     "ussc;36;asia,au,cae,eu,..."  a best region is known  -> field 0
        ///     "asia,au,cae,eu,..."          none known  -> NO region at all
        /// The second is the bare available-region list, which it returns
        /// whenever BestRegion is null or its ping exceeded
        /// RegionPinger.MaxMillisecondsPerPing. Splitting THAT on ';' yields the
        /// whole comma-separated list as "field 0", and sending it would put a
        /// 60-character string into region_at_signup where the server would
        /// count it as a legitimate vote. So the three-field form is required
        /// (the middle field must parse as the ping) and the code is validated
        /// before it is used.
        ///
        /// SCOPE: used by the tournament signup only, and NOT because the other
        /// CloudRegion reads in this file are safe from the same emptiness —
        /// they are the queue joins, which also run from the menu and also send
        /// "". The difference is what the server does with it: every queue-lock
        /// path coerces the room's region with `or "us"`, so a queue room is
        /// never issued without one, while the tournament lock takes the MODE of
        /// the reported values and a population of one legacy row wins it
        /// outright. Feeding this to the queue joins would improve matchmaking
        /// region accuracy and is worth doing deliberately, with its own review
        /// of what the server infers from that field — it is not a drive-by.</summary>
        public static string BestKnownPhotonRegion()
        {
            try
            {
                string live = (PhotonNetwork.CloudRegion ?? "").Replace("/*", "").Trim().ToLowerInvariant();
                if (IsPlausibleRegionCode(live)) return live;
            }
            catch { }
            try
            {
                string summary = PhotonNetwork.BestRegionSummaryInPreferences ?? "";
                string[] parts = summary.Split(';');
                if (parts.Length >= 3)
                {
                    int ping;
                    if (int.TryParse(parts[1], System.Globalization.NumberStyles.Integer,
                                     System.Globalization.CultureInfo.InvariantCulture, out ping))
                    {
                        string code = parts[0].Trim().ToLowerInvariant();
                        if (IsPlausibleRegionCode(code)) return code;
                    }
                }
            }
            catch { }
            return "";
        }

        public static void TournamentSignup(string tournamentId, string steamId, string displayName, string[] slotIsos = null)
        {
            // Include the client's best-known Photon region so the server can pick
            // the tournament's canonical region at lock time (mode of all signups'
            // regions). Auto-connect then pins every SYNC match to that region.
            //
            // Not a bare CloudRegion read: signup happens at the main menu, where
            // CloudRegion is empty unless the client happens to be connected.
            // See BestKnownPhotonRegion for why that emptiness is the root cause
            // of the "[RU] region" bug and how the cached verdict is parsed.
            string region = BestKnownPhotonRegion();
            // Item 3: sync signups carry the player's time votes (>= 1 slot
            // required server-side; the UI enforces it before calling).
            var sb = new System.Text.StringBuilder();
            sb.Append("{\"steam_id\":\"").Append(Escape(steamId))
              .Append("\",\"display_name\":\"").Append(Escape(displayName ?? steamId))
              .Append("\",\"region\":\"").Append(Escape(region))
              .Append("\",\"slot_ts\":[");
            if (slotIsos != null)
                for (int i = 0; i < slotIsos.Length; i++)
                {
                    if (i > 0) sb.Append(',');
                    sb.Append('"').Append(Escape(slotIsos[i])).Append('"');
                }
            sb.Append("]}");
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/tournaments/{tournamentId}/signup", sb.ToString(),
                (s, r) =>
                {
                    if (s) { FetchTournamentCurrent(steamId, force: true); CompetitiveUI.ShowNotification("Signed up for tournament", new Color(0.4f, 1f, 0.5f)); }
                    else { CompetitiveUI.ShowNotification(ExtractErrorDetail(r) ?? "Signup failed", new Color(1f, 0.4f, 0.4f)); }
                }));
        }

        public static void TournamentUnsignup(string tournamentId, string steamId)
        {
            string body = $"{{\"steam_id\":\"{Escape(steamId)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/tournaments/{tournamentId}/unsignup", body,
                (s, r) =>
                {
                    if (s) { FetchTournamentCurrent(steamId, force: true); CompetitiveUI.ShowNotification("Left tournament signup", new Color(0.9f, 0.9f, 0.4f)); }
                    else { CompetitiveUI.ShowNotification(ExtractErrorDetail(r) ?? "Failed", new Color(1f, 0.4f, 0.4f)); }
                }));
        }

        public static void TournamentTimeVote(string tournamentId, string steamId, string[] slotIsos)
        {
            var sb = new System.Text.StringBuilder();
            sb.Append("{\"steam_id\":\"").Append(Escape(steamId)).Append("\",\"slot_ts\":[");
            for (int i = 0; i < slotIsos.Length; i++)
            {
                if (i > 0) sb.Append(',');
                sb.Append('"').Append(Escape(slotIsos[i])).Append('"');
            }
            sb.Append("]}");
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/tournaments/{tournamentId}/time-vote", sb.ToString(),
                (s, r) => { if (s) FetchTournamentCurrent(steamId, force: true); }));
        }

