        // Skip the between-rounds break (July 17 round 2): the match starts
        // immediately once BOTH players have pressed Play Now.
        public static void TournamentPlayNow(string tournamentId, string matchId, string steamId)
        {
            string body = $"{{\"steam_id\":\"{Escape(steamId)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/tournaments/{tournamentId}/matches/{matchId}/play-now", body,
                (s, r) =>
                {
                    if (s)
                    {
                        CompetitiveUI.ShowNotification("Play Now sent - starts when your opponent presses it too", new Color(0.5f, 0.9f, 1f));
                        // Refresh both surfaces so the button state + countdown update.
                        _myActiveMatchesRefreshAt = 0f;
                        FetchMyActiveTournamentMatches(steamId);
                        FetchTournamentCurrent(steamId, force: true);
                    }
                    else CompetitiveUI.ShowNotification(ExtractErrorDetail(r) ?? "Play Now failed", new Color(1f, 0.5f, 0.4f));
                }));
        }

        // Match-scoped self-forfeit (Aug 22 lifecycle pass). The server
        // records EVIDENCE only — its overdue sweep resolves the match — so
        // the success copy says RECORDED, never resolved/forfeited (v1.39.1
        // r2 find 6: a completed game result reported meanwhile still wins,
        // and claiming a final technical loss here would be false).
        public static void TournamentForfeit(string tournamentId, string matchId, string steamId)
        {
            string body = $"{{\"steam_id\":\"{Escape(steamId)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/tournaments/{tournamentId}/matches/{matchId}/forfeit", body,
                (s, r) =>
                {
                    string result = s ? ExtractString(r ?? "", "result") : null;
                    // RAW literals — ShowNotification translates at its own
                    // chokepoint, and pre-wrapping here would translate
                    // twice (Phase B r1 find 8).
                    if (s && result == "forfeit_recorded")
                        CompetitiveUI.ShowNotification("Forfeit recorded - the match will be resolved shortly.", new Color(1f, 0.75f, 0.4f));
                    else
                    {
                        // ALWAYS the catalogued generic (b4 find 1): the
                        // server's 409 detail is English-only and would
                        // render raw on ES/RU/UK/SV clients. The detail
                        // still goes to the log for diagnostics.
                        Plugin.Log.LogInfo($"[TOURNAMENT] forfeit refused: {ExtractErrorDetail(r) ?? (r ?? "(no body)")}");
                        CompetitiveUI.ShowNotification("Forfeit failed", new Color(1f, 0.5f, 0.4f));
                    }
                    // Refresh so the panel reflects the recorded concession /
                    // the real state behind a refusal.
                    FetchTournamentCurrent(steamId, force: true);
                }));
        }

        private static string ExtractErrorDetail(string response)
        {
            if (string.IsNullOrEmpty(response)) return null;
            try
            {
                // FastAPI returns {"detail":"..."} on HTTPException
                return ExtractString(response, "detail");
            }
            catch { return null; }
        }


        // ── Tournament history (per-player trophy counts + recent tournaments) ─
        //
        // Populated lazily: FetchPlayerTournaments hits /api/v1/tournaments/players/{steam}/tournaments
        // and stores the parsed PlayerTournamentHistory keyed by steam_id. Used by the
        // Leaderboard click-a-player detail (shows trophy summary for the viewed player)
        // and the Tournaments tab (shows the local player's own history line).

        [Serializable]
        public class PlayerTournamentHistory
        {
            public string steam_id;
            public int winner_count;
            public int runner_up_count;
            public int third_place_count;
            public int participant_count;
            public PlayerTournamentEntry[] recent;
        }

        [Serializable]
        public class PlayerTournamentEntry
        {
            public string tournament_id;
            public string ended_at;
            public int placed_rank;
            public string kind;
            public int signup_count;
            public string winner_display_name;
            // Site-wide Recent Tournaments detail. GET /tournaments/history has
            // returned all four of these since the endpoint was written; only
            // the winner was ever parsed, so the panel showed one name for a
            // bracket that also decided a 2nd and a 3rd.
            //
            // This type is SHARED with GET /players/{id}/tournaments, whose
            // `recent` rows carry only the six fields above — so on that path
            // these stay null / 0 by design. Any renderer must treat them as
            // optional rather than assume the /history shape.
            public string runner_up_display_name;
            public string third_place_display_name;
            public string format;      // "single_elim_bo3" | "double_elim_bo3" | ...
            public string prize_tier;
        }

        public static readonly Dictionary<string, PlayerTournamentHistory> CachedPlayerTournaments
            = new Dictionary<string, PlayerTournamentHistory>();

        public static void FetchPlayerTournaments(string steamId, Action onDone = null)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/tournaments/players/{Escape(steamId)}/tournaments?limit=8",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try
                    {
                        var h = new PlayerTournamentHistory
                        {
                            steam_id = ExtractString(response, "steam_id") ?? steamId,
                            winner_count = ExtractInt(response, "winner_count", 0),
                            runner_up_count = ExtractInt(response, "runner_up_count", 0),
                            third_place_count = ExtractInt(response, "third_place_count", 0),
                            participant_count = ExtractInt(response, "participant_count", 0),
                            recent = ExtractObjectArray(response, "recent", raw => new PlayerTournamentEntry
                            {
                                tournament_id = ExtractString(raw, "tournament_id"),
                                ended_at = ExtractString(raw, "ended_at"),
                                placed_rank = ExtractInt(raw, "placed_rank", 0),
                                kind = ExtractString(raw, "kind"),
                                signup_count = ExtractInt(raw, "signup_count", 0),
                                winner_display_name = ExtractString(raw, "winner_display_name"),
                                // Absent on this endpoint today (see the type's
                                // comment). Parsed anyway so that if the server
                                // ever widens `recent` to the /history shape the
                                // client picks it up with no release — an absent
                                // key extracts as null, never an exception.
                                runner_up_display_name = ExtractString(raw, "runner_up_display_name"),
                                third_place_display_name = ExtractString(raw, "third_place_display_name"),
                                format = ExtractString(raw, "format"),
                                prize_tier = ExtractString(raw, "prize_tier"),
                            }),
                        };
                        CachedPlayerTournaments[steamId] = h;
                        NativeUI.MarkDirty();
                        onDone?.Invoke();
                    }
                    catch (Exception e) { Plugin.Log.LogWarning($"[TOURNAMENT-HIST] parse: {e.Message}"); }
                }
            ));
        }

        // "Am I in a tournament match right now?" — polled every 20s regardless
        // of tab so the TOURNAMENT GAME indicator at the top of the competitive
        // page can light up when in a room with a tournament opponent. Spans
        // both sync and async so a player in both doesn't miss either.
        [Serializable]
        public class ActiveTournamentMatch
        {
            public string tournament_id;
            public string kind;
            public string match_id;
            public string status;
            public string bracket_side;
            public int round;
            public string opponent_steam_id;
            public string opponent_display_name;
            // Server-issued Photon room + region. Used by the
            // tournament dispatch loop to fire SetPendingRoom from a
            // plugin-level coroutine, independent of which UI tab is
            // open — without it, auto-connect only ran when the user
            // happened to be on the Tournament tab.
            public string photon_room_name;
            public string photon_region;
            public bool my_ready;
            public bool opp_ready;
            // Seconds until the sync no-show forfeit fires (negative = past the
            // deadline; heartbeating players are spared). Drives the big
            // banner countdown (item 3). Snapshot at fetch time — pair with
            // fetched_at_realtime for a live countdown between polls.
            public int ready_seconds_left;
            // Break state (July 17 round 2): sync rounds 2+ sit in
            // status='scheduled' — countdown to auto-ready, plus who has
            // pressed Play Now (both = the break skips).
            public int scheduled_seconds_left;
            public bool my_early_ok;
            public bool opp_early_ok;
            public float fetched_at_realtime;
        }
        public static List<ActiveTournamentMatch> CachedMyActiveTournamentMatches = new List<ActiveTournamentMatch>();
        private static float _myActiveMatchesRefreshAt;
        public static void FetchMyActiveTournamentMatches(string steamId)
        {
            if (string.IsNullOrEmpty(steamId) || steamId == "unknown") return;
            if (Time.unscaledTime < _myActiveMatchesRefreshAt) return;
            _myActiveMatchesRefreshAt = Time.unscaledTime + 20f;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/tournaments/my-active-matches?steam_id={Escape(steamId)}",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try
                    {
                        var list = new List<ActiveTournamentMatch>();
                        foreach (var raw in ExtractObjectArray(response, "matches", r => r))
                        {
                            list.Add(new ActiveTournamentMatch
                            {
                                tournament_id = ExtractString(raw, "tournament_id"),
                                kind = ExtractString(raw, "kind"),
                                match_id = ExtractString(raw, "match_id"),
                                status = ExtractString(raw, "status"),
                                bracket_side = ExtractString(raw, "bracket_side"),
                                round = ExtractInt(raw, "round", 0),
                                opponent_steam_id = ExtractString(raw, "opponent_steam_id"),
                                opponent_display_name = ExtractString(raw, "opponent_display_name"),
                                photon_room_name = ExtractString(raw, "photon_room_name"),
                                photon_region = ExtractString(raw, "photon_region"),
                                my_ready = ExtractBool(raw, "my_ready"),
                                opp_ready = ExtractBool(raw, "opp_ready"),
                                ready_seconds_left = ExtractInt(raw, "ready_seconds_left", -1),
                                scheduled_seconds_left = ExtractInt(raw, "scheduled_seconds_left", -1),
                                my_early_ok = ExtractBool(raw, "my_early_ok"),
                                opp_early_ok = ExtractBool(raw, "opp_early_ok"),
                                fetched_at_realtime = Time.realtimeSinceStartup,
                            });
                        }
                        CachedMyActiveTournamentMatches = list;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception e) { Plugin.Log.LogWarning($"[TOURNAMENT-ACTIVE] parse: {e.Message}"); }
                }
            ));
        }

        /// <summary>The region a server-issued tournament room (sct-) must be
        /// joined in, or "" when the SERVER has not told us one yet.
        ///
        /// Every rung is a value the server sent. There is deliberately no rung
        /// that derives a region locally, because two clients deriving locally
        /// derive DIFFERENTLY and each creates its own room — learning #49, and
        /// the double no-show forfeit that follows costs both players their run.
        /// "" is therefore a real answer meaning "refuse and re-poll", not a
        /// signal to fall through to whatever the region dropdown last held.
        ///
        /// Rungs:
        ///   1. the per-match region on the active-match row for THIS room
        ///      (refreshed by the 20s tournament heartbeat, so re-polling is
        ///      what eventually fills it in);
        ///   2. <paramref name="allowTournamentLevel"/> — the tournament-wide
        ///      region, and ONLY once the room has been matched to an active
        ///      match whose tournament_id equals the cached snapshot's. Without
        ///      that equality the snapshot could belong to a different
        ///      tournament (or the other kind — CachedTournament follows the
        ///      TournamentKind sub-tab), and using it would be a guess wearing
        ///      a server value's clothes.</summary>
        public static string TournamentRegionForRoom(string roomName, bool allowTournamentLevel)
        {
            if (string.IsNullOrEmpty(roomName)) return "";
            string tournamentId = null;
            try
            {
                var list = CachedMyActiveTournamentMatches;
                if (list != null)
                {
                    foreach (var m in list)
                    {
                        if (m == null || !string.Equals(m.photon_room_name, roomName, StringComparison.Ordinal))
                            continue;
                        tournamentId = m.tournament_id;
                        string per = (m.photon_region ?? "").Trim();
                        if (per.Length > 0) return per;
                        break;
                    }
                }
            }
            catch { }
            if (!allowTournamentLevel || string.IsNullOrEmpty(tournamentId)) return "";
            try
            {
                var t = CachedTournament;
                if (t != null
                    && !string.IsNullOrEmpty(t.photon_region)
                    && string.Equals(t.tournament_id, tournamentId, StringComparison.Ordinal))
                    return t.photon_region.Trim();
            }
            catch { }
            return "";
        }

        /// <summary>Ask the server again for the region of a tournament room we
        /// are refusing to join without one. Both fetches are internally
        /// throttled (20s / 5s), so calling this on a timer is safe.</summary>
        public static void RepollTournamentRegion()
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            try { FetchMyActiveTournamentMatches(sid); } catch { }
            try { FetchTournamentCurrent(sid); } catch { }
        }

        // Recent completed tournaments (site-wide history), used by the Tournaments
        // tab's "Recent Tournaments" section. Returns a JSON array which we
        // slice row-by-row.
        public static PlayerTournamentEntry[] CachedSiteTournamentHistory;
        public static string[] CachedSiteTournamentHistoryNames;  // aligned with ^, each entry's winner_display_name
        public static void FetchSiteTournamentHistory()
        {
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/tournaments/history?limit=12",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try
                    {
                        // /tournaments/history returns a bare array [ {...}, ... ].
                        // Reuse ExtractObjectArray by wrapping it under a synthetic key.
                        string wrapped = "{\"_hist\":" + response + "}";
                        CachedSiteTournamentHistory = ExtractObjectArray(wrapped, "_hist", raw => new PlayerTournamentEntry
                        {
                            tournament_id = ExtractString(raw, "tournament_id"),
                            ended_at = ExtractString(raw, "ended_at"),
                            placed_rank = 0,
                            kind = ExtractString(raw, "kind"),
                            signup_count = ExtractInt(raw, "signup_count", 0),
                            winner_display_name = ExtractString(raw, "winner_display_name"),
                            // Sid, Aug 13 item 7/15: Recent Tournaments needs
                            // more than the winner. All four have been in this
                            // endpoint's response since it was written — the
                            // client simply never read them.
                            runner_up_display_name = ExtractString(raw, "runner_up_display_name"),
                            third_place_display_name = ExtractString(raw, "third_place_display_name"),
                            format = ExtractString(raw, "format"),
                            prize_tier = ExtractString(raw, "prize_tier"),
                        });
                        NativeUI.MarkDirty();
                    }
                    catch (Exception e) { Plugin.Log.LogWarning($"[TOURNAMENT-SITEHIST] parse: {e.Message}"); }
                }
            ));
        }

