        // ── Bracket hover detail (Aug 17 bracket-clarity batch) ─────────────

        [Serializable]
        public class BracketGameDetail
        {
            public int n;
            public int p1_rounds, p2_rounds;
            public int p1_points, p2_points;
            public int dur;                       // seconds; 0 = unknown
            public int p1_fps, p2_fps;            // -1 = not recorded
            public int p1_ping, p2_ping;          // -1 = not recorded
            public int p1_hit_pct, p2_hit_pct;    // -1 = not recorded
            public int p1_blk_pct, p2_blk_pct;    // -1 = not recorded
            public string p1_cards, p2_cards;     // pipe-joined pick-order card names
        }

        [Serializable]
        public class BracketMatchDetail
        {
            public string match_id;
            public BracketGameDetail[] games;
        }

        /// <summary>Keyed by bracket match_id; belongs to CachedBracketDetailTid.
        /// Hover tooltips read this synchronously, so the fetch runs at bracket
        /// RENDER time (never at hover time) and re-arms when the tournament or
        /// its terminal-match count changes.</summary>
        public static Dictionary<string, BracketMatchDetail> CachedBracketDetail
            = new Dictionary<string, BracketMatchDetail>();
        public static string CachedBracketDetailTid;
        public static int CachedBracketDetailStamp = -1;  // terminal+wins stamp at fetch
        private static float _bracketDetailAt;
        private static float _bracketDetailFreshUntil;

        public static void FetchBracketDetail(string tournamentId, int terminalCount)
        {
            if (string.IsNullOrEmpty(tournamentId)) return;
            // The stamp observes completions but NOT admin invalidations
            // (round-2 f7: a reversal preserves the bracket match's terminal
            // status and win counters while /bracket-detail drops the games).
            // The 3-minute TTL is the observability backstop: revoked detail
            // heals on the next render past it instead of living forever.
            bool fresh = tournamentId == CachedBracketDetailTid
                         && terminalCount == CachedBracketDetailStamp
                         && Time.unscaledTime < _bracketDetailFreshUntil;
            if (fresh) return;
            if (Time.unscaledTime < _bracketDetailAt) return;   // in-flight / throttle
            _bracketDetailAt = Time.unscaledTime + 10f;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/tournaments/{UnityWebRequest.EscapeURL(tournamentId)}/bracket-detail",
                (success, response) =>
                {
                    if (!success || string.IsNullOrEmpty(response)) return;
                    try
                    {
                        var dict = new Dictionary<string, BracketMatchDetail>();
                        foreach (var m in ExtractObjectArray(response, "matches",
                            raw => new BracketMatchDetail
                            {
                                match_id = ExtractString(raw, "match_id"),
                                games = ExtractObjectArray(raw, "games", g => new BracketGameDetail
                                {
                                    n = ExtractInt(g, "n", 0),
                                    p1_rounds = ExtractInt(g, "p1_rounds", 0),
                                    p2_rounds = ExtractInt(g, "p2_rounds", 0),
                                    p1_points = ExtractInt(g, "p1_points", 0),
                                    p2_points = ExtractInt(g, "p2_points", 0),
                                    dur = ExtractInt(g, "dur", 0),
                                    p1_fps = ExtractInt(g, "p1_fps", -1),
                                    p2_fps = ExtractInt(g, "p2_fps", -1),
                                    p1_ping = ExtractInt(g, "p1_ping", -1),
                                    p2_ping = ExtractInt(g, "p2_ping", -1),
                                    p1_hit_pct = ExtractInt(g, "p1_hit_pct", -1),
                                    p2_hit_pct = ExtractInt(g, "p2_hit_pct", -1),
                                    p1_blk_pct = ExtractInt(g, "p1_blk_pct", -1),
                                    p2_blk_pct = ExtractInt(g, "p2_blk_pct", -1),
                                    p1_cards = ExtractString(g, "p1_cards"),
                                    p2_cards = ExtractString(g, "p2_cards"),
                                }),
                            }))
                        {
                            if (!string.IsNullOrEmpty(m.match_id)) dict[m.match_id] = m;
                        }
                        CachedBracketDetail = dict;
                        CachedBracketDetailTid = tournamentId;
                        CachedBracketDetailStamp = terminalCount;
                        _bracketDetailFreshUntil = Time.unscaledTime + 180f;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception e) { Plugin.Log.LogWarning($"[TOURN-BRACKETDETAIL] parse: {e.Message}"); }
                }
            ));
        }

        // ── Spectator mode (Aug 6 item 13, Phases 2/3/6) ─────────────────
        // All spectate traffic is strict-session POST (bodies, never query
        // strings — room credentials must not reach access logs, design
        // §6.3). The lease token is held ONLY here and in SpectatorSession;
        // it is never published to Photon or logged.

        /// <summary>Queue actions are disabled while spectating (design §3.1:
        /// never silently cancel the seat — the user leaves it explicitly).
        /// Also blocked while a spectate grant is in flight (Codex r1 find 6:
        /// a queue join landing between grant and Photon join would race the
        /// spectator joiner for the connection).</summary>
        private static bool SpectatorBlocksQueue()
        {
            // §2c identity fence: the broadcast service account never enters
            // any queue/lobby enrollment. This helper is the single entry
            // point every join/create funnel already passes through, so one
            // check here covers all of them. Identity-keyed, NOT config-keyed.
            if (BroadcastMode.FenceBlocksFighterPath("queue-join")) return true;
            if (!SpectatorSession.IsLocalSpectator && !spectateGrantInFlight) return false;
            try { CompetitiveUI.ShowNotification(I18n.Tr("Stop spectating first (Esc)."), Color.yellow, 4f); } catch { }
            return true;
        }

        // SpectatorBlocksBet used to live here — removed per Sid's design
        // ruling (Aug 9): spectators bet under the same bet-close windows as
        // everyone else and watch from beginning to DC. The matching server
        // rule (_reject_active_spectator_bet) was removed the same day.

        public class SpectateGameInfo
        {
            public string game_id = "";
            public string mode = "";
            public string source_ref = "";
            public string roster = "";   // sorted comma-joined fighter steam ids
            public string names = "";
            public string roster_titles = "";    // pipe-joined, roster-aligned
            // Per-title colours for roster_titles, same pipe-joined alignment.
            // OPTIONAL on the wire: a server that predates the field leaves
            // this empty, and SetWatchedMeta then drops the whole array so the
            // HUD renders its grey fallback rather than a misaligned colour.
            public string roster_title_colors = "";
            public string roster_ratings = "";   // comma-joined ints, roster-aligned
            public int spectator_count;
            public int spectator_cap;
            public bool spectatable;
            public string disabled_reason = "";
        }

        public static List<SpectateGameInfo> CachedSpectateGames = new List<SpectateGameInfo>();
        private static float lastSpectateGamesFetch = -999f;
        private static string spectateLeaseId = "";

        /// <summary>Fighter-side attestation (design §6.3): every fighter
        /// independently reports the live room so the server can list the
        /// game once ALL fighters agree. Fire-and-forget; called from
        /// GameStateWatcher's attest ticker while a competitive match is
        /// live. The roster is the sorted comma-joined fighter steam ids —
        /// all attesters must submit byte-identical tuples.</summary>
        public static void SpectateAttest(string mode, string sourceRef, string roomName,
                                          string region, int actorNumber, int fighterTarget,
                                          int roomCapacity, string phase, string rosterCsv)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || Plugin.Instance == null) return;
            if (string.IsNullOrEmpty(SteamAuth.SessionToken)) return;   // strict-session endpoint
            string json = "{"
                + $"\"steam_id\":\"{Escape(sid)}\","
                + $"\"mode\":\"{Escape(mode)}\","
                + $"\"source_ref\":\"{Escape(sourceRef ?? "")}\","
                + $"\"room_name\":\"{Escape(roomName)}\","
                + $"\"region\":\"{Escape(region ?? "")}\","
                + $"\"actor_number\":{actorNumber},"
                + $"\"fighter_target\":{fighterTarget},"
                + $"\"room_capacity\":{roomCapacity},"
                + $"\"spectator_protocol\":{SpectatorSession.PROTOCOL},"
                + $"\"phase\":\"{Escape(phase)}\","
                + $"\"roster\":\"{Escape(rosterCsv ?? "")}\""
                + "}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/spectate/participant-attest", json,
                (ok, resp) =>
                {
                    if (!ok && !resp.Contains("HTTP 4"))
                        Plugin.Log.LogInfo($"[SPECTATE] attest failed (transport): {resp}");
                }));
        }

        /// <summary>Tell the server this fighter has left the room, so the
        /// spectate row can be closed instead of aging out.
        ///
        /// WHY (bug 199 adjacent finding): nothing ever wrote
        /// spectate_games.ended_at — fighters just stopped attesting, and the
        /// row stayed listed until last_attest_at aged past the 150s freshness
        /// window. For up to two and a half minutes the games list advertised a
        /// room Photon had already destroyed, which is what produced the
        /// "Photon join refused (32758): Game does not exist" rejoin failures.
        ///
        /// Fire-and-forget and deliberately unconditional on room type: the
        /// server 200s with closed:false for a room that was never spectatable,
        /// so the client needs no knowledge of whether this room had a row.
        /// The server only ever retracts THIS caller's attestation, and closes
        /// the row solely when no other fighter is still fresh.</summary>
        public static void SpectateClose(string roomName)
        {
            if (string.IsNullOrEmpty(roomName) || Plugin.Instance == null) return;
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown") return;
            if (string.IsNullOrEmpty(SteamAuth.SessionToken)) return;   // strict-session endpoint
            string json = "{"
                + $"\"steam_id\":\"{Escape(sid)}\","
                + $"\"room_name\":\"{Escape(roomName)}\""
                + "}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/spectate/close", json,
                (ok, resp) =>
                {
                    if (!ok && !resp.Contains("HTTP 4"))
                        Plugin.Log.LogInfo($"[SPECTATE] close failed (transport): {resp}");
                }));
        }

        /// <summary>Refresh the public spectatable-games list (10s throttle).
        /// Parsed with the string-aware slicers — display names are
        /// adversarial input (#156).</summary>
        public static void MaybeFetchSpectateGames()
        {
            if (Plugin.Instance == null) return;
            if (Time.realtimeSinceStartup - lastSpectateGamesFetch < 10f) return;
            lastSpectateGamesFetch = Time.realtimeSinceStartup;
            Plugin.Instance.StartCoroutine(GetRequest(
                $"{baseUrl}/api/v1/spectate/games",
                (ok, resp) =>
                {
                    if (!ok) return;
                    try
                    {
                        var list = new List<SpectateGameInfo>();
                        int arr = resp.IndexOf("\"games\"", StringComparison.Ordinal);
                        if (arr >= 0)
                        {
                            int open = resp.IndexOf('[', arr);
                            if (open >= 0)
                            {
                                int close = FindMatchingBracketStringAware(resp, open);
                                if (close > open)
                                {
                                    string body = resp.Substring(open + 1, close - open - 1);
                                    foreach (var raw in SliceTopLevelObjects(body))
                                    {
                                        var g = new SpectateGameInfo
                                        {
                                            game_id = ExtractJsonString(raw, "game_id") ?? "",
                                            mode = ExtractJsonString(raw, "mode") ?? "",
                                            source_ref = ExtractJsonString(raw, "source_ref") ?? "",
                                            roster = ExtractJsonString(raw, "roster") ?? "",
                                            names = ExtractJsonString(raw, "names") ?? "",
                                            roster_titles = ExtractJsonString(raw, "roster_titles") ?? "",
                                            roster_title_colors = ExtractJsonString(raw, "roster_title_colors") ?? "",
                                            roster_ratings = ExtractJsonString(raw, "roster_ratings") ?? "",
                                            spectator_count = ExtractJsonInt(raw, "spectator_count"),
                                            spectator_cap = ExtractJsonInt(raw, "spectator_cap"),
                                            spectatable = ExtractJsonBool(raw, "spectatable"),
                                            disabled_reason = ExtractJsonString(raw, "disabled_reason") ?? "",
                                        };
                                        if (!string.IsNullOrEmpty(g.game_id)) list.Add(g);
                                    }
                                }
                            }
                        }
                        CachedSpectateGames = list;
                        NativeUI.MarkDirty();
                    }
                    catch (Exception e) { Plugin.Log.LogWarning($"[SPECTATE] games parse: {e.Message}"); }
                }));
        }

        // A grant round-trip is a commitment window (Codex r1 find 6):
        // queue joins are blocked while one is in flight, and a second WATCH
        // click is ignored rather than double-granted.
        private static bool spectateGrantInFlight;
        public static bool SpectateGrantInFlight => spectateGrantInFlight;

        // Stamped by every queue/lobby JOIN at POST time (Codex r3: the
        // status flags flip only on the RESPONSE, so a WATCH click inside
        // the round-trip saw no commitment). 25s: PostRequest's timeout is
        // 20s, so the window must OUTLIVE the slowest possible response
        // (Codex r4 — a 15s window expired before an 18s join landed).
        private static float queueRequestInFlightUntil = -999f;
        internal static void NoteQueueRequestInFlight()
        {
            queueRequestInFlightUntil = Time.realtimeSinceStartup + 25f;
        }

        /// <summary>True when the client holds ANY fighter commitment a
        /// spectate session would race: an in-flight queue lock, a pending
        /// room join, an active lobby, or an online room.</summary>
        private static bool SpectateCommitmentBlocked(out string why)
        {
            why = "";
            try
            {
                if (SpectatorSession.IsLocalSpectator) { why = "already spectating"; return true; }
                if (Time.realtimeSinceStartup < queueRequestInFlightUntil)
                { why = "a queue action is in flight"; return true; }
                if (PhotonNetwork.InRoom && !PhotonNetwork.OfflineMode) { why = "in a game"; return true; }
                // Offline sandbox: a LIVE offline battle would leave its scene
                // and state behind the spectator join (Codex r2 find 9). The
                // lingering post-sandbox InRoom at the MENU (#122) stays
                // allowed — battleOngoing is false there.
                try
                {
                    if (PhotonNetwork.OfflineMode && GameManager.instance != null
                        && GameManager.instance.battleOngoing)
                    { why = "leave the sandbox first"; return true; }
                }
                catch { }
                if (!string.IsNullOrEmpty(Plugin.PendingRankedRoom)
                    || Plugin.Pending2v2Slot >= 0 || Plugin.PendingOvtSlot >= 0
                    || Plugin.PendingFfaSlot >= 0) { why = "match pending"; return true; }
                if (IsQueuePolling) { why = "in the 1v1 queue"; return true; }
                if (CurrentTeamQueueState != TeamQueueState.Idle) { why = "in the 2v2 queue"; return true; }
                if (IsOvtQueuePolling || !string.IsNullOrEmpty(OvtQueueStatus)) { why = "in the 1v2 queue"; return true; }
                if (IsFfaQueuePolling || !string.IsNullOrEmpty(ActiveFfaLobbyId)) { why = "in an FFA lobby"; return true; }
            }
            catch { }
            return false;
        }

        // Grant OWNER TOKENS (Codex mod-r1 F6): every dispatch gets a fresh
        // seq; the latch records its current owner. Clearing the latch is a
        // CAS against that owner, so neither a stale callback nor a director
        // force-release can free (or re-free) a latch a SUCCESSOR grant now
        // holds. 0 = latch unowned.
        private static int spectateGrantSeq;
        private static int spectateGrantOwner;

        // Broadcast-grant TRANSPORT guard (Codex mod-r2 find 4, restructured
        // per mod-r3 find 2): the latch above is a client-memory admission
        // gate; releasing it (director budget/cancel) does NOT resolve the
        // HTTP request, which stays alive for up to its 20s UnityWebRequest
        // timeout. A NEWER grant reaching the server's serialized
        // revoke-and-replace section before a DELAYED older one would have
        // its fresh lease revoked by the straggler — so while any
        // broadcast-issued grant request is unresolved, NO new grant may be
        // admitted (director acquisition OR a dispatch on this seat).
        //
        // REQUEST-OWNED TOKENS, no clock (r3: an elapsed-time deadman is the
        // #367 elapsed-time-latch ownership hole — it reopened admission
        // without a transport-terminal signal, and a shared counter let one
        // request decrement another's slot). Each broadcast dispatch owns
        // its grant-seq token; ONLY its own callback (or its synchronous
        // dispatch failure) releases it. Admission NEVER reopens by clock:
        // a token outliving TRANSPORT_FAULT_SECONDS makes the DIRECTOR
        // escalate to FAULTED (BroadcastGrantTransportStuckBeyond below) —
        // process replacement is what clears every in-flight request.
        // Non-broadcast installs never add a token, so the public path
        // elsewhere is untouched.
        private static readonly Dictionary<int, float> broadcastGrantTransportTokens =
            new Dictionary<int, float>();
        public static bool BroadcastGrantTransportUnsettled => broadcastGrantTransportTokens.Count > 0;

        /// <summary>True when any broadcast grant request has been on the
        /// wire longer than <paramref name="seconds"/> without its terminal
        /// callback. Read by the director's fault escalation only.</summary>
        internal static bool BroadcastGrantTransportStuckBeyond(float seconds)
        {
            if (broadcastGrantTransportTokens.Count == 0) return false;
            float now = Time.realtimeSinceStartup;
            foreach (var kv in broadcastGrantTransportTokens)
                if (now - kv.Value > seconds) return true;
            return false;
        }

        /// <summary>Ask the server for a seat. On success, begins the local
        /// spectator session and starts the joiner. Refusals surface as a
        /// notification with the server's stable reason.</summary>
        public static void RequestSpectateGrant(string gameId)
        {
            RequestSpectateGrantCore(gameId, broadcastTicket: false);
        }

        /// <summary>Director dispatch (§3a): same flow, but returns the grant
        /// OWNER TOKEN (0 = not dispatched) so CancelAcquisition can
        /// CAS-release exactly its own latch (r1 F6), and the stale-arc
        /// discard below applies ONLY to these dispatches — a public grant
        /// must never be discarded by a director generation bump (a human's
        /// WATCH landing during a broadcast cancel is legitimate).</summary>
        internal static int RequestSpectateGrantForBroadcast(string gameId)
        {
            return RequestSpectateGrantCore(gameId, broadcastTicket: true);
        }

        private static int RequestSpectateGrantCore(string gameId, bool broadcastTicket)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || Plugin.Instance == null) return 0;
            if (spectateGrantInFlight) return 0;
            // r2 find 4: NO grant is admitted while a broadcast-issued grant
            // request is still unresolved on the wire — even a public WATCH
            // on this seat. A newer grant reaching the server before the
            // delayed straggler would be revoke-and-replaced BY the
            // straggler. Only ever armed on the broadcast seat.
            if (BroadcastGrantTransportUnsettled)
            {
                // Deliberately NOT I18n.Tr: this toast is reachable only on
                // the broadcast seat (the guard arms nowhere else), and
                // bot-seat-only strings must not enter the translation
                // catalogue (#295 — same rule as BroadcastHud).
                if (!broadcastTicket)
                    CompetitiveUI.ShowNotification("Spectate is settling - try again in a moment.", Color.yellow, 4f);
                return 0;
            }
            string blocked;
            if (SpectateCommitmentBlocked(out blocked))
            {
                CompetitiveUI.ShowNotification(I18n.TrF("Cannot spectate: {0}", blocked), Color.yellow, 4f);
                return 0;
            }
            if (string.IsNullOrEmpty(SteamAuth.SessionToken))
            {
                CompetitiveUI.ShowNotification(I18n.Tr("Sign-in still pending - try again in a moment."), Color.yellow, 4f);
                return 0;
            }
            spectateGrantInFlight = true;
            int myGrant = ++spectateGrantSeq;
            spectateGrantOwner = myGrant;
            // r3 find 2: request-owned transport token — this dispatch owns
            // exactly its own slot; only its own callback (or the synchronous
            // dispatch failure below) can release it.
            if (broadcastTicket)
                broadcastGrantTransportTokens[myGrant] = Time.realtimeSinceStartup;
            // §3a ticket hook (#367): capture the shared-flow generation at
            // dispatch. A broadcast CancelAcquisition bumps it, making this
            // callback stale — it then releases without beginning a session.
            // Consulted ONLY for broadcast-ticket dispatches (see above).
            int flowGenAtSend = BroadcastMode.SharedFlowGeneration;
            string json = $"{{\"steam_id\":\"{Escape(sid)}\",\"game_id\":\"{Escape(gameId)}\",\"client_protocol\":{SpectatorSession.PROTOCOL}}}";
            var grantReq = PostRequest(
                $"{baseUrl}/api/v1/spectate/grant", json,
                (ok, resp) =>
                {
                    // r2 find 4 / r3 find 2: the transport settled (success,
                    // HTTP error, or the 20s timeout — PostRequest always
                    // invokes its callback). Release ONLY this dispatch's own
                    // token, FIRST, before any early return below.
                    if (broadcastTicket) broadcastGrantTransportTokens.Remove(myGrant);
                    // F6 CAS: only the owner clears the latch — a director
                    // force-release may already have freed it for a successor,
                    // whose in-flight state must not be clobbered.
                    if (spectateGrantOwner == myGrant)
                    {
                        spectateGrantOwner = 0;
                        spectateGrantInFlight = false;
                    }
                    if (broadcastTicket && BroadcastMode.SharedFlowStale(flowGenAtSend))
                    {
                        // Stale ticket: the acquisition was cancelled while
                        // this round-trip was in flight. Release the lease the
                        // server may have just granted BY ID — never through
                        // the global current-lease state, which a successor
                        // public session may own by now (r1 F6).
                        Plugin.Log.LogInfo("[SPECTATE] grant response for a cancelled acquisition — discarding");
                        if (ok)
                        {
                            string staleLease = ExtractJsonString(resp, "lease_id");
                            if (!string.IsNullOrEmpty(staleLease)) SpectateReleaseLeaseById(staleLease);
                        }
                        return;
                    }
                    if (!ok)
                    {
                        string why = I18n.Tr("Could not spectate this game.");
                        if (resp.Contains("spectator_full")) why = I18n.Tr("All spectator seats are taken.");
                        else if (resp.Contains("spectating_disabled")) why = I18n.Tr("A player in this game has spectating disabled.");
                        else if (resp.Contains("game_not_live")) why = I18n.Tr("That game is no longer live.");
                        else if (resp.Contains("already_in_game")) why = I18n.Tr("Leave your current game first.");
                        Plugin.Log.LogInfo($"[SPECTATE] grant refused: {resp}");
                        CompetitiveUI.ShowNotification(why, Color.yellow, 5f);
                        return;
                    }
                    string room = ExtractJsonString(resp, "room_name");
                    string region = ExtractJsonString(resp, "region");
                    string leaseId = ExtractJsonString(resp, "lease_id");
                    string leaseToken = ExtractJsonString(resp, "lease_token");
                    if (string.IsNullOrEmpty(room) || string.IsNullOrEmpty(leaseId))
                    {
                        Plugin.Log.LogWarning("[SPECTATE] grant response missing fields");
                        return;
                    }
                    // RE-CHECK commitments (r1 find 6): a queue lock can have
                    // landed during the grant round-trip; the fighter path
                    // always wins, and the unused lease is released.
                    string blockedNow;
                    if (SpectateCommitmentBlocked(out blockedNow))
                    {
                        Plugin.Log.LogInfo($"[SPECTATE] grant discarded — {blockedNow}");
                        spectateLeaseId = leaseId;
                        SpectateLeaveNotify();
                        return;
                    }
                    spectateLeaseId = leaseId;
                    // Cache the fighters' display metadata for the HUD
                    // (playtest #2b): clean DB names + title + elo, keyed by
                    // the roster steam order.
                    try
                    {
                        foreach (var g in CachedSpectateGames)
                            if (g != null && g.game_id == gameId)
                            {
                                SpectatorSession.SetWatchedMeta(g.roster, g.names, g.roster_titles,
                                                                g.roster_ratings, g.roster_title_colors);
                                break;
                            }
                    }
                    catch { }
                    string refusal;
                    // r2 find 3: the session records its EXACT creator (this
                    // dispatch's owner token + whether it was broadcast-
                    // issued) — the director claims sessions by that identity
                    // alone, and the joiner consumes director-generation
                    // invalidation only for broadcast-owned sessions.
                    if (!SpectatorSession.BeginSession(room, region, leaseId, leaseToken ?? "", gameId, out refusal,
                                                       ownerGrantSeq: myGrant, broadcastOwned: broadcastTicket))
                    {
                        Plugin.Log.LogWarning($"[SPECTATE] session refused: {refusal}");
                        CompetitiveUI.ShowNotification(I18n.TrF("Cannot spectate: {0}", refusal), Color.yellow, 5f);
                        SpectateLeaveNotify();   // release the lease we won't use
                        return;
                    }
                    SpectatorJoiner.StartJoin();
                });
            try
            {
                Plugin.Instance.StartCoroutine(grantReq);
            }
            catch (Exception ex)
            {
                // r3 find 2: SYNCHRONOUS dispatch failure — nothing left the
                // client, so this dispatch releases exactly its own state:
                // its transport token and (by CAS) the latch it owns.
                if (broadcastTicket) broadcastGrantTransportTokens.Remove(myGrant);
                if (spectateGrantOwner == myGrant)
                {
                    spectateGrantOwner = 0;
                    spectateGrantInFlight = false;
                }
                Plugin.Log.LogWarning($"[SPECTATE] grant dispatch failed synchronously: {ex.Message}");
                return 0;
            }
            return myGrant;
        }

        /// <summary>Spectator lease heartbeat (15s cadence from
        /// SpectatorSync.HeartbeatLoop). A definitive server rejection —
        /// 4xx/410 — ends the session; transport failures do not (#249's
        /// direction: the lease outlives a lost beat, the server's own
        /// expiry is the backstop).</summary>
        public static void SpectateHeartbeat()
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || string.IsNullOrEmpty(spectateLeaseId) || Plugin.Instance == null) return;
            string leaseAtSend = spectateLeaseId;   // generation fence (r2 find 12)
            string json = $"{{\"steam_id\":\"{Escape(sid)}\",\"lease_id\":\"{Escape(leaseAtSend)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/spectate/heartbeat", json,
                (ok, resp) =>
                {
                    if (ok) return;
                    // A delayed rejection for an OLD lease must not end the
                    // CURRENT session (r2 find 12).
                    if (!string.Equals(spectateLeaseId, leaseAtSend, StringComparison.Ordinal)) return;
                    if (resp.StartsWith("HTTP 4", StringComparison.Ordinal))
                    {
                        Plugin.Log.LogInfo($"[SPECTATE] heartbeat rejected: {resp}");
                        SpectatorSync.OnHeartbeatRejected(resp);
                    }
                }));
        }

        /// <summary>Best-effort lease release on leave. Fire-and-forget —
        /// the server's heartbeat expiry frees the seat if this is lost
        /// (#276: absence of renewal frees; nothing depends on this call).</summary>
        public static void SpectateLeaveNotify()
        {
            string sid = MatchTracker.LocalSteamId;
            string lease = spectateLeaseId;
            spectateLeaseId = "";
            if (string.IsNullOrEmpty(sid) || string.IsNullOrEmpty(lease) || Plugin.Instance == null) return;
            string json = $"{{\"steam_id\":\"{Escape(sid)}\",\"lease_id\":\"{Escape(lease)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/spectate/leave", json, (ok, resp) => { }));
        }

        // ── SCR Broadcast §2a: /broadcast/target poll ────────────────────

        /// <summary>One target entry from GET /broadcast/target. Field names
        /// mirror the wire keys (authored server: main.py _broadcast_public).</summary>
        public class BroadcastTargetInfo
        {
            public string game_id = "";
            public string incarnation = "";
            public string mode = "";
            public string source_ref = "";
            public string phase = "";
            public bool is_tournament;
            public float score;
            public List<string> names = new List<string>();
            public List<double> ratings = new List<double>();
        }

        public class BroadcastTargetResponse
        {
            public BroadcastTargetInfo target;        // null when none selected
            public bool hasCurrent;
            public string currentGameId = "";
            public bool currentStillEligible;
            public string currentReason = "";
            public int rotationSetSize;
            public int rotationNextSwitchIn;
        }

        /// <summary>One row from GET /broadcast/report-status (W7, D1 f6/f7).
        /// Field names mirror the wire keys (spectate_games columns via A8's
        /// endpoint). ended_at == "" means the server sent JSON null — the
        /// game is still live; a NON-empty ended_at is the ONLY terminal
        /// proof (absence from the list proves nothing). roster is a
        /// steam-id CSV (server-generated, bracket-free); names carries
        /// player display names = hostile input (#156) — sanitize at
        /// render, never trust for identity (roster is the identity).</summary>
        public class BroadcastReportStatusEntry
        {
            public string game_id = "";
            public string mode = "";
            public string started_at = "";
            public string ended_at = "";
            public string roster = "";
            public List<string> names = new List<string>();
        }

        /// <summary>GET /api/v1/broadcast/target (director poll, §2a).
        /// Query params match the AUTHORED server endpoint exactly (verified
        /// against main.py broadcast_target — the design doc's `acq={...}`
        /// shorthand is three separate params on the real wire, #329):
        /// steam_id, current, activation_age, exclude, acq_ticket, acq_phase,
        /// acq_age. Pass currentGameId=null pre-activation (the server's
        /// acquisition-progress lease renews on acq polls only in its
        /// not-current branch). activationAge/acqAge &lt; 0 = omit.</summary>
        public static void FetchBroadcastTarget(string currentGameId, float activationAge,
            string acqTicket, string acqPhase, float acqAge, string excludeCsv,
            Action<bool, BroadcastTargetResponse> callback)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || Plugin.Instance == null)
            { callback?.Invoke(false, null); return; }
            var url = new StringBuilder(256);
            url.Append(baseUrl).Append("/api/v1/broadcast/target?steam_id=").Append(Escape(sid));
            if (!string.IsNullOrEmpty(currentGameId))
                url.Append("&current=").Append(UnityWebRequest.EscapeURL(currentGameId));
            if (activationAge >= 0f)
                url.Append("&activation_age=").Append(activationAge.ToString("F1", System.Globalization.CultureInfo.InvariantCulture));
            if (!string.IsNullOrEmpty(excludeCsv))
                url.Append("&exclude=").Append(UnityWebRequest.EscapeURL(excludeCsv));
            if (!string.IsNullOrEmpty(acqTicket))
            {
                url.Append("&acq_ticket=").Append(UnityWebRequest.EscapeURL(acqTicket));
                if (!string.IsNullOrEmpty(acqPhase))
                    url.Append("&acq_phase=").Append(UnityWebRequest.EscapeURL(acqPhase));
                if (acqAge >= 0f)
                    url.Append("&acq_age=").Append(acqAge.ToString("F1", System.Globalization.CultureInfo.InvariantCulture));
            }
            // Living stream post (Aug 17): fold the VM bot's stream-info
            // advert into the poll. No-op on every seat but the broadcast VM
            // (the file only exists there, and the endpoint 403s non-service
            // accounts anyway). The series score is deliberately NOT sent —
            // the server derives it from its own series row, oriented to the
            // candidate it composes (review F1: a client-computed aggregate
            // has neither game identity nor side-order binding).
            try
            {
                if (BroadcastMode.StreamInfoLive && !string.IsNullOrEmpty(BroadcastMode.StreamInfoSession))
                {
                    url.Append("&stream_live=1&stream_session=")
                       .Append(UnityWebRequest.EscapeURL(BroadcastMode.StreamInfoSession));
                    // Direct VOD links resolved by the VM bot (Aug 18): the
                    // server stores them on the stream post row so the
                    // "stream ended" edit can link the VODs. Optional —
                    // absent until the platform mints the archive.
                    string tvod = BroadcastMode.StreamInfoTwitchVod;
                    string yvod = BroadcastMode.StreamInfoYoutubeVod;
                    if (!string.IsNullOrEmpty(tvod))
                        url.Append("&stream_tvod=").Append(UnityWebRequest.EscapeURL(tvod));
                    if (!string.IsNullOrEmpty(yvod))
                        url.Append("&stream_yvod=").Append(UnityWebRequest.EscapeURL(yvod));
                }
            }
            catch { }
            Plugin.Instance.StartCoroutine(GetRequest(url.ToString(), (ok, resp) =>
            {
                if (!ok) { callback?.Invoke(false, null); return; }
                try { callback?.Invoke(true, ParseBroadcastTarget(resp)); }
                catch (Exception e)
                {
                    Plugin.Log.LogWarning($"[BROADCAST] target parse: {e.Message}");
                    callback?.Invoke(false, null);
                }
            }));
        }

        /// <summary>Defensive parse by KEY SEARCH (never position — the
        /// endpoint is new and its emission order is not a contract). Each
        /// top-level object is SLICED string-aware before extracting fields,
        /// because names[] carries adversarial display names (#156) and the
        /// candidates array repeats every key of target.</summary>
        private static BroadcastTargetResponse ParseBroadcastTarget(string resp)
        {
            var outR = new BroadcastTargetResponse();
            string targetSlice = SliceTopLevelValueObject(resp, "target");
            if (targetSlice != null)
                outR.target = ParseBroadcastTargetInfo(targetSlice);
            string currentSlice = SliceTopLevelValueObject(resp, "current");
            if (currentSlice != null)
            {
                outR.hasCurrent = true;
                outR.currentGameId = ExtractJsonString(currentSlice, "game_id") ?? "";
                outR.currentStillEligible = ExtractJsonBool(currentSlice, "still_eligible");
                outR.currentReason = ExtractJsonString(currentSlice, "reason") ?? "";
            }
            string rotSlice = SliceTopLevelValueObject(resp, "rotation");
            if (rotSlice != null)
            {
                outR.rotationSetSize = ExtractJsonInt(rotSlice, "set_size");
                outR.rotationNextSwitchIn = ExtractJsonInt(rotSlice, "next_switch_in");
            }
            return outR;
        }

        private static BroadcastTargetInfo ParseBroadcastTargetInfo(string slice)
        {
            var t = new BroadcastTargetInfo
            {
                game_id = ExtractJsonString(slice, "game_id") ?? "",
                incarnation = ExtractJsonString(slice, "incarnation") ?? "",
                mode = ExtractJsonString(slice, "mode") ?? "",
                source_ref = ExtractJsonString(slice, "source_ref") ?? "",
                phase = ExtractJsonString(slice, "phase") ?? "",
                is_tournament = ExtractJsonBool(slice, "is_tournament"),
                score = ExtractJsonFloat(slice, "score"),
                names = ExtractJsonStringArray(slice, "names"),
                ratings = ExtractJsonNumberArray(slice, "ratings"),
            };
            return string.IsNullOrEmpty(t.game_id) ? null : t;
        }

        /// <summary>Slice the value OBJECT of a top-level key ("key": {...}),
        /// or null when the value is JSON null / the key is absent. The
        /// `"key":` needle cannot be forged from inside a string value —
        /// producing the raw sequence would need an unescaped quote — and the
        /// FIRST occurrence is the top-level key on this endpoint.</summary>
        private static string SliceTopLevelValueObject(string json, string key)
        {
            int at = json.IndexOf("\"" + key + "\":", StringComparison.Ordinal);
            if (at < 0) return null;
            int i = at + key.Length + 3;
            while (i < json.Length && (json[i] == ' ' || json[i] == '\t')) i++;
            if (i >= json.Length || json[i] != '{') return null;   // null / non-object
            int close = FindMatchingBraceStringAware(json, i);
            if (close < 0) return null;
            return json.Substring(i, close - i + 1);
        }

        /// <summary>Flat numeric array ("ratings":[1523.4,1499]). Numbers
        /// only — no strings inside, so the naive scan is safe (#156's rule:
        /// server-generated bracket-free values).</summary>
        private static List<double> ExtractJsonNumberArray(string json, string key)
        {
            var list = new List<double>();
            try
            {
                int at = json.IndexOf("\"" + key + "\":", StringComparison.Ordinal);
                if (at < 0) return list;
                int open = json.IndexOf('[', at);
                if (open < 0) return list;
                int close = FindMatchingBracketStringAware(json, open);
                if (close < 0) return list;
                foreach (var tok in json.Substring(open + 1, close - open - 1).Split(','))
                {
                    string s = tok.Trim();
                    if (s.Length == 0) continue;
                    if (double.TryParse(s, System.Globalization.NumberStyles.Float,
                                        System.Globalization.CultureInfo.InvariantCulture, out double v))
                        list.Add(v);
                }
            }
            catch { }
            return list;
        }

        /// <summary>GET /api/v1/broadcast/report-status?game_ids=&lt;csv&gt;
        /// (W7, D1 f6/f7): terminal-state poll for the post-session report
        /// queue. Auth mirrors FetchBroadcastTarget exactly — steam_id query
        /// param bound to the session token GetRequest stamps; the server
        /// 403s non-service accounts. Callback gets NULL on transport/parse
        /// failure ("unreachable" — feeds the caller's 25-min partial
        /// fallback) and the parsed list on a server answer; entries the
        /// server omitted are simply absent, which proves nothing about
        /// their state.</summary>
        public static void FetchBroadcastReportStatus(string gameIdsCsv, Action<List<BroadcastReportStatusEntry>> cb)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || sid == "unknown" || Plugin.Instance == null
                || string.IsNullOrEmpty(gameIdsCsv))
            { cb?.Invoke(null); return; }
            var url = new StringBuilder(192);
            url.Append(baseUrl).Append("/api/v1/broadcast/report-status?steam_id=").Append(Escape(sid));
            url.Append("&game_ids=").Append(UnityWebRequest.EscapeURL(gameIdsCsv));
            Plugin.Instance.StartCoroutine(GetRequest(url.ToString(), (ok, resp) =>
            {
                if (!ok) { cb?.Invoke(null); return; }
                List<BroadcastReportStatusEntry> list;
                try { list = ParseBroadcastReportStatus(resp); }
                catch (Exception e)
                {
                    Plugin.Log.LogWarning($"[BROADCAST] report-status parse: {e.Message}");
                    list = null;
                }
                try { cb?.Invoke(list); } catch { }
            }));
        }

        /// <summary>Defensive parse of the report-status array. The body's
        /// FIRST non-whitespace char must be '[' (an error object never
        /// parses as rows); objects are sliced string-aware because names[]
        /// carries adversarial display names (#156).</summary>
        private static List<BroadcastReportStatusEntry> ParseBroadcastReportStatus(string resp)
        {
            var list = new List<BroadcastReportStatusEntry>();
            if (string.IsNullOrEmpty(resp)) return list;
            int open = -1;
            for (int i = 0; i < resp.Length; i++)
            {
                char c = resp[i];
                if (c == ' ' || c == '\t' || c == '\r' || c == '\n') continue;
                if (c == '[') open = i;
                break;
            }
            if (open < 0) return list;
            int close = FindMatchingBracketStringAware(resp, open);
            if (close <= open) return list;
            foreach (string obj in SliceTopLevelObjects(resp.Substring(open + 1, close - open - 1)))
            {
                var e = new BroadcastReportStatusEntry
                {
                    game_id = ExtractJsonString(obj, "game_id") ?? "",
                    mode = ExtractJsonString(obj, "mode") ?? "",
                    started_at = ExtractJsonString(obj, "started_at") ?? "",
                    // ExtractJsonString needs the `"key":"` needle, which a
                    // JSON null cannot match — a live game arrives as "".
                    ended_at = ExtractJsonString(obj, "ended_at") ?? "",
                    roster = ExtractJsonString(obj, "roster") ?? "",
                    names = ExtractJsonStringArray(obj, "names"),
                };
                if (!string.IsNullOrEmpty(e.game_id)) list.Add(e);
            }
            return list;
        }

        /// <summary>Force-release the grant latch for a cancelled broadcast
        /// acquisition (§3a via BroadcastMode.CancelAcquisition — the #367
        /// latch/ownership split). CAS against the ticket's own dispatch
        /// token (r1 F6): if the latch has since been freed and re-taken by a
        /// SUCCESSOR grant (a human's public WATCH), the owner differs and
        /// nothing is touched. The cancelled dispatch's own late callback is
        /// covered by the same CAS plus its stale-generation discard. NEVER
        /// called on public spectate paths (no ticket = no cancel).</summary>
        internal static void ReleaseSpectateGrantLatchForStaleTicket(int ownerSeq)
        {
            if (ownerSeq <= 0 || spectateGrantOwner != ownerSeq) return;
            spectateGrantOwner = 0;
            spectateGrantInFlight = false;
        }

        /// <summary>Release a SPECIFIC lease by id (r1 F6): used for a stale
        /// grant response whose lease was never adopted. Deliberately touches
        /// NO global lease state — a successor session's spectateLeaseId and
        /// heartbeats must be unaffected.</summary>
        internal static void SpectateReleaseLeaseById(string leaseId)
        {
            string sid = MatchTracker.LocalSteamId;
            if (string.IsNullOrEmpty(sid) || string.IsNullOrEmpty(leaseId) || Plugin.Instance == null) return;
            string json = $"{{\"steam_id\":\"{Escape(sid)}\",\"lease_id\":\"{Escape(leaseId)}\"}}";
            Plugin.Instance.StartCoroutine(PostRequest(
                $"{baseUrl}/api/v1/spectate/leave", json, (ok, resp) => { }));
        }

        /// <summary>Master-side spectator validation (design §6.6): confirm
        /// each claimed spectator actor holds a live lease for THIS room.
        /// Invalid actors are kicked; valid names are published as a room
        /// property for the roster display (names only — no credentials).
        /// Called on spectator entry and from the periodic attest ticker.</summary>
        public static void SpectateValidateActors()
        {
            try
            {
                if (!Photon.Pun.PhotonNetwork.InRoom || !Photon.Pun.PhotonNetwork.IsMasterClient) return;
                if (RoomActors.LocalIsSpectator) return;
                var specs = RoomActors.Spectators();
                if (specs.Length == 0) return;
                string sid = MatchTracker.LocalSteamId;
                if (string.IsNullOrEmpty(sid) || Plugin.Instance == null) return;
                if (string.IsNullOrEmpty(SteamAuth.SessionToken)) return;

                string roomAtSend = Photon.Pun.PhotonNetwork.CurrentRoom?.Name ?? "";
                var sb = new StringBuilder();
                sb.Append('{')
                  .Append($"\"steam_id\":\"{Escape(sid)}\",")
                  .Append($"\"room_name\":\"{Escape(roomAtSend)}\",")
                  .Append("\"spectators\":[");
                bool first = true;
                for (int i = 0; i < specs.Length; i++)
                {
                    // Wrong-protocol seats are never validated (Aug 10 r2
                    // blocker 2): the master closes them (entry hook + sweep);
                    // validating one would keep its lease bound and alive.
                    if (RoomActors.SpectatorProtocolOf(specs[i]) != SpectatorSession.PROTOCOL) continue;
                    if (!first) sb.Append(',');
                    first = false;
                    sb.Append('{')
                      .Append($"\"actor_number\":{specs[i].ActorNumber},")
                      .Append($"\"steam_id\":\"{Escape(RoomActors.SteamIdOf(specs[i]))}\"")
                      .Append('}');
                }
                sb.Append("]}");
                Plugin.Instance.StartCoroutine(PostRequest(
                    $"{baseUrl}/api/v1/spectate/validate", sb.ToString(),
                    (ok, resp) =>
                    {
                        if (!ok) return;   // no kick on transport failure — fail open, revalidated next tick
                        // Room fence (Codex r3): a delayed verdict from room A
                        // must not validate the same ActorNumber in room B.
                        try
                        {
                            if (!string.Equals(Photon.Pun.PhotonNetwork.CurrentRoom?.Name ?? "", roomAtSend, StringComparison.Ordinal))
                                return;
                        }
                        catch { return; }
                        try
                        {
                            // Response: {"results":[{"actor_number":N,"ok":true,"display_name":"..."}]}
                            var names = new List<string>();
                            int arr = resp.IndexOf("\"results\"", StringComparison.Ordinal);
                            if (arr < 0) return;
                            int open = resp.IndexOf('[', arr);
                            if (open < 0) return;
                            int close = FindMatchingBracketStringAware(resp, open);
                            if (close <= open) return;
                            foreach (var raw in SliceTopLevelObjects(resp.Substring(open + 1, close - open - 1)))
                            {
                                int actor = ExtractJsonInt(raw, "actor_number");
                                bool valid = ExtractJsonBool(raw, "ok");
                                // Feed the master's admission set: only
                                // validated actors are answered with match
                                // state (Codex r1 find 3).
                                try { SpectatorSync.MasterNoteValidated(actor, valid); } catch { }
                                if (!valid)
                                {
                                    try
                                    {
                                        var room = Photon.Pun.PhotonNetwork.CurrentRoom;
                                        var p = room != null ? room.GetPlayer(actor) : null;
                                        if (p != null && RoomActors.IsSpectator(p))
                                        {
                                            Plugin.Log.LogWarning($"[SPECTATE] close requested for invalid spectator actor {actor} (cooperative)");
                                            RoomActors.CooperativeClose(p);
                                        }
                                    }
                                    catch { }
                                    continue;
                                }
                                string nm = ExtractJsonString(raw, "display_name") ?? "";
                                if (!string.IsNullOrEmpty(nm)) names.Add(nm);
                            }
                            // Publish the validated roster (names only) so every
                            // fighter can render "Spectators (N)".
                            var props = new ExitGames.Client.Photon.Hashtable
                            {
                                { "cr_spec_roster", string.Join("|", names) }
                            };
                            Photon.Pun.PhotonNetwork.CurrentRoom?.SetCustomProperties(props);
                        }
                        catch (Exception e) { Plugin.Log.LogWarning($"[SPECTATE] validate parse: {e.Message}"); }
                    }));
            }
            catch (Exception ex) { Plugin.Log.LogWarning($"[SPECTATE] validate: {ex.Message}"); }
        }
    }
}
